--
-- Name: _adjust_posted_sales_invoice_financials("uuid", numeric, numeric, "date", numeric, numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_adjust_posted_sales_invoice_financials"("p_invoice_id" "uuid", "p_old_grand" numeric, "p_new_grand" numeric, "p_effective_from" "date" DEFAULT NULL::"date", "p_old_tax" numeric DEFAULT NULL::numeric, "p_new_tax" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_invoices%rowtype;
  v_ar_row erp.ar_documents%rowtype;
  v_delta numeric;
  v_old_net numeric;
  v_new_net numeric;
  v_old_tax numeric;
  v_new_tax numeric;
  v_delta_net numeric;
  v_delta_tax numeric;
  v_je_id uuid;
  v_ln int := 0;
  v_ar text;
  v_rev text;
  v_tax text;
  v_adj_no text;
begin
  v_delta := round(coalesce(p_new_grand, 0) - coalesce(p_old_grand, 0), 3);
  if abs(v_delta) < 0.01 then
    return jsonb_build_object('ok', true, 'adjusted', false, 'reason', 'no delta');
  end if;

  select * into v_doc from erp.sales_invoices where id = p_invoice_id;
  if not found or v_doc.posting_status <> 'posted' then
    return jsonb_build_object('ok', false, 'error', 'invoice not posted');
  end if;

  select * into v_ar_row
  from erp.ar_documents
  where source_doc_type = 'sales_invoice'
    and source_doc_id = p_invoice_id
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'AR document missing');
  end if;

  if v_ar_row.status <> 'open'
     or abs(coalesce(v_ar_row.open_amount, 0) - coalesce(v_ar_row.amount, 0)) >= 0.01 then
    return jsonb_build_object(
      'ok', false,
      'skipped', true,
      'reason', 'AR not fully open (partial payment or settled)'
    );
  end if;

  if exists (
    select 1 from erp.payment_allocations pa
    where pa.ar_document_id = v_ar_row.id
  ) then
    return jsonb_build_object(
      'ok', false,
      'skipped', true,
      'reason', 'Payment allocations exist on AR'
    );
  end if;

  v_old_tax := coalesce(p_old_tax, v_doc.tax_amount, 0);
  v_new_tax := coalesce(p_new_tax, v_doc.tax_amount, 0);
  v_old_net := coalesce(p_old_grand, 0) - v_old_tax;
  v_new_net := coalesce(p_new_grand, 0) - v_new_tax;
  v_delta_net := round(v_new_net - v_old_net, 3);
  v_delta_tax := round(v_new_tax - v_old_tax, 3);

  v_ar := erp._resolve_posting_account('sales_invoice', 'ar');
  v_rev := erp._resolve_posting_account('sales_invoice', 'sales_revenue');
  v_tax := erp._resolve_posting_account('sales_invoice', 'output_tax');
  v_adj_no := v_doc.invoice_no || '-WATTA-' || to_char(now(), 'YYMMDDHH24MI');

  insert into erp.journal_entries (
    voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
  ) values (
    v_adj_no,
    'SALES_INVOICE_ADJ',
    current_date,
    'sales_invoice',
    p_invoice_id,
    v_doc.invoice_no,
    'Watta matrix recalc from ' || coalesce(p_effective_from::text, 'matrix'),
    'posted',
    now(),
    auth.uid()
  ) returning id into v_je_id;

  if v_delta > 0 then
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_ar, v_doc.party_id, v_delta, 0, 'Watta recalc AR increase');
    if v_delta_net > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_rev, null, 0, v_delta_net, 'Watta recalc revenue');
    end if;
    if v_delta_tax > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_tax, null, 0, v_delta_tax, 'Watta recalc output tax');
    end if;
  else
    v_delta := abs(v_delta);
    v_delta_net := abs(v_delta_net);
    v_delta_tax := abs(v_delta_tax);
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_ar, v_doc.party_id, 0, v_delta, 'Watta recalc AR decrease');
    if v_delta_net > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_rev, null, v_delta_net, 0, 'Watta recalc revenue reversal');
    end if;
    if v_delta_tax > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_tax, null, v_delta_tax, 0, 'Watta recalc tax reversal');
    end if;
  end if;

  update erp.ar_documents
  set amount = round(amount + (p_new_grand - p_old_grand), 3),
      open_amount = round(open_amount + (p_new_grand - p_old_grand), 3)
  where id = v_ar_row.id;

  return jsonb_build_object('ok', true, 'adjusted', true, 'delta', (p_new_grand - p_old_grand), 'je_id', v_je_id);
end;
$$;


ALTER FUNCTION "erp"."_adjust_posted_sales_invoice_financials"("p_invoice_id" "uuid", "p_old_grand" numeric, "p_new_grand" numeric, "p_effective_from" "date", "p_old_tax" numeric, "p_new_tax" numeric) OWNER TO "postgres";

--
-- Name: _admin_assign_app_role("uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_admin_assign_app_role"("p_user_id" "uuid", "p_role_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_role_id uuid;
  v_role_code text;
begin
  v_role_code := upper(trim(coalesce(p_role_code, '')));
  if v_role_code not in ('ADMIN', 'ACCOUNTANT') then
    raise exception 'Invalid role code: %', v_role_code;
  end if;

  select id into v_role_id from erp.roles where code = v_role_code limit 1;
  if v_role_id is null then
    raise exception 'Role % not found', v_role_code;
  end if;

  delete from erp.user_role_assignments ura
  using erp.roles r
  where ura.user_id = p_user_id
    and ura.role_id = r.id
    and r.code in ('ADMIN', 'ACCOUNTANT');

  insert into erp.user_role_assignments (user_id, role_id)
  values (p_user_id, v_role_id);
end;
$$;


ALTER FUNCTION "erp"."_admin_assign_app_role"("p_user_id" "uuid", "p_role_code" "text") OWNER TO "postgres";

--
-- Name: _advance_account("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_advance_account"("p_side" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_code text;
begin
  if p_side = 'customer' then
    v_code := erp._resolve_posting_account('payment_receipt', 'customer_advance');
    return coalesce(v_code, '21104');
  elsif p_side = 'vendor' then
    v_code := erp._resolve_posting_account('payment_payment', 'vendor_advance');
    return coalesce(v_code, '11203');
  else
    raise exception 'invalid advance side: % (expected customer|vendor)', p_side using errcode = 'P0001';
  end if;
end;
$$;


ALTER FUNCTION "erp"."_advance_account"("p_side" "text") OWNER TO "postgres";

--
-- Name: _apply_ap_allocation("uuid", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_apply_ap_allocation"("p_doc_id" "uuid", "p_amount" numeric) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_remaining numeric := p_amount;
  v_row record;
begin
  for v_row in
    select id, open_amount from erp.ap_documents
    where party_id = (select party_id from erp.payments where id = p_doc_id)
      and status in ('open','partially_settled')
      and open_amount > 0
    order by doc_date
  loop
    exit when v_remaining <= 0;
    if v_row.open_amount >= v_remaining then
      update erp.ap_documents set
        open_amount = open_amount - v_remaining,
        status = case when open_amount - v_remaining <= 0.01 then 'settled' else 'partially_settled' end
      where id = v_row.id;
      insert into erp.payment_allocations (payment_id, allocation_type, ap_document_id, allocated_amount)
      values (p_doc_id, 'ap', v_row.id, v_remaining);
      v_remaining := 0;
    else
      update erp.ap_documents set open_amount = 0, status = 'settled' where id = v_row.id;
      insert into erp.payment_allocations (payment_id, allocation_type, ap_document_id, allocated_amount)
      values (p_doc_id, 'ap', v_row.id, v_row.open_amount);
      v_remaining := v_remaining - v_row.open_amount;
    end if;
  end loop;
  return p_amount - v_remaining;
end;
$$;


ALTER FUNCTION "erp"."_apply_ap_allocation"("p_doc_id" "uuid", "p_amount" numeric) OWNER TO "postgres";

