--
-- Name: _apply_goat_packing_issues("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_apply_goat_packing_issues"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_invoices%rowtype;
  v_line record;
  v_net numeric;
  v_thr_low numeric;
  v_thr_mid_lo numeric;
  v_thr_mid_hi numeric;
  v_pack5_code text;
  v_pack10_code text;
  v_pack5_id uuid;
  v_pack10_id uuid;
  v_wh_fg uuid;
  v_avg numeric;
begin
  select * into v_doc from erp.sales_invoices where id = p_invoice_id;
  if not found then return; end if;

  v_thr_low := erp._production_standard_num('goat_packing_threshold_low_kg', v_doc.invoice_date);
  v_thr_mid_lo := erp._production_standard_num('goat_packing_threshold_mid_lo_kg', v_doc.invoice_date);
  v_thr_mid_hi := erp._production_standard_num('goat_packing_threshold_mid_hi_kg', v_doc.invoice_date);
  v_pack5_code := coalesce(erp._production_standard_text('goat_packing_5kg_item_code', v_doc.invoice_date), 'PK-GOAT-5');
  v_pack10_code := coalesce(erp._production_standard_text('goat_packing_10kg_item_code', v_doc.invoice_date), 'PK-GOAT-10');

  select id into v_pack5_id from erp.items where code = v_pack5_code and is_active limit 1;
  select id into v_pack10_id from erp.items where code = v_pack10_code and is_active limit 1;
  select id into v_wh_fg from erp.warehouses where wh_type = 'packing_material' and is_active limit 1;
  if v_wh_fg is null then
    select id into v_wh_fg from erp.warehouses where wh_type = 'finished_goods' and is_active limit 1;
  end if;
  if v_wh_fg is null then return; end if;

  for v_line in
    select sil.*, i.name as item_name, i.inventory_group, i.item_type
    from erp.sales_invoice_lines sil
    join erp.items i on i.id = sil.item_id
    where sil.sales_invoice_id = p_invoice_id
  loop
    if lower(coalesce(v_line.item_name, '')) not like '%goat%'
       and coalesce(v_line.inventory_group, '') not in ('enameled', 'strip', 'copper_wire') then
      continue;
    end if;
    if lower(coalesce(v_line.item_name, '')) not like '%goat%'
       and coalesce(v_line.item_type, '') not ilike '%goat%' then
      continue;
    end if;

    v_net := coalesce(v_line.net_weight, v_line.qty, 0);
    if v_net <= 0 then continue; end if;

    if v_net < v_thr_low and v_pack5_id is not null then
      select coalesce(ib.avg_unit_cost, 0) into v_avg
      from erp.inventory_balances ib
      where ib.item_id = v_pack5_id and ib.warehouse_id = v_wh_fg;
      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id, qty_out, unit_cost, value_amount,
        source_doc_type, source_doc_id, source_line_id, party_id, reference_no
      ) values (
        v_doc.invoice_date, 'sales_out', v_pack5_id, v_wh_fg, 5, coalesce(v_avg, 0), 5 * coalesce(v_avg, 0),
        'sales_invoice', v_doc.id, v_line.id, v_doc.party_id, 'goat-packing-5kg'
      );
    elsif v_net > v_thr_mid_lo and v_net < v_thr_mid_hi and v_pack10_id is not null then
      select coalesce(ib.avg_unit_cost, 0) into v_avg
      from erp.inventory_balances ib
      where ib.item_id = v_pack10_id and ib.warehouse_id = v_wh_fg;
      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id, qty_out, unit_cost, value_amount,
        source_doc_type, source_doc_id, source_line_id, party_id, reference_no
      ) values (
        v_doc.invoice_date, 'sales_out', v_pack10_id, v_wh_fg, 10, coalesce(v_avg, 0), 10 * coalesce(v_avg, 0),
        'sales_invoice', v_doc.id, v_line.id, v_doc.party_id, 'goat-packing-10kg'
      );
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "erp"."_apply_goat_packing_issues"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _apply_premium_purchase_scrap_pool("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_apply_premium_purchase_scrap_pool"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_invoices%rowtype;
  v_lot_ids uuid[];
  v_dispatch_id uuid;
begin
  select * into v_doc from erp.purchase_invoices where id = p_invoice_id;
  if not found then return; end if;
  if coalesce(v_doc.purchase_mode, 'cash') <> 'premium' then return; end if;

  select array_agg(distinct sa.scrap_lot_id) into v_lot_ids
  from erp.scrap_allocations sa
  where sa.purchase_invoice_id = p_invoice_id;

  if coalesce(array_length(v_lot_ids, 1), 0) > 0 then
    perform erp.fn_refresh_scrap_lot_allocations(v_lot_ids);
  end if;

  for v_dispatch_id in
    select distinct spl.source_doc_id
    from erp.scrap_allocations sa
    join erp.scrap_payable_lots spl on spl.id = sa.scrap_lot_id
    where sa.purchase_invoice_id = p_invoice_id
      and spl.source_doc_type = 'factory_scrap_dispatch'
      and sa.is_mazdoori_pending = false
  loop
    perform erp._sync_factory_obligation_from_premium_allocations(v_dispatch_id, p_invoice_id);
  end loop;
end;
$$;


ALTER FUNCTION "erp"."_apply_premium_purchase_scrap_pool"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _apply_production_batch_costing("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_apply_production_batch_costing"("p_batch_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_issue_cost numeric;
  v_item_ids uuid[];
begin
  v_issue_cost := erp._apply_production_batch_costing_pooled_318(p_batch_id);
  perform erp._redistribute_batch_varnish_cost(p_batch_id);

  select coalesce(array_agg(distinct im.item_id) filter (where im.item_id is not null), '{}')
  into v_item_ids
  from erp.inventory_movements im
  where im.source_doc_type = 'production_batch'
    and im.source_doc_id = p_batch_id
    and im.movement_type = 'production_receipt';

  if cardinality(v_item_ids) > 0 then
    perform erp.rebuild_inventory_balances_for_items(v_item_ids);
  end if;
  return v_issue_cost;
end;
$$;


ALTER FUNCTION "erp"."_apply_production_batch_costing"("p_batch_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "_apply_production_batch_costing"("p_batch_id" "uuid"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_apply_production_batch_costing"("p_batch_id" "uuid") IS 'Book production costing with varnish restricted to enameled-wire receipts.';


--
-- Name: _apply_production_batch_costing_pooled_318("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_apply_production_batch_costing_pooled_318"("p_batch_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_line record;
  v_mov_id uuid;
  v_wac numeric;
  v_line_cost numeric;
  v_total_issue_cost numeric := 0;
  v_copper_cost numeric := 0;
  v_varnish_cost numeric := 0;
  v_packing_cost numeric := 0;
  v_comp text;
  v_total_receipt_kg numeric := 0;
  v_batch_date date;
  v_rate numeric := 0;
  v_absorbed numeric := 0;
  v_landed_total numeric := 0;
  v_alloc numeric;
  v_unit numeric;
  v_last_receipt_mov_id uuid;
  v_alloc_sum numeric := 0;
  v_c_alloc numeric;
  v_v_alloc numeric;
  v_p_alloc numeric;
  v_o_alloc numeric;
  v_c_sum numeric := 0;
  v_v_sum numeric := 0;
  v_p_sum numeric := 0;
  v_o_sum numeric := 0;
  v_fg_item_ids uuid[] := '{}';
begin
  select batch_date into v_batch_date
  from erp.production_batches
  where id = p_batch_id;

  for v_line in
    select pbl.*
    from erp.production_batch_lines pbl
    where pbl.production_batch_id = p_batch_id
      and pbl.line_type = 'issue'
      and coalesce(pbl.net_weight, 0) > 0
    order by pbl.line_no
  loop
    select im.id into v_mov_id
    from erp.inventory_movements im
    where im.source_doc_type = 'production_batch'
      and im.source_doc_id = p_batch_id
      and im.source_line_id = v_line.id
      and im.movement_type = 'production_issue';

    v_wac := case
      when v_mov_id is not null then erp._inventory_wac_before_movement(v_mov_id)
      else 0
    end;
    if coalesce(v_wac, 0) = 0 then
      v_wac := erp._item_latest_purchase_unit_cost(v_line.item_id, v_line.warehouse_id);
    end if;

    v_line_cost := round(v_line.net_weight * coalesce(v_wac, 0), 3);
    v_total_issue_cost := v_total_issue_cost + v_line_cost;

    v_comp := erp._issue_cost_component(v_line.item_id, v_line.warehouse_id);
    if v_comp = 'varnish' then
      v_varnish_cost := v_varnish_cost + v_line_cost;
    elsif v_comp = 'packing' then
      v_packing_cost := v_packing_cost + v_line_cost;
    else
      v_copper_cost := v_copper_cost + v_line_cost;
    end if;

    update erp.inventory_movements im
    set unit_cost = coalesce(v_wac, 0),
        value_amount = case
          when coalesce(v_wac, 0) > 0 then round(v_line.net_weight * v_wac, 3)
          else coalesce(im.value_amount, 0)
        end,
        cost_copper = case when v_comp = 'copper' then v_line_cost else 0 end,
        cost_varnish = case when v_comp = 'varnish' then v_line_cost else 0 end,
        cost_packing = case when v_comp = 'packing' then v_line_cost else 0 end,
        cost_oh = 0
    where im.source_doc_type = 'production_batch'
      and im.source_doc_id = p_batch_id
      and im.source_line_id = v_line.id
      and im.movement_type = 'production_issue';
  end loop;

  select coalesce(sum(pbl.net_weight), 0)
  into v_total_receipt_kg
  from erp.production_batch_lines pbl
  where pbl.production_batch_id = p_batch_id
    and pbl.line_type = 'receipt'
    and coalesce(pbl.net_weight, 0) > 0;

  if v_total_receipt_kg <= 0 then
    return v_total_issue_cost;
  end if;

  v_rate := coalesce(erp.fn_get_live_conversion_rate(coalesce(v_batch_date, current_date)), 0);
  v_absorbed := round(v_rate * v_total_receipt_kg, 3);
  if v_absorbed < 0 then
    v_absorbed := 0;
  end if;

  v_landed_total := round(coalesce(v_total_issue_cost, 0) + v_absorbed, 3);

  if v_landed_total <= 0 then
    return v_total_issue_cost;
  end if;

  for v_line in
    select pbl.*
    from erp.production_batch_lines pbl
    where pbl.production_batch_id = p_batch_id
      and pbl.line_type = 'receipt'
      and coalesce(pbl.net_weight, 0) > 0
    order by pbl.line_no
  loop
    v_alloc := round(v_landed_total * v_line.net_weight / v_total_receipt_kg, 3);
    v_c_alloc := round(v_copper_cost * v_line.net_weight / v_total_receipt_kg, 3);
    v_v_alloc := round(v_varnish_cost * v_line.net_weight / v_total_receipt_kg, 3);
    v_p_alloc := round(v_packing_cost * v_line.net_weight / v_total_receipt_kg, 3);
    v_o_alloc := round(v_absorbed * v_line.net_weight / v_total_receipt_kg, 3);

    v_alloc_sum := v_alloc_sum + v_alloc;
    v_c_sum := v_c_sum + v_c_alloc;
    v_v_sum := v_v_sum + v_v_alloc;
    v_p_sum := v_p_sum + v_p_alloc;
    v_o_sum := v_o_sum + v_o_alloc;
    v_unit := round(v_alloc / v_line.net_weight, 6);

    if v_line.item_id is not null then
      v_fg_item_ids := array_append(v_fg_item_ids, v_line.item_id);
    end if;

    update erp.inventory_movements im
    set unit_cost = v_unit,
        value_amount = v_alloc,
        cost_copper = v_c_alloc,
        cost_varnish = v_v_alloc,
        cost_packing = v_p_alloc,
        cost_oh = v_o_alloc
    where im.source_doc_type = 'production_batch'
      and im.source_doc_id = p_batch_id
      and im.source_line_id = v_line.id
      and im.movement_type = 'production_receipt'
    returning im.id into v_last_receipt_mov_id;
  end loop;

  if v_last_receipt_mov_id is not null and v_alloc_sum <> v_landed_total then
    update erp.inventory_movements im
    set value_amount = im.value_amount + (v_landed_total - v_alloc_sum),
        cost_copper = im.cost_copper + (v_copper_cost - v_c_sum),
        cost_varnish = im.cost_varnish + (v_varnish_cost - v_v_sum),
        cost_packing = im.cost_packing + (v_packing_cost - v_p_sum),
        cost_oh = im.cost_oh + (v_absorbed - v_o_sum),
        unit_cost = round(
          (im.value_amount + (v_landed_total - v_alloc_sum)) / nullif(im.qty_in, 0),
          6
        )
    where im.id = v_last_receipt_mov_id;
  end if;

  if array_length(v_fg_item_ids, 1) is not null then
    perform erp.rebuild_inventory_balances_for_items(v_fg_item_ids);
  end if;

  return v_total_issue_cost;
end;
$$;


ALTER FUNCTION "erp"."_apply_production_batch_costing_pooled_318"("p_batch_id" "uuid") OWNER TO "postgres";

--
-- Name: _apply_purchase_order_fulfillment("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_apply_purchase_order_fulfillment"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_line record;
  v_qty numeric;
  v_remaining numeric;
  v_order_line erp.purchase_order_lines%rowtype;
  v_order_ids uuid[] := array[]::uuid[];
  v_order_id uuid;
begin
  for v_line in
    select *
    from erp.purchase_invoice_lines
    where purchase_invoice_id = p_invoice_id
      and purchase_order_line_id is not null
    order by line_no
  loop
    select * into v_order_line
    from erp.purchase_order_lines
    where id = v_line.purchase_order_line_id
    for update;

    if not found then
      raise exception 'Linked purchase order line % not found', v_line.purchase_order_line_id;
    end if;

    v_qty := coalesce(v_line.net_weight, v_line.qty, 0);
    if v_qty <= 0 then continue; end if;

    v_remaining := v_order_line.qty_ordered - v_order_line.qty_received;
    if v_qty > v_remaining + 0.001 then
      raise exception 'Invoice qty % exceeds remaining purchase order qty % for order line %',
        v_qty, v_remaining, v_order_line.id;
    end if;

    update erp.purchase_order_lines
    set qty_received = qty_received + v_qty
    where id = v_order_line.id;

    if not v_order_line.purchase_order_id = any(v_order_ids) then
      v_order_ids := array_append(v_order_ids, v_order_line.purchase_order_id);
    end if;
  end loop;

  if array_length(v_order_ids, 1) is not null then
    foreach v_order_id in array v_order_ids
    loop
      perform erp._recalc_purchase_order_status(v_order_id);
    end loop;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_apply_purchase_order_fulfillment"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _apply_sales_order_fulfillment("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_apply_sales_order_fulfillment"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_line record;
  v_qty numeric;
  v_remaining numeric;
  v_order_line erp.sales_order_lines%rowtype;
  v_order_ids uuid[] := array[]::uuid[];
  v_order_id uuid;
begin
  for v_line in
    select *
    from erp.sales_invoice_lines
    where sales_invoice_id = p_invoice_id
      and sales_order_line_id is not null
    order by line_no
  loop
    select * into v_order_line
    from erp.sales_order_lines
    where id = v_line.sales_order_line_id
    for update;

    if not found then
      raise exception 'Linked sales order line % not found', v_line.sales_order_line_id;
    end if;

    v_qty := coalesce(v_line.net_weight, v_line.qty, 0);
    if v_qty <= 0 then continue; end if;

    v_remaining := v_order_line.qty_ordered - v_order_line.qty_fulfilled;
    if v_qty > v_remaining + 0.001 then
      raise exception 'Invoice qty % exceeds remaining sales order qty % for order line %',
        v_qty, v_remaining, v_order_line.id;
    end if;

    update erp.sales_order_lines
    set qty_fulfilled = qty_fulfilled + v_qty
    where id = v_order_line.id;

    if not v_order_line.sales_order_id = any(v_order_ids) then
      v_order_ids := array_append(v_order_ids, v_order_line.sales_order_id);
    end if;
  end loop;

  if array_length(v_order_ids, 1) is not null then
    foreach v_order_id in array v_order_ids
    loop
      perform erp._recalc_sales_order_status(v_order_id);
    end loop;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_apply_sales_order_fulfillment"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _apply_scrap_obligation_kg("uuid", "uuid", numeric, "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_apply_scrap_obligation_kg"("p_trade_id" "uuid", "p_obligation_id" "uuid", "p_kg" numeric, "p_receipt_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_trades%rowtype;
  v_obl erp.scrap_receivable_obligations%rowtype;
  v_receipt erp.scrap_receipts%rowtype;
  v_open numeric;
begin
  if coalesce(p_kg, 0) <= 0 then
    raise exception 'allocated kg must be positive';
  end if;

  select * into v_doc from erp.scrap_trades where id = p_trade_id;
  if not found then raise exception 'scrap trade not found'; end if;

  select * into v_obl from erp.scrap_receivable_obligations where id = p_obligation_id for update;
  if not found then raise exception 'linked scrap obligation not found'; end if;
  if v_obl.party_id is distinct from v_doc.source_party_id then
    raise exception 'obligation party must match toll-drop source (customer)';
  end if;

  v_open := greatest(v_obl.expected_kg - v_obl.received_kg, 0);
  if p_kg > v_open + 0.001 then
    raise exception 'Allocated % kg exceeds open obligation % kg', p_kg, v_open;
  end if;

  update erp.scrap_receivable_obligations
  set received_kg = received_kg + p_kg
  where id = v_obl.id;

  perform erp._sync_scrap_obligation_status(v_obl.id);

  if p_receipt_id is not null then
    select * into v_receipt from erp.scrap_receipts where id = p_receipt_id for update;
    if not found then raise exception 'linked scrap receipt not found'; end if;
    if v_receipt.obligation_id is distinct from p_obligation_id then
      raise exception 'receipt obligation mismatch';
    end if;
    if v_receipt.status = 'draft' then
      update erp.scrap_receipts
      set status = 'posted', posted_at = now(), posted_by = auth.uid(), scrap_trade_id = coalesce(scrap_trade_id, p_trade_id)
      where id = v_receipt.id;
    end if;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_apply_scrap_obligation_kg"("p_trade_id" "uuid", "p_obligation_id" "uuid", "p_kg" numeric, "p_receipt_id" "uuid") OWNER TO "postgres";

--
-- Name: _apply_scrap_trade_rate_fix("uuid", numeric, numeric, numeric, "date", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_apply_scrap_trade_rate_fix"("p_source_doc_id" "uuid", "p_qty" numeric, "p_rate" numeric, "p_amount" numeric, "p_posting_date" "date", "p_remarks" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_st erp.scrap_trades%rowtype;
  v_je_id uuid;
  v_ln int := 0;
  v_inv text;
  v_ap text;
  v_ar text;
  v_cash text;
  v_is_cash boolean;
begin
  select * into v_st from erp.scrap_trades where id = p_source_doc_id for update;
  if not found then
    raise exception 'Scrap trade % not found', p_source_doc_id;
  end if;

  v_is_cash := coalesce(v_st.settlement_mode, 'triangle') = 'cash';

  update erp.scrap_trades
  set rate_status = 'fixed',
      unit_rate = p_rate,
      amount = p_amount,
      rate_fixed_at = now(),
      rate_fixed_by = auth.uid()
  where id = p_source_doc_id;

  update erp.inventory_movements
  set unit_cost = case when p_qty > 0 then round(p_amount / p_qty, 6) else 0 end,
      value_amount = p_amount
  where source_doc_type = 'scrap_trade' and source_doc_id = p_source_doc_id;

  v_inv := erp._resolve_posting_account('scrap_trade', 'inventory');
  v_ap := erp._resolve_posting_account('scrap_trade', 'ap');
  v_ar := erp._resolve_posting_account('scrap_trade', 'ar');
  v_cash := coalesce(nullif(v_st.bank_account_code, ''), erp._resolve_posting_account('scrap_trade', 'cash'));

  insert into erp.journal_entries (
    voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no,
    narration, status, posted_at, posted_by
  )
  values (
    v_st.trade_no, 'SCRAP_TRADE', p_posting_date, 'scrap_trade', v_st.id, v_st.trade_no,
    coalesce(nullif(trim(p_remarks), ''), v_st.remarks, 'Scrap trade posted'),
    'posted', now(), auth.uid()
  )
  returning id into v_je_id;

  v_ln := v_ln + 1;
  perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, p_amount, 0, 'Scrap acquired');
  v_ln := v_ln + 1;
  perform erp._insert_je_line(v_je_id, v_ln, v_ap, v_st.source_party_id, 0, p_amount, 'Payable to source');

  if v_is_cash then
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_cash, v_st.dest_party_id, p_amount, 0, 'Cash received from destination');
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, 0, p_amount, 'Scrap delivered');

    insert into erp.ap_documents (
      party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status
    )
    values (
      v_st.source_party_id, 'scrap_trade', v_st.id, v_st.trade_no,
      p_posting_date, p_posting_date, p_amount, p_amount, 'open'
    )
    on conflict (source_doc_type, source_doc_id, party_id) do update
      set amount = erp.ap_documents.amount + excluded.amount,
          open_amount = erp.ap_documents.open_amount + excluded.open_amount;
  else
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_ar, v_st.dest_party_id, p_amount, 0, 'Receivable from dest');
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, 0, p_amount, 'Scrap delivered');

    insert into erp.ap_documents (
      party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status
    )
    values (
      v_st.source_party_id, 'scrap_trade', v_st.id, v_st.trade_no,
      p_posting_date, p_posting_date, p_amount, p_amount, 'open'
    )
    on conflict (source_doc_type, source_doc_id, party_id) do update
      set amount = erp.ap_documents.amount + excluded.amount,
          open_amount = erp.ap_documents.open_amount + excluded.open_amount;

    insert into erp.ar_documents (
      party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status
    )
    values (
      v_st.dest_party_id, 'scrap_trade', v_st.id, v_st.trade_no,
      p_posting_date, p_posting_date, p_amount, p_amount, 'open'
    )
    on conflict (source_doc_type, source_doc_id, party_id) do update
      set amount = erp.ar_documents.amount + excluded.amount,
          open_amount = erp.ar_documents.open_amount + excluded.open_amount;
  end if;

  perform erp._refresh_doc_financial_status('scrap_trade', p_source_doc_id);
end;
$$;


ALTER FUNCTION "erp"."_apply_scrap_trade_rate_fix"("p_source_doc_id" "uuid", "p_qty" numeric, "p_rate" numeric, "p_amount" numeric, "p_posting_date" "date", "p_remarks" "text") OWNER TO "postgres";

--
-- Name: _assert_admin(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_admin"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if not erp.is_session_live() then
    raise exception 'session has been terminated (logged out or expired); sign in again' using errcode = '28000';
  end if;
  if not erp.has_role('ADMIN') then
    raise exception 'Admin privilege required for this operation' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "erp"."_assert_admin"() OWNER TO "postgres";

--
-- Name: _assert_ai_tool_permission("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_ai_tool_permission"("p_tool" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Unauthorized';
  end if;
  if erp.has_role('ADMIN') then
    return;
  end if;

  if p_tool in (
    'get_party_ledger', 'get_party_metal_ledger', 'get_party_balance',
    'get_ar_aging', 'get_ap_aging', 'get_pending_rate_register',
    'get_sales_invoice', 'get_purchase_invoice', 'get_stock_valuation',
    'get_party_context', 'get_document_context', 'search_documents',
    'search_parties', 'get_recent_sales_invoices', 'get_sales_summary',
    'get_posting_health', 'get_reconciliation_checks', 'get_sales_invoice_deploy_check',
    'get_purchase_invoice_deploy_check'
  ) then
    if erp.has_permission('ledger.read') or erp.has_permission('transactions.read') or erp.has_role('ACCOUNTANT') then
      return;
    end if;
    raise exception 'Permission denied for tool: %', p_tool;
  end if;

  if p_tool in ('get_trial_balance', 'get_profit_loss', 'get_balance_sheet', 'get_unit_economics') then
    if erp.has_permission('reports.financial.read') then
      return;
    end if;
    raise exception 'Permission denied for tool: % (financial reports)', p_tool;
  end if;

  if p_tool in ('get_daily_production', 'get_scrap_wastage') then
    if erp.has_permission('reports.operational.read') then
      return;
    end if;
    raise exception 'Permission denied for tool: % (operational reports)', p_tool;
  end if;

  if p_tool = 'get_transaction_history' then
    if erp.has_role('ADMIN') then
      return;
    end if;
    raise exception 'Permission denied for tool: %', p_tool;
  end if;

  raise exception 'Unknown AI tool: %', p_tool;
end;
$$;


ALTER FUNCTION "erp"."_assert_ai_tool_permission"("p_tool" "text") OWNER TO "postgres";

--
-- Name: _assert_cashbook_cash_bank("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_cashbook_cash_bank"("p_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_acc erp.coa_accounts%rowtype;
begin
  if p_code is null or trim(p_code) = '' then
    raise exception 'Cash/bank account code is required';
  end if;
  select * into v_acc from erp.coa_accounts where code = p_code;
  if not found then
    raise exception 'Account % not found in COA', p_code;
  end if;
  if coalesce(v_acc.is_active, true) = false then
    raise exception 'Account % is inactive', p_code;
  end if;
  if coalesce(v_acc.is_group, false) = true or coalesce(v_acc.is_posting, true) = false then
    raise exception 'Account % is not a postable leaf', p_code;
  end if;
  if p_code not in ('11101', '11102', '11111', '11112', '11113', '11114') then
    raise exception 'Account % is not a cash/bank account', p_code;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_assert_cashbook_cash_bank"("p_code" "text") OWNER TO "postgres";

--
-- Name: _assert_cashbook_counter("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_cashbook_counter"("p_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_acc erp.coa_accounts%rowtype;
begin
  if p_code is null or trim(p_code) = '' then
    raise exception 'Account code is required';
  end if;
  select * into v_acc from erp.coa_accounts where code = p_code;
  if not found then
    raise exception 'Account % not found in COA', p_code;
  end if;
  if coalesce(v_acc.is_active, true) = false then
    raise exception 'Account % is inactive', p_code;
  end if;
  if coalesce(v_acc.is_group, false) = true or coalesce(v_acc.is_posting, true) = false then
    raise exception 'Account % is not a postable leaf', p_code;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_assert_cashbook_counter"("p_code" "text") OWNER TO "postgres";

