--
-- Name: _assert_je_balanced("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_je_balanced"("p_je_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_dr numeric;
  v_cr numeric;
begin
  select coalesce(sum(debit_amount), 0), coalesce(sum(credit_amount), 0)
    into v_dr, v_cr
  from erp.journal_lines
  where journal_entry_id = p_je_id;
  if abs(v_dr - v_cr) > 0.01 then
    raise exception 'journal entry % is unbalanced: debit=% credit=%', p_je_id, v_dr, v_cr
      using errcode = 'P0001';
  end if;
end;
$$;


