--
-- Name: _assert_period_allows_posting("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_period_allows_posting"("p_posting_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_period erp.costing_periods%rowtype;
begin
  if p_posting_date is null then
    return;
  end if;

  select * into v_period
  from erp.costing_periods ap
  where ap.status = 'locked'
    and p_posting_date between ap.start_date and ap.end_date
  order by ap.end_date desc
  limit 1;

  if found then
    raise exception
      'Posting date % falls in locked costing period %. Reopen the period before backdating.',
      p_posting_date, v_period.period_code;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_assert_period_allows_posting"("p_posting_date" "date") OWNER TO "postgres";

