-- Name: _assert_period_open("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_period_open"("p_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if p_date is null then
    return;
  end if;
  if exists (
    select 1 from erp.accounting_periods ap
    where ap.status = 'closed'
      and p_date between ap.starts_on and ap.ends_on
  ) then
    raise exception 'Accounting period for % is closed', p_date using errcode = '42501';
  end if;
end;
$$;


