--
-- Name: _assert_posting_access(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_posting_access"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if not erp.is_session_live() then
    raise exception 'session has been terminated (logged out or expired); sign in again' using errcode = '28000';
  end if;
  if erp.has_role('ADMIN') or erp.has_role('ACCOUNTANT') then
    return;
  end if;
  if not erp.has_permission('transactions.post') then
    raise exception 'Posting denied: assign ADMIN or ACCOUNTANT role, or grant transactions.post' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "erp"."_assert_posting_access"() OWNER TO "postgres";

--
-- Name: _assert_production_wire8_stock("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_production_wire8_stock"("p_batch_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_batch erp.production_batches%rowtype;
  v_line record;
  v_need numeric := 0;
  v_have numeric := 0;
  v_code text;
begin
  select * into v_batch from erp.production_batches where id = p_batch_id;
  if not found then return; end if;
  if v_batch.process_type not in ('enamel', 'workshop') then return; end if;

  select coalesce(sum(pbl.net_weight), 0) into v_need
  from erp.production_batch_lines pbl
  where pbl.production_batch_id = p_batch_id
    and pbl.line_type = 'issue'
    and erp._is_wire8_item(pbl.item_id);

  if v_need <= 0.001 then return; end if;

  select erp._canonical_wire8_item_code(v_batch.batch_date) into v_code;

  select coalesce(sum(coalesce(im.qty_in, 0) - coalesce(im.qty_out, 0)), 0) into v_have
  from erp.inventory_movements im
  join erp.items i on i.id = im.item_id
  where i.code = v_code;

  if v_have + 0.001 < v_need then
    raise exception
      'Insufficient Wire No 8 stock (%): need % kg, on hand % kg. Post a purchase receipt or reduce production input.',
      v_code, round(v_need, 3), round(v_have, 3);
  end if;
end;
$$;


ALTER FUNCTION "erp"."_assert_production_wire8_stock"("p_batch_id" "uuid") OWNER TO "postgres";

--
-- Name: _assert_purchase_return_stock("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_purchase_return_stock"("p_return_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_returns%rowtype;
  v_line record;
  v_on_hand numeric;
begin
  select * into v_doc from erp.purchase_returns where id = p_return_id;
  if not found then return; end if;
  if coalesce(v_doc.return_action, '') <> 'stock' then return; end if;
  for v_line in
    select l.*, i.code as item_code, w.code as warehouse_code
    from erp.purchase_return_lines l
    join erp.items i on i.id = l.item_id
    left join erp.warehouses w on w.id = l.warehouse_id
    where l.purchase_return_id = p_return_id
      and l.item_id is not null
      and coalesce(l.qty, 0) > 0
    order by l.line_no
  loop
    v_on_hand := erp._inventory_on_hand(v_line.item_id, v_line.warehouse_id);
    if v_on_hand + 0.001 < v_line.qty then
      raise exception
        'Insufficient stock for % (%): need % kg, on hand % kg. Reduce quantity or choose financial-only return.',
        coalesce(v_line.item_code, 'item'),
        coalesce(v_line.warehouse_code, 'warehouse'),
        trim(to_char(v_line.qty, 'FM999,999,990.999')),
        trim(to_char(greatest(v_on_hand, 0), 'FM999,999,990.999'));
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "erp"."_assert_purchase_return_stock"("p_return_id" "uuid") OWNER TO "postgres";

--
-- Name: _assert_report_access(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_report_access"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    -- SQL Editor (postgres) and service_role jobs have no auth.uid().
    if session_user in ('postgres', 'supabase_admin')
       or coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
       or current_setting('erp.report_audit', true) = 'on'
    then
      return;
    end if;
    raise exception 'authentication required' using errcode = '28000';
  end if;
  if not (
    erp.has_permission('ledger.read')
    or erp.has_permission('transactions.read')
    or erp.has_permission('reports.financial.read')
    or erp.has_permission('masters.read')
    or erp.has_role('ADMIN')
    or erp.has_role('ACCOUNTANT')
  ) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "erp"."_assert_report_access"() OWNER TO "postgres";

--
-- Name: _assert_sales_invoice_stock("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assert_sales_invoice_stock"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_line record;
  v_on_hand numeric;
begin
  for v_line in
    select
      l.item_id,
      l.warehouse_id,
      max(i.code) as item_code,
      max(w.code) as warehouse_code,
      sum(coalesce(l.net_weight, l.qty, 0)) as required_qty
    from erp.sales_invoice_lines l
    join erp.items i on i.id = l.item_id
    join erp.warehouses w on w.id = l.warehouse_id
    where l.sales_invoice_id = p_invoice_id
      and l.item_id is not null
      and coalesce(l.net_weight, l.qty, 0) > 0
      and not coalesce(w.allow_negative_stock, false)
    group by l.item_id, l.warehouse_id
  loop
    v_on_hand := erp._inventory_on_hand(v_line.item_id, v_line.warehouse_id);
    if v_on_hand + 0.001 < v_line.required_qty then
      raise exception
        'Insufficient stock for % (%): need % kg across invoice lines, on hand % kg.',
        v_line.item_code,
        v_line.warehouse_code,
        trim(to_char(v_line.required_qty, 'FM999,999,990.999')),
        trim(to_char(greatest(v_on_hand, 0), 'FM999,999,990.999'));
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "erp"."_assert_sales_invoice_stock"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _assistant_resolve_party_code("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_assistant_resolve_party_code"("p_input" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select p.code
  from erp.parties p
  where p.is_active = true
    and (
      lower(p.code) = lower(trim(p_input))
      or p.code ilike trim(p_input)
      or p.name ilike '%' || trim(p_input) || '%'
    )
  order by
    case
      when lower(p.code) = lower(trim(p_input)) then 0
      when lower(p.name) = lower(trim(p_input)) then 1
      when p.code ilike trim(p_input) then 2
      else 3
    end,
    p.name
  limit 1;
$$;


ALTER FUNCTION "erp"."_assistant_resolve_party_code"("p_input" "text") OWNER TO "postgres";

