--
-- Name: _audit_log("text", "text", "text", "text", "uuid", "text", "jsonb", "jsonb", "text", "jsonb", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_audit_log"("p_action" "text", "p_entity_type" "text", "p_entity_id" "text", "p_source_doc_type" "text" DEFAULT NULL::"text", "p_source_doc_id" "uuid" DEFAULT NULL::"uuid", "p_source_doc_no" "text" DEFAULT NULL::"text", "p_before_data" "jsonb" DEFAULT NULL::"jsonb", "p_after_data" "jsonb" DEFAULT NULL::"jsonb", "p_summary" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  insert into erp.audit_events (
    actor_user_id, action, entity_type, entity_id,
    source_doc_type, source_doc_id, source_doc_no,
    before_data, after_data, summary, metadata
  ) values (
    coalesce(p_actor_user_id, auth.uid()),
    p_action,
    p_entity_type,
    p_entity_id,
    p_source_doc_type,
    p_source_doc_id,
    nullif(trim(p_source_doc_no), ''),
    p_before_data,
    p_after_data,
    p_summary,
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "erp"."_audit_log"("p_action" "text", "p_entity_type" "text", "p_entity_id" "text", "p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_source_doc_no" "text", "p_before_data" "jsonb", "p_after_data" "jsonb", "p_summary" "text", "p_metadata" "jsonb", "p_actor_user_id" "uuid") OWNER TO "postgres";

--
-- Name: _audit_log_safe("text", "text", "text", "text", "uuid", "text", "jsonb", "jsonb", "text", "jsonb", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_audit_log_safe"("p_action" "text", "p_entity_type" "text", "p_entity_id" "text", "p_source_doc_type" "text" DEFAULT NULL::"text", "p_source_doc_id" "uuid" DEFAULT NULL::"uuid", "p_source_doc_no" "text" DEFAULT NULL::"text", "p_before_data" "jsonb" DEFAULT NULL::"jsonb", "p_after_data" "jsonb" DEFAULT NULL::"jsonb", "p_summary" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  begin
    perform erp._audit_log(
      p_action, p_entity_type, p_entity_id,
      p_source_doc_type, p_source_doc_id, p_source_doc_no,
      p_before_data, p_after_data, p_summary, p_metadata, p_actor_user_id
    );
  exception when others then
    raise warning 'audit_log failed (% %): %', p_entity_type, p_entity_id, sqlerrm;
  end;
end;
$$;


ALTER FUNCTION "erp"."_audit_log_safe"("p_action" "text", "p_entity_type" "text", "p_entity_id" "text", "p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_source_doc_no" "text", "p_before_data" "jsonb", "p_after_data" "jsonb", "p_summary" "text", "p_metadata" "jsonb", "p_actor_user_id" "uuid") OWNER TO "postgres";

--
-- Name: _audit_resolve_source("text", "jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_audit_resolve_source"("p_table" "text", "p_row" "jsonb") RETURNS TABLE("source_doc_type" "text", "source_doc_id" "uuid", "source_doc_no" "text")
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  case p_table
    when 'sales_invoices' then
      return query select 'sales_invoice'::text, (p_row->>'id')::uuid, p_row->>'invoice_no';
    when 'purchase_invoices' then
      return query select 'purchase_invoice'::text, (p_row->>'id')::uuid, p_row->>'invoice_no';
    when 'sales_returns' then
      return query select 'sales_return'::text, (p_row->>'id')::uuid, p_row->>'return_no';
    when 'purchase_returns' then
      return query select 'purchase_return'::text, (p_row->>'id')::uuid, p_row->>'return_no';
    when 'payments' then
      return query select 'payment'::text, (p_row->>'id')::uuid, p_row->>'payment_no';
    when 'parchi_instruments' then
      return query select 'parchi_instrument'::text, (p_row->>'id')::uuid, p_row->>'parchi_no';
    when 'sales_orders' then
      return query select 'sales_order'::text, (p_row->>'id')::uuid, p_row->>'order_no';
    when 'purchase_orders' then
      return query select 'purchase_order'::text, (p_row->>'id')::uuid, p_row->>'order_no';
    when 'production_batches' then
      return query select 'production_batch'::text, (p_row->>'id')::uuid, p_row->>'batch_no';
    when 'scrap_trades' then
      return query select 'scrap_trade'::text, (p_row->>'id')::uuid, p_row->>'trade_no';
    when 'drawing_weekly_wage_sheets' then
      return query select 'drawing_weekly_wage_sheet'::text, (p_row->>'id')::uuid, p_row->>'sheet_no';
    when 'items' then
      return query select 'item'::text, (p_row->>'id')::uuid, p_row->>'code';
    when 'parties' then
      return query select 'party'::text, (p_row->>'id')::uuid, p_row->>'code';
    when 'coa_accounts' then
      return query select 'coa_account'::text, (p_row->>'id')::uuid, p_row->>'code';
    else
      return query select p_table::text, null::uuid, null::text;
  end case;
end;
$$;


ALTER FUNCTION "erp"."_audit_resolve_source"("p_table" "text", "p_row" "jsonb") OWNER TO "postgres";

--
-- Name: _audit_row_summary("text", "text", "jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_audit_row_summary"("p_table" "text", "p_action" "text", "p_row" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_ref text;
begin
  v_ref := coalesce(
    p_row->>'invoice_no', p_row->>'return_no', p_row->>'payment_no', p_row->>'parchi_no',
    p_row->>'order_no', p_row->>'batch_no', p_row->>'trade_no', p_row->>'sheet_no',
    p_row->>'code', p_row->>'name', p_row->>'id'
  );
  return initcap(p_action) || ' ' || replace(p_table, '_', ' ') || coalesce(' ' || v_ref, '');
end;
$$;


ALTER FUNCTION "erp"."_audit_row_summary"("p_table" "text", "p_action" "text", "p_row" "jsonb") OWNER TO "postgres";

--
-- Name: _audit_trigger_fn(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_audit_trigger_fn"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_action text;
  v_row jsonb;
  v_before jsonb;
  v_src record;
begin
  if TG_OP = 'INSERT' then
    v_action := 'insert';
    v_row := to_jsonb(NEW);
    v_before := null;
  elsif TG_OP = 'UPDATE' then
    if to_jsonb(OLD) = to_jsonb(NEW) then
      return NEW;
    end if;
    v_action := 'update';
    v_row := to_jsonb(NEW);
    v_before := to_jsonb(OLD);
  elsif TG_OP = 'DELETE' then
    v_action := 'delete';
    v_row := to_jsonb(OLD);
    v_before := to_jsonb(OLD);
  else
    return coalesce(NEW, OLD);
  end if;

  select * into v_src from erp._audit_resolve_source(TG_TABLE_NAME, v_row);

  perform erp._audit_log_safe(
    v_action,
    TG_TABLE_NAME,
    coalesce(v_row->>'id', v_row->>'code', 'unknown'),
    v_src.source_doc_type,
    v_src.source_doc_id,
    v_src.source_doc_no,
    v_before,
    case when TG_OP = 'DELETE' then null else v_row end,
    erp._audit_row_summary(TG_TABLE_NAME, v_action, v_row),
    jsonb_build_object('trigger', TG_TABLE_NAME)
  );

  return coalesce(NEW, OLD);
end;
$$;


ALTER FUNCTION "erp"."_audit_trigger_fn"() OWNER TO "postgres";

--
-- Name: _block_drawing_production(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_block_drawing_production"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if new.process_type = 'drawing' then
    raise exception 'Drawing production is disabled. Receive Wire No 8 via purchase invoice.';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "erp"."_block_drawing_production"() OWNER TO "postgres";

--
-- Name: _build_all_wac_replay(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_build_all_wac_replay"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  r record;
  v_item uuid;
  v_wh uuid;
  v_qty numeric := 0;
  v_value numeric := 0;
  v_avg numeric := 0;
  v_last_valid_avg numeric := 0;
  v_last_explicit_inbound_rate numeric := 0;
  v_c_value numeric := 0;
  v_v_value numeric := 0;
  v_p_value numeric := 0;
  v_o_value numeric := 0;
  v_c_unit numeric := 0;
  v_v_unit numeric := 0;
  v_p_unit numeric := 0;
  v_o_unit numeric := 0;
  v_qty_before numeric;
  v_qty_after numeric;
  v_wac_before numeric;
  v_expected_unit numeric;
  v_expected_value numeric;
  v_expected_c numeric;
  v_expected_v numeric;
  v_expected_p numeric;
  v_expected_o numeric;
  v_state_out_value numeric;
  v_state_out_c numeric;
  v_state_out_v numeric;
  v_state_out_p numeric;
  v_state_out_o numeric;
  v_in_value numeric;
  v_cost_source text;
  v_fallback boolean;
  v_unresolved boolean;
  v_locked boolean;
  v_use_pac_stamp boolean;
  v_negative boolean;
  v_pac numeric;
  v_standard numeric;
  v_comp_kind text;
begin
  drop table if exists pg_temp.wac_replay_results;
  create temporary table wac_replay_results (
    movement_id uuid primary key,
    item_id uuid not null,
    warehouse_id uuid not null,
    posting_date date not null,
    created_at timestamptz not null,
    movement_type text not null,
    source_doc_type text not null,
    source_doc_id uuid not null,
    source_line_id uuid,
    qty_in numeric not null,
    qty_out numeric not null,
    qty_before numeric not null,
    qty_after numeric not null,
    negative_event boolean not null,
    locked_pac_stamp boolean not null,
    cost_source text not null,
    fallback_used boolean not null,
    unresolved_zero_cost boolean not null,
    current_unit_cost numeric not null,
    expected_unit_cost numeric not null,
    current_value numeric not null,
    expected_value numeric not null,
    movement_value_delta numeric not null,
    wac_before numeric not null,
    wac_after numeric not null,
    current_copper numeric not null,
    expected_copper numeric not null,
    current_varnish numeric not null,
    expected_varnish numeric not null,
    current_packing numeric not null,
    expected_packing numeric not null,
    current_oh numeric not null,
    expected_oh numeric not null
  ) on commit drop;

  for r in
    select
      im.*,
      i.standard_cost,
      exists (
        select 1
        from erp.costing_periods cp
        where cp.id = im.costed_period_id
          and cp.status = 'locked'
          and coalesce(im.cost_status, '') = 'period_final'
      ) as is_locked_pac,
      coalesce(im.cost_status, 'provisional') in ('period_draft', 'period_final')
        and coalesce(im.unit_cost, 0) > 0 as is_pac_stamp,
      (
        select pcr.pac_unit_cost
        from erp.period_cost_rates pcr
        join erp.costing_periods cp on cp.id = pcr.period_id
        where pcr.item_id = im.item_id
          and cp.status = 'locked'
          and im.posting_date between cp.start_date and cp.end_date
          and pcr.is_draft = false
        order by cp.end_date desc, pcr.computed_at desc
        limit 1
      ) as locked_pac_rate
    from erp.inventory_movements im
    join erp.items i on i.id = im.item_id
    order by im.item_id, im.warehouse_id, im.posting_date, im.created_at, im.id
  loop
    if v_item is distinct from r.item_id or v_wh is distinct from r.warehouse_id then
      v_item := r.item_id;
      v_wh := r.warehouse_id;
      v_qty := 0;
      v_value := 0;
      v_avg := 0;
      v_last_valid_avg := 0;
      v_last_explicit_inbound_rate := 0;
      v_c_value := 0;
      v_v_value := 0;
      v_p_value := 0;
      v_o_value := 0;
      v_c_unit := 0;
      v_v_unit := 0;
      v_p_unit := 0;
      v_o_unit := 0;
    end if;

    v_qty_before := v_qty;
    v_wac_before := coalesce(nullif(v_avg, 0), v_last_valid_avg, 0);
    v_expected_unit := 0;
    v_expected_value := 0;
    v_expected_c := 0;
    v_expected_v := 0;
    v_expected_p := 0;
    v_expected_o := 0;
    v_state_out_value := 0;
    v_state_out_c := 0;
    v_state_out_v := 0;
    v_state_out_p := 0;
    v_state_out_o := 0;
    v_cost_source := 'chronological_wac';
    v_fallback := false;
    v_unresolved := false;
    v_locked := coalesce(r.is_locked_pac, false);
    v_use_pac_stamp := coalesce(r.is_pac_stamp, false);
    v_pac := coalesce(r.locked_pac_rate, 0);
    v_standard := coalesce(r.standard_cost, 0);

    if coalesce(r.qty_out, 0) > 0 then
      if v_use_pac_stamp then
        v_expected_unit := r.unit_cost;
        v_cost_source := case
          when v_locked then 'locked_pac_stamp' else 'pac_stamp'
        end;
      else
        v_expected_unit := coalesce(nullif(v_avg, 0), nullif(v_last_valid_avg, 0), 0);
        if v_expected_unit <= 0 and v_pac > 0 then
          v_expected_unit := v_pac;
          v_cost_source := 'locked_pac_fallback';
          v_fallback := true;
        elsif v_expected_unit <= 0 and v_standard > 0 then
          v_expected_unit := v_standard;
          v_cost_source := 'item_standard_fallback';
          v_fallback := true;
        end if;
      end if;

      v_expected_value := round(coalesce(r.qty_out, 0) * v_expected_unit, 3);
      if v_use_pac_stamp then
        v_expected_c := coalesce(r.cost_copper, 0);
        v_expected_v := coalesce(r.cost_varnish, 0);
        v_expected_p := coalesce(r.cost_packing, 0);
        v_expected_o := coalesce(r.cost_oh, 0);
      else
        v_expected_c := round(coalesce(r.qty_out, 0) * v_c_unit, 3);
        v_expected_v := round(coalesce(r.qty_out, 0) * v_v_unit, 3);
        v_expected_p := round(coalesce(r.qty_out, 0) * v_p_unit, 3);
        v_expected_o := round(coalesce(r.qty_out, 0) * v_o_unit, 3);
        if v_expected_c + v_expected_v + v_expected_p + v_expected_o <= 0
           and v_expected_value > 0 then
          v_expected_c := v_expected_value;
        end if;
      end if;

      if r.movement_type = 'scrap_out'
         and r.source_doc_type = 'factory_scrap_dispatch' then
        -- This is the outbound half of an immediate scrap_in/scrap_out mirror.
        -- Its movement stamp is intentionally zero; the linked parent-RM
        -- production_issue and 51006/12104 JE carry the economic value.
        -- Preserve that audit convention while the replay state still relieves
        -- the mirrored scrap quantity at chronological WAC.
        v_expected_unit := coalesce(r.unit_cost, 0);
        v_expected_value := coalesce(r.value_amount, 0);
        v_expected_c := coalesce(r.cost_copper, 0);
        v_expected_v := coalesce(r.cost_varnish, 0);
        v_expected_p := coalesce(r.cost_packing, 0);
        v_expected_o := coalesce(r.cost_oh, 0);
        v_cost_source := 'paired_scrap_mirror';
        v_state_out_value := round(r.qty_out * coalesce(v_avg, 0), 3);
        v_state_out_c := round(r.qty_out * v_c_unit, 3);
        v_state_out_v := round(r.qty_out * v_v_unit, 3);
        v_state_out_p := round(r.qty_out * v_p_unit, 3);
        v_state_out_o := round(r.qty_out * v_o_unit, 3);
      elsif r.movement_type = 'purchase_return_out'
         and not v_use_pac_stamp
         and coalesce(r.unit_cost, 0) > 0 then
        -- Migration 291's movement stamp is original purchase cost and is
        -- immutable provenance. Canonical Book-WAC state still relieves the
        -- running average (migration 290), so movement and state values differ
        -- intentionally and the GL variance helper accounts for that policy.
        v_expected_unit := r.unit_cost;
        v_expected_value := coalesce(
          nullif(r.value_amount, 0),
          round(r.qty_out * r.unit_cost, 3)
        );
        v_expected_c := coalesce(r.cost_copper, 0);
        v_expected_v := coalesce(r.cost_varnish, 0);
        v_expected_p := coalesce(r.cost_packing, 0);
        v_expected_o := coalesce(r.cost_oh, 0);
        v_cost_source := 'original_purchase_return_cost';
        v_state_out_value := round(r.qty_out * coalesce(v_avg, 0), 3);
        v_state_out_c := round(r.qty_out * v_c_unit, 3);
        v_state_out_v := round(r.qty_out * v_v_unit, 3);
        v_state_out_p := round(r.qty_out * v_p_unit, 3);
        v_state_out_o := round(r.qty_out * v_o_unit, 3);
      else
        v_state_out_value := v_expected_value;
        v_state_out_c := v_expected_c;
        v_state_out_v := v_expected_v;
        v_state_out_p := v_expected_p;
        v_state_out_o := v_expected_o;
      end if;

      v_qty := v_qty - coalesce(r.qty_out, 0);
      v_value := v_value - v_state_out_value;
      v_c_value := v_c_value - v_state_out_c;
      v_v_value := v_v_value - v_state_out_v;
      v_p_value := v_p_value - v_state_out_p;
      v_o_value := v_o_value - v_state_out_o;
    else
      if v_locked and coalesce(r.unit_cost, 0) > 0 then
        v_expected_unit := r.unit_cost;
        v_in_value := coalesce(nullif(r.value_amount, 0), round(r.qty_in * r.unit_cost, 3), 0);
        v_cost_source := 'locked_pac_stamp';
      elsif coalesce(r.value_amount, 0) > 0 and coalesce(r.qty_in, 0) > 0 then
        v_in_value := r.value_amount;
        v_expected_unit := round(v_in_value / r.qty_in, 6);
        v_cost_source := 'explicit_value';
      elsif coalesce(r.unit_cost, 0) > 0 then
        v_expected_unit := r.unit_cost;
        v_in_value := round(r.qty_in * r.unit_cost, 3);
        v_cost_source := 'explicit_unit_cost';
      elsif v_last_explicit_inbound_rate > 0 then
        v_expected_unit := v_last_explicit_inbound_rate;
        v_in_value := round(r.qty_in * v_expected_unit, 3);
        v_cost_source := 'last_explicit_inbound_fallback';
        v_fallback := true;
      elsif coalesce(v_avg, 0) > 0 or coalesce(v_last_valid_avg, 0) > 0 then
        v_expected_unit := coalesce(nullif(v_avg, 0), v_last_valid_avg);
        v_in_value := round(r.qty_in * v_expected_unit, 3);
        v_cost_source := 'last_valid_wac_fallback';
        v_fallback := true;
      elsif v_pac > 0 then
        v_expected_unit := v_pac;
        v_in_value := round(r.qty_in * v_expected_unit, 3);
        v_cost_source := 'locked_pac_fallback';
        v_fallback := true;
      elsif v_standard > 0 then
        v_expected_unit := v_standard;
        v_in_value := round(r.qty_in * v_expected_unit, 3);
        v_cost_source := 'item_standard_fallback';
        v_fallback := true;
      else
        v_expected_unit := 0;
        v_in_value := 0;
        v_cost_source := 'unresolved_zero_cost';
        v_fallback := true;
        v_unresolved := true;
      end if;

      v_expected_value := coalesce(v_in_value, 0);
      if r.movement_type in ('opening', 'purchase_in')
         and v_cost_source in ('locked_pac_stamp', 'explicit_value', 'explicit_unit_cost')
         and v_expected_unit > 0 then
        v_last_explicit_inbound_rate := v_expected_unit;
      end if;
      if r.cost_copper is not null or r.cost_varnish is not null
         or r.cost_packing is not null or r.cost_oh is not null then
        v_expected_c := coalesce(r.cost_copper, 0);
        v_expected_v := coalesce(r.cost_varnish, 0);
        v_expected_p := coalesce(r.cost_packing, 0);
        v_expected_o := coalesce(r.cost_oh, 0);
      else
        v_comp_kind := case
          when to_regprocedure('erp._issue_cost_component(uuid,uuid)') is not null
            then erp._issue_cost_component(r.item_id, r.warehouse_id)
          else 'copper'
        end;
        if v_comp_kind = 'varnish' then
          v_expected_v := v_expected_value;
        elsif v_comp_kind = 'packing' then
          v_expected_p := v_expected_value;
        else
          v_expected_c := v_expected_value;
        end if;
      end if;

      v_qty_after := v_qty + coalesce(r.qty_in, 0);
      if v_qty > 0.001 then
        v_qty := v_qty_after;
        v_value := v_value + v_expected_value;
        v_c_value := v_c_value + v_expected_c;
        v_v_value := v_v_value + v_expected_v;
        v_p_value := v_p_value + v_expected_p;
        v_o_value := v_o_value + v_expected_o;
      elsif v_qty_after > 0.001 then
        -- Match migration 290: a receipt that clears a deficit starts the
        -- positive remainder at that receipt's rate/components.
        v_qty := v_qty_after;
        v_avg := v_expected_unit;
        v_value := round(v_qty * v_avg, 3);
        v_c_unit := round(v_expected_c / nullif(r.qty_in, 0), 6);
        v_v_unit := round(v_expected_v / nullif(r.qty_in, 0), 6);
        v_p_unit := round(v_expected_p / nullif(r.qty_in, 0), 6);
        v_o_unit := round(v_expected_o / nullif(r.qty_in, 0), 6);
        v_c_value := round(v_qty * v_c_unit, 3);
        v_v_value := round(v_qty * v_v_unit, 3);
        v_p_value := round(v_qty * v_p_unit, 3);
        v_o_value := round(v_qty * v_o_unit, 3);
      else
        v_qty := v_qty_after;
        v_value := round(v_qty * v_avg, 3);
        v_c_value := round(v_qty * v_c_unit, 3);
        v_v_value := round(v_qty * v_v_unit, 3);
        v_p_value := round(v_qty * v_p_unit, 3);
        v_o_value := round(v_qty * v_o_unit, 3);
      end if;
    end if;

    v_qty_after := v_qty;
    v_negative := v_qty_after < -0.001;

    -- At zero/negative stock retain the last valid rate and do not divide a
    -- signed value by signed quantity. This is the migration-290 policy.
    if v_qty_after > 0.001 then
      v_avg := round(v_value / v_qty_after, 6);
      v_c_unit := round(v_c_value / v_qty_after, 6);
      v_v_unit := round(v_v_value / v_qty_after, 6);
      v_p_unit := round(v_p_value / v_qty_after, 6);
      v_o_unit := round(v_o_value / v_qty_after, 6);
      if v_avg > 0 then
        v_last_valid_avg := v_avg;
      end if;
    else
      v_avg := v_last_valid_avg;
      v_value := round(v_qty_after * v_avg, 3);
      v_c_value := round(v_qty_after * v_c_unit, 3);
      v_v_value := round(v_qty_after * v_v_unit, 3);
      v_p_value := round(v_qty_after * v_p_unit, 3);
      v_o_value := round(v_qty_after * v_o_unit, 3);
    end if;

    insert into pg_temp.wac_replay_results (
      movement_id, item_id, warehouse_id, posting_date, created_at,
      movement_type, source_doc_type, source_doc_id, source_line_id,
      qty_in, qty_out, qty_before, qty_after, negative_event,
      locked_pac_stamp, cost_source, fallback_used, unresolved_zero_cost,
      current_unit_cost, expected_unit_cost, current_value, expected_value,
      movement_value_delta, wac_before, wac_after,
      current_copper, expected_copper, current_varnish, expected_varnish,
      current_packing, expected_packing, current_oh, expected_oh
    ) values (
      r.id, r.item_id, r.warehouse_id, r.posting_date, r.created_at,
      r.movement_type, r.source_doc_type, r.source_doc_id, r.source_line_id,
      coalesce(r.qty_in, 0), coalesce(r.qty_out, 0), v_qty_before, v_qty_after,
      v_negative, v_locked, v_cost_source, v_fallback, v_unresolved,
      coalesce(r.unit_cost, 0), v_expected_unit,
      coalesce(r.value_amount, 0), v_expected_value,
      round(v_expected_value - coalesce(r.value_amount, 0), 3),
      v_wac_before, v_avg,
      coalesce(r.cost_copper, 0), v_expected_c,
      coalesce(r.cost_varnish, 0), v_expected_v,
      coalesce(r.cost_packing, 0), v_expected_p,
      coalesce(r.cost_oh, 0), v_expected_o
    );
  end loop;
end;
$$;


ALTER FUNCTION "erp"."_build_all_wac_replay"() OWNER TO "postgres";

--
-- Name: _canonical_wire8_item_code("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_canonical_wire8_item_code"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(
    nullif(trim((
      select s.text_value
      from erp.production_standards s
      where s.standard_key = 'wire8_item_code'
        and s.effective_from <= coalesce(p_as_of, current_date)
      order by s.effective_from desc
      limit 1
    )), ''),
    'RM-W8-001'
  );
$$;


ALTER FUNCTION "erp"."_canonical_wire8_item_code"("p_as_of" "date") OWNER TO "postgres";

--
-- Name: _canonical_wire8_item_id("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_canonical_wire8_item_id"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select id from erp.items where code = erp._canonical_wire8_item_code(p_as_of) limit 1;
$$;


ALTER FUNCTION "erp"."_canonical_wire8_item_id"("p_as_of" "date") OWNER TO "postgres";

--
-- Name: _cascade_purchase_reprice_cogs("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_cascade_purchase_reprice_cogs"("p_purchase_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_pair record;
  v_batch record;
  v_receipt record;
  v_je record;
  v_depth int := 0;
  v_new_batches int := 0;
  v_direct_pairs int := 0;
  v_sales_restamped int := 0;
  v_period_draft_sales_restamped int := 0;
  v_locked_or_final_sales_skipped int := 0;
  v_sales_gl_synced int := 0;
  v_production_batches int := 0;
  v_production_gl_synced int := 0;
  v_production_journals_voided int := 0;
  v_part jsonb;
  v_item_ids uuid[];
  v_seq int;
begin
  drop table if exists pg_temp._purchase_reprice_pairs;
  create temp table _purchase_reprice_pairs (
    item_id uuid not null,
    warehouse_id uuid not null,
    first_date date not null,
    primary key (item_id, warehouse_id)
  ) on commit drop;

  drop table if exists pg_temp._purchase_reprice_restamped_pairs;
  create temp table _purchase_reprice_restamped_pairs (
    item_id uuid not null,
    warehouse_id uuid not null,
    primary key (item_id, warehouse_id)
  ) on commit drop;

  drop table if exists pg_temp._purchase_reprice_batches;
  create temp table _purchase_reprice_batches (
    batch_id uuid primary key
  ) on commit drop;

  insert into pg_temp._purchase_reprice_pairs (item_id, warehouse_id, first_date)
  select im.item_id, im.warehouse_id, min(im.posting_date)::date
  from erp.inventory_movements im
  where im.source_doc_type = 'purchase_invoice'
    and im.source_doc_id = p_purchase_invoice_id
    and im.item_id is not null
    and im.warehouse_id is not null
    and coalesce(im.qty_in, 0) > 0
  group by im.item_id, im.warehouse_id
  on conflict (item_id, warehouse_id) do update
  set first_date = least(_purchase_reprice_pairs.first_date, excluded.first_date);

  select coalesce(array_agg(distinct item_id), '{}') into v_item_ids
  from pg_temp._purchase_reprice_pairs;
  if coalesce(array_length(v_item_ids, 1), 0) > 0 then
    perform erp._rebuild_after_document_post(v_item_ids);
  end if;

  loop
    v_depth := v_depth + 1;
    v_new_batches := 0;

    for v_pair in
      select p.item_id, p.warehouse_id
      from pg_temp._purchase_reprice_pairs p
      left join pg_temp._purchase_reprice_restamped_pairs r
        on r.item_id = p.item_id and r.warehouse_id = p.warehouse_id
      where r.item_id is null
      order by p.first_date, p.item_id, p.warehouse_id
    loop
      v_part := erp._restamp_purchase_reprice_sales_cogs_for_item_wh(v_pair.item_id, v_pair.warehouse_id, null);
      v_direct_pairs := v_direct_pairs + 1;
      v_sales_restamped := v_sales_restamped + coalesce((v_part->>'sales_out_restamped')::int, 0);
      v_period_draft_sales_restamped := v_period_draft_sales_restamped + coalesce((v_part->>'period_draft_sales_restamped')::int, 0);
      v_locked_or_final_sales_skipped := v_locked_or_final_sales_skipped + coalesce((v_part->>'locked_or_final_sales_skipped')::int, 0);
      v_sales_gl_synced := v_sales_gl_synced + coalesce((v_part->>'invoices_gl_synced')::int, 0);

      insert into pg_temp._purchase_reprice_restamped_pairs (item_id, warehouse_id)
      values (v_pair.item_id, v_pair.warehouse_id)
      on conflict do nothing;
    end loop;

    for v_batch in
      select distinct pb.id, pb.batch_date, pb.batch_no
      from erp.production_batches pb
      join erp.inventory_movements im
        on im.source_doc_type = 'production_batch'
       and im.source_doc_id = pb.id
       and im.movement_type = 'production_issue'
      join pg_temp._purchase_reprice_pairs p
        on p.item_id = im.item_id
       and p.warehouse_id = im.warehouse_id
      left join pg_temp._purchase_reprice_batches done on done.batch_id = pb.id
      where pb.status = 'posted'
        and done.batch_id is null
        and im.posting_date >= p.first_date
        and not exists (
          select 1
          from erp.costing_periods cp
          where cp.status = 'locked'
            and pb.batch_date between cp.start_date and cp.end_date
        )
      order by pb.batch_date, pb.batch_no, pb.id
    loop
      perform erp._apply_production_batch_costing(v_batch.id);
      v_production_batches := v_production_batches + 1;
      v_new_batches := v_new_batches + 1;

      v_seq := 0;
      for v_je in
        select je.id
        from erp.journal_entries je
        where je.source_doc_type = 'production_batch'
          and je.source_doc_id = v_batch.id
          and coalesce(je.voucher_no, '') not like 'VOID-%'
        order by je.posted_at, je.id
      loop
        v_seq := v_seq + 1;
        update erp.journal_entries
        set voucher_no = 'VOID-REPRICE-' || left(v_batch.id::text, 8)
              || case when v_seq > 1 then '-' || v_seq::text else '' end,
            narration = coalesce(narration, '')
              || format(' [superseded by purchase reprice cascade for %s]', p_purchase_invoice_id)
        where id = v_je.id;
        v_production_journals_voided := v_production_journals_voided + 1;
      end loop;

      perform erp._sync_production_batch_gl(v_batch.id);
      v_production_gl_synced := v_production_gl_synced + 1;

      select coalesce(array_agg(distinct im.item_id), '{}') into v_item_ids
      from erp.inventory_movements im
      where im.source_doc_type = 'production_batch'
        and im.source_doc_id = v_batch.id
        and im.item_id is not null;
      if coalesce(array_length(v_item_ids, 1), 0) > 0 then
        perform erp._rebuild_after_document_post(v_item_ids);
      end if;

      for v_receipt in
        select distinct im.item_id, im.warehouse_id, min(im.posting_date)::date as first_date
        from erp.inventory_movements im
        where im.source_doc_type = 'production_batch'
          and im.source_doc_id = v_batch.id
          and im.movement_type = 'production_receipt'
          and im.item_id is not null
          and im.warehouse_id is not null
          and coalesce(im.qty_in, 0) > 0
        group by im.item_id, im.warehouse_id
      loop
        insert into pg_temp._purchase_reprice_pairs (item_id, warehouse_id, first_date)
        values (v_receipt.item_id, v_receipt.warehouse_id, v_receipt.first_date)
        on conflict (item_id, warehouse_id) do update
        set first_date = least(_purchase_reprice_pairs.first_date, excluded.first_date);
      end loop;

      insert into pg_temp._purchase_reprice_batches (batch_id)
      values (v_batch.id)
      on conflict do nothing;
    end loop;

    exit when v_new_batches = 0 or v_depth >= 8;
  end loop;

  return jsonb_build_object(
    'direct_pairs_restamped', v_direct_pairs,
    'sales_out_restamped', v_sales_restamped,
    'period_draft_sales_restamped', v_period_draft_sales_restamped,
    'locked_or_final_sales_skipped', v_locked_or_final_sales_skipped,
    'sales_invoices_gl_synced', v_sales_gl_synced,
    'production_batches_recosted', v_production_batches,
    'production_journals_voided', v_production_journals_voided,
    'production_gl_synced', v_production_gl_synced,
    'cascade_depth', v_depth
  );
end;
$$;


ALTER FUNCTION "erp"."_cascade_purchase_reprice_cogs"("p_purchase_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _clear_ar_payment_allocations_for_doc("text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_clear_ar_payment_allocations_for_doc"("p_source_doc_type" "text", "p_source_doc_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_n int;
begin
  with ad as (
    select id from erp.ar_documents
    where source_doc_type = p_source_doc_type and source_doc_id = p_source_doc_id
  )
  delete from erp.payment_allocations pa
  using ad
  where pa.ar_document_id = ad.id;

  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


ALTER FUNCTION "erp"."_clear_ar_payment_allocations_for_doc"("p_source_doc_type" "text", "p_source_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: _clear_factory_scrap_dispatch_posting("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_clear_factory_scrap_dispatch_posting"("p_doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item_ids uuid[];
begin
  if exists (
    select 1
    from erp.ar_documents ad
    join erp.payment_allocations pa on pa.ar_document_id = ad.id
    where ad.source_doc_type = 'factory_scrap_dispatch'
      and ad.source_doc_id = p_doc_id
  ) then
    raise exception 'cannot change dispatch: cashbook payment allocations exist - clear allocations first';
  end if;

  select coalesce(array_agg(distinct item_id), '{}')
  into v_item_ids
  from erp.inventory_movements
  where source_doc_type = 'factory_scrap_dispatch'
    and source_doc_id = p_doc_id;

  -- Removing an outbound movement credits stock. Do this before removing the
  -- matching scrap receipt so the row guard sees the correct final direction.
  delete from erp.inventory_movements
  where source_doc_type = 'factory_scrap_dispatch'
    and source_doc_id = p_doc_id
    and coalesce(qty_out, 0) > 0;

  delete from erp.inventory_movements
  where source_doc_type = 'factory_scrap_dispatch'
    and source_doc_id = p_doc_id;

  perform erp._clear_ar_payment_allocations_for_doc('factory_scrap_dispatch', p_doc_id);
  delete from erp.ar_documents
  where source_doc_type = 'factory_scrap_dispatch'
    and source_doc_id = p_doc_id;
  perform erp._hard_delete_clear_journals('factory_scrap_dispatch', p_doc_id);

  if coalesce(array_length(v_item_ids, 1), 0) > 0 then
    perform erp.rebuild_inventory_balances_for_items(v_item_ids);
  end if;
end;
$$;


ALTER FUNCTION "erp"."_clear_factory_scrap_dispatch_posting"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: _clear_factory_scrap_obligation("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_clear_factory_scrap_obligation"("p_dispatch_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_obl record;
begin
  perform erp._assert_factory_scrap_has_no_returns(p_dispatch_id);
  perform erp._purge_scrap_payable_lots_for_dispatch(p_dispatch_id);

  select * into v_obl
  from erp.scrap_conversion_obligations
  where dispatch_id = p_dispatch_id;
  if not found then return; end if;

  delete from erp.scrap_conversion_obligations where id = v_obl.id;
end;
$$;


ALTER FUNCTION "erp"."_clear_factory_scrap_obligation"("p_dispatch_id" "uuid") OWNER TO "postgres";

--
-- Name: _clear_purchase_invoice_draft_posting("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_clear_purchase_invoice_draft_posting"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if exists (
    select 1 from erp.purchase_invoices pi
    where pi.id = p_invoice_id and pi.posting_status = 'posted'
  ) then
    return;
  end if;

  perform erp._revert_purchase_order_receiving_from_invoice(p_invoice_id);

  delete from erp.inventory_movements
  where source_doc_type = 'purchase_invoice' and source_doc_id = p_invoice_id;

  delete from erp.journal_lines jl
  using erp.journal_entries je
  where je.id = jl.journal_entry_id
    and je.source_doc_type = 'purchase_invoice'
    and je.source_doc_id = p_invoice_id;

  delete from erp.journal_entries
  where source_doc_type = 'purchase_invoice' and source_doc_id = p_invoice_id;

  delete from erp.ap_documents ad
  where ad.source_doc_type = 'purchase_invoice'
    and ad.source_doc_id = p_invoice_id
    and not exists (
      select 1 from erp.payment_allocations pa where pa.ap_document_id = ad.id
    );
end;
$$;


ALTER FUNCTION "erp"."_clear_purchase_invoice_draft_posting"("p_invoice_id" "uuid") OWNER TO "postgres";

