--
-- Name: _compute_drawing_sheet_totals(numeric, numeric, numeric, "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_compute_drawing_sheet_totals"("p_received" numeric, "p_scrap" numeric, "p_base_rate" numeric, "p_sheet_id" "uuid") RETURNS TABLE("net_kg" numeric, "base_wage" numeric, "premium_wage" numeric, "total_wage" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_net numeric;
  v_base numeric;
  v_premium numeric;
begin
  v_net := greatest(coalesce(p_received, 0) - coalesce(p_scrap, 0), 0);
  v_base := round(v_net * coalesce(p_base_rate, 0), 2);

  select coalesce(sum(round(pl.weight_kg * pl.rate_pkr_per_kg, 2)), 0)
    into v_premium
  from erp.drawing_weekly_wage_premium_lines pl
  where pl.sheet_id = p_sheet_id;

  return query select v_net, v_base, v_premium, v_base + v_premium;
end;
$$;


ALTER FUNCTION "erp"."_compute_drawing_sheet_totals"("p_received" numeric, "p_scrap" numeric, "p_base_rate" numeric, "p_sheet_id" "uuid") OWNER TO "postgres";

--
-- Name: _consume_party_scrap_credit("uuid", numeric, "uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_consume_party_scrap_credit"("p_credit_id" "uuid", "p_allocated_kg" numeric, "p_scrap_trade_id" "uuid", "p_obligation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_credit erp.party_scrap_credits%rowtype;
  v_open numeric;
begin
  if coalesce(p_allocated_kg, 0) <= 0 then return; end if;

  select * into v_credit
  from erp.party_scrap_credits
  where id = p_credit_id
  for update;

  if not found then
    raise exception 'Party scrap credit % not found', p_credit_id;
  end if;

  if v_credit.status = 'void' then
    raise exception 'Party scrap credit % is void', p_credit_id;
  end if;

  v_open := v_credit.credit_kg - v_credit.consumed_kg;
  if p_allocated_kg > v_open + 0.001 then
    raise exception 'Credit open kg % insufficient for allocation %', v_open, p_allocated_kg;
  end if;

  update erp.party_scrap_credits
  set consumed_kg = consumed_kg + p_allocated_kg
  where id = p_credit_id;

  insert into erp.scrap_credit_allocations (scrap_credit_id, obligation_id, scrap_trade_id, allocated_kg)
  values (p_credit_id, p_obligation_id, p_scrap_trade_id, p_allocated_kg);

  perform erp._sync_party_scrap_credit_status(p_credit_id);
end;
$$;


ALTER FUNCTION "erp"."_consume_party_scrap_credit"("p_credit_id" "uuid", "p_allocated_kg" numeric, "p_scrap_trade_id" "uuid", "p_obligation_id" "uuid") OWNER TO "postgres";

--
-- Name: _create_scrap_lot_from_factory_dispatch("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_create_scrap_lot_from_factory_dispatch"("p_dispatch_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.factory_scrap_dispatches%rowtype;
  v_rate numeric;
  v_lot_no text;
  v_suffix text;
begin
  perform erp._purge_orphan_scrap_payable_lots();

  select * into v_doc
  from erp.factory_scrap_dispatches
  where id = p_dispatch_id
    and status = 'posted'
    and mode = 'toll';

  if not found then return; end if;
  if coalesce(v_doc.net_weight, 0) <= 0 then return; end if;
  if v_doc.dest_party_id is null then return; end if;

  if exists (
    select 1 from erp.scrap_payable_lots l
    where l.source_doc_type = 'factory_scrap_dispatch' and l.source_doc_id = p_dispatch_id
  ) then
    return;
  end if;

  v_rate := round(
    coalesce(nullif(v_doc.unit_rate, 0), nullif(v_doc.amount, 0) / nullif(v_doc.net_weight, 0), 0),
    3
  );
  v_lot_no := 'SPL-' || v_doc.dispatch_no;
  v_suffix := left(replace(p_dispatch_id::text, '-', ''), 8);

  if exists (
    select 1 from erp.scrap_payable_lots l
    where l.lot_no = v_lot_no and l.source_doc_id is distinct from p_dispatch_id
  ) then
    v_lot_no := 'SPL-' || v_doc.dispatch_no || '-' || v_suffix;
  end if;

  while exists (select 1 from erp.scrap_payable_lots where lot_no = v_lot_no) loop
    v_lot_no := 'SPL-' || v_doc.dispatch_no || '-' || v_suffix || '-' || floor(random() * 10000)::text;
  end loop;

  insert into erp.scrap_payable_lots (
    lot_no, party_id, source_doc_type, source_doc_id, source_doc_no, lot_date, unit_rate, original_kg, allocated_kg, status
  ) values (
    v_lot_no, v_doc.dest_party_id, 'factory_scrap_dispatch', v_doc.id, v_doc.dispatch_no,
    v_doc.dispatch_date, v_rate, v_doc.net_weight, 0, 'open'
  )
  on conflict (source_doc_type, source_doc_id, party_id, unit_rate) do update set
    lot_no = excluded.lot_no,
    original_kg = excluded.original_kg,
    lot_date = excluded.lot_date,
    unit_rate = excluded.unit_rate;
end;
$$;


ALTER FUNCTION "erp"."_create_scrap_lot_from_factory_dispatch"("p_dispatch_id" "uuid") OWNER TO "postgres";

--
-- Name: _create_scrap_lot_from_trade("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_create_scrap_lot_from_trade"("p_trade_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_trades%rowtype;
  v_rate numeric;
  v_lot_no text;
  v_suffix text;
begin
  perform erp._purge_orphan_scrap_payable_lots();

  select * into v_doc from erp.scrap_trades where id = p_trade_id and status = 'posted';
  if not found then
    return;
  end if;

  if exists (
    select 1
    from erp.scrap_payable_lots l
    where l.source_doc_type = 'scrap_trade'
      and l.source_doc_id = p_trade_id
  ) then
    return;
  end if;

  v_rate := round(
    coalesce(nullif(v_doc.amount, 0) / nullif(v_doc.net_weight, 0), nullif(v_doc.unit_rate, 0), 0),
    3
  );
  v_lot_no := 'SPL-' || v_doc.trade_no;
  v_suffix := left(replace(p_trade_id::text, '-', ''), 8);

  if exists (
    select 1
    from erp.scrap_payable_lots l
    where l.lot_no = v_lot_no
      and l.source_doc_id is distinct from p_trade_id
  ) then
    v_lot_no := 'SPL-' || v_doc.trade_no || '-' || v_suffix;
  end if;

  while exists (select 1 from erp.scrap_payable_lots where lot_no = v_lot_no) loop
    v_lot_no := 'SPL-' || v_doc.trade_no || '-' || v_suffix || '-' || floor(random() * 10000)::text;
  end loop;

  insert into erp.scrap_payable_lots (
    lot_no, party_id, source_doc_type, source_doc_id, source_doc_no, lot_date, unit_rate, original_kg, allocated_kg, status
  ) values (
    v_lot_no,
    v_doc.dest_party_id,
    'scrap_trade',
    v_doc.id,
    v_doc.trade_no,
    v_doc.trade_date,
    v_rate,
    v_doc.net_weight,
    0,
    'open'
  )
  on conflict (source_doc_type, source_doc_id, party_id, unit_rate) do update set
    lot_no = excluded.lot_no,
    original_kg = excluded.original_kg,
    lot_date = excluded.lot_date,
    unit_rate = excluded.unit_rate;
end;
$$;


ALTER FUNCTION "erp"."_create_scrap_lot_from_trade"("p_trade_id" "uuid") OWNER TO "postgres";

--
-- Name: _create_scrap_receivable_obligation("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_create_scrap_receivable_obligation"("p_sales_invoice_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_invoices%rowtype;
  v_kg numeric;
  v_obl_id uuid;
  v_obl_no text;
begin
  select * into v_doc from erp.sales_invoices where id = p_sales_invoice_id;
  if not found then return null; end if;
  if coalesce(v_doc.sale_mode, 'direct') <> 'premium' then return null; end if;
  if coalesce(v_doc.ref_scrap_rate, 0) <= 0 then return null; end if;

  v_kg := erp._premium_invoice_total_kg(p_sales_invoice_id);
  if v_kg <= 0 then return null; end if;

  select id into v_obl_id
  from erp.scrap_receivable_obligations
  where sales_invoice_id = p_sales_invoice_id;

  if v_obl_id is not null then
    update erp.scrap_receivable_obligations
    set
      party_id = v_doc.party_id,
      sales_invoice_no = v_doc.invoice_no,
      invoice_date = v_doc.invoice_date,
      ref_scrap_rate = v_doc.ref_scrap_rate,
      expected_kg = v_kg,
      obligation_source = 'invoice'
    where id = v_obl_id;
    perform erp._sync_scrap_obligation_status(v_obl_id);
    return v_obl_id;
  end if;

  v_obl_no := 'SRO-' || v_doc.invoice_no;

  insert into erp.scrap_receivable_obligations (
    obligation_no, party_id, sales_invoice_id, sales_invoice_no, invoice_date,
    ref_scrap_rate, expected_kg, received_kg, status, obligation_source
  ) values (
    v_obl_no, v_doc.party_id, v_doc.id, v_doc.invoice_no, v_doc.invoice_date,
    v_doc.ref_scrap_rate, v_kg, 0, 'open', 'invoice'
  ) returning id into v_obl_id;

  update erp.sales_invoices set premium_total_kg = v_kg where id = p_sales_invoice_id;

  return v_obl_id;
end;
$$;


ALTER FUNCTION "erp"."_create_scrap_receivable_obligation"("p_sales_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _delete_opening_scrap_obligation("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_delete_opening_scrap_obligation"("p_obligation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_obl erp.scrap_receivable_obligations%rowtype;
begin
  select * into v_obl
  from erp.scrap_receivable_obligations
  where id = p_obligation_id
    and obligation_source = 'opening'
  for update;

  if not found then
    return;
  end if;

  if coalesce(v_obl.received_kg, 0) > 0.001 then
    raise exception 'Cannot remove opening scrap obligation %: % kg already received',
      v_obl.obligation_no, v_obl.received_kg;
  end if;

  delete from erp.scrap_receipts
  where obligation_id = v_obl.id
    and status = 'draft';

  delete from erp.scrap_receivable_obligations
  where id = v_obl.id;
end;
$$;


ALTER FUNCTION "erp"."_delete_opening_scrap_obligation"("p_obligation_id" "uuid") OWNER TO "postgres";

--
-- Name: _display_account_name("text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_display_account_name"("p_code" "text", "p_coa_name" "text", "p_line_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_coa text := nullif(trim(coalesce(p_coa_name, '')), '');
  v_line text := nullif(trim(coalesce(p_line_name, '')), '');
  v_code text := trim(coalesce(p_code, ''));
begin
  if v_coa is not null and v_coa <> v_code then
    return v_coa;
  end if;
  if v_line is not null and v_line <> v_code then
    return v_line;
  end if;
  if v_coa is not null then
    return v_coa;
  end if;
  if v_line is not null then
    return v_line;
  end if;
  return v_code;
end;
$$;


ALTER FUNCTION "erp"."_display_account_name"("p_code" "text", "p_coa_name" "text", "p_line_name" "text") OWNER TO "postgres";

--
-- Name: _drawing_base_rate("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_drawing_base_rate"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce((
    select s.base_rate_pkr
    from erp.drawing_labor_settings s
    where s.is_active = true
      and s.effective_from <= coalesce(p_as_of, current_date)
    order by s.effective_from desc
    limit 1
  ), 12)::numeric;
$$;


ALTER FUNCTION "erp"."_drawing_base_rate"("p_as_of" "date") OWNER TO "postgres";

--
-- Name: _drawing_machine_input_kg("uuid", "date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_drawing_machine_input_kg"("p_machine_id" "uuid", "p_from" "date", "p_to" "date") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$ with bounds as (select coalesce(p_from, '1900-01-01'::date) as dt_from, coalesce(p_to, current_date) as dt_to), machine_scrap as (select coalesce(sum(fsl.net_weight), 0)::numeric as kg from erp.factory_scrap_dispatch_lines fsl join erp.factory_scrap_dispatches fs on fs.id = fsl.dispatch_id cross join bounds b where fs.status = 'posted' and fsl.department = 'drawing' and fsl.machine_id = p_machine_id and fs.dispatch_date between b.dt_from and b.dt_to), dept_scrap as (select erp._mtd_drawing_scrap_kg((select dt_from from bounds), (select dt_to from bounds)) as kg), wire8_landed as (select erp._mtd_wire8_landed_kg((select dt_from from bounds), (select dt_to from bounds)) as kg) select case when (select kg from dept_scrap) > 0 then (select kg from wire8_landed) * (select kg from machine_scrap) / (select kg from dept_scrap) when (select kg from machine_scrap) > 0 then (select kg from wire8_landed) else 0::numeric end; $$;


ALTER FUNCTION "erp"."_drawing_machine_input_kg"("p_machine_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";

