-- Name: _effective_line_unit_count("uuid", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_effective_line_unit_count"("p_item_id" "uuid", "p_unit_count" numeric) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case
    when coalesce(i.inventory_group, '') in ('enameled', 'strip', 'copper_wire', 'raw_material')
      or (coalesce(i.inventory_group, '') = 'chemicals' and coalesce(i.item_type, '') ilike '%varnish%')
    then greatest(coalesce(p_unit_count, 0), 0)
    else 0
  end
  from erp.items i
  where i.id = p_item_id;
$$;


