-- Name: _enqueue_pending_if_needed("text", "text", "uuid", "uuid", "text", integer, "uuid", "uuid", "uuid", numeric, "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_enqueue_pending_if_needed"("p_rate_status" "text", "p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_source_line_id" "uuid", "p_source_doc_no" "text", "p_line_seq" integer, "p_party_id" "uuid", "p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_original_posting_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if coalesce(p_rate_status, 'fixed') <> 'pending' then
    return;
  end if;
  perform erp._enqueue_pending_rate_item(
    p_source_doc_type, p_source_doc_id, p_source_line_id, p_source_doc_no, p_line_seq,
    p_party_id, p_item_id, p_warehouse_id, p_qty, p_original_posting_date
  );
end;
$$;


ALTER FUNCTION "erp"."_enqueue_pending_if_needed"("p_rate_status" "text", "p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_source_line_id" "uuid", "p_source_doc_no" "text", "p_line_seq" integer, "p_party_id" "uuid", "p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_original_posting_date" "date") OWNER TO "postgres";

--
-- Name: _enqueue_pending_rate_item("text", "uuid", "uuid", "text", integer, "uuid", "uuid", "uuid", numeric, "date", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_enqueue_pending_rate_item"("p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_source_line_id" "uuid", "p_source_doc_no" "text", "p_line_seq" integer, "p_party_id" "uuid", "p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_posting_date" "date", "p_pending_reason" "text" DEFAULT 'rate'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_reason text := coalesce(nullif(trim(p_pending_reason), ''), 'rate');
begin
  if v_reason not in ('rate', 'tare', 'rate_and_tare') then
    v_reason := 'rate';
  end if;

  insert into erp.pending_rate_items (
    source_doc_type, source_doc_id, source_line_id, source_doc_no, line_seq,
    party_id, item_id, warehouse_id, qty, original_posting_date, status, pending_reason
  ) values (
    p_source_doc_type, p_source_doc_id, p_source_line_id, p_source_doc_no, coalesce(p_line_seq, 1),
    p_party_id, p_item_id, p_warehouse_id, p_qty, p_posting_date, 'open', v_reason
  )
  on conflict do nothing
  returning id into v_id;

  if v_id is null then
    select pri.id into v_id
    from erp.pending_rate_items pri
    where pri.source_doc_type = p_source_doc_type
      and (
        (p_source_line_id is not null and pri.source_line_id = p_source_line_id)
        or (p_source_line_id is null and pri.source_doc_id = p_source_doc_id and pri.source_doc_type = 'scrap_trade')
      )
      and pri.status = 'open'
    limit 1;

    if v_id is not null then
      update erp.pending_rate_items
      set pending_reason = v_reason
      where id = v_id;
    end if;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "erp"."_enqueue_pending_rate_item"("p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_source_line_id" "uuid", "p_source_doc_no" "text", "p_line_seq" integer, "p_party_id" "uuid", "p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_posting_date" "date", "p_pending_reason" "text") OWNER TO "postgres";

