-- Name: _ensure_supplies_restock_gl_trigger(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ensure_supplies_restock_gl_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if new.source_doc_type = 'supplies_restock'
     and new.movement_type = 'adjustment_in'
     and new.source_doc_id is not null
     and coalesce(new.value_amount, 0) > 0 then
    perform erp._sync_supplies_restock_gl(
      new.source_doc_id,
      new.posting_date,
      new.value_amount,
      coalesce(nullif(trim(new.reference_no), ''), 'Supplies restock')
    );
  end if;
  return new;
end;
$$;


