--
-- Name: _force_delete_scrap_receipt_row("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_force_delete_scrap_receipt_row"("p_receipt_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je_ids uuid[];
begin
  if not exists (select 1 from erp.scrap_receipts where id = p_receipt_id) then
    return;
  end if;

  delete from erp.inventory_movements
  where source_doc_type = 'scrap_receipt' and source_doc_id = p_receipt_id;

  select coalesce(array_agg(id), '{}') into v_je_ids
  from erp.journal_entries
  where source_doc_type = 'scrap_receipt' and source_doc_id = p_receipt_id;

  if coalesce(array_length(v_je_ids, 1), 0) > 0 then
    delete from erp.journal_lines where journal_entry_id = any(v_je_ids);
    delete from erp.journal_entries where id = any(v_je_ids);
  end if;

  delete from erp.scrap_receipts where id = p_receipt_id;
end;
$$;


ALTER FUNCTION "erp"."_force_delete_scrap_receipt_row"("p_receipt_id" "uuid") OWNER TO "postgres";

--
-- Name: _freeze_factory_scrap_dispatch_posted(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_freeze_factory_scrap_dispatch_posted"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if current_user = 'authenticated' and coalesce(old.status, '') = 'posted' then
    raise exception 'posted factory scrap dispatch cannot be edited directly; unpost first'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "erp"."_freeze_factory_scrap_dispatch_posted"() OWNER TO "postgres";

--
-- Name: _freeze_pending_rate_status(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_freeze_pending_rate_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if current_user = 'authenticated'
     and coalesce(old.status, '') = 'fixed'
     and coalesce(new.status, '') <> 'fixed' then
    raise exception 'a fixed rate item is immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "erp"."_freeze_pending_rate_status"() OWNER TO "postgres";

--
-- Name: _freeze_posting_status(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_freeze_posting_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  -- Only guard direct end-user writes. SECURITY DEFINER RPCs execute as the function
  -- owner, so current_user is not 'authenticated' and legitimate transitions pass.
  if current_user = 'authenticated'
     and coalesce(old.posting_status, '') = 'posted'
     and coalesce(new.posting_status, '') <> 'posted' then
    raise exception 'posted documents cannot be reverted to draft directly; use the void/delete workflow'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "erp"."_freeze_posting_status"() OWNER TO "postgres";

--
-- Name: _fulfill_scrap_obligation_on_trade("uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_fulfill_scrap_obligation_on_trade"("p_trade_id" "uuid", "p_obligation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_trades%rowtype;
  v_receipt_id uuid;
begin
  select * into v_doc from erp.scrap_trades where id = p_trade_id;
  if not found then raise exception 'scrap trade not found'; end if;

  select r.id into v_receipt_id
  from erp.scrap_receipts r
  where r.obligation_id = p_obligation_id
    and r.status = 'draft'
    and r.party_id = v_doc.source_party_id
  order by r.created_at desc
  limit 1;

  perform erp._apply_scrap_obligation_kg(p_trade_id, p_obligation_id, v_doc.net_weight, v_receipt_id);
end;
$$;


ALTER FUNCTION "erp"."_fulfill_scrap_obligation_on_trade"("p_trade_id" "uuid", "p_obligation_id" "uuid") OWNER TO "postgres";

--
-- Name: _guard_order_line_qty(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_guard_order_line_qty"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if tg_table_name = 'sales_order_lines' then
    if new.qty_ordered < coalesce(new.qty_fulfilled, 0) then
      raise exception 'qty_ordered cannot be less than qty_fulfilled';
    end if;
  elsif tg_table_name = 'purchase_order_lines' then
    if new.qty_ordered < coalesce(new.qty_received, 0) then
      raise exception 'qty_ordered cannot be less than qty_received';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "erp"."_guard_order_line_qty"() OWNER TO "postgres";

--
-- Name: _hard_delete_clear_doc_side_effects("text", "uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_hard_delete_clear_doc_side_effects"("p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_ledger_table" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  perform erp._hard_delete_clear_journals(p_source_doc_type, p_source_doc_id);

  delete from erp.inventory_movements
  where source_doc_type = p_source_doc_type and source_doc_id = p_source_doc_id;

  if p_ledger_table = 'ar' then
    delete from erp.ar_documents
    where source_doc_type = p_source_doc_type and source_doc_id = p_source_doc_id;
  elsif p_ledger_table = 'ap' then
    delete from erp.ap_documents
    where source_doc_type = p_source_doc_type and source_doc_id = p_source_doc_id;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_hard_delete_clear_doc_side_effects"("p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_ledger_table" "text") OWNER TO "postgres";

--
-- Name: _hard_delete_clear_journals("text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_hard_delete_clear_journals"("p_source_doc_type" "text", "p_source_doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je_ids uuid[];
begin
  select coalesce(array_agg(id), '{}') into v_je_ids
  from erp.journal_entries
  where source_doc_type = p_source_doc_type and source_doc_id = p_source_doc_id;

  if coalesce(array_length(v_je_ids, 1), 0) = 0 then
    return;
  end if;

  delete from erp.journal_lines where journal_entry_id = any(v_je_ids);
  delete from erp.journal_entries where id = any(v_je_ids);
end;
$$;


ALTER FUNCTION "erp"."_hard_delete_clear_journals"("p_source_doc_type" "text", "p_source_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: _hard_delete_premium_scrap_for_sales_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_hard_delete_premium_scrap_for_sales_invoice"("p_sales_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_obl record;
  v_receipt_id uuid;
  v_invoice_no text;
  v_hd jsonb;
begin
  if to_regclass('erp.scrap_receivable_obligations') is null then
    return;
  end if;

  select invoice_no into v_invoice_no
  from erp.sales_invoices where id = p_sales_invoice_id;

  for v_obl in
    select o.id
    from erp.scrap_receivable_obligations o
    where o.sales_invoice_id = p_sales_invoice_id
       or (v_invoice_no is not null and o.sales_invoice_no = v_invoice_no)
  loop
    for v_receipt_id in
      select r.id from erp.scrap_receipts r where r.obligation_id = v_obl.id
    loop
      begin
        v_hd := erp.hard_delete_scrap_receipt(v_receipt_id);
        if coalesce((v_hd->>'ok')::boolean, false) is not true then
          perform erp._force_delete_scrap_receipt_row(v_receipt_id);
        end if;
      exception when others then
        perform erp._force_delete_scrap_receipt_row(v_receipt_id);
      end;
      if exists (select 1 from erp.scrap_receipts where id = v_receipt_id) then
        perform erp._force_delete_scrap_receipt_row(v_receipt_id);
      end if;
    end loop;
    delete from erp.scrap_receivable_obligations where id = v_obl.id;
  end loop;
end;
$$;


ALTER FUNCTION "erp"."_hard_delete_premium_scrap_for_sales_invoice"("p_sales_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _infer_account_type("text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_infer_account_type"("p_code" "text", "p_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(
    nullif(trim(p_type), ''),
    case left(trim(p_code), 1)
      when '1' then 'asset'
      when '2' then 'liability'
      when '3' then 'equity'
      when '4' then 'income'
      when '5' then 'expense'
      when '6' then 'expense'
      when '7' then 'expense'
      else 'unknown'
    end
  );
$$;


ALTER FUNCTION "erp"."_infer_account_type"("p_code" "text", "p_type" "text") OWNER TO "postgres";

--
-- Name: _infer_report_group("text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_infer_report_group"("p_code" "text", "p_type" "text", "p_coa_group" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(
    nullif(trim(p_coa_group), ''),
    case
      when left(trim(coalesce(p_code, '')), 2) = '42' then 'other_income'
      when left(trim(coalesce(p_code, '')), 2) in ('40', '41') then 'operating_revenue'
      when left(trim(coalesce(p_code, '')), 2) in ('50', '51') then 'cogs'
      when left(trim(coalesce(p_code, '')), 2) = '61' then 'selling_expense'
      when left(trim(coalesce(p_code, '')), 2) = '62' then 'admin_expense'
      when left(trim(coalesce(p_code, '')), 2) = '63' then 'factory_overhead'
      when left(trim(coalesce(p_code, '')), 2) in ('70', '71') then 'other_expense'
      else null
    end,
    'other'
  );
$$;


ALTER FUNCTION "erp"."_infer_report_group"("p_code" "text", "p_type" "text", "p_coa_group" "text") OWNER TO "postgres";

--
-- Name: _insert_je_line("uuid", integer, "text", "uuid", numeric, numeric, "text"); Type: FUNCTION; Schema: erp; Owner: postgres
