CREATE FUNCTION "erp"."_insert_je_line"("p_je_id" "uuid", "p_line_no" integer, "p_account_code" "text", "p_party_id" "uuid", "p_debit" numeric, "p_credit" numeric, "p_desc" "text") RETURNS "void"
