begin
  select name into v_name from erp.coa_accounts where code = p_account_code;
  insert into erp.journal_lines (
    journal_entry_id, line_no, account_code, account_name, party_id, debit_amount, credit_amount, line_description
  ) values (
    p_je_id, p_line_no, p_account_code, coalesce(v_name, p_account_code), p_party_id, p_debit, p_credit, p_desc
  );
end;
$$;


