--
-- Name: _inventory_gl_account_for_item("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_inventory_gl_account_for_item"("p_item_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_section text;
  v_code text;
begin
  v_section := erp._item_inventory_section(p_item_id);
  if v_section = 'varnish' then
    v_code := erp._lookup_posting_account('opening_stock', 'inventory_varnish');
    return coalesce(v_code, '12500');
  elsif v_section in ('fg_enameled', 'fg_copper_wire') then
    v_code := erp._lookup_posting_account('opening_stock', 'inventory_fg');
    if v_code is null then
      v_code := erp._lookup_posting_account('production_batch', 'inventory_fg');
    end if;
    return coalesce(v_code, '12301');
  elsif v_section = 'rm_scrap' then
    v_code := erp._lookup_posting_account('scrap_trade', 'inventory');
    return coalesce(v_code, '12101');
  else
    -- rm_wire8, rm_rod, packing, other
    return erp._resolve_posting_account('opening_stock', 'inventory');
  end if;
end;
$$;


ALTER FUNCTION "erp"."_inventory_gl_account_for_item"("p_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _inventory_group_top_category("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_inventory_group_top_category"("p_group" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case p_group
    when 'enameled' then 'Finished Goods'
    when 'strip' then 'Finished Goods'
    when 'copper_wire' then 'Finished Goods'
    when 'raw_material' then 'Raw Material'
    when 'packing_material' then 'Packing Material'
    when 'chemicals' then 'Chemicals'
    else null end;
$$;


ALTER FUNCTION "erp"."_inventory_group_top_category"("p_group" "text") OWNER TO "postgres";

--
-- Name: _inventory_group_warehouse_type("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_inventory_group_warehouse_type"("p_group" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case p_group
    when 'enameled' then 'finished_goods'
    when 'strip' then 'finished_goods'
    when 'copper_wire' then 'finished_goods'
    when 'raw_material' then 'raw_material'
    when 'packing_material' then 'packing_material'
    when 'chemicals' then 'varnish'
    else null end;
$$;


ALTER FUNCTION "erp"."_inventory_group_warehouse_type"("p_group" "text") OWNER TO "postgres";

--
-- Name: _inventory_movement_is_rate_pending("text", "uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_inventory_movement_is_rate_pending"("p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_source_line_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if p_source_doc_type = 'purchase_invoice' then
    return exists (
      select 1 from erp.purchase_invoice_lines l
      where l.id = p_source_line_id
        and l.purchase_invoice_id = p_source_doc_id
        and coalesce(l.rate_status, 'fixed') = 'pending'
    );
  elsif p_source_doc_type = 'sales_return' then
    return exists (
      select 1 from erp.sales_return_lines l
      where l.id = p_source_line_id
        and l.sales_return_id = p_source_doc_id
        and coalesce(l.rate_status, 'fixed') = 'pending'
    );
  elsif p_source_doc_type = 'scrap_trade' then
    return exists (
      select 1 from erp.scrap_trades st
      where st.id = p_source_doc_id
        and coalesce(st.rate_status, 'fixed') = 'pending'
    );
  end if;
  return false;
end;
$$;


ALTER FUNCTION "erp"."_inventory_movement_is_rate_pending"("p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_source_line_id" "uuid") OWNER TO "postgres";

--
-- Name: _inventory_on_hand("uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_inventory_on_hand"("p_item_id" "uuid", "p_warehouse_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(sum(coalesce(im.qty_in, 0) - coalesce(im.qty_out, 0)), 0) from erp.inventory_movements im
  where im.item_id = p_item_id and im.warehouse_id = p_warehouse_id;
$$;


