--
-- Name: _inventory_provisional_receipt_unit_cost("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_inventory_provisional_receipt_unit_cost"("p_mov_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_mov erp.inventory_movements%rowtype;
  v_rate numeric := 0;
begin
  select * into v_mov
  from erp.inventory_movements
  where id = p_mov_id;
  if not found or coalesce(v_mov.qty_in, 0) <= 0 then
    return 0;
  end if;

  -- Prefer the latest explicit inbound source rate. The running WAC can already
  -- be distorted by prior zero-cost receipts or PAC-stamped issues; using it
  -- first would compound the contamination.
  select coalesce(
    nullif(round(im.value_amount / nullif(im.qty_in, 0), 6), 0),
    nullif(im.unit_cost, 0)
  )
  into v_rate
  from erp.inventory_movements im
  where im.item_id = v_mov.item_id
    and im.warehouse_id = v_mov.warehouse_id
    and coalesce(im.qty_in, 0) > 0
    and (coalesce(im.value_amount, 0) > 0 or coalesce(im.unit_cost, 0) > 0)
    and (
      im.posting_date < v_mov.posting_date
      or (im.posting_date = v_mov.posting_date and im.created_at < v_mov.created_at)
      or (
        im.posting_date = v_mov.posting_date
        and im.created_at = v_mov.created_at
        and im.id < v_mov.id
      )
    )
  order by im.posting_date desc, im.created_at desc, im.id desc
  limit 1;

  if coalesce(v_rate, 0) <= 0 then
    v_rate := erp._inventory_wac_before_movement(v_mov.id);
  end if;

  if coalesce(v_rate, 0) <= 0 then
    select coalesce(
      nullif(round(im.value_amount / nullif(im.qty_in, 0), 6), 0),
      nullif(im.unit_cost, 0)
    )
    into v_rate
    from erp.inventory_movements im
    where im.item_id = v_mov.item_id
      and coalesce(im.qty_in, 0) > 0
      and (coalesce(im.value_amount, 0) > 0 or coalesce(im.unit_cost, 0) > 0)
      and im.posting_date <= v_mov.posting_date
    order by im.posting_date desc, im.created_at desc, im.id desc
    limit 1;
  end if;

  if coalesce(v_rate, 0) <= 0 then
    select coalesce(nullif(i.standard_cost, 0), 0)
    into v_rate
    from erp.items i
    where i.id = v_mov.item_id;
  end if;

  return greatest(coalesce(v_rate, 0), 0);
end;
$$;


ALTER FUNCTION "erp"."_inventory_provisional_receipt_unit_cost"("p_mov_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "_inventory_provisional_receipt_unit_cost"("p_mov_id" "uuid"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_inventory_provisional_receipt_unit_cost"("p_mov_id" "uuid") IS 'Fallback for a zero-valued pending-rate receipt: prior explicit inbound rate, prior WAC, item-wide inbound, then item standard cost.';


--
-- Name: _inventory_replay_current_wac("uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_inventory_replay_current_wac"("p_item_id" "uuid", "p_warehouse_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(s.avg_unit_cost, 0)
  from erp._inventory_replay_state(p_item_id, p_warehouse_id, null) s;
$$;


