--
-- Name: _inventory_replay_state("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_inventory_replay_state"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_before_movement_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("on_hand_qty" numeric, "stock_value" numeric, "avg_unit_cost" numeric, "copper_unit_cost" numeric, "varnish_unit_cost" numeric, "packing_unit_cost" numeric, "oh_unit_cost" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_anchor erp.inventory_movements%rowtype;
  v_rec record;
  v_qty numeric := 0;
  v_value numeric := 0;
  v_wac numeric := 0;
  v_last_valid_wac numeric := 0;
  v_qty_after numeric;
  v_in_qty numeric;
  v_out_qty numeric;
  v_in_value numeric;
  v_in_rate numeric;
  v_out_rate numeric;
  v_c_unit numeric := 0;
  v_v_unit numeric := 0;
  v_p_unit numeric := 0;
  v_o_unit numeric := 0;
  v_c_value numeric := 0;
  v_v_value numeric := 0;
  v_p_value numeric := 0;
  v_o_value numeric := 0;
  v_c_in numeric;
  v_v_in numeric;
  v_p_in numeric;
  v_o_in numeric;
  v_c_out numeric;
  v_v_out numeric;
  v_p_out numeric;
  v_o_out numeric;
  v_use_stamp boolean;
begin
  if p_item_id is null or p_warehouse_id is null then
    return query select 0::numeric, 0::numeric, 0::numeric,
      0::numeric, 0::numeric, 0::numeric, 0::numeric;
    return;
  end if;

  if p_before_movement_id is not null then
    select *
    into v_anchor
    from erp.inventory_movements
    where id = p_before_movement_id
      and item_id = p_item_id
      and warehouse_id = p_warehouse_id;

    if not found then
      return query select 0::numeric, 0::numeric, 0::numeric,
        0::numeric, 0::numeric, 0::numeric, 0::numeric;
      return;
    end if;
  end if;

  for v_rec in
    select im.*
    from erp.inventory_movements im
    where im.item_id = p_item_id
      and im.warehouse_id = p_warehouse_id
      and (
        p_before_movement_id is null
        or im.posting_date < v_anchor.posting_date
        or (im.posting_date = v_anchor.posting_date and im.created_at < v_anchor.created_at)
        or (
          im.posting_date = v_anchor.posting_date
          and im.created_at = v_anchor.created_at
          and im.id < v_anchor.id
        )
      )
    order by im.posting_date, im.created_at, im.id
  loop
    v_in_qty := greatest(coalesce(v_rec.qty_in, 0), 0);
    v_out_qty := greatest(coalesce(v_rec.qty_out, 0), 0);

    if v_in_qty > 0 then
      v_in_value := coalesce(
        nullif(v_rec.value_amount, 0),
        nullif(round(v_in_qty * coalesce(v_rec.unit_cost, 0), 3), 0),
        round(v_in_qty * coalesce(nullif(v_wac, 0), v_last_valid_wac, 0), 3),
        0
      );
      v_in_rate := coalesce(
        nullif(round(v_in_value / nullif(v_in_qty, 0), 6), 0),
        nullif(v_rec.unit_cost, 0),
        nullif(v_wac, 0),
        nullif(v_last_valid_wac, 0),
        0
      );
      v_c_in := coalesce(v_rec.cost_copper, 0);
      v_v_in := coalesce(v_rec.cost_varnish, 0);
      v_p_in := coalesce(v_rec.cost_packing, 0);
      v_o_in := coalesce(v_rec.cost_oh, 0);
      v_qty_after := v_qty + v_in_qty;

      if v_qty > 0 then
        v_value := v_value + v_in_value;
        v_c_value := round(v_qty * v_c_unit, 3) + v_c_in;
        v_v_value := round(v_qty * v_v_unit, 3) + v_v_in;
        v_p_value := round(v_qty * v_p_unit, 3) + v_p_in;
        v_o_value := round(v_qty * v_o_unit, 3) + v_o_in;
        v_qty := v_qty_after;

        if v_qty > 0 then
          v_wac := round(v_value / nullif(v_qty, 0), 6);
          if v_wac > 0 then v_last_valid_wac := v_wac; end if;
          v_c_unit := round(v_c_value / nullif(v_qty, 0), 6);
          v_v_unit := round(v_v_value / nullif(v_qty, 0), 6);
          v_p_unit := round(v_p_value / nullif(v_qty, 0), 6);
          v_o_unit := round(v_o_value / nullif(v_qty, 0), 6);
        end if;
      elsif v_qty_after > 0 then
        -- Clear a prior deficit at the retained WAC; only the positive remainder
        -- is valued at this receipt's rate/components.
        v_qty := v_qty_after;
        if v_in_rate > 0 then
          v_wac := v_in_rate;
          v_last_valid_wac := v_wac;
        else
          v_wac := v_last_valid_wac;
        end if;
        v_value := round(v_qty * v_wac, 3);
        v_c_unit := round(v_c_in / nullif(v_in_qty, 0), 6);
        v_v_unit := round(v_v_in / nullif(v_in_qty, 0), 6);
        v_p_unit := round(v_p_in / nullif(v_in_qty, 0), 6);
        v_o_unit := round(v_o_in / nullif(v_in_qty, 0), 6);
        v_c_value := round(v_qty * v_c_unit, 3);
        v_v_value := round(v_qty * v_v_unit, 3);
        v_p_value := round(v_qty * v_p_unit, 3);
        v_o_value := round(v_qty * v_o_unit, 3);
      else
        -- Still non-positive: retain, do not recompute.
        v_qty := v_qty_after;
        v_wac := v_last_valid_wac;
        v_value := round(v_qty * v_wac, 3);
        v_c_value := round(v_qty * v_c_unit, 3);
        v_v_value := round(v_qty * v_v_unit, 3);
        v_p_value := round(v_qty * v_p_unit, 3);
        v_o_value := round(v_qty * v_o_unit, 3);
      end if;
    elsif v_out_qty > 0 then
      v_use_stamp := coalesce(v_rec.cost_status, 'provisional')
        in ('period_draft', 'period_final')
        and coalesce(v_rec.unit_cost, 0) > 0;
      v_out_rate := case
        when v_use_stamp then v_rec.unit_cost
        else coalesce(nullif(v_wac, 0), v_last_valid_wac, 0)
      end;
      v_c_out := case
        when v_use_stamp and v_rec.cost_copper is not null then v_rec.cost_copper
        else round(v_out_qty * v_c_unit, 3)
      end;
      v_v_out := case
        when v_use_stamp and v_rec.cost_varnish is not null then v_rec.cost_varnish
        else round(v_out_qty * v_v_unit, 3)
      end;
      v_p_out := case
        when v_use_stamp and v_rec.cost_packing is not null then v_rec.cost_packing
        else round(v_out_qty * v_p_unit, 3)
      end;
      v_o_out := case
        when v_use_stamp and v_rec.cost_oh is not null then v_rec.cost_oh
        else round(v_out_qty * v_o_unit, 3)
      end;

      v_qty_after := v_qty - v_out_qty;
      v_value := v_value - round(v_out_qty * coalesce(v_out_rate, 0), 3);
      v_c_value := round(v_qty * v_c_unit, 3) - v_c_out;
      v_v_value := round(v_qty * v_v_unit, 3) - v_v_out;
      v_p_value := round(v_qty * v_p_unit, 3) - v_p_out;
      v_o_value := round(v_qty * v_o_unit, 3) - v_o_out;
      v_qty := v_qty_after;

      if v_qty > 0 then
        v_wac := round(v_value / nullif(v_qty, 0), 6);
        if v_wac > 0 then v_last_valid_wac := v_wac; end if;
        v_c_unit := round(v_c_value / nullif(v_qty, 0), 6);
        v_v_unit := round(v_v_value / nullif(v_qty, 0), 6);
        v_p_unit := round(v_p_value / nullif(v_qty, 0), 6);
        v_o_unit := round(v_o_value / nullif(v_qty, 0), 6);
      else
        -- Preserve the last valid rates at zero/negative quantity.
        v_wac := v_last_valid_wac;
        v_value := round(v_qty * v_wac, 3);
        v_c_value := round(v_qty * v_c_unit, 3);
        v_v_value := round(v_qty * v_v_unit, 3);
        v_p_value := round(v_qty * v_p_unit, 3);
        v_o_value := round(v_qty * v_o_unit, 3);
      end if;
    end if;
  end loop;

  return query
  select
    coalesce(v_qty, 0),
    coalesce(v_value, 0),
    coalesce(v_wac, 0),
    coalesce(v_c_unit, 0),
    coalesce(v_v_unit, 0),
    coalesce(v_p_unit, 0),
    coalesce(v_o_unit, 0);
end;
$$;


ALTER FUNCTION "erp"."_inventory_replay_state"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_before_movement_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "_inventory_replay_state"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_before_movement_id" "uuid"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_inventory_replay_state"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_before_movement_id" "uuid") IS 'Canonical chronological inventory replay. Preserves last valid WAC/components at non-positive quantity and honors PAC-stamped outbound movements.';


--
-- Name: _inventory_wac_before_movement("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_inventory_wac_before_movement"("p_mov_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(s.avg_unit_cost, 0)
  from erp.inventory_movements m
  cross join lateral erp._inventory_replay_state(m.item_id, m.warehouse_id, m.id) s
  where m.id = p_mov_id;
$$;


ALTER FUNCTION "erp"."_inventory_wac_before_movement"("p_mov_id" "uuid") OWNER TO "postgres";

--
-- Name: _is_enameled_output_item("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_is_enameled_output_item"("p_item_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(
    upper(trim(i.code)) like 'FG-ENW-%'
    or lower(trim(coalesce(i.item_type, ''))) in ('enameled wire', 'enamelled wire'),
    false
  )
  from erp.items i
  where i.id = p_item_id;
$$;


ALTER FUNCTION "erp"."_is_enameled_output_item"("p_item_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "_is_enameled_output_item"("p_item_id" "uuid"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_is_enameled_output_item"("p_item_id" "uuid") IS 'True only for finished enameled-wire items eligible to absorb varnish material cost.';


--
-- Name: _is_party_control_account("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_is_party_control_account"("p_account_code" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(p_account_code, '') in ('11201', '11202', '21101', '21103');
$$;


