--
-- Name: _is_varnish_item("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_is_varnish_item"("p_item_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select exists (
    select 1
    from erp.items i
    where i.id = p_item_id
      and coalesce(i.inventory_group, '') = 'chemicals'
      and coalesce(i.item_type, '') ilike '%varnish%'
  );
$$;


ALTER FUNCTION "erp"."_is_varnish_item"("p_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _is_wire8_item("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_is_wire8_item"("p_item_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select exists (
    select 1
    from erp.items i
    where i.id = p_item_id
      and upper(coalesce(i.code, '')) not like 'RM-CR%'
      and lower(coalesce(i.name, '')) not like '%rod%'
      and (
        -- Item master wire raw-material codes (RM-W8-*)
        (
          upper(i.code) like 'RM-W8%'
          and (
            coalesce(i.size_spec, '') ~* '(no\.?\s*8|#8|wire\s*8|\m8\M)'
            or lower(coalesce(i.name, '')) ~* 'wire\s*(no\.?\s*)?8\b'
            or coalesce(i.size_spec, '') = ''
          )
          and lower(coalesce(i.name, '')) !~* 'no\.?\s*10|#10|wire\s*10|\m10\M'
        )
        or (
          coalesce(i.item_type, '') ilike '%wire%'
          and coalesce(i.inventory_group, '') = 'raw_material'
          and (
            lower(coalesce(i.name, '')) ~* 'wire\s*(no\.?\s*)?8\b'
            or coalesce(i.size_spec, '') ~* '(no\.?\s*8|#8|wire\s*8|\m8\M)'
          )
        )
        or lower(coalesce(i.name, '')) ~* 'wire\s*(no\.?\s*)?8\b'
      )
  );
$$;


ALTER FUNCTION "erp"."_is_wire8_item"("p_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _issue_cost_component("uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_issue_cost_component"("p_item_id" "uuid", "p_warehouse_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_wh_type text;
begin
  select wh_type into v_wh_type
  from erp.warehouses
  where id = p_warehouse_id;

  if coalesce(v_wh_type, '') = 'varnish' then
    return 'varnish';
  end if;
  if coalesce(v_wh_type, '') = 'packing_material' then
    return 'packing';
  end if;
  return 'copper';
end;
$$;


ALTER FUNCTION "erp"."_issue_cost_component"("p_item_id" "uuid", "p_warehouse_id" "uuid") OWNER TO "postgres";

--
-- Name: _item_ids_from_inventory_movements("text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_item_ids_from_inventory_movements"("p_source_doc_type" "text", "p_source_doc_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(array_agg(distinct im.item_id) filter (where im.item_id is not null), '{}'::uuid[])
  from erp.inventory_movements im
  where im.source_doc_type = p_source_doc_type and im.source_doc_id = p_source_doc_id;
$$;


ALTER FUNCTION "erp"."_item_ids_from_inventory_movements"("p_source_doc_type" "text", "p_source_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: _item_inventory_section("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_item_inventory_section"("p_item_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case
    when coalesce(i.inventory_group, '') = 'enameled'
      or coalesce(i.item_type, '') ilike '%enameled%' then 'fg_enameled'
    when coalesce(i.inventory_group, '') = 'strip'
      or coalesce(i.item_type, '') ilike '%strip%' then 'fg_strip'
    when coalesce(i.inventory_group, '') = 'copper_wire'
      or coalesce(i.item_type, '') ilike '%copper wire%' then 'fg_copper_wire'
    when coalesce(i.inventory_group, '') = 'packing_material'
      or coalesce(i.item_type, '') ilike '%packing%' then 'packing'
    when coalesce(i.item_type, '') ilike '%varnish%'
      or coalesce(i.inventory_group, '') = 'chemicals' then 'varnish'
    when coalesce(i.item_type, '') = 'Wire'
      or coalesce(i.name, '') ilike '%wire no 8%' then 'rm_wire8'
    when coalesce(i.item_type, '') = 'Rod'
      or coalesce(i.name, '') ilike '%rod%' then 'rm_rod'
    when coalesce(i.item_type, '') in ('Scrap', 'Scrap Feed')
      or coalesce(i.name, '') ilike '%scrap%' then 'rm_scrap'
    else 'varnish'
  end
  from erp.items i
  where i.id = p_item_id;
$$;


ALTER FUNCTION "erp"."_item_inventory_section"("p_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _item_latest_purchase_unit_cost("uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_item_latest_purchase_unit_cost"("p_item_id" "uuid", "p_warehouse_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(
    (
      select im.unit_cost
      from erp.inventory_movements im
      where im.item_id = p_item_id
        and im.warehouse_id = p_warehouse_id
        and im.movement_type in ('purchase_in', 'opening', 'adjustment_in')
        and coalesce(im.unit_cost, 0) > 0
      order by im.posting_date desc, im.created_at desc, im.id desc
      limit 1
    ),
    (
      select im.unit_cost
      from erp.inventory_movements im
      where im.item_id = p_item_id
        and im.movement_type in ('purchase_in', 'opening', 'adjustment_in')
        and coalesce(im.unit_cost, 0) > 0
      order by im.posting_date desc, im.created_at desc, im.id desc
      limit 1
    ),
    0
  );
$$;


ALTER FUNCTION "erp"."_item_latest_purchase_unit_cost"("p_item_id" "uuid", "p_warehouse_id" "uuid") OWNER TO "postgres";

--
-- Name: _item_product_kind("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_item_product_kind"("p_item_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case
    when coalesce(i.inventory_group, '') = 'enameled'
      or coalesce(i.item_type, '') ilike '%enameled%'
      or coalesce(i.name, '') ilike '%enameled%' then 'enamel'
    when coalesce(i.item_type, '') ilike '%wire%'
      or coalesce(i.name, '') ilike '%wire no 8%'
      or coalesce(i.name, '') ilike '%wire%8%' then 'wire8'
    when coalesce(i.item_type, '') ilike '%rod%'
      or coalesce(i.name, '') ilike '%rod%'
      or coalesce(i.name, '') ilike '%copper rod%' then 'rod'
    when coalesce(i.inventory_group, '') = 'strip' then 'enamel'
    else 'wire8'
  end
  from erp.items i where i.id = p_item_id;
$$;


ALTER FUNCTION "erp"."_item_product_kind"("p_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _item_scrap_kind("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_item_scrap_kind"("p_item_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case
    when coalesce(i.code, '') ilike '%-DRAW%'
      or coalesce(i.size_spec, '') ilike '%drawing%' then 'drawing'
    when coalesce(i.code, '') ilike '%-ENAM%'
      or coalesce(i.size_spec, '') ilike '%enamel%' then 'enamel'
    when coalesce(i.code, '') ilike '%-WS%'
      or coalesce(i.size_spec, '') ilike '%workshop%' then 'workshop'
    else 'feed'
  end
  from erp.items i
  where i.id = p_item_id;
$$;


ALTER FUNCTION "erp"."_item_scrap_kind"("p_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _ledger_is_voided("text", "uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_is_voided"("p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_voucher_no" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    coalesce(p_voucher_no, '') like 'VOID-%'
    or (
      p_source_doc_type = 'sales_return'
      and exists (
        select 1 from erp.sales_returns sr
        where sr.id = p_source_doc_id and sr.return_no ilike 'VOID-%'
      )
    )
    or (
      p_source_doc_type = 'purchase_return'
      and exists (
        select 1 from erp.purchase_returns pr
        where pr.id = p_source_doc_id and pr.return_no ilike 'VOID-%'
      )
    );
$$;


ALTER FUNCTION "erp"."_ledger_is_voided"("p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_voucher_no" "text") OWNER TO "postgres";

--
-- Name: _ledger_is_watta_party_adj_hidden("text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_is_watta_party_adj_hidden"("p_voucher_type" "text", "p_line_description" "text", "p_narration" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select p_voucher_type = 'SALES_INVOICE_ADJ'
    and (
      coalesce(p_line_description, '') ilike 'Watta recalc%'
      or coalesce(p_narration, '') ilike '%Watta matrix recalc%'
    );
$$;


ALTER FUNCTION "erp"."_ledger_is_watta_party_adj_hidden"("p_voucher_type" "text", "p_line_description" "text", "p_narration" "text") OWNER TO "postgres";

--
-- Name: _ledger_line_details("text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_line_details"("p_source_doc_type" "text", "p_source_doc_id" "uuid") RETURNS TABLE("detail_seq" integer, "particulars" "text", "size_spec" "text", "weight_qty" numeric, "unit_rate" numeric, "line_amount" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_si erp.sales_invoices%rowtype;
begin
  if p_source_doc_type = 'scrap_trade' then
    return query
    select
      a.line_seq,
      ('Scrap toll-drop · ' || coalesce(i.name, i.code) || ' · vs ' || o.sales_invoice_no)::text,
      null::text,
      a.allocated_kg,
      coalesce(r.unit_rate, o.ref_scrap_rate),
      round(a.allocated_kg * coalesce(r.unit_rate, o.ref_scrap_rate), 3)
    from erp.scrap_obligation_allocations a
    join erp.scrap_receivable_obligations o on o.id = a.obligation_id
    left join erp.scrap_receipts r on r.id = a.receipt_id
    join erp.scrap_trades st on st.id = a.scrap_trade_id
    join erp.items i on i.id = st.item_id
    where a.scrap_trade_id = p_source_doc_id
    order by a.line_seq;
    if found then return; end if;

    return query
    select sub.detail_seq, sub.particulars, sub.size_spec, sub.weight_qty, sub.unit_rate, sub.line_amount
    from (
      select
        row_number() over (order by r.created_at, r.id)::int as detail_seq,
        ('Scrap toll-drop · ' || coalesce(i.name, i.code) || ' · vs ' || o.sales_invoice_no)::text as particulars,
        null::text as size_spec,
        r.net_weight as weight_qty,
        coalesce(o.ref_scrap_rate, r.unit_rate) as unit_rate,
        round(r.net_weight * coalesce(o.ref_scrap_rate, r.unit_rate), 3) as line_amount
      from erp.scrap_receipts r
      join erp.scrap_receivable_obligations o on o.id = r.obligation_id
      join erp.scrap_trades st on st.id = p_source_doc_id
      join erp.items i on i.id = st.item_id
      where r.scrap_trade_id = p_source_doc_id and coalesce(r.record_metal_movement, true) = false
    ) sub order by sub.detail_seq;
    if found then return; end if;

    return query
    select sub.detail_seq, sub.particulars, sub.size_spec, sub.weight_qty, sub.unit_rate, sub.line_amount
    from (
      select
        row_number() over (order by r.created_at, r.id)::int as detail_seq,
        ('Scrap toll-drop · ' || coalesce(i.name, i.code) || ' · vs ' || o.sales_invoice_no)::text as particulars,
        null::text as size_spec,
        r.net_weight as weight_qty,
        coalesce(o.ref_scrap_rate, r.unit_rate) as unit_rate,
        round(r.net_weight * coalesce(o.ref_scrap_rate, r.unit_rate), 3) as line_amount
      from erp.scrap_receipts r
      join erp.scrap_receivable_obligations o on o.id = r.obligation_id
      join erp.scrap_trades st on st.id = p_source_doc_id
      join erp.items i on i.id = st.item_id
      where r.party_id = st.source_party_id and r.receipt_date = st.trade_date
        and abs(r.net_weight - st.net_weight) < 0.001 and coalesce(r.record_metal_movement, true) = false
    ) sub order by sub.detail_seq;
    if found then return; end if;

    return query
    select
      1,
      case when coalesce(st.rate_status, 'fixed') = 'pending'
        then ('Rate pending · ' || coalesce(i.name, i.code))::text
        else ('Scrap toll-drop · ' || coalesce(i.name, i.code) || coalesce(' · ' || nullif(trim(st.bilty_no), ''), ''))::text
      end,
      null::text,
      st.net_weight,
      case when coalesce(st.rate_status, 'fixed') = 'pending' then null::numeric else st.unit_rate end,
      case when coalesce(st.rate_status, 'fixed') = 'pending' then 0::numeric else round(st.net_weight * st.unit_rate, 3) end
    from erp.scrap_trades st
    join erp.items i on i.id = st.item_id
    where st.id = p_source_doc_id;
    if found then return; end if;

  elsif p_source_doc_type = 'sales_invoice' then
    select * into v_si from erp.sales_invoices where id = p_source_doc_id;
    return query
    select
      l.line_no,
      case when coalesce(l.rate_status, 'fixed') = 'pending'
        then ('Rate pending · ' || coalesce(i.name, i.code) || ' · ' || v_si.invoice_no)::text
        else (coalesce(i.name, i.code) || case when coalesce(v_si.sale_mode, '') = 'premium' and coalesce(v_si.ref_scrap_rate, 0) > 0
          then ' [ref scrap ' || v_si.ref_scrap_rate::text || '+watta ' || coalesce(l.watta_rate, 0)::text || ']'
          else '' end)::text
      end,
      nullif(trim(coalesce(i.size_spec, '')), '')::text,
      coalesce(nullif(l.net_weight, 0), l.qty),
      case when coalesce(l.rate_status, 'fixed') = 'pending' then null::numeric else nullif(l.unit_price, 0) end,
      case when coalesce(l.rate_status, 'fixed') = 'pending' then 0::numeric else l.line_amount end
    from erp.sales_invoice_lines l
    join erp.items i on i.id = l.item_id
    where l.sales_invoice_id = p_source_doc_id
    order by l.line_no;
    if found then return; end if;

  elsif p_source_doc_type = 'purchase_invoice' then
    return query
    select
      l.line_no,
      case when coalesce(l.rate_status, 'fixed') = 'pending'
        then ('Rate pending · ' || coalesce(i.name, i.code) || ' · ' || pi.invoice_no)::text
        else coalesce(i.name, i.code)::text
      end,
      nullif(trim(coalesce(i.size_spec, '')), '')::text,
      coalesce(nullif(l.net_weight, 0), l.qty),
      case when coalesce(l.rate_status, 'fixed') = 'pending' then null::numeric else nullif(l.unit_price, 0) end,
      case when coalesce(l.rate_status, 'fixed') = 'pending' then 0::numeric else l.line_amount end
    from erp.purchase_invoice_lines l
    join erp.items i on i.id = l.item_id
    join erp.purchase_invoices pi on pi.id = l.purchase_invoice_id
    where l.purchase_invoice_id = p_source_doc_id
    order by l.line_no;
    if found then return; end if;

  elsif p_source_doc_type = 'scrap_receipt' then
    return query
    select 1,
      ('Scrap in vs ' || o.sales_invoice_no || ' @ ref ' || o.ref_scrap_rate::text)::text,
      null::text, r.net_weight, coalesce(o.ref_scrap_rate, r.unit_rate),
      round(r.net_weight * coalesce(o.ref_scrap_rate, r.unit_rate), 3)
    from erp.scrap_receipts r
    join erp.scrap_receivable_obligations o on o.id = r.obligation_id
    where r.id = p_source_doc_id;
    if found then return; end if;

  elsif p_source_doc_type = 'sales_return' then
    return query
    select
      l.line_no,
      case when coalesce(l.rate_status, 'fixed') = 'pending'
        then ('Rate pending · ' || coalesce(i.name, i.code))::text
        else coalesce(i.name, i.code)::text
      end,
      nullif(trim(coalesce(i.size_spec, '')), '')::text,
      l.qty,
      case when coalesce(l.rate_status, 'fixed') = 'pending' then null::numeric else nullif(l.unit_price, 0) end,
      case when coalesce(l.rate_status, 'fixed') = 'pending' then 0::numeric else l.line_amount end
    from erp.sales_return_lines l
    join erp.items i on i.id = l.item_id
    where l.sales_return_id = p_source_doc_id
    order by l.line_no;
    if found then return; end if;

  elsif p_source_doc_type = 'purchase_return' then
    return query
    select
      l.line_no,
      case when coalesce(l.rate_status, 'fixed') = 'pending'
        then ('Rate pending · ' || coalesce(i.name, i.code))::text
        else coalesce(i.name, i.code)::text
      end,
      nullif(trim(coalesce(i.size_spec, '')), '')::text,
      l.qty,
      case when coalesce(l.rate_status, 'fixed') = 'pending' then null::numeric else nullif(l.unit_price, 0) end,
      case when coalesce(l.rate_status, 'fixed') = 'pending' then 0::numeric else l.line_amount end
    from erp.purchase_return_lines l
    join erp.items i on i.id = l.item_id
    where l.purchase_return_id = p_source_doc_id
    order by l.line_no;
    if found then return; end if;

  elsif p_source_doc_type = 'payment' then
    return query
    select 1,
      coalesce(nullif(trim(p.remarks), ''), case p.payment_type when 'receipt' then 'Cash receipt' else 'Cash payment' end)::text,
      null::text, null::numeric, null::numeric, p.amount
    from erp.payments p where p.id = p_source_doc_id;
    if found then return; end if;

  elsif p_source_doc_type = 'party_opening' then
    return query select 1, 'Opening balance'::text, null::text, null::numeric, null::numeric, null::numeric;
    return;
  end if;

  return query select 1, null::text, null::text, null::numeric, null::numeric, null::numeric;
end;
$$;


ALTER FUNCTION "erp"."_ledger_line_details"("p_source_doc_type" "text", "p_source_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: _ledger_pending_rate_account_code("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_pending_rate_account_code"("p_source_doc_type" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case p_source_doc_type
    when 'purchase_invoice' then erp._resolve_posting_account('purchase_invoice', 'ap')
    when 'sales_invoice' then erp._resolve_posting_account('sales_invoice', 'ar')
    when 'sales_return' then erp._resolve_posting_account('sales_return', 'ar')
    when 'purchase_return' then erp._resolve_posting_account('purchase_return', 'ap')
    when 'scrap_trade' then erp._resolve_posting_account('scrap_trade', 'ap')
    else null
  end;
$$;


ALTER FUNCTION "erp"."_ledger_pending_rate_account_code"("p_source_doc_type" "text") OWNER TO "postgres";

--
-- Name: _ledger_pending_rate_party_rows("uuid", "date", "date", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_pending_rate_party_rows"("p_party_id" "uuid" DEFAULT NULL::"uuid", "p_from" "date" DEFAULT '1900-01-01'::"date", "p_to" "date" DEFAULT CURRENT_DATE, "p_open_only" boolean DEFAULT false) RETURNS TABLE("party_code" "text", "party_name" "text", "posting_date" "date", "voucher_no" "text", "voucher_type" "text", "source_doc_type" "text", "source_doc_id" "uuid", "source_doc_no" "text", "ref_no" "text", "account_code" "text", "account_name" "text", "line_description" "text", "transaction_description" "text", "narration" "text", "particulars" "text", "size_spec" "text", "weight_qty" numeric, "unit_rate" numeric, "detail_seq" integer, "display_debit" numeric, "display_credit" numeric, "display_delta" numeric, "sort_ts" timestamp with time zone, "posted_at" timestamp with time zone, "posted_by" "uuid", "posted_by_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    p.code::text,
    p.name::text,
    pri.original_posting_date,
    pri.source_doc_no::text,
    erp._ledger_pending_rate_voucher_type(pri.source_doc_type),
    pri.source_doc_type::text,
    pri.source_doc_id,
    pri.source_doc_no::text,
    pri.source_doc_no::text,
    erp._ledger_pending_rate_account_code(pri.source_doc_type),
    coa.name::text,
    erp._pending_reason_label(pri.pending_reason)::text,
    case
      when pri.source_doc_type = 'scrap_trade' then 'Advance scrap (pending)'
      else erp._ledger_pending_rate_txn_description(pri.source_doc_type)
    end::text,
    ('Awaiting fix in Rate Management — ' || erp._pending_reason_label(pri.pending_reason))::text,
    (
      erp._pending_reason_label(pri.pending_reason)
      || ' · '
      || coalesce(i.name, i.code, 'Item')
      || ' · '
      || pri.source_doc_no
      || ' · '
      || pri.qty::text
      || ' kg'
    )::text,
    nullif(trim(coalesce(i.size_spec, '')), '')::text,
    pri.qty,
    null::numeric,
    pri.line_seq,
    0::numeric,
    0::numeric,
    0::numeric,
    (pri.original_posting_date::timestamptz + interval '18 hours'),
    (pri.original_posting_date::timestamptz + interval '18 hours'),
    null::uuid,
    null::text
  from erp.pending_rate_items pri
  join erp.parties p on p.id = pri.party_id
  left join erp.items i on i.id = pri.item_id
  left join erp.coa_accounts coa on coa.code = erp._ledger_pending_rate_account_code(pri.source_doc_type)
  where pri.status = 'open'
    and (p_party_id is null or pri.party_id = p_party_id)
    and (
      p_open_only
      or pri.original_posting_date between p_from and p_to
    );
$$;


ALTER FUNCTION "erp"."_ledger_pending_rate_party_rows"("p_party_id" "uuid", "p_from" "date", "p_to" "date", "p_open_only" boolean) OWNER TO "postgres";

--
-- Name: _ledger_pending_rate_txn_description("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_pending_rate_txn_description"("p_source_doc_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case p_source_doc_type
    when 'purchase_invoice' then 'Purchase invoice (rate pending)'
    when 'sales_invoice' then 'Sales invoice (rate pending)'
    when 'sales_return' then 'Sales return (rate pending)'
    when 'purchase_return' then 'Purchase return (rate pending)'
    when 'scrap_trade' then 'Scrap trade (rate pending)'
    else initcap(replace(coalesce(p_source_doc_type, 'document'), '_', ' ')) || ' (rate pending)'
  end;
$$;


ALTER FUNCTION "erp"."_ledger_pending_rate_txn_description"("p_source_doc_type" "text") OWNER TO "postgres";

--
-- Name: _ledger_pending_rate_voucher_type("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_pending_rate_voucher_type"("p_source_doc_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case p_source_doc_type
    when 'purchase_invoice' then 'PURCHASE_INVOICE'
    when 'sales_invoice' then 'SALES_INVOICE'
    when 'sales_return' then 'SALES_RETURN'
    when 'purchase_return' then 'PURCHASE_RETURN'
    when 'scrap_trade' then 'SCRAP_TRADE'
    else upper(coalesce(p_source_doc_type, 'document'))
  end;
$$;


ALTER FUNCTION "erp"."_ledger_pending_rate_voucher_type"("p_source_doc_type" "text") OWNER TO "postgres";

--
-- Name: _ledger_ref_no("text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_ref_no"("p_source_doc_type" "text", "p_source_doc_no" "text", "p_voucher_no" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    SET "row_security" TO 'off'
    AS $$
  select case
    when p_source_doc_type = 'payment' then
      coalesce(
        (
          select 'p.' || nullif(trim(pay.page_no), '')
          from erp.payments pay
          where pay.payment_no = coalesce(
            nullif(trim(p_source_doc_no), ''),
            nullif(trim(p_voucher_no), '')
          )
          limit 1
        ),
        'p.?'
      )
    when p_source_doc_type = 'party_opening' then
      coalesce(nullif(trim(p_voucher_no), ''), 'OPENING')
    else
      coalesce(nullif(trim(p_source_doc_no), ''), nullif(trim(p_voucher_no), ''))
  end;
$$;


ALTER FUNCTION "erp"."_ledger_ref_no"("p_source_doc_type" "text", "p_source_doc_no" "text", "p_voucher_no" "text") OWNER TO "postgres";

--
-- Name: _ledger_should_expand_details("text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_should_expand_details"("p_voucher_type" "text", "p_source_doc_type" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    (p_voucher_type = 'SALES_INVOICE' and p_source_doc_type = 'sales_invoice')
    or (p_voucher_type = 'PURCHASE_INVOICE' and p_source_doc_type = 'purchase_invoice')
    or (p_voucher_type = 'SALES_RETURN' and p_source_doc_type = 'sales_return')
    or (p_voucher_type = 'PURCHASE_RETURN' and p_source_doc_type = 'purchase_return')
    or p_source_doc_type in ('scrap_trade', 'scrap_receipt');
$$;


ALTER FUNCTION "erp"."_ledger_should_expand_details"("p_voucher_type" "text", "p_source_doc_type" "text") OWNER TO "postgres";

--
-- Name: _ledger_transaction_description("text", "text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_ledger_transaction_description"("p_source_doc_type" "text", "p_voucher_type" "text", "p_line_description" "text", "p_payment_type" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(
    nullif(trim(p_line_description), ''),
    case p_source_doc_type
      when 'sales_invoice' then 'Sales Invoice'
      when 'purchase_invoice' then 'Purchase Invoice'
      when 'sales_return' then 'Sales Return'
      when 'purchase_return' then 'Purchase Return'
      when 'payment' then
        case coalesce(p_payment_type, '')
          when 'receipt' then 'Cash Received'
          else 'Cash Paid'
        end
      when 'party_opening' then 'Opening Balance'
      when 'parchi_instrument' then 'Parchi'
      when 'opening' then 'Opening Balance'
      else coalesce(nullif(trim(p_voucher_type), ''), initcap(replace(p_source_doc_type, '_', ' ')))
    end
  );
$$;


ALTER FUNCTION "erp"."_ledger_transaction_description"("p_source_doc_type" "text", "p_voucher_type" "text", "p_line_description" "text", "p_payment_type" "text") OWNER TO "postgres";

--
-- Name: _lookup_posting_account("text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_lookup_posting_account"("p_doc_type" "text", "p_line_role" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select pam.account_code
  from erp.posting_account_map pam
  where pam.doc_type = p_doc_type
    and pam.line_role = p_line_role
    and pam.is_active = true
    and pam.effective_from <= current_date
  order by pam.effective_from desc
  limit 1;
$$;


ALTER FUNCTION "erp"."_lookup_posting_account"("p_doc_type" "text", "p_line_role" "text") OWNER TO "postgres";

--
-- Name: _machine_scrap_dispatched_kg("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_machine_scrap_dispatched_kg"("p_machine_id" "uuid", "p_item_id" "uuid", "p_exclude_dispatch_id" "uuid" DEFAULT NULL::"uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(sum(fsl.net_weight), 0)::numeric
  from erp.factory_scrap_dispatch_lines fsl
  join erp.factory_scrap_dispatches fs on fs.id = fsl.dispatch_id
  where fs.status = 'posted'
    and fsl.machine_id = p_machine_id
    and fsl.item_id = p_item_id
    and (p_exclude_dispatch_id is null or fs.id <> p_exclude_dispatch_id);
$$;


ALTER FUNCTION "erp"."_machine_scrap_dispatched_kg"("p_machine_id" "uuid", "p_item_id" "uuid", "p_exclude_dispatch_id" "uuid") OWNER TO "postgres";

--
-- Name: _machine_scrap_generated_kg("uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_machine_scrap_generated_kg"("p_machine_id" "uuid", "p_item_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(sum(coalesce(pbl.scrap_weight, pbl.net_weight, 0)), 0)::numeric
  from erp.production_batch_lines pbl
  join erp.production_batches pb on pb.id = pbl.production_batch_id
  where pb.status = 'posted'
    and pbl.line_type = 'scrap'
    and pbl.item_id = p_item_id
    and coalesce(pbl.machine_id, pb.machine_id) = p_machine_id;
$$;


ALTER FUNCTION "erp"."_machine_scrap_generated_kg"("p_machine_id" "uuid", "p_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _machine_scrap_on_hand_kg("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_machine_scrap_on_hand_kg"("p_machine_id" "uuid", "p_item_id" "uuid", "p_exclude_dispatch_id" "uuid" DEFAULT NULL::"uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select greatest(
    erp._machine_scrap_generated_kg(p_machine_id, p_item_id)
      - erp._machine_scrap_dispatched_kg(p_machine_id, p_item_id, p_exclude_dispatch_id),
    0
  );
$$;


ALTER FUNCTION "erp"."_machine_scrap_on_hand_kg"("p_machine_id" "uuid", "p_item_id" "uuid", "p_exclude_dispatch_id" "uuid") OWNER TO "postgres";

--
-- Name: _machine_wastage_limit_pct("text", "text", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_machine_wastage_limit_pct"("p_machine_code" "text", "p_department" "text", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(
    erp._production_standard_num_optional('machine_wastage_pct:' || p_machine_code, p_as_of),
    case coalesce(p_department, '') when 'drawing' then erp._production_standard_num('drawing_wastage_pct', p_as_of) when 'workshop' then erp._production_standard_num('workshop_wastage_pct', p_as_of) when 'enamel' then erp._production_standard_num('enamel_scrap_pct', p_as_of) else 0::numeric end,
    0::numeric
  );
$$;


