--
-- Name: _market_implied_pkr_per_kg(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_market_implied_pkr_per_kg"() RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_settings erp.market_settings%rowtype;
  v_copper numeric;
  v_fx numeric;
  v_manual numeric;
  v_implied numeric;
begin
  select * into v_settings from erp.market_settings where id = 1;

  select m.value into v_manual
  from erp.market_manual_overrides m
  where m.symbol_code = 'LOCAL_SCRAP_PKR_KG'
    and m.effective_from <= current_date
  order by m.effective_from desc
  limit 1;

  if v_manual is not null and v_manual > 0 then
    return round(v_manual, 3);
  end if;

  select q.value into v_copper from erp._market_latest_quote('LME_COPPER_USD_T') q;
  select q.value into v_fx from erp._market_latest_quote('USD_PKR') q;
  v_copper := coalesce(v_copper, 0);
  v_fx := coalesce(v_fx, 0);

  if v_copper <= 0 or v_fx <= 0 then
    return 0;
  end if;

  v_implied := (v_copper / 1000.0) * v_fx * coalesce(v_settings.conversion_factor, 1)
    + coalesce(v_settings.local_premium_pkr, 0);
  return round(v_implied, 3);
end;
$$;


ALTER FUNCTION "erp"."_market_implied_pkr_per_kg"() OWNER TO "postgres";

