    AS $$
  select coalesce(sum(x.kg), 0)::numeric
  from (
    select coalesce(im.qty_in, 0) as kg
    from erp.inventory_movements im
  join erp.items i on i.id = im.item_id
    where im.posting_date between p_from and p_to
      and im.movement_type in ('purchase_in', 'production_receipt')
      and erp._is_wire8_item(im.item_id)
    union all
    select coalesce(pil.net_weight, pil.qty, 0)
    from erp.purchase_invoice_lines pil
    join erp.purchase_invoices pi on pi.id = pil.purchase_invoice_id
    join erp.items i on i.id = pil.item_id
    where pi.posting_status = 'posted'
      and pi.invoice_date between p_from and p_to
      and erp._is_wire8_item(pil.item_id)
  ) x;
$$;


