--
-- Name: _normalize_cogs_components(numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_normalize_cogs_components"("p_total" numeric, "p_copper" numeric, "p_varnish" numeric, "p_packing" numeric, "p_oh" numeric, OUT "o_copper" numeric, OUT "o_varnish" numeric, OUT "o_packing" numeric, OUT "o_oh" numeric, OUT "o_clearing" numeric) RETURNS "record"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_total numeric := round(coalesce(p_total, 0), 3);
  v_copper numeric := coalesce(p_copper, 0);
  v_varnish numeric := coalesce(p_varnish, 0);
  v_packing numeric := coalesce(p_packing, 0);
  v_oh numeric := coalesce(p_oh, 0);
  v_comp numeric;
begin
  o_copper := 0; o_varnish := 0; o_packing := 0; o_oh := 0; o_clearing := 0;
  if v_total <= 0 then return; end if;
  v_copper := greatest(v_copper, 0);
  v_varnish := greatest(v_varnish, 0);
  v_packing := greatest(v_packing, 0);
  v_oh := greatest(v_oh, 0);
  v_comp := v_copper + v_varnish + v_packing + v_oh;
  if v_comp > 0.001 then
    o_copper := round(v_total * v_copper / v_comp, 3);
    o_varnish := round(v_total * v_varnish / v_comp, 3);
    o_packing := round(v_total * v_packing / v_comp, 3);
    o_oh := round(v_total - o_copper - o_varnish - o_packing, 3);
    if o_oh < 0 then
      o_copper := round(o_copper + o_oh, 3); o_oh := 0;
      if o_copper < 0 then
        o_varnish := round(o_varnish + o_copper, 3); o_copper := 0;
        if o_varnish < 0 then
          o_packing := round(o_packing + o_varnish, 3); o_varnish := 0;
          if o_packing < 0 then o_packing := 0; end if;
        end if;
      end if;
    end if;
    o_clearing := round(v_total - o_copper - o_varnish - o_packing - o_oh, 3);
  else
    o_clearing := v_total;
  end if;
  if abs(o_clearing) <= 0.01 and o_clearing <> 0 then
    if o_oh > 0 or o_clearing > 0 then
      o_oh := round(o_oh + o_clearing, 3); o_clearing := 0;
    elsif o_copper > 0 then
      o_copper := round(o_copper + o_clearing, 3); o_clearing := 0;
    end if;
  end if;
  if o_clearing < 0 then
    o_clearing := 0;
    o_oh := round(v_total - o_copper - o_varnish - o_packing, 3);
    if o_oh < 0 then
      o_copper := v_total; o_varnish := 0; o_packing := 0; o_oh := 0;
    end if;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_normalize_cogs_components"("p_total" numeric, "p_copper" numeric, "p_varnish" numeric, "p_packing" numeric, "p_oh" numeric, OUT "o_copper" numeric, OUT "o_varnish" numeric, OUT "o_packing" numeric, OUT "o_oh" numeric, OUT "o_clearing" numeric) OWNER TO "postgres";

--
-- Name: _normalize_valuation_spec_key("text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_normalize_valuation_spec_key"("p_size_spec" "text", "p_name" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $_$
declare
  v text;
  v_thousand text[];
  v_strip text[];
  v_mm text[];
begin
  v := lower(trim(coalesce(nullif(trim(p_size_spec), ''), nullif(trim(p_name), ''), '')));
  if v = '' then return null; end if;
  if v ~ 'swg\s*\d' or v ~ '^\d+(?:\.\d+)?$' then return null; end if;
  if v ~ 'thousand' then
    v_thousand := regexp_match(v, '(\d+)\s*thousand');
    if v_thousand is not null then return v_thousand[1] || '_thousand'; end if;
  end if;
  v_strip := regexp_match(v, '(\d+(?:\.\d+)?)\s*mm\s*[x×]\s*(\d+(?:\.\d+)?)\s*mm');
  if v_strip is not null then
    return replace(v_strip[1], '.', '_') || 'x' || replace(v_strip[2], '.', '_') || '_mm';
  end if;
  v_mm := regexp_match(v, '^(\d+(?:\.\d+)?)\s*mm$');
  if v_mm is not null then return replace(v_mm[1], '.', '_') || '_mm'; end if;
  v := regexp_replace(v, '[^a-z0-9]+', '_', 'g');
  v := trim(both '_' from v);
  return nullif(v, '');
end;
$_$;


ALTER FUNCTION "erp"."_normalize_valuation_spec_key"("p_size_spec" "text", "p_name" "text") OWNER TO "postgres";

--
-- Name: _pac_auto_overhead_amount("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_auto_overhead_amount"("p_start_date" "date", "p_end_date" "date") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0)::numeric(18,3)
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  join erp.coa_accounts ca on ca.code = jl.account_code
  where je.status = 'posted'
    and je.posting_date between p_start_date and p_end_date
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    and (
      ca.report_group in ('factory_overhead', 'conversion_overhead')
      or ca.code in ('51002', '51003', '51004', '51005', '51007', '51008', '51009')
    )
    and ca.code not in (
      '51000', '51001', '51006', '51010', '51011', '51012', '51013',
      '51014', '51999'
    );
$$;


ALTER FUNCTION "erp"."_pac_auto_overhead_amount"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";

--
-- Name: FUNCTION "_pac_auto_overhead_amount"("p_start_date" "date", "p_end_date" "date"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_pac_auto_overhead_amount"("p_start_date" "date", "p_end_date" "date") IS 'Monthly PAC conversion-overhead numerator. Uses the same classified groups and direct factory account whitelist as fn_get_live_conversion_rate.';


--
-- Name: _pac_compute_rm_rates("uuid", "date", "date", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_compute_rm_rates"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_wh_id uuid;
  v_open_qty numeric;
  v_open_val numeric;
  v_rec record;
  v_pac numeric;
  v_purch_qty numeric;
  v_purch_val numeric;
  v_zero_purchases int;
  v_rates jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
begin
  if p_is_draft then
    delete from erp.period_cost_rates where period_id = p_period_id and is_draft = true;
  else
    delete from erp.period_cost_rates where period_id = p_period_id and is_draft = false;
  end if;
  for v_rec in
    select i.id as item_id, i.code, i.inventory_group,
           case
             when i.code like 'RM-W8%' then 'rm_copper'
             when i.code like 'RM-CR%' then 'rm_rod'
             when i.code like 'CHM-VAR%' or coalesce(i.inventory_group,'') in ('chemicals','varnish') then 'rm_varnish'
             when i.code like 'CON-GOT%' or coalesce(i.inventory_group,'') in ('packing_material','consumables') then 'rm_packing'
             else null end as rate_class,
           case
             when i.code like 'RM-W8%' or i.code like 'RM-CR%' then 'raw_material'
             when i.code like 'CHM-VAR%' or coalesce(i.inventory_group,'') in ('chemicals','varnish') then 'varnish'
             when i.code like 'CON-GOT%' or coalesce(i.inventory_group,'') in ('packing_material','consumables') then 'packing_material'
             else null end as wh_type
    from erp.items i
    where i.is_active = true
      and (i.code like 'RM-W8%' or i.code like 'RM-CR%' or i.code like 'CHM-VAR%' or i.code like 'CON-GOT%')
  loop
    if v_rec.rate_class is null then continue; end if;
    select id into v_wh_id from erp.warehouses where wh_type = v_rec.wh_type and is_active = true order by code limit 1;
    if v_wh_id is null then
      v_warnings := v_warnings || jsonb_build_object('item_code', v_rec.code, 'warning', 'no_warehouse_for_class', 'wh_type', v_rec.wh_type);
      continue;
    end if;
    select qty, value into v_open_qty, v_open_val from erp._pac_opening_qty_value(v_rec.item_id, v_wh_id, p_start_date);
    select coalesce(sum(im.qty_in), 0),
           coalesce(sum(coalesce(nullif(im.value_amount, 0), im.qty_in * im.unit_cost)), 0),
           count(*) filter (where coalesce(im.unit_cost, 0) = 0 and coalesce(im.value_amount, 0) = 0)
    into v_purch_qty, v_purch_val, v_zero_purchases
    from erp.inventory_movements im
    where im.item_id = v_rec.item_id
      and im.warehouse_id = v_wh_id
      and im.movement_type in ('purchase_in', 'adjustment_in')
      and im.posting_date between p_start_date and p_end_date;
    v_pac := case
      when (coalesce(v_open_qty, 0) + coalesce(v_purch_qty, 0)) = 0 then 0
      else round((coalesce(v_open_val, 0) + coalesce(v_purch_val, 0)) / nullif(coalesce(v_open_qty, 0) + coalesce(v_purch_qty, 0), 0), 6)
    end;
    if v_zero_purchases > 0 then
      v_warnings := v_warnings || jsonb_build_object('item_code', v_rec.code, 'warning', 'zero_rate_purchases', 'count', v_zero_purchases);
    end if;
    insert into erp.period_cost_rates (period_id, item_id, rate_class, opening_qty, opening_value, purchase_qty, purchase_value, pac_unit_cost, is_draft, computed_at)
    values (p_period_id, v_rec.item_id, v_rec.rate_class, coalesce(v_open_qty, 0), coalesce(v_open_val, 0), coalesce(v_purch_qty, 0), coalesce(v_purch_val, 0), v_pac, p_is_draft, now())
    on conflict (period_id, item_id, is_draft) do update
      set opening_qty = excluded.opening_qty, opening_value = excluded.opening_value, purchase_qty = excluded.purchase_qty, purchase_value = excluded.purchase_value, pac_unit_cost = excluded.pac_unit_cost, computed_at = now();
    v_rates := v_rates || jsonb_build_object('item_code', v_rec.code, 'rate_class', v_rec.rate_class, 'pac_unit_cost', v_pac, 'opening_qty', coalesce(v_open_qty, 0), 'purchase_qty', coalesce(v_purch_qty, 0));
  end loop;
  return jsonb_build_object('rates', v_rates, 'warnings', v_warnings);
end;
$$;


ALTER FUNCTION "erp"."_pac_compute_rm_rates"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean) OWNER TO "postgres";

--
-- Name: _pac_cost_production("uuid", "date", "date", numeric, boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_cost_production"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_scrap jsonb;
begin
  v_result := erp._pac_cost_production_varnish_318(
    p_period_id, p_start_date, p_end_date, p_oh_rate, p_is_draft
  );
  v_scrap := erp._sync_factory_scrap_period_costs(p_start_date, p_end_date);
  return coalesce(v_result, '{}'::jsonb) || jsonb_build_object('factory_scrap_cost_sync', v_scrap);
end;
$$;


ALTER FUNCTION "erp"."_pac_cost_production"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean) OWNER TO "postgres";

--
-- Name: _pac_cost_production_pooled_318("uuid", "date", "date", numeric, boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_cost_production_pooled_318"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_mov record;
  v_pac numeric;
  v_batch record;
  v_copper_kg numeric;
  v_varnish_kg numeric;
  v_packing_qty numeric;
  v_fg_output_kg numeric;
  v_rm_cost numeric;
  v_oh_cost numeric;
  v_pac_fg numeric;
  v_copper_per numeric;
  v_varnish_per numeric;
  v_packing_per numeric;
  v_issues_stamped int := 0;
  v_receipts_stamped int := 0;
  v_rates jsonb := '[]'::jsonb;
begin
  -- Phase 1: stamp production issues with item PAC rates
  for v_mov in
    select im.id, im.item_id, im.qty_out
    from erp.inventory_movements im
    where im.movement_type = 'production_issue'
      and im.posting_date between p_start_date and p_end_date
      and coalesce(im.qty_out, 0) > 0
    order by im.posting_date, im.created_at, im.id
  loop
    select pac_unit_cost into v_pac
    from erp.period_cost_rates
    where period_id = p_period_id
      and item_id = v_mov.item_id
      and is_draft = p_is_draft
    limit 1;
    v_pac := coalesce(v_pac, 0);

    update erp.inventory_movements
      set unit_cost = v_pac,
          value_amount = round(v_mov.qty_out * v_pac, 3),
          cost_status = case when p_is_draft then 'period_draft' else 'period_final' end,
          costed_period_id = p_period_id
      where id = v_mov.id;

    v_issues_stamped := v_issues_stamped + 1;
  end loop;

  -- Phase 2: per-batch FG PAC = (metal + varnish + packing + OH) / FG kg
  for v_batch in
    select distinct im.source_doc_id as batch_id
    from erp.inventory_movements im
    where im.movement_type = 'production_receipt'
      and im.posting_date between p_start_date and p_end_date
      and im.source_doc_type = 'production_batch'
      and im.source_doc_id is not null
    order by im.source_doc_id
  loop
    -- Qty diagnostics (metal = wire copper + rod)
    select
      coalesce(sum(case
        when r.rate_class in ('rm_copper', 'rm_rod') then im.qty_out
        else 0
      end), 0),
      coalesce(sum(case when r.rate_class = 'rm_varnish' then im.qty_out else 0 end), 0),
      coalesce(sum(case when r.rate_class = 'rm_packing' then im.qty_out else 0 end), 0)
    into v_copper_kg, v_varnish_kg, v_packing_qty
    from erp.inventory_movements im
    left join erp.period_cost_rates r
      on r.period_id = p_period_id
     and r.item_id = im.item_id
     and r.is_draft = p_is_draft
    where im.movement_type = 'production_issue'
      and im.source_doc_id = v_batch.batch_id
      and im.source_doc_type = 'production_batch';

    select coalesce(sum(im.qty_in), 0) into v_fg_output_kg
    from erp.inventory_movements im
    where im.movement_type = 'production_receipt'
      and im.source_doc_id = v_batch.batch_id
      and im.source_doc_type = 'production_batch';

    if coalesce(v_fg_output_kg, 0) <= 0 then
      continue;
    end if;

    -- Value rollup: rm_rod MUST be included with rm_copper (bug fix)
    select
      coalesce(sum(case
        when r.rate_class in ('rm_copper', 'rm_rod') then im.qty_out * r.pac_unit_cost
        else 0
      end), 0),
      coalesce(sum(case
        when r.rate_class = 'rm_varnish' then im.qty_out * r.pac_unit_cost
        else 0
      end), 0),
      coalesce(sum(case
        when r.rate_class = 'rm_packing' then im.qty_out * r.pac_unit_cost
        else 0
      end), 0)
    into v_copper_per, v_varnish_per, v_packing_per
    from erp.inventory_movements im
    join erp.period_cost_rates r
      on r.period_id = p_period_id
     and r.item_id = im.item_id
     and r.is_draft = p_is_draft
    where im.movement_type = 'production_issue'
      and im.source_doc_id = v_batch.batch_id
      and im.source_doc_type = 'production_batch';

    v_rm_cost := v_copper_per + v_varnish_per + v_packing_per;
    v_oh_cost := round(v_fg_output_kg * p_oh_rate, 3);
    v_pac_fg := round((v_rm_cost + v_oh_cost) / v_fg_output_kg, 6);

    for v_mov in
      select im.id, im.item_id, im.qty_in
      from erp.inventory_movements im
      where im.movement_type = 'production_receipt'
        and im.source_doc_id = v_batch.batch_id
        and im.source_doc_type = 'production_batch'
      order by im.id
    loop
      update erp.inventory_movements
        set unit_cost = v_pac_fg,
            value_amount = round(v_mov.qty_in * v_pac_fg, 3),
            -- Metal (wire + rod) allocated into cost_copper component
            cost_copper  = round(v_mov.qty_in * v_copper_per  / nullif(v_fg_output_kg, 0), 3),
            cost_varnish = round(v_mov.qty_in * v_varnish_per / nullif(v_fg_output_kg, 0), 3),
            cost_packing = round(v_mov.qty_in * v_packing_per / nullif(v_fg_output_kg, 0), 3),
            cost_oh      = round(v_mov.qty_in * p_oh_rate, 3),
            cost_status  = case when p_is_draft then 'period_draft' else 'period_final' end,
            costed_period_id = p_period_id
        where id = v_mov.id;

      v_receipts_stamped := v_receipts_stamped + 1;

      insert into erp.period_cost_rates (
        period_id, item_id, rate_class,
        pac_unit_cost,
        rm_copper_per_kg, rm_varnish_per_kg, rm_packing_per_kg, oh_per_kg,
        production_qty, is_draft, computed_at
      )
      values (
        p_period_id, v_mov.item_id, 'fg_enamel', v_pac_fg,
        round(v_copper_per  / nullif(v_fg_output_kg, 0), 6),
        round(v_varnish_per / nullif(v_fg_output_kg, 0), 6),
        round(v_packing_per / nullif(v_fg_output_kg, 0), 6),
        p_oh_rate,
        v_mov.qty_in, p_is_draft, now()
      )
      on conflict (period_id, item_id, is_draft) do update
        set pac_unit_cost = excluded.pac_unit_cost,
            rm_copper_per_kg = excluded.rm_copper_per_kg,
            rm_varnish_per_kg = excluded.rm_varnish_per_kg,
            rm_packing_per_kg = excluded.rm_packing_per_kg,
            oh_per_kg = excluded.oh_per_kg,
            production_qty = erp.period_cost_rates.production_qty + excluded.production_qty,
            computed_at = now();

      v_rates := v_rates || jsonb_build_object(
        'item_id', v_mov.item_id,
        'pac_fg', v_pac_fg,
        'copper_per_kg', round(v_copper_per / nullif(v_fg_output_kg, 0), 6),
        'varnish_per_kg', round(v_varnish_per / nullif(v_fg_output_kg, 0), 6),
        'packing_per_kg', round(v_packing_per / nullif(v_fg_output_kg, 0), 6),
        'oh_per_kg', p_oh_rate
      );
    end loop;
  end loop;

  return jsonb_build_object(
    'issues_stamped', v_issues_stamped,
    'receipts_stamped', v_receipts_stamped,
    'fg_rates', v_rates
  );
end;
$$;


ALTER FUNCTION "erp"."_pac_cost_production_pooled_318"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean) OWNER TO "postgres";

--
-- Name: FUNCTION "_pac_cost_production_pooled_318"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_pac_cost_production_pooled_318"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean) IS 'PAC Phase C: stamp production issues + FG receipts. Metal = rm_copper + rm_rod.';


--
-- Name: _pac_cost_production_varnish_318("uuid", "date", "date", numeric, boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_cost_production_varnish_318"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_batch record;
  v_item record;
  v_adjustments jsonb := '[]'::jsonb;
begin
  v_result := erp._pac_cost_production_pooled_318(
    p_period_id, p_start_date, p_end_date, p_oh_rate, p_is_draft
  );

  for v_batch in
    select distinct im.source_doc_id as batch_id
    from erp.inventory_movements im
    where im.source_doc_type = 'production_batch'
      and im.movement_type = 'production_receipt'
      and im.posting_date between p_start_date and p_end_date
      and im.source_doc_id is not null
    order by im.source_doc_id
  loop
    v_adjustments := v_adjustments || erp._redistribute_batch_varnish_cost(v_batch.batch_id);
  end loop;

  -- PAC sales stamping reads period_cost_rates. Rebuild each FG item rate from
  -- the corrected receipt components before Phase D runs.
  for v_item in
    select
      im.item_id,
      sum(im.qty_in) as production_qty,
      round(sum(im.value_amount) / nullif(sum(im.qty_in), 0), 6) as pac_unit_cost,
      round(sum(coalesce(im.cost_copper, 0)) / nullif(sum(im.qty_in), 0), 6) as copper_per_kg,
      round(sum(coalesce(im.cost_varnish, 0)) / nullif(sum(im.qty_in), 0), 6) as varnish_per_kg,
      round(sum(coalesce(im.cost_packing, 0)) / nullif(sum(im.qty_in), 0), 6) as packing_per_kg,
      round(sum(coalesce(im.cost_oh, 0)) / nullif(sum(im.qty_in), 0), 6) as oh_per_kg
    from erp.inventory_movements im
    where im.source_doc_type = 'production_batch'
      and im.movement_type = 'production_receipt'
      and im.posting_date between p_start_date and p_end_date
      and coalesce(im.qty_in, 0) > 0
    group by im.item_id
  loop
    insert into erp.period_cost_rates (
      period_id, item_id, rate_class, pac_unit_cost,
      rm_copper_per_kg, rm_varnish_per_kg, rm_packing_per_kg, oh_per_kg,
      production_qty, is_draft, computed_at
    ) values (
      p_period_id, v_item.item_id,
      case when erp._is_enameled_output_item(v_item.item_id) then 'fg_enamel' else 'fg_other' end,
      v_item.pac_unit_cost, v_item.copper_per_kg, v_item.varnish_per_kg,
      v_item.packing_per_kg, v_item.oh_per_kg,
      v_item.production_qty, p_is_draft, now()
    )
    on conflict (period_id, item_id, is_draft) do update
    set rate_class = excluded.rate_class,
        pac_unit_cost = excluded.pac_unit_cost,
        rm_copper_per_kg = excluded.rm_copper_per_kg,
        rm_varnish_per_kg = excluded.rm_varnish_per_kg,
        rm_packing_per_kg = excluded.rm_packing_per_kg,
        oh_per_kg = excluded.oh_per_kg,
        production_qty = excluded.production_qty,
        computed_at = now();
  end loop;

  return coalesce(v_result, '{}'::jsonb)
    || jsonb_build_object('varnish_distribution', v_adjustments);
end;
$$;


ALTER FUNCTION "erp"."_pac_cost_production_varnish_318"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean) OWNER TO "postgres";

--
-- Name: FUNCTION "_pac_cost_production_varnish_318"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_pac_cost_production_varnish_318"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_oh_rate" numeric, "p_is_draft" boolean) IS 'PAC production costing with varnish restricted to enameled-wire receipts and corrected item rates.';


--
-- Name: _pac_opening_qty_value("uuid", "uuid", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_opening_qty_value"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_as_of" "date") RETURNS TABLE("qty" numeric, "value" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_avg numeric := 0;
  v_delta_qty numeric;
  v_delta_val numeric;
  v_rec record;
begin
  qty := 0;
  value := 0;
  if p_as_of is null then
    return next;
    return;
  end if;

  for v_rec in
    select im.*
    from erp.inventory_movements im
    where im.item_id = p_item_id
      and im.warehouse_id = p_warehouse_id
      and im.posting_date < p_as_of
    order by im.posting_date,
             case im.movement_type
               when 'opening' then 1
               when 'purchase_in' then 2
               when 'production_issue' then 3
               when 'production_receipt' then 3
               when 'scrap_in' then 4
               when 'scrap_out' then 4
               when 'sales_out' then 5
               when 'adjustment_in' then 6
               when 'adjustment_out' then 6
               else 9
             end,
             im.created_at,
             im.id
  loop
    v_delta_qty := coalesce(v_rec.qty_in, 0) - coalesce(v_rec.qty_out, 0);
    if coalesce(v_rec.qty_out, 0) > 0 then
      v_delta_val := -round(v_rec.qty_out * coalesce(v_avg, 0), 3);
    else
      v_delta_val := coalesce(
        nullif(v_rec.value_amount, 0),
        round(coalesce(v_rec.qty_in, 0) * coalesce(v_rec.unit_cost, 0), 3),
        0
      );
    end if;

    qty := qty + v_delta_qty;
    value := value + v_delta_val;

    if qty <= 0 then
      qty := 0;
      value := 0;
      v_avg := 0;
    else
      v_avg := round(value / qty, 6);
    end if;
  end loop;

  return next;
  return;
end;
$$;


ALTER FUNCTION "erp"."_pac_opening_qty_value"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_as_of" "date") OWNER TO "postgres";

--
-- Name: _pac_period_fg_output_kg("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_period_fg_output_kg"("p_start_date" "date", "p_end_date" "date") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(sum(im.qty_in), 0)
  from erp.inventory_movements im
  where im.movement_type = 'production_receipt'
    and im.source_doc_type = 'production_batch'
    and im.posting_date between p_start_date and p_end_date;
$$;


ALTER FUNCTION "erp"."_pac_period_fg_output_kg"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";

--
-- Name: FUNCTION "_pac_period_fg_output_kg"("p_start_date" "date", "p_end_date" "date"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_pac_period_fg_output_kg"("p_start_date" "date", "p_end_date" "date") IS 'Monthly PAC denominator: all finished output received from production batches, including enameled wire, copper wire and strip.';


--
-- Name: _pac_rebuild_and_finalize("uuid", boolean, numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_rebuild_and_finalize"("p_period_id" "uuid", "p_is_draft" boolean, "p_oh_rate" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item_ids uuid[] := '{}';
  v_id uuid;
begin
  select array_agg(distinct item_id) into v_item_ids
  from erp.period_cost_rates where period_id = p_period_id;

  if v_item_ids is not null and array_length(v_item_ids, 1) > 0 then
    perform erp.rebuild_inventory_balances_for_items(v_item_ids);
  end if;

  if p_is_draft then
    update erp.costing_periods
      set status = 'draft',
          last_run_at = now(),
          last_run_mode = 'draft',
          updated_at = now()
      where id = p_period_id;
  else
    update erp.costing_periods
      set status = 'locked',
          locked_at = now(),
          locked_by = auth.uid(),
          last_run_at = now(),
          last_run_mode = 'final',
          actual_overhead_rate = coalesce(actual_overhead_rate, p_oh_rate),
          updated_at = now()
      where id = p_period_id;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_pac_rebuild_and_finalize"("p_period_id" "uuid", "p_is_draft" boolean, "p_oh_rate" numeric) OWNER TO "postgres";

--
-- Name: _pac_rebuild_production_gl("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_rebuild_production_gl"("p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_batch record;
  v_je record;
  v_seq int;
  v_batches int := 0;
  v_voided int := 0;
  v_synced int := 0;
  v_fg numeric;
begin
  for v_batch in
    select pb.id, pb.batch_no
    from erp.production_batches pb
    where pb.status = 'posted'
      and pb.batch_date between p_start_date and p_end_date
    order by pb.batch_date, pb.batch_no, pb.id
  loop
    v_batches := v_batches + 1;
    v_seq := 0;

    for v_je in
      select je.id, je.voucher_no
      from erp.journal_entries je
      where je.source_doc_type = 'production_batch'
        and je.source_doc_id = v_batch.id
        and coalesce(je.voucher_no, '') not like 'VOID-%'
    loop
      v_seq := v_seq + 1;
      update erp.journal_entries
        set voucher_no = 'VOID-PAC-' || v_batch.batch_no
          || case when v_seq > 1 then '-' || v_seq::text else '' end,
            narration = coalesce(narration, '') || ' [superseded by PAC final rebuild]'
      where id = v_je.id;
      v_voided := v_voided + 1;
    end loop;

    v_fg := erp._sync_production_batch_gl(v_batch.id);
    if coalesce(v_fg, 0) > 0 or exists (
      select 1 from erp.journal_entries je
      where je.source_doc_type = 'production_batch'
        and je.source_doc_id = v_batch.id
        and coalesce(je.voucher_no, '') not like 'VOID-%'
    ) then
      v_synced := v_synced + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'batches_in_range', v_batches,
    'jes_void_renamed', v_voided,
    'batches_gl_synced', v_synced
  );
end;
$$;


ALTER FUNCTION "erp"."_pac_rebuild_production_gl"("p_start_date" "date", "p_end_date" "date") OWNER TO "postgres";

--
-- Name: FUNCTION "_pac_rebuild_production_gl"("p_start_date" "date", "p_end_date" "date"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_pac_rebuild_production_gl"("p_start_date" "date", "p_end_date" "date") IS 'PAC final helper: void-rename stale production JEs and rebuild from PAC-stamped movements.';


--
-- Name: _pac_resolve_overhead("uuid", "date", "date", boolean, numeric, numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_resolve_overhead"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean, "p_actual_overhead_rate" numeric, "p_actual_overhead_amount" numeric) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_oh numeric;
  v_proxy_period erp.costing_periods%rowtype;
  v_fg_kg numeric;
  v_amount numeric := p_actual_overhead_amount;
begin
  if p_is_draft then
    select * into v_proxy_period
    from erp.costing_periods
    where status = 'locked'
      and actual_overhead_rate is not null
      and actual_overhead_rate > 0
    order by end_date desc
    limit 1;

    if found then
      v_oh := v_proxy_period.actual_overhead_rate;
      update erp.costing_periods
        set proxy_overhead_rate_used = v_oh,
            proxy_source_period_id = v_proxy_period.id
        where id = p_period_id;
      return v_oh;
    end if;

    -- No locked period yet: derive draft proxy from posted factory GL / FG kg
    -- (same pool as final auto). Falls back to live_conversion_rate_fallback.
    v_amount := coalesce(erp._pac_auto_overhead_amount(p_start_date, p_end_date), 0);
    v_fg_kg := erp._pac_period_fg_output_kg(p_start_date, p_end_date);
    if coalesce(v_fg_kg, 0) > 0 and coalesce(v_amount, 0) > 0 then
      v_oh := round(v_amount / v_fg_kg, 6);
    else
      v_oh := coalesce(nullif(erp._production_standard_num('live_conversion_rate_fallback'), 0), 0);
    end if;

    update erp.costing_periods
      set proxy_overhead_rate_used = v_oh,
          proxy_source_period_id = null
      where id = p_period_id;
    return v_oh;
  end if;

  -- Final: manual rate wins; else amount (manual or auto) / FG kg
  if coalesce(p_actual_overhead_rate, 0) > 0 then
    v_oh := p_actual_overhead_rate;
  else
    if v_amount is null then
      v_amount := coalesce(erp._pac_auto_overhead_amount(p_start_date, p_end_date), 0);
    end if;

    v_fg_kg := erp._pac_period_fg_output_kg(p_start_date, p_end_date);
    if coalesce(v_fg_kg, 0) <= 0 then
      raise exception 'Final run requires FG output kg > 0 to derive overhead rate from amount';
    end if;
    v_oh := round(v_amount / v_fg_kg, 6);
  end if;

  update erp.costing_periods
    set actual_overhead_rate = v_oh,
        actual_overhead_amount = coalesce(v_amount, p_actual_overhead_amount)
    where id = p_period_id;

  return v_oh;
end;
$$;


ALTER FUNCTION "erp"."_pac_resolve_overhead"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean, "p_actual_overhead_rate" numeric, "p_actual_overhead_amount" numeric) OWNER TO "postgres";

--
-- Name: _pac_stamp_cogs("uuid", "date", "date", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_stamp_cogs"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_mov record;
  v_state record;
  v_pac numeric;
  v_copper_per numeric;
  v_varnish_per numeric;
  v_packing_per numeric;
  v_oh_per numeric;
  v_sales_stamped int := 0;
  v_sales_fallback int := 0;
  v_scrap_stamped int := 0;
  v_scrap_skipped int := 0;
  v_invoice_ids uuid[] := '{}';
  v_inv uuid;
  v_gl_synced int := 0;
begin
  for v_mov in
    select im.id, im.item_id, im.warehouse_id, im.qty_out,
           im.unit_cost, im.source_doc_type, im.source_doc_id
    from erp.inventory_movements im
    where im.movement_type = 'sales_out'
      and im.posting_date between p_start_date and p_end_date
      and coalesce(im.qty_out, 0) > 0
    order by im.posting_date, im.created_at, im.id
  loop
    v_pac := null;
    v_copper_per := null;
    v_varnish_per := null;
    v_packing_per := null;
    v_oh_per := null;

    select pac_unit_cost, rm_copper_per_kg, rm_varnish_per_kg,
           rm_packing_per_kg, oh_per_kg
    into v_pac, v_copper_per, v_varnish_per, v_packing_per, v_oh_per
    from erp.period_cost_rates
    where period_id = p_period_id
      and item_id = v_mov.item_id
      and is_draft = p_is_draft
    limit 1;

    if coalesce(v_pac, 0) <= 0 then
      select * into v_state
      from erp._inventory_replay_state(
        v_mov.item_id, v_mov.warehouse_id, v_mov.id
      );
      v_pac := coalesce(
        nullif(v_state.avg_unit_cost, 0),
        nullif(v_mov.unit_cost, 0),
        (select nullif(i.standard_cost, 0)
         from erp.items i where i.id = v_mov.item_id),
        0
      );
      v_copper_per := coalesce(v_state.copper_unit_cost, 0);
      v_varnish_per := coalesce(v_state.varnish_unit_cost, 0);
      v_packing_per := coalesce(v_state.packing_unit_cost, 0);
      v_oh_per := coalesce(v_state.oh_unit_cost, 0);
      v_sales_fallback := v_sales_fallback + 1;
    end if;

    update erp.inventory_movements
    set unit_cost = v_pac,
        value_amount = round(v_mov.qty_out * v_pac, 3),
        cost_copper = round(v_mov.qty_out * coalesce(v_copper_per, 0), 3),
        cost_varnish = round(v_mov.qty_out * coalesce(v_varnish_per, 0), 3),
        cost_packing = round(v_mov.qty_out * coalesce(v_packing_per, 0), 3),
        cost_oh = round(v_mov.qty_out * coalesce(v_oh_per, 0), 3),
        cost_status = case when p_is_draft then 'period_draft' else 'period_final' end,
        costed_period_id = p_period_id
    where id = v_mov.id;

    v_sales_stamped := v_sales_stamped + 1;
    if v_mov.source_doc_type = 'sales_invoice'
       and v_mov.source_doc_id is not null
       and not (v_mov.source_doc_id = any(v_invoice_ids)) then
      v_invoice_ids := array_append(v_invoice_ids, v_mov.source_doc_id);
    end if;
  end loop;

  for v_mov in
    select im.id, im.item_id, im.warehouse_id, im.qty_out,
           im.unit_cost, im.source_doc_type
    from erp.inventory_movements im
    where im.movement_type = 'scrap_out'
      and im.posting_date between p_start_date and p_end_date
      and coalesce(im.qty_out, 0) > 0
    order by im.posting_date, im.created_at, im.id
  loop
    if v_mov.source_doc_type = 'factory_scrap_dispatch' then
      v_scrap_skipped := v_scrap_skipped + 1;
      continue;
    end if;

    v_pac := null;
    select pac_unit_cost into v_pac
    from erp.period_cost_rates
    where period_id = p_period_id
      and item_id = v_mov.item_id
      and is_draft = p_is_draft
    limit 1;
    if coalesce(v_pac, 0) <= 0 then
      select * into v_state
      from erp._inventory_replay_state(
        v_mov.item_id, v_mov.warehouse_id, v_mov.id
      );
      v_pac := coalesce(
        nullif(v_state.avg_unit_cost, 0),
        nullif(v_mov.unit_cost, 0),
        (select nullif(i.standard_cost, 0)
         from erp.items i where i.id = v_mov.item_id),
        0
      );
    end if;

    update erp.inventory_movements
    set unit_cost = v_pac,
        value_amount = round(v_mov.qty_out * v_pac, 3),
        cost_status = case when p_is_draft then 'period_draft' else 'period_final' end,
        costed_period_id = p_period_id
    where id = v_mov.id;
    v_scrap_stamped := v_scrap_stamped + 1;
  end loop;

  if not p_is_draft then
    foreach v_inv in array v_invoice_ids loop
      if erp._sync_sales_invoice_cogs_gl(v_inv) then
        v_gl_synced := v_gl_synced + 1;
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'sales_stamped', v_sales_stamped,
    'sales_book_wac_fallback', v_sales_fallback,
    'scrap_stamped', v_scrap_stamped,
    'factory_scrap_mirrors_skipped', v_scrap_skipped,
    'invoices_touched', cardinality(v_invoice_ids),
    'invoices_gl_synced', v_gl_synced
  );
end;
$$;


ALTER FUNCTION "erp"."_pac_stamp_cogs"("p_period_id" "uuid", "p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean) OWNER TO "postgres";

--
-- Name: _pac_upsert_period("date", "date", boolean, "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_pac_upsert_period"("p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean, "p_period_code" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_code text;
begin
  v_code := coalesce(p_period_code,
    to_char(p_start_date, 'YYYY-MM') || case when p_is_draft then '-DRAFT' else '' end);

  insert into erp.costing_periods (period_code, start_date, end_date, status)
  values (v_code, p_start_date, p_end_date, case when p_is_draft then 'draft' else 'open' end)
  on conflict (period_code) do update
    set start_date = excluded.start_date,
        end_date = excluded.end_date,
        updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "erp"."_pac_upsert_period"("p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean, "p_period_code" "text") OWNER TO "postgres";

--
-- Name: _parse_item_swg("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_parse_item_swg"("p_size_spec" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $_$
declare
  v_m text[];
  v_n int;
begin
  if p_size_spec is null or trim(p_size_spec) = '' then return null; end if;
  v_m := regexp_match(upper(trim(p_size_spec)), 'SWG\s*(\d+)');
  if v_m is not null then return v_m[1]::int; end if;
  if trim(p_size_spec) ~ '^\d+$' then return trim(p_size_spec)::int; end if;
  return null;
end;
$_$;


ALTER FUNCTION "erp"."_parse_item_swg"("p_size_spec" "text") OWNER TO "postgres";

--
-- Name: _parse_item_swg_decimal("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_parse_item_swg_decimal"("p_size_spec" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $_$
declare
  v_m text[];
begin
  if p_size_spec is null or trim(p_size_spec) = '' then return null; end if;
  v_m := regexp_match(upper(trim(p_size_spec)), 'SWG\s*(\d+(?:\.\d+)?)');
  if v_m is not null then return v_m[1]::numeric; end if;
  if trim(p_size_spec) ~ '^\d+(?:\.\d+)?$' then return trim(p_size_spec)::numeric; end if;
  return null;
end;
$_$;


ALTER FUNCTION "erp"."_parse_item_swg_decimal"("p_size_spec" "text") OWNER TO "postgres";

--
-- Name: _parse_wire8_grade("text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_parse_wire8_grade"("p_size_spec" "text", "p_name" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v text := upper(coalesce(p_size_spec, '') || ' ' || coalesce(p_name, ''));
begin
  if v like '%SPECIAL%' then return 'Special'; end if;
  if v like '%FAIL%' then return 'Fail'; end if;
  if v like '%PASS%' then return 'Pass'; end if;
  return null;
end;
$$;


ALTER FUNCTION "erp"."_parse_wire8_grade"("p_size_spec" "text", "p_name" "text") OWNER TO "postgres";

--
-- Name: _party_fin_subledger_codes(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_party_fin_subledger_codes"() RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(
    array_agg(distinct pam.account_code order by pam.account_code),
    array['11201', '21101', '11203', '21104']::text[]
  )
  from erp.posting_account_map pam
  where pam.is_active = true
    and pam.effective_from <= current_date
    and pam.line_role in (
      'ar', 'ap', 'parchi_receivable', 'parchi_payable',
      'customer_advance', 'vendor_advance'
    );
$$;


ALTER FUNCTION "erp"."_party_fin_subledger_codes"() OWNER TO "postgres";

