--
-- Name: _post_correction_adjustment_in("text", "text", numeric, numeric, "text", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_post_correction_adjustment_in"("p_item_code" "text", "p_wh_type" "text", "p_qty" numeric, "p_units" numeric, "p_remarks" "text", "p_posting_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item erp.items%rowtype;
  v_wh_id uuid;
  v_adj_id uuid;
  v_adj_no text;
  v_unit_cost numeric;
  v_value numeric;
  v_tracks_units boolean := false;
  v_section text;
  v_units numeric := greatest(coalesce(p_units, 0), 0);
begin
  if coalesce(p_qty, 0) <= 0 then
    return jsonb_build_object('ok', true, 'skipped', true, 'reason', 'qty<=0');
  end if;

  select * into v_item
  from erp.items
  where code = p_item_code and coalesce(is_active, true)
  limit 1;
  if not found then
    return jsonb_build_object('ok', false, 'error', format('item not found: %s', p_item_code));
  end if;

  select id into v_wh_id
  from erp.warehouses
  where wh_type = p_wh_type and coalesce(is_active, true)
  order by code
  limit 1;
  if v_wh_id is null then
    return jsonb_build_object('ok', false, 'error', format('warehouse missing for %s', p_wh_type));
  end if;

  -- Idempotent: skip if an identical correction remark already posted
  if exists (
    select 1 from erp.inventory_adjustments a
    where a.item_id = v_item.id
      and a.direction = 'in'
      and a.status = 'posted'
      and a.remarks = p_remarks
  ) then
    return jsonb_build_object('ok', true, 'skipped', true, 'reason', 'already posted');
  end if;

  v_section := erp._item_inventory_section(v_item.id);
  v_tracks_units := v_section in (
      'fg_enameled', 'fg_strip', 'fg_copper_wire',
      'rm_scrap', 'rm_wire8', 'rm_rod', 'varnish'
    )
    or v_item.inventory_group = 'packing_material'
    or erp._is_varnish_item(v_item.id);

  v_unit_cost := erp._resolve_adjustment_unit_cost(v_item.id, v_wh_id, 'in', p_posting_date);
  v_value := round(p_qty * coalesce(v_unit_cost, 0), 3);

  v_adj_no := erp.next_inventory_adjustment_no('ADJ-');
  v_adj_id := gen_random_uuid();

  insert into erp.inventory_adjustments (
    id, adjustment_no, posting_date, item_id, warehouse_id, direction,
    qty_kg, unit_count, unit_cost, value_amount, remarks, status, posted_at, posted_by, created_by
  ) values (
    v_adj_id, v_adj_no, p_posting_date, v_item.id, v_wh_id, 'in',
    p_qty, v_units, v_unit_cost, v_value, p_remarks,
    'posted', now(), null, null
  );

  insert into erp.inventory_movements (
    posting_date, movement_type, item_id, warehouse_id,
    qty_in, units_in, unit_cost, value_amount,
    source_doc_type, source_doc_id, reference_no
  ) values (
    p_posting_date, 'adjustment_in', v_item.id, v_wh_id,
    p_qty,
    case
      when v_tracks_units and v_units > 0 then v_units
      when v_tracks_units and erp._is_varnish_item(v_item.id)
        then erp._varnish_units_from_kg(v_item.id, p_qty)
      else 0
    end,
    v_unit_cost, v_value,
    'inventory_adjustment', v_adj_id, v_adj_no
  );

  if v_value > 0 then
    perform erp._sync_inventory_adjustment_gl(v_adj_id, 'in', v_value, p_remarks);
  end if;

  perform erp._rebuild_after_document_post(array[v_item.id]);

  return jsonb_build_object(
    'ok', true,
    'adjustment_no', v_adj_no,
    'item_code', p_item_code,
    'qty_kg', p_qty,
    'unit_count', v_units,
    'value_amount', v_value
  );
end;
$$;


ALTER FUNCTION "erp"."_post_correction_adjustment_in"("p_item_code" "text", "p_wh_type" "text", "p_qty" numeric, "p_units" numeric, "p_remarks" "text", "p_posting_date" "date") OWNER TO "postgres";

--
-- Name: _post_correction_adjustment_out("uuid", "uuid", numeric, numeric, "text", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_post_correction_adjustment_out"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_units" numeric, "p_remarks" "text", "p_posting_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item erp.items%rowtype;
  v_adj_id uuid;
  v_adj_no text;
  v_unit_cost numeric;
  v_value numeric;
  v_tracks_units boolean := false;
  v_section text;
  v_units numeric := greatest(coalesce(p_units, 0), 0);
  v_on_hand numeric;
  v_on_hand_units numeric;
begin
  if coalesce(p_qty, 0) <= 0 then
    return jsonb_build_object('ok', true, 'skipped', true, 'reason', 'qty<=0');
  end if;

  select * into v_item from erp.items where id = p_item_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'item not found');
  end if;

  if exists (
    select 1 from erp.inventory_adjustments a
    where a.item_id = p_item_id
      and a.direction = 'out'
      and a.status = 'posted'
      and a.remarks = p_remarks
  ) then
    return jsonb_build_object('ok', true, 'skipped', true, 'reason', 'already posted');
  end if;

  v_on_hand := erp._inventory_on_hand(p_item_id, p_warehouse_id);
  if v_on_hand + 0.001 < p_qty then
    return jsonb_build_object(
      'ok', false,
      'error', format('insufficient stock for revert: need %s, on hand %s', p_qty, v_on_hand)
    );
  end if;

  v_section := erp._item_inventory_section(v_item.id);
  v_tracks_units := v_section in (
      'fg_enameled', 'fg_strip', 'fg_copper_wire',
      'rm_scrap', 'rm_wire8', 'rm_rod', 'varnish'
    )
    or v_item.inventory_group = 'packing_material'
    or erp._is_varnish_item(v_item.id);

  if v_tracks_units and v_units > 0 then
    v_on_hand_units := erp._inventory_on_hand_units(p_item_id, p_warehouse_id);
    if v_on_hand_units + 0.001 < v_units then
      return jsonb_build_object(
        'ok', false,
        'error', format('insufficient units for revert: need %s, on hand %s', v_units, v_on_hand_units)
      );
    end if;
  end if;

  v_unit_cost := erp._resolve_adjustment_unit_cost(p_item_id, p_warehouse_id, 'out', p_posting_date);
  v_value := round(p_qty * coalesce(v_unit_cost, 0), 3);

  if v_value <= 0 then
    -- Still move qty even if cost resolves to 0 (stock correction priority)
    v_unit_cost := 0;
    v_value := 0;
  end if;

  v_adj_no := erp.next_inventory_adjustment_no('ADJ-');
  v_adj_id := gen_random_uuid();

  insert into erp.inventory_adjustments (
    id, adjustment_no, posting_date, item_id, warehouse_id, direction,
    qty_kg, unit_count, unit_cost, value_amount, remarks, status, posted_at, posted_by, created_by
  ) values (
    v_adj_id, v_adj_no, p_posting_date, p_item_id, p_warehouse_id, 'out',
    p_qty, v_units, v_unit_cost, v_value, p_remarks,
    'posted', now(), null, null
  );

  insert into erp.inventory_movements (
    posting_date, movement_type, item_id, warehouse_id,
    qty_out, units_out, unit_cost, value_amount,
    source_doc_type, source_doc_id, reference_no
  ) values (
    p_posting_date, 'adjustment_out', p_item_id, p_warehouse_id,
    p_qty,
    case when v_tracks_units and v_units > 0 then v_units else 0 end,
    v_unit_cost, v_value,
    'inventory_adjustment', v_adj_id, v_adj_no
  );

  if v_value > 0 then
    perform erp._sync_inventory_adjustment_gl(v_adj_id, 'out', v_value, p_remarks);
  end if;

  perform erp._rebuild_after_document_post(array[p_item_id]);

  return jsonb_build_object(
    'ok', true,
    'adjustment_no', v_adj_no,
    'item_id', p_item_id,
    'qty_kg', p_qty,
    'unit_count', v_units,
    'value_amount', v_value
  );
end;
$$;


ALTER FUNCTION "erp"."_post_correction_adjustment_out"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_units" numeric, "p_remarks" "text", "p_posting_date" "date") OWNER TO "postgres";

