--
-- Name: _post_reversing_journal_entry("uuid", "text", "text", "uuid", "text", "date", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_post_reversing_journal_entry"("p_original_je_id" "uuid", "p_void_voucher_no" "text", "p_void_source_doc_type" "text", "p_void_source_doc_id" "uuid", "p_void_source_doc_no" "text", "p_posting_date" "date", "p_narration" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_orig erp.journal_entries%rowtype;
  v_new_je_id uuid;
  v_ln int := 0;
  r record;
begin
  select * into v_orig from erp.journal_entries where id = p_original_je_id;
  if not found then
    return null;
  end if;

  insert into erp.journal_entries (
    voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no,
    narration, status, posted_at, posted_by
  ) values (
    p_void_voucher_no,
    coalesce(v_orig.voucher_type, 'REVERSAL'),
    coalesce(p_posting_date, v_orig.posting_date, current_date),
    p_void_source_doc_type,
    p_void_source_doc_id,
    p_void_source_doc_no,
    coalesce(p_narration, 'Void reversal'),
    'posted',
    now(),
    auth.uid()
  ) returning id into v_new_je_id;

  for r in
    select jl.*
    from erp.journal_lines jl
    where jl.journal_entry_id = p_original_je_id
    order by jl.line_no
  loop
    v_ln := v_ln + 1;
    perform erp._insert_je_line(
      v_new_je_id,
      v_ln,
      r.account_code,
      r.party_id,
      coalesce(r.credit_amount, 0),
      coalesce(r.debit_amount, 0),
      coalesce(r.line_description, 'Void reversal')
    );
  end loop;

  return v_new_je_id;
end;
$$;


ALTER FUNCTION "erp"."_post_reversing_journal_entry"("p_original_je_id" "uuid", "p_void_voucher_no" "text", "p_void_source_doc_type" "text", "p_void_source_doc_id" "uuid", "p_void_source_doc_no" "text", "p_posting_date" "date", "p_narration" "text") OWNER TO "postgres";

