--
-- Name: _production_alert_eval_as_of("date", "uuid"[]); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_production_alert_eval_as_of"("p_doc_date" "date", "p_machine_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "date"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with bounds as (
    select
      coalesce(p_doc_date, current_date) as doc_date,
      date_trunc('month', coalesce(p_doc_date, current_date))::date as month_start,
      (date_trunc('month', coalesce(p_doc_date, current_date)) + interval '1 month - 1 day')::date as month_end
  ),
  machine_filter as (
    select coalesce(p_machine_ids, '{}'::uuid[]) as ids
  ),
  activity as (
    select max(activity_date) as latest_date
    from (
      select pb.batch_date as activity_date
      from erp.production_batches pb, bounds b, machine_filter mf
      where pb.status = 'posted'
        and pb.batch_date between b.month_start and b.month_end
        and (
          cardinality(mf.ids) = 0
          or exists (
            select 1
            from erp.production_batch_lines pl
            where pl.production_batch_id = pb.id
              and coalesce(pl.machine_id, pb.machine_id) = any(mf.ids)
          )
        )
      union all
      select fs.dispatch_date
      from erp.factory_scrap_dispatches fs
      join erp.factory_scrap_dispatch_lines fsl on fsl.dispatch_id = fs.id,
        bounds b,
        machine_filter mf
      where fs.status = 'posted'
        and fs.dispatch_date between b.month_start and b.month_end
        and (cardinality(mf.ids) = 0 or fsl.machine_id = any(mf.ids))
    ) dated_activity
  )
  select least(
    b.month_end,
    greatest(
      b.doc_date,
      least(current_date, b.month_end),
      coalesce(a.latest_date, b.doc_date)
    )
  )
  from bounds b
  cross join activity a;
$$;


ALTER FUNCTION "erp"."_production_alert_eval_as_of"("p_doc_date" "date", "p_machine_ids" "uuid"[]) OWNER TO "postgres";

--
-- Name: _production_batch_totals("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_production_batch_totals"("p_batch_id" "uuid") RETURNS TABLE("input_kg" numeric, "output_kg" numeric, "scrap_kg" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    coalesce(sum(
      case
        when pbl.line_type = 'issue' and coalesce(w.wh_type, '') <> 'packing_material'
          then coalesce(pbl.net_weight, 0)
        else 0
      end
    ), 0),
    coalesce(sum(case when pbl.line_type = 'receipt' then coalesce(pbl.net_weight, 0) else 0 end), 0),
    coalesce(sum(case when pbl.line_type = 'scrap' then coalesce(pbl.scrap_weight, pbl.net_weight, 0) else 0 end), 0)
  from erp.production_batch_lines pbl
  left join erp.warehouses w on w.id = pbl.warehouse_id
  where pbl.production_batch_id = p_batch_id;
$$;


ALTER FUNCTION "erp"."_production_batch_totals"("p_batch_id" "uuid") OWNER TO "postgres";

