-- Name: _production_standard_num("text", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_production_standard_num"("p_key" "text", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce((
    select s.numeric_value
    from erp.production_standards s
    where s.standard_key = p_key
      and s.effective_from <= coalesce(p_as_of, current_date)
    order by s.effective_from desc
    limit 1
  ), 0)::numeric;
$$;


