--
-- Name: _purchase_return_line_inventory_cost("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_purchase_return_line_inventory_cost"("p_line_id" "uuid") RETURNS TABLE("source_movement_id" "uuid", "unit_cost" numeric, "value_amount" numeric, "cost_basis" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_line record;
  v_mov erp.inventory_movements%rowtype;
  v_original_price numeric;
  v_fallback numeric;
begin
  select l.*, r.ref_invoice_id
  into v_line
  from erp.purchase_return_lines l
  join erp.purchase_returns r on r.id = l.purchase_return_id
  where l.id = p_line_id;

  if not found or coalesce(v_line.qty, 0) <= 0 then
    return;
  end if;

  if v_line.ref_invoice_id is not null then
    select pil.unit_price
    into v_original_price
    from erp.purchase_invoice_lines pil
    where pil.purchase_invoice_id = v_line.ref_invoice_id
      and pil.line_no = v_line.line_no
      and pil.item_id is not distinct from v_line.item_id
      and pil.warehouse_id is not distinct from v_line.warehouse_id
    order by pil.id
    limit 1;

    select im.*
    into v_mov
    from erp.purchase_invoice_lines pil
    join erp.inventory_movements im
      on im.source_doc_type = 'purchase_invoice'
     and im.source_doc_id = v_line.ref_invoice_id
     and im.source_line_id = pil.id
     and im.movement_type = 'purchase_in'
    where pil.purchase_invoice_id = v_line.ref_invoice_id
      and pil.line_no = v_line.line_no
      and pil.item_id is not distinct from v_line.item_id
      and pil.warehouse_id is not distinct from v_line.warehouse_id
    order by im.created_at nulls last, im.id
    limit 1;
  end if;

  if v_mov.id is not null then
    source_movement_id := v_mov.id;
    unit_cost := coalesce(
      nullif(v_mov.unit_cost, 0),
      v_mov.value_amount / nullif(v_mov.qty_in, 0),
      nullif(v_original_price, 0),
      0
    );
    value_amount := round(v_line.qty * unit_cost, 3);
    cost_basis := 'original_purchase_movement';
    return next;
    return;
  end if;

  if coalesce(v_original_price, 0) > 0 then
    source_movement_id := null;
    unit_cost := v_original_price;
    value_amount := round(v_line.qty * v_original_price, 3);
    cost_basis := 'original_purchase_line';
    return next;
    return;
  end if;

  v_fallback := coalesce(
    erp._inventory_balance_avg_cost(v_line.item_id, v_line.warehouse_id),
    erp._inventory_replay_current_wac(v_line.item_id, v_line.warehouse_id),
    0
  );
  source_movement_id := null;
  unit_cost := v_fallback;
  value_amount := round(v_line.qty * v_fallback, 3);
  cost_basis := 'fallback_wac';
  return next;
end;
$$;


ALTER FUNCTION "erp"."_purchase_return_line_inventory_cost"("p_line_id" "uuid") OWNER TO "postgres";

--
-- Name: _purge_orphan_scrap_payable_lots(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_purge_orphan_scrap_payable_lots"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  delete from erp.scrap_allocations a
  using erp.scrap_payable_lots l
  where a.scrap_lot_id = l.id
    and l.source_doc_type = 'scrap_trade'
    and not exists (select 1 from erp.scrap_trades t where t.id = l.source_doc_id);

  delete from erp.scrap_payable_lots l
  where l.source_doc_type = 'scrap_trade'
    and not exists (select 1 from erp.scrap_trades t where t.id = l.source_doc_id);

  delete from erp.scrap_payable_lots l
  where l.source_doc_type = 'scrap_trade'
    and not exists (
      select 1 from erp.scrap_trades t where t.id = l.source_doc_id and t.status = 'posted'
    )
    and not exists (select 1 from erp.scrap_allocations sa where sa.scrap_lot_id = l.id);

  delete from erp.scrap_allocations a
  using erp.scrap_payable_lots l
  where a.scrap_lot_id = l.id
    and l.source_doc_type = 'factory_scrap_dispatch'
    and not exists (select 1 from erp.factory_scrap_dispatches d where d.id = l.source_doc_id);

  delete from erp.scrap_payable_lots l
  where l.source_doc_type = 'factory_scrap_dispatch'
    and not exists (select 1 from erp.factory_scrap_dispatches d where d.id = l.source_doc_id);

  delete from erp.scrap_payable_lots l
  where l.source_doc_type = 'factory_scrap_dispatch'
    and not exists (
      select 1 from erp.factory_scrap_dispatches d where d.id = l.source_doc_id and d.status = 'posted'
    )
    and not exists (select 1 from erp.scrap_allocations sa where sa.scrap_lot_id = l.id);
end;
$$;


ALTER FUNCTION "erp"."_purge_orphan_scrap_payable_lots"() OWNER TO "postgres";

--
-- Name: _purge_scrap_payable_lots_for_dispatch("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_purge_scrap_payable_lots_for_dispatch"("p_dispatch_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_lot_ids uuid[];
begin
  select array_agg(id) into v_lot_ids
  from erp.scrap_payable_lots
  where source_doc_type = 'factory_scrap_dispatch'
    and source_doc_id = p_dispatch_id;

  if coalesce(array_length(v_lot_ids, 1), 0) = 0 then
    return;
  end if;

  if exists (
    select 1 from erp.scrap_allocations sa
    where sa.scrap_lot_id = any(v_lot_ids)
      and sa.allocated_kg > 0.001
  ) then
    raise exception 'cannot remove scrap payable lots: premium purchase allocations exist for this dispatch';
  end if;

  delete from erp.scrap_allocations where scrap_lot_id = any(v_lot_ids);
  delete from erp.scrap_payable_lots where id = any(v_lot_ids);
end;
$$;


ALTER FUNCTION "erp"."_purge_scrap_payable_lots_for_dispatch"("p_dispatch_id" "uuid") OWNER TO "postgres";

