--
-- Name: _recalc_premium_sales_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_recalc_premium_sales_invoice"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_invoices%rowtype;
  v_line record;
  v_item record;
  v_swg int;
  v_new_watta numeric;
  v_ref_scrap numeric;
  v_unit_price numeric;
  v_line_amount numeric;
  v_subtotal numeric := 0;
  v_tax_rate numeric := 0;
  v_tax_amt numeric;
  v_old_grand numeric;
  v_new_grand numeric;
  v_old_tax numeric;
  v_lines_changed int := 0;
begin
  select * into v_doc from erp.sales_invoices where id = p_invoice_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'invoice not found');
  end if;
  if coalesce(v_doc.sale_mode, 'direct') <> 'premium' then
    return jsonb_build_object('ok', false, 'error', 'not premium invoice', 'skipped', true);
  end if;

  v_ref_scrap := coalesce(v_doc.ref_scrap_rate, 0);
  v_old_grand := coalesce(v_doc.grand_total, 0);
  v_old_tax := coalesce(v_doc.tax_amount, 0);

  for v_line in
    select l.*, i.size_spec
    from erp.sales_invoice_lines l
    join erp.items i on i.id = l.item_id
    where l.sales_invoice_id = p_invoice_id
    order by l.line_no
  loop
    if erp._item_product_kind(v_line.item_id) <> 'enamel' then
      v_subtotal := v_subtotal + coalesce(v_line.line_amount, 0);
      if v_line.tax_rate is not null and v_line.tax_rate > v_tax_rate then
        v_tax_rate := v_line.tax_rate;
      end if;
      continue;
    end if;

    v_swg := erp._parse_item_swg(v_line.size_spec);
    v_new_watta := erp.resolve_watta(v_doc.party_id, v_line.item_id, 'sales', v_doc.invoice_date, v_swg);

    if abs(coalesce(v_new_watta, 0) - coalesce(v_line.watta_rate, 0)) >= 0.001 then
      v_lines_changed := v_lines_changed + 1;
    end if;

    v_unit_price := round(v_ref_scrap + coalesce(v_new_watta, 0), 3);
    v_line_amount := round(coalesce(v_line.net_weight, 0) * v_unit_price, 3);

    update erp.sales_invoice_lines
    set watta_rate = coalesce(v_new_watta, 0),
        unit_price = v_unit_price,
        line_amount = v_line_amount
    where id = v_line.id;

    v_subtotal := v_subtotal + v_line_amount;
    if v_line.tax_rate is not null and v_line.tax_rate > v_tax_rate then
      v_tax_rate := v_line.tax_rate;
    end if;
  end loop;

  v_tax_amt := round(greatest(v_subtotal - coalesce(v_doc.discount_amount, 0), 0) * coalesce(v_tax_rate, 0) / 100.0, 3);

  v_new_grand := round(v_subtotal - coalesce(v_doc.discount_amount, 0) + v_tax_amt, 3);

  update erp.sales_invoices
  set subtotal_amount = v_subtotal,
      tax_amount = v_tax_amt,
      grand_total = v_new_grand
  where id = p_invoice_id;

  return jsonb_build_object(
    'ok', true,
    'invoice_id', p_invoice_id,
    'old_grand', v_old_grand,
    'new_grand', v_new_grand,
    'old_tax', v_old_tax,
    'new_tax', v_tax_amt,
    'lines_changed', v_lines_changed,
    'changed', (v_lines_changed > 0 or abs(v_old_grand - v_new_grand) >= 0.01)
  );
end;
$$;


ALTER FUNCTION "erp"."_recalc_premium_sales_invoice"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _recalc_purchase_order_inline("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_recalc_purchase_order_inline"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_total_ordered numeric;
  v_total_received numeric;
begin
  select coalesce(sum(qty_ordered), 0), coalesce(sum(qty_received), 0)
  into v_total_ordered, v_total_received
  from erp.purchase_order_lines
  where purchase_order_id = p_order_id;

  update erp.purchase_orders
  set
    total_ordered_qty = v_total_ordered,
    total_received_qty = v_total_received,
    status = case
      when status in ('cancelled') then status
      when v_total_received <= 0 then 'open'
      when v_total_received >= v_total_ordered * 0.98 then 'closed'
      else 'partial'
    end
  where id = p_order_id;
end;
$$;


ALTER FUNCTION "erp"."_recalc_purchase_order_inline"("p_order_id" "uuid") OWNER TO "postgres";

--
-- Name: _recalc_purchase_order_status("uuid", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_recalc_purchase_order_status"("p_order_id" "uuid", "p_force" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_order erp.purchase_orders%rowtype;
  v_total_ordered numeric;
  v_total_received numeric;
  v_tolerance constant numeric := 0.02;
begin
  select * into v_order from erp.purchase_orders where id = p_order_id for update;
  if not found then return; end if;
  if v_order.status = 'cancelled' then return; end if;
  if not p_force and v_order.status = 'closed' then return; end if;

  select coalesce(sum(qty_ordered), 0), coalesce(sum(qty_received), 0)
  into v_total_ordered, v_total_received
  from erp.purchase_order_lines
  where purchase_order_id = p_order_id;

  update erp.purchase_orders
  set
    total_ordered_qty = v_total_ordered,
    total_received_qty = v_total_received,
    status = case
      when v_total_received >= v_total_ordered * (1 - v_tolerance) then 'closed'
      when v_total_received > 0 then 'partial'
      else 'open'
    end
  where id = p_order_id;
end;
$$;


ALTER FUNCTION "erp"."_recalc_purchase_order_status"("p_order_id" "uuid", "p_force" boolean) OWNER TO "postgres";

