--
-- Name: _reclass_unallocated_to_advance("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_reclass_unallocated_to_advance"("p_payment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_pay erp.payments%rowtype;
  v_allocated numeric := 0;
  v_unalloc numeric;
  v_je_id uuid;
  v_ctrl_code text;
  v_adv_code text;
  v_line record;
  v_max_ln int;
  v_name text;
  v_already numeric;
begin
  -- Allow migration/ops batch via: select set_config('erp.skip_posting_access','1', true);
  if coalesce(current_setting('erp.skip_posting_access', true), '') <> '1' then
    perform erp._assert_posting_access();
  end if;

  select * into v_pay from erp.payments where id = p_payment_id for update;
  if not found then raise exception 'payment not found' using errcode = 'P0001'; end if;
  if v_pay.posting_status <> 'posted' or v_pay.voided_at is not null then
    raise exception 'payment must be posted and not voided' using errcode = 'P0001';
  end if;
  if v_pay.entry_kind not in ('party_receipt', 'party_payment') then
    raise exception 'only party_receipt / party_payment can be reclassed' using errcode = 'P0001';
  end if;

  select coalesce(sum(allocated_amount), 0) into v_allocated
  from erp.payment_allocations where payment_id = v_pay.id;
  v_unalloc := round(v_pay.amount - v_allocated, 3);

  v_already := round(coalesce(v_pay.advance_amount, 0) - coalesce(v_pay.advance_consumed, 0), 3);
  if v_unalloc <= 0.01 and v_already <= 0.01 then
    return jsonb_build_object('ok', true, 'skipped', true, 'reason', 'nothing to reclass');
  end if;
  if v_unalloc <= 0.01 then
    update erp.payments
       set is_advance = (coalesce(advance_amount, 0) > 0.01)
     where id = v_pay.id;
    return jsonb_build_object('ok', true, 'skipped', true, 'reason', 'fully allocated');
  end if;

  if v_pay.entry_kind = 'party_receipt' then
    v_ctrl_code := erp._resolve_posting_account('payment_receipt', 'ar');
    v_adv_code := erp._advance_account('customer');
  else
    v_ctrl_code := erp._resolve_posting_account('payment_payment', 'ap');
    v_adv_code := erp._advance_account('vendor');
  end if;

  select je.id into v_je_id
  from erp.journal_entries je
  where je.source_doc_type = 'payment'
    and je.source_doc_id = v_pay.id
    and je.voucher_type = 'PAYMENT'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
  order by je.posted_at nulls last, je.id
  limit 1;

  if v_je_id is null then
    raise exception 'PAYMENT journal entry not found for %', v_pay.payment_no using errcode = 'P0001';
  end if;

  if exists (
    select 1 from erp.journal_lines jl
    where jl.journal_entry_id = v_je_id
      and jl.account_code = v_adv_code
      and (
        (v_pay.entry_kind = 'party_receipt' and abs(jl.credit_amount - v_unalloc) <= 0.01)
        or (v_pay.entry_kind = 'party_payment' and abs(jl.debit_amount - v_unalloc) <= 0.01)
      )
  ) then
    update erp.payments
       set advance_amount = greatest(coalesce(advance_amount, 0), v_unalloc),
           is_advance = true
     where id = v_pay.id;
    return jsonb_build_object('ok', true, 'skipped', true, 'reason', 'advance line already present', 'advance_amount', v_unalloc);
  end if;

  select * into v_line
  from erp.journal_lines jl
  where jl.journal_entry_id = v_je_id
    and jl.account_code = v_ctrl_code
  order by jl.line_no
  limit 1;

  if not found then
    raise exception 'control account line % not found on JE for %', v_ctrl_code, v_pay.payment_no
      using errcode = 'P0001';
  end if;

  select name into v_name from erp.coa_accounts where code = v_adv_code;

  if v_allocated <= 0.01 then
    update erp.journal_lines
       set account_code = v_adv_code,
           account_name = coalesce(v_name, v_adv_code),
           line_description = case
             when v_pay.entry_kind = 'party_receipt' then 'Customer advance (reclassed)'
             else 'Vendor advance (reclassed)'
           end
     where id = v_line.id;
  else
    if v_pay.entry_kind = 'party_receipt' then
      if round(v_line.credit_amount, 3) < v_unalloc - 0.001 then
        raise exception 'credit line % too small to split unalloc %', v_line.credit_amount, v_unalloc
          using errcode = 'P0001';
      end if;
      update erp.journal_lines
         set credit_amount = round(credit_amount - v_unalloc, 3),
             line_description = coalesce(line_description, 'Settle receivable') || ' (allocated portion)'
       where id = v_line.id;
      select coalesce(max(line_no), 0) into v_max_ln from erp.journal_lines where journal_entry_id = v_je_id;
      insert into erp.journal_lines (
        journal_entry_id, line_no, account_code, account_name, party_id,
        debit_amount, credit_amount, line_description
      ) values (
        v_je_id, v_max_ln + 1, v_adv_code, coalesce(v_name, v_adv_code), v_pay.party_id,
        0, v_unalloc, 'Customer advance (reclassed unallocated)'
      );
    else
      if round(v_line.debit_amount, 3) < v_unalloc - 0.001 then
        raise exception 'debit line % too small to split unalloc %', v_line.debit_amount, v_unalloc
          using errcode = 'P0001';
      end if;
      update erp.journal_lines
         set debit_amount = round(debit_amount - v_unalloc, 3),
             line_description = coalesce(line_description, 'Settle payable') || ' (allocated portion)'
       where id = v_line.id;
      select coalesce(max(line_no), 0) into v_max_ln from erp.journal_lines where journal_entry_id = v_je_id;
      insert into erp.journal_lines (
        journal_entry_id, line_no, account_code, account_name, party_id,
        debit_amount, credit_amount, line_description
      ) values (
        v_je_id, v_max_ln + 1, v_adv_code, coalesce(v_name, v_adv_code), v_pay.party_id,
        v_unalloc, 0, 'Vendor advance (reclassed unallocated)'
      );
    end if;
  end if;

  perform erp._assert_je_balanced(v_je_id);

  update erp.payments
     set advance_amount = v_unalloc,
         advance_consumed = 0,
         is_advance = true
   where id = v_pay.id;

  return jsonb_build_object(
    'ok', true,
    'payment_id', v_pay.id,
    'payment_no', v_pay.payment_no,
    'advance_amount', v_unalloc,
    'advance_account', v_adv_code,
    'journal_entry_id', v_je_id
  );
end;
$$;


ALTER FUNCTION "erp"."_reclass_unallocated_to_advance"("p_payment_id" "uuid") OWNER TO "postgres";

--
-- Name: _reconcile_order_fulfillment_core(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_reconcile_order_fulfillment_core"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_sales_lines_adjusted int := 0;
  v_sales_lines_zeroed int := 0;
  v_purchase_lines_adjusted int := 0;
  v_purchase_lines_zeroed int := 0;
  v_so_recalced int := 0;
  v_po_recalced int := 0;
  v_header_drifts_before int := 0;
  v_order_id uuid;
begin
  select count(*) into v_header_drifts_before
  from (
    select so.id
    from erp.sales_orders so
    join erp.sales_order_lines sol on sol.sales_order_id = so.id
    group by so.id, so.total_fulfilled_qty
    having abs(so.total_fulfilled_qty - coalesce(sum(sol.qty_fulfilled), 0)) > 0.001
    union all
    select po.id
    from erp.purchase_orders po
    join erp.purchase_order_lines pol on pol.purchase_order_id = po.id
    group by po.id, po.total_received_qty
    having abs(po.total_received_qty - coalesce(sum(pol.qty_received), 0)) > 0.001
  ) drift;

  with updated as (
    update erp.sales_order_lines sol
    set qty_fulfilled = src.qty
    from (
      select sil.sales_order_line_id as id,
             sum(coalesce(sil.net_weight, sil.qty))::numeric as qty
      from erp.sales_invoice_lines sil
      join erp.sales_invoices si on si.id = sil.sales_invoice_id
      where sil.sales_order_line_id is not null
        and si.posting_status = 'posted'
      group by sil.sales_order_line_id
    ) src
    where sol.id = src.id
      and abs(sol.qty_fulfilled - src.qty) > 0.001
    returning sol.id
  )
  select count(*) into v_sales_lines_adjusted from updated;

  with zeroed as (
    update erp.sales_order_lines sol
    set qty_fulfilled = 0
    where sol.qty_fulfilled > 0.001
      and not exists (
        select 1
        from erp.sales_invoice_lines sil
        join erp.sales_invoices si on si.id = sil.sales_invoice_id
        where sil.sales_order_line_id = sol.id
          and si.posting_status = 'posted'
      )
    returning sol.id
  )
  select count(*) into v_sales_lines_zeroed from zeroed;

  with updated as (
    update erp.purchase_order_lines pol
    set qty_received = src.qty
    from (
      select pil.purchase_order_line_id as id,
             sum(coalesce(pil.net_weight, pil.qty))::numeric as qty
      from erp.purchase_invoice_lines pil
      join erp.purchase_invoices pi on pi.id = pil.purchase_invoice_id
      where pil.purchase_order_line_id is not null
        and pi.posting_status = 'posted'
      group by pil.purchase_order_line_id
    ) src
    where pol.id = src.id
      and abs(pol.qty_received - src.qty) > 0.001
    returning pol.id
  )
  select count(*) into v_purchase_lines_adjusted from updated;

  with zeroed as (
    update erp.purchase_order_lines pol
    set qty_received = 0
    where pol.qty_received > 0.001
      and not exists (
        select 1
        from erp.purchase_invoice_lines pil
        join erp.purchase_invoices pi on pi.id = pil.purchase_invoice_id
        where pil.purchase_order_line_id = pol.id
          and pi.posting_status = 'posted'
      )
    returning pol.id
  )
  select count(*) into v_purchase_lines_zeroed from zeroed;

  for v_order_id in select id from erp.sales_orders where status <> 'cancelled'
  loop
    perform erp._recalc_sales_order_status(v_order_id, true);
    v_so_recalced := v_so_recalced + 1;
  end loop;

  for v_order_id in select id from erp.purchase_orders where status <> 'cancelled'
  loop
    perform erp._recalc_purchase_order_status(v_order_id, true);
    v_po_recalced := v_po_recalced + 1;
  end loop;

  return jsonb_build_object(
    'sales_lines_adjusted', v_sales_lines_adjusted,
    'sales_lines_zeroed', v_sales_lines_zeroed,
    'purchase_lines_adjusted', v_purchase_lines_adjusted,
    'purchase_lines_zeroed', v_purchase_lines_zeroed,
    'sales_orders_recalced', v_so_recalced,
    'purchase_orders_recalced', v_po_recalced,
    'header_drifts_before', v_header_drifts_before
  );
end;
$$;


ALTER FUNCTION "erp"."_reconcile_order_fulfillment_core"() OWNER TO "postgres";

--
-- Name: _redistribute_batch_varnish_cost("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_redistribute_batch_varnish_cost"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_total_varnish numeric := 0;
  v_enameled_kg numeric := 0;
  v_before_non_enameled numeric := 0;
  v_allocated numeric := 0;
  v_remainder numeric := 0;
  v_last_enameled_id uuid;
begin
  select
    coalesce(sum(coalesce(im.cost_varnish, 0)), 0),
    coalesce(sum(im.qty_in) filter (where erp._is_enameled_output_item(im.item_id)), 0),
    coalesce(sum(coalesce(im.cost_varnish, 0)) filter (
      where not erp._is_enameled_output_item(im.item_id)
    ), 0)
  into v_total_varnish, v_enameled_kg, v_before_non_enameled
  from erp.inventory_movements im
  where im.source_doc_type = 'production_batch'
    and im.source_doc_id = p_batch_id
    and im.movement_type = 'production_receipt'
    and coalesce(im.qty_in, 0) > 0;

  if abs(v_total_varnish) <= 0.001 then
    return jsonb_build_object(
      'batch_id', p_batch_id,
      'varnish_total', 0,
      'moved_from_non_enameled', 0,
      'enameled_output_kg', v_enameled_kg
    );
  end if;

  if v_enameled_kg <= 0 then
    raise exception 'Production batch % consumes varnish but has no enameled-wire receipt', p_batch_id
      using errcode = '23514';
  end if;

  select im.id into v_last_enameled_id
  from erp.inventory_movements im
  where im.source_doc_type = 'production_batch'
    and im.source_doc_id = p_batch_id
    and im.movement_type = 'production_receipt'
    and coalesce(im.qty_in, 0) > 0
    and erp._is_enameled_output_item(im.item_id)
  order by im.created_at desc, im.id desc
  limit 1;

  with allocation as (
    select
      im.id,
      coalesce(im.cost_varnish, 0) as old_varnish,
      case
        when erp._is_enameled_output_item(im.item_id)
          then round(v_total_varnish * im.qty_in / v_enameled_kg, 3)
        else 0::numeric
      end as new_varnish
    from erp.inventory_movements im
    where im.source_doc_type = 'production_batch'
      and im.source_doc_id = p_batch_id
      and im.movement_type = 'production_receipt'
      and coalesce(im.qty_in, 0) > 0
  )
  update erp.inventory_movements im
  set cost_varnish = a.new_varnish,
      value_amount = round(coalesce(im.value_amount, 0) - a.old_varnish + a.new_varnish, 3),
      unit_cost = round(
        (coalesce(im.value_amount, 0) - a.old_varnish + a.new_varnish)
        / nullif(im.qty_in, 0),
        6
      )
  from allocation a
  where im.id = a.id;

  select coalesce(sum(coalesce(im.cost_varnish, 0)), 0)
  into v_allocated
  from erp.inventory_movements im
  where im.source_doc_type = 'production_batch'
    and im.source_doc_id = p_batch_id
    and im.movement_type = 'production_receipt';

  v_remainder := round(v_total_varnish - v_allocated, 3);
  if abs(v_remainder) > 0 then
    update erp.inventory_movements im
    set cost_varnish = round(coalesce(im.cost_varnish, 0) + v_remainder, 3),
        value_amount = round(coalesce(im.value_amount, 0) + v_remainder, 3),
        unit_cost = round(
          (coalesce(im.value_amount, 0) + v_remainder) / nullif(im.qty_in, 0),
          6
        )
    where im.id = v_last_enameled_id;
  end if;

  return jsonb_build_object(
    'batch_id', p_batch_id,
    'varnish_total', round(v_total_varnish, 3),
    'moved_from_non_enameled', round(v_before_non_enameled, 3),
    'enameled_output_kg', round(v_enameled_kg, 3)
  );
end;
$$;


ALTER FUNCTION "erp"."_redistribute_batch_varnish_cost"("p_batch_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "_redistribute_batch_varnish_cost"("p_batch_id" "uuid"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_redistribute_batch_varnish_cost"("p_batch_id" "uuid") IS 'Preserves total batch value while assigning its entire varnish component only to enameled-wire receipts.';


--
-- Name: _reduce_ap_open("uuid", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_reduce_ap_open"("p_party_id" "uuid", "p_amount" numeric) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_remaining numeric := coalesce(p_amount, 0);
  v_row record;
begin
  if v_remaining <= 0 or p_party_id is null then
    return coalesce(p_amount, 0);
  end if;

  for v_row in
    select id, open_amount
    from erp.ap_documents
    where party_id = p_party_id
      and status in ('open', 'partially_settled')
      and open_amount > 0
    order by doc_date, id
  loop
    exit when v_remaining <= 0;
    if v_row.open_amount >= v_remaining then
      update erp.ap_documents
      set
        open_amount = open_amount - v_remaining,
        status = case when open_amount - v_remaining <= 0.01 then 'settled' else 'partially_settled' end
      where id = v_row.id;
      v_remaining := 0;
    else
      update erp.ap_documents set open_amount = 0, status = 'settled' where id = v_row.id;
      v_remaining := v_remaining - v_row.open_amount;
    end if;
  end loop;

  return coalesce(p_amount, 0) - v_remaining;
end;
$$;


