--
-- Name: _refresh_doc_financial_status("text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_refresh_doc_financial_status"("p_doc_type" "text", "p_doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_pending int := 0;
  v_fixed int := 0;
  v_status text := 'complete';
begin
  if p_doc_type = 'sales_invoice' then
    select
      count(*) filter (where rate_status = 'pending'),
      count(*) filter (where rate_status = 'fixed')
    into v_pending, v_fixed
    from erp.sales_invoice_lines where sales_invoice_id = p_doc_id;
    update erp.sales_invoices set financial_status = case
      when v_pending > 0 and v_fixed > 0 then 'partial'
      when v_pending > 0 then 'pending'
      else 'complete' end where id = p_doc_id;

  elsif p_doc_type = 'purchase_invoice' then
    select
      count(*) filter (where rate_status = 'pending'),
      count(*) filter (where rate_status = 'fixed')
    into v_pending, v_fixed
    from erp.purchase_invoice_lines where purchase_invoice_id = p_doc_id;
    update erp.purchase_invoices set financial_status = case
      when v_pending > 0 and v_fixed > 0 then 'partial'
      when v_pending > 0 then 'pending'
      else 'complete' end where id = p_doc_id;

  elsif p_doc_type = 'sales_return' then
    select
      count(*) filter (where rate_status = 'pending'),
      count(*) filter (where rate_status = 'fixed')
    into v_pending, v_fixed
    from erp.sales_return_lines where sales_return_id = p_doc_id;
    update erp.sales_returns set financial_status = case
      when v_pending > 0 and v_fixed > 0 then 'partial'
      when v_pending > 0 then 'pending'
      else 'complete' end where id = p_doc_id;

  elsif p_doc_type = 'purchase_return' then
    select
      count(*) filter (where rate_status = 'pending'),
      count(*) filter (where rate_status = 'fixed')
    into v_pending, v_fixed
    from erp.purchase_return_lines where purchase_return_id = p_doc_id;
    update erp.purchase_returns set financial_status = case
      when v_pending > 0 and v_fixed > 0 then 'partial'
      when v_pending > 0 then 'pending'
      else 'complete' end where id = p_doc_id;

  elsif p_doc_type = 'scrap_trade' then
    select case when rate_status = 'pending' then 1 else 0 end,
           case when rate_status = 'fixed' then 1 else 0 end
    into v_pending, v_fixed
    from erp.scrap_trades where id = p_doc_id;
    update erp.scrap_trades set financial_status = case
      when v_pending > 0 then 'pending'
      else 'complete' end where id = p_doc_id;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_refresh_doc_financial_status"("p_doc_type" "text", "p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: _refresh_doc_header_totals("text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_refresh_doc_header_totals"("p_doc_type" "text", "p_doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_subtotal numeric := 0;
  v_discount numeric := 0;
  v_tax_rate numeric := 0;
  v_tax_amt numeric := 0;
  v_grand numeric := 0;
  v_old_subtotal numeric := 0;
begin
  if p_doc_type = 'sales_invoice' then
    select coalesce(sum(l.line_amount), 0) into v_subtotal
    from erp.sales_invoice_lines l
    where l.sales_invoice_id = p_doc_id;

    select coalesce(si.discount_amount, 0), coalesce(si.subtotal_amount, 0)
    into v_discount, v_old_subtotal
    from erp.sales_invoices si where si.id = p_doc_id;

    select coalesce(max(l.tax_rate), 0) into v_tax_rate
    from erp.sales_invoice_lines l where l.sales_invoice_id = p_doc_id;

    if v_old_subtotal > 0 and v_subtotal > 0 then
      select coalesce(si.tax_amount, 0) * v_subtotal / v_old_subtotal into v_tax_amt
      from erp.sales_invoices si where si.id = p_doc_id;
    else
      v_tax_amt := round(greatest(v_subtotal - v_discount, 0) * v_tax_rate / 100, 3);
    end if;
    v_grand := v_subtotal - v_discount + v_tax_amt;

    update erp.sales_invoices
    set subtotal_amount = v_subtotal,
        tax_amount = v_tax_amt,
        grand_total = v_grand
    where id = p_doc_id;

  elsif p_doc_type = 'purchase_invoice' then
    select coalesce(sum(l.line_amount), 0) into v_subtotal
    from erp.purchase_invoice_lines l
    where l.purchase_invoice_id = p_doc_id;

    select coalesce(pi.additional_charges, 0) into v_discount
    from erp.purchase_invoices pi where pi.id = p_doc_id;

    v_grand := v_subtotal + v_discount;

    update erp.purchase_invoices
    set subtotal_amount = v_subtotal,
        grand_total = v_grand
    where id = p_doc_id;

  elsif p_doc_type = 'sales_return' then
    select coalesce(sum(l.line_amount), 0) into v_grand
    from erp.sales_return_lines l
    where l.sales_return_id = p_doc_id;

    update erp.sales_returns set grand_total = v_grand, subtotal_amount = v_grand where id = p_doc_id;

  elsif p_doc_type = 'purchase_return' then
    select coalesce(sum(l.line_amount), 0) into v_grand
    from erp.purchase_return_lines l
    where l.purchase_return_id = p_doc_id;

    update erp.purchase_returns set grand_total = v_grand where id = p_doc_id;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_refresh_doc_header_totals"("p_doc_type" "text", "p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: _reject_negative_line_values(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_reject_negative_line_values"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v jsonb := to_jsonb(new);
  k text;
  v_keys text[] := array[
    'unit_price', 'line_amount', 'qty', 'net_weight',
    'gross_weight', 'tare_weight', 'watta_rate', 'amount', 'credit_amount'
  ];
begin
  foreach k in array v_keys loop
    if (v ? k) and nullif(v->>k, '') is not null and (v->>k)::numeric < 0 then
      raise exception 'negative % is not allowed on document lines', k using errcode = '23514';
    end if;
  end loop;
  return new;
end;
$$;


ALTER FUNCTION "erp"."_reject_negative_line_values"() OWNER TO "postgres";

