--
-- Name: _replace_production_batch_changed_lines("uuid", "date", "jsonb", "uuid", numeric, numeric, numeric, boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_replace_production_batch_changed_lines"("p_batch_id" "uuid", "p_batch_date" "date", "p_lines" "jsonb", "p_machine_id" "uuid" DEFAULT NULL::"uuid", "p_input_kg" numeric DEFAULT NULL::numeric, "p_output_kg" numeric DEFAULT NULL::numeric, "p_scrap_kg" numeric DEFAULT NULL::numeric, "p_post" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $_$
declare
  v_batch erp.production_batches%rowtype;
  v_line jsonb;
  v_idx int := 0;
  v_item_id uuid;
  v_wh_id uuid;
  v_old_item_ids uuid[] := '{}';
  v_item_ids uuid[] := '{}';
  v_keep_line_ids uuid[] := '{}';
  v_line_id uuid;
  v_requested_line_id uuid;
  v_line_type text;
  v_item_code text;
  v_wh_type text;
  v_scrap_cat text;
  v_line_machine uuid;
  v_db_line erp.production_batch_lines%rowtype;
  v_movement erp.inventory_movements%rowtype;
  v_expected_movement_type text;
  v_qty_in numeric;
  v_qty_out numeric;
  v_units_in numeric;
  v_units_out numeric;
  v_effective_units numeric;
  v_cost numeric;
  v_in numeric;
  v_out numeric;
  v_scrap numeric;
  v_machines uuid[];
begin
  perform erp._assert_posting_access();

  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'at least one production line is required';
  end if;

  select * into v_batch
  from erp.production_batches
  where id = p_batch_id
  for update;
  if not found then
    raise exception 'production batch not found';
  end if;

  select coalesce(array_agg(distinct item_id), '{}')
  into v_old_item_ids
  from (
    select item_id
    from erp.production_batch_lines
    where production_batch_id = p_batch_id
    union
    select item_id
    from erp.inventory_movements
    where source_doc_type = 'production_batch' and source_doc_id = p_batch_id
  ) old_items;

  update erp.production_batches
  set status = 'draft',
      batch_date = p_batch_date,
      posted_at = null,
      posted_by = null,
      machine_id = p_machine_id,
      input_kg = coalesce(p_input_kg, 0),
      output_kg = coalesce(p_output_kg, 0),
      scrap_kg = coalesce(p_scrap_kg, 0)
  where id = p_batch_id;

  -- Preserve explicit receipt line IDs supplied by the editor. Auto-generated
  -- issue lines have no ID, so match them by their stable semantic identity.
  for v_line in select value from jsonb_array_elements(p_lines) as t(value)
  loop
    v_idx := v_idx + 1;
    v_line_type := v_line->>'lineType';
    v_item_code := v_line->>'itemCode';
    v_wh_type := v_line->>'warehouseType';
    v_scrap_cat := v_line->>'scrapCategory';
    v_line_machine := nullif(v_line->>'machineId', '')::uuid;
    v_requested_line_id := null;

    if coalesce(v_line->>'lineId', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      v_requested_line_id := (v_line->>'lineId')::uuid;
    end if;

    if v_line_type is null or v_item_code is null or v_wh_type is null then
      raise exception 'invalid line payload at index %', v_idx;
    end if;

    select id into v_item_id from erp.items where code = v_item_code limit 1;
    if v_item_id is null then
      raise exception 'item not found: %', v_item_code;
    end if;

    select id into v_wh_id
    from erp.warehouses
    where wh_type = v_wh_type and is_active = true
    limit 1;
    if v_wh_id is null then
      raise exception 'warehouse not found for type %', v_wh_type;
    end if;

    v_line_id := null;
    if v_requested_line_id is not null then
      select id into v_line_id
      from erp.production_batch_lines
      where id = v_requested_line_id and production_batch_id = p_batch_id
      for update;
      if v_line_id is null then
        raise exception 'production line % does not belong to batch %', v_requested_line_id, p_batch_id;
      end if;
    else
      select pbl.id into v_line_id
      from erp.production_batch_lines pbl
      where pbl.production_batch_id = p_batch_id
        and pbl.line_type = v_line_type
        and pbl.item_id = v_item_id
        and pbl.warehouse_id = v_wh_id
        and pbl.machine_id is not distinct from coalesce(v_line_machine, p_machine_id)
        and pbl.scrap_category is not distinct from v_scrap_cat
        and not (pbl.id = any(v_keep_line_ids))
      order by pbl.line_no, pbl.id
      limit 1
      for update;
    end if;

    if v_line_id is null then
      insert into erp.production_batch_lines (
        production_batch_id, line_no, line_type, item_id, warehouse_id,
        gross_weight, tare_weight, net_weight, scrap_weight, unit_count,
        machine_id, scrap_category
      ) values (
        p_batch_id, v_idx, v_line_type, v_item_id, v_wh_id,
        coalesce((v_line->>'grossWeight')::numeric, 0),
        coalesce((v_line->>'tareWeight')::numeric, 0),
        coalesce((v_line->>'netWeight')::numeric, 0),
        coalesce((v_line->>'scrapWeight')::numeric, 0),
        coalesce((v_line->>'unitCount')::numeric, 0),
        coalesce(v_line_machine, p_machine_id),
        v_scrap_cat
      ) returning id into v_line_id;
    else
      update erp.production_batch_lines
      set line_no = v_idx,
          line_type = v_line_type,
          item_id = v_item_id,
          warehouse_id = v_wh_id,
          gross_weight = coalesce((v_line->>'grossWeight')::numeric, 0),
          tare_weight = coalesce((v_line->>'tareWeight')::numeric, 0),
          net_weight = coalesce((v_line->>'netWeight')::numeric, 0),
          scrap_weight = coalesce((v_line->>'scrapWeight')::numeric, 0),
          unit_count = coalesce((v_line->>'unitCount')::numeric, 0),
          machine_id = coalesce(v_line_machine, p_machine_id),
          scrap_category = v_scrap_cat
      where id = v_line_id;
    end if;

    v_keep_line_ids := array_append(v_keep_line_ids, v_line_id);
  end loop;

  -- Removed lines are the only old lines whose movement should be removed.
  for v_db_line in
    select *
    from erp.production_batch_lines
    where production_batch_id = p_batch_id
      and not (id = any(v_keep_line_ids))
    order by line_no, id
    for update
  loop
    delete from erp.inventory_movements
    where source_doc_type = 'production_batch'
      and source_doc_id = p_batch_id
      and source_line_id = v_db_line.id;
    delete from erp.production_batch_lines where id = v_db_line.id;
  end loop;

  if not p_post then
    -- A draft has no inventory effect. Unlike posted-to-posted edits, removing
    -- all movements is the intended final state and normal stock guards apply.
    delete from erp.inventory_movements
    where source_doc_type = 'production_batch' and source_doc_id = p_batch_id;

    if coalesce(array_length(v_old_item_ids, 1), 0) > 0 then
      perform erp.rebuild_inventory_balances_for_items(v_old_item_ids);
    end if;
    return jsonb_build_object('ok', true, 'batch_id', p_batch_id, 'posted', false);
  end if;

  perform erp._validate_production_mass_balance(p_batch_id);

  -- Synchronize one movement per retained/new line. Unchanged movements are
  -- not updated, so their IDs and historical inventory effect remain intact.
  for v_db_line in
    select *
    from erp.production_batch_lines
    where production_batch_id = p_batch_id
    order by line_no, id
    for update
  loop
    v_expected_movement_type := null;
    v_qty_in := 0;
    v_qty_out := 0;
    v_units_in := 0;
    v_units_out := 0;
    v_effective_units := erp._effective_line_unit_count(v_db_line.item_id, v_db_line.unit_count);
    if v_effective_units <= 0 and v_db_line.line_type = 'issue' and coalesce(v_db_line.net_weight, 0) > 0 then
      v_effective_units := erp._varnish_units_from_kg(v_db_line.item_id, v_db_line.net_weight);
    end if;

    if v_db_line.line_type = 'issue' and coalesce(v_db_line.net_weight, 0) > 0 then
      v_expected_movement_type := 'production_issue';
      v_qty_out := v_db_line.net_weight;
      v_units_out := v_effective_units;
    elsif v_db_line.line_type = 'receipt' and coalesce(v_db_line.net_weight, 0) > 0 then
      v_expected_movement_type := 'production_receipt';
      v_qty_in := v_db_line.net_weight;
      v_units_in := v_effective_units;
    elsif v_db_line.line_type = 'scrap'
       and coalesce(v_db_line.scrap_weight, v_db_line.net_weight, 0) > 0 then
      v_expected_movement_type := 'scrap_in';
      v_qty_in := coalesce(v_db_line.scrap_weight, v_db_line.net_weight);
      v_units_in := v_effective_units;
    end if;

    select * into v_movement
    from erp.inventory_movements
    where source_doc_type = 'production_batch'
      and source_doc_id = p_batch_id
      and source_line_id = v_db_line.id
    order by created_at, id
    limit 1
    for update;

    if v_expected_movement_type is null then
      if found then
        delete from erp.inventory_movements
        where source_doc_type = 'production_batch'
          and source_doc_id = p_batch_id
          and source_line_id = v_db_line.id;
      end if;
      continue;
    end if;

    if found
       and v_movement.item_id = v_db_line.item_id
       and v_movement.warehouse_id = v_db_line.warehouse_id
       and v_movement.movement_type = v_expected_movement_type then
      if v_movement.posting_date is distinct from p_batch_date
         or coalesce(v_movement.qty_in, 0) is distinct from v_qty_in
         or coalesce(v_movement.qty_out, 0) is distinct from v_qty_out
         or coalesce(v_movement.units_in, 0) is distinct from v_units_in
         or coalesce(v_movement.units_out, 0) is distinct from v_units_out then
        update erp.inventory_movements
        set posting_date = p_batch_date,
            qty_in = v_qty_in,
            qty_out = v_qty_out,
            units_in = v_units_in,
            units_out = v_units_out
        where id = v_movement.id;
      end if;

      delete from erp.inventory_movements
      where source_doc_type = 'production_batch'
        and source_doc_id = p_batch_id
        and source_line_id = v_db_line.id
        and id <> v_movement.id;
    else
      delete from erp.inventory_movements
      where source_doc_type = 'production_batch'
        and source_doc_id = p_batch_id
        and source_line_id = v_db_line.id;

      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id,
        qty_in, qty_out, units_in, units_out, value_amount,
        source_doc_type, source_doc_id, source_line_id
      ) values (
        p_batch_date, v_expected_movement_type, v_db_line.item_id, v_db_line.warehouse_id,
        v_qty_in, v_qty_out, v_units_in, v_units_out, 0,
        'production_batch', p_batch_id, v_db_line.id
      );
    end if;
  end loop;

  v_cost := erp._apply_production_batch_costing(p_batch_id);
  perform erp._sync_production_batch_gl(p_batch_id);

  select t.input_kg, t.output_kg, t.scrap_kg
  into v_in, v_out, v_scrap
  from erp._production_batch_totals(p_batch_id) t;

  update erp.production_batches
  set status = 'posted',
      posted_at = now(),
      posted_by = auth.uid(),
      input_kg = v_in,
      output_kg = v_out,
      scrap_kg = v_scrap
  where id = p_batch_id;

  select coalesce(array_agg(distinct item_id), '{}')
  into v_item_ids
  from (
    select unnest(v_old_item_ids) as item_id
    union
    select item_id
    from erp.production_batch_lines
    where production_batch_id = p_batch_id
    union
    select item_id
    from erp.inventory_movements
    where source_doc_type = 'production_batch' and source_doc_id = p_batch_id
  ) affected;

  perform erp._rebuild_after_document_post(v_item_ids);

  select coalesce(array_agg(distinct coalesce(pbl.machine_id, p_machine_id)), '{}')
  into v_machines
  from erp.production_batch_lines pbl
  where pbl.production_batch_id = p_batch_id
    and coalesce(pbl.machine_id, p_machine_id) is not null;

  perform erp.fn_evaluate_production_alerts(
    erp._production_alert_eval_as_of(p_batch_date, v_machines)
  );

  return jsonb_build_object('ok', true, 'batch_id', p_batch_id, 'posted', true);
end;
$_$;


ALTER FUNCTION "erp"."_replace_production_batch_changed_lines"("p_batch_id" "uuid", "p_batch_date" "date", "p_lines" "jsonb", "p_machine_id" "uuid", "p_input_kg" numeric, "p_output_kg" numeric, "p_scrap_kg" numeric, "p_post" boolean) OWNER TO "postgres";

--
-- Name: _reprice_purchase_invoice_without_stock_replay("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_reprice_purchase_invoice_without_stock_replay"("p_doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_invoices%rowtype;
  v_je_id uuid;
  v_inv text;
  v_ap text;
  v_tax text;
  v_tax_amt numeric;
  v_net numeric;
  v_grand numeric;
  v_fixed_subtotal numeric;
  v_ln int := 0;
  v_item_ids uuid[] := '{}';
  v_ap_doc_id uuid;
  v_ap_doc_party_id uuid;
  v_allocated numeric := 0;
  v_open numeric := 0;
begin
  perform erp._assert_posting_access();

  select * into v_doc from erp.purchase_invoices where id = p_doc_id for update;
  if not found then raise exception 'purchase invoice not found'; end if;
  if v_doc.posting_status <> 'posted' then
    raise exception 'only posted purchase invoices can be repriced without stock replay';
  end if;

  select ad.id, ad.party_id, coalesce(sum(pa.allocated_amount), 0)
  into v_ap_doc_id, v_ap_doc_party_id, v_allocated
  from erp.ap_documents ad
  left join erp.payment_allocations pa on pa.ap_document_id = ad.id
  where ad.source_doc_type = 'purchase_invoice'
    and ad.source_doc_id = v_doc.id
  group by ad.id, ad.party_id
  order by coalesce(sum(pa.allocated_amount), 0) desc
  limit 1;

  if v_ap_doc_id is not null
     and v_allocated > 0
     and v_ap_doc_party_id is distinct from v_doc.party_id then
    raise exception 'cannot repost: allocated purchase invoice supplier cannot be changed';
  end if;

  v_inv := erp._resolve_posting_account('purchase_invoice', 'inventory');
  v_ap := erp._resolve_posting_account('purchase_invoice', 'ap');
  v_tax := erp._resolve_posting_account('purchase_invoice', 'input_tax');

  select coalesce(sum(l.line_amount), 0) into v_fixed_subtotal
  from erp.purchase_invoice_lines l
  where l.purchase_invoice_id = v_doc.id
    and coalesce(l.rate_status, 'fixed') = 'fixed';

  if coalesce(v_doc.subtotal_amount, 0) > 0 and v_fixed_subtotal > 0 then
    v_tax_amt := round(coalesce(v_doc.tax_amount, 0) * v_fixed_subtotal / v_doc.subtotal_amount, 3);
  else
    v_tax_amt := 0;
  end if;
  v_net := v_fixed_subtotal;
  v_grand := v_net + v_tax_amt;

  if coalesce(v_allocated, 0) > v_grand then
    raise exception 'cannot repost: allocated payments % exceed new invoice amount %', v_allocated, v_grand;
  end if;

  perform erp._void_pending_rate_items_for_doc('purchase_invoice', v_doc.id);
  perform erp._hard_delete_clear_journals('purchase_invoice', v_doc.id);

  with mov as (
    select im.id as movement_id,
           im.item_id,
           im.warehouse_id,
           row_number() over (
             partition by im.item_id, im.warehouse_id
             order by im.source_line_id nulls last, im.id
           ) as rn
    from erp.inventory_movements im
    where im.source_doc_type = 'purchase_invoice'
      and im.source_doc_id = v_doc.id
      and coalesce(im.qty_in, 0) > 0
      and coalesce(im.qty_out, 0) = 0
  ),
  lin as (
    select l.*,
           row_number() over (
             partition by l.item_id, l.warehouse_id
             order by l.line_no, l.id
           ) as rn
    from erp.purchase_invoice_lines l
    where l.purchase_invoice_id = v_doc.id
      and l.item_id is not null
      and coalesce(l.net_weight, l.qty, 0) > 0
  )
  update erp.inventory_movements im
  set source_line_id = lin.id,
      posting_date = v_doc.invoice_date,
      units_in = greatest(coalesce(lin.unit_count, 0), 0),
      unit_cost = case
        when coalesce(lin.rate_status, 'fixed') = 'pending' then 0
        when coalesce(lin.net_weight, lin.qty, 0) > 0 then round(lin.line_amount / coalesce(lin.net_weight, lin.qty, 0), 6)
        else 0
      end,
      value_amount = case when coalesce(lin.rate_status, 'fixed') = 'pending' then 0 else lin.line_amount end,
      party_id = v_doc.party_id
  from lin
  join mov
    on mov.item_id = lin.item_id
   and mov.warehouse_id = lin.warehouse_id
   and mov.rn = lin.rn
  where im.id = mov.movement_id
    and im.item_id = lin.item_id
    and im.warehouse_id = lin.warehouse_id;

  insert into erp.pending_rate_items (
    source_doc_type, source_doc_id, source_line_id, source_doc_no, line_seq,
    party_id, item_id, warehouse_id, qty, original_posting_date, pending_reason, status
  )
  select
    'purchase_invoice', v_doc.id, l.id, v_doc.invoice_no, l.line_no,
    v_doc.party_id, l.item_id, l.warehouse_id, coalesce(l.net_weight, l.qty, 0), v_doc.invoice_date, 'rate', 'open'
  from erp.purchase_invoice_lines l
  where l.purchase_invoice_id = v_doc.id
    and l.item_id is not null
    and coalesce(l.net_weight, l.qty, 0) > 0
    and coalesce(l.rate_status, 'fixed') = 'pending';

  select coalesce(array_agg(distinct l.item_id) filter (where l.item_id is not null), '{}')
  into v_item_ids
  from erp.purchase_invoice_lines l
  where l.purchase_invoice_id = v_doc.id;

  if v_grand > 0 then
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
    ) values (
      v_doc.invoice_no, 'PURCHASE_INVOICE', v_doc.invoice_date, 'purchase_invoice', v_doc.id, v_doc.invoice_no,
      coalesce(v_doc.remarks, 'Purchase invoice posted'), 'posted', now(), auth.uid()
    ) returning id into v_je_id;

    if v_net > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, v_net, 0, 'Inventory');
    end if;
    if v_tax_amt > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_tax, null, v_tax_amt, 0, 'Input Tax');
    end if;
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_ap, v_doc.party_id, 0, v_grand, 'Accounts Payable');
  end if;

  v_open := v_grand - coalesce(v_allocated, 0);

  if v_ap_doc_id is not null then
    update erp.ap_documents
    set party_id = v_doc.party_id,
        source_doc_no = v_doc.invoice_no,
        doc_date = v_doc.invoice_date,
        due_date = coalesce(v_doc.due_date, v_doc.invoice_date),
        amount = v_grand,
        open_amount = v_open,
        status = case
          when v_open <= 0 then 'settled'
          when v_open < v_grand then 'partially_settled'
          else 'open'
        end
    where id = v_ap_doc_id;
  elsif v_grand > 0 then
    insert into erp.ap_documents (
      party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status
    ) values (
      v_doc.party_id, 'purchase_invoice', v_doc.id, v_doc.invoice_no, v_doc.invoice_date,
      coalesce(v_doc.due_date, v_doc.invoice_date), v_grand, v_open,
      case
        when v_open <= 0 then 'settled'
        when v_open < v_grand then 'partially_settled'
        else 'open'
      end
    );
  end if;

  perform erp._rebuild_after_document_post(v_item_ids);
  perform erp._refresh_doc_financial_status('purchase_invoice', v_doc.id);

  update erp.purchase_invoices
  set posting_status = 'posted', posted_at = now(), posted_by = auth.uid()
  where id = v_doc.id;
end;
$$;


ALTER FUNCTION "erp"."_reprice_purchase_invoice_without_stock_replay"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: _resolve_adjustment_unit_cost("uuid", "uuid", "text", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_resolve_adjustment_unit_cost"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_direction" "text", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_wac numeric := 0;
  v_on_hand numeric := 0;
  v_standard numeric := 0;
  v_valuation numeric := 0;
begin
  v_on_hand := erp._inventory_on_hand(p_item_id, p_warehouse_id);
  v_wac := erp._inventory_replay_current_wac(p_item_id, p_warehouse_id);
  if coalesce(v_wac, 0) > 0 then return round(v_wac, 6); end if;
  select coalesce(ib.avg_unit_cost, 0) into v_wac from erp.inventory_balances ib where ib.item_id = p_item_id and ib.warehouse_id = p_warehouse_id;
  if coalesce(v_wac, 0) > 0 then return round(v_wac, 6); end if;
  select coalesce(i.standard_cost, 0) into v_standard from erp.items i where i.id = p_item_id;
  if coalesce(v_standard, 0) > 0 then return round(v_standard, 6); end if;
  v_valuation := coalesce(erp.resolve_inventory_valuation_rate(p_item_id, p_as_of), 0);
  if coalesce(v_valuation, 0) > 0 then return round(v_valuation, 6); end if;
  if p_direction = 'in' and coalesce(v_on_hand, 0) <= 0 then
    raise exception 'Cannot value adjustment in for item %: no book WAC, standard cost, or valuation rate', (select code from erp.items where id = p_item_id);
  end if;
  return 0;
end;
$$;


ALTER FUNCTION "erp"."_resolve_adjustment_unit_cost"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_direction" "text", "p_as_of" "date") OWNER TO "postgres";

--
-- Name: _resolve_posting_account("text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_resolve_posting_account"("p_doc_type" "text", "p_line_role" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_code text;
begin
  select pam.account_code into v_code
  from erp.posting_account_map pam
  where pam.doc_type = p_doc_type
    and pam.line_role = p_line_role
    and pam.is_active = true
    and pam.effective_from <= current_date
  order by pam.effective_from desc
  limit 1;
  if v_code is null then
    raise exception 'Missing posting map: % / %', p_doc_type, p_line_role;
  end if;
  return v_code;
end;
$$;


ALTER FUNCTION "erp"."_resolve_posting_account"("p_doc_type" "text", "p_line_role" "text") OWNER TO "postgres";

--
-- Name: _restamp_purchase_reprice_sales_cogs_for_item_wh("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_restamp_purchase_reprice_sales_cogs_for_item_wh"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_anchor_mov_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_anchor erp.inventory_movements%rowtype;
  v_mov record;
  v_state record;
  v_wac numeric;
  v_new_val numeric;
  v_c_amt numeric;
  v_v_amt numeric;
  v_p_amt numeric;
  v_o_amt numeric;
  v_sales_fixed int := 0;
  v_period_draft_fixed int := 0;
  v_locked_or_final_skipped int := 0;
  v_invoice_ids uuid[] := '{}';
  v_invoice_id uuid;
  v_gl_fixed int := 0;
  v_norm record;
begin
  if p_item_id is null or p_warehouse_id is null then
    return jsonb_build_object(
      'sales_out_restamped', 0,
      'period_draft_sales_restamped', 0,
      'locked_or_final_sales_skipped', 0,
      'invoices_gl_synced', 0
    );
  end if;

  if p_anchor_mov_id is not null then
    select * into v_anchor from erp.inventory_movements where id = p_anchor_mov_id;
    if not found then
      return jsonb_build_object(
        'sales_out_restamped', 0,
        'period_draft_sales_restamped', 0,
        'locked_or_final_sales_skipped', 0,
        'invoices_gl_synced', 0
      );
    end if;
  end if;

  select count(*) into v_locked_or_final_skipped
  from erp.inventory_movements im
  where im.item_id = p_item_id
    and im.warehouse_id = p_warehouse_id
    and im.movement_type = 'sales_out'
    and coalesce(im.qty_out, 0) > 0
    and (
      coalesce(im.cost_status, 'provisional') = 'period_final'
      or exists (
        select 1
        from erp.costing_periods cp
        where cp.status = 'locked'
          and im.posting_date between cp.start_date and cp.end_date
      )
    )
    and (
      p_anchor_mov_id is null
      or im.posting_date > v_anchor.posting_date
      or (im.posting_date = v_anchor.posting_date and im.created_at > v_anchor.created_at)
      or (
        im.posting_date = v_anchor.posting_date
        and im.created_at = v_anchor.created_at
        and im.id > v_anchor.id
      )
    );

  for v_mov in
    select im.*
    from erp.inventory_movements im
    where im.item_id = p_item_id
      and im.warehouse_id = p_warehouse_id
      and im.movement_type = 'sales_out'
      and coalesce(im.qty_out, 0) > 0
      and coalesce(im.cost_status, 'provisional') in ('provisional', 'period_draft')
      and not exists (
        select 1
        from erp.costing_periods cp
        where cp.status = 'locked'
          and im.posting_date between cp.start_date and cp.end_date
      )
      and (
        p_anchor_mov_id is null
        or im.posting_date > v_anchor.posting_date
        or (im.posting_date = v_anchor.posting_date and im.created_at > v_anchor.created_at)
        or (
          im.posting_date = v_anchor.posting_date
          and im.created_at = v_anchor.created_at
          and im.id > v_anchor.id
        )
      )
    order by im.posting_date, im.created_at, im.id
  loop
    select * into v_state
    from erp._inventory_replay_state(v_mov.item_id, v_mov.warehouse_id, v_mov.id);
    v_wac := coalesce(v_state.avg_unit_cost, 0);
    v_new_val := round(v_mov.qty_out * v_wac, 3);
    v_c_amt := round(v_mov.qty_out * coalesce(v_state.copper_unit_cost, 0), 3);
    v_v_amt := round(v_mov.qty_out * coalesce(v_state.varnish_unit_cost, 0), 3);
    v_p_amt := round(v_mov.qty_out * coalesce(v_state.packing_unit_cost, 0), 3);
    v_o_amt := round(v_mov.qty_out * coalesce(v_state.oh_unit_cost, 0), 3);

    select * into v_norm
    from erp._normalize_cogs_components(v_new_val, v_c_amt, v_v_amt, v_p_amt, v_o_amt);
    v_c_amt := v_norm.o_copper;
    v_v_amt := v_norm.o_varnish;
    v_p_amt := v_norm.o_packing;
    v_o_amt := round(coalesce(v_norm.o_oh, 0) + coalesce(v_norm.o_clearing, 0), 3);

    if v_mov.unit_cost is distinct from v_wac
       or v_mov.value_amount is distinct from v_new_val
       or v_mov.cost_copper is distinct from v_c_amt
       or v_mov.cost_varnish is distinct from v_v_amt
       or v_mov.cost_packing is distinct from v_p_amt
       or v_mov.cost_oh is distinct from v_o_amt then
      update erp.inventory_movements
      set unit_cost = v_wac,
          value_amount = v_new_val,
          cost_copper = v_c_amt,
          cost_varnish = v_v_amt,
          cost_packing = v_p_amt,
          cost_oh = v_o_amt
      where id = v_mov.id;
      v_sales_fixed := v_sales_fixed + 1;
      if coalesce(v_mov.cost_status, 'provisional') = 'period_draft' then
        v_period_draft_fixed := v_period_draft_fixed + 1;
      end if;
    end if;

    if v_mov.source_doc_type = 'sales_invoice'
       and v_mov.source_doc_id is not null
       and not (v_mov.source_doc_id = any(v_invoice_ids)) then
      v_invoice_ids := array_append(v_invoice_ids, v_mov.source_doc_id);
    end if;
  end loop;

  foreach v_invoice_id in array v_invoice_ids loop
    if erp._sync_sales_invoice_cogs_gl(v_invoice_id) then
      v_gl_fixed := v_gl_fixed + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'sales_out_restamped', v_sales_fixed,
    'period_draft_sales_restamped', v_period_draft_fixed,
    'locked_or_final_sales_skipped', v_locked_or_final_skipped,
    'invoices_touched', cardinality(v_invoice_ids),
    'invoices_gl_synced', v_gl_fixed
  );
end;
$$;


ALTER FUNCTION "erp"."_restamp_purchase_reprice_sales_cogs_for_item_wh"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_anchor_mov_id" "uuid") OWNER TO "postgres";

--
-- Name: _restamp_sales_cogs_for_item_wh("uuid", "uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_restamp_sales_cogs_for_item_wh"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_anchor_mov_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_anchor erp.inventory_movements%rowtype;
  v_mov record;
  v_state record;
  v_wac numeric;
  v_new_val numeric;
  v_c_amt numeric;
  v_v_amt numeric;
  v_p_amt numeric;
  v_o_amt numeric;
  v_sales_fixed int := 0;
  v_invoice_ids uuid[] := '{}';
  v_invoice_id uuid;
  v_gl_fixed int := 0;
  v_norm record;
begin
  if p_item_id is null or p_warehouse_id is null then
    return jsonb_build_object('sales_out_restamped', 0, 'invoices_gl_synced', 0);
  end if;
  if p_anchor_mov_id is not null then
    select * into v_anchor from erp.inventory_movements where id = p_anchor_mov_id;
    if not found then
      return jsonb_build_object('sales_out_restamped', 0, 'invoices_gl_synced', 0);
    end if;
  end if;

  for v_mov in
    select im.*
    from erp.inventory_movements im
    where im.item_id = p_item_id
      and im.warehouse_id = p_warehouse_id
      and im.movement_type = 'sales_out'
      and coalesce(im.qty_out, 0) > 0
      and coalesce(im.cost_status, 'provisional') = 'provisional'
      and (
        p_anchor_mov_id is null
        or im.posting_date > v_anchor.posting_date
        or (im.posting_date = v_anchor.posting_date and im.created_at > v_anchor.created_at)
        or (
          im.posting_date = v_anchor.posting_date
          and im.created_at = v_anchor.created_at
          and im.id > v_anchor.id
        )
      )
    order by im.posting_date, im.created_at, im.id
  loop
    select * into v_state
    from erp._inventory_replay_state(v_mov.item_id, v_mov.warehouse_id, v_mov.id);
    v_wac := coalesce(v_state.avg_unit_cost, 0);
    v_new_val := round(v_mov.qty_out * v_wac, 3);
    v_c_amt := round(v_mov.qty_out * coalesce(v_state.copper_unit_cost, 0), 3);
    v_v_amt := round(v_mov.qty_out * coalesce(v_state.varnish_unit_cost, 0), 3);
    v_p_amt := round(v_mov.qty_out * coalesce(v_state.packing_unit_cost, 0), 3);
    v_o_amt := round(v_mov.qty_out * coalesce(v_state.oh_unit_cost, 0), 3);

    select * into v_norm
    from erp._normalize_cogs_components(v_new_val, v_c_amt, v_v_amt, v_p_amt, v_o_amt);
    v_c_amt := v_norm.o_copper;
    v_v_amt := v_norm.o_varnish;
    v_p_amt := v_norm.o_packing;
    v_o_amt := round(coalesce(v_norm.o_oh, 0) + coalesce(v_norm.o_clearing, 0), 3);

    if v_mov.unit_cost is distinct from v_wac
       or v_mov.value_amount is distinct from v_new_val
       or v_mov.cost_copper is distinct from v_c_amt
       or v_mov.cost_varnish is distinct from v_v_amt
       or v_mov.cost_packing is distinct from v_p_amt
       or v_mov.cost_oh is distinct from v_o_amt then
      update erp.inventory_movements
      set unit_cost = v_wac,
          value_amount = v_new_val,
          cost_copper = v_c_amt,
          cost_varnish = v_v_amt,
          cost_packing = v_p_amt,
          cost_oh = v_o_amt
      where id = v_mov.id;
      v_sales_fixed := v_sales_fixed + 1;
    end if;

    if v_mov.source_doc_type = 'sales_invoice'
       and v_mov.source_doc_id is not null
       and not (v_mov.source_doc_id = any(v_invoice_ids)) then
      v_invoice_ids := array_append(v_invoice_ids, v_mov.source_doc_id);
    end if;
  end loop;

  foreach v_invoice_id in array v_invoice_ids loop
    if erp._sync_sales_invoice_cogs_gl(v_invoice_id) then
      v_gl_fixed := v_gl_fixed + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'sales_out_restamped', v_sales_fixed,
    'invoices_touched', cardinality(v_invoice_ids),
    'invoices_gl_synced', v_gl_fixed
  );
end;
$$;


ALTER FUNCTION "erp"."_restamp_sales_cogs_for_item_wh"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_anchor_mov_id" "uuid") OWNER TO "postgres";

--
-- Name: _restore_ap_open("uuid", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_restore_ap_open"("p_party_id" "uuid", "p_amount" numeric) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_remaining numeric := coalesce(p_amount, 0);
  v_row record;
  v_restore numeric;
begin
  if v_remaining <= 0 or p_party_id is null then return 0; end if;

  for v_row in
    select id, amount, open_amount, status
    from erp.ap_documents
    where party_id = p_party_id
      and status in ('settled', 'partially_settled', 'open')
    order by doc_date desc, id desc
  loop
    exit when v_remaining <= 0;
    v_restore := least(v_remaining, v_row.amount - v_row.open_amount);
    if v_restore <= 0 then continue; end if;

    update erp.ap_documents
    set open_amount = open_amount + v_restore,
        status = case
          when open_amount + v_restore >= amount - 0.01 then 'open'
          else 'partially_settled'
        end
    where id = v_row.id;

    v_remaining := v_remaining - v_restore;
  end loop;

  return coalesce(p_amount, 0) - v_remaining;
end;
$$;


ALTER FUNCTION "erp"."_restore_ap_open"("p_party_id" "uuid", "p_amount" numeric) OWNER TO "postgres";

