--
-- Name: _reverse_parchi_issue_gl_for("uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_reverse_parchi_issue_gl_for"("p_parchi_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_p erp.parchi_instruments%rowtype;
  v_je record;
  v_count int := 0;
  v_narration text;
begin
  select * into v_p from erp.parchi_instruments where id = p_parchi_id;
  if not found then
  -- Orphan JE when instrument row was removed: still reverse from journal party lines
    for v_je in
      select je.id, je.voucher_no, je.source_doc_no
      from erp.journal_entries je
      where je.source_doc_type = 'parchi_instrument'
        and je.source_doc_id = p_parchi_id
        and je.voucher_type = 'PARCHI_ISSUE'
        and coalesce(je.voucher_no, '') not like 'VOID-%'
        and not exists (
          select 1 from erp.journal_entries rev
          where rev.source_doc_id = p_parchi_id
            and rev.source_doc_type = 'parchi_instrument'
            and coalesce(rev.voucher_no, '') like 'VOID-%'
        )
    loop
      v_narration := coalesce(p_reason, 'Void parchi (orphan GL)');
      perform erp._post_reversing_journal_entry(
        v_je.id,
        'VOID-' || coalesce(v_je.voucher_no, v_je.source_doc_no, 'PARCHI'),
        'parchi_instrument',
        p_parchi_id,
        coalesce(v_je.source_doc_no, v_je.voucher_no),
        current_date,
        v_narration
      );
      v_count := v_count + 1;
    end loop;
    return v_count;
  end if;

  if v_p.direction = 'received' then
    perform erp._restore_ar_open(v_p.party_id, v_p.total_amount);
  elsif v_p.party_id is not null then
    perform erp._restore_ap_open(v_p.party_id, v_p.total_amount);
  end if;

  v_narration := coalesce(p_reason, 'Void parchi ' || v_p.parchi_no);

  for v_je in
    select je.id, je.voucher_no, je.source_doc_no
    from erp.journal_entries je
    where je.source_doc_type = 'parchi_instrument'
      and je.source_doc_id = p_parchi_id
      and je.voucher_type = 'PARCHI_ISSUE'
      and coalesce(je.voucher_no, '') not like 'VOID-%'
      and not exists (
        select 1 from erp.journal_entries rev
        where rev.source_doc_id = p_parchi_id
          and rev.source_doc_type = 'parchi_instrument'
          and coalesce(rev.voucher_no, '') like 'VOID-%'
      )
  loop
    perform erp._post_reversing_journal_entry(
      v_je.id,
      'VOID-' || coalesce(v_je.voucher_no, v_p.parchi_no),
      'parchi_instrument',
      p_parchi_id,
      coalesce(v_je.source_doc_no, v_p.parchi_no),
      current_date,
      v_narration
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "erp"."_reverse_parchi_issue_gl_for"("p_parchi_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: _reverse_party_opening("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_reverse_party_opening"("p_party_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je_ids uuid[];
begin
  select coalesce(array_agg(id), '{}') into v_je_ids
  from erp.journal_entries
  where source_doc_type = 'party_opening' and source_doc_id = p_party_id;

  if coalesce(array_length(v_je_ids, 1), 0) > 0 then
    delete from erp.journal_lines where journal_entry_id = any(v_je_ids);
    delete from erp.journal_entries where id = any(v_je_ids);
  end if;

  delete from erp.ar_documents
  where source_doc_type = 'party_opening' and source_doc_id = p_party_id;
  delete from erp.ap_documents
  where source_doc_type = 'party_opening' and source_doc_id = p_party_id;
  delete from erp.inventory_movements
  where source_doc_type = 'party_opening' and source_doc_id = p_party_id;
end;
$$;


ALTER FUNCTION "erp"."_reverse_party_opening"("p_party_id" "uuid") OWNER TO "postgres";

--
-- Name: _reverse_party_opening_scrap("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_reverse_party_opening_scrap"("p_party_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_obl erp.scrap_receivable_obligations%rowtype;
begin
  for v_obl in
    select *
    from erp.scrap_receivable_obligations
    where party_id = p_party_id
      and obligation_source = 'opening'
    for update
  loop
    if coalesce(v_obl.received_kg, 0) > 0.001 then
      raise exception 'Cannot remove opening scrap obligation %: % kg already received',
        v_obl.obligation_no, v_obl.received_kg;
    end if;

    delete from erp.scrap_receipts
    where obligation_id = v_obl.id
      and status = 'draft';

    delete from erp.scrap_receivable_obligations
    where id = v_obl.id;
  end loop;
end;
$$;


ALTER FUNCTION "erp"."_reverse_party_opening_scrap"("p_party_id" "uuid") OWNER TO "postgres";

--
-- Name: _revert_premium_purchase_scrap_pool("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_revert_premium_purchase_scrap_pool"("p_invoice_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_lot_ids uuid[];
  v_dispatch_id uuid;
begin
  select array_agg(distinct sa.scrap_lot_id) into v_lot_ids
  from erp.scrap_allocations sa
  where sa.purchase_invoice_id = p_invoice_id;

  if coalesce(array_length(v_lot_ids, 1), 0) = 0 then
    return;
  end if;

  -- Explicitly remove allocations for this invoice before header delete cascade,
  -- then refresh open/allocated lot balances.
  delete from erp.scrap_allocations sa where sa.purchase_invoice_id = p_invoice_id;
  perform erp.fn_refresh_scrap_lot_allocations(v_lot_ids);

  -- Keep factory toll obligations in sync after reverting this invoice allocation.
  for v_dispatch_id in
    select distinct spl.source_doc_id
    from erp.scrap_payable_lots spl
    where spl.id = any(v_lot_ids)
      and spl.source_doc_type = 'factory_scrap_dispatch'
  loop
    perform erp._sync_factory_obligation_from_premium_allocations(v_dispatch_id, null);
  end loop;
end;
$$;


ALTER FUNCTION "erp"."_revert_premium_purchase_scrap_pool"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _revert_purchase_order_receiving_from_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_revert_purchase_order_receiving_from_invoice"("p_invoice_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_order_ids uuid[] := '{}';
  v_order_id uuid;
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'erp' and table_name = 'purchase_invoice_lines' and column_name = 'purchase_order_line_id'
  ) then
    return v_order_ids;
  end if;

  with affected as (
    select distinct pil.purchase_order_line_id as pol_id
    from erp.purchase_invoice_lines pil
    where pil.purchase_invoice_id = p_invoice_id
      and pil.purchase_order_line_id is not null
  )
  update erp.purchase_order_lines pol
  set qty_received = coalesce((
    select sum(coalesce(pil.net_weight, pil.qty))::numeric
    from erp.purchase_invoice_lines pil
    join erp.purchase_invoices pi on pi.id = pil.purchase_invoice_id
    where pil.purchase_order_line_id = pol.id
      and pi.posting_status = 'posted'
      and pi.id <> p_invoice_id
  ), 0)
  from affected a
  where pol.id = a.pol_id;

  select coalesce(array_agg(distinct pol.purchase_order_id), '{}')
  into v_order_ids
  from erp.purchase_order_lines pol
  join erp.purchase_invoice_lines pil on pil.purchase_order_line_id = pol.id
  where pil.purchase_invoice_id = p_invoice_id;

  if coalesce(array_length(v_order_ids, 1), 0) > 0 then
    foreach v_order_id in array v_order_ids
    loop
      perform erp._recalc_purchase_order_status(v_order_id, true);
    end loop;
  end if;

  return v_order_ids;
end;
$$;


ALTER FUNCTION "erp"."_revert_purchase_order_receiving_from_invoice"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _revert_sales_order_fulfillment_from_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_revert_sales_order_fulfillment_from_invoice"("p_invoice_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_order_ids uuid[] := '{}';
  v_order_id uuid;
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'erp' and table_name = 'sales_invoice_lines' and column_name = 'sales_order_line_id'
  ) then
    return v_order_ids;
  end if;

  with affected as (
    select distinct sil.sales_order_line_id as sol_id
    from erp.sales_invoice_lines sil
    where sil.sales_invoice_id = p_invoice_id
      and sil.sales_order_line_id is not null
  )
  update erp.sales_order_lines sol
  set qty_fulfilled = coalesce((
    select sum(coalesce(sil.net_weight, sil.qty))::numeric
    from erp.sales_invoice_lines sil
    join erp.sales_invoices si on si.id = sil.sales_invoice_id
    where sil.sales_order_line_id = sol.id
      and si.posting_status = 'posted'
      and si.id <> p_invoice_id
  ), 0)
  from affected a
  where sol.id = a.sol_id;

  select coalesce(array_agg(distinct sol.sales_order_id), '{}')
  into v_order_ids
  from erp.sales_order_lines sol
  join erp.sales_invoice_lines sil on sil.sales_order_line_id = sol.id
  where sil.sales_invoice_id = p_invoice_id;

  if coalesce(array_length(v_order_ids, 1), 0) > 0 then
    foreach v_order_id in array v_order_ids
    loop
      perform erp._recalc_sales_order_status(v_order_id, true);
    end loop;
  end if;

  return v_order_ids;
end;
$$;


ALTER FUNCTION "erp"."_revert_sales_order_fulfillment_from_invoice"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _sales_cogs_category_label("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sales_cogs_category_label"("p_category" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case p_category
    when 'enameled_wire' then 'COGS - Enameled Wire'
    when 'copper_wire' then 'COGS - Copper Wire'
    when 'copper_strip' then 'COGS - Copper Strip'
    when 'wire_rm' then 'COGS - Wire No 8 / RM'
    when 'other_fg' then 'COGS - Other FG'
    when 'other_gl' then 'Other sales COGS (GL)'
    else coalesce(p_category, 'COGS - Other')
  end;
$$;


ALTER FUNCTION "erp"."_sales_cogs_category_label"("p_category" "text") OWNER TO "postgres";

--
-- Name: _sales_return_line_inventory_cost("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sales_return_line_inventory_cost"("p_line_id" "uuid") RETURNS TABLE("source_movement_id" "uuid", "unit_cost" numeric, "value_amount" numeric, "cost_copper" numeric, "cost_varnish" numeric, "cost_packing" numeric, "cost_oh" numeric, "cost_basis" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_line record;
  v_mov erp.inventory_movements%rowtype;
  v_ratio numeric;
  v_fallback numeric;
begin
  select l.*, r.ref_invoice_id
  into v_line
  from erp.sales_return_lines l
  join erp.sales_returns r on r.id = l.sales_return_id
  where l.id = p_line_id;

  if not found or coalesce(v_line.qty, 0) <= 0 then
    return;
  end if;

  if v_line.ref_invoice_id is not null then
    select im.*
    into v_mov
    from erp.sales_invoice_lines sil
    join erp.inventory_movements im
      on im.source_doc_type = 'sales_invoice'
     and im.source_doc_id = v_line.ref_invoice_id
     and im.source_line_id = sil.id
     and im.movement_type = 'sales_out'
    where sil.sales_invoice_id = v_line.ref_invoice_id
      and sil.line_no = v_line.line_no
      and sil.item_id is not distinct from v_line.item_id
      and sil.warehouse_id is not distinct from v_line.warehouse_id
    order by im.created_at, im.id
    limit 1;
  end if;

  if v_mov.id is not null and coalesce(v_mov.qty_out, 0) > 0 then
    v_ratio := v_line.qty / v_mov.qty_out;
    source_movement_id := v_mov.id;
    unit_cost := coalesce(
      nullif(v_mov.unit_cost, 0),
      v_mov.value_amount / nullif(v_mov.qty_out, 0),
      0
    );
    value_amount := round(v_line.qty * unit_cost, 3);
    cost_copper := round(coalesce(v_mov.cost_copper, 0) * v_ratio, 3);
    cost_varnish := round(coalesce(v_mov.cost_varnish, 0) * v_ratio, 3);
    cost_packing := round(coalesce(v_mov.cost_packing, 0) * v_ratio, 3);
    cost_oh := round(coalesce(v_mov.cost_oh, 0) * v_ratio, 3);
    cost_basis := 'original_sales_out';
    return next;
    return;
  end if;

  v_fallback := coalesce(
    erp._inventory_balance_avg_cost(v_line.item_id, v_line.warehouse_id),
    erp._inventory_replay_current_wac(v_line.item_id, v_line.warehouse_id),
    0
  );
  source_movement_id := null;
  unit_cost := v_fallback;
  value_amount := round(v_line.qty * v_fallback, 3);
  cost_copper := 0;
  cost_varnish := 0;
  cost_packing := 0;
  cost_oh := 0;
  cost_basis := 'fallback_wac';
  return next;
end;
$$;


ALTER FUNCTION "erp"."_sales_return_line_inventory_cost"("p_line_id" "uuid") OWNER TO "postgres";

--
-- Name: _sales_revenue_category("text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sales_revenue_category"("p_item_type" "text", "p_inventory_group" "text", "p_item_code" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case
    when coalesce(p_inventory_group, '') = 'enameled'
      or coalesce(p_item_type, '') ilike '%enamel%'
      then 'enameled_wire'
    when coalesce(p_inventory_group, '') = 'copper_wire'
      or coalesce(p_item_type, '') ilike '%copper wire%'
      then 'copper_wire'
    when coalesce(p_inventory_group, '') = 'strip'
      or coalesce(p_item_type, '') ilike '%strip%'
      then 'copper_strip'
    when coalesce(p_inventory_group, '') = 'raw_material'
      or coalesce(p_item_code, '') like 'RM-W8%'
      or coalesce(p_item_type, '') in ('Wire', 'Raw Material')
      then 'wire_rm'
    else 'other_fg'
  end;
$$;


ALTER FUNCTION "erp"."_sales_revenue_category"("p_item_type" "text", "p_inventory_group" "text", "p_item_code" "text") OWNER TO "postgres";

--
-- Name: _sales_revenue_category_label("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sales_revenue_category_label"("p_category" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case p_category
    when 'enameled_wire' then 'Sales - Enameled Wire'
    when 'copper_wire' then 'Sales - Copper Wire'
    when 'copper_strip' then 'Sales - Copper Strip'
    when 'wire_rm' then 'Sales - Wire No 8 / RM'
    when 'scrap_sale' then 'Scrap Sales'
    when 'other_fg' then 'Sales - Other FG'
    when 'other_gl' then 'Other operating revenue (GL)'
    else coalesce(p_category, 'Sales - Other')
  end;
$$;


ALTER FUNCTION "erp"."_sales_revenue_category_label"("p_category" "text") OWNER TO "postgres";

--
-- Name: _scrap_backflush_parent_rm("text", "date", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_scrap_backflush_parent_rm"("p_department" "text", "p_as_of" "date" DEFAULT CURRENT_DATE, "p_expected_return_item_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item_id uuid;
  v_rod_code text;
begin
  -- p_expected_return_item_id is intentionally ignored for inventory backflush.
  if lower(coalesce(p_department, '')) in ('drawing', 'enamel') then
    v_item_id := erp._canonical_wire8_item_id(p_as_of);
    if v_item_id is null then
      select id into v_item_id from erp.items where code = 'RM-W8-001' and is_active = true limit 1;
    end if;
    return v_item_id;
  end if;

  if lower(coalesce(p_department, '')) = 'workshop' then
    v_rod_code := coalesce(erp._production_standard_text('rod_input_item_code', p_as_of), 'RM-CR-001');
    select id into v_item_id from erp.items where code = v_rod_code and is_active = true limit 1;
    if v_item_id is null then
      select id into v_item_id from erp.items where code = 'RM-CR-001' and is_active = true limit 1;
    end if;
    return v_item_id;
  end if;

  v_item_id := erp._canonical_wire8_item_id(p_as_of);
  if v_item_id is null then
    select id into v_item_id from erp.items where code = 'RM-W8-001' and is_active = true limit 1;
  end if;
  return v_item_id;
end;
$$;


ALTER FUNCTION "erp"."_scrap_backflush_parent_rm"("p_department" "text", "p_as_of" "date", "p_expected_return_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _sync_factory_obligation_from_premium_allocations("uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_factory_obligation_from_premium_allocations"("p_dispatch_id" "uuid", "p_include_invoice_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_obl erp.scrap_conversion_obligations%rowtype;
  v_from_pi numeric;
  v_from_returns numeric;
begin
  select * into v_obl from erp.scrap_conversion_obligations where dispatch_id = p_dispatch_id;
  if not found then return; end if;

  select coalesce(sum(sa.allocated_kg), 0) into v_from_pi
  from erp.scrap_allocations sa
  join erp.scrap_payable_lots spl on spl.id = sa.scrap_lot_id
  join erp.purchase_invoices pi on pi.id = sa.purchase_invoice_id
  where spl.source_doc_type = 'factory_scrap_dispatch'
    and spl.source_doc_id = p_dispatch_id
    and sa.is_mazdoori_pending = false
    and (pi.posting_status = 'posted' or (p_include_invoice_id is not null and pi.id = p_include_invoice_id));

  select coalesce(sum(scr.net_weight), 0) into v_from_returns
  from erp.scrap_conversion_returns scr
  where scr.obligation_id = v_obl.id and scr.status = 'posted';

  update erp.scrap_conversion_obligations
  set returned_kg = v_from_pi + v_from_returns
  where id = v_obl.id;

  perform erp._sync_scrap_conversion_obligation_status(v_obl.id);
end;
$$;


ALTER FUNCTION "erp"."_sync_factory_obligation_from_premium_allocations"("p_dispatch_id" "uuid", "p_include_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _sync_factory_scrap_dispatch_cost("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_factory_scrap_dispatch_cost"("p_dispatch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_total numeric := 0;
  v_je_id uuid;
  v_item_ids uuid[] := '{}';
  v_rows int := 0;
begin
  select round(coalesce(sum(im.value_amount), 0), 3)
  into v_total
  from erp.inventory_movements im
  where im.source_doc_type = 'factory_scrap_dispatch'
    and im.source_doc_id = p_dispatch_id
    and im.movement_type = 'production_issue';

  if v_total <= 0 then
    return jsonb_build_object('dispatch_id', p_dispatch_id, 'synced', false, 'cost', v_total);
  end if;

  with issue as (
    select distinct on (im.source_line_id)
      im.source_line_id, im.unit_cost, im.value_amount,
      im.cost_copper, im.cost_varnish, im.cost_packing, im.cost_oh
    from erp.inventory_movements im
    where im.source_doc_type = 'factory_scrap_dispatch'
      and im.source_doc_id = p_dispatch_id
      and im.movement_type = 'production_issue'
    order by im.source_line_id, im.created_at, im.id
  )
  update erp.inventory_movements target
  set unit_cost = issue.unit_cost,
      value_amount = issue.value_amount,
      cost_copper = issue.cost_copper,
      cost_varnish = issue.cost_varnish,
      cost_packing = issue.cost_packing,
      cost_oh = issue.cost_oh
  from issue
  where target.source_doc_type = 'factory_scrap_dispatch'
    and target.source_doc_id = p_dispatch_id
    and target.source_line_id = issue.source_line_id
    and target.movement_type in ('scrap_in', 'scrap_out');
  get diagnostics v_rows = row_count;

  select je.id into v_je_id
  from erp.journal_entries je
  where je.source_doc_type = 'factory_scrap_dispatch'
    and je.source_doc_id = p_dispatch_id
    and je.status = 'posted'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
  order by je.posted_at desc nulls last, je.id desc
  limit 1;

  if v_je_id is not null then
    update erp.journal_lines
    set debit_amount = v_total, credit_amount = 0
    where journal_entry_id = v_je_id and account_code = '51006';

    update erp.journal_lines
    set debit_amount = 0, credit_amount = v_total
    where journal_entry_id = v_je_id
      and account_code in ('12101', '12104', '12301', '12500')
      and credit_amount > 0;

    perform erp._assert_je_balanced(v_je_id);
  end if;

  select coalesce(array_agg(distinct im.item_id) filter (where im.item_id is not null), '{}')
  into v_item_ids
  from erp.inventory_movements im
  where im.source_doc_type = 'factory_scrap_dispatch'
    and im.source_doc_id = p_dispatch_id;
  if cardinality(v_item_ids) > 0 then
    perform erp.rebuild_inventory_balances_for_items(v_item_ids);
  end if;

  return jsonb_build_object(
    'dispatch_id', p_dispatch_id,
    'synced', true,
    'cost', v_total,
    'derived_movements_updated', v_rows
  );
end;
$$;


ALTER FUNCTION "erp"."_sync_factory_scrap_dispatch_cost"("p_dispatch_id" "uuid") OWNER TO "postgres";

--
-- Name: _sync_factory_scrap_period_costs("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_factory_scrap_period_costs"("p_from" "date", "p_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc record;
  v_count int := 0;
begin
  for v_doc in
    select d.id
    from erp.factory_scrap_dispatches d
    where d.status = 'posted'
      and d.dispatch_date between p_from and p_to
    order by d.dispatch_date, d.dispatch_no, d.id
  loop
    perform erp._sync_factory_scrap_dispatch_cost(v_doc.id);
    v_count := v_count + 1;
  end loop;
  return jsonb_build_object('dispatches_synced', v_count, 'from', p_from, 'to', p_to);
end;
$$;


ALTER FUNCTION "erp"."_sync_factory_scrap_period_costs"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: _sync_inventory_adjustment_gl("uuid", "text", numeric, "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_inventory_adjustment_gl"("p_adjustment_id" "uuid", "p_direction" "text", "p_value" numeric, "p_narration" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_adj erp.inventory_adjustments%rowtype;
  v_item_code text;
  v_inv_acct text;
  v_loss_acct text;
  v_gain_acct text;
  v_je_id uuid;
  v_value numeric := round(coalesce(p_value, 0), 3);
  v_narration text;
begin
  if p_adjustment_id is null or v_value <= 0 then return; end if;
  select * into v_adj from erp.inventory_adjustments where id = p_adjustment_id;
  if not found then raise exception 'inventory adjustment not found: %', p_adjustment_id; end if;
  select i.code into v_item_code from erp.items i where i.id = v_adj.item_id;
  v_inv_acct := erp._inventory_gl_account_for_item(v_adj.item_id);
  v_loss_acct := erp._resolve_posting_account('inventory_adjustment', 'loss_expense');
  v_gain_acct := erp._resolve_posting_account('inventory_adjustment', 'gain_income');
  if v_inv_acct is null then raise exception 'Missing inventory GL account for item %', coalesce(v_item_code, v_adj.item_id::text); end if;
  v_narration := coalesce(nullif(trim(p_narration), ''), nullif(trim(v_adj.remarks), ''), format('Inventory adjustment %s %s', v_adj.adjustment_no, v_adj.direction));
  select je.id into v_je_id from erp.journal_entries je where je.source_doc_type = 'inventory_adjustment' and je.source_doc_id = p_adjustment_id and coalesce(je.voucher_no, '') not like 'VOID-%' order by je.posted_at desc nulls last limit 1;
  if v_je_id is null then
    insert into erp.journal_entries (voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by)
    values (v_adj.adjustment_no, 'INVENTORY_ADJUSTMENT', v_adj.posting_date, 'inventory_adjustment', p_adjustment_id, v_adj.adjustment_no, v_narration, 'posted', now(), auth.uid())
    returning id into v_je_id;
    if p_direction = 'out' then
      if v_loss_acct is null then raise exception 'Missing inventory_adjustment posting map (loss_expense)'; end if;
      perform erp._insert_je_line(v_je_id, 1, v_loss_acct, null, v_value, 0, 'Inventory write-down');
      perform erp._insert_je_line(v_je_id, 2, v_inv_acct, null, 0, v_value, 'Inventory asset credit');
    else
      if v_gain_acct is null then raise exception 'Missing inventory_adjustment posting map (gain_income)'; end if;
      perform erp._insert_je_line(v_je_id, 1, v_inv_acct, null, v_value, 0, 'Inventory asset debit');
      perform erp._insert_je_line(v_je_id, 2, v_gain_acct, null, 0, v_value, 'Inventory gain');
    end if;
    return;
  end if;
  update erp.journal_entries set posting_date = v_adj.posting_date, narration = v_narration where id = v_je_id;
  delete from erp.journal_lines where journal_entry_id = v_je_id;
  if p_direction = 'out' then
    perform erp._insert_je_line(v_je_id, 1, v_loss_acct, null, v_value, 0, 'Inventory write-down');
    perform erp._insert_je_line(v_je_id, 2, v_inv_acct, null, 0, v_value, 'Inventory asset credit');
  else
    perform erp._insert_je_line(v_je_id, 1, v_inv_acct, null, v_value, 0, 'Inventory asset debit');
    perform erp._insert_je_line(v_je_id, 2, v_gain_acct, null, 0, v_value, 'Inventory gain');
  end if;
end;
$$;


ALTER FUNCTION "erp"."_sync_inventory_adjustment_gl"("p_adjustment_id" "uuid", "p_direction" "text", "p_value" numeric, "p_narration" "text") OWNER TO "postgres";

--
-- Name: _sync_party_scrap_credit_status("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_party_scrap_credit_status"("p_credit_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_credit erp.party_scrap_credits%rowtype;
begin
  select * into v_credit from erp.party_scrap_credits where id = p_credit_id;
  if not found then return; end if;

  update erp.party_scrap_credits
  set status = case
    when v_credit.status = 'void' then 'void'
    when v_credit.consumed_kg <= 0 then 'open'
    when v_credit.consumed_kg + 0.001 >= v_credit.credit_kg then 'consumed'
    else 'partial'
  end
  where id = p_credit_id;
end;
$$;


ALTER FUNCTION "erp"."_sync_party_scrap_credit_status"("p_credit_id" "uuid") OWNER TO "postgres";

--
-- Name: _sync_pending_rate_provisional_gl("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_pending_rate_provisional_gl"("p_pending_item_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_pri erp.pending_rate_items%rowtype;
  v_mov erp.inventory_movements%rowtype;
  v_je_id uuid;
  v_inv text;
  v_amount numeric;
begin
  select * into v_pri
  from erp.pending_rate_items
  where id = p_pending_item_id;
  if not found or v_pri.status <> 'open'
     or v_pri.source_doc_type <> 'purchase_invoice' then
    return false;
  end if;

  select * into v_mov
  from erp.inventory_movements im
  where im.source_doc_type = 'purchase_invoice'
    and im.source_doc_id = v_pri.source_doc_id
    and im.source_line_id = v_pri.source_line_id
    and im.movement_type = 'purchase_in'
  order by im.created_at, im.id
  limit 1;
  if not found then return false; end if;

  v_amount := round(coalesce(v_mov.value_amount, 0), 3);
  if v_amount <= 0 then return false; end if;
  v_inv := erp._resolve_posting_account('purchase_invoice', 'inventory');

  select je.id into v_je_id
  from erp.journal_entries je
  where je.source_doc_type = 'pending_rate_provisional'
    and je.source_doc_id = v_pri.id
    and coalesce(je.voucher_no, '') not like 'VOID-%'
  order by je.posted_at desc nulls last, je.id
  limit 1
  for update;

  if v_je_id is null then
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id,
      source_doc_no, narration, status, posted_at, posted_by
    ) values (
      'PRV-' || coalesce(v_pri.source_doc_no, 'PENDING')
        || '-' || left(v_pri.id::text, 8),
      'PENDING_RATE_PROVISIONAL', v_pri.original_posting_date,
      'pending_rate_provisional', v_pri.id, v_pri.source_doc_no,
      'Provisional inventory value pending supplier rate',
      'posted', now(), auth.uid()
    ) returning id into v_je_id;
  else
    update erp.journal_entries
    set status = 'posted', posted_at = now()
    where id = v_je_id;
    delete from erp.journal_lines where journal_entry_id = v_je_id;
  end if;

  perform erp._insert_je_line(
    v_je_id, 1, v_inv, null, v_amount, 0,
    'Inventory at provisional pending-rate cost'
  );
  perform erp._insert_je_line(
    v_je_id, 2, '21190', null, 0, v_amount,
    'Pending-rate receipt accrual'
  );
  perform erp._assert_je_balanced(v_je_id);
  update erp.journal_entries
  set status = 'posted', posted_at = now()
  where id = v_je_id;
  return true;
end;
$$;


ALTER FUNCTION "erp"."_sync_pending_rate_provisional_gl"("p_pending_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _sync_production_batch_gl("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_production_batch_gl"("p_batch_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.production_batches%rowtype;
  v_rm_cost numeric := 0;
  v_fg_cost numeric := 0;
  v_oh_absorbed numeric := 0;
  v_yield_shortfall numeric := 0;
  v_rm text;
  v_fg text;
  v_oh text;
  v_wastage text;
  v_je_id uuid;
  v_ln int := 0;
  v_dr numeric := 0;
  v_cr numeric := 0;
begin
  select * into v_doc from erp.production_batches where id = p_batch_id;
  if not found then raise exception 'production batch not found'; end if;

  select coalesce(sum(im.value_amount), 0) into v_rm_cost
  from erp.inventory_movements im
  where im.source_doc_type = 'production_batch' and im.source_doc_id = p_batch_id and im.movement_type = 'production_issue';
  select coalesce(sum(im.value_amount), 0) into v_fg_cost
  from erp.inventory_movements im
  where im.source_doc_type = 'production_batch' and im.source_doc_id = p_batch_id and im.movement_type = 'production_receipt';
  v_rm_cost := round(coalesce(v_rm_cost, 0), 3);
  v_fg_cost := round(coalesce(v_fg_cost, 0), 3);

  if v_fg_cost <= 0 and v_rm_cost <= 0 then
    return 0;
  end if;

  if exists (
    select 1 from erp.journal_entries je
    where je.source_doc_type = 'production_batch' and je.source_doc_id = p_batch_id
      and coalesce(je.voucher_no, '') not like 'VOID-%'
  ) then
    return v_fg_cost;
  end if;

  if v_fg_cost > v_rm_cost then
    v_oh_absorbed := round(v_fg_cost - v_rm_cost, 3);
  elsif v_rm_cost > v_fg_cost then
    v_yield_shortfall := round(v_rm_cost - v_fg_cost, 3);
  end if;

  v_rm := erp._resolve_posting_account('production_batch', 'inventory_rm');
  v_fg := erp._resolve_posting_account('production_batch', 'inventory_fg');
  v_oh := erp._resolve_posting_account('production_batch', 'absorbed_overhead');
  v_wastage := coalesce(erp._lookup_posting_account('inventory_adjustment', 'wastage'), '51006');

  insert into erp.journal_entries (
    voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no,
    narration, status, posted_at, posted_by
  ) values (
    v_doc.batch_no, 'PRODUCTION_BATCH', v_doc.batch_date, 'production_batch', v_doc.id, v_doc.batch_no,
    format('Production RM->FG (absorbed OH %s / yield shortfall %s PKR)', v_oh_absorbed, v_yield_shortfall),
    'posted', now(), auth.uid()
  ) returning id into v_je_id;

  if v_fg_cost > 0 then
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_fg, null, v_fg_cost, 0, 'FG received (RM + absorbed overhead)');
  end if;
  if v_rm_cost > 0 then
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_rm, null, 0, v_rm_cost, 'RM issued to production');
  end if;
  if v_oh_absorbed > 0 then
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_oh, null, 0, v_oh_absorbed, 'Absorbed factory overhead');
  end if;
  if v_yield_shortfall > 0 then
    v_ln := v_ln + 1;
    perform erp._insert_je_line(
      v_je_id, v_ln, v_wastage, null, v_yield_shortfall, 0,
      'Production yield / scrap shortfall (RM above FG value)'
    );
  end if;

  select coalesce(sum(debit_amount), 0), coalesce(sum(credit_amount), 0)
  into v_dr, v_cr
  from erp.journal_lines where journal_entry_id = v_je_id;
  if abs(round(v_dr - v_cr, 3)) > 0.01 then
    raise exception 'Production batch % GL is unbalanced (dr=%, cr=%); refusing to commit', v_doc.batch_no, v_dr, v_cr
      using errcode = 'P0001';
  end if;

  return v_fg_cost;
end;
$$;


ALTER FUNCTION "erp"."_sync_production_batch_gl"("p_batch_id" "uuid") OWNER TO "postgres";

--
-- Name: _sync_purchase_return_inventory_gl("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_purchase_return_inventory_gl"("p_return_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_returns%rowtype;
  v_inv text;
  v_var text;
  v_desired numeric := 0;
  v_current numeric := 0;
  v_delta numeric := 0;
  v_je_id uuid;
  v_ln int := 0;
begin
  select * into v_doc from erp.purchase_returns where id = p_return_id;
  if not found then return false; end if;
  if coalesce(v_doc.return_no, '') like 'VOID-%' then return false; end if;

  v_inv := erp._resolve_posting_account('purchase_return', 'inventory');
  v_var := coalesce(erp._lookup_posting_account('purchase_return', 'cost_variance'), '51014');

  if coalesce(v_doc.return_action, '') = 'stock' then
    select round(coalesce(sum(im.value_amount), 0), 3)
    into v_desired
    from erp.inventory_movements im
    where im.source_doc_type = 'purchase_return'
      and im.source_doc_id = p_return_id
      and im.movement_type = 'purchase_return_out';
  end if;

  select round(coalesce(sum(jl.credit_amount - jl.debit_amount), 0), 3)
  into v_current
  from erp.journal_entries je
  join erp.journal_lines jl on jl.journal_entry_id = je.id
  where je.source_doc_type in ('purchase_return', 'purchase_return_cost_sync')
    and je.source_doc_id = p_return_id
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    and jl.account_code = v_inv;

  v_delta := round(v_desired - v_current, 3);
  if abs(v_delta) <= 0.001 then return false; end if;

  insert into erp.journal_entries (
    voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id,
    source_doc_no, narration, status, posted_at, posted_by
  ) values (
    v_doc.return_no || '-COST-SYNC', 'PURCHASE_RETURN_COST_SYNC', v_doc.return_date,
    'purchase_return_cost_sync', v_doc.id, v_doc.return_no,
    'Align purchase-return inventory GL to original receipt cost',
    'posted', now(), auth.uid()
  ) returning id into v_je_id;

  if v_delta > 0 then
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_var, null, v_delta, 0, 'Purchase return cost sync');
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, 0, v_delta, 'Inventory cost sync');
  else
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, -v_delta, 0, 'Reverse excess inventory credit');
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_var, null, 0, -v_delta, 'Purchase return cost sync');
  end if;

  perform erp._assert_je_balanced(v_je_id);
  update erp.journal_entries set status = 'posted', posted_at = now() where id = v_je_id;
  return true;
end;
$$;


ALTER FUNCTION "erp"."_sync_purchase_return_inventory_gl"("p_return_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "_sync_purchase_return_inventory_gl"("p_return_id" "uuid"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_sync_purchase_return_inventory_gl"("p_return_id" "uuid") IS 'Post the exact inventory/variance delta required to align purchase-return GL with return movements.';


--
-- Name: _sync_sales_invoice_cogs_gl("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_sales_invoice_cogs_gl"("p_invoice_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_cogs_clearing text;
  v_cogs_copper text;
  v_cogs_varnish text;
  v_cogs_packing text;
  v_cogs_oh text;
  v_inv_acct text;
  v_je_id uuid;
  v_ln int;
  v_total numeric := 0;
  v_copper numeric := 0;
  v_varnish numeric := 0;
  v_packing numeric := 0;
  v_oh numeric := 0;
  v_clearing numeric := 0;
  v_old_clearing numeric := 0;
  v_old_copper numeric := 0;
  v_old_varnish numeric := 0;
  v_old_packing numeric := 0;
  v_old_oh numeric := 0;
  v_old_inv numeric := 0;
  v_norm record;
begin
  if p_invoice_id is null then return false; end if;
  v_cogs_clearing := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs'), erp._resolve_posting_account('sales_invoice', 'cogs'));
  v_cogs_copper := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs_copper'), '51010');
  v_cogs_varnish := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs_varnish'), '51011');
  v_cogs_packing := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs_packing'), '51012');
  v_cogs_oh := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs_overhead'), erp._lookup_posting_account('sales_invoice', 'cogs_oh'), '51013');
  v_inv_acct := erp._resolve_posting_account('sales_invoice', 'inventory');
  select round(coalesce(sum(im.value_amount), 0), 3), round(coalesce(sum(im.cost_copper), 0), 3), round(coalesce(sum(im.cost_varnish), 0), 3), round(coalesce(sum(im.cost_packing), 0), 3), round(coalesce(sum(im.cost_oh), 0), 3)
  into v_total, v_copper, v_varnish, v_packing, v_oh
  from erp.inventory_movements im
  where im.source_doc_type = 'sales_invoice' and im.source_doc_id = p_invoice_id and im.movement_type = 'sales_out';
  if v_total <= 0 then return false; end if;
  select * into v_norm from erp._normalize_cogs_components(v_total, v_copper, v_varnish, v_packing, v_oh);
  v_copper := v_norm.o_copper; v_varnish := v_norm.o_varnish; v_packing := v_norm.o_packing; v_oh := v_norm.o_oh; v_clearing := v_norm.o_clearing;
  select je.id into v_je_id from erp.journal_entries je
  where je.source_doc_type = 'sales_invoice' and je.source_doc_id = p_invoice_id
    and je.voucher_type in ('SALES_INVOICE', 'SALES_COGS_ADJ') and coalesce(je.voucher_no, '') not like 'VOID-%'
  order by case when je.voucher_type = 'SALES_INVOICE' then 0 else 1 end, je.posted_at, je.id limit 1;
  if v_je_id is null then return false; end if;
  select coalesce(sum(jl.debit_amount) filter (where jl.account_code = v_cogs_clearing), 0),
         coalesce(sum(jl.debit_amount) filter (where jl.account_code = v_cogs_copper), 0),
         coalesce(sum(jl.debit_amount) filter (where jl.account_code = v_cogs_varnish), 0),
         coalesce(sum(jl.debit_amount) filter (where jl.account_code = v_cogs_packing), 0),
         coalesce(sum(jl.debit_amount) filter (where jl.account_code = v_cogs_oh), 0),
         coalesce(sum(jl.credit_amount) filter (where jl.account_code = v_inv_acct), 0)
  into v_old_clearing, v_old_copper, v_old_varnish, v_old_packing, v_old_oh, v_old_inv
  from erp.journal_lines jl where jl.journal_entry_id = v_je_id;
  if abs(v_old_clearing - v_clearing) <= 0.01 and abs(v_old_copper - v_copper) <= 0.01 and abs(v_old_varnish - v_varnish) <= 0.01
     and abs(v_old_packing - v_packing) <= 0.01 and abs(v_old_oh - v_oh) <= 0.01 and abs(v_old_inv - v_total) <= 0.01 then
    return false;
  end if;
  delete from erp.journal_lines jl where jl.journal_entry_id = v_je_id
    and (jl.account_code in (v_cogs_clearing, v_cogs_copper, v_cogs_varnish, v_cogs_packing, v_cogs_oh)
         or (jl.account_code = v_inv_acct and jl.credit_amount > 0));
  select coalesce(max(line_no), 0) into v_ln from erp.journal_lines where journal_entry_id = v_je_id;
  if v_copper > 0 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_cogs_copper, null, v_copper, 0, 'COGS - Copper'); end if;
  if v_varnish > 0 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_cogs_varnish, null, v_varnish, 0, 'COGS - Varnish'); end if;
  if v_packing > 0 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_cogs_packing, null, v_packing, 0, 'COGS - Packing'); end if;
  if v_oh > 0 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_cogs_oh, null, v_oh, 0, 'COGS - Absorbed Overhead'); end if;
  if v_clearing > 0.001 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_cogs_clearing, null, v_clearing, 0, 'COGS - Clearing'); end if;
  v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_inv_acct, null, 0, v_total, 'Inventory');
  perform erp._assert_je_balanced(v_je_id);
  return true;
end;
$$;


ALTER FUNCTION "erp"."_sync_sales_invoice_cogs_gl"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: _sync_sales_return_cogs_gl("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_sales_return_cogs_gl"("p_return_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_returns%rowtype;
  v_je_id uuid;
  v_inv text; v_clear text; v_copper_acct text; v_varnish_acct text; v_packing_acct text; v_oh_acct text;
  v_total numeric; v_copper numeric; v_varnish numeric; v_packing numeric; v_oh numeric; v_clearing numeric;
  v_ln int := 0; v_norm record;
begin
  select * into v_doc from erp.sales_returns where id = p_return_id;
  if not found or coalesce(v_doc.return_action, '') <> 'restock' then return false; end if;
  select round(coalesce(sum(im.value_amount), 0), 3), round(coalesce(sum(im.cost_copper), 0), 3), round(coalesce(sum(im.cost_varnish), 0), 3), round(coalesce(sum(im.cost_packing), 0), 3), round(coalesce(sum(im.cost_oh), 0), 3)
  into v_total, v_copper, v_varnish, v_packing, v_oh
  from erp.inventory_movements im
  where im.source_doc_type = 'sales_return' and im.source_doc_id = p_return_id and im.movement_type = 'sales_return_in';
  if v_total <= 0 then return false; end if;
  v_inv := coalesce(erp._lookup_posting_account('sales_invoice', 'inventory'), erp._resolve_posting_account('sales_invoice', 'inventory'));
  v_clear := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs'), erp._resolve_posting_account('sales_invoice', 'cogs'));
  v_copper_acct := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs_copper'), '51010');
  v_varnish_acct := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs_varnish'), '51011');
  v_packing_acct := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs_packing'), '51012');
  v_oh_acct := coalesce(erp._lookup_posting_account('sales_invoice', 'cogs_overhead'), erp._lookup_posting_account('sales_invoice', 'cogs_oh'), '51013');
  select * into v_norm from erp._normalize_cogs_components(v_total, v_copper, v_varnish, v_packing, v_oh);
  v_copper := v_norm.o_copper; v_varnish := v_norm.o_varnish; v_packing := v_norm.o_packing; v_oh := v_norm.o_oh; v_clearing := v_norm.o_clearing;
  select je.id into v_je_id from erp.journal_entries je
  where je.source_doc_type = 'sales_return_cogs' and je.source_doc_id = p_return_id and coalesce(je.voucher_no, '') not like 'VOID-SUPERSEDED-%'
  order by je.posted_at desc nulls last, je.id limit 1 for update;
  if v_je_id is null then
    insert into erp.journal_entries (voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by)
    values (v_doc.return_no || '-COGS', 'SALES_RETURN_COGS', v_doc.return_date, 'sales_return_cogs', v_doc.id, v_doc.return_no, 'Inventory / COGS mirror for sales return', 'posted', now(), auth.uid())
    returning id into v_je_id;
  else
    delete from erp.journal_lines where journal_entry_id = v_je_id;
    update erp.journal_entries set status = 'posted', posted_at = coalesce(posted_at, now()) where id = v_je_id;
  end if;
  v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, v_total, 0, 'Inventory restored at original COGS');
  if v_copper > 0 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_copper_acct, null, 0, v_copper, 'Reverse COGS - Copper'); end if;
  if v_varnish > 0 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_varnish_acct, null, 0, v_varnish, 'Reverse COGS - Varnish'); end if;
  if v_packing > 0 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_packing_acct, null, 0, v_packing, 'Reverse COGS - Packing'); end if;
  if v_oh > 0 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_oh_acct, null, 0, v_oh, 'Reverse COGS - Absorbed Overhead'); end if;
  if v_clearing > 0.001 then v_ln := v_ln + 1; perform erp._insert_je_line(v_je_id, v_ln, v_clear, null, 0, v_clearing, 'Reverse COGS - Clearing'); end if;
  perform erp._assert_je_balanced(v_je_id);
  return true;
end;
$$;


ALTER FUNCTION "erp"."_sync_sales_return_cogs_gl"("p_return_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "_sync_sales_return_cogs_gl"("p_return_id" "uuid"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."_sync_sales_return_cogs_gl"("p_return_id" "uuid") IS 'Build a balanced inventory/COGS mirror from sales_return_in original-cost stamps.';


--
-- Name: _sync_scrap_conversion_obligation_status("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_scrap_conversion_obligation_status"("p_obligation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_exp numeric;
  v_rec numeric;
begin
  select expected_kg, returned_kg into v_exp, v_rec
  from erp.scrap_conversion_obligations where id = p_obligation_id;
  if not found then return; end if;

  update erp.scrap_conversion_obligations
  set status = case
    when v_rec <= 0.001 then 'open'
    when v_rec + 0.001 >= v_exp then 'fulfilled'
    else 'partial'
  end
  where id = p_obligation_id;
end;
$$;


ALTER FUNCTION "erp"."_sync_scrap_conversion_obligation_status"("p_obligation_id" "uuid") OWNER TO "postgres";

--
-- Name: _sync_scrap_lot_status("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_scrap_lot_status"("p_lot_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_orig numeric;
  v_alloc numeric;
begin
  select original_kg, allocated_kg into v_orig, v_alloc from erp.scrap_payable_lots where id = p_lot_id;
  update erp.scrap_payable_lots
  set status = case
    when v_alloc <= 0 then 'open'
    when v_alloc + 0.001 >= v_orig then 'exhausted'
    else 'partial'
  end
  where id = p_lot_id;
end;
$$;


