--
-- Name: _sync_supplies_restock_gl("uuid", "date", numeric, "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_sync_supplies_restock_gl"("p_source_doc_id" "uuid", "p_posting_date" "date", "p_value" numeric, "p_narration" "text" DEFAULT 'Varnish supplies restock'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je_id uuid;
  v_inv text;
  v_offset text;
  v_value numeric := round(coalesce(p_value, 0), 3);
begin
  if p_source_doc_id is null or v_value <= 0 then
    return;
  end if;

  v_inv := erp._resolve_posting_account('supplies_restock', 'inventory');
  v_offset := erp._resolve_posting_account('supplies_restock', 'offset');
  if v_inv is null or v_offset is null then
    raise exception 'Missing supplies_restock posting map (inventory / offset)';
  end if;

  select je.id into v_je_id
  from erp.journal_entries je
  where je.source_doc_type = 'supplies_restock'
    and je.source_doc_id = p_source_doc_id
    and coalesce(je.voucher_no, '') not like 'VOID-%'
  order by je.posted_at desc nulls last
  limit 1;

  if v_je_id is null then
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no,
      narration, status, posted_at, posted_by
    ) values (
      'RESTOCK-' || left(p_source_doc_id::text, 8),
      'SUPPLIES_RESTOCK',
      coalesce(p_posting_date, current_date),
      'supplies_restock',
      p_source_doc_id,
      'RESTOCK-' || left(p_source_doc_id::text, 8),
      coalesce(nullif(trim(p_narration), ''), 'Varnish supplies restock'),
      'posted',
      now(),
      auth.uid()
    ) returning id into v_je_id;

    perform erp._insert_je_line(v_je_id, 1, v_inv, null, v_value, 0, 'Chemicals inventory');
    perform erp._insert_je_line(v_je_id, 2, v_offset, null, 0, v_value, 'Opening equity offset');
    return;
  end if;

  update erp.journal_entries
  set posting_date = coalesce(p_posting_date, posting_date),
      narration = coalesce(nullif(trim(p_narration), ''), narration)
  where id = v_je_id;

  update erp.journal_lines
  set debit_amount = v_value
  where journal_entry_id = v_je_id
    and debit_amount > 0;

  update erp.journal_lines
  set credit_amount = v_value
  where journal_entry_id = v_je_id
    and credit_amount > 0;
end;
$$;


ALTER FUNCTION "erp"."_sync_supplies_restock_gl"("p_source_doc_id" "uuid", "p_posting_date" "date", "p_value" numeric, "p_narration" "text") OWNER TO "postgres";

--
-- Name: _trg_block_scrap_cashbook(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_trg_block_scrap_cashbook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare v_voucher_type text; v_source_doc_type text;
begin
  if new.account_code in ('11101','11102','11111','11112','11113','11114') then
    select voucher_type, source_doc_type into v_voucher_type, v_source_doc_type
    from erp.journal_entries where id = new.journal_entry_id;
    if coalesce(v_source_doc_type,'') = 'scrap_trade' or coalesce(v_voucher_type,'') = 'SCRAP_TRADE' then
      raise exception 'Scrap must not affect the cashbook. Account % is a cash/bank account; scrap cash is parked in Scrap Clearing (12190) and banked separately.', new.account_code;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "erp"."_trg_block_scrap_cashbook"() OWNER TO "postgres";

--
-- Name: _trg_guard_negative_inventory(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_trg_guard_negative_inventory"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item_id uuid;
  v_warehouse_id uuid;
  v_current numeric;
  v_projected numeric;
  v_old_delta numeric := 0;
  v_new_delta numeric := 0;
  v_allow boolean := false;
begin
  if tg_op = 'DELETE' then
    v_item_id := old.item_id;
    v_warehouse_id := old.warehouse_id;
  else
    v_item_id := new.item_id;
    v_warehouse_id := new.warehouse_id;
  end if;

  -- Moving a row between item/warehouse pairs is rare and must validate both
  -- sides; reject it here so callers use delete+insert under the same guard.
  if tg_op = 'UPDATE'
     and (new.item_id is distinct from old.item_id
       or new.warehouse_id is distinct from old.warehouse_id) then
    raise exception 'Changing movement item/warehouse is not allowed; replace the movement instead';
  end if;

  select coalesce(w.allow_negative_stock, false)
  into v_allow
  from erp.warehouses w
  where w.id = v_warehouse_id;
  if v_allow then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_item_id::text || ':' || v_warehouse_id::text, 0)
  );

  select coalesce(sum(coalesce(im.qty_in, 0) - coalesce(im.qty_out, 0)), 0)
  into v_current
  from erp.inventory_movements im
  where im.item_id = v_item_id
    and im.warehouse_id = v_warehouse_id;

  if tg_op in ('UPDATE', 'DELETE') then
    v_old_delta := coalesce(old.qty_in, 0) - coalesce(old.qty_out, 0);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    v_new_delta := coalesce(new.qty_in, 0) - coalesce(new.qty_out, 0);
  end if;

  v_projected := v_current - v_old_delta + v_new_delta;

  -- Existing negative data is grandfathered only while a write leaves it
  -- unchanged or improves it. New/worsening deficits are blocked.
  if v_projected < -0.0005 and v_projected < v_current - 0.0005 then
    raise exception
      'Negative stock blocked for item % warehouse %: current % kg, projected % kg. Configure warehouses.allow_negative_stock only for transit/clearing.',
      v_item_id, v_warehouse_id, round(v_current, 3), round(v_projected, 3)
      using errcode = '23514';
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;


ALTER FUNCTION "erp"."_trg_guard_negative_inventory"() OWNER TO "postgres";

--
-- Name: _trg_inventory_in_restamp_downstream_sales(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_trg_inventory_in_restamp_downstream_sales"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if erp._cogs_restamp_skipped() then
    return new;
  end if;

  if coalesce(new.qty_in, 0) <= 0 then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.posting_date is not distinct from old.posting_date
       and new.qty_in is not distinct from old.qty_in
       and new.unit_cost is not distinct from old.unit_cost
       and new.value_amount is not distinct from old.value_amount
       and new.item_id is not distinct from old.item_id
       and new.warehouse_id is not distinct from old.warehouse_id then
      return new;
    end if;
  end if;

  perform erp._restamp_sales_cogs_for_item_wh(new.item_id, new.warehouse_id, new.id);
  return new;
end;
$$;


ALTER FUNCTION "erp"."_trg_inventory_in_restamp_downstream_sales"() OWNER TO "postgres";

