--
-- Name: _trg_journal_lines_balance_check(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_trg_journal_lines_balance_check"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je_id uuid;
  v_dr numeric;
  v_cr numeric;
  v_status text;
begin
  v_je_id := coalesce((case when TG_OP in ('INSERT','UPDATE') then NEW.journal_entry_id end), (case when TG_OP in ('UPDATE','DELETE') then OLD.journal_entry_id end));
  if v_je_id is null then return null; end if;
  select je.status into v_status from erp.journal_entries je where je.id = v_je_id;
  if not found or v_status <> 'posted' then return null; end if;
  select coalesce(sum(debit_amount), 0), coalesce(sum(credit_amount), 0) into v_dr, v_cr from erp.journal_lines where journal_entry_id = v_je_id;
  if abs(round(v_dr - v_cr, 3)) > 0.01 then raise exception 'Journal entry % is unbalanced (dr=%, cr=%); cannot commit a posted JE', v_je_id, v_dr, v_cr using errcode = 'P0001'; end if;
  return null;
end;
$$;


ALTER FUNCTION "erp"."_trg_journal_lines_balance_check"() OWNER TO "postgres";

--
-- Name: _trg_pending_purchase_return_variance(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_trg_pending_purchase_return_variance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je_id uuid;
  v_inv text;
  v_var text;
  v_name text;
  v_line erp.purchase_return_lines%rowtype;
begin
  if old.status = 'open'
     and new.status = 'fixed'
     and new.source_doc_type = 'purchase_return' then
    select * into v_line
    from erp.purchase_return_lines
    where id = new.source_line_id;

    v_inv := erp._resolve_posting_account('purchase_return', 'inventory');
    v_var := coalesce(erp._lookup_posting_account('purchase_return', 'cost_variance'), '51014');
    select name into v_name from erp.coa_accounts where code = v_var;

    select je.id into v_je_id
    from erp.journal_entries je
    where je.source_doc_type = 'purchase_return'
      and je.source_doc_id = new.source_doc_id
      and je.voucher_type = 'PURCHASE_RETURN'
      and coalesce(je.voucher_no, '') not like 'VOID-%'
    order by je.posted_at desc nulls last, je.id desc
    limit 1;

    if v_je_id is not null then
      update erp.journal_lines
      set account_code = v_var,
          account_name = coalesce(v_name, 'Purchase Return Cost Variance'),
          line_description = 'Purchase return rate fix variance'
      where journal_entry_id = v_je_id
        and account_code = v_inv
        and credit_amount > 0;
    end if;

    update erp.purchase_return_lines
    set cost_variance_amount = round(
      new.fixed_amount - coalesce(inventory_value_amount, 0),
      3
    )
    where id = new.source_line_id;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "erp"."_trg_pending_purchase_return_variance"() OWNER TO "postgres";

--
-- Name: _trg_pending_rate_provisional_gl(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_trg_pending_rate_provisional_gl"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_pending_id uuid;
begin
  if tg_table_name = 'pending_rate_items' then
    if tg_op = 'INSERT' and new.source_doc_type = 'purchase_invoice'
       and new.status = 'open' then
      perform erp._sync_pending_rate_provisional_gl(new.id);
    elsif tg_op = 'UPDATE' and old.status = 'open' and new.status = 'fixed'
       and new.source_doc_type = 'purchase_invoice' then
      update erp.journal_entries
      set voucher_no = 'VOID-' || voucher_no,
          narration = coalesce(narration, '')
            || ' [replaced by fixed-rate Inventory/AP posting]'
      where source_doc_type = 'pending_rate_provisional'
        and source_doc_id = new.id
        and coalesce(voucher_no, '') not like 'VOID-%';
    end if;
    return null;
  end if;

  if tg_table_name = 'inventory_movements' and tg_op = 'UPDATE'
     and new.source_doc_type = 'purchase_invoice'
     and new.movement_type = 'purchase_in'
     and (
       new.unit_cost is distinct from old.unit_cost
       or new.value_amount is distinct from old.value_amount
     ) then
    select pri.id into v_pending_id
    from erp.pending_rate_items pri
    where pri.source_doc_type = 'purchase_invoice'
      and pri.source_doc_id = new.source_doc_id
      and pri.source_line_id = new.source_line_id
      and pri.status = 'open'
    order by pri.created_at, pri.id
    limit 1;
    if v_pending_id is not null then
      perform erp._sync_pending_rate_provisional_gl(v_pending_id);
    end if;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "erp"."_trg_pending_rate_provisional_gl"() OWNER TO "postgres";

--
-- Name: _trg_pending_receipt_provisional_cost(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_trg_pending_receipt_provisional_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_rate numeric;
begin
  if coalesce(new.qty_in, 0) <= 0
     or coalesce(new.value_amount, 0) <> 0
     or coalesce(new.unit_cost, 0) <> 0
     or not erp._inventory_movement_is_rate_pending(
       new.source_doc_type, new.source_doc_id, new.source_line_id
     ) then
    return new;
  end if;

  v_rate := erp._inventory_provisional_receipt_unit_cost(new.id);
  if coalesce(v_rate, 0) > 0 then
    update erp.inventory_movements
    set unit_cost = v_rate,
        value_amount = round(qty_in * v_rate, 3),
        cost_status = 'provisional',
        costed_period_id = null
    where id = new.id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "erp"."_trg_pending_receipt_provisional_cost"() OWNER TO "postgres";

--
-- Name: _trg_return_movement_keep_inventory_cost(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_trg_return_movement_keep_inventory_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if new.source_doc_type in ('sales_return', 'purchase_return')
     and new.movement_type in ('sales_return_in', 'purchase_return_out') then
    new.value_amount := round(
      coalesce(nullif(new.qty_in, 0), new.qty_out, 0) * coalesce(new.unit_cost, 0),
      3
    );
  end if;
  return new;
end;
$$;


