--
-- Name: _trg_void_movement_exact_mirror(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_trg_void_movement_exact_mirror"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $_$
declare
  v_original erp.inventory_movements%rowtype;
  v_original_source_type text;
  v_original_movement_type text;
begin
  if new.source_doc_type not in ('scrap_trade_void', 'production_batch_void') then
    return new;
  end if;

  v_original_source_type := case new.source_doc_type
    when 'scrap_trade_void' then 'scrap_trade'
    else 'production_batch'
  end;
  v_original_movement_type := regexp_replace(new.movement_type, '_void$', '');

  select im.* into v_original
  from erp.inventory_movements im
  where im.source_doc_type = v_original_source_type
    and im.source_doc_id = new.source_doc_id
    and im.movement_type = v_original_movement_type
    and im.item_id is not distinct from new.item_id
    and im.warehouse_id is not distinct from new.warehouse_id
    and coalesce(im.qty_in, 0) = coalesce(new.qty_out, 0)
    and coalesce(im.qty_out, 0) = coalesce(new.qty_in, 0)
    and not exists (
      select 1
      from erp.inventory_movements vm
      where vm.source_doc_type = new.source_doc_type
        and vm.source_doc_id = new.source_doc_id
        and vm.source_line_id = im.id
    )
  order by im.created_at, im.id
  limit 1;

  if found then
    -- source_line_id is an audit pointer to the mirrored movement for void rows.
    new.source_line_id := v_original.id;
    new.unit_cost := coalesce(
      nullif(v_original.unit_cost, 0),
      v_original.value_amount
        / nullif(coalesce(nullif(v_original.qty_in, 0), v_original.qty_out), 0),
      0
    );
    new.value_amount := abs(coalesce(v_original.value_amount, 0));
    new.cost_copper := abs(coalesce(v_original.cost_copper, 0));
    new.cost_varnish := abs(coalesce(v_original.cost_varnish, 0));
    new.cost_packing := abs(coalesce(v_original.cost_packing, 0));
    new.cost_oh := abs(coalesce(v_original.cost_oh, 0));
  end if;
  return new;
end;
$_$;


ALTER FUNCTION "erp"."_trg_void_movement_exact_mirror"() OWNER TO "postgres";

