-- Name: _upsert_party_scrap_credit("uuid", "uuid", numeric, "uuid", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_upsert_party_scrap_credit"("p_party_id" "uuid", "p_scrap_trade_id" "uuid", "p_credit_kg" numeric, "p_pending_rate_item_id" "uuid" DEFAULT NULL::"uuid", "p_ref_scrap_rate" numeric DEFAULT NULL::numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  insert into erp.party_scrap_credits (
    party_id, source_doc_type, source_doc_id, pending_rate_item_id, credit_kg, ref_scrap_rate, status
  ) values (
    p_party_id, 'scrap_trade', p_scrap_trade_id, p_pending_rate_item_id, p_credit_kg, p_ref_scrap_rate, 'open'
  )
  on conflict (source_doc_type, source_doc_id) do update
  set credit_kg = excluded.credit_kg,
      pending_rate_item_id = coalesce(excluded.pending_rate_item_id, erp.party_scrap_credits.pending_rate_item_id),
      ref_scrap_rate = coalesce(excluded.ref_scrap_rate, erp.party_scrap_credits.ref_scrap_rate)
  returning id into v_id;

  perform erp._sync_party_scrap_credit_status(v_id);
  return v_id;
end;
$$;


