--
-- Name: _validate_production_mass_balance("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_validate_production_mass_balance"("p_batch_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.production_batches%rowtype;
  v_in numeric;
  v_out numeric;
  v_scrap numeric;
  v_loss numeric;
  v_tol numeric;
  v_std_pct numeric;
begin
  select * into v_doc from erp.production_batches where id = p_batch_id;
  if not found then return; end if;

  select t.input_kg, t.output_kg, t.scrap_kg
  into v_in, v_out, v_scrap
  from erp._production_batch_totals(p_batch_id) t;

  if v_doc.process_type in ('drawing', 'workshop') then
    if v_in <= 0 then
      raise exception 'Production batch requires input (issue) weight';
    end if;
    if v_out <= 0 then
      raise exception 'Production batch requires output (receipt) weight';
    end if;
    v_std_pct := case v_doc.process_type
      when 'drawing' then erp._production_standard_num('drawing_wastage_pct')
      else erp._production_standard_num('workshop_wastage_pct')
    end;
    v_tol := greatest(0.5, v_in * 2 * coalesce(v_std_pct, 0) / 100.0);
    v_loss := v_in - v_out;
    if v_loss < -v_tol then
      raise exception 'Output % kg exceeds input % kg (tol % kg)',
        round(v_out, 3), round(v_in, 3), round(v_tol, 3);
    end if;
    if v_loss > v_tol then
      raise exception 'Mass balance failed: input % kg exceeds output % kg by more than tolerance % kg (implicit yield loss)',
        round(v_in, 3), round(v_out, 3), round(v_tol, 3);
    end if;
  elsif v_doc.process_type = 'enamel' then
    if v_out <= 0 then
      raise exception 'Enamel batch requires output (receipt) weight';
    end if;
    if v_in > 0 and abs(v_in - v_out) > 0.5 + v_out * 0.01 then
      raise exception 'Enamel mass balance failed: issues % kg (wire + varnish) ≠ output % kg',
        round(v_in, 3), round(v_out, 3);
    end if;
  end if;
end;
$$;


ALTER FUNCTION "erp"."_validate_production_mass_balance"("p_batch_id" "uuid") OWNER TO "postgres";

--
-- Name: _varnish_drum_weight_kg("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_varnish_drum_weight_kg"("p_item_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_spec text;
  v_match text[];
  v_std numeric;
begin
  select i.size_spec into v_spec from erp.items i where i.id = p_item_id;
  if v_spec is null then
    v_std := coalesce(nullif(erp._production_standard_num('varnish_drum_weight_kg'), 0), 200);
    return v_std;
  end if;

  v_match := regexp_match(v_spec, '(\d+(?:\.\d+)?)\s*kg', 'i');
  if v_match is not null and coalesce(v_match[1], '') ~ '^\d' then
    return greatest(v_match[1]::numeric, 0.001);
  end if;

  v_std := coalesce(nullif(erp._production_standard_num('varnish_drum_weight_kg'), 0), 200);
  return v_std;
end;
$$;


ALTER FUNCTION "erp"."_varnish_drum_weight_kg"("p_item_id" "uuid") OWNER TO "postgres";

--
-- Name: _varnish_units_from_kg("uuid", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_varnish_units_from_kg"("p_item_id" "uuid", "p_kg" numeric) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select case
    when erp._is_varnish_item(p_item_id) and coalesce(p_kg, 0) > 0
    then round(p_kg / erp._varnish_drum_weight_kg(p_item_id), 3)
    else 0
  end;
$$;


