--
-- Name: _void_rename_active_journals("text", "uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_void_rename_active_journals"("p_source_doc_type" "text", "p_source_doc_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je record;
  v_count int := 0;
begin
  for v_je in
    select je.id, je.voucher_no
    from erp.journal_entries je
    where je.source_doc_type = p_source_doc_type
      and je.source_doc_id = p_source_doc_id
      and coalesce(je.voucher_no, '') not like 'VOID-%'
    order by je.posted_at nulls last, je.id
    for update
  loop
    update erp.journal_entries
    set voucher_no = 'VOID-' || coalesce(nullif(v_je.voucher_no, ''), p_source_doc_type)
          || '-' || left(v_je.id::text, 8),
        narration = concat_ws(
          ' ',
          nullif(narration, ''),
          '[void-excluded:',
          coalesce(nullif(trim(p_reason), ''), 'document void'),
          ']'
        )
    where id = v_je.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


