--
-- Name: _wac_rebuild_source_fingerprint(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."_wac_rebuild_source_fingerprint"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'movements', (
      select jsonb_build_object(
        'count', count(*),
        'max_created_at', max(im.created_at),
        'max_id', max(im.id::text),
        'qty_in', round(coalesce(sum(im.qty_in), 0), 3),
        'qty_out', round(coalesce(sum(im.qty_out), 0), 3),
        'value', round(coalesce(sum(im.value_amount), 0), 3),
        'row_digest', md5(coalesce(string_agg(
          concat_ws('|', im.id::text, im.posting_date::text, im.created_at::text,
            im.item_id::text, im.warehouse_id::text, im.movement_type,
            coalesce(im.qty_in,0)::text, coalesce(im.qty_out,0)::text,
            coalesce(im.unit_cost,0)::text, coalesce(im.value_amount,0)::text,
            coalesce(im.cost_copper,0)::text, coalesce(im.cost_varnish,0)::text,
            coalesce(im.cost_packing,0)::text, coalesce(im.cost_oh,0)::text,
            coalesce(im.cost_status,''), coalesce(im.costed_period_id::text,'')),
          '||' order by im.id::text
        ), ''))
      )
      from erp.inventory_movements im
    ),
    'active_cost_journals', (
      select jsonb_build_object(
        'entry_count', count(distinct je.id),
        'line_count', count(jl.id),
        'max_entry_id', max(je.id::text),
        'max_posted_at', max(je.posted_at),
        'debit', round(coalesce(sum(jl.debit_amount), 0), 3),
        'credit', round(coalesce(sum(jl.credit_amount), 0), 3)
      )
      from erp.journal_entries je
      left join erp.journal_lines jl on jl.journal_entry_id = je.id
      where coalesce(je.voucher_no, '') not like 'VOID-%'
        and je.source_doc_type in (
          'sales_invoice','sales_return','sales_return_cogs',
          'purchase_return','purchase_return_cost_sync','production_batch'
        )
    )
  );
$$;


