-- Name: admin_confirm_auth_user("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."admin_confirm_auth_user"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'erp', 'pg_temp'
    AS $$
begin
  if not erp.has_role('ADMIN') then
    raise exception 'Admin access required';
  end if;

  if p_user_id is null then
    raise exception 'User id is required';
  end if;

  update auth.users
  set
    email_confirmed_at = coalesce(email_confirmed_at, now()),
    updated_at = now()
  where id = p_user_id;

  if not found then
    raise exception 'Auth user not found';
  end if;
end;
$$;


