--
-- Name: admin_create_managed_user("text", "text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."admin_create_managed_user"("p_email" "text", "p_password" "text", "p_display_name" "text", "p_role_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'erp', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid;
  v_email text;
  v_display_name text;
  v_role_code text;
  v_fully_provisioned boolean;
begin
  if not erp.has_role('ADMIN') then
    raise exception 'Admin access required';
  end if;

  v_email := lower(trim(coalesce(p_email, '')));
  v_display_name := trim(coalesce(p_display_name, ''));
  v_role_code := upper(trim(coalesce(p_role_code, '')));

  if v_email = '' then
    raise exception 'Email is required';
  end if;
  if length(coalesce(p_password, '')) < 6 then
    raise exception 'Password must be at least 6 characters';
  end if;
  if v_display_name = '' then
    raise exception 'Display name is required';
  end if;
  if v_role_code not in ('ADMIN', 'ACCOUNTANT') then
    raise exception 'Invalid role code: %', v_role_code;
  end if;

  select u.id
    into v_user_id
  from auth.users u
  where lower(u.email) = v_email
  limit 1;

  if v_user_id is not null then
    select exists (
      select 1
      from auth.users u
      where u.id = v_user_id
        and u.email_confirmed_at is not null
        and exists (
          select 1
          from erp.user_profiles up
          join erp.user_role_assignments ura on ura.user_id = up.user_id
          where up.user_id = v_user_id
            and up.is_active = true
        )
    ) into v_fully_provisioned;

    if v_fully_provisioned then
      raise exception 'User with this email already exists';
    end if;

    perform erp.admin_finalize_managed_user(
      v_user_id,
      v_email,
      v_display_name,
      v_role_code,
      p_password
    );

    return v_user_id;
  end if;

  v_user_id := gen_random_uuid();

  insert into auth.users (
    id,
    instance_id,
    aud,
    role,
    email,
    encrypted_password,
    email_confirmed_at,
    raw_app_meta_data,
    raw_user_meta_data,
    created_at,
    updated_at,
    confirmation_token,
    email_change,
    email_change_token_new,
    recovery_token,
    is_sso_user
  ) values (
    v_user_id,
    '00000000-0000-0000-0000-000000000000'::uuid,
    'authenticated',
    'authenticated',
    v_email,
    extensions.crypt(p_password, extensions.gen_salt('bf')),
    now(),
    '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('display_name', v_display_name),
    now(),
    now(),
    '',
    '',
    '',
    '',
    false
  );

  insert into auth.identities (
    id,
    user_id,
    identity_data,
    provider,
    provider_id,
    last_sign_in_at,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_user_id,
    jsonb_build_object(
      'sub', v_user_id::text,
      'email', v_email,
      'email_verified', true,
      'phone_verified', false
    ),
    'email',
    v_user_id::text,
    now(),
    now(),
    now()
  );

  insert into erp.user_profiles (user_id, display_name, email, is_active)
  values (v_user_id, v_display_name, v_email, true)
  on conflict (user_id) do update
    set display_name = excluded.display_name,
        email = excluded.email,
        is_active = true;

  perform erp._admin_assign_app_role(v_user_id, v_role_code);

  return v_user_id;
end;
$$;


ALTER FUNCTION "erp"."admin_create_managed_user"("p_email" "text", "p_password" "text", "p_display_name" "text", "p_role_code" "text") OWNER TO "postgres";

--
-- Name: admin_finalize_managed_user("uuid", "text", "text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."admin_finalize_managed_user"("p_user_id" "uuid", "p_email" "text", "p_display_name" "text", "p_role_code" "text", "p_password" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'erp', 'extensions', 'pg_temp'
    AS $$
declare
  v_email text;
  v_display_name text;
begin
  if not erp.has_role('ADMIN') then
    raise exception 'Admin access required';
  end if;

  if p_user_id is null then
    raise exception 'User id is required';
  end if;

  v_email := lower(trim(coalesce(p_email, '')));
  v_display_name := trim(coalesce(p_display_name, ''));

  if v_email = '' then
    raise exception 'Email is required';
  end if;
  if v_display_name = '' then
    raise exception 'Display name is required';
  end if;

  perform erp.admin_confirm_auth_user(p_user_id);

  if p_password is not null and length(p_password) >= 6 then
    update auth.users
    set
      encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf')),
      raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb)
        || jsonb_build_object('display_name', v_display_name),
      updated_at = now()
    where id = p_user_id;
  else
    update auth.users
    set
      raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb)
        || jsonb_build_object('display_name', v_display_name),
      updated_at = now()
    where id = p_user_id;
  end if;

  insert into erp.user_profiles (user_id, display_name, email, is_active)
  values (p_user_id, v_display_name, v_email, true)
  on conflict (user_id) do update
    set display_name = excluded.display_name,
        email = excluded.email,
        is_active = true;

  perform erp._admin_assign_app_role(p_user_id, p_role_code);
end;
$$;


ALTER FUNCTION "erp"."admin_finalize_managed_user"("p_user_id" "uuid", "p_email" "text", "p_display_name" "text", "p_role_code" "text", "p_password" "text") OWNER TO "postgres";

