--
-- Name: admin_repair_managed_user("text", "text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."admin_repair_managed_user"("p_email" "text", "p_password" "text", "p_display_name" "text", "p_role_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'erp', 'extensions', 'pg_temp'
    AS $$
declare
  v_user_id uuid;
  v_email text;
begin
  if not erp.has_role('ADMIN') then
    raise exception 'Admin access required';
  end if;

  v_email := lower(trim(coalesce(p_email, '')));
  if v_email = '' then
    raise exception 'Email is required';
  end if;
  if length(coalesce(p_password, '')) < 6 then
    raise exception 'Password must be at least 6 characters';
  end if;

  select u.id
    into v_user_id
  from auth.users u
  where lower(u.email) = v_email
  limit 1;

  if v_user_id is null then
    raise exception 'No auth user found for this email';
  end if;

  if exists (
    select 1
    from auth.users u
    where u.id = v_user_id
      and u.email_confirmed_at is not null
      and exists (
        select 1
        from erp.user_profiles up
        join erp.user_role_assignments ura on ura.user_id = up.user_id
        where up.user_id = v_user_id
          and up.is_active = true
      )
  ) then
    raise exception 'User with this email already exists';
  end if;

  perform erp.admin_finalize_managed_user(
    v_user_id,
    v_email,
    p_display_name,
    p_role_code,
    p_password
  );

  return v_user_id;
end;
$$;


