--
-- Name: admin_update_managed_user("uuid", "text", "text", "text", boolean, "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."admin_update_managed_user"("p_user_id" "uuid", "p_display_name" "text", "p_email" "text", "p_role_code" "text", "p_is_active" boolean, "p_password" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'erp', 'extensions', 'pg_temp'
    AS $$
declare
  v_email text;
  v_display_name text;
  v_current_email text;
begin
  if not erp.has_role('ADMIN') then
    raise exception 'Admin access required';
  end if;

  if p_user_id is null then
    raise exception 'User id is required';
  end if;

  if p_user_id = auth.uid() and coalesce(p_is_active, true) = false then
    raise exception 'You cannot deactivate your own account';
  end if;

  v_email := lower(trim(coalesce(p_email, '')));
  v_display_name := trim(coalesce(p_display_name, ''));

  if v_email = '' then
    raise exception 'Email is required';
  end if;
  if v_display_name = '' then
    raise exception 'Display name is required';
  end if;

  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    raise exception 'Auth user not found';
  end if;

  select lower(u.email)
    into v_current_email
  from auth.users u
  where u.id = p_user_id;

  if exists (
    select 1
    from auth.users u
    where lower(u.email) = v_email
      and u.id <> p_user_id
  ) then
    raise exception 'Another user already uses this email';
  end if;

  if v_current_email is distinct from v_email then
    update auth.users
    set
      email = v_email,
      raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb)
        || jsonb_build_object('display_name', v_display_name),
      updated_at = now()
    where id = p_user_id;

    begin
      update auth.identities i
      set
        identity_data = jsonb_build_object(
          'sub', p_user_id::text,
          'email', v_email,
          'email_verified', true,
          'phone_verified', false
        ),
        updated_at = now()
      where i.user_id = p_user_id
        and i.provider = 'email';
    exception
      when others then
        null;
    end;
  else
    update auth.users
    set
      raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb)
        || jsonb_build_object('display_name', v_display_name),
      updated_at = now()
    where id = p_user_id;
  end if;

  if p_password is not null and length(p_password) >= 6 then
    update auth.users
    set
      encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf')),
      updated_at = now()
    where id = p_user_id;
  end if;

  update auth.users
  set
    banned_until = case
      when coalesce(p_is_active, true) then null
      else '9999-12-31 23:59:59+00'::timestamptz
    end,
    updated_at = now()
  where id = p_user_id;

  insert into erp.user_profiles (user_id, display_name, email, is_active)
  values (p_user_id, v_display_name, v_email, coalesce(p_is_active, true))
  on conflict (user_id) do update
    set display_name = excluded.display_name,
        email = excluded.email,
        is_active = excluded.is_active;

  perform erp._admin_assign_app_role(p_user_id, p_role_code);
end;
$$;


ALTER FUNCTION "erp"."admin_update_managed_user"("p_user_id" "uuid", "p_display_name" "text", "p_email" "text", "p_role_code" "text", "p_is_active" boolean, "p_password" "text") OWNER TO "postgres";

--
-- Name: apply_watta_matrix_recalc("text", "date", "uuid", "text", "text", boolean, integer, "uuid", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."apply_watta_matrix_recalc"("p_direction" "text" DEFAULT 'sales'::"text", "p_effective_from" "date" DEFAULT CURRENT_DATE, "p_party_id" "uuid" DEFAULT NULL::"uuid", "p_product_kind" "text" DEFAULT 'enamel'::"text", "p_wire8_grade" "text" DEFAULT NULL::"text", "p_include_posted" boolean DEFAULT true, "p_batch_size" integer DEFAULT 25, "p_after_invoice_id" "uuid" DEFAULT NULL::"uuid", "p_dry_run" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_inv record;
  v_recalc jsonb;
  v_adj jsonb;
  v_old_grand numeric;
  v_new_grand numeric;
  v_processed int := 0;
  v_updated_drafts int := 0;
  v_updated_posted int := 0;
  v_skipped int := 0;
  v_unchanged int := 0;
  v_skipped_items jsonb := '[]'::jsonb;
  v_last_id uuid := p_after_invoice_id;
  v_done boolean := false;
  v_total_estimate int;
begin
  if p_direction <> 'sales' or p_product_kind <> 'enamel' then
    return jsonb_build_object('ok', false, 'error', 'Only sales/enamel recalc is supported in this release');
  end if;

  select count(*)::int into v_total_estimate
  from erp.sales_invoices si
  where si.sale_mode = 'premium'
    and si.invoice_date >= p_effective_from
    and si.posting_status in ('draft', 'posted')
    and (p_party_id is null or si.party_id = p_party_id)
    and exists (
      select 1 from erp.sales_invoice_lines l
      where l.sales_invoice_id = si.id
        and erp._item_product_kind(l.item_id) = 'enamel'
    );

  if p_dry_run then
    return jsonb_build_object(
      'ok', true,
      'dry_run', true,
      'estimated_total', v_total_estimate,
      'done', true
    );
  end if;

  for v_inv in
    select si.id, si.posting_status
    from erp.sales_invoices si
    where si.sale_mode = 'premium'
      and si.invoice_date >= p_effective_from
      and si.posting_status in ('draft', 'posted')
      and (p_party_id is null or si.party_id = p_party_id)
      and (p_after_invoice_id is null or si.id > p_after_invoice_id)
      and exists (
        select 1 from erp.sales_invoice_lines l
        where l.sales_invoice_id = si.id
          and erp._item_product_kind(l.item_id) = 'enamel'
      )
    order by si.id
    limit greatest(1, least(coalesce(p_batch_size, 25), 100))
  loop
    v_last_id := v_inv.id;
    v_processed := v_processed + 1;

    v_recalc := erp._recalc_premium_sales_invoice(v_inv.id);
    if not coalesce((v_recalc->>'ok')::boolean, false) then
      v_skipped := v_skipped + 1;
      v_skipped_items := v_skipped_items || jsonb_build_array(jsonb_build_object(
        'invoice_id', v_inv.id,
        'reason', coalesce(v_recalc->>'error', 'recalc failed')
      ));
      continue;
    end if;

    v_old_grand := (v_recalc->>'old_grand')::numeric;
    v_new_grand := (v_recalc->>'new_grand')::numeric;

    if not coalesce((v_recalc->>'changed')::boolean, false) then
      v_unchanged := v_unchanged + 1;
      continue;
    end if;

    if v_inv.posting_status = 'draft' then
      v_updated_drafts := v_updated_drafts + 1;
      insert into erp.watta_recalc_log (sales_invoice_id, old_grand_total, new_grand_total, lines_changed, posting_status, effective_from)
      values (
        v_inv.id, v_old_grand, v_new_grand,
        coalesce((v_recalc->>'lines_changed')::int, 0),
        'draft', p_effective_from
      );
    elsif v_inv.posting_status = 'posted' and p_include_posted then
      v_adj := erp._adjust_posted_sales_invoice_financials(
        v_inv.id,
        v_old_grand,
        v_new_grand,
        p_effective_from,
        (v_recalc->>'old_tax')::numeric,
        (v_recalc->>'new_tax')::numeric
      );
      if coalesce((v_adj->>'skipped')::boolean, false) then
        v_skipped := v_skipped + 1;
        v_skipped_items := v_skipped_items || jsonb_build_array(jsonb_build_object(
          'invoice_id', v_inv.id,
          'reason', coalesce(v_adj->>'reason', 'skipped')
        ));
        insert into erp.watta_recalc_log (sales_invoice_id, old_grand_total, new_grand_total, lines_changed, posting_status, skipped_reason, effective_from)
        values (
          v_inv.id, v_old_grand, v_new_grand,
          coalesce((v_recalc->>'lines_changed')::int, 0),
          'posted', v_adj->>'reason', p_effective_from
        );
      elsif coalesce((v_adj->>'ok')::boolean, false) then
        v_updated_posted := v_updated_posted + 1;
        insert into erp.watta_recalc_log (sales_invoice_id, old_grand_total, new_grand_total, lines_changed, posting_status, effective_from)
        values (
          v_inv.id, v_old_grand, v_new_grand,
          coalesce((v_recalc->>'lines_changed')::int, 0),
          'posted', p_effective_from
        );
      else
        v_skipped := v_skipped + 1;
      end if;
    end if;
  end loop;

  if v_processed < greatest(1, least(coalesce(p_batch_size, 25), 100)) then
    v_done := true;
  end if;

  return jsonb_build_object(
    'ok', true,
    'done', v_done,
    'last_invoice_id', v_last_id,
    'processed', v_processed,
    'updated_drafts', v_updated_drafts,
    'updated_posted', v_updated_posted,
    'skipped', v_skipped,
    'unchanged', v_unchanged,
    'estimated_total', v_total_estimate,
    'skipped_items', v_skipped_items
  );
end;
$$;


ALTER FUNCTION "erp"."apply_watta_matrix_recalc"("p_direction" "text", "p_effective_from" "date", "p_party_id" "uuid", "p_product_kind" "text", "p_wire8_grade" "text", "p_include_posted" boolean, "p_batch_size" integer, "p_after_invoice_id" "uuid", "p_dry_run" boolean) OWNER TO "postgres";

--
-- Name: audit_all_wac_and_gl(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."audit_all_wac_and_gl"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_run_id uuid := gen_random_uuid();
  v_fingerprint jsonb;
  v_summary jsonb;
  v_movements bigint;
  v_pairs bigint;
  v_negative bigint;
  v_fallback bigint;
  v_zero bigint;
  v_changed bigint;
  v_value_delta numeric;
  v_sales_expected numeric;
  v_sales_gl numeric;
  v_return_expected numeric;
  v_return_gl numeric;
  v_prod_expected numeric;
  v_prod_gl numeric;
  v_locked_count bigint;
begin
  perform erp._assert_report_access();
  perform erp._build_all_wac_replay();

  select count(*), count(distinct (item_id, warehouse_id))
  into v_movements, v_pairs
  from pg_temp.wac_replay_results;

  select
    count(*) filter (where negative_event),
    count(*) filter (where fallback_used),
    count(*) filter (where unresolved_zero_cost),
    count(*) filter (
      where abs(movement_value_delta) > 0.01
         or abs(expected_unit_cost - current_unit_cost) > 0.000001
    ),
    coalesce(sum(movement_value_delta), 0)
  into v_negative, v_fallback, v_zero, v_changed, v_value_delta
  from pg_temp.wac_replay_results;

  select coalesce(sum(expected_value), 0)
  into v_sales_expected
  from pg_temp.wac_replay_results
  where movement_type = 'sales_out' and source_doc_type = 'sales_invoice';

  select coalesce(sum(jl.debit_amount), 0)
  into v_sales_gl
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where je.source_doc_type = 'sales_invoice'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    and jl.account_code in ('51001','51010','51011','51012','51013');

  select coalesce(sum(expected_value), 0)
  into v_return_expected
  from pg_temp.wac_replay_results
  where movement_type = 'sales_return_in' and source_doc_type = 'sales_return';

  select coalesce(sum(jl.credit_amount), 0)
  into v_return_gl
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where je.source_doc_type in ('sales_return', 'sales_return_cogs')
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    and jl.account_code in ('51001','51010','51011','51012','51013');

  select coalesce(sum(expected_value) filter (where movement_type = 'production_receipt'), 0)
  into v_prod_expected
  from pg_temp.wac_replay_results
  where source_doc_type = 'production_batch';

  select coalesce(sum(jl.debit_amount), 0)
  into v_prod_gl
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where je.source_doc_type = 'production_batch'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    and jl.account_code = coalesce(
      erp._lookup_posting_account('production_batch', 'inventory_fg'), '12301'
    );

  v_fingerprint := erp._wac_rebuild_source_fingerprint();

  v_summary := jsonb_build_object(
    'negative_events', v_negative,
    'fallback_movements', v_fallback,
    'unresolved_zero_cost_inbound', v_zero,
    'movements_with_delta', v_changed,
    'movement_value_delta', round(v_value_delta, 3),
    'sales_expected_cogs', round(v_sales_expected, 3),
    'sales_active_gl_cogs', round(v_sales_gl, 3),
    'sales_gl_delta', round(v_sales_expected - v_sales_gl, 3),
    'sales_return_expected_cogs_credit', round(v_return_expected, 3),
    'sales_return_active_gl_cogs_credit', round(v_return_gl, 3),
    'sales_return_gl_delta', round(v_return_expected - v_return_gl, 3),
    'production_expected_fg', round(v_prod_expected, 3),
    'production_active_gl_fg', round(v_prod_gl, 3),
    'production_gl_delta', round(v_prod_expected - v_prod_gl, 3)
  );

  insert into erp.wac_rebuild_audit_runs (
    id, created_by, status, is_executable, algorithm_version,
    movement_count, pair_count, source_fingerprint, summary
  ) values (
    v_run_id, auth.uid(), 'succeeded', v_zero = 0,
    '292.1-posting_date-created_at-id', v_movements, v_pairs,
    v_fingerprint, v_summary
  );

  insert into erp.wac_rebuild_audit_details (
    audit_run_id, movement_id, item_id, warehouse_id, posting_date, created_at,
    movement_type, source_doc_type, source_doc_id, source_line_id,
    qty_in, qty_out, qty_before, qty_after, negative_event, locked_pac_stamp,
    cost_source, fallback_used, unresolved_zero_cost,
    current_unit_cost, expected_unit_cost, current_value, expected_value,
    movement_value_delta, wac_before, wac_after,
    current_copper, expected_copper, current_varnish, expected_varnish,
    current_packing, expected_packing, current_oh, expected_oh
  )
  select
    v_run_id, movement_id, item_id, warehouse_id, posting_date, created_at,
    movement_type, source_doc_type, source_doc_id, source_line_id,
    qty_in, qty_out, qty_before, qty_after, negative_event, locked_pac_stamp,
    cost_source, fallback_used, unresolved_zero_cost,
    current_unit_cost, expected_unit_cost, current_value, expected_value,
    movement_value_delta, wac_before, wac_after,
    current_copper, expected_copper, current_varnish, expected_varnish,
    current_packing, expected_packing, current_oh, expected_oh
  from pg_temp.wac_replay_results
  order by item_id, warehouse_id, posting_date, created_at, movement_id;

  insert into erp.wac_rebuild_affected_periods (
    audit_run_id, period_id, period_code, start_date, end_date,
    status_at_audit, affected_movement_count, estimated_value_delta
  )
  select
    v_run_id, cp.id, cp.period_code, cp.start_date, cp.end_date, cp.status,
    count(*), round(coalesce(sum(rr.movement_value_delta), 0), 3)
  from erp.costing_periods cp
  join pg_temp.wac_replay_results rr
    on rr.posting_date between cp.start_date and cp.end_date
  where cp.status = 'locked'
    and (
      abs(rr.movement_value_delta) > 0.01
      or abs(rr.expected_unit_cost - rr.current_unit_cost) > 0.000001
    )
  group by cp.id, cp.period_code, cp.start_date, cp.end_date, cp.status;

  get diagnostics v_locked_count = row_count;

  return jsonb_build_object(
    'ok', true,
    'audit_run_id', v_run_id,
    'is_executable', v_zero = 0,
    'movement_count', v_movements,
    'item_warehouse_pairs', v_pairs,
    'affected_locked_pac_periods', v_locked_count,
    'summary', v_summary,
    'note', 'No business ledger rows or PAC periods were changed'
  );
end;
$$;


ALTER FUNCTION "erp"."audit_all_wac_and_gl"() OWNER TO "postgres";

