--
-- Name: backfill_sales_cogs_journals(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."backfill_sales_cogs_journals"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc record;
  v_je_id uuid;
  v_cogs_total numeric;
  v_cogs_acct text;
  v_inv_acct text;
  v_count int := 0;
begin
  v_cogs_acct := erp._resolve_posting_account('sales_invoice', 'cogs');
  v_inv_acct := erp._resolve_posting_account('sales_invoice', 'inventory');

  for v_doc in
    select si.*
    from erp.sales_invoices si
    where si.posting_status = 'posted'
      and not exists (
        select 1
        from erp.journal_entries je
        join erp.journal_lines jl on jl.journal_entry_id = je.id
        where je.source_doc_id = si.id
          and je.source_doc_type = 'sales_invoice'
          and jl.account_code = v_cogs_acct
          and jl.debit_amount > 0
      )
  loop
    select coalesce(sum(im.value_amount), 0)
    into v_cogs_total
    from erp.inventory_movements im
    where im.source_doc_id = v_doc.id
      and im.source_doc_type = 'sales_invoice'
      and im.movement_type = 'sales_out';

    if v_cogs_total <= 0 then
      continue;
    end if;

    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
    ) values (
      v_doc.invoice_no || '-COGS', 'SALES_COGS_ADJ', v_doc.invoice_date, 'sales_invoice', v_doc.id, v_doc.invoice_no,
      'Backfill COGS for posted sales invoice', 'posted', now(), auth.uid()
    ) returning id into v_je_id;

    perform erp._insert_je_line(v_je_id, 1, v_cogs_acct, null, v_cogs_total, 0, 'COGS backfill');
    perform erp._insert_je_line(v_je_id, 2, v_inv_acct, null, 0, v_cogs_total, 'Inventory backfill');
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "erp"."backfill_sales_cogs_journals"() OWNER TO "postgres";

--
-- Name: backfill_sales_return_ar_offsets(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."backfill_sales_return_ar_offsets"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_r record;
  v_count int := 0;
begin
  for v_r in
    select sr.party_id, sr.grand_total
    from erp.sales_returns sr
    where sr.posting_status = 'posted'
      and exists (
        select 1 from erp.journal_entries je
        where je.source_doc_type = 'sales_return' and je.source_doc_id = sr.id
      )
  loop
    perform erp._reduce_ar_open(v_r.party_id, v_r.grand_total);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "erp"."backfill_sales_return_ar_offsets"() OWNER TO "postgres";

--
-- Name: batch_apply_parchi_clearances("uuid", "date", "jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."batch_apply_parchi_clearances"("p_payment_id" "uuid", "p_clearance_date" "date", "p_allocations" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_elem jsonb;
  v_parchi_id uuid;
  v_amount numeric;
  v_parchi erp.parchi_instruments%rowtype;
  v_cleared numeric;
  v_open numeric;
  v_rows jsonb := '[]'::jsonb;
begin
  for v_elem in select * from jsonb_array_elements(coalesce(p_allocations, '[]'::jsonb))
  loop
    v_parchi_id := nullif(v_elem->>'parchi_id', '')::uuid;
    v_amount := coalesce((v_elem->>'amount')::numeric, 0);
    if v_parchi_id is null or v_amount <= 0 then
      continue;
    end if;

    insert into erp.parchi_clearances (parchi_id, payment_id, amount, clearance_date)
    values (v_parchi_id, p_payment_id, v_amount, p_clearance_date);

    select * into v_parchi from erp.parchi_instruments where id = v_parchi_id for update;
    if found then
      v_cleared := coalesce(v_parchi.cleared_amount, 0) + v_amount;
      v_open := greatest(0, coalesce(v_parchi.total_amount, 0) - v_cleared);
      update erp.parchi_instruments
      set
        cleared_amount = v_cleared,
        open_amount = v_open,
        status = case
          when v_open <= 0.01 then 'cleared'
          when v_cleared > 0 then 'partial'
          else 'open'
        end
      where id = v_parchi_id;

      v_rows := v_rows || jsonb_build_array(
        jsonb_build_object(
          'id', v_parchi.id,
          'parchi_no', v_parchi.parchi_no,
          'cleared_amount', v_cleared,
          'open_amount', v_open,
          'status', case
            when v_open <= 0.01 then 'cleared'
            when v_cleared > 0 then 'partial'
            else 'open'
          end
        )
      );
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'parchi_rows', v_rows);
end;
$$;


ALTER FUNCTION "erp"."batch_apply_parchi_clearances"("p_payment_id" "uuid", "p_clearance_date" "date", "p_allocations" "jsonb") OWNER TO "postgres";

--
-- Name: bootstrap_single_company("uuid", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."bootstrap_single_company"("p_admin_user_id" "uuid", "p_admin_name" "text" DEFAULT 'System Admin'::"text", "p_admin_email" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_admin_role uuid;
begin
  select id into v_admin_role from erp.roles where code = 'ADMIN' limit 1;
  if v_admin_role is null then
    raise exception 'ADMIN role missing';
  end if;

  insert into erp.user_profiles (user_id, display_name, email, is_active)
  values (p_admin_user_id, p_admin_name, p_admin_email, true)
  on conflict (user_id) do update set display_name = excluded.display_name, email = excluded.email, is_active = true;

  insert into erp.user_role_assignments (user_id, role_id)
  values (p_admin_user_id, v_admin_role)
  on conflict do nothing;
end;
$$;


ALTER FUNCTION "erp"."bootstrap_single_company"("p_admin_user_id" "uuid", "p_admin_name" "text", "p_admin_email" "text") OWNER TO "postgres";

