--
-- Name: coa_account_safe_delete("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."coa_account_safe_delete"("p_account_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_acc erp.coa_accounts%rowtype;
  v_jl_count int;
  v_pm_count int;
begin
  if not erp.can_mutate_masters() then
    raise exception 'Permission denied: masters.write or admin required' using errcode = '42501';
  end if;

  select * into v_acc from erp.coa_accounts where code = p_account_code;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'account not found');
  end if;

  if coalesce(v_acc.is_anchor, false) then
    return jsonb_build_object('ok', false, 'error', 'cannot delete anchor account');
  end if;

  select count(*) into v_jl_count from erp.journal_lines where account_code = p_account_code;
  select count(*) into v_pm_count from erp.posting_account_map where account_code = p_account_code and is_active = true;

  if v_jl_count > 0 or v_pm_count > 0 then
    update erp.coa_accounts set is_active = false where code = p_account_code;
    return jsonb_build_object('ok', true, 'mode', 'deactivated', 'reason',
      case when v_jl_count > 0 then 'has journal lines' else 'in active posting map' end);
  end if;

  update erp.coa_accounts set parent_id = null where parent_id = v_acc.id;
  delete from erp.coa_accounts where code = p_account_code;
  return jsonb_build_object('ok', true, 'mode', 'deleted');
exception
  when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."coa_account_safe_delete"("p_account_code" "text") OWNER TO "postgres";

--
-- Name: consume_party_advance("uuid", "uuid", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."consume_party_advance"("p_payment_id" "uuid", "p_doc_id" "uuid", "p_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_pay erp.payments%rowtype;
  v_open_adv numeric;
  v_ar erp.ar_documents%rowtype;
  v_ap erp.ap_documents%rowtype;
  v_side text;
  v_adv text;
  v_ar_code text;
  v_ap_code text;
  v_je_id uuid;
  v_seq int;
  v_voucher text;
  v_amt numeric;
begin
  perform erp._assert_posting_access();

  v_amt := round(coalesce(p_amount, 0), 3);
  if v_amt <= 0 then
    raise exception 'consume amount must be > 0' using errcode = 'P0001';
  end if;

  select * into v_pay from erp.payments where id = p_payment_id for update;
  if not found then
    raise exception 'payment not found' using errcode = 'P0001';
  end if;
  if v_pay.posting_status <> 'posted' or v_pay.voided_at is not null then
    raise exception 'payment must be posted and not voided' using errcode = 'P0001';
  end if;
  if v_pay.party_id is null then
    raise exception 'advance payment has no party' using errcode = 'P0001';
  end if;
  if v_pay.entry_kind not in ('party_receipt', 'party_payment') then
    raise exception 'advance entry_kind must be party_receipt or party_payment' using errcode = 'P0001';
  end if;

  v_open_adv := round(coalesce(v_pay.advance_amount, 0) - coalesce(v_pay.advance_consumed, 0), 3);
  if v_open_adv <= 0.01 then
    raise exception 'payment % has no open advance to consume', v_pay.payment_no using errcode = 'P0001';
  end if;
  if v_amt > v_open_adv + 0.001 then
    raise exception 'amount % exceeds open advance % on %', v_amt, v_open_adv, v_pay.payment_no
      using errcode = 'P0001';
  end if;

  v_ar_code := erp._resolve_posting_account('payment_receipt', 'ar');
  v_ap_code := erp._resolve_posting_account('payment_payment', 'ap');

  if v_pay.entry_kind = 'party_receipt' then
    v_side := 'customer';
    v_adv := erp._advance_account('customer');
    select * into v_ar from erp.ar_documents where id = p_doc_id for update;
    if not found then raise exception 'AR document not found' using errcode = 'P0001'; end if;
    if v_ar.party_id <> v_pay.party_id then
      raise exception 'AR document party does not match advance party' using errcode = 'P0001';
    end if;
    if v_ar.status not in ('open', 'partially_settled') or coalesce(v_ar.open_amount, 0) <= 0.01 then
      raise exception 'AR document is not open' using errcode = 'P0001';
    end if;
    if v_amt > v_ar.open_amount + 0.001 then
      raise exception 'amount % exceeds AR open_amount %', v_amt, v_ar.open_amount using errcode = 'P0001';
    end if;

    select coalesce(count(*), 0) + 1 into v_seq
    from erp.journal_entries
    where source_doc_type = 'payment' and source_doc_id = v_pay.id and voucher_type = 'ADVANCE_APPLY';
    v_voucher := 'ADV-' || v_pay.payment_no || '-' || v_seq::text;

    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no,
      narration, status, posted_at, posted_by
    ) values (
      v_voucher, 'ADVANCE_APPLY', coalesce(v_pay.payment_date, current_date),
      'payment', v_pay.id, v_pay.payment_no,
      format('Apply customer advance %s to AR', v_pay.payment_no),
      'posted', now(), auth.uid()
    ) returning id into v_je_id;

    perform erp._insert_je_line(v_je_id, 1, v_adv, v_pay.party_id, v_amt, 0, 'Consume customer advance');
    perform erp._insert_je_line(v_je_id, 2, v_ar_code, v_pay.party_id, 0, v_amt, 'Settle receivable from advance');
    perform erp._assert_je_balanced(v_je_id);

    insert into erp.payment_allocations (payment_id, allocation_type, ar_document_id, allocated_amount)
    values (v_pay.id, 'ar', v_ar.id, v_amt);

    update erp.ar_documents
       set open_amount = open_amount - v_amt,
           status = case when open_amount - v_amt <= 0.01 then 'settled' else 'partially_settled' end
     where id = v_ar.id;

  else
    v_side := 'vendor';
    v_adv := erp._advance_account('vendor');
    select * into v_ap from erp.ap_documents where id = p_doc_id for update;
    if not found then raise exception 'AP document not found' using errcode = 'P0001'; end if;
    if v_ap.party_id <> v_pay.party_id then
      raise exception 'AP document party does not match advance party' using errcode = 'P0001';
    end if;
    if v_ap.status not in ('open', 'partially_settled') or coalesce(v_ap.open_amount, 0) <= 0.01 then
      raise exception 'AP document is not open' using errcode = 'P0001';
    end if;
    if v_amt > v_ap.open_amount + 0.001 then
      raise exception 'amount % exceeds AP open_amount %', v_amt, v_ap.open_amount using errcode = 'P0001';
    end if;

    select coalesce(count(*), 0) + 1 into v_seq
    from erp.journal_entries
    where source_doc_type = 'payment' and source_doc_id = v_pay.id and voucher_type = 'ADVANCE_APPLY';
    v_voucher := 'ADV-' || v_pay.payment_no || '-' || v_seq::text;

    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no,
      narration, status, posted_at, posted_by
    ) values (
      v_voucher, 'ADVANCE_APPLY', coalesce(v_pay.payment_date, current_date),
      'payment', v_pay.id, v_pay.payment_no,
      format('Apply vendor advance %s to AP', v_pay.payment_no),
      'posted', now(), auth.uid()
    ) returning id into v_je_id;

    perform erp._insert_je_line(v_je_id, 1, v_ap_code, v_pay.party_id, v_amt, 0, 'Settle payable from advance');
    perform erp._insert_je_line(v_je_id, 2, v_adv, v_pay.party_id, 0, v_amt, 'Consume vendor advance');
    perform erp._assert_je_balanced(v_je_id);

    insert into erp.payment_allocations (payment_id, allocation_type, ap_document_id, allocated_amount)
    values (v_pay.id, 'ap', v_ap.id, v_amt);

    update erp.ap_documents
       set open_amount = open_amount - v_amt,
           status = case when open_amount - v_amt <= 0.01 then 'settled' else 'partially_settled' end
     where id = v_ap.id;
  end if;

  update erp.payments
     set advance_consumed = round(coalesce(advance_consumed, 0) + v_amt, 3),
         is_advance = true
   where id = v_pay.id;

  return jsonb_build_object(
    'ok', true,
    'payment_id', v_pay.id,
    'doc_id', p_doc_id,
    'amount', v_amt,
    'side', v_side,
    'journal_entry_id', v_je_id,
    'voucher_no', v_voucher,
    'advance_open_after', round(v_open_adv - v_amt, 3)
  );
end;
$$;


ALTER FUNCTION "erp"."consume_party_advance"("p_payment_id" "uuid", "p_doc_id" "uuid", "p_amount" numeric) OWNER TO "postgres";

--
-- Name: create_drawing_weekly_wage_sheet("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."create_drawing_weekly_wage_sheet"("p_week_start" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_week_end date;
  v_id uuid;
  v_sheet_no text;
  v_received numeric;
  v_scrap numeric;
  v_base_rate numeric;
  v_totals record;
begin
  perform erp._drawing_wage_post_access();

  if p_week_start is null then
    raise exception 'week_start is required';
  end if;

  v_week_end := p_week_start + 6;

  if exists (select 1 from erp.drawing_weekly_wage_sheets s where s.week_start = p_week_start) then
    raise exception 'A wage sheet already exists for this week';
  end if;

  select w.received_kg, w.scrap_kg
    into v_received, v_scrap
  from erp.fn_drawing_week_wire8_weights(p_week_start, v_week_end) w;

  v_base_rate := erp._drawing_base_rate(p_week_start);
  v_sheet_no := 'DW-' || to_char(p_week_start, 'IYYY') || '-W' || lpad(extract(week from p_week_start)::text, 2, '0');

  insert into erp.drawing_weekly_wage_sheets (
    sheet_no, week_start, week_end, status,
    wire8_received_kg, wire8_scrap_kg, base_rate_pkr,
    net_wire8_kg, base_wage_pkr, premium_wage_pkr, total_wage_pkr
  ) values (
    v_sheet_no, p_week_start, v_week_end, 'draft',
    coalesce(v_received, 0), coalesce(v_scrap, 0), v_base_rate,
    0, 0, 0, 0
  )
  returning id into v_id;

  select * into v_totals from erp._compute_drawing_sheet_totals(v_received, v_scrap, v_base_rate, v_id);

  update erp.drawing_weekly_wage_sheets s
  set
    net_wire8_kg = v_totals.net_kg,
    base_wage_pkr = v_totals.base_wage,
    premium_wage_pkr = v_totals.premium_wage,
    total_wage_pkr = v_totals.total_wage,
    updated_at = now()
  where s.id = v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "erp"."create_drawing_weekly_wage_sheet"("p_week_start" "date") OWNER TO "postgres";

