--
-- Name: deactivate_party("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."deactivate_party"("p_party_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_party erp.parties%rowtype;
  v_cnt bigint;
begin
  select * into v_party from erp.parties where code = trim(p_party_code);
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Party not found');
  end if;

  select count(*) into v_cnt from erp.sales_invoices where party_id = v_party.id;
  if v_cnt > 0 then
    return jsonb_build_object('ok', false, 'error', 'Cannot deactivate party with existing sales invoices.');
  end if;

  select count(*) into v_cnt from erp.purchase_invoices where party_id = v_party.id;
  if v_cnt > 0 then
    return jsonb_build_object('ok', false, 'error', 'Cannot deactivate party with existing purchase invoices.');
  end if;

  select count(*) into v_cnt from erp.payments where party_id = v_party.id;
  if v_cnt > 0 then
    return jsonb_build_object('ok', false, 'error', 'Cannot deactivate party with existing payments.');
  end if;

  select count(*) into v_cnt from erp.sales_orders where party_id = v_party.id;
  if v_cnt > 0 then
    return jsonb_build_object('ok', false, 'error', 'Cannot deactivate party with existing sales orders.');
  end if;

  select count(*) into v_cnt from erp.purchase_orders where party_id = v_party.id;
  if v_cnt > 0 then
    return jsonb_build_object('ok', false, 'error', 'Cannot deactivate party with existing purchase orders.');
  end if;

  begin
    perform erp._reverse_party_opening_scrap(v_party.id);
  exception
    when others then
      return jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  perform erp._reverse_party_opening(v_party.id);

  update erp.parties
  set is_active = false,
      opening_fin_balance = 0,
      opening_metal_balance = 0,
      opening_scrap_kg = 0,
      opening_scrap_ref_rate = 0
  where id = v_party.id;

  return jsonb_build_object(
    'ok', true,
    'party_code', v_party.code,
    'opening_reversed', true
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."deactivate_party"("p_party_code" "text") OWNER TO "postgres";

