-- Name: delete_drawing_weekly_wage_sheet("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."delete_drawing_weekly_wage_sheet"("p_sheet_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  perform erp._drawing_wage_post_access();

  select s.status into v_status
  from erp.drawing_weekly_wage_sheets s
  where s.id = p_sheet_id
  for update;

  if not found then raise exception 'Wage sheet not found'; end if;
  if v_status <> 'draft' then
    raise exception 'Only draft sheets can be deleted';
  end if;

  delete from erp.drawing_weekly_wage_sheets where id = p_sheet_id;
end;
