--
-- Name: delete_production_batch("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."delete_production_batch"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_status text;
  v_item_ids uuid[];
  v_je_ids uuid[];
begin
  perform erp._assert_posting_access();
  select status into v_status from erp.production_batches where id = p_batch_id;
  if not found then
    raise exception 'production batch not found';
  end if;
  if v_status = 'posted' then
    return erp.void_production_batch(p_batch_id, 'Voided via delete_production_batch');
  end if;
  select coalesce(array_agg(distinct item_id), '{}') into v_item_ids
  from erp.inventory_movements where source_doc_type = 'production_batch' and source_doc_id = p_batch_id;
  delete from erp.inventory_movements where source_doc_type = 'production_batch' and source_doc_id = p_batch_id;
  select coalesce(array_agg(id), '{}') into v_je_ids
  from erp.journal_entries where source_doc_type = 'production_batch' and source_doc_id = p_batch_id;
  if coalesce(array_length(v_je_ids, 1), 0) > 0 then
    delete from erp.journal_lines where journal_entry_id = any(v_je_ids);
    delete from erp.journal_entries where id = any(v_je_ids);
  end if;
  delete from erp.production_batches where id = p_batch_id;
  if coalesce(array_length(v_item_ids, 1), 0) > 0 then
    perform erp.rebuild_inventory_balances_for_items(v_item_ids);
  end if;
  return jsonb_build_object('ok', true, 'batch_id', p_batch_id, 'action', 'deleted');
end;
$$;


ALTER FUNCTION "erp"."delete_production_batch"("p_batch_id" "uuid") OWNER TO "postgres";

--
-- Name: delete_purchase_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."delete_purchase_invoice"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_invoices%rowtype;
begin
  perform erp._assert_posting_access();

  select * into v_doc
  from erp.purchase_invoices
  where id = p_doc_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'purchase invoice not found');
  end if;

  if v_doc.posting_status = 'posted' then
    return jsonb_build_object('ok', false, 'error', 'posted purchase invoices cannot be deleted');
  end if;

  perform erp._revert_premium_purchase_scrap_pool(v_doc.id);
  delete from erp.purchase_invoices where id = v_doc.id;

  return jsonb_build_object('ok', true, 'id', v_doc.id);
exception
  when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."delete_purchase_invoice"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: diagnose_sales_invoice_delete("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."diagnose_sales_invoice_delete"("p_invoice_no" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_inv erp.sales_invoices%rowtype;
  v_payments jsonb;
  v_obligations jsonb;
  v_returns jsonb;
  v_triggers jsonb;
begin
  select * into v_inv from erp.sales_invoices where invoice_no = p_invoice_no;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'invoice not found', 'invoice_no', p_invoice_no);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'payment_no', p.payment_no,
    'allocated_amount', pa.allocated_amount
  )), '[]'::jsonb)
  into v_payments
  from erp.ar_documents ad
  join erp.payment_allocations pa on pa.ar_document_id = ad.id
  join erp.payments p on p.id = pa.payment_id
  where ad.source_doc_type = 'sales_invoice' and ad.source_doc_id = v_inv.id;

  if to_regclass('erp.scrap_receivable_obligations') is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'obligation_no', o.obligation_no,
      'expected_kg', o.expected_kg,
      'received_kg', o.received_kg,
      'status', o.status,
      'receipt_count', (select count(*) from erp.scrap_receipts r where r.obligation_id = o.id)
    )), '[]'::jsonb)
    into v_obligations
    from erp.scrap_receivable_obligations o
    where o.sales_invoice_id = v_inv.id or o.sales_invoice_no = v_inv.invoice_no;
  else
    v_obligations := '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'return_no', sr.return_no,
    'posting_status', sr.posting_status
  )), '[]'::jsonb)
  into v_returns
  from erp.sales_returns sr
  where sr.ref_invoice_id = v_inv.id;

  select coalesce(jsonb_agg(jsonb_build_object('trigger', t.tgname)), '[]'::jsonb)
  into v_triggers
  from pg_trigger t
  join pg_class c on c.oid = t.tgrelid
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'erp'
    and c.relname = 'sales_invoices'
    and not t.tgisinternal
    and t.tgname like '%posted%delete%';

  return jsonb_build_object(
    'ok', true,
    'invoice_id', v_inv.id,
    'invoice_no', v_inv.invoice_no,
    'sale_mode', v_inv.sale_mode,
    'posting_status', v_inv.posting_status,
    'payment_allocations', v_payments,
    'has_payment_block', jsonb_array_length(v_payments) > 0,
    'scrap_obligations', v_obligations,
    'linked_returns', v_returns,
    'blocking_triggers', v_triggers,
    'recommended_action', case
      when jsonb_array_length(v_payments) > 0 then 'run: select erp.force_delete_sales_invoice_by_no(' || quote_literal(p_invoice_no) || ');'
      when jsonb_array_length(v_triggers) > 0 then 'run migration 106 (drops posted-delete triggers)'
      else 'run: select erp.hard_delete_sales_invoice(''' || v_inv.id::text || '''::uuid);'
    end
  );
end;
$$;


ALTER FUNCTION "erp"."diagnose_sales_invoice_delete"("p_invoice_no" "text") OWNER TO "postgres";

--
-- Name: fix_pending_rate_items("jsonb", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fix_pending_rate_items"("p_items" "jsonb", "p_remarks" "text" DEFAULT NULL::"text", "p_proof_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_row jsonb;
  v_pri erp.pending_rate_items%rowtype;
  v_fix_id uuid;
  v_party_id uuid;
  v_rate numeric;
  v_amount numeric;
  v_je_id uuid;
  v_ln int;
  v_inv text;
  v_ap text;
  v_ar text;
  v_rev text;
  v_tax text;
  v_tax_amt numeric;
  v_tax_rate numeric;
  v_doc record;
  v_fixed_count int := 0;
  v_item_ids uuid[] := '{}';
begin
  perform erp._assert_posting_access();

  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'At least one pending item is required';
  end if;

  select (p_items->0->>'pending_item_id')::uuid into v_pri.id;
  select * into v_pri from erp.pending_rate_items where id = (p_items->0->>'pending_item_id')::uuid for update;
  if not found then raise exception 'Pending item not found'; end if;
  v_party_id := v_pri.party_id;

  insert into erp.rate_fixes (party_id, fixed_by, remarks, proof_url)
  values (v_party_id, auth.uid(), p_remarks, p_proof_url)
  returning id into v_fix_id;

  for v_row in select * from jsonb_array_elements(p_items)
  loop
    select * into v_pri from erp.pending_rate_items where id = (v_row->>'pending_item_id')::uuid for update;
    if not found then raise exception 'Pending item % not found', v_row->>'pending_item_id'; end if;
    if v_pri.status <> 'open' then raise exception 'Pending item % is not open', v_pri.id; end if;
    if v_pri.party_id is distinct from v_party_id then
      raise exception 'All items must belong to the same party';
    end if;

    v_rate := (v_row->>'unit_rate')::numeric;
    if coalesce(v_rate, 0) <= 0 then raise exception 'unit_rate must be positive'; end if;
    perform erp._assert_period_open(v_pri.original_posting_date);

    v_amount := round(v_pri.qty * v_rate, 3);
    if v_pri.item_id is not null then
      v_item_ids := array_append(v_item_ids, v_pri.item_id);
    end if;

    if v_pri.source_doc_type = 'purchase_invoice' then
      update erp.purchase_invoice_lines
      set rate_status = 'fixed', unit_price = v_rate, line_amount = v_amount,
          rate_fixed_at = now(), rate_fixed_by = auth.uid()
      where id = v_pri.source_line_id;

      update erp.inventory_movements
      set unit_cost = case when v_pri.qty > 0 then round(v_amount / v_pri.qty, 6) else 0 end,
          value_amount = v_amount
      where source_doc_type = 'purchase_invoice'
        and source_doc_id = v_pri.source_doc_id
        and source_line_id = v_pri.source_line_id;

      v_inv := erp._resolve_posting_account('purchase_invoice', 'inventory');
      v_ap := erp._resolve_posting_account('purchase_invoice', 'ap');

      insert into erp.journal_entries (
        voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
      )
      select pi.invoice_no, 'PURCHASE_INVOICE', v_pri.original_posting_date, 'purchase_invoice', pi.id, pi.invoice_no,
        coalesce(nullif(trim(p_remarks), ''), pi.remarks, 'Purchase invoice posted'), 'posted', now(), auth.uid()
      from erp.purchase_invoices pi where pi.id = v_pri.source_doc_id
      returning id into v_je_id;

      v_ln := 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, v_amount, 0, 'Inventory');
      v_ln := 2;
      perform erp._insert_je_line(v_je_id, v_ln, v_ap, v_pri.party_id, 0, v_amount, 'Accounts Payable');

      if exists (
        select 1 from erp.ap_documents ad
        where ad.source_doc_type = 'purchase_invoice' and ad.source_doc_id = v_pri.source_doc_id and ad.party_id = v_pri.party_id
      ) then
        update erp.ap_documents
        set amount = amount + v_amount, open_amount = open_amount + v_amount
        where source_doc_type = 'purchase_invoice' and source_doc_id = v_pri.source_doc_id and party_id = v_pri.party_id;
      else
        insert into erp.ap_documents (party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status)
        select v_pri.party_id, 'purchase_invoice', pi.id, pi.invoice_no, v_pri.original_posting_date,
          coalesce(pi.due_date, v_pri.original_posting_date), v_amount, v_amount, 'open'
        from erp.purchase_invoices pi where pi.id = v_pri.source_doc_id;
      end if;

      perform erp._refresh_doc_financial_status('purchase_invoice', v_pri.source_doc_id);
      perform erp._refresh_doc_header_totals('purchase_invoice', v_pri.source_doc_id);

    elsif v_pri.source_doc_type = 'sales_invoice' then
      update erp.sales_invoice_lines
      set rate_status = 'fixed', unit_price = v_rate, line_amount = v_amount,
          rate_fixed_at = now(), rate_fixed_by = auth.uid()
      where id = v_pri.source_line_id;

      select coalesce(max(l.tax_rate), 0) into v_tax_rate
      from erp.sales_invoice_lines l where l.sales_invoice_id = v_pri.source_doc_id;

      v_tax_amt := round(v_amount * coalesce(v_tax_rate, 0) / 100, 3);

      v_ar := erp._resolve_posting_account('sales_invoice', 'ar');
      v_rev := erp._resolve_posting_account('sales_invoice', 'sales_revenue');
      v_tax := erp._resolve_posting_account('sales_invoice', 'output_tax');

      insert into erp.journal_entries (
        voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
      )
      select si.invoice_no, 'SALES_INVOICE', v_pri.original_posting_date, 'sales_invoice', si.id, si.invoice_no,
        coalesce(nullif(trim(p_remarks), ''), si.remarks, 'Sales invoice posted'), 'posted', now(), auth.uid()
      from erp.sales_invoices si where si.id = v_pri.source_doc_id
      returning id into v_je_id;

      v_ln := 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ar, v_pri.party_id, v_amount + v_tax_amt, 0, 'Accounts Receivable');
      if v_amount > 0 then
        v_ln := 2;
        perform erp._insert_je_line(v_je_id, v_ln, v_rev, null, 0, v_amount, 'Sales Revenue');
      end if;
      if v_tax_amt > 0 then
        v_ln := v_ln + 1;
        perform erp._insert_je_line(v_je_id, v_ln, v_tax, null, 0, v_tax_amt, 'Output Tax');
      end if;

      if exists (
        select 1 from erp.ar_documents ad
        where ad.source_doc_type = 'sales_invoice' and ad.source_doc_id = v_pri.source_doc_id and ad.party_id = v_pri.party_id
      ) then
        update erp.ar_documents
        set amount = amount + v_amount + v_tax_amt, open_amount = open_amount + v_amount + v_tax_amt
        where source_doc_type = 'sales_invoice' and source_doc_id = v_pri.source_doc_id and party_id = v_pri.party_id;
      else
        insert into erp.ar_documents (party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status)
        select v_pri.party_id, 'sales_invoice', si.id, si.invoice_no, v_pri.original_posting_date,
          si.due_date, v_amount + v_tax_amt, v_amount + v_tax_amt, 'open'
        from erp.sales_invoices si where si.id = v_pri.source_doc_id;
      end if;

      perform erp._refresh_doc_financial_status('sales_invoice', v_pri.source_doc_id);
      perform erp._refresh_doc_header_totals('sales_invoice', v_pri.source_doc_id);

    elsif v_pri.source_doc_type = 'sales_return' then
      update erp.sales_return_lines
      set rate_status = 'fixed', unit_price = v_rate, line_amount = v_amount,
          rate_fixed_at = now(), rate_fixed_by = auth.uid()
      where id = v_pri.source_line_id;

      update erp.inventory_movements
      set value_amount = v_amount
      where source_doc_type = 'sales_return'
        and source_doc_id = v_pri.source_doc_id
        and source_line_id = v_pri.source_line_id;

      select sr.tax_amount, sr.subtotal_amount into v_doc from erp.sales_returns sr where sr.id = v_pri.source_doc_id;
      v_tax_amt := case when coalesce(v_doc.subtotal_amount, 0) > 0
        then round(coalesce(v_doc.tax_amount, 0) * v_amount / v_doc.subtotal_amount, 3) else 0 end;

      v_ar := erp._resolve_posting_account('sales_return', 'ar');
      v_rev := erp._resolve_posting_account('sales_return', 'sales_revenue');
      v_tax := erp._resolve_posting_account('sales_return', 'output_tax');

      insert into erp.journal_entries (
        voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
      )
      select sr.return_no, 'SALES_RETURN', v_pri.original_posting_date, 'sales_return', sr.id, sr.return_no,
        coalesce(nullif(trim(p_remarks), ''), sr.remarks, 'Sales return posted'), 'posted', now(), auth.uid()
      from erp.sales_returns sr where sr.id = v_pri.source_doc_id
      returning id into v_je_id;

      v_ln := 0;
      if v_amount > 0 then
        v_ln := v_ln + 1;
        perform erp._insert_je_line(v_je_id, v_ln, v_rev, null, v_amount, 0, 'Sales return');
      end if;
      if v_tax_amt > 0 then
        v_ln := v_ln + 1;
        perform erp._insert_je_line(v_je_id, v_ln, v_tax, null, v_tax_amt, 0, 'Output tax reversal');
      end if;
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ar, v_pri.party_id, 0, v_amount + v_tax_amt, 'Reduce receivable');
      perform erp._reduce_ar_open(v_pri.party_id, v_amount + v_tax_amt);
      perform erp._refresh_doc_financial_status('sales_return', v_pri.source_doc_id);
      perform erp._refresh_doc_header_totals('sales_return', v_pri.source_doc_id);

    elsif v_pri.source_doc_type = 'purchase_return' then
      update erp.purchase_return_lines
      set rate_status = 'fixed', unit_price = v_rate, line_amount = v_amount,
          rate_fixed_at = now(), rate_fixed_by = auth.uid()
      where id = v_pri.source_line_id;

      update erp.inventory_movements
      set value_amount = v_amount
      where source_doc_type = 'purchase_return'
        and source_doc_id = v_pri.source_doc_id
        and source_line_id = v_pri.source_line_id;

      v_ap := erp._resolve_posting_account('purchase_return', 'ap');
      v_inv := erp._resolve_posting_account('purchase_return', 'inventory');

      insert into erp.journal_entries (
        voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
      )
      select pr.return_no, 'PURCHASE_RETURN', v_pri.original_posting_date, 'purchase_return', pr.id, pr.return_no,
        coalesce(nullif(trim(p_remarks), ''), pr.remarks, 'Purchase return posted'), 'posted', now(), auth.uid()
      from erp.purchase_returns pr where pr.id = v_pri.source_doc_id
      returning id into v_je_id;

      v_ln := 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ap, v_pri.party_id, v_amount, 0, 'Reduce payable');
      v_ln := 2;
      perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, 0, v_amount, 'Inventory out');
      perform erp._reduce_ap_open(v_pri.party_id, v_amount);
      perform erp._refresh_doc_financial_status('purchase_return', v_pri.source_doc_id);
      perform erp._refresh_doc_header_totals('purchase_return', v_pri.source_doc_id);

    elsif v_pri.source_doc_type = 'scrap_trade' then
      perform erp._apply_scrap_trade_rate_fix(
        v_pri.source_doc_id,
        v_pri.qty,
        v_rate,
        v_amount,
        v_pri.original_posting_date,
        p_remarks
      );
    else
      raise exception 'Unsupported source_doc_type: %', v_pri.source_doc_type;
    end if;

    update erp.pending_rate_items
    set status = 'fixed', fixed_unit_rate = v_rate, fixed_amount = v_amount,
        fixed_at = now(), fixed_by = auth.uid(), rate_fix_id = v_fix_id
    where id = v_pri.id;

    insert into erp.rate_fix_lines (rate_fix_id, pending_rate_item_id, unit_rate, fixed_amount)
    values (v_fix_id, v_pri.id, v_rate, v_amount);

    v_fixed_count := v_fixed_count + 1;
  end loop;

  perform erp._rebuild_after_document_post(v_item_ids);

  return jsonb_build_object('ok', true, 'rate_fix_id', v_fix_id, 'fixed_count', v_fixed_count);
end;
$$;


ALTER FUNCTION "erp"."fix_pending_rate_items"("p_items" "jsonb", "p_remarks" "text", "p_proof_url" "text") OWNER TO "postgres";

--
-- Name: fn_account_ledger("text", "date", "date", integer, integer); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_account_ledger"("p_account_code" "text", "p_from" "date" DEFAULT '1900-01-01'::"date", "p_to" "date" DEFAULT CURRENT_DATE, "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0) RETURNS TABLE("posting_date" "date", "voucher_no" "text", "voucher_type" "text", "source_doc_type" "text", "source_doc_id" "uuid", "source_doc_no" "text", "ref_no" "text", "account_code" "text", "account_name" "text", "party_code" "text", "party_name" "text", "line_description" "text", "transaction_description" "text", "narration" "text", "particulars" "text", "size_spec" "text", "weight_qty" numeric, "unit_rate" numeric, "detail_seq" integer, "debit_amount" numeric, "credit_amount" numeric, "running_balance" numeric, "posted_at" timestamp with time zone, "posted_by" "uuid", "posted_by_name" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with opening as (
    select coalesce(sum(jl.debit_amount - jl.credit_amount), 0)::numeric as bal
    from erp.journal_lines jl
    join erp.journal_entries je on je.id = jl.journal_entry_id
    where jl.account_code = p_account_code
      and je.posting_date < p_from
      and coalesce(je.voucher_no, '') not like 'VOID-%'
      and not erp._ledger_is_voided(je.source_doc_type, je.source_doc_id, je.voucher_no)
  ),
  journal_rows as (
    select
      je.posting_date,
      je.voucher_no::text,
      je.voucher_type::text,
      je.source_doc_type::text,
      je.source_doc_id,
      je.source_doc_no::text,
      case
        when je.source_doc_type = 'payment' then
          coalesce('p.' || nullif(trim(pay.page_no), ''), 'p.?')
        else
          coalesce(nullif(trim(je.source_doc_no), ''), nullif(trim(je.voucher_no), ''))
      end::text as ref_no,
      jl.account_code::text,
      jl.account_name::text,
      p.code::text as party_code,
      p.name::text as party_name,
      jl.line_description::text,
      erp._ledger_transaction_description(
        je.source_doc_type, je.voucher_type, jl.line_description, pay.payment_type
      )::text as transaction_description,
      je.narration::text,
      jl.debit_amount,
      jl.credit_amount,
      (jl.debit_amount - jl.credit_amount) as delta,
      je.id as je_id,
      jl.line_no as je_line_no,
      je.posted_at,
      je.posted_by,
      erp._audit_actor_name(je.posted_by) as posted_by_name
    from erp.journal_lines jl
    join erp.journal_entries je on je.id = jl.journal_entry_id
    left join erp.parties p on p.id = jl.party_id
    left join erp.payments pay on je.source_doc_type = 'payment' and pay.id = je.source_doc_id
    where jl.account_code = p_account_code
      and je.posting_date between p_from and p_to
      and coalesce(je.voucher_no, '') not like 'VOID-%'
      and not erp._ledger_is_voided(je.source_doc_type, je.source_doc_id, je.voucher_no)
  ),
  expanded_raw as (
    select
      jr.*,
      coalesce(d.detail_seq, 1) as detail_seq,
      coalesce(d.particulars, jr.line_description, jr.narration) as particulars,
      d.size_spec,
      d.weight_qty,
      d.unit_rate,
      coalesce(
        d.line_amount,
        case when d.weight_qty is not null and d.unit_rate is not null then round(d.weight_qty * d.unit_rate, 3) else null end
      ) as raw_line_amount,
      erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type) as should_expand
    from journal_rows jr
    left join lateral (
      select ld.*
      from erp._ledger_line_details(
        case when erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type) then jr.source_doc_type end,
        case when erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type) then jr.source_doc_id end
      ) ld
      where erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type)
    ) d on true
  ),
  expanded as (
    select
      r.*,
      case
        when r.should_expand and coalesce(r.raw_line_amount, 0) > 0 then r.raw_line_amount
        when not r.should_expand and r.detail_seq = 1 then
          case when r.debit_amount > 0 then r.debit_amount when r.credit_amount > 0 then r.credit_amount else 0 end
        else 0
      end as alloc_amount
    from expanded_raw r
  ),
  expanded_final as (
    select
      e.*,
      case when e.debit_amount > 0 then e.alloc_amount else 0 end as display_debit,
      case when e.credit_amount > 0 then e.alloc_amount else 0 end as display_credit,
      case when e.debit_amount > 0 then e.alloc_amount when e.credit_amount > 0 then -e.alloc_amount else 0 end as display_delta,
      row_number() over (
        order by coalesce(e.posted_at, e.posting_date::timestamptz), e.je_id, e.je_line_no, e.detail_seq
      ) as rn
    from expanded e
  ),
  opening_row as (
    select
      p_from as posting_date,
      'OPENING'::text as voucher_no,
      'OPENING'::text as voucher_type,
      'opening'::text as source_doc_type,
      null::uuid as source_doc_id,
      null::text as source_doc_no,
      'B/F'::text as ref_no,
      p_account_code::text as account_code,
      (select coalesce(name, p_account_code) from erp.coa_accounts where code = p_account_code)::text as account_name,
      null::text as party_code,
      null::text as party_name,
      'Balance brought forward'::text as line_description,
      'Balance brought forward'::text as transaction_description,
      null::text as narration,
      'Balance brought forward'::text as particulars,
      null::text as size_spec,
      null::numeric as weight_qty,
      null::numeric as unit_rate,
      1 as detail_seq,
      0::numeric as display_debit,
      0::numeric as display_credit,
      (select bal from opening) as display_delta,
      0::bigint as rn,
      null::timestamptz as posted_at,
      null::uuid as posted_by,
      null::text as posted_by_name
  ),
  all_rows as (
    select * from opening_row
    union all
    select
      posting_date, voucher_no, voucher_type, source_doc_type, source_doc_id, source_doc_no, ref_no,
      account_code, account_name, party_code, party_name, line_description, transaction_description,
      narration, particulars, size_spec, weight_qty, unit_rate, detail_seq,
      display_debit, display_credit, display_delta, rn,
      posted_at, posted_by, posted_by_name
    from expanded_final
  )
  select
    numbered.posting_date, numbered.voucher_no, numbered.voucher_type, numbered.source_doc_type, numbered.source_doc_id, numbered.source_doc_no, numbered.ref_no,
    numbered.account_code, numbered.account_name, numbered.party_code, numbered.party_name, numbered.line_description, numbered.transaction_description,
    numbered.narration, numbered.particulars, numbered.size_spec, numbered.weight_qty, numbered.unit_rate, numbered.detail_seq,
    numbered.debit_amount, numbered.credit_amount, numbered.running_balance,
    numbered.posted_at, numbered.posted_by, numbered.posted_by_name
  from (
    select
      ar.posting_date, ar.voucher_no, ar.voucher_type, ar.source_doc_type, ar.source_doc_id, ar.source_doc_no, ar.ref_no,
      ar.account_code, ar.account_name, ar.party_code, ar.party_name, ar.line_description, ar.transaction_description,
      ar.narration, ar.particulars, ar.size_spec, ar.weight_qty, ar.unit_rate, ar.detail_seq,
      ar.display_debit as debit_amount, ar.display_credit as credit_amount,
      sum(ar.display_delta) over (order by ar.rn) as running_balance,
      ar.rn,
      ar.posted_at, ar.posted_by, ar.posted_by_name
    from all_rows ar
  ) numbered
  order by numbered.rn
  limit p_limit
  offset greatest(coalesce(p_offset, 0), 0);
$$;


ALTER FUNCTION "erp"."fn_account_ledger"("p_account_code" "text", "p_from" "date", "p_to" "date", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";

--
-- Name: fn_ap_aging("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_ap_aging"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("party_code" "text", "party_name" "text", "doc_no" "text", "doc_date" "date", "due_date" "date", "open_amount" numeric, "days_overdue" integer, "aging_bucket" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    p.code::text  as party_code,
    p.name::text  as party_name,
    coalesce(ad.source_doc_id::text, '')::text as doc_no,
    ad.doc_date,
    ad.due_date,
    ad.open_amount,
    (p_as_of - coalesce(ad.due_date, ad.doc_date))::int as days_overdue,
    case
      when (p_as_of - coalesce(ad.due_date, ad.doc_date)) <= 30  then '0_30'
      when (p_as_of - coalesce(ad.due_date, ad.doc_date)) <= 60  then '31_60'
      when (p_as_of - coalesce(ad.due_date, ad.doc_date)) <= 90  then '61_90'
      when (p_as_of - coalesce(ad.due_date, ad.doc_date)) <= 180 then '91_180'
      else '181_plus'
    end::text as aging_bucket
  from erp.ap_documents ad
  join erp.parties p on p.id = ad.party_id
  where ad.status in ('open','partially_settled')
    and coalesce(ad.open_amount, 0) > 0
    and ad.doc_date <= p_as_of;
$$;


ALTER FUNCTION "erp"."fn_ap_aging"("p_as_of" "date") OWNER TO "postgres";

--
-- Name: fn_ar_aging("date"); Type: FUNCTION; Schema: erp; Owner: postgres
