--
-- Name: fn_audit_chain("text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_audit_chain"("p_source_doc_type" "text", "p_source_doc_id" "uuid") RETURNS TABLE("event_id" "uuid", "event_at" timestamp with time zone, "action" "text", "actor_user_id" "uuid", "actor_display_name" "text", "summary" "text", "entity_type" "text", "before_data" "jsonb", "after_data" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if not (erp.has_role('ADMIN') or erp.has_role('ACCOUNTANT')) then
    raise exception 'insufficient privileges for audit chain';
  end if;

  if p_source_doc_type is null or p_source_doc_id is null then
    return;
  end if;

  return query
  select
    ae.id,
    ae.event_at,
    ae.action,
    ae.actor_user_id,
    erp._audit_actor_name(ae.actor_user_id),
    ae.summary,
    ae.entity_type,
    ae.before_data,
    ae.after_data
  from erp.audit_events ae
  where (
      ae.source_doc_type = p_source_doc_type and ae.source_doc_id = p_source_doc_id
    )
    or (
      ae.entity_type = p_source_doc_type and ae.entity_id = p_source_doc_id::text
    )
  order by ae.event_at asc, ae.id asc;
end;
$$;


ALTER FUNCTION "erp"."fn_audit_chain"("p_source_doc_type" "text", "p_source_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: fn_audit_chain_bulk("jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_audit_chain_bulk"("p_docs" "jsonb") RETURNS TABLE("source_doc_type" "text", "source_doc_id" "uuid", "chain" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc jsonb;
  v_type text;
  v_id uuid;
begin
  if not (erp.has_role('ADMIN') or erp.has_role('ACCOUNTANT')) then
    raise exception 'insufficient privileges for audit chain';
  end if;

  for v_doc in select * from jsonb_array_elements(coalesce(p_docs, '[]'::jsonb))
  loop
    v_type := nullif(trim(v_doc->>'source_doc_type'), '');
    v_id := nullif(trim(v_doc->>'source_doc_id'), '')::uuid;
    if v_type is null or v_id is null then
      continue;
    end if;

    source_doc_type := v_type;
    source_doc_id := v_id;
    chain := coalesce((
      select jsonb_agg(row_to_json(t))
      from erp.fn_audit_chain(v_type, v_id) t
    ), '[]'::jsonb);
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "erp"."fn_audit_chain_bulk"("p_docs" "jsonb") OWNER TO "postgres";

--
-- Name: fn_balance_sheet("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_balance_sheet"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("account_code" "text", "account_name" "text", "account_type" "text", "report_group" "text", "closing_balance" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with jl_agg as (
    select
      jl.account_code,
      max(jl.account_name) as line_name,
      coalesce(sum(jl.debit_amount), 0) as total_debit,
      coalesce(sum(jl.credit_amount), 0) as total_credit
    from erp.journal_lines jl
    join erp.journal_entries je on je.id = jl.journal_entry_id
    where je.posting_date <= p_as_of
      and coalesce(je.voucher_no, '') not like 'VOID-%'
    group by jl.account_code
  ),
  classified as (
    select
      a.account_code::text as account_code,
      erp._display_account_name(a.account_code, ca.name, a.line_name)::text as account_name,
      erp._infer_account_type(a.account_code, ca.account_type)::text as account_type,
      coalesce(ca.report_group, 'other')::text as report_group,
      case erp._infer_account_type(a.account_code, ca.account_type)
        when 'asset' then (a.total_debit - a.total_credit)
        when 'liability' then (a.total_credit - a.total_debit)
        when 'equity' then (a.total_credit - a.total_debit)
        else 0
      end::numeric as closing_balance
    from jl_agg a
    left join erp.coa_accounts ca on ca.code = a.account_code
  ),
  ytd_pl as (
    select coalesce(sum(case
      when account_type = 'income'  then amount
      when account_type = 'expense' then -amount
      else 0
    end), 0)::numeric as net_profit
    from erp.fn_profit_loss(date_trunc('year', p_as_of)::date, p_as_of)
  )
  select account_code, account_name, account_type, report_group, closing_balance
  from classified
  where account_type in ('asset', 'liability', 'equity')
    and closing_balance <> 0
  union all
  select
    '32002'::text,
    'Current Year Profit / (Loss)'::text,
    'equity'::text,
    'equity'::text,
    net_profit
  from ytd_pl
  where net_profit <> 0
  order by 3, 1;
$$;


ALTER FUNCTION "erp"."fn_balance_sheet"("p_as_of" "date") OWNER TO "postgres";

--
-- Name: fn_check_sales_invoice_stock("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_check_sales_invoice_stock"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_line record;
  v_on_hand numeric;
  v_failures jsonb := '[]'::jsonb;
begin
  for v_line in
    select
      l.item_id,
      l.warehouse_id,
      max(i.code) as item_code,
      max(w.code) as warehouse_code,
      sum(coalesce(l.net_weight, l.qty, 0)) as required_qty
    from erp.sales_invoice_lines l
    join erp.items i on i.id = l.item_id
    join erp.warehouses w on w.id = l.warehouse_id
    where l.sales_invoice_id = p_invoice_id
      and l.item_id is not null
      and coalesce(l.net_weight, l.qty, 0) > 0
      and not coalesce(w.allow_negative_stock, false)
    group by l.item_id, l.warehouse_id
  loop
    v_on_hand := erp._inventory_on_hand(v_line.item_id, v_line.warehouse_id);
    if v_on_hand + 0.001 < v_line.required_qty then
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'item_code', v_line.item_code,
        'warehouse_code', v_line.warehouse_code,
        'requested', v_line.required_qty,
        'on_hand', greatest(v_on_hand, 0)
      ));
    end if;
  end loop;
  return jsonb_build_object(
    'ok', jsonb_array_length(v_failures) = 0,
    'failures', v_failures
  );
end;
$$;


ALTER FUNCTION "erp"."fn_check_sales_invoice_stock"("p_invoice_id" "uuid") OWNER TO "postgres";

--
-- Name: fn_cutover_health(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_cutover_health"() RETURNS TABLE("metric" "text", "value" numeric, "status" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with x as (
    select
      (select count(*)::numeric from erp.fn_reconciliation_checks() where status = 'FAIL') as recon_fail,
      (select count(*)::numeric from erp.sales_invoices where posting_status = 'draft') as draft_si,
      (select count(*)::numeric from erp.purchase_invoices where posting_status = 'draft') as draft_pi
  )
  select *
  from (
    select 'reconciliation_fail_count'::text, recon_fail, case when recon_fail = 0 then 'PASS' else 'FAIL' end::text from x
    union all
    select 'draft_sales_invoices', draft_si, case when draft_si = 0 then 'PASS' else 'WARN' end from x
    union all
    select 'draft_purchase_invoices', draft_pi, case when draft_pi = 0 then 'PASS' else 'WARN' end from x
  ) q(metric, value, status)
$$;


ALTER FUNCTION "erp"."fn_cutover_health"() OWNER TO "postgres";

--
-- Name: fn_daily_production("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_daily_production"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("batch_date" "date", "process_type" "text", "batch_no" "text", "total_input_kg" numeric, "total_output_kg" numeric, "total_scrap_kg" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    pb.batch_date,
    pb.process_type,
    pb.batch_no,
    coalesce(sum(case when pbl.line_type = 'issue' then pbl.net_weight else 0 end), 0),
    coalesce(sum(case when pbl.line_type = 'receipt' then pbl.net_weight else 0 end), 0),
    coalesce(
      sum(
        case
          when pbl.line_type = 'scrap' then coalesce(pbl.scrap_weight, pbl.net_weight)
          else 0
        end
      ),
      0
    )
  from erp.production_batches pb
  left join erp.production_batch_lines pbl on pbl.production_batch_id = pb.id
  where pb.status = 'posted'
    and (p_from is null or pb.batch_date >= p_from)
    and (p_to is null or pb.batch_date <= p_to)
  group by pb.batch_date, pb.process_type, pb.batch_no
  order by pb.batch_date desc, pb.batch_no desc
$$;


ALTER FUNCTION "erp"."fn_daily_production"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_daily_production_detail("date", "date", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_daily_production_detail"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_process_type" "text" DEFAULT NULL::"text") RETURNS TABLE("batch_date" "date", "batch_no" "text", "process_type" "text", "machine_code" "text", "machine_name" "text", "item_code" "text", "item_name" "text", "line_type" "text", "line_input_kg" numeric, "batch_input_kg" numeric, "gross_weight" numeric, "tare_weight" numeric, "net_weight" numeric, "unit_count" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    pb.batch_date,
    pb.batch_no,
    pb.process_type,
    m.machine_code,
    m.name,
    i.code,
    i.name,
    pbl.line_type,
    0::numeric,
    coalesce(pb.input_kg, 0),
    pbl.gross_weight,
    pbl.tare_weight,
    pbl.net_weight,
    coalesce(pbl.unit_count, 0)
  from erp.production_batches pb
  join erp.production_batch_lines pbl on pbl.production_batch_id = pb.id
  join erp.items i on i.id = pbl.item_id
  left join erp.production_machines m on m.id = coalesce(pbl.machine_id, pb.machine_id)
  where pb.status = 'posted'
    and pbl.line_type = 'receipt'
    and (p_from is null or pb.batch_date >= p_from)
    and (p_to is null or pb.batch_date <= p_to)
    and (
      p_process_type is null
      or coalesce(m.department, pb.process_type) = p_process_type
    )
  order by pb.batch_date desc, pb.batch_no, pbl.line_no;
$$;


ALTER FUNCTION "erp"."fn_daily_production_detail"("p_from" "date", "p_to" "date", "p_process_type" "text") OWNER TO "postgres";

--
-- Name: fn_dashboard_kpis("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_dashboard_kpis"("p_from" "date" DEFAULT (CURRENT_DATE - 6), "p_to" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_today date := current_date;
  v_month_start date := date_trunc('month', current_date)::date;
  v_result jsonb;
begin
  select jsonb_build_object(
    'open_purchase_orders', (
      select count(*)::int from erp.purchase_orders po
      where po.status in ('open', 'partial')
    ),
    'pending_sales_invoices', (
      select count(*)::int from erp.sales_invoices si
      where coalesce(si.posting_status, '') <> 'posted'
    ),
    'parchis_due_today', (
      select count(*)::int from erp.parchi_instruments p
      where p.due_date = v_today and coalesce(p.open_amount, 0) > 0 and coalesce(p.status, '') <> 'void'
    ),
    'month_revenue', coalesce((
      select sum(pl.amount)
      from erp.fn_profit_loss(v_month_start, v_today) pl
      where pl.account_type = 'income'
    ), 0),
    'production_by_day', coalesce((
      select jsonb_agg(jsonb_build_object(
        'name', to_char(d.batch_date, 'Dy'),
        'total', round(d.total_kg)::int
      ) order by d.batch_date)
      from (
        select pb.batch_date::date as batch_date,
               sum(coalesce(
                 (select sum(case when pbl.line_type = 'receipt' then pbl.net_weight else 0 end)
                  from erp.production_batch_lines pbl where pbl.production_batch_id = pb.id),
               0)) as total_kg
        from erp.production_batches pb
        where pb.status = 'posted'
          and pb.batch_date between p_from and p_to
        group by pb.batch_date::date
      ) d
      where d.total_kg > 0
    ), '[]'::jsonb),
    'parchis_due_today_rows', coalesce((
      select jsonb_agg(row_to_json(x))
      from (
        select p.parchi_no, p.due_date, p.open_amount, p.parchi_type, p.status,
               jsonb_build_object('code', pt.code, 'name', pt.name) as parties
        from erp.parchi_instruments p
        left join erp.parties pt on pt.id = p.party_id
        where p.due_date = v_today
          and coalesce(p.open_amount, 0) > 0
          and coalesce(p.status, '') <> 'void'
        order by p.open_amount desc
        limit 20
      ) x
    ), '[]'::jsonb),
    'top_parties', coalesce((
      select jsonb_agg(jsonb_build_object(
        'party_code', b.party_code,
        'party_name', b.party_name,
        'party_type', b.party_type,
        'fin_balance_pkr', b.fin_balance_pkr,
        'metal_balance_kg', b.metal_balance_kg
      ))
      from (
        select * from erp.fn_party_balance_snapshot(v_today) snap
        where abs(snap.fin_balance_pkr) > 0.5 or abs(snap.metal_balance_kg) > 0.001
        order by abs(snap.fin_balance_pkr) desc
        limit 5
      ) b
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "erp"."fn_dashboard_kpis"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_deactivate_item("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_deactivate_item"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item erp.items%rowtype;
  v_on_hand numeric := 0;
  v_bal record;
  v_written_off numeric := 0;
begin
  if p_code is null or trim(p_code) = '' then
    return jsonb_build_object('ok', false, 'error', 'Item code is required');
  end if;

  select * into v_item
  from erp.items
  where code = trim(p_code)
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', format('Item not found: %s', p_code));
  end if;

  if coalesce(v_item.is_active, true) = false then
    return jsonb_build_object('ok', true, 'code', v_item.code, 'already_inactive', true);
  end if;

  perform erp.rebuild_inventory_balances_for_items(array[v_item.id]);

  select coalesce(sum(ib.on_hand_qty), 0)
  into v_on_hand
  from erp.inventory_balances ib
  where ib.item_id = v_item.id;

  if v_on_hand > 0.001 then
    for v_bal in
      select ib.warehouse_id, ib.on_hand_qty, coalesce(ib.on_hand_units, 0) as on_hand_units
      from erp.inventory_balances ib
      where ib.item_id = v_item.id
        and coalesce(ib.on_hand_qty, 0) > 0.001
    loop
      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id,
        qty_in, qty_out, units_in, units_out, unit_cost, value_amount,
        source_doc_type, source_doc_id, reference_no
      ) values (
        current_date, 'adjustment_out', v_item.id, v_bal.warehouse_id,
        0, v_bal.on_hand_qty, 0, v_bal.on_hand_units,
        coalesce(v_item.standard_cost, 0),
        round(v_bal.on_hand_qty * coalesce(v_item.standard_cost, 0), 3),
        'item_deactivate', v_item.id, 'DEACTIVATE-' || v_item.code
      );
      v_written_off := v_written_off + v_bal.on_hand_qty;
    end loop;

    perform erp.rebuild_inventory_balances_for_items(array[v_item.id]);
  end if;

  update erp.items
  set is_active = false
  where id = v_item.id;

  delete from erp.inventory_balances
  where item_id = v_item.id
    and coalesce(on_hand_qty, 0) <= 0.001
    and coalesce(on_hand_units, 0) <= 0.001;

  return jsonb_build_object(
    'ok', true,
    'code', v_item.code,
    'written_off_qty', v_written_off
  );
end;
$$;


ALTER FUNCTION "erp"."fn_deactivate_item"("p_code" "text") OWNER TO "postgres";

--
-- Name: fn_drawing_week_wire8_weights("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_drawing_week_wire8_weights"("p_week_start" "date", "p_week_end" "date") RETURNS TABLE("received_kg" numeric, "scrap_kg" numeric, "issued_kg" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with wire8_purchase_lines as (
    select coalesce(sum(coalesce(l.net_weight, l.qty, 0)), 0)::numeric as kg
    from erp.purchase_invoice_lines l
    join erp.purchase_invoices pi on pi.id = l.purchase_invoice_id
    where pi.posting_status = 'posted'
      and pi.invoice_date between p_week_start and p_week_end
      and erp._is_wire8_item(l.item_id)
  ),
  wire8_purchase_mov as (
    select coalesce(sum(coalesce(im.qty_in, 0)), 0)::numeric as kg
    from erp.inventory_movements im
    where im.movement_type = 'purchase_in'
      and im.source_doc_type = 'purchase_invoice'
      and im.posting_date between p_week_start and p_week_end
      and erp._is_wire8_item(im.item_id)
      and exists (
        select 1
        from erp.purchase_invoices pi
        where pi.id = im.source_doc_id
          and pi.posting_status = 'posted'
      )
  ),
  drawing_scrap_dispatch as (
    select coalesce(sum(coalesce(fsl.net_weight, 0)), 0)::numeric as kg
    from erp.factory_scrap_dispatch_lines fsl
    join erp.factory_scrap_dispatches fs on fs.id = fsl.dispatch_id
    where fs.status = 'posted'
      and fs.dispatch_date between p_week_start and p_week_end
      and fsl.department = 'drawing'
  ),
  enamel_wire_issue as (
    select coalesce(sum(im.qty_out), 0)::numeric as kg
    from erp.inventory_movements im
    join erp.production_batches pb on pb.id = im.source_doc_id
      and im.source_doc_type = 'production_batch'
    where pb.process_type = 'enamel'
      and pb.status = 'posted'
      and pb.batch_date between p_week_start and p_week_end
      and im.movement_type = 'production_issue'
      and erp._is_wire8_item(im.item_id)
  )
  select
    greatest(
      (select kg from wire8_purchase_lines),
      (select kg from wire8_purchase_mov)
    ),
    (select kg from drawing_scrap_dispatch),
    (select kg from enamel_wire_issue);
$$;


ALTER FUNCTION "erp"."fn_drawing_week_wire8_weights"("p_week_start" "date", "p_week_end" "date") OWNER TO "postgres";

--
-- Name: fn_erp_assistant_allowed_tools(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_erp_assistant_allowed_tools"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_tools text[] := array[]::text[];
begin
  if auth.uid() is null then
    return '[]'::jsonb;
  end if;

  if erp.has_role('ADMIN')
     or erp.has_permission('ledger.read')
     or erp.has_permission('transactions.read')
     or erp.has_role('ACCOUNTANT') then
    v_tools := v_tools || array[
      'get_party_ledger', 'get_party_metal_ledger', 'get_party_balance',
      'get_ar_aging', 'get_ap_aging', 'get_pending_rate_register',
      'get_sales_invoice', 'get_purchase_invoice', 'get_stock_valuation',
      'get_party_context', 'get_document_context', 'search_documents',
      'search_parties', 'get_recent_sales_invoices', 'get_sales_summary',
      'get_posting_health', 'get_reconciliation_checks',
      'get_sales_invoice_deploy_check', 'get_purchase_invoice_deploy_check'
    ];
  end if;

  if erp.has_role('ADMIN') or erp.has_permission('reports.financial.read') then
    v_tools := v_tools || array[
      'get_trial_balance', 'get_profit_loss', 'get_balance_sheet', 'get_unit_economics'
    ];
  end if;

  if erp.has_role('ADMIN') or erp.has_permission('reports.operational.read') then
    v_tools := v_tools || array['get_daily_production', 'get_scrap_wastage'];
  end if;

  if erp.has_role('ADMIN') then
    v_tools := v_tools || array['get_transaction_history'];
  end if;

  return to_jsonb(v_tools);
end;
$$;


ALTER FUNCTION "erp"."fn_erp_assistant_allowed_tools"() OWNER TO "postgres";

--
-- Name: fn_erp_assistant_context("text", "jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_erp_assistant_context"("p_topic" "text", "p_params" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_party_input text := nullif(trim(p_params->>'party_code'), '');
  v_party_code text;
  v_doc_no text := nullif(trim(p_params->>'doc_no'), '');
  v_doc_type text := nullif(trim(p_params->>'doc_type'), '');
  v_party_id uuid;
  v_result jsonb := '{}'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'Unauthorized';
  end if;
  if not erp.has_role('ADMIN')
     and not erp.has_permission('ledger.read')
     and not erp.has_permission('transactions.read')
     and not erp.has_role('ACCOUNTANT') then
    raise exception 'Permission denied';
  end if;

  if p_topic = 'party' and v_party_input is not null then
    v_party_code := coalesce(erp._assistant_resolve_party_code(v_party_input), v_party_input);
    select id into v_party_id from erp.parties where code ilike v_party_code limit 1;
    if v_party_id is null then
      select id, code into v_party_id, v_party_code
      from erp.parties
      where name ilike '%' || v_party_input || '%'
      order by name
      limit 1;
    end if;
    if v_party_id is null then
      return jsonb_build_object('ok', false, 'error', 'Party not found');
    end if;

    v_result := jsonb_build_object(
      'party_code', v_party_code,
      'balance', (
        select row_to_json(b) from erp.fn_party_balance_for_code(v_party_code, current_date) b
      ),
      'recent_ledger', coalesce((
        select jsonb_agg(row_to_json(t))
        from (
          select * from erp.fn_party_ledger(v_party_code, current_date - 90, current_date)
          order by posting_date desc
          limit 15
        ) t
      ), '[]'::jsonb),
      'pending_rates', coalesce((
        select jsonb_agg(row_to_json(t))
        from (
          select * from erp.fn_pending_rate_register(v_party_code, null, null, true)
          limit 20
        ) t
      ), '[]'::jsonb),
      'open_ar', coalesce((
        select jsonb_agg(row_to_json(ad))
        from erp.ar_documents ad
        where ad.party_id = v_party_id and ad.open_amount > 0
      ), '[]'::jsonb),
      'open_ap', coalesce((
        select jsonb_agg(row_to_json(ad))
        from erp.ap_documents ad
        where ad.party_id = v_party_id and ad.open_amount > 0
      ), '[]'::jsonb)
    );
    return jsonb_build_object('ok', true, 'topic', p_topic, 'data', v_result);
  end if;

  if p_topic = 'document' and v_doc_no is not null then
    if coalesce(v_doc_type, 'sales_invoice') = 'sales_invoice' then
      return erp.fn_erp_assistant_execute_tool('get_sales_invoice', jsonb_build_object('doc_no', v_doc_no));
    elsif v_doc_type = 'purchase_invoice' then
      return erp.fn_erp_assistant_execute_tool('get_purchase_invoice', jsonb_build_object('doc_no', v_doc_no));
    end if;
  end if;

  return jsonb_build_object('ok', false, 'error', 'Invalid context params');
end;
$$;


ALTER FUNCTION "erp"."fn_erp_assistant_context"("p_topic" "text", "p_params" "jsonb") OWNER TO "postgres";

--
-- Name: fn_erp_assistant_execute_tool("text", "jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_erp_assistant_execute_tool"("p_tool" "text", "p_params" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_party_code text;
  v_query text;
  v_from date;
  v_to date;
  v_as_of date;
  v_doc_no text;
  v_limit int;
begin
  perform erp._assert_ai_tool_permission(p_tool);

  v_party_code := nullif(trim(p_params->>'party_code'), '');
  v_query := nullif(trim(coalesce(p_params->>'query', p_params->>'party_name')), '');
  v_from := nullif(p_params->>'from', '')::date;
  v_to := nullif(p_params->>'to', '')::date;
  v_as_of := coalesce(nullif(p_params->>'as_of', '')::date, current_date);
  v_doc_no := nullif(trim(p_params->>'doc_no'), '');
  v_limit := least(greatest(coalesce((p_params->>'limit')::int, 50), 1), 200);

  if p_tool in (
    'get_party_ledger', 'get_party_metal_ledger', 'get_party_balance',
    'get_party_context', 'get_pending_rate_register'
  ) and coalesce(v_party_code, v_query) is not null then
    v_party_code := coalesce(
      erp._assistant_resolve_party_code(coalesce(v_party_code, v_query)),
      v_party_code,
      v_query
    );
  end if;

  case p_tool
    when 'search_parties' then
      if v_query is null then
        raise exception 'query required for search_parties';
      end if;
      select coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) into v_result
      from (
        select p.code as party_code, p.name as party_name, p.party_type, p.city, p.status
        from erp.parties p
        where p.is_active = true
          and (lower(p.name) like '%' || lower(v_query) || '%'
               or lower(p.code) like '%' || lower(v_query) || '%')
        order by p.name
        limit least(greatest(coalesce((p_params->>'limit')::int, 20), 1), 50)
      ) x;

    when 'get_recent_sales_invoices' then
      select coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) into v_result
      from (
        select si.invoice_no, si.invoice_date, si.grand_total, si.subtotal_amount,
               si.posting_status, si.financial_status, p.code as party_code, p.name as party_name
        from erp.sales_invoices si
        join erp.parties p on p.id = si.party_id
        where (v_from is null or si.invoice_date >= v_from)
          and (v_to is null or si.invoice_date <= v_to)
        order by si.invoice_date desc, si.created_at desc
        limit least(greatest(coalesce((p_params->>'limit')::int, 10), 1), 50)
      ) x;

    when 'get_sales_summary' then
      select jsonb_build_object(
        'from', coalesce(v_from, date_trunc('month', current_date)::date),
        'to', coalesce(v_to, current_date),
        'invoice_count', count(*),
        'total_grand', coalesce(sum(si.grand_total), 0),
        'total_subtotal', coalesce(sum(si.subtotal_amount), 0),
        'posted_count', count(*) filter (where si.posting_status = 'posted'),
        'draft_count', count(*) filter (where coalesce(si.posting_status, '') <> 'posted')
      ) into v_result
      from erp.sales_invoices si
      where si.invoice_date between coalesce(v_from, date_trunc('month', current_date)::date)
                                and coalesce(v_to, current_date);

    when 'get_party_ledger' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (
        select * from erp.fn_party_ledger(v_party_code, v_from, v_to)
        order by posting_date desc, voucher_no desc
        limit v_limit
      ) t;

    when 'get_party_metal_ledger' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (
        select * from erp.fn_party_metal_ledger(v_party_code, v_from, v_to)
        limit v_limit
      ) t;

    when 'get_party_balance' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from erp.fn_party_balance_snapshot(v_as_of) t
      where v_party_code is null
         or t.party_code ilike v_party_code
         or t.party_name ilike '%' || v_party_code || '%';

    when 'get_ar_aging' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (select * from erp.fn_ar_aging(v_as_of) limit v_limit) t;

    when 'get_ap_aging' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (select * from erp.fn_ap_aging(v_as_of) limit v_limit) t;

    when 'get_pending_rate_register' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (
        select * from erp.fn_pending_rate_register(
          v_party_code,
          v_from,
          v_to,
          coalesce((p_params->>'open_only')::boolean, true)
        )
        limit v_limit
      ) t;

    when 'get_stock_valuation' then
      select coalesce(jsonb_agg(row_to_json(sv)), '[]'::jsonb) into v_result
      from (
        select * from erp.fn_stock_valuation() sv
        where nullif(trim(p_params->>'item_code'), '') is null
           or sv.item_code ilike trim(p_params->>'item_code')
        limit v_limit
      ) sub;

    when 'get_trial_balance' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (select * from erp.fn_trial_balance(v_from, v_to) limit v_limit) t;

    when 'get_profit_loss' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (select * from erp.fn_profit_loss(v_from, v_to) limit v_limit) t;

    when 'get_balance_sheet' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (select * from erp.fn_balance_sheet(v_as_of) limit v_limit) t;

    when 'get_daily_production' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (select * from erp.fn_daily_production(v_from, v_to) limit v_limit) t;

    when 'get_scrap_wastage' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (select * from erp.fn_scrap_wastage(v_from, v_to) limit v_limit) t;

    when 'get_unit_economics' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (select * from erp.fn_unit_economics(v_from, v_to) limit v_limit) t;

    when 'get_sales_invoice' then
      if v_doc_no is null then
        raise exception 'doc_no required for get_sales_invoice';
      end if;
      select jsonb_build_object(
        'header', (
          select row_to_json(x) from (
            select si.id, si.invoice_no, si.invoice_date, si.posting_status, si.financial_status,
                   si.subtotal_amount, si.discount_amount, si.tax_amount, si.grand_total,
                   si.sale_mode, si.remarks, p.code as party_code, p.name as party_name
            from erp.sales_invoices si
            join erp.parties p on p.id = si.party_id
            where si.invoice_no ilike v_doc_no
            limit 1
          ) x
        ),
        'lines', (
          select coalesce(jsonb_agg(row_to_json(l)), '[]'::jsonb)
          from erp.sales_invoice_lines l
          join erp.sales_invoices si on si.id = l.sales_invoice_id
          where si.invoice_no ilike v_doc_no
        )
      ) into v_result;

    when 'get_purchase_invoice' then
      if v_doc_no is null then
        raise exception 'doc_no required for get_purchase_invoice';
      end if;
      select jsonb_build_object(
        'header', (
          select row_to_json(x) from (
            select pi.id, pi.invoice_no, pi.invoice_date, pi.posting_status, pi.financial_status,
                   pi.subtotal_amount, pi.grand_total, pi.remarks, p.code as party_code, p.name as party_name
            from erp.purchase_invoices pi
            join erp.parties p on p.id = pi.party_id
            where pi.invoice_no ilike v_doc_no
            limit 1
          ) x
        ),
        'lines', (
          select coalesce(jsonb_agg(row_to_json(l)), '[]'::jsonb)
          from erp.purchase_invoice_lines l
          join erp.purchase_invoices pi on pi.id = l.purchase_invoice_id
          where pi.invoice_no ilike v_doc_no
        )
      ) into v_result;

    when 'get_posting_health' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from erp.fn_posting_map_health() t;

    when 'get_reconciliation_checks' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from erp.fn_reconciliation_checks() t;

    when 'get_sales_invoice_deploy_check' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from erp.fn_post_sales_invoice_deploy_check() t;

    when 'get_purchase_invoice_deploy_check' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from erp.fn_post_purchase_invoice_deploy_check() t;

    when 'get_transaction_history' then
      select coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) into v_result
      from (
        select * from erp.fn_transaction_history(
          coalesce((p_params->>'from_ts')::timestamptz, current_date - interval '30 days'),
          coalesce((p_params->>'to_ts')::timestamptz, current_date + interval '1 day'),
          nullif(p_params->>'entity_type', ''),
          null,
          nullif(p_params->>'search', ''),
          v_limit
        )
      ) t;

    when 'get_party_context' then
      v_result := erp.fn_erp_assistant_context('party', jsonb_build_object('party_code', v_party_code));

    when 'get_document_context' then
      v_result := erp.fn_erp_assistant_context('document', p_params);

    when 'search_documents' then
      v_result := erp.fn_erp_document_search(
        coalesce(nullif(trim(p_params->>'query'), ''), ''),
        coalesce(nullif(p_params->>'doc_type', ''), null),
        v_limit
      );

    else
      raise exception 'Unknown tool: %', p_tool;
  end case;

  return jsonb_build_object('ok', true, 'tool', p_tool, 'data', coalesce(v_result, 'null'::jsonb));
end;
$$;


ALTER FUNCTION "erp"."fn_erp_assistant_execute_tool"("p_tool" "text", "p_params" "jsonb") OWNER TO "postgres";

--
-- Name: fn_erp_assistant_log("text", "text"[], "text", boolean, "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_erp_assistant_log"("p_question_hash" "text", "p_tools_called" "text"[], "p_context_page" "text" DEFAULT NULL::"text", "p_success" boolean DEFAULT true, "p_error_message" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Unauthorized';
  end if;
  insert into erp.ai_query_log (user_id, question_hash, tools_called, context_page, success, error_message)
  values (auth.uid(), p_question_hash, coalesce(p_tools_called, '{}'), p_context_page, coalesce(p_success, true), p_error_message)
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "erp"."fn_erp_assistant_log"("p_question_hash" "text", "p_tools_called" "text"[], "p_context_page" "text", "p_success" boolean, "p_error_message" "text") OWNER TO "postgres";

--
-- Name: fn_erp_document_search("text", "text", integer); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_erp_document_search"("p_query" "text", "p_doc_type" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_q text := '%' || lower(trim(coalesce(p_query, ''))) || '%';
  v_lim int := least(greatest(coalesce(p_limit, 30), 1), 100);
  v_hits jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'Unauthorized';
  end if;
  if not erp.has_role('ADMIN')
     and not erp.has_permission('ledger.read')
     and not erp.has_permission('transactions.read')
     and not erp.has_role('ACCOUNTANT') then
    raise exception 'Permission denied';
  end if;

  if length(trim(coalesce(p_query, ''))) < 2 then
    return jsonb_build_object('ok', false, 'error', 'Query must be at least 2 characters');
  end if;

  if p_doc_type is null or p_doc_type = 'sales_invoice' then
    v_hits := v_hits || coalesce((
      select jsonb_agg(jsonb_build_object(
        'doc_type', 'sales_invoice',
        'doc_no', si.invoice_no,
        'date', si.invoice_date,
        'party_name', p.name,
        'party_code', p.code,
        'amount', si.grand_total,
        'status', si.posting_status
      ))
      from erp.sales_invoices si
      join erp.parties p on p.id = si.party_id
      where lower(si.invoice_no) like v_q
         or lower(p.name) like v_q
         or lower(coalesce(si.remarks, '')) like v_q
      limit v_lim
    ), '[]'::jsonb);
  end if;

  if p_doc_type is null or p_doc_type = 'purchase_invoice' then
    v_hits := v_hits || coalesce((
      select jsonb_agg(jsonb_build_object(
        'doc_type', 'purchase_invoice',
        'doc_no', pi.invoice_no,
        'date', pi.invoice_date,
        'party_name', p.name,
        'party_code', p.code,
        'amount', pi.grand_total,
        'status', pi.posting_status
      ))
      from erp.purchase_invoices pi
      join erp.parties p on p.id = pi.party_id
      where lower(pi.invoice_no) like v_q
         or lower(p.name) like v_q
         or lower(coalesce(pi.remarks, '')) like v_q
      limit v_lim
    ), '[]'::jsonb);
  end if;

  return jsonb_build_object('ok', true, 'query', p_query, 'hits', v_hits);
end;
$$;


ALTER FUNCTION "erp"."fn_erp_document_search"("p_query" "text", "p_doc_type" "text", "p_limit" integer) OWNER TO "postgres";

--
-- Name: fn_evaluate_production_alerts("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_evaluate_production_alerts"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_eval_as_of date;
  v_period_start date;
  v_draw_pct numeric; v_ws_pct numeric; v_enam_pct numeric;
  v_wire8_landed numeric; v_draw_scrap numeric; v_ws_scrap numeric; v_enam_scrap numeric;
  v_enam_input numeric; v_rod_in numeric;
  v_draw_ratio numeric; v_ws_ratio numeric; v_enam_ratio numeric;
  v_count int := 0; v_machine record; v_std numeric; v_ratio numeric;
  v_draw_over boolean; v_ws_over boolean; v_enam_over boolean;
begin
  v_eval_as_of := erp._production_alert_eval_as_of(coalesce(p_as_of, current_date), null);
  v_period_start := date_trunc('month', v_eval_as_of)::date;
  v_draw_pct := erp._production_standard_num('drawing_wastage_pct', v_eval_as_of) / 100.0;
  v_ws_pct := erp._production_standard_num('workshop_wastage_pct', v_eval_as_of) / 100.0;
  v_enam_pct := erp._production_standard_num('enamel_scrap_pct', v_eval_as_of) / 100.0;
  v_wire8_landed := erp._mtd_wire8_landed_kg(v_period_start, v_eval_as_of);
  v_draw_scrap := erp._mtd_drawing_scrap_kg(v_period_start, v_eval_as_of);
  v_ws_scrap := erp._mtd_workshop_scrap_kg(v_period_start, v_eval_as_of);
  v_enam_scrap := erp._mtd_enamel_scrap_kg(v_period_start, v_eval_as_of);
  select coalesce(sum(pb.input_kg), 0) into v_enam_input from erp.production_batches pb
  where pb.process_type = 'enamel' and pb.status = 'posted' and pb.batch_date between v_period_start and v_eval_as_of;
  v_rod_in := erp._mtd_rod_input_kg(v_period_start, v_eval_as_of);
  v_draw_over := v_wire8_landed > 0 and v_draw_scrap > v_wire8_landed * v_draw_pct;
  v_ws_over := v_rod_in > 0 and v_ws_scrap > v_rod_in * v_ws_pct;
  v_enam_over := v_enam_input > 0 and v_enam_scrap > v_enam_input * v_enam_pct;
  if v_draw_over then
    v_draw_ratio := round((v_draw_scrap / v_wire8_landed) * 100, 2);
    insert into erp.production_alerts (alert_type, severity, message, metric_value, threshold_value, period_start, status)
    values ('drawing_scrap_mtd', case when v_draw_ratio > v_draw_pct * 100 * 1.5 then 'critical' else 'warning' end,
      format('Drawing scrap MTD %s%% exceeds standard %s%% (%s kg / %s kg wire-8 landed)', v_draw_ratio, round(v_draw_pct * 100, 2), round(v_draw_scrap, 1), round(v_wire8_landed, 1)),
      v_draw_ratio, v_draw_pct * 100, v_period_start, 'open')
    on conflict (alert_type, period_start, coalesce(machine_id, '00000000-0000-0000-0000-000000000000'::uuid)) do update set
      message=excluded.message, metric_value=excluded.metric_value, threshold_value=excluded.threshold_value, severity=excluded.severity,
      status=case when erp.production_alerts.status='resolved' then 'open' else erp.production_alerts.status end;
    v_count := v_count + 1;
  elsif v_draw_scrap <= 0 or v_wire8_landed > 0 then
    update erp.production_alerts set status='resolved' where alert_type='drawing_scrap_mtd' and period_start=v_period_start and machine_id is null and status='open';
  end if;
  if v_ws_over then
    v_ws_ratio := round((v_ws_scrap / v_rod_in) * 100, 2);
    insert into erp.production_alerts (alert_type, severity, message, metric_value, threshold_value, period_start, status)
    values ('workshop_scrap_mtd', case when v_ws_ratio > v_ws_pct * 100 * 1.5 then 'critical' else 'warning' end,
      format('Workshop scrap MTD %s%% exceeds standard %s%% (%s kg / %s kg rod input)', v_ws_ratio, round(v_ws_pct * 100, 2), round(v_ws_scrap, 1), round(v_rod_in, 1)),
      v_ws_ratio, v_ws_pct * 100, v_period_start, 'open')
    on conflict (alert_type, period_start, coalesce(machine_id, '00000000-0000-0000-0000-000000000000'::uuid)) do update set
      message=excluded.message, metric_value=excluded.metric_value, threshold_value=excluded.threshold_value, severity=excluded.severity,
      status=case when erp.production_alerts.status='resolved' then 'open' else erp.production_alerts.status end;
    v_count := v_count + 1;
  elsif v_ws_scrap <= 0 or v_rod_in > 0 then
    update erp.production_alerts set status='resolved' where alert_type='workshop_scrap_mtd' and period_start=v_period_start and machine_id is null and status='open';
  end if;
  if v_enam_over then
    v_enam_ratio := round((v_enam_scrap / v_enam_input) * 100, 2);
    insert into erp.production_alerts (alert_type, severity, message, metric_value, threshold_value, period_start, status)
    values ('enamel_scrap_mtd', case when v_enam_ratio > v_enam_pct * 100 * 1.5 then 'critical' else 'warning' end,
      format('Enamel scrap MTD %s%% exceeds standard %s%% (%s kg / %s kg input)', v_enam_ratio, round(v_enam_pct * 100, 2), round(v_enam_scrap, 1), round(v_enam_input, 1)),
      v_enam_ratio, v_enam_pct * 100, v_period_start, 'open')
    on conflict (alert_type, period_start, coalesce(machine_id, '00000000-0000-0000-0000-000000000000'::uuid)) do update set
      message=excluded.message, metric_value=excluded.metric_value, threshold_value=excluded.threshold_value, severity=excluded.severity,
      status=case when erp.production_alerts.status='resolved' then 'open' else erp.production_alerts.status end;
    v_count := v_count + 1;
  elsif v_enam_scrap <= 0 or v_enam_input > 0 then
    update erp.production_alerts set status='resolved' where alert_type='enamel_scrap_mtd' and period_start=v_period_start and machine_id is null and status='open';
  end if;
  for v_machine in select * from erp.fn_machine_production_summary(v_period_start, v_eval_as_of, null, null) where input_kg > 0 and scrap_kg > 0 loop
    v_std := erp._machine_wastage_limit_pct(v_machine.machine_code, v_machine.department, v_eval_as_of);
    if v_std <= 0 then continue; end if;
    v_ratio := round((v_machine.scrap_kg / nullif(v_machine.input_kg, 0)) * 100, 2);
    if v_ratio <= v_std then
      update erp.production_alerts set status='resolved' where alert_type='machine_scrap_mtd' and period_start=v_period_start and machine_id=v_machine.machine_id and status='open';
      continue;
    end if;
    insert into erp.production_alerts (alert_type, severity, message, metric_value, threshold_value, period_start, machine_id, status)
    values ('machine_scrap_mtd', case when v_ratio > v_std * 1.5 then 'critical' else 'warning' end,
      format('Machine %s scrap MTD %s%% exceeds standard %s%% (%s kg / %s kg input)', v_machine.machine_code, v_ratio, round(v_std, 2), round(v_machine.scrap_kg, 1), round(v_machine.input_kg, 1)),
      v_ratio, v_std, v_period_start, v_machine.machine_id, 'open')
    on conflict (alert_type, period_start, coalesce(machine_id, '00000000-0000-0000-0000-000000000000'::uuid)) do update set
      message=excluded.message, metric_value=excluded.metric_value, threshold_value=excluded.threshold_value, severity=excluded.severity, machine_id=excluded.machine_id,
      status=case when erp.production_alerts.status='resolved' then 'open' else erp.production_alerts.status end;
    v_count := v_count + 1;
  end loop;
  update erp.production_alerts a set status='resolved'
  where a.alert_type='machine_scrap_mtd' and a.period_start=v_period_start and a.status='open' and a.machine_id is not null
    and not exists (select 1 from erp.fn_machine_production_summary(v_period_start, v_eval_as_of, null, a.machine_id) s
      where s.input_kg > 0 and s.scrap_kg > 0 and s.scrap_pct > erp._machine_wastage_limit_pct(s.machine_code, s.department, v_eval_as_of));
  return v_count;
end;
$$;


ALTER FUNCTION "erp"."fn_evaluate_production_alerts"("p_as_of" "date") OWNER TO "postgres";

--
-- Name: fn_expense_register_report("date", "date", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_expense_register_report"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_report_group" "text" DEFAULT NULL::"text") RETURNS TABLE("posting_date" "date", "voucher_no" "text", "account_code" "text", "account_name" "text", "report_group" "text", "party_name" "text", "narration" "text", "debit_amount" numeric, "credit_amount" numeric, "net_amount" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    je.posting_date,
    coalesce(je.voucher_no, je.source_doc_no, '')::text as voucher_no,
    ca.code::text as account_code,
    ca.name::text as account_name,
    coalesce(ca.report_group, 'other')::text as report_group,
    coalesce(p.name, '')::text as party_name,
    coalesce(jl.line_description, je.narration, '')::text as narration,
    coalesce(jl.debit_amount, 0)::numeric as debit_amount,
    coalesce(jl.credit_amount, 0)::numeric as credit_amount,
    (coalesce(jl.debit_amount, 0) - coalesce(jl.credit_amount, 0))::numeric as net_amount
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  join erp.coa_accounts ca on ca.code = jl.account_code
  left join erp.parties p on p.id = jl.party_id
  where je.status = 'posted'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    and ca.is_posting = true
    and ca.account_type = 'expense'
    and ca.code not in ('51001', '51010', '51011', '51012', '51013', '51999')
    and (
      ca.report_group in (
        'factory_overhead',
        'admin_expense',
        'selling_expense',
        'other_expense'
      )
      or ca.code in (
        '51002', '51003', '51004', '51005', '51006', '51007', '51008', '51009',
        '50001', '50002', '50003'
      )
    )
    and (p_from is null or je.posting_date >= p_from)
    and (p_to is null or je.posting_date <= p_to)
    and (
      p_report_group is null
      or p_report_group = ''
      or p_report_group = 'all'
      or coalesce(ca.report_group, 'other') = p_report_group
      or (
        p_report_group = 'cogs_cash'
        and ca.code in (
          '51002', '51003', '51004', '51005', '51006', '51007', '51008', '51009'
        )
      )
    )
  order by je.posting_date, je.voucher_no, ca.code;
$$;


ALTER FUNCTION "erp"."fn_expense_register_report"("p_from" "date", "p_to" "date", "p_report_group" "text") OWNER TO "postgres";

--
-- Name: fn_factory_scrap_dispatch_register("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_factory_scrap_dispatch_register"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("dispatch_id" "uuid", "dispatch_no" "text", "dispatch_date" "date", "mode" "text", "vendor_code" "text", "vendor_name" "text", "net_weight" numeric, "unit_rate" numeric, "amount" numeric, "status" "text", "machines" "text", "departments" "text", "expected_item_code" "text", "expected_kg" numeric, "returned_kg" numeric, "obligation_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    fs.id,
    fs.dispatch_no,
    fs.dispatch_date,
    fs.mode,
    p.code,
    p.name,
    fs.net_weight,
    fs.unit_rate,
    fs.amount,
    fs.status,
    coalesce(string_agg(distinct m.machine_code, ', ' order by m.machine_code), ''),
    coalesce(string_agg(distinct fsl.department, ', '), ''),
    ei.code,
    coalesce(sco.expected_kg, 0),
    coalesce(sco.returned_kg, 0),
    sco.status
  from erp.factory_scrap_dispatches fs
  join erp.parties p on p.id = fs.dest_party_id
  left join erp.factory_scrap_dispatch_lines fsl on fsl.dispatch_id = fs.id
  left join erp.production_machines m on m.id = fsl.machine_id
  left join erp.scrap_conversion_obligations sco on sco.dispatch_id = fs.id
  left join erp.items ei on ei.id = fs.expected_return_item_id
  where (p_from is null or fs.dispatch_date >= p_from)
    and (p_to is null or fs.dispatch_date <= p_to)
  group by
    fs.id, fs.dispatch_no, fs.dispatch_date, fs.mode,
    p.code, p.name, fs.net_weight, fs.unit_rate, fs.amount, fs.status,
    ei.code, sco.expected_kg, sco.returned_kg, sco.status
  order by fs.dispatch_date desc, fs.dispatch_no desc;
$$;


ALTER FUNCTION "erp"."fn_factory_scrap_dispatch_register"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_get_live_conversion_rate("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_get_live_conversion_rate"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_as_of date := coalesce(p_as_of, current_date);
  v_from date := v_as_of - 29;
  v_opex numeric := 0;
  v_fg_kg numeric := 0;
  v_fallback numeric := 0;
  v_rate numeric := 0;
begin
  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0)
  into v_opex
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where je.posting_date between v_from and v_as_of
    and je.status = 'posted'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    -- Positive whitelist (migration 274 parity): classified conversion OH only.
    and (
      exists (
        select 1
        from erp.coa_accounts ca
        where ca.code = jl.account_code
          and ca.is_posting = true
          and ca.report_group in ('factory_overhead', 'conversion_overhead')
      )
      or jl.account_code in (
        '51002', '51003', '51004', '51005', '51007', '51008', '51009'
      )
    )
    -- Safety net: never absorb variances, unabsorbed-OH plugs, clearing or
    -- COGS component accounts even if someone retags them later.
    and jl.account_code not in (
      '51014', '51999',
      '51000', '51001', '51006', '51010', '51011', '51012', '51013'
    );

  select coalesce(sum(im.qty_in), 0)
  into v_fg_kg
  from erp.inventory_movements im
  where im.movement_type = 'production_receipt'
    and im.source_doc_type = 'production_batch'
    and im.posting_date between v_from and v_as_of;

  if v_fg_kg > 0.0005 then
    v_rate := round(v_opex / v_fg_kg, 6);
  else
    v_fallback := coalesce(
      nullif(erp._production_standard_num('live_conversion_rate_fallback', v_as_of), 0),
      0
    );
    v_rate := round(coalesce(v_fallback, 0), 6);
  end if;

  if v_rate < 0 then
    v_rate := 0;
  end if;

  return v_rate;
end;
$$;


ALTER FUNCTION "erp"."fn_get_live_conversion_rate"("p_as_of" "date") OWNER TO "postgres";

--
-- Name: FUNCTION "fn_get_live_conversion_rate"("p_as_of" "date"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."fn_get_live_conversion_rate"("p_as_of" "date") IS 'Rolling 30-day conversion overhead per FG kg for perpetual absorption. Whitelist-based since mig 309: factory_overhead/conversion_overhead group tags + direct codes {51002-05, 51007-09}; excludes 51014 variance, 51999 plug, COGS components. Mirrors _pac_auto_overhead_amount (mig 274).';


--
-- Name: fn_inventory_movement_totals("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_inventory_movement_totals"("p_from" "date", "p_to" "date") RETURNS TABLE("sales_out_qty" numeric, "purchase_in_qty" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  perform erp._assert_report_access();

  if p_from is null or p_to is null then
    raise exception 'p_from and p_to are required';
  end if;
  if p_from > p_to then
    raise exception 'p_from must be on or before p_to';
  end if;

  return query
  select
    coalesce(sum(im.qty_out) filter (
      where im.movement_type = 'sales_out'
    ), 0)::numeric as sales_out_qty,
    coalesce(sum(im.qty_in) filter (
      where im.movement_type = 'purchase_in'
    ), 0)::numeric as purchase_in_qty
  from erp.inventory_movements im
  where im.posting_date between p_from and p_to
    and im.movement_type in ('sales_out', 'purchase_in');
end;
$$;


ALTER FUNCTION "erp"."fn_inventory_movement_totals"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_invoice_posting_integrity(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_invoice_posting_integrity"() RETURNS TABLE("check_code" "text", "check_name" "text", "issue_count" bigint, "status" "text", "sample_refs" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_has_obligations boolean := to_regclass('erp.scrap_receivable_obligations') is not null;
begin
  return query
  select
    'POSTED_SI_NO_JOURNAL'::text,
    'Posted sales invoices missing journal entry'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(si.invoice_no, ', ' order by si.invoice_no), '')
  from erp.sales_invoices si
  where si.posting_status = 'posted'
    and not exists (
      select 1 from erp.journal_entries je
      where je.source_doc_type = 'sales_invoice' and je.source_doc_id = si.id
    );

  return query
  select
    'POSTED_PI_NO_JOURNAL'::text,
    'Posted purchase invoices missing journal entry'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(pi.invoice_no, ', ' order by pi.invoice_no), '')
  from erp.purchase_invoices pi
  where pi.posting_status = 'posted'
    and not exists (
      select 1 from erp.journal_entries je
      where je.source_doc_type = 'purchase_invoice' and je.source_doc_id = pi.id
    );

  return query
  select
    'POSTED_SR_NO_JOURNAL'::text,
    'Posted sales returns missing journal entry'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(sr.return_no, ', ' order by sr.return_no), '')
  from erp.sales_returns sr
  where sr.posting_status = 'posted'
    and not exists (
      select 1 from erp.journal_entries je
      where je.source_doc_type = 'sales_return' and je.source_doc_id = sr.id
    );

  return query
  select
    'POSTED_PR_NO_JOURNAL'::text,
    'Posted purchase returns missing journal entry'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(pr.return_no, ', ' order by pr.return_no), '')
  from erp.purchase_returns pr
  where pr.posting_status = 'posted'
    and not exists (
      select 1 from erp.journal_entries je
      where je.source_doc_type = 'purchase_return' and je.source_doc_id = pr.id
    );

  return query
  select
    'POSTED_SI_NO_AR'::text,
    'Posted sales invoices missing AR subledger document'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(si.invoice_no, ', ' order by si.invoice_no), '')
  from erp.sales_invoices si
  where si.posting_status = 'posted'
    and not exists (
      select 1 from erp.ar_documents ad
      where ad.source_doc_type = 'sales_invoice' and ad.source_doc_id = si.id
    );

  return query
  select
    'POSTED_PI_NO_AP'::text,
    'Posted purchase invoices missing AP subledger document'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(pi.invoice_no, ', ' order by pi.invoice_no), '')
  from erp.purchase_invoices pi
  where pi.posting_status = 'posted'
    and not exists (
      select 1 from erp.ap_documents ad
      where ad.source_doc_type = 'purchase_invoice' and ad.source_doc_id = pi.id
    );

  return query
  select
    'POSTED_SI_NULL_POSTED_AT'::text,
    'Posted sales invoices with null posted_at'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(si.invoice_no, ', ' order by si.invoice_no), '')
  from erp.sales_invoices si
  where si.posting_status = 'posted' and si.posted_at is null;

  return query
  select
    'POSTED_PI_NULL_POSTED_AT'::text,
    'Posted purchase invoices with null posted_at'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(pi.invoice_no, ', ' order by pi.invoice_no), '')
  from erp.purchase_invoices pi
  where pi.posting_status = 'posted' and pi.posted_at is null;

  return query
  select
    'SI_AR_AMOUNT_MISMATCH'::text,
    'Posted sales invoice grand_total vs AR journal line'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(x.invoice_no, ', ' order by x.invoice_no), '')
  from (
    select si.invoice_no
    from erp.sales_invoices si
    left join lateral (
      select coalesce(sum(jl.debit_amount), 0) as ar_debit
      from erp.journal_entries je
      join erp.journal_lines jl on jl.journal_entry_id = je.id
      where je.source_doc_type = 'sales_invoice'
        and je.source_doc_id = si.id
        and jl.account_code = erp._resolve_posting_account('sales_invoice', 'ar')
    ) j on true
    where si.posting_status = 'posted'
      and abs(si.grand_total - coalesce(j.ar_debit, 0)) > 0.01
  ) x;

  return query
  select
    'PI_AP_AMOUNT_MISMATCH'::text,
    'Posted purchase invoice grand_total vs AP journal line'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(x.invoice_no, ', ' order by x.invoice_no), '')
  from (
    select pi.invoice_no
    from erp.purchase_invoices pi
    left join lateral (
      select coalesce(sum(jl.credit_amount), 0) as ap_credit
      from erp.journal_entries je
      join erp.journal_lines jl on jl.journal_entry_id = je.id
      where je.source_doc_type = 'purchase_invoice'
        and je.source_doc_id = pi.id
        and jl.account_code = erp._resolve_posting_account('purchase_invoice', 'ap')
    ) j on true
    where pi.posting_status = 'posted'
      and abs(pi.grand_total - coalesce(j.ap_credit, 0)) > 0.01
  ) x;

  return query
  select
    'STUCK_DRAFT_SI'::text,
    'Sales invoice drafts older than 7 days (review)'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'WARN' end,
    coalesce(string_agg(si.invoice_no, ', ' order by si.invoice_no), '')
  from erp.sales_invoices si
  where si.posting_status = 'draft'
    and si.created_at < now() - interval '7 days'
    and exists (select 1 from erp.sales_invoice_lines sil where sil.sales_invoice_id = si.id);

  return query
  select
    'STUCK_DRAFT_PI'::text,
    'Purchase invoice drafts older than 7 days (review)'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'WARN' end,
    coalesce(string_agg(pi.invoice_no, ', ' order by pi.invoice_no), '')
  from erp.purchase_invoices pi
  where pi.posting_status = 'draft'
    and pi.created_at < now() - interval '7 days'
    and exists (select 1 from erp.purchase_invoice_lines pil where pil.purchase_invoice_id = pi.id);

  if v_has_obligations then
    return query
    select
      'PREMIUM_SI_NO_OBLIGATION'::text,
      'Posted premium sales invoices missing scrap obligation'::text,
      count(*)::bigint,
      case when count(*) = 0 then 'PASS' else 'FAIL' end,
      coalesce(string_agg(si.invoice_no, ', ' order by si.invoice_no), '')
    from erp.sales_invoices si
    where si.posting_status = 'posted'
      and si.sale_mode = 'premium'
      and not exists (
        select 1 from erp.scrap_receivable_obligations o
        where o.sales_invoice_id = si.id
      );
  end if;

  return query
  with bad_si as (
    select distinct si.invoice_no
    from erp.sales_invoices si
    join erp.sales_invoice_lines sil on sil.sales_invoice_id = si.id
    where si.posting_status = 'posted'
      and coalesce(sil.net_weight, sil.qty, 0) > 0
      and sil.sales_order_line_id is null
      and exists (
        select 1 from erp.sales_invoice_lines s2
        where s2.sales_invoice_id = si.id and s2.sales_order_line_id is not null
      )
  )
  select
    'SI_MIXED_SO_LINE_FK'::text,
    'Posted SI with billable lines missing sales_order_line_id when invoice is partially linked'::text,
    count(*)::bigint,
    case when count(*) = 0 then 'PASS' else 'FAIL' end,
    coalesce(string_agg(invoice_no, ', ' order by invoice_no), '')
  from bad_si;
end;
$$;


ALTER FUNCTION "erp"."fn_invoice_posting_integrity"() OWNER TO "postgres";

--
-- Name: fn_item_ledger("text", "date", "date", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_item_ledger"("p_item_code" "text", "p_from" "date" DEFAULT '1900-01-01'::"date", "p_to" "date" DEFAULT CURRENT_DATE, "p_warehouse_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("posting_date" "date", "movement_type" "text", "source_doc_type" "text", "source_doc_no" "text", "party_code" "text", "party_name" "text", "reference_no" "text", "qty_in" numeric, "qty_out" numeric, "units_in" numeric, "units_out" numeric, "running_qty" numeric, "running_units" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item_id uuid;
begin
  if p_item_code is null then
    raise exception 'p_item_code is required';
  end if;

  select id into v_item_id from erp.items where code = p_item_code;
  if v_item_id is null then
    raise exception 'Item not found: %', p_item_code;
  end if;

  return query
  with opening as (
    select
      coalesce(sum(coalesce(im.qty_in, 0) - coalesce(im.qty_out, 0)), 0)::numeric as qty,
      coalesce(sum(coalesce(im.units_in, 0) - coalesce(im.units_out, 0)), 0)::numeric as units
    from erp.inventory_movements im
    where im.item_id = v_item_id
      and im.posting_date < p_from
      and (p_warehouse_id is null or im.warehouse_id = p_warehouse_id)
  ),
  period as (
    select
      im.posting_date as pd,
      im.movement_type as mt,
      coalesce(im.source_doc_type, '') as sdt,
      coalesce(
        pb.batch_no,
        si.invoice_no,
        pi.invoice_no,
        sr.return_no,
        pr.return_no,
        st.trade_no,
        fsd.dispatch_no,
        im.reference_no,
        ''
      ) as sdn,
      p.code as pcode,
      p.name as pname,
      im.reference_no as refno,
      coalesce(im.qty_in, 0) as qi,
      coalesce(im.qty_out, 0) as qo,
      coalesce(im.units_in, 0) as ui,
      coalesce(im.units_out, 0) as uo,
      (coalesce(im.qty_in, 0) - coalesce(im.qty_out, 0)) as qd,
      (coalesce(im.units_in, 0) - coalesce(im.units_out, 0)) as ud,
      row_number() over (
        order by im.posting_date, im.created_at, im.id
      )::bigint as rn
    from erp.inventory_movements im
    left join erp.parties p on p.id = im.party_id
    left join erp.production_batches pb
      on pb.id = im.source_doc_id and im.source_doc_type = 'production_batch'
    left join erp.sales_invoices si
      on si.id = im.source_doc_id and im.source_doc_type = 'sales_invoice'
    left join erp.purchase_invoices pi
      on pi.id = im.source_doc_id and im.source_doc_type = 'purchase_invoice'
    left join erp.sales_returns sr
      on sr.id = im.source_doc_id and im.source_doc_type = 'sales_return'
    left join erp.purchase_returns pr
      on pr.id = im.source_doc_id and im.source_doc_type = 'purchase_return'
    left join erp.scrap_trades st
      on st.id = im.source_doc_id and im.source_doc_type = 'scrap_trade'
    left join erp.factory_scrap_dispatches fsd
      on fsd.id = im.source_doc_id and im.source_doc_type = 'factory_scrap_dispatch'
    where im.item_id = v_item_id
      and im.posting_date between p_from and p_to
      and (p_warehouse_id is null or im.warehouse_id = p_warehouse_id)
  ),
  opening_row as (
    select
      p_from as pd,
      'opening'::text as mt,
      'opening'::text as sdt,
      'OPENING'::text as sdn,
      null::text as pcode,
      null::text as pname,
      null::text as refno,
      case when o.qty > 0 then o.qty else 0 end as qi,
      case when o.qty < 0 then -o.qty else 0 end as qo,
      case when o.units > 0 then o.units else 0 end as ui,
      case when o.units < 0 then -o.units else 0 end as uo,
      o.qty as qd,
      o.units as ud,
      0::bigint as rn
    from opening o
  ),
  all_rows as (
    select pd, mt, sdt, sdn, pcode, pname, refno, qi, qo, ui, uo, qd, ud, rn from opening_row
    union all
    select pd, mt, sdt, sdn, pcode, pname, refno, qi, qo, ui, uo, qd, ud, rn from period
  )
  select
    r.pd,
    r.mt,
    r.sdt,
    r.sdn,
    r.pcode,
    r.pname,
    r.refno,
    r.qi,
    r.qo,
    r.ui,
    r.uo,
    sum(r.qd) over (order by r.rn) as rq,
    sum(r.ud) over (order by r.rn) as ru
  from all_rows r
  order by r.rn;
end;
$$;


ALTER FUNCTION "erp"."fn_item_ledger"("p_item_code" "text", "p_from" "date", "p_to" "date", "p_warehouse_id" "uuid") OWNER TO "postgres";

--
-- Name: fn_machine_production_daily("date", "date", "text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_machine_production_daily"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_department" "text" DEFAULT NULL::"text", "p_machine_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("prod_date" "date", "machine_id" "uuid", "machine_code" "text", "machine_name" "text", "department" "text", "batch_count" bigint, "input_kg" numeric, "output_kg" numeric, "scrap_kg" numeric, "scrap_pct" numeric, "standard_pct" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with prod as (
    select
      pb.batch_date as prod_date,
      coalesce(pbl.machine_id, pb.machine_id) as machine_id,
      count(distinct pb.id)::bigint as batch_count,
      sum(
        case
          when pbl.line_type = 'issue' and coalesce(w.wh_type, '') <> 'packing_material'
            then coalesce(pbl.net_weight, 0)
          else 0
        end
      )::numeric as input_kg,
      sum(case when pbl.line_type = 'receipt' then coalesce(pbl.net_weight, 0) else 0 end)::numeric as output_kg
    from erp.production_batches pb
    join erp.production_batch_lines pbl on pbl.production_batch_id = pb.id
    left join erp.warehouses w on w.id = pbl.warehouse_id
    where pb.status = 'posted'
      and coalesce(pbl.machine_id, pb.machine_id) is not null
      and (p_from is null or pb.batch_date >= p_from)
      and (p_to is null or pb.batch_date <= p_to)
      and (p_machine_id is null or coalesce(pbl.machine_id, pb.machine_id) = p_machine_id)
    group by pb.batch_date, coalesce(pbl.machine_id, pb.machine_id)
  ),
  scrap as (
    select
      fs.dispatch_date as prod_date,
      fsl.machine_id,
      sum(fsl.net_weight)::numeric as scrap_kg
    from erp.factory_scrap_dispatch_lines fsl
    join erp.factory_scrap_dispatches fs on fs.id = fsl.dispatch_id
    where fs.status = 'posted'
      and fsl.machine_id is not null
      and (p_from is null or fs.dispatch_date >= p_from)
      and (p_to is null or fs.dispatch_date <= p_to)
      and (p_machine_id is null or fsl.machine_id = p_machine_id)
    group by fs.dispatch_date, fsl.machine_id
  ),
  keys as (
    select prod_date, machine_id from prod
    union
    select prod_date, machine_id from scrap
  )
  select
    k.prod_date,
    m.id,
    m.machine_code,
    m.name,
    m.department,
    coalesce(p.batch_count, 0)::bigint,
    coalesce(p.input_kg, 0),
    coalesce(p.output_kg, 0),
    coalesce(s.scrap_kg, 0),
    case
      when coalesce(p.input_kg, 0) > 0
        then round((coalesce(s.scrap_kg, 0) / p.input_kg) * 100, 2)
      else 0
    end,
    erp._machine_wastage_limit_pct(m.machine_code, m.department, k.prod_date)
  from keys k
  join erp.production_machines m on m.id = k.machine_id
  left join prod p on p.prod_date = k.prod_date and p.machine_id = k.machine_id
  left join scrap s on s.prod_date = k.prod_date and s.machine_id = k.machine_id
  where m.is_active
    and (p_department is null or m.department = p_department)
  order by k.prod_date, m.department, m.sort_order, m.machine_code;
$$;


ALTER FUNCTION "erp"."fn_machine_production_daily"("p_from" "date", "p_to" "date", "p_department" "text", "p_machine_id" "uuid") OWNER TO "postgres";

--
-- Name: fn_machine_production_summary("date", "date", "text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_machine_production_summary"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_department" "text" DEFAULT NULL::"text", "p_machine_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("machine_id" "uuid", "machine_code" "text", "machine_name" "text", "department" "text", "batch_count" bigint, "input_kg" numeric, "output_kg" numeric, "scrap_kg" numeric, "scrap_pct" numeric, "standard_pct" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with production as (
    select
      coalesce(pbl.machine_id, pb.machine_id) as machine_id,
      count(distinct pb.id)::bigint as batch_count,
      sum(
        case
          when pbl.line_type = 'issue'
            and coalesce(w.wh_type, '') <> 'packing_material'
            then coalesce(pbl.net_weight, 0)
          else 0
        end
      )::numeric as input_kg,
      sum(
        case when pbl.line_type = 'receipt' then coalesce(pbl.net_weight, 0) else 0 end
      )::numeric as output_kg
    from erp.production_batches pb
    join erp.production_batch_lines pbl on pbl.production_batch_id = pb.id
    left join erp.warehouses w on w.id = pbl.warehouse_id
    where pb.status = 'posted'
      and coalesce(pbl.machine_id, pb.machine_id) is not null
      and (p_from is null or pb.batch_date >= p_from)
      and (p_to is null or pb.batch_date <= p_to)
      and (p_machine_id is null or coalesce(pbl.machine_id, pb.machine_id) = p_machine_id)
    group by coalesce(pbl.machine_id, pb.machine_id)
  ),
  scrap as (
    select
      fsl.machine_id,
      sum(fsl.net_weight)::numeric as scrap_kg
    from erp.factory_scrap_dispatch_lines fsl
    join erp.factory_scrap_dispatches fs on fs.id = fsl.dispatch_id
    where fs.status = 'posted'
      and fsl.machine_id is not null
      and (p_from is null or fs.dispatch_date >= p_from)
      and (p_to is null or fs.dispatch_date <= p_to)
      and (p_machine_id is null or fsl.machine_id = p_machine_id)
    group by fsl.machine_id
  ),
  machine_values as (
    select
      m.id as machine_id,
      coalesce(pr.batch_count, 0)::bigint as batch_count,
      case
        when m.department = 'drawing'
          then erp._drawing_machine_input_kg(m.id, p_from, p_to)
        else coalesce(pr.input_kg, 0)
      end::numeric as input_kg,
      case
        when m.department = 'drawing' then 0::numeric
        else coalesce(pr.output_kg, 0)
      end::numeric as output_kg,
      coalesce(sc.scrap_kg, 0)::numeric as scrap_kg
    from erp.production_machines m
    left join production pr on pr.machine_id = m.id
    left join scrap sc on sc.machine_id = m.id
    where m.is_active
      and (p_department is null or m.department = p_department)
      and (p_machine_id is null or m.id = p_machine_id)
  )
  select
    m.id,
    m.machine_code,
    m.name,
    m.department,
    mv.batch_count,
    mv.input_kg,
    mv.output_kg,
    mv.scrap_kg,
    case
      when mv.input_kg > 0 then round((mv.scrap_kg / mv.input_kg) * 100, 2)
      else 0
    end,
    erp._machine_wastage_limit_pct(
      m.machine_code,
      m.department,
      coalesce(p_to, current_date)
    )
  from machine_values mv
  join erp.production_machines m on m.id = mv.machine_id
  where mv.batch_count > 0
     or mv.input_kg > 0
     or mv.scrap_kg > 0
     or p_machine_id is not null
  order by m.department, m.sort_order, m.machine_code;
$$;


ALTER FUNCTION "erp"."fn_machine_production_summary"("p_from" "date", "p_to" "date", "p_department" "text", "p_machine_id" "uuid") OWNER TO "postgres";

--
-- Name: fn_machine_scrap_ledger("date", "date", "text", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_machine_scrap_ledger"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_department" "text" DEFAULT NULL::"text", "p_machine_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("machine_id" "uuid", "machine_code" "text", "machine_name" "text", "department" "text", "scrap_item_code" "text", "generated_kg" numeric, "dispatched_kg" numeric, "on_hand_kg" numeric, "scrap_pct" numeric, "standard_pct" numeric, "over_limit" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with production as (
    select
      coalesce(pbl.machine_id, pb.machine_id) as machine_id,
      sum(
        case
          when pbl.line_type = 'issue'
            and coalesce(w.wh_type, '') <> 'packing_material'
            then coalesce(pbl.net_weight, 0)
          else 0
        end
      )::numeric as input_kg
    from erp.production_batches pb
    join erp.production_batch_lines pbl on pbl.production_batch_id = pb.id
    left join erp.warehouses w on w.id = pbl.warehouse_id
    where pb.status = 'posted'
      and coalesce(pbl.machine_id, pb.machine_id) is not null
      and (p_from is null or pb.batch_date >= p_from)
      and (p_to is null or pb.batch_date <= p_to)
      and (p_machine_id is null or coalesce(pbl.machine_id, pb.machine_id) = p_machine_id)
    group by coalesce(pbl.machine_id, pb.machine_id)
  ),
  scrap as (
    select
      fsl.machine_id,
      sum(fsl.net_weight)::numeric as scrap_kg
    from erp.factory_scrap_dispatch_lines fsl
    join erp.factory_scrap_dispatches fs on fs.id = fsl.dispatch_id
    where fs.status = 'posted'
      and fsl.machine_id is not null
      and (p_from is null or fs.dispatch_date >= p_from)
      and (p_to is null or fs.dispatch_date <= p_to)
      and (p_machine_id is null or fsl.machine_id = p_machine_id)
    group by fsl.machine_id
  ),
  measured as (
    select
      m.id as machine_id,
      case
        when m.department = 'drawing'
          then erp._drawing_machine_input_kg(m.id, p_from, p_to)
        else coalesce(pr.input_kg, 0)
      end::numeric as input_kg,
      coalesce(sc.scrap_kg, 0)::numeric as scrap_kg,
      erp._machine_wastage_limit_pct(
        m.machine_code,
        m.department,
        coalesce(p_to, current_date)
      )::numeric as standard_pct
    from erp.production_machines m
    left join production pr on pr.machine_id = m.id
    left join scrap sc on sc.machine_id = m.id
    where m.is_active
      and (p_department is null or m.department = p_department)
      and (p_machine_id is null or m.id = p_machine_id)
  )
  select
    m.id,
    m.machine_code,
    m.name,
    m.department,
    i.code,
    x.scrap_kg,
    x.scrap_kg,
    0::numeric,
    case
      when x.input_kg > 0 then round((x.scrap_kg / x.input_kg) * 100, 2)
      else 0
    end,
    x.standard_pct,
    case
      when x.input_kg > 0 and x.standard_pct > 0
        then (x.scrap_kg / x.input_kg) * 100 > x.standard_pct
      else false
    end
  from measured x
  join erp.production_machines m on m.id = x.machine_id
  left join erp.items i on i.id = m.scrap_item_id
  where x.scrap_kg > 0 or p_machine_id is not null
  order by m.department, m.sort_order, m.machine_code;
$$;


ALTER FUNCTION "erp"."fn_machine_scrap_ledger"("p_from" "date", "p_to" "date", "p_department" "text", "p_machine_id" "uuid") OWNER TO "postgres";

--
-- Name: fn_market_erp_context(integer); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_market_erp_context"("p_days" integer DEFAULT 7) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_days int := greatest(coalesce(p_days, 7), 1);
  v_from date := current_date - v_days;
  v_avg_scrap numeric;
  v_min_scrap numeric;
  v_max_scrap numeric;
  v_cnt int;
  v_avg_lot numeric;
  v_implied numeric;
begin
  v_implied := erp._market_implied_pkr_per_kg();

  select
    coalesce(avg(si.ref_scrap_rate), 0),
    coalesce(min(si.ref_scrap_rate), 0),
    coalesce(max(si.ref_scrap_rate), 0),
    count(*)::int
  into v_avg_scrap, v_min_scrap, v_max_scrap, v_cnt
  from erp.sales_invoices si
  where coalesce(si.sale_mode, 'direct') = 'premium'
    and coalesce(si.ref_scrap_rate, 0) > 0
    and si.invoice_date >= v_from;

  select coalesce(avg(spl.unit_rate), 0) into v_avg_lot
  from erp.scrap_payable_lots spl
  where spl.lot_date >= v_from
    and coalesce(spl.unit_rate, 0) > 0;

  return jsonb_build_object(
    'days', v_days,
    'implied_pkr_per_kg', v_implied,
    'premium_ref_scrap_avg', round(v_avg_scrap, 3),
    'premium_ref_scrap_min', round(v_min_scrap, 3),
    'premium_ref_scrap_max', round(v_max_scrap, 3),
    'premium_invoice_count', v_cnt,
    'avg_scrap_lot_rate', round(v_avg_lot, 3),
    'spread_vs_implied', case when v_implied > 0 and v_avg_scrap > 0
      then round(v_avg_scrap - v_implied, 3) else null end,
    'suggested_ref_scrap_low', case when v_implied > 0
      then round(greatest(v_implied * 0.98, 0), 0) else round(v_avg_scrap, 0) end,
    'suggested_ref_scrap_high', case when v_implied > 0
      then round(v_implied * 1.02, 0) else round(v_avg_scrap, 0) end
  );
end;
$$;


ALTER FUNCTION "erp"."fn_market_erp_context"("p_days" integer) OWNER TO "postgres";

