--
-- Name: fn_market_insert_brief("date", "text", "text", "text", "jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_market_insert_brief"("p_brief_date" "date", "p_content_md" "text", "p_signal" "text", "p_model" "text", "p_snapshot" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  insert into erp.market_briefs (brief_date, content_md, signal, model, input_snapshot)
  values (coalesce(p_brief_date, current_date), p_content_md, p_signal, p_model, p_snapshot)
  on conflict (brief_date) do update set
    content_md = excluded.content_md,
    signal = excluded.signal,
    model = excluded.model,
    input_snapshot = excluded.input_snapshot,
    created_at = now()
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "erp"."fn_market_insert_brief"("p_brief_date" "date", "p_content_md" "text", "p_signal" "text", "p_model" "text", "p_snapshot" "jsonb") OWNER TO "postgres";

--
-- Name: fn_market_insert_quote("text", numeric, "text", "text", "jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_market_insert_quote"("p_symbol" "text", "p_value" numeric, "p_currency" "text" DEFAULT 'USD'::"text", "p_source" "text" DEFAULT 'api'::"text", "p_raw" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_prev numeric;
  v_chg numeric;
  v_id uuid;
begin
  select value into v_prev
  from erp.market_quotes
  where symbol_code = p_symbol
    and quoted_at < now() - interval '20 hours'
  order by quoted_at desc
  limit 1;

  if v_prev is not null and v_prev <> 0 then
    v_chg := round(((p_value - v_prev) / v_prev) * 100.0, 4);
  end if;

  insert into erp.market_quotes (symbol_code, value, currency, source, change_1d_pct, raw)
  values (p_symbol, p_value, coalesce(p_currency, 'USD'), coalesce(p_source, 'api'), v_chg, p_raw)
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "erp"."fn_market_insert_quote"("p_symbol" "text", "p_value" numeric, "p_currency" "text", "p_source" "text", "p_raw" "jsonb") OWNER TO "postgres";

