--
-- Name: fn_market_latest_quotes(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_market_latest_quotes"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_result jsonb := '[]'::jsonb;
  v_sym record;
  v_q erp.market_quotes%rowtype;
  v_implied numeric;
  v_manual numeric;
begin
  v_implied := erp._market_implied_pkr_per_kg();

  for v_sym in
    select * from erp.market_symbols where is_active order by sort_order
  loop
    if v_sym.code = 'IMPLIED_COPPER_PKR_KG' then
      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'code', v_sym.code,
        'label', v_sym.label,
        'unit', v_sym.unit,
        'value', v_implied,
        'currency', 'PKR',
        'source', 'derived',
        'quoted_at', now(),
        'change_1d_pct', null
      ));
      continue;
    end if;

    select * into v_q from erp._market_latest_quote(v_sym.code);

    if v_sym.code = 'LOCAL_SCRAP_PKR_KG' and v_q.id is null then
      select m.value into v_manual
      from erp.market_manual_overrides m
      where m.symbol_code = 'LOCAL_SCRAP_PKR_KG'
        and m.effective_from <= current_date
      order by m.effective_from desc
      limit 1;
      if v_manual is not null then
        v_result := v_result || jsonb_build_array(jsonb_build_object(
          'code', v_sym.code,
          'label', v_sym.label,
          'unit', v_sym.unit,
          'value', v_manual,
          'currency', 'PKR',
          'source', 'manual',
          'quoted_at', now(),
          'change_1d_pct', null
        ));
      end if;
      continue;
    end if;

    if v_q.id is not null then
      v_result := v_result || jsonb_build_array(jsonb_build_object(
        'code', v_sym.code,
        'label', v_sym.label,
        'unit', v_sym.unit,
        'value', v_q.value,
        'currency', v_q.currency,
        'source', v_q.source,
        'quoted_at', v_q.quoted_at,
        'change_1d_pct', v_q.change_1d_pct
      ));
    end if;
  end loop;

  return v_result;
end;
$$;


ALTER FUNCTION "erp"."fn_market_latest_quotes"() OWNER TO "postgres";

--
-- Name: fn_market_quote_history("text", integer); Type: FUNCTION; Schema: erp; Owner: postgres
