CREATE FUNCTION "erp"."fn_market_quote_history"("p_symbol" "text", "p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'quoted_at', q.quoted_at,
    'value', q.value,
    'change_1d_pct', q.change_1d_pct
  ) order by q.quoted_at), '[]'::jsonb)
  from erp.market_quotes q
  where q.symbol_code = p_symbol
    and q.quoted_at >= now() - make_interval(days => greatest(coalesce(p_days, 30), 1));
$$;


