--
-- Name: fn_market_update_settings(numeric, numeric, boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_market_update_settings"("p_conversion_factor" numeric DEFAULT NULL::numeric, "p_local_premium_pkr" numeric DEFAULT NULL::numeric, "p_ai_brief_enabled" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if not erp.has_role('ADMIN') then
    raise exception 'Admin only';
  end if;
  update erp.market_settings set
    conversion_factor = coalesce(p_conversion_factor, conversion_factor),
    local_premium_pkr = coalesce(p_local_premium_pkr, local_premium_pkr),
    ai_brief_enabled = coalesce(p_ai_brief_enabled, ai_brief_enabled),
    updated_at = now()
  where id = 1;
  return erp.fn_market_get_settings();
end;
$$;


