--
-- Name: fn_market_upsert_manual_override("text", numeric, "date", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_market_upsert_manual_override"("p_symbol_code" "text", "p_value" numeric, "p_effective_from" "date" DEFAULT CURRENT_DATE, "p_remarks" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  if not erp.has_role('ADMIN') then
    raise exception 'Admin only';
  end if;
  if coalesce(p_value, 0) <= 0 then
    raise exception 'Value must be positive';
  end if;

  insert into erp.market_manual_overrides (symbol_code, value, effective_from, remarks, created_by)
  values (p_symbol_code, p_value, coalesce(p_effective_from, current_date), p_remarks, auth.uid())
  returning id into v_id;

  insert into erp.market_quotes (symbol_code, quoted_at, value, currency, source, raw)
  values (
    p_symbol_code,
    now(),
    p_value,
    'PKR',
    'manual',
    jsonb_build_object('override_id', v_id)
  );

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$$;


