--
-- Name: fn_next_document_no("text", "text", "text", integer); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_next_document_no"("p_table" "text", "p_column" "text", "p_prefix" "text", "p_pad" integer DEFAULT 3) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $_$
declare
  v_allowed text[] := array[
    'sales_invoices.invoice_no',
    'purchase_invoices.invoice_no',
    'sales_orders.order_no',
    'purchase_orders.order_no',
    'sales_returns.return_no',
    'purchase_returns.return_no',
    'payments.payment_no',
    'parchi_instruments.parchi_no'
  ];
  v_key text := p_table || '.' || p_column;
  v_pattern text := '^' || regexp_replace(p_prefix, '([.*+?^${}()|[\]\\])', '\\\1', 'g') || '([0-9]+)$';
  v_max int;
  v_sql text;
begin
  if not (v_key = any (v_allowed)) then
    raise exception 'document number allocation not allowed for %', v_key;
  end if;

  v_sql := format(
    'select coalesce(max(nullif((regexp_match(%1$I, %2$L))[1], '''')::int), 0)
       from erp.%3$I
      where %1$I ilike %4$L',
    p_column,
    v_pattern,
    p_table,
    p_prefix || '%'
  );
  execute v_sql into v_max;

  return p_prefix || lpad((coalesce(v_max, 0) + 1)::text, greatest(coalesce(p_pad, 3), 1), '0');
end;
$_$;


ALTER FUNCTION "erp"."fn_next_document_no"("p_table" "text", "p_column" "text", "p_prefix" "text", "p_pad" integer) OWNER TO "postgres";

--
-- Name: fn_party_balance_for_code("text", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_party_balance_for_code"("p_code" "text", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("party_code" "text", "party_name" "text", "party_type" "text", "city" "text", "credit_limit" numeric, "opening_fin" numeric, "opening_metal" numeric, "fin_balance_pkr" numeric, "metal_balance_kg" numeric, "open_ar" numeric, "open_ap" numeric, "last_txn_date" "date", "status" "text", "metal_tag" "text", "credit_limit_used_pct" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select b.*
  from erp.fn_party_balance_snapshot(p_as_of) b
  where b.party_code ilike p_code
     or b.party_name ilike '%' || p_code || '%'
  order by case when b.party_code ilike p_code then 0 else 1 end, b.party_name
  limit 1;
$$;


ALTER FUNCTION "erp"."fn_party_balance_for_code"("p_code" "text", "p_as_of" "date") OWNER TO "postgres";

--
-- Name: fn_party_balance_snapshot("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_party_balance_snapshot"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("party_code" "text", "party_name" "text", "party_type" "text", "city" "text", "credit_limit" numeric, "opening_fin" numeric, "opening_metal" numeric, "fin_balance_pkr" numeric, "metal_balance_kg" numeric, "open_ar" numeric, "open_ap" numeric, "last_txn_date" "date", "status" "text", "metal_tag" "text", "credit_limit_used_pct" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with fin as (
    select p.id as party_id,
      coalesce(sum(case when jl.account_code in ('11201', '21101') then jl.debit_amount - jl.credit_amount else 0 end), 0)::numeric as fin_movement
    from erp.parties p
    left join erp.journal_lines jl on jl.party_id = p.id
    left join erp.journal_entries je on je.id = jl.journal_entry_id
    where p.is_active = true and (je.id is null or (je.posting_date <= p_as_of and coalesce(je.voucher_no, '') not like 'VOID-%' and jl.account_code in ('11201', '21101') and not erp._ledger_is_voided(je.source_doc_type, je.source_doc_id, je.voucher_no)))
    group by p.id
  ),
  metal as (
    select p.id as party_id,
      coalesce(sum(coalesce(im.qty_in, 0) - coalesce(im.qty_out, 0)), 0)::numeric as metal_movement
    from erp.parties p
    left join erp.inventory_movements im on im.party_id = p.id
      and im.movement_type in ('purchase_in','purchase_return_out','sales_out','sales_return_in','scrap_out','scrap_in','opening')
      and coalesce(im.source_doc_type, '') <> 'party_opening'
      and im.posting_date <= p_as_of
    where p.is_active = true
    group by p.id
  ),
  ar as (select ad.party_id, coalesce(sum(ad.open_amount), 0)::numeric as open_ar_total from erp.ar_documents ad where ad.status in ('open','partially_settled') and coalesce(ad.open_amount, 0) > 0 and ad.doc_date <= p_as_of group by ad.party_id),
  ap as (select ad.party_id, coalesce(sum(ad.open_amount), 0)::numeric as open_ap_total from erp.ap_documents ad where ad.status in ('open','partially_settled') and coalesce(ad.open_amount, 0) > 0 and ad.doc_date <= p_as_of group by ad.party_id),
  last_je as (select jl.party_id, max(je.posting_date) as max_date from erp.journal_lines jl join erp.journal_entries je on je.id = jl.journal_entry_id where jl.party_id is not null and je.posting_date <= p_as_of group by jl.party_id),
  last_im as (select party_id, max(posting_date) as max_date from erp.inventory_movements where party_id is not null and coalesce(source_doc_type, '') <> 'party_opening' and posting_date <= p_as_of group by party_id)
  select p.code, p.name, p.party_type, p.city, coalesce(p.credit_limit, 0)::numeric,
    coalesce(p.opening_fin_balance, 0)::numeric, coalesce(p.opening_metal_balance, 0)::numeric,
    coalesce(fin.fin_movement, 0)::numeric,
    (coalesce(p.opening_metal_balance, 0) + coalesce(metal.metal_movement, 0))::numeric,
    coalesce(ar.open_ar_total, 0)::numeric, coalesce(ap.open_ap_total, 0)::numeric,
    greatest(coalesce(last_je.max_date, '1900-01-01'::date), coalesce(last_im.max_date, '1900-01-01'::date)),
    case when coalesce(fin.fin_movement, 0) > 0.5 then 'Receivable' when coalesce(fin.fin_movement, 0) < -0.5 then 'Payable' else 'Settled' end,
    case when abs(coalesce(p.opening_metal_balance, 0) + coalesce(metal.metal_movement, 0)) > 0.001 then 'Metal Open' else 'Metal Clear' end,
    case when coalesce(p.credit_limit, 0) > 0 then round(coalesce(ar.open_ar_total, 0) / p.credit_limit * 100, 2) else null end
  from erp.parties p
  left join fin on fin.party_id = p.id left join metal on metal.party_id = p.id
  left join ar on ar.party_id = p.id left join ap on ap.party_id = p.id
  left join last_je on last_je.party_id = p.id left join last_im on last_im.party_id = p.id
  where p.is_active = true order by p.code;
$$;


ALTER FUNCTION "erp"."fn_party_balance_snapshot"("p_as_of" "date") OWNER TO "postgres";

--
-- Name: fn_party_ledger("text", "date", "date", integer, integer); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_party_ledger"("p_party_code" "text" DEFAULT NULL::"text", "p_from" "date" DEFAULT '1900-01-01'::"date", "p_to" "date" DEFAULT CURRENT_DATE, "p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0) RETURNS TABLE("party_code" "text", "party_name" "text", "posting_date" "date", "voucher_no" "text", "voucher_type" "text", "source_doc_type" "text", "source_doc_id" "uuid", "source_doc_no" "text", "ref_no" "text", "account_code" "text", "account_name" "text", "line_description" "text", "transaction_description" "text", "narration" "text", "particulars" "text", "size_spec" "text", "weight_qty" numeric, "unit_rate" numeric, "detail_seq" integer, "debit_amount" numeric, "credit_amount" numeric, "running_balance" numeric, "posted_at" timestamp with time zone, "posted_by" "uuid", "posted_by_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_party_id uuid;
  v_party_name text;
begin
  if p_party_code is not null then
    select id, name into v_party_id, v_party_name
    from erp.parties where code = p_party_code;
    if v_party_id is null then return; end if;

    return query
    with opening_as_of as (
      select (
        coalesce((
          select sum(jl.debit_amount - jl.credit_amount)
          from erp.journal_lines jl
          join erp.journal_entries je on je.id = jl.journal_entry_id
          where jl.party_id = v_party_id
            and jl.account_code = any(erp._party_fin_subledger_codes())
            and je.source_doc_type = 'party_opening'
            and coalesce(je.voucher_no, '') not like 'VOID-%'
            and not erp._ledger_is_voided(je.source_doc_type, je.source_doc_id, je.voucher_no)
        ), 0)
        + case
            when not exists (
              select 1
              from erp.journal_lines jl2
              join erp.journal_entries je2 on je2.id = jl2.journal_entry_id
              where jl2.party_id = v_party_id
                and jl2.account_code = any(erp._party_fin_subledger_codes())
                and je2.source_doc_type = 'party_opening'
            ) then coalesce((select opening_fin_balance from erp.parties where id = v_party_id), 0)
            else 0
          end
        + coalesce((
          select sum(jl.debit_amount - jl.credit_amount)
          from erp.journal_lines jl
          join erp.journal_entries je on je.id = jl.journal_entry_id
          where jl.party_id = v_party_id
            and jl.account_code = any(erp._party_fin_subledger_codes())
            and je.posting_date < p_from
            and coalesce(je.source_doc_type, '') <> 'party_opening'
            and coalesce(je.voucher_no, '') not like 'VOID-%'
            and not erp._ledger_is_voided(je.source_doc_type, je.source_doc_id, je.voucher_no)
        ), 0)
      )::numeric as bal
    ),
    journal_rows as (
      select
        p.code::text as party_code,
        p.name::text as party_name,
        je.posting_date,
        je.voucher_no::text,
        je.voucher_type::text,
        je.source_doc_type::text,
        je.source_doc_id,
        je.source_doc_no::text,
        erp._ledger_ref_no(je.source_doc_type, je.source_doc_no, je.voucher_no)::text as ref_no,
        jl.account_code::text,
        jl.account_name::text,
        jl.line_description::text,
        erp._ledger_transaction_description(
          je.source_doc_type, je.voucher_type, jl.line_description, pay.payment_type
        )::text as transaction_description,
        je.narration::text,
        jl.debit_amount,
        jl.credit_amount,
        je.id as je_id,
        jl.line_no as je_line_no,
        je.posted_at,
        je.posted_by,
        erp._audit_actor_name(je.posted_by) as posted_by_name
      from erp.journal_lines jl
      join erp.journal_entries je on je.id = jl.journal_entry_id
      join erp.parties p on p.id = jl.party_id
      left join erp.payments pay on je.source_doc_type = 'payment' and pay.id = je.source_doc_id
      where p.id = v_party_id
        and jl.account_code = any(erp._party_fin_subledger_codes())
        and je.posting_date between p_from and p_to
        and coalesce(je.source_doc_type, '') <> 'party_opening'
        and coalesce(je.voucher_no, '') not like 'VOID-%'
        and not erp._ledger_is_voided(je.source_doc_type, je.source_doc_id, je.voucher_no)
        and not erp._ledger_is_watta_party_adj_hidden(je.voucher_type, jl.line_description, je.narration)
    ),
    expanded_raw as (
      select
        jr.*,
        coalesce(d.detail_seq, 1) as detail_seq,
        coalesce(d.particulars, jr.line_description, jr.narration) as particulars,
        d.size_spec,
        d.weight_qty,
        d.unit_rate,
        coalesce(
          d.line_amount,
          case when d.weight_qty is not null and d.unit_rate is not null then round(d.weight_qty * d.unit_rate, 3) else null end
        ) as raw_line_amount,
        erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type) as should_expand
      from journal_rows jr
      left join lateral (
        select ld.*
        from erp._ledger_line_details(
          case when erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type) then jr.source_doc_type end,
          case when erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type) then jr.source_doc_id end
        ) ld
        where erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type)
      ) d on true
    ),
    expanded as (
      select
        r.*,
        case
          when r.should_expand and coalesce(r.raw_line_amount, 0) > 0 then r.raw_line_amount
          when not r.should_expand and r.detail_seq = 1 then
            case when r.debit_amount > 0 then r.debit_amount when r.credit_amount > 0 then r.credit_amount else 0 end
          else 0
        end as alloc_amount
      from expanded_raw r
      where not (
        r.should_expand
        and coalesce(r.raw_line_amount, 0) = 0
        and coalesce(r.weight_qty, 0) > 0
        and coalesce(r.particulars, '') like 'Rate pending%'
      )
    ),
    expanded_final as (
      select
        e.party_code, e.party_name, e.posting_date, e.voucher_no, e.voucher_type,
        e.source_doc_type, e.source_doc_id, e.source_doc_no, e.ref_no,
        e.account_code, e.account_name, e.line_description, e.transaction_description,
        e.narration, e.particulars, e.size_spec, e.weight_qty, e.unit_rate, e.detail_seq,
        case when e.debit_amount > 0 then e.alloc_amount else 0 end as display_debit,
        case when e.credit_amount > 0 then e.alloc_amount else 0 end as display_credit,
        case when e.debit_amount > 0 then e.alloc_amount when e.credit_amount > 0 then -e.alloc_amount else 0 end as display_delta,
        coalesce(e.posted_at, e.posting_date::timestamptz) as sort_ts,
        e.je_id,
        e.je_line_no,
        e.posted_at, e.posted_by, e.posted_by_name
      from expanded e
    ),
    pending_period as (
      select
        pr.party_code, pr.party_name, pr.posting_date, pr.voucher_no, pr.voucher_type,
        pr.source_doc_type, pr.source_doc_id, pr.source_doc_no, pr.ref_no,
        pr.account_code, pr.account_name, pr.line_description, pr.transaction_description,
        pr.narration, pr.particulars, pr.size_spec, pr.weight_qty, pr.unit_rate, pr.detail_seq,
        pr.display_debit, pr.display_credit, pr.display_delta,
        pr.sort_ts,
        null::uuid as je_id,
        0 as je_line_no,
        pr.posted_at, pr.posted_by, pr.posted_by_name
      from erp._ledger_pending_rate_party_rows(v_party_id, p_from, p_to, true) pr
    ),
    period_combined as (
      select * from expanded_final
      union all
      select * from pending_period
    ),
    opening_row as (
      select
        p_party_code::text as party_code,
        v_party_name::text as party_name,
        p_from as posting_date,
        'OPENING'::text as voucher_no,
        'OPENING'::text as voucher_type,
        'opening'::text as source_doc_type,
        null::uuid as source_doc_id,
        null::text as source_doc_no,
        'B/F'::text as ref_no,
        null::text as account_code,
        null::text as account_name,
        'Balance brought forward'::text as line_description,
        'Balance brought forward'::text as transaction_description,
        null::text as narration,
        'Balance brought forward'::text as particulars,
        null::text as size_spec,
        null::numeric as weight_qty,
        null::numeric as unit_rate,
        1 as detail_seq,
        0::numeric as display_debit,
        0::numeric as display_credit,
        ob.bal as display_delta,
        0::bigint as rn,
        null::timestamptz as posted_at,
        null::uuid as posted_by,
        null::text as posted_by_name
      from opening_as_of ob
    ),
    period_rows as (
      select
        pc.party_code, pc.party_name, pc.posting_date, pc.voucher_no, pc.voucher_type,
        pc.source_doc_type, pc.source_doc_id, pc.source_doc_no, pc.ref_no,
        pc.account_code, pc.account_name, pc.line_description, pc.transaction_description,
        pc.narration, pc.particulars, pc.size_spec, pc.weight_qty, pc.unit_rate, pc.detail_seq,
        pc.display_debit, pc.display_credit, pc.display_delta,
        row_number() over (
          order by pc.sort_ts, pc.je_id nulls last, pc.je_line_no, pc.detail_seq
        ) as rn,
        pc.posted_at, pc.posted_by, pc.posted_by_name
      from period_combined pc
    ),
    all_rows as (
      select * from opening_row
      union all
      select
        pr.party_code, pr.party_name, pr.posting_date, pr.voucher_no, pr.voucher_type,
        pr.source_doc_type, pr.source_doc_id, pr.source_doc_no, pr.ref_no,
        pr.account_code, pr.account_name, pr.line_description, pr.transaction_description,
        pr.narration, pr.particulars, pr.size_spec, pr.weight_qty, pr.unit_rate, pr.detail_seq,
        pr.display_debit, pr.display_credit, pr.display_delta, pr.rn,
        pr.posted_at, pr.posted_by, pr.posted_by_name
      from period_rows pr
    )
    select
      numbered.party_code, numbered.party_name, numbered.posting_date, numbered.voucher_no, numbered.voucher_type,
      numbered.source_doc_type, numbered.source_doc_id, numbered.source_doc_no, numbered.ref_no,
      numbered.account_code, numbered.account_name, numbered.line_description, numbered.transaction_description,
      numbered.narration, numbered.particulars, numbered.size_spec, numbered.weight_qty, numbered.unit_rate, numbered.detail_seq,
      numbered.debit_amount, numbered.credit_amount, numbered.running_balance,
      numbered.posted_at, numbered.posted_by, numbered.posted_by_name
    from (
      select
        ar.party_code, ar.party_name, ar.posting_date, ar.voucher_no, ar.voucher_type,
        ar.source_doc_type, ar.source_doc_id, ar.source_doc_no, ar.ref_no,
        ar.account_code, ar.account_name, ar.line_description, ar.transaction_description,
        ar.narration, ar.particulars, ar.size_spec, ar.weight_qty, ar.unit_rate, ar.detail_seq,
        ar.display_debit as debit_amount, ar.display_credit as credit_amount,
        sum(ar.display_delta) over (order by ar.rn) as running_balance,
        ar.rn,
        ar.posted_at, ar.posted_by, ar.posted_by_name
      from all_rows ar
    ) numbered
    order by numbered.rn
    limit p_limit
    offset greatest(coalesce(p_offset, 0), 0);

  else
    return query
    with journal_rows as (
      select
        p.code::text as party_code,
        p.name::text as party_name,
        je.posting_date,
        je.voucher_no::text,
        je.voucher_type::text,
        je.source_doc_type::text,
        je.source_doc_id,
        je.source_doc_no::text,
        erp._ledger_ref_no(je.source_doc_type, je.source_doc_no, je.voucher_no)::text as ref_no,
        jl.account_code::text,
        jl.account_name::text,
        jl.line_description::text,
        erp._ledger_transaction_description(
          je.source_doc_type, je.voucher_type, jl.line_description, pay.payment_type
        )::text as transaction_description,
        je.narration::text,
        jl.debit_amount,
        jl.credit_amount,
        je.id as je_id,
        jl.line_no as je_line_no,
        je.posted_at,
        je.posted_by,
        erp._audit_actor_name(je.posted_by) as posted_by_name
      from erp.journal_lines jl
      join erp.journal_entries je on je.id = jl.journal_entry_id
      join erp.parties p on p.id = jl.party_id
      left join erp.payments pay on je.source_doc_type = 'payment' and pay.id = je.source_doc_id
      where jl.account_code = any(erp._party_fin_subledger_codes())
        and je.posting_date between p_from and p_to
        and coalesce(je.voucher_no, '') not like 'VOID-%'
        and not erp._ledger_is_voided(je.source_doc_type, je.source_doc_id, je.voucher_no)
        and not erp._ledger_is_watta_party_adj_hidden(je.voucher_type, jl.line_description, je.narration)
    ),
    expanded_raw as (
      select
        jr.*,
        coalesce(d.detail_seq, 1) as detail_seq,
        coalesce(d.particulars, jr.line_description, jr.narration) as particulars,
        d.size_spec,
        d.weight_qty,
        d.unit_rate,
        coalesce(
          d.line_amount,
          case when d.weight_qty is not null and d.unit_rate is not null then round(d.weight_qty * d.unit_rate, 3) else null end
        ) as raw_line_amount,
        erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type) as should_expand
      from journal_rows jr
      left join lateral (
        select ld.*
        from erp._ledger_line_details(
          case when erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type) then jr.source_doc_type end,
          case when erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type) then jr.source_doc_id end
        ) ld
        where erp._ledger_should_expand_details(jr.voucher_type, jr.source_doc_type)
      ) d on true
    ),
    expanded as (
      select
        r.party_code, r.party_name, r.posting_date, r.voucher_no, r.voucher_type,
        r.source_doc_type, r.source_doc_id, r.source_doc_no, r.ref_no,
        r.account_code, r.account_name, r.line_description, r.transaction_description,
        r.narration, r.particulars, r.size_spec, r.weight_qty, r.unit_rate, r.detail_seq,
        case when r.debit_amount > 0 then r.alloc_amount else 0 end as display_debit,
        case when r.credit_amount > 0 then r.alloc_amount else 0 end as display_credit,
        r.posted_at, r.posted_by, r.posted_by_name,
        coalesce(r.posted_at, r.posting_date::timestamptz) as sort_ts,
        r.je_id, r.je_line_no
      from (
        select
          r.*,
          case
            when r.should_expand and coalesce(r.raw_line_amount, 0) > 0 then r.raw_line_amount
            when not r.should_expand and r.detail_seq = 1 then
              case when r.debit_amount > 0 then r.debit_amount when r.credit_amount > 0 then r.credit_amount else 0 end
            else 0
          end as alloc_amount
        from expanded_raw r
        where not (
          r.should_expand
          and coalesce(r.raw_line_amount, 0) = 0
          and coalesce(r.weight_qty, 0) > 0
          and coalesce(r.particulars, '') like 'Rate pending%'
        )
      ) r
    ),
    pending_expanded as (
      select
        pr.party_code, pr.party_name, pr.posting_date, pr.voucher_no, pr.voucher_type,
        pr.source_doc_type, pr.source_doc_id, pr.source_doc_no, pr.ref_no,
        pr.account_code, pr.account_name, pr.line_description, pr.transaction_description,
        pr.narration, pr.particulars, pr.size_spec, pr.weight_qty, pr.unit_rate, pr.detail_seq,
        pr.display_debit, pr.display_credit,
        pr.posted_at, pr.posted_by, pr.posted_by_name,
        pr.sort_ts,
        null::uuid as je_id,
        0 as je_line_no
      from erp._ledger_pending_rate_party_rows(null, p_from, p_to, false) pr
    )
    select
      numbered.party_code, numbered.party_name, numbered.posting_date, numbered.voucher_no, numbered.voucher_type,
      numbered.source_doc_type, numbered.source_doc_id, numbered.source_doc_no, numbered.ref_no,
      numbered.account_code, numbered.account_name, numbered.line_description, numbered.transaction_description,
      numbered.narration, numbered.particulars, numbered.size_spec, numbered.weight_qty, numbered.unit_rate, numbered.detail_seq,
      numbered.debit_amount, numbered.credit_amount, numbered.running_balance,
      numbered.posted_at, numbered.posted_by, numbered.posted_by_name
    from (
      select
        u.party_code, u.party_name, u.posting_date, u.voucher_no, u.voucher_type,
        u.source_doc_type, u.source_doc_id, u.source_doc_no, u.ref_no,
        u.account_code, u.account_name, u.line_description, u.transaction_description,
        u.narration, u.particulars, u.size_spec, u.weight_qty, u.unit_rate, u.detail_seq,
        u.display_debit as debit_amount, u.display_credit as credit_amount,
        null::numeric as running_balance,
        u.posted_at, u.posted_by, u.posted_by_name,
        row_number() over (order by u.sort_ts, u.je_id nulls last, u.je_line_no, u.detail_seq) as rn
      from (
        select * from expanded
        union all
        select * from pending_expanded
      ) u
    ) numbered
    order by numbered.rn
    limit p_limit
    offset greatest(coalesce(p_offset, 0), 0);
  end if;
end;
$$;


ALTER FUNCTION "erp"."fn_party_ledger"("p_party_code" "text", "p_from" "date", "p_to" "date", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";

--
-- Name: fn_party_metal_ledger("text", "date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_party_metal_ledger"("p_party_code" "text" DEFAULT NULL::"text", "p_from" "date" DEFAULT '1900-01-01'::"date", "p_to" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("party_code" "text", "party_name" "text", "posting_date" "date", "source_doc_type" "text", "reference_no" "text", "item_name" "text", "size_spec" "text", "description" "text", "weight_in" numeric, "weight_out" numeric, "running_kg" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_party_id uuid;
begin
  if p_party_code is not null then
    select id into v_party_id from erp.parties where code = p_party_code;
    if v_party_id is null then return; end if;
    return query
    with opening_as_of as (
      select (
        coalesce((
          select sum(coalesce(im.qty_in, 0) - coalesce(im.qty_out, 0))
          from erp.inventory_movements im
          where im.party_id = v_party_id
            and im.posting_date < p_from
            and im.movement_type in (
              'purchase_in', 'purchase_return_out', 'sales_out', 'sales_return_in',
              'scrap_out', 'scrap_in', 'opening'
            )
        ), 0)
        + case
            when not exists (
              select 1
              from erp.inventory_movements im2
              where im2.party_id = v_party_id
                and im2.source_doc_type = 'party_opening'
            ) then coalesce((select opening_metal_balance from erp.parties where id = v_party_id), 0)
            else 0
          end
      )::numeric as bal
    ),
    period_rows as (
      select v.party_code as pc, v.party_name as pn, v.posting_date as pd, v.source_doc_type as sdt,
        v.reference_no as refno, v.item_name as iname, v.size_spec as ss,
        coalesce(v.item_name, initcap(replace(v.source_doc_type, '_', ' '))) as descr,
        v.weight_in as wi, v.weight_out as wo, (v.weight_in - v.weight_out) as delta,
        row_number() over (order by v.posting_date, v.source_doc_type, v.reference_no) as rn
      from erp.v_party_metal_ledger v
      where v.party_code = p_party_code and v.posting_date between p_from and p_to
        and coalesce(v.source_doc_type, '') <> 'party_opening'
    ),
    opening_row as (
      select p_party_code::text as pc, (select name from erp.parties where id = v_party_id)::text as pn,
        p_from as pd, 'opening'::text as sdt, 'B/F'::text as refno, null::text as iname, null::text as ss,
        'Balance brought forward'::text as descr,
        0::numeric as wi,
        0::numeric as wo,
        ob.bal as delta, 0::bigint as rn
      from opening_as_of ob
    ),
    all_rows as (
      select * from opening_row union all select * from period_rows
    )
    select r.pc, r.pn, r.pd, r.sdt, r.refno, r.iname, r.ss, r.descr, r.wi, r.wo,
      sum(r.delta) over (order by r.rn) as running_kg
    from all_rows r order by r.rn;
  else
    return query
    select v.party_code, v.party_name, v.posting_date, v.source_doc_type, v.reference_no,
      v.item_name, v.size_spec,
      coalesce(v.item_name, initcap(replace(v.source_doc_type, '_', ' '))) as description,
      v.weight_in, v.weight_out, null::numeric as running_kg
    from erp.v_party_metal_ledger v
    where v.posting_date between p_from and p_to
    order by v.posting_date, v.party_code;
  end if;
end;
$$;


ALTER FUNCTION "erp"."fn_party_metal_ledger"("p_party_code" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_party_scrap_allocation_context("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_party_scrap_allocation_context"("p_party_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_credits jsonb;
  v_obligations jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) into v_credits
  from erp.fn_party_scrap_credits_for_party(p_party_code, true) t;

  select coalesce(jsonb_agg(to_jsonb(o)), '[]'::jsonb) into v_obligations
  from (
    select
      o.id as obligation_id,
      o.obligation_no,
      o.sales_invoice_no,
      o.invoice_date,
      o.ref_scrap_rate,
      o.expected_kg,
      o.received_kg,
      greatest(o.expected_kg - o.received_kg, 0) as open_kg,
      o.status
    from erp.scrap_receivable_obligations o
    join erp.parties p on p.id = o.party_id
    where p.code = p_party_code
      and o.status <> 'cancelled'
      and greatest(o.expected_kg - o.received_kg, 0) > 0
    order by o.invoice_date, o.sales_invoice_no
  ) o;

  return jsonb_build_object('credits', v_credits, 'obligations', v_obligations);
end;
$$;


ALTER FUNCTION "erp"."fn_party_scrap_allocation_context"("p_party_code" "text") OWNER TO "postgres";

--
-- Name: fn_party_scrap_credits_for_party("text", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_party_scrap_credits_for_party"("p_party_code" "text", "p_open_only" boolean DEFAULT true) RETURNS TABLE("credit_id" "uuid", "trade_no" "text", "trade_date" "date", "credit_kg" numeric, "consumed_kg" numeric, "open_kg" numeric, "pending_reason" "text", "status" "text", "ref_scrap_rate" numeric, "source_doc_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    c.id,
    st.trade_no,
    st.trade_date,
    c.credit_kg,
    c.consumed_kg,
    greatest(c.credit_kg - c.consumed_kg, 0),
    coalesce(st.pending_reason, pri.pending_reason, 'rate'),
    c.status,
    c.ref_scrap_rate,
    c.source_doc_id
  from erp.party_scrap_credits c
  join erp.parties p on p.id = c.party_id
  join erp.scrap_trades st on st.id = c.source_doc_id and c.source_doc_type = 'scrap_trade'
  left join erp.pending_rate_items pri on pri.id = c.pending_rate_item_id
  where p.code = p_party_code
    and c.status <> 'void'
    and (not p_open_only or greatest(c.credit_kg - c.consumed_kg, 0) > 0)
  order by st.trade_date, st.trade_no;
$$;


ALTER FUNCTION "erp"."fn_party_scrap_credits_for_party"("p_party_code" "text", "p_open_only" boolean) OWNER TO "postgres";

--
-- Name: fn_party_scrap_expectations("text", "date", "date", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_party_scrap_expectations"("p_party_code" "text" DEFAULT NULL::"text", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_open_only" boolean DEFAULT true) RETURNS TABLE("party_code" "text", "party_name" "text", "obligation_no" "text", "sales_invoice_no" "text", "invoice_date" "date", "ref_scrap_rate" numeric, "expected_kg" numeric, "received_kg" numeric, "open_kg" numeric, "status" "text", "obligation_source" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    p.code,
    p.name,
    o.obligation_no,
    o.sales_invoice_no,
    o.invoice_date,
    o.ref_scrap_rate,
    o.expected_kg,
    o.received_kg,
    greatest(o.expected_kg - o.received_kg, 0),
    o.status,
    coalesce(o.obligation_source, 'invoice')::text
  from erp.scrap_receivable_obligations o
  join erp.parties p on p.id = o.party_id
  where o.status <> 'cancelled'
    and (p_party_code is null or p.code = p_party_code)
    and (
      (p_open_only and greatest(o.expected_kg - o.received_kg, 0) > 0)
      or (
        not p_open_only
        and (p_from is null or o.invoice_date >= p_from)
        and (p_to is null or o.invoice_date <= p_to)
      )
    )
  order by
    case when o.obligation_source = 'opening' then 0 else 1 end,
    o.invoice_date desc,
    o.sales_invoice_no desc;
$$;


ALTER FUNCTION "erp"."fn_party_scrap_expectations"("p_party_code" "text", "p_from" "date", "p_to" "date", "p_open_only" boolean) OWNER TO "postgres";

--
-- Name: fn_party_stock_movement("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_party_stock_movement"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("party_code" "text", "party_name" "text", "movement_type" "text", "posting_date" "date", "item_code" "text", "inventory_group" "text", "item_type" "text", "source_doc_no" "text", "qty_in" numeric, "qty_out" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    p.code,
    p.name,
    im.movement_type,
    im.posting_date,
    i.code,
    i.inventory_group,
    i.item_type,
    coalesce(
      nullif(trim(im.reference_no), ''),
      si.invoice_no,
      pi.invoice_no,
      sr.return_no,
      pr.return_no,
      st.trade_no,
      scr.receipt_no
    ) as source_doc_no,
    coalesce(im.qty_in, 0),
    coalesce(im.qty_out, 0)
  from erp.inventory_movements im
  join erp.parties p on p.id = im.party_id
  join erp.items i on i.id = im.item_id
  left join erp.sales_invoices si on im.source_doc_type = 'sales_invoice' and si.id = im.source_doc_id
  left join erp.purchase_invoices pi on im.source_doc_type = 'purchase_invoice' and pi.id = im.source_doc_id
  left join erp.sales_returns sr on im.source_doc_type = 'sales_return' and sr.id = im.source_doc_id
  left join erp.purchase_returns pr on im.source_doc_type = 'purchase_return' and pr.id = im.source_doc_id
  left join erp.scrap_trades st on im.source_doc_type = 'scrap_trade' and st.id = im.source_doc_id
  left join erp.scrap_receipts scr on im.source_doc_type = 'scrap_receipt' and scr.id = im.source_doc_id
  where im.party_id is not null
    and im.movement_type in (
      'purchase_in',
      'purchase_return_out',
      'sales_out',
      'sales_return_in',
      'scrap_out',
      'scrap_in'
    )
    and (p_from is null or im.posting_date >= p_from)
    and (p_to is null or im.posting_date <= p_to)
  order by im.posting_date desc, p.code, i.code
$$;


ALTER FUNCTION "erp"."fn_party_stock_movement"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_pending_rate_alerts(integer); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_pending_rate_alerts"("p_days" integer DEFAULT 3) RETURNS TABLE("alert_type" "text", "party_code" "text", "party_name" "text", "source_doc_no" "text", "qty" numeric, "days_pending" integer, "original_posting_date" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    'RATE_PENDING_STALE'::text,
    p.code,
    p.name,
    pri.source_doc_no,
    pri.qty,
    (current_date - pri.original_posting_date)::int,
    pri.original_posting_date
  from erp.pending_rate_items pri
  join erp.parties p on p.id = pri.party_id
  where pri.status = 'open'
    and (current_date - pri.original_posting_date) >= p_days
  order by pri.original_posting_date;
$$;


ALTER FUNCTION "erp"."fn_pending_rate_alerts"("p_days" integer) OWNER TO "postgres";

--
-- Name: fn_pending_rate_register("text", "date", "date", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_pending_rate_register"("p_party_code" "text" DEFAULT NULL::"text", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_open_only" boolean DEFAULT true) RETURNS TABLE("id" "uuid", "source_doc_type" "text", "source_doc_id" "uuid", "source_line_id" "uuid", "source_doc_no" "text", "line_seq" integer, "party_code" "text", "party_name" "text", "item_code" "text", "item_name" "text", "qty" numeric, "original_posting_date" "date", "days_pending" integer, "status" "text", "pending_reason" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    pri.id,
    pri.source_doc_type,
    pri.source_doc_id,
    pri.source_line_id,
    pri.source_doc_no,
    pri.line_seq,
    p.code,
    p.name,
    i.code,
    i.name,
    pri.qty,
    pri.original_posting_date,
    (current_date - pri.original_posting_date)::int,
    pri.status,
    pri.pending_reason
  from erp.pending_rate_items pri
  join erp.parties p on p.id = pri.party_id
  left join erp.items i on i.id = pri.item_id
  where (not p_open_only or pri.status = 'open')
    and (p_party_code is null or p.code = p_party_code)
    and (
      p_open_only
      or (
        (p_from is null or pri.original_posting_date >= p_from)
        and (p_to is null or pri.original_posting_date <= p_to)
      )
    )
  order by pri.original_posting_date, pri.source_doc_no, pri.line_seq;
$$;


ALTER FUNCTION "erp"."fn_pending_rate_register"("p_party_code" "text", "p_from" "date", "p_to" "date", "p_open_only" boolean) OWNER TO "postgres";

--
-- Name: fn_post_purchase_invoice_deploy_check(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_post_purchase_invoice_deploy_check"() RETURNS TABLE("check_name" "text", "status" "text", "detail" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_body text;
begin
  select pg_get_functiondef(p.oid) into v_body
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'erp' and p.proname = 'post_purchase_invoice'
  order by p.oid desc
  limit 1;

  return query select
    'post_purchase_invoice_body'::text,
    case
      when v_body is null then 'MISSING'
      when v_body ilike '%_clear_purchase_invoice_draft_posting%' then 'OK'
      when v_body ilike '%on conflict (source_doc_type, source_doc_id, party_id)%' then 'PARTIAL_87'
      when v_body ilike '%on conflict (source_doc_id)%' then 'STALE_23'
      else 'UNKNOWN'
    end,
    coalesce(left(v_body, 120), 'function not found')::text;

  return query select
    'ap_documents_unique_index'::text,
    case when exists (
      select 1 from pg_indexes
      where schemaname = 'erp' and tablename = 'ap_documents'
        and indexdef ilike '%source_doc_type%' and indexdef ilike '%party_id%'
    ) then 'OK' else 'MISSING' end,
    'Run migrations 75 and 88'::text;

  return query select
    'posting_map_purchase_invoice'::text,
    case when exists (
      select 1 from erp.posting_account_map pam
      where pam.doc_type = 'purchase_invoice' and pam.line_role = 'inventory' and pam.is_active
    ) and exists (
      select 1 from erp.posting_account_map pam
      where pam.doc_type = 'purchase_invoice' and pam.line_role = 'ap' and pam.is_active
    ) then 'OK' else 'MISSING' end,
  'Run migration 42_restore_posting_account_map'::text;
end;
$$;


ALTER FUNCTION "erp"."fn_post_purchase_invoice_deploy_check"() OWNER TO "postgres";

--
-- Name: fn_post_sales_invoice_deploy_check(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_post_sales_invoice_deploy_check"() RETURNS TABLE("check_name" "text", "status" "text", "detail" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  return query select
    'posting_map_sales_invoice_ar'::text,
    case when exists (
      select 1 from erp.posting_account_map pam
      where pam.doc_type = 'sales_invoice'
        and pam.line_role = 'ar'
        and pam.is_active
        and pam.effective_from <= current_date
    ) then 'OK' else 'MISSING' end,
    'Run migration 94_repair_sales_posting_map (or 42 / 78)'::text;

  return query select
    'posting_map_sales_invoice_inventory'::text,
    case when exists (
      select 1 from erp.posting_account_map pam
      where pam.doc_type = 'sales_invoice'
        and pam.line_role = 'inventory'
        and pam.is_active
        and pam.effective_from <= current_date
    ) then 'OK' else 'MISSING' end,
    'Requires COA 12301 or 12104'::text;

  return query select
    'resolve_sales_ar'::text,
    case
      when (
        select erp._resolve_posting_account('sales_invoice', 'ar')
      ) is not null then 'OK'
      else 'MISSING'
    end,
    'Calls _resolve_posting_account live'::text;
exception
  when others then
    return query select
      'resolve_sales_ar'::text,
      'MISSING'::text,
      sqlerrm::text;
end;
$$;


ALTER FUNCTION "erp"."fn_post_sales_invoice_deploy_check"() OWNER TO "postgres";

--
-- Name: fn_posting_map_health(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_posting_map_health"() RETURNS TABLE("doc_type" "text", "line_role" "text", "account_code" "text", "status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  r record;
  v_code text;
begin
  for r in
    select reg.doc_type, reg.line_role
    from erp.posting_map_registry reg
    where reg.is_required
    order by reg.doc_type, reg.line_role
  loop
    doc_type := r.doc_type;
    line_role := r.line_role;
    account_code := null;
    begin
      v_code := erp._resolve_posting_account(r.doc_type, r.line_role);
      account_code := v_code;
      status := 'OK';
    exception when others then
      status := 'MISSING';
    end;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "erp"."fn_posting_map_health"() OWNER TO "postgres";

