-- Name: fn_production_alerts("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_production_alerts"("p_status" "text" DEFAULT 'open'::"text") RETURNS TABLE("id" "uuid", "alert_type" "text", "severity" "text", "message" "text", "metric_value" numeric, "threshold_value" numeric, "period_start" "date", "machine_code" "text", "status" "text", "created_at" timestamp with time zone)
