--
-- Name: fn_production_detail_report("date", "date", "uuid", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_production_detail_report"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_machine_id" "uuid" DEFAULT NULL::"uuid", "p_size_spec" "text" DEFAULT NULL::"text", "p_department" "text" DEFAULT NULL::"text") RETURNS TABLE("batch_no" "text", "batch_date" "date", "machine_id" "uuid", "machine_code" "text", "machine_name" "text", "department" "text", "line_type" "text", "item_code" "text", "item_name" "text", "size_spec" "text", "net_weight" numeric, "unit_count" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    pb.batch_no,
    pb.batch_date,
    coalesce(pbl.machine_id, pb.machine_id) as machine_id,
    pm.machine_code,
    pm.name as machine_name,
    pb.process_type as department,
    pbl.line_type,
    i.code as item_code,
    i.name as item_name,
    i.size_spec,
    coalesce(pbl.net_weight, 0) as net_weight,
    coalesce(pbl.unit_count, 0) as unit_count
  from erp.production_batches pb
  join erp.production_batch_lines pbl on pbl.production_batch_id = pb.id
  left join erp.production_machines pm on pm.id = coalesce(pbl.machine_id, pb.machine_id)
  join erp.items i on i.id = pbl.item_id
  where pb.status = 'posted'
    and (p_from is null or pb.batch_date >= p_from)
    and (p_to is null or pb.batch_date <= p_to)
    and (p_machine_id is null or coalesce(pbl.machine_id, pb.machine_id) = p_machine_id)
    and (p_department is null or pb.process_type = p_department)
    and (p_size_spec is null or i.size_spec is not null and i.size_spec ilike '%' || p_size_spec || '%')
  order by pm.machine_code nulls last, pb.batch_date, pb.batch_no, pbl.line_no;
$$;


