--
-- Name: fn_profit_loss("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_profit_loss"("p_from" "date" DEFAULT ("date_trunc"('year'::"text", (CURRENT_DATE)::timestamp with time zone))::"date", "p_to" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("account_code" "text", "account_name" "text", "account_type" "text", "report_group" "text", "amount" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with jl_agg as (
    select
      jl.account_code,
      erp._infer_account_type(jl.account_code, max(ca.account_type)) as account_type,
      max(jl.account_name) as line_name,
      coalesce(sum(jl.debit_amount), 0) as total_debit,
      coalesce(sum(jl.credit_amount), 0) as total_credit
    from erp.journal_lines jl
    join erp.journal_entries je on je.id = jl.journal_entry_id
    left join erp.coa_accounts ca on ca.code = jl.account_code
    where je.posting_date between p_from and p_to
      and coalesce(je.voucher_no, '') not like 'VOID-%'
    group by jl.account_code
  )
  select
    a.account_code::text,
    erp._display_account_name(a.account_code, ca.name, a.line_name)::text as account_name,
    a.account_type::text,
    erp._infer_report_group(a.account_code, a.account_type, ca.report_group)::text as report_group,
    case
      when a.account_type = 'income'  then (a.total_credit - a.total_debit)
      when a.account_type = 'expense' then (a.total_debit - a.total_credit)
      else 0
    end::numeric as amount
  from jl_agg a
  left join erp.coa_accounts ca on ca.code = a.account_code
  where a.account_type in ('income', 'expense')
    and case
      when a.account_type = 'income'  then (a.total_credit - a.total_debit)
      when a.account_type = 'expense' then (a.total_debit - a.total_credit)
      else 0
    end <> 0
  order by a.account_type, a.account_code;
$$;


ALTER FUNCTION "erp"."fn_profit_loss"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_profit_loss_periodic("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_profit_loss_periodic"("p_from" "date" DEFAULT ("date_trunc"('year'::"text", (CURRENT_DATE)::timestamp with time zone))::"date", "p_to" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("section" "text", "line_key" "text", "line_label" "text", "amount" numeric, "sort_order" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  /*
    WARNING: This periodic COGS calculation mixes external raw material
    purchases with Closing Stock that contains absorbed factory overhead (PAC).
    Therefore, Calculated COGS will artificially diverge from perpetual Sales
    COGS, and this Gross Profit should not be used for per-kg product margin
    analysis.

    Stock value is set-based on inventory_movements (chronological WAC stamped
    into value_amount). Do NOT loop _pac_opening_qty_value.
    Opening includes movement_type 'opening' (aliases) on p_from so Day-1 B/F
    is not dropped from Opening while still in Closing.
    Void protocol: coalesce(je.voucher_no, '') not like 'VOID-%';
    movements: exclude movement_type ending in _void; exclude triangle WH.
  */
  with mov_base as (
    select
      im.posting_date,
      im.movement_type,
      coalesce(
        nullif(im.value_amount, 0),
        round(coalesce(im.qty_in, 0) * coalesce(im.unit_cost, 0), 3),
        round(coalesce(im.qty_out, 0) * coalesce(im.unit_cost, 0), 3),
        0
      ) as v_amt,
      coalesce(im.qty_in, 0) as qty_in,
      coalesce(im.qty_out, 0) as qty_out
    from erp.inventory_movements im
    join erp.warehouses w on w.id = im.warehouse_id
    where coalesce(w.wh_type, '') <> 'triangle_transit'
      and w.code not ilike '%TRIANGLE%'
      and im.movement_type not like '%\_void' escape '\'
  ),
  mov_signed as (
    select
      posting_date,
      movement_type,
      case
        when qty_in > 0 then abs(v_amt)
        when qty_out > 0 then -abs(v_amt)
        else 0
      end as signed_value,
      case
        when movement_type in ('opening', 'opening_balance', 'ledger_opening', 'initial_stock')
          then 0
        when movement_type in ('purchase_in', 'adjustment_in') then abs(v_amt)
        when movement_type = 'purchase_return_out' then -abs(v_amt)
        else 0
      end as purchase_signed,
      (
        movement_type in ('opening', 'opening_balance', 'ledger_opening', 'initial_stock')
      ) as is_opening_balance
    from mov_base
  ),
  stock as (
    select
      coalesce(
        sum(signed_value) filter (
          where posting_date < p_from
             or (posting_date = p_from and is_opening_balance)
        ),
        0
      ) as opening_stock,
      coalesce(sum(signed_value) filter (where posting_date < (p_to + 1)), 0) as closing_stock,
      coalesce(
        sum(purchase_signed) filter (
          where posting_date between p_from and p_to
            and movement_type in ('purchase_in', 'adjustment_in', 'purchase_return_out')
            and not is_opening_balance
        ),
        0
      ) as purchases
    from mov_signed
  ),
  jl_agg as (
    select
      jl.account_code,
      erp._infer_account_type(jl.account_code, max(ca.account_type)) as account_type,
      max(ca.report_group) as coa_report_group,
      coalesce(sum(jl.debit_amount), 0) as total_debit,
      coalesce(sum(jl.credit_amount), 0) as total_credit
    from erp.journal_lines jl
    join erp.journal_entries je on je.id = jl.journal_entry_id
    left join erp.coa_accounts ca on ca.code = jl.account_code
    where je.posting_date between p_from and p_to
      and coalesce(je.voucher_no, '') not like 'VOID-%'
    group by jl.account_code
  ),
  gl as (
    select
      a.account_code,
      erp._infer_report_group(a.account_code, a.account_type, a.coa_report_group) as report_group,
      a.total_debit,
      a.total_credit
    from jl_agg a
  ),
  metrics as (
    select
      coalesce(sum(g.total_credit) filter (where g.report_group = 'operating_revenue'), 0) as gross_sales,
      coalesce(sum(g.total_debit) filter (where g.report_group = 'operating_revenue'), 0) as sales_returns,
      coalesce(
        sum(g.total_debit - g.total_credit) filter (
          where g.report_group in (
            'selling_expense',
            'admin_expense',
            'factory_overhead',
            'other_expense'
          )
        ),
        0
      ) as operating_expenses,
      coalesce(
        sum(g.total_credit - g.total_debit) filter (where g.report_group = 'other_income'),
        0
      ) as other_income
    from gl g
  ),
  calc as (
    select
      m.gross_sales,
      m.sales_returns,
      (m.gross_sales - m.sales_returns) as net_sales,
      s.opening_stock,
      s.purchases,
      s.closing_stock,
      (s.opening_stock + s.purchases - s.closing_stock) as calculated_cogs,
      (
        (m.gross_sales - m.sales_returns)
        - (s.opening_stock + s.purchases - s.closing_stock)
      ) as gross_profit,
      m.operating_expenses,
      m.other_income,
      (
        (m.gross_sales - m.sales_returns)
        - (s.opening_stock + s.purchases - s.closing_stock)
        - m.operating_expenses
        + m.other_income
      ) as net_profit
    from metrics m
    cross join stock s
  )
  select x.section, x.line_key, x.line_label, x.amount, x.sort_order
  from calc c
  cross join lateral (
    values
      ('net_sales'::text, 'gross_sales'::text, 'Gross Sales'::text, abs(c.gross_sales), 10),
      ('net_sales', 'sales_returns', 'Sales Returns', abs(c.sales_returns), 20),
      ('net_sales', 'net_sales', 'Net Sales', c.net_sales, 30),
      ('cogs_periodic', 'opening_stock', 'Opening Stock', abs(c.opening_stock), 40),
      ('cogs_periodic', 'purchases', 'Purchases', abs(c.purchases), 50),
      ('cogs_periodic', 'closing_stock', 'Closing Stock', abs(c.closing_stock), 60),
      ('cogs_periodic', 'calculated_cogs', 'Calculated COGS', c.calculated_cogs, 70),
      ('gross_profit', 'gross_profit', 'Gross Profit', c.gross_profit, 80),
      ('operating_expenses', 'operating_expenses', 'Operating Expenses', abs(c.operating_expenses), 90),
      ('other_income', 'other_income', 'Other Income', abs(c.other_income), 100),
      ('net_profit', 'net_profit', 'Net Profit', c.net_profit, 110)
  ) as x(section, line_key, line_label, amount, sort_order)
  order by x.sort_order;
$$;


ALTER FUNCTION "erp"."fn_profit_loss_periodic"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: FUNCTION "fn_profit_loss_periodic"("p_from" "date", "p_to" "date"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."fn_profit_loss_periodic"("p_from" "date", "p_to" "date") IS 'Periodic P&L: Net Sales from GL; COGS = Opening + Purchases - Closing (set-based movements). Opening includes Day-1 opening movements on p_from. WARNING: mixes external purchases with Closing Stock that includes absorbed factory overhead (PAC); do not use Gross Profit for per-kg product margin analysis.';


--
-- Name: fn_profit_loss_revenue_by_category("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_profit_loss_revenue_by_category"("p_from" "date" DEFAULT ("date_trunc"('month'::"text", (CURRENT_DATE)::timestamp with time zone))::"date", "p_to" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("category_code" "text", "category_name" "text", "amount" numeric, "kg" numeric, "sort_order" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  perform erp._assert_report_access();

  if p_from is null then
    p_from := date_trunc('month', current_date)::date;
  end if;
  if p_to is null then
    p_to := current_date;
  end if;

  return query
  with invoice_lines as (
    select
      erp._sales_revenue_category(i.item_type, i.inventory_group, i.code) as category_code,
      round(sum(sil.line_amount), 2) as amount,
      round(sum(coalesce(nullif(sil.net_weight, 0), sil.qty, 0)), 3) as kg
    from erp.sales_invoices si
    join erp.sales_invoice_lines sil on sil.sales_invoice_id = si.id
    join erp.items i on i.id = sil.item_id
    where si.posting_status = 'posted'
      and si.voided_at is null
      and si.invoice_date between p_from and p_to
    group by 1
  ),
  return_lines as (
    select
      erp._sales_revenue_category(i.item_type, i.inventory_group, i.code) as category_code,
      -round(sum(srl.line_amount), 2) as amount,
      -round(sum(coalesce(srl.qty, 0)), 3) as kg
    from erp.sales_returns sr
    join erp.sales_return_lines srl on srl.sales_return_id = sr.id
    join erp.items i on i.id = srl.item_id
    where sr.posting_status = 'posted'
      and sr.return_date between p_from and p_to
    group by 1
  ),
  scrap_sales as (
    select
      'scrap_sale'::text as category_code,
      round(sum(d.amount), 2) as amount,
      round(sum(d.net_weight), 3) as kg
    from erp.factory_scrap_dispatches d
    where d.status = 'posted'
      and d.mode = 'sale'
      and d.dispatch_date between p_from and p_to
    having abs(round(sum(d.amount), 2)) > 0.005
  ),
  combined as (
    select category_code, amount, kg from invoice_lines
    union all
    select category_code, amount, kg from return_lines
    union all
    select category_code, amount, kg from scrap_sales
  ),
  rolled as (
    select
      c.category_code,
      round(sum(c.amount), 2) as amount,
      round(sum(c.kg), 3) as kg
    from combined c
    group by c.category_code
  ),
  gl_operating as (
    select round(coalesce(sum(jl.credit_amount - jl.debit_amount), 0), 2) as amount
    from erp.journal_lines jl
    join erp.journal_entries je on je.id = jl.journal_entry_id
    left join erp.coa_accounts ca on ca.code = jl.account_code
    where je.posting_date between p_from and p_to
      and coalesce(je.voucher_no, '') not like 'VOID-%'
      and coalesce(ca.account_type, erp._infer_account_type(jl.account_code, ca.account_type)) = 'income'
      and erp._infer_report_group(
        jl.account_code,
        coalesce(ca.account_type, erp._infer_account_type(jl.account_code, ca.account_type)),
        ca.report_group
      ) = 'operating_revenue'
  ),
  with_plug as (
    select r.category_code, r.amount, r.kg from rolled r
    where abs(r.amount) > 0.005 or abs(r.kg) > 0.0005
    union all
    select
      'other_gl'::text,
      round(g.amount - coalesce((select sum(r.amount) from rolled r), 0), 2),
      0::numeric
    from gl_operating g
    where abs(g.amount - coalesce((select sum(r.amount) from rolled r), 0)) > 0.02
  )
  select
    w.category_code,
    erp._sales_revenue_category_label(w.category_code),
    w.amount,
    w.kg,
    case w.category_code
      when 'enameled_wire' then 10
      when 'copper_wire' then 20
      when 'copper_strip' then 30
      when 'wire_rm' then 40
      when 'other_fg' then 50
      when 'scrap_sale' then 60
      when 'other_gl' then 95
      else 90
    end
  from with_plug w
  order by 5, 1;
end;
$$;


ALTER FUNCTION "erp"."fn_profit_loss_revenue_by_category"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: FUNCTION "fn_profit_loss_revenue_by_category"("p_from" "date", "p_to" "date"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."fn_profit_loss_revenue_by_category"("p_from" "date", "p_to" "date") IS 'Document-level operating revenue split by product category for P&L presentation. Reconciles to GL operating_revenue with an other_gl plug if needed.';


--
-- Name: fn_profit_loss_sales_cogs_by_category("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_profit_loss_sales_cogs_by_category"("p_from" "date" DEFAULT ("date_trunc"('month'::"text", (CURRENT_DATE)::timestamp with time zone))::"date", "p_to" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("category_code" "text", "category_name" "text", "amount" numeric, "kg" numeric, "sort_order" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
#variable_conflict use_column
begin
  perform erp._assert_report_access();

  if p_from is null then
    p_from := date_trunc('month', current_date)::date;
  end if;
  if p_to is null then
    p_to := current_date;
  end if;

  return query
  with sales_out as (
    select
      erp._sales_revenue_category(i.item_type, i.inventory_group, i.code) as category_code,
      round(sum(im.value_amount), 2) as amount,
      round(sum(im.qty_out), 3) as kg
    from erp.inventory_movements im
    join erp.items i on i.id = im.item_id
    where im.movement_type = 'sales_out'
      and im.posting_date between p_from and p_to
    group by 1
  ),
  sales_return_in as (
    select
      erp._sales_revenue_category(i.item_type, i.inventory_group, i.code) as category_code,
      -round(sum(im.value_amount), 2) as amount,
      -round(sum(im.qty_in), 3) as kg
    from erp.inventory_movements im
    join erp.items i on i.id = im.item_id
    where im.movement_type = 'sales_return_in'
      and im.posting_date between p_from and p_to
    group by 1
  ),
  combined as (
    select category_code, amount, kg from sales_out
    union all
    select category_code, amount, kg from sales_return_in
  ),
  rolled as (
    select
      c.category_code,
      round(sum(c.amount), 2) as amount,
      round(sum(c.kg), 3) as kg
    from combined c
    group by c.category_code
  ),
  gl_sales_cogs as (
    select round(coalesce(sum(jl.debit_amount - jl.credit_amount), 0), 2) as amount
    from erp.journal_lines jl
    join erp.journal_entries je on je.id = jl.journal_entry_id
    where je.posting_date between p_from and p_to
      and coalesce(je.voucher_no, '') not like 'VOID-%'
      and jl.account_code in ('51001', '51010', '51011', '51012', '51013')
  ),
  with_plug as (
    select r.category_code, r.amount, r.kg from rolled r
    where abs(r.amount) > 0.005 or abs(r.kg) > 0.0005
    union all
    select
      'other_gl'::text,
      round(g.amount - coalesce((select sum(r.amount) from rolled r), 0), 2),
      0::numeric
    from gl_sales_cogs g
    where abs(g.amount - coalesce((select sum(r.amount) from rolled r), 0)) > 0.02
  )
  select
    w.category_code,
    erp._sales_cogs_category_label(w.category_code),
    w.amount,
    w.kg,
    case w.category_code
      when 'enameled_wire' then 10
      when 'copper_wire' then 20
      when 'copper_strip' then 30
      when 'wire_rm' then 40
      when 'other_fg' then 50
      when 'other_gl' then 95
      else 90
    end
  from with_plug w
  order by 5, 1;
end;
$$;


ALTER FUNCTION "erp"."fn_profit_loss_sales_cogs_by_category"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: FUNCTION "fn_profit_loss_sales_cogs_by_category"("p_from" "date", "p_to" "date"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."fn_profit_loss_sales_cogs_by_category"("p_from" "date", "p_to" "date") IS 'Sales COGS (direct RM) split by product category from sales_out / sales_return_in movements; reconciles to GL 51001+51010-13.';


--
-- Name: fn_purchase_register_report("date", "date", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_purchase_register_report"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_doc_side" "text" DEFAULT 'sale'::"text") RETURNS TABLE("doc_date" "date", "doc_no" "text", "party_code" "text", "party_name" "text", "item_code" "text", "item_name" "text", "size_spec" "text", "qty_kg" numeric, "unit_count" numeric, "unit_price" numeric, "line_amount" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select *
  from (
    select
      pi.invoice_date as doc_date,
      pi.invoice_no as doc_no,
      p.code as party_code,
      p.name as party_name,
      i.code as item_code,
      i.name as item_name,
      i.size_spec as size_spec,
      coalesce(nullif(pil.net_weight, 0), pil.qty, 0) as qty_kg,
      coalesce(pil.unit_count, 0) as unit_count,
      coalesce(pil.unit_price, 0) as unit_price,
      coalesce(pil.line_amount, 0) as line_amount
    from erp.purchase_invoices pi
    join erp.parties p on p.id = pi.party_id
    join erp.purchase_invoice_lines pil on pil.purchase_invoice_id = pi.id
    join erp.items i on i.id = pil.item_id
    where p_doc_side = 'sale'
      and pi.posting_status = 'posted'
      and (p_from is null or pi.invoice_date >= p_from)
      and (p_to is null or pi.invoice_date <= p_to)

    union all

    select
      pr.return_date as doc_date,
      pr.return_no as doc_no,
      p.code as party_code,
      p.name as party_name,
      i.code as item_code,
      i.name as item_name,
      i.size_spec as size_spec,
      coalesce(prl.qty, 0) as qty_kg,
      coalesce(prl.unit_count, 0) as unit_count,
      coalesce(prl.unit_price, 0) as unit_price,
      coalesce(prl.line_amount, 0) as line_amount
    from erp.purchase_returns pr
    join erp.parties p on p.id = pr.party_id
    join erp.purchase_return_lines prl on prl.purchase_return_id = pr.id
    join erp.items i on i.id = prl.item_id
    where p_doc_side = 'return'
      and pr.posting_status = 'posted'
      and (p_from is null or pr.return_date >= p_from)
      and (p_to is null or pr.return_date <= p_to)
  ) x
  order by doc_date, doc_no, item_code;
$$;


ALTER FUNCTION "erp"."fn_purchase_register_report"("p_from" "date", "p_to" "date", "p_doc_side" "text") OWNER TO "postgres";

--
-- Name: fn_reconcile_order_fulfillment(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_reconcile_order_fulfillment"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if not erp.has_role('ADMIN') then
    raise exception 'insufficient privileges: admin role required';
  end if;

  return erp._reconcile_order_fulfillment_core();
end;
$$;


ALTER FUNCTION "erp"."fn_reconcile_order_fulfillment"() OWNER TO "postgres";

--
-- Name: fn_reconciliation_checks(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_reconciliation_checks"() RETURNS TABLE("check_code" "text", "check_name" "text", "variance" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_ar_code text;
  v_ap_code text;
  v_gl_net numeric;
  v_ar_gl numeric;
  v_ar_sub numeric;
  v_ap_gl numeric;
  v_ap_sub numeric;
  v_inv_gl numeric;
  v_inv_sub numeric;
  v_unalloc_receipts numeric;
  v_unalloc_payments numeric;
  v_null_party_amount numeric;
  v_null_party_count int;
  v_orphan_prod_je int;
  v_orphan_scrap_arap int;
  v_prior_month_start date;
  v_prior_month_end date;
  v_prior_sales numeric := 0;
  v_prior_locked boolean := false;
  v_51999_net numeric := 0;
  v_sales_cogs numeric := 0;
  v_51999_pct numeric := 0;
  v_opening_mismatch int := 0;
begin
  v_ar_code := erp._lookup_posting_account('sales_invoice', 'ar');
  v_ap_code := erp._lookup_posting_account('purchase_invoice', 'ap');

  if v_ar_code is null or v_ap_code is null then
    return query select 'POSTING_MAP'::text, 'Required posting maps missing'::text, 0::numeric, 'FAIL'::text;
    return;
  end if;

  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0) into v_gl_net
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where coalesce(je.voucher_no, '') not like 'VOID-%';

  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0) into v_ar_gl
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where jl.account_code = v_ar_code
    and coalesce(je.voucher_no, '') not like 'VOID-%';

  select coalesce(sum(open_amount), 0) into v_ar_sub
  from erp.ar_documents ad where ad.status in ('open', 'partially_settled');

  select coalesce(sum(jl.credit_amount - jl.debit_amount), 0) into v_ap_gl
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where jl.account_code = v_ap_code
    and coalesce(je.voucher_no, '') not like 'VOID-%';

  select coalesce(sum(open_amount), 0) into v_ap_sub
  from erp.ap_documents ap where ap.status in ('open', 'partially_settled');

  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0) into v_inv_gl
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where jl.account_code in ('12101','12104','12301','12500')
    and coalesce(je.voucher_no, '') not like 'VOID-%';

  select coalesce(sum(ib.stock_value), 0) into v_inv_sub
  from erp.inventory_balances ib
  where not exists (
    select 1 from erp.warehouses w
    where w.id = ib.warehouse_id
      and (w.wh_type = 'triangle_transit' or w.code ilike '%TRIANGLE%')
  );

  select coalesce(sum(u.unallocated), 0) into v_unalloc_receipts
  from erp.v_unallocated_payments u
  where u.payment_type = 'receipt';

  select coalesce(sum(u.unallocated), 0) into v_unalloc_payments
  from erp.v_unallocated_payments u
  where u.payment_type = 'payment';

  select coalesce(sum(p.amount), 0), count(*) into v_null_party_amount, v_null_party_count
  from erp.payments p
  where p.posting_status = 'posted'
    and p.voided_at is null
    and p.party_id is null
    and p.entry_kind in ('party_receipt', 'party_payment', 'party_settlement');

  select count(*) into v_orphan_prod_je
  from erp.journal_entries je
  where je.voucher_type = 'PRODUCTION_BATCH'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    and not exists (select 1 from erp.production_batches pb where pb.id = je.source_doc_id);

  select count(*) into v_orphan_scrap_arap
  from (
    select ard.id, ard.source_doc_id from erp.ar_documents ard
      where ard.source_doc_type = 'scrap_trade' and coalesce(ard.status,'') <> 'void'
    union all
    select apd.id, apd.source_doc_id from erp.ap_documents apd
      where apd.source_doc_type = 'scrap_trade' and coalesce(apd.status,'') <> 'void'
  ) d
  where not exists (select 1 from erp.scrap_trades st where st.id = d.source_doc_id);

  -- Prior full calendar month (close target)
  v_prior_month_start := (date_trunc('month', current_date) - interval '1 month')::date;
  v_prior_month_end := (date_trunc('month', current_date) - interval '1 day')::date;

  select coalesce(sum(im.qty_out * coalesce(im.unit_cost, 0)), 0)
  into v_prior_sales
  from erp.inventory_movements im
  where im.movement_type = 'sales_out'
    and im.posting_date between v_prior_month_start and v_prior_month_end;

  select exists (
    select 1 from erp.costing_periods cp
    where cp.status = 'locked'
      and cp.start_date <= v_prior_month_start
      and cp.end_date >= v_prior_month_end
  ) into v_prior_locked;

  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0)
  into v_51999_net
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where jl.account_code = '51999'
    and je.status = 'posted'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    and je.posting_date between v_prior_month_start and v_prior_month_end;

  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0)
  into v_sales_cogs
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where jl.account_code in ('51001', '51010', '51011', '51012', '51013')
    and je.status = 'posted'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
    and je.posting_date between v_prior_month_start and v_prior_month_end;

  if v_sales_cogs > 0 then
    v_51999_pct := round(abs(v_51999_net) / v_sales_cogs * 100, 4);
  else
    v_51999_pct := case when abs(v_51999_net) > 0.5 then 100 else 0 end;
  end if;

  -- Opening JE ↔ opening movement by shared source_doc_id (opening_stock)
  select count(*) into v_opening_mismatch
  from (
    select im.source_doc_id
    from erp.inventory_movements im
    where im.source_doc_type = 'opening_stock'
      and im.source_doc_id is not null
      and coalesce(im.value_amount, 0) > 0.01
      and not exists (
        select 1 from erp.journal_entries je
        where je.source_doc_type = 'opening_stock'
          and je.source_doc_id = im.source_doc_id
          and coalesce(je.voucher_no, '') not like 'VOID-%'
      )
    union
    select je.source_doc_id
    from erp.journal_entries je
    where je.source_doc_type = 'opening_stock'
      and coalesce(je.voucher_no, '') not like 'VOID-%'
      and je.source_doc_id is not null
      and not exists (
        select 1 from erp.inventory_movements im
        where im.source_doc_type = 'opening_stock'
          and im.source_doc_id = je.source_doc_id
      )
  ) m;

  return query select 'TB_BALANCE'::text, 'Total GL should net to zero'::text, v_gl_net,
    case when abs(v_gl_net) <= 0.5 then 'PASS' else 'FAIL' end;
  return query select 'AR_CONTROL'::text, 'AR control vs subledger'::text, v_ar_gl - v_ar_sub,
    case when abs(v_ar_gl - v_ar_sub) <= 0.5 then 'PASS' else 'FAIL' end;
  return query select 'AP_CONTROL'::text, 'AP control vs subledger'::text, v_ap_gl - v_ap_sub,
    case when abs(v_ap_gl - v_ap_sub) <= 0.5 then 'PASS' else 'FAIL' end;
  return query select 'INV_CONTROL'::text, 'Inventory GL vs stock valuation'::text, v_inv_gl - v_inv_sub,
    case when abs(v_inv_gl - v_inv_sub) <= 0.5 then 'PASS' else 'FAIL' end;
  return query select 'AR_UNALLOCATED_RECEIPTS'::text, 'Customer settle leftovers not allocated (excl advances)'::text, v_unalloc_receipts,
    case when abs(v_unalloc_receipts) <= 0.5 then 'PASS' else 'FAIL' end;
  return query select 'AP_UNALLOCATED_PAYMENTS'::text, 'Vendor settle leftovers not allocated (excl advances)'::text, v_unalloc_payments,
    case when abs(v_unalloc_payments) <= 0.5 then 'PASS' else 'FAIL' end;
  return query select 'PAYMENTS_NULL_PARTY'::text, 'Posted party payments with no party (unallocatable)'::text, v_null_party_amount,
    case when v_null_party_count = 0 then 'PASS' else 'FAIL' end;
  return query select 'ORPHAN_PROD_JE'::text, 'Production-batch JEs with no batch (orphan)'::text, v_orphan_prod_je::numeric,
    case when v_orphan_prod_je = 0 then 'PASS' else 'FAIL' end;
  return query select 'ORPHAN_SCRAP_ARAP'::text, 'Scrap AR/AP docs with no trade (orphan)'::text, v_orphan_scrap_arap::numeric,
    case when v_orphan_scrap_arap = 0 then 'PASS' else 'FAIL' end;

  -- Report-grade close checks
  return query select
    'PAC_PERIOD_LOCKED'::text,
    format('Prior month %s–%s PAC locked when material sales', v_prior_month_start, v_prior_month_end)::text,
    round(v_prior_sales, 2),
    case
      when v_prior_sales <= 1000 then 'PASS'
      when v_prior_locked then 'PASS'
      else 'FAIL'
    end;

  return query select
    'UNABSORBED_51999_CAP'::text,
    'Prior-month |51999| pct of sales COGS (cap 5% when PAC locked)'::text,
    round(v_51999_pct, 4),
    case
      when not v_prior_locked then
        case when abs(v_51999_net) <= 0.5 or v_51999_pct <= 25 then 'PASS' else 'FAIL' end
      when v_51999_pct <= 5 then 'PASS'
      else 'FAIL'
    end;

  return query select
    'OPENING_JE_MOVEMENT_MATCH'::text,
    'Opening JE exists iff opening movement exists'::text,
    v_opening_mismatch::numeric,
    case when v_opening_mismatch = 0 then 'PASS' else 'FAIL' end;
end;
$$;


ALTER FUNCTION "erp"."fn_reconciliation_checks"() OWNER TO "postgres";

--
-- Name: fn_refresh_scrap_lot_allocations("uuid"[]); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_refresh_scrap_lot_allocations"("p_lot_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_lot_id uuid;
  v_new_alloc numeric;
  v_original numeric;
  v_status text;
begin
  if p_lot_ids is null or array_length(p_lot_ids, 1) is null then
    return;
  end if;

  foreach v_lot_id in array p_lot_ids
  loop
    select coalesce(sum(sa.allocated_kg), 0)
    into v_new_alloc
    from erp.scrap_allocations sa
    where sa.scrap_lot_id = v_lot_id;

    select spl.original_kg into v_original
    from erp.scrap_payable_lots spl
    where spl.id = v_lot_id;

    if v_original is null then
      continue;
    end if;

    if v_new_alloc + 0.001 >= v_original then
      v_status := 'exhausted';
    elsif v_new_alloc > 0 then
      v_status := 'partial';
    else
      v_status := 'open';
    end if;

    update erp.scrap_payable_lots
    set allocated_kg = v_new_alloc,
        status = v_status
    where id = v_lot_id;
  end loop;
end;
$$;


ALTER FUNCTION "erp"."fn_refresh_scrap_lot_allocations"("p_lot_ids" "uuid"[]) OWNER TO "postgres";

--
-- Name: fn_sales_detail_report("date", "date", "text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_sales_detail_report"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_party_code" "text" DEFAULT NULL::"text", "p_item_code" "text" DEFAULT NULL::"text", "p_size_spec" "text" DEFAULT NULL::"text") RETURNS TABLE("direction" "text", "doc_no" "text", "doc_date" "date", "party_code" "text", "party_name" "text", "item_code" "text", "item_name" "text", "size_spec" "text", "net_weight" numeric, "unit_count" numeric, "unit_price" numeric, "line_amount" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with sales as (
    select
      'sale'::text as direction,
      si.invoice_no as doc_no,
      si.invoice_date as doc_date,
      p.code as party_code,
      p.name as party_name,
      i.code as item_code,
      i.name as item_name,
      i.size_spec as size_spec,
      coalesce(sil.net_weight, 0) as net_weight,
      coalesce(sil.unit_count, 0) as unit_count,
      coalesce(sil.unit_price, 0) as unit_price,
      coalesce(sil.line_amount, 0) as line_amount
    from erp.sales_invoices si
    join erp.parties p on p.id = si.party_id
    join erp.sales_invoice_lines sil on sil.sales_invoice_id = si.id
    join erp.items i on i.id = sil.item_id
    where si.posting_status = 'posted'
      and (p_from is null or si.invoice_date >= p_from)
      and (p_to is null or si.invoice_date <= p_to)
      and (p_party_code is null or p.code = p_party_code)
      and (p_item_code is null or i.code = p_item_code)
      and (p_size_spec is null or i.size_spec is not null and i.size_spec ilike '%' || p_size_spec || '%')
  ),
  returns as (
    select
      'return'::text as direction,
      sr.return_no as doc_no,
      sr.return_date as doc_date,
      p.code as party_code,
      p.name as party_name,
      i.code as item_code,
      i.name as item_name,
      i.size_spec as size_spec,
      -coalesce(srl.qty, 0) as net_weight,
      -coalesce(srl.unit_count, 0) as unit_count,
      coalesce(srl.unit_price, 0) as unit_price,
      -coalesce(srl.line_amount, 0) as line_amount
    from erp.sales_returns sr
    join erp.parties p on p.id = sr.party_id
    join erp.sales_return_lines srl on srl.sales_return_id = sr.id
    join erp.items i on i.id = srl.item_id
    where sr.posting_status = 'posted'
      and (p_from is null or sr.return_date >= p_from)
      and (p_to is null or sr.return_date <= p_to)
      and (p_party_code is null or p.code = p_party_code)
      and (p_item_code is null or i.code = p_item_code)
      and (p_size_spec is null or i.size_spec is not null and i.size_spec ilike '%' || p_size_spec || '%')
  )
  select * from sales
  union all
  select * from returns
  order by doc_date, doc_no, direction;
$$;


ALTER FUNCTION "erp"."fn_sales_detail_report"("p_from" "date", "p_to" "date", "p_party_code" "text", "p_item_code" "text", "p_size_spec" "text") OWNER TO "postgres";

--
-- Name: fn_sales_register_report("date", "date", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_sales_register_report"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date", "p_doc_side" "text" DEFAULT 'sale'::"text") RETURNS TABLE("doc_date" "date", "doc_no" "text", "party_code" "text", "party_name" "text", "item_code" "text", "item_name" "text", "size_spec" "text", "qty_kg" numeric, "unit_count" numeric, "unit_price" numeric, "line_amount" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select *
  from (
    select
      si.invoice_date as doc_date,
      si.invoice_no as doc_no,
      p.code as party_code,
      p.name as party_name,
      i.code as item_code,
      i.name as item_name,
      i.size_spec as size_spec,
      coalesce(nullif(sil.net_weight, 0), sil.qty, 0) as qty_kg,
      coalesce(sil.unit_count, 0) as unit_count,
      coalesce(sil.unit_price, 0) as unit_price,
      coalesce(sil.line_amount, 0) as line_amount
    from erp.sales_invoices si
    join erp.parties p on p.id = si.party_id
    join erp.sales_invoice_lines sil on sil.sales_invoice_id = si.id
    join erp.items i on i.id = sil.item_id
    where p_doc_side = 'sale'
      and si.posting_status = 'posted'
      and (p_from is null or si.invoice_date >= p_from)
      and (p_to is null or si.invoice_date <= p_to)

    union all

    select
      sr.return_date as doc_date,
      sr.return_no as doc_no,
      p.code as party_code,
      p.name as party_name,
      i.code as item_code,
      i.name as item_name,
      i.size_spec as size_spec,
      coalesce(srl.qty, 0) as qty_kg,
      coalesce(srl.unit_count, 0) as unit_count,
      coalesce(srl.unit_price, 0) as unit_price,
      coalesce(srl.line_amount, 0) as line_amount
    from erp.sales_returns sr
    join erp.parties p on p.id = sr.party_id
    join erp.sales_return_lines srl on srl.sales_return_id = sr.id
    join erp.items i on i.id = srl.item_id
    where p_doc_side = 'return'
      and sr.posting_status = 'posted'
      and (p_from is null or sr.return_date >= p_from)
      and (p_to is null or sr.return_date <= p_to)
  ) x
  order by doc_date, doc_no, item_code;
$$;


ALTER FUNCTION "erp"."fn_sales_register_report"("p_from" "date", "p_to" "date", "p_doc_side" "text") OWNER TO "postgres";

--
-- Name: fn_scrap_obligations_for_party("text", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_scrap_obligations_for_party"("p_party_code" "text", "p_open_only" boolean DEFAULT true) RETURNS TABLE("obligation_id" "uuid", "obligation_no" "text", "sales_invoice_id" "uuid", "sales_invoice_no" "text", "invoice_date" "date", "ref_scrap_rate" numeric, "expected_kg" numeric, "received_kg" numeric, "open_kg" numeric, "status" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    o.id,
    o.obligation_no,
    o.sales_invoice_id,
    o.sales_invoice_no,
    o.invoice_date,
    o.ref_scrap_rate,
    o.expected_kg,
    o.received_kg,
    greatest(o.expected_kg - o.received_kg, 0) as open_kg,
    o.status
  from erp.scrap_receivable_obligations o
  join erp.parties p on p.id = o.party_id
  where p.code = p_party_code
    and o.status <> 'cancelled'
    and (not p_open_only or o.status in ('open', 'partial'))
  order by
    o.invoice_date asc nulls last,
    o.sales_invoice_no asc;
$$;


ALTER FUNCTION "erp"."fn_scrap_obligations_for_party"("p_party_code" "text", "p_open_only" boolean) OWNER TO "postgres";

--
-- Name: fn_scrap_page_load(integer); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_scrap_page_load"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with t as (
    select st.*
    from erp.scrap_trades st
    order by st.trade_date desc
    limit greatest(coalesce(p_limit, 100), 1)
  ),
  prem as (
    select
      t.id as trade_id,
      coalesce(
        (
          select jsonb_agg(jsonb_build_object(
            'sales_invoice_no', o.sales_invoice_no,
            'allocated_kg', a.allocated_kg,
            'ref_scrap_rate', o.ref_scrap_rate,
            'line_seq', a.line_seq
          ) order by a.line_seq)
          from erp.scrap_obligation_allocations a
          join erp.scrap_receivable_obligations o on o.id = a.obligation_id
          where a.scrap_trade_id = t.id
        ),
        (
          select jsonb_agg(jsonb_build_object(
            'sales_invoice_no', coalesce(s.sales_invoice_no, 'Invoice'),
            'allocated_kg', s.net_weight,
            'ref_scrap_rate', coalesce(s.ref_scrap_rate, s.unit_rate, 0),
            'line_seq', s.rn
          ) order by s.rn)
          from (
            select r.net_weight, r.unit_rate, o.sales_invoice_no, o.ref_scrap_rate,
                   row_number() over (order by r.id) as rn
            from erp.scrap_receipts r
            left join erp.scrap_receivable_obligations o on o.id = r.obligation_id
            where r.scrap_trade_id = t.id
              and r.record_metal_movement = false
          ) s
        ),
        (
          select jsonb_agg(jsonb_build_object(
            'sales_invoice_no', coalesce(s.sales_invoice_no, 'Invoice'),
            'allocated_kg', s.net_weight,
            'ref_scrap_rate', coalesce(s.ref_scrap_rate, s.unit_rate, 0),
            'line_seq', s.rn
          ) order by s.rn)
          from (
            select r.net_weight, r.unit_rate, o.sales_invoice_no, o.ref_scrap_rate,
                   row_number() over (order by r.id) as rn
            from erp.scrap_receipts r
            left join erp.scrap_receivable_obligations o on o.id = r.obligation_id
            where t.source_party_id is not null
              and r.party_id = t.source_party_id
              and r.receipt_date = t.trade_date
              and r.record_metal_movement = false
          ) s
        ),
        '[]'::jsonb
      ) as premium_lines
    from t
  )
  select jsonb_build_object(
    'trades', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id,
        'trade_no', t.trade_no,
        'trade_date', t.trade_date,
        'gross_weight', t.gross_weight,
        'tare_weight', t.tare_weight,
        'net_weight', t.net_weight,
        'unit_rate', t.unit_rate,
        'amount', t.amount,
        'status', t.status,
        'rate_status', t.rate_status,
        'financial_status', t.financial_status,
        'settlement_mode', t.settlement_mode,
        'bank_account_code', t.bank_account_code,
        'bilty_no', t.bilty_no,
        'vehicle_no', t.vehicle_no,
        'source_party_id', t.source_party_id,
        'dest_party_id', t.dest_party_id,
        'item_id', t.item_id,
        'source', (select jsonb_build_object('code', p.code, 'name', p.name) from erp.parties p where p.id = t.source_party_id),
        'dest', (select jsonb_build_object('code', p.code, 'name', p.name) from erp.parties p where p.id = t.dest_party_id),
        'item', (select jsonb_build_object('code', i.code, 'name', i.name) from erp.items i where i.id = t.item_id),
        'premium_lines', pr.premium_lines
      ) order by t.trade_date desc)
      from t
      join prem pr on pr.trade_id = t.id
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "erp"."fn_scrap_page_load"("p_limit" integer) OWNER TO "postgres";

--
-- Name: fn_scrap_party_summary("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_scrap_party_summary"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("party_code" "text", "party_name" "text", "direction" "text", "scrap_kg" numeric, "scrap_amount" numeric, "trade_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with metal as (
    select
      p.code as party_code,
      p.name as party_name,
      case
        when im.movement_type = 'scrap_out' then 'sent'
        when im.movement_type = 'scrap_in' then 'received'
      end as direction,
      coalesce(im.qty_out, im.qty_in, 0) as scrap_kg,
      coalesce(im.value_amount, 0) as scrap_amount,
      im.source_doc_id
    from erp.inventory_movements im
    join erp.parties p on p.id = im.party_id
  where im.source_doc_type = 'scrap_trade'
    and im.movement_type in ('scrap_out', 'scrap_in')
    and (p_from is null or im.posting_date >= p_from)
    and (p_to is null or im.posting_date <= p_to)
  ),
  agg as (
    select
      party_code,
      party_name,
      direction,
      sum(scrap_kg) as scrap_kg,
      sum(scrap_amount) as scrap_amount,
      count(distinct source_doc_id) as trade_count
    from metal
    where direction is not null
    group by party_code, party_name, direction
  )
  select * from agg
  order by party_name, direction;
$$;


ALTER FUNCTION "erp"."fn_scrap_party_summary"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_scrap_payable_lots_for_party("text", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_scrap_payable_lots_for_party"("p_party_code" "text", "p_open_only" boolean DEFAULT true) RETURNS TABLE("lot_id" "uuid", "lot_no" "text", "source_doc_type" "text", "source_doc_no" "text", "lot_date" "date", "unit_rate" numeric, "original_kg" numeric, "allocated_kg" numeric, "open_kg" numeric, "status" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    l.id, l.lot_no, l.source_doc_type, l.source_doc_no, l.lot_date, l.unit_rate,
    l.original_kg, l.allocated_kg, greatest(l.original_kg - l.allocated_kg, 0), l.status
  from erp.scrap_payable_lots l
  join erp.parties p on p.id = l.party_id
  left join erp.scrap_trades st
    on st.id = l.source_doc_id
   and l.source_doc_type = 'scrap_trade'
  where p.code = p_party_code
    and (not p_open_only or l.status in ('open', 'partial'))
    and coalesce(st.settlement_mode, 'triangle') <> 'cash'
  order by l.unit_rate, l.lot_date;
$$;


ALTER FUNCTION "erp"."fn_scrap_payable_lots_for_party"("p_party_code" "text", "p_open_only" boolean) OWNER TO "postgres";

--
-- Name: fn_scrap_posting_health(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_scrap_posting_health"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_has_receipts_table boolean := to_regclass('erp.scrap_receipts') is not null;
  v_has_obligations_table boolean := to_regclass('erp.scrap_receivable_obligations') is not null;
  v_post_trade boolean := false;
  v_post_receipt boolean := false;
begin
  select exists (
    select 1 from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'erp' and p.proname = 'post_scrap_trade'
  ) into v_post_trade;

  select exists (
    select 1 from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'erp' and p.proname = 'post_scrap_receipt'
      and pg_get_function_identity_arguments(p.oid) = 'doc_id uuid'
  ) into v_post_receipt;

  return jsonb_build_object(
    'ok', v_has_receipts_table and v_has_obligations_table and v_post_trade and v_post_receipt,
    'scrap_receipts_table', v_has_receipts_table,
    'scrap_obligations_table', v_has_obligations_table,
    'post_scrap_trade', v_post_trade,
    'post_scrap_receipt', v_post_receipt,
    'hint', case
      when not v_has_receipts_table then 'Apply migration 76 (premium scrap obligations).'
      when not v_post_receipt then 'Apply migration 79 or 81 (post_scrap_receipt).'
      else null
    end
  );
end;
$$;


ALTER FUNCTION "erp"."fn_scrap_posting_health"() OWNER TO "postgres";

--
-- Name: fn_scrap_toll_drop_party_summary("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_scrap_toll_drop_party_summary"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("party_code" "text", "party_name" "text", "party_role" "text", "scrap_kg" numeric, "avg_rate" numeric, "scrap_amount" numeric, "trade_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  with posted as (
    select *
    from erp.scrap_trades st
    where st.status = 'posted'
      and (p_from is null or st.trade_date >= p_from)
      and (p_to is null or st.trade_date <= p_to)
  ),
  sources as (
    select
      ps.code as party_code,
      ps.name as party_name,
      'source'::text as party_role,
      sum(p.net_weight) as scrap_kg,
      case
        when sum(p.net_weight) > 0 then round(sum(p.amount) / sum(p.net_weight), 3)
        else 0
      end as avg_rate,
      sum(p.amount) as scrap_amount,
      count(*)::bigint as trade_count
    from posted p
    join erp.parties ps on ps.id = p.source_party_id
    group by ps.code, ps.name
  ),
  destinations as (
    select
      pd.code as party_code,
      pd.name as party_name,
      'destination'::text as party_role,
      sum(p.net_weight) as scrap_kg,
      case
        when sum(p.net_weight) > 0 then round(sum(p.amount) / sum(p.net_weight), 3)
        else 0
      end as avg_rate,
      sum(p.amount) as scrap_amount,
      count(*)::bigint as trade_count
    from posted p
    join erp.parties pd on pd.id = p.dest_party_id
    group by pd.code, pd.name
  )
  select * from sources
  union all
  select * from destinations
  order by party_role, party_name;
$$;


ALTER FUNCTION "erp"."fn_scrap_toll_drop_party_summary"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_scrap_trade_register("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_scrap_trade_register"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("trade_no" "text", "trade_date" "date", "source_name" "text", "dest_name" "text", "item_code" "text", "bilty_no" "text", "vehicle_no" "text", "net_weight" numeric, "unit_rate" numeric, "amount" numeric, "source_ap_amount" numeric, "dest_ar_amount" numeric, "settlement_mode" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    st.trade_no,
    st.trade_date,
    ps.name as source_name,
    pd.name as dest_name,
    i.code as item_code,
    st.bilty_no,
    st.vehicle_no,
    st.net_weight,
    st.unit_rate,
    st.amount,
    coalesce(ap.amount, 0) as source_ap_amount,
    case
      when coalesce(st.settlement_mode, 'triangle') = 'cash' then 0::numeric
      else coalesce(ar.amount, 0)
    end as dest_ar_amount,
    coalesce(st.settlement_mode, 'triangle') as settlement_mode
  from erp.scrap_trades st
  join erp.parties ps on ps.id = st.source_party_id
  join erp.parties pd on pd.id = st.dest_party_id
  left join erp.items i on i.id = st.item_id
  left join erp.ap_documents ap
    on ap.source_doc_type = 'scrap_trade' and ap.source_doc_id = st.id and ap.party_id = st.source_party_id
  left join erp.ar_documents ar
    on ar.source_doc_type = 'scrap_trade' and ar.source_doc_id = st.id and ar.party_id = st.dest_party_id
  where st.status = 'posted'
    and (p_from is null or st.trade_date >= p_from)
    and (p_to is null or st.trade_date <= p_to)
  order by st.trade_date desc, st.trade_no desc;
$$;


ALTER FUNCTION "erp"."fn_scrap_trade_register"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_scrap_wastage("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_scrap_wastage"("p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS TABLE("source" "text", "posting_date" "date", "item_code" "text", "scrap_kg" numeric, "batch_no" "text", "trade_no" "text", "machine_code" "text", "department" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    'production'::text,
    fs.dispatch_date,
    i.code,
    fsl.net_weight,
    null::text,
    fs.dispatch_no,
    m.machine_code,
    fsl.department
  from erp.factory_scrap_dispatch_lines fsl
  join erp.factory_scrap_dispatches fs on fs.id = fsl.dispatch_id
  join erp.items i on i.id = fsl.item_id
  left join erp.production_machines m on m.id = fsl.machine_id
  where fs.status = 'posted'
    and (p_from is null or fs.dispatch_date >= p_from)
    and (p_to is null or fs.dispatch_date <= p_to)
  union all
  select
    'scrap_trade',
    st.trade_date,
    i.code,
    st.net_weight,
    null::text,
    st.trade_no,
    null::text,
    null::text
  from erp.scrap_trades st
  join erp.items i on i.id = st.item_id
  where st.status = 'posted'
    and (p_from is null or st.trade_date >= p_from)
    and (p_to is null or st.trade_date <= p_to)
  union all
  select
    'conversion_return',
    scr.return_date,
    i.code,
    scr.net_weight,
    null::text,
    scr.return_no,
    null::text,
    null::text
  from erp.scrap_conversion_returns scr
  join erp.items i on i.id = scr.item_id
  where scr.status = 'posted'
    and (p_from is null or scr.return_date >= p_from)
    and (p_to is null or scr.return_date <= p_to)
$$;


ALTER FUNCTION "erp"."fn_scrap_wastage"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_stock_valuation("date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_stock_valuation"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("item_code" "text", "item_name" "text", "warehouse_code" "text", "inventory_section" "text", "on_hand_qty" numeric, "on_hand_units" numeric, "pending_qty" numeric, "book_unit_cost" numeric, "book_value" numeric, "valuation_unit_rate" numeric, "valuation_value" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  perform erp._assert_report_access();

  return query
  with pending as (
    select pri.item_id, pri.warehouse_id, sum(pri.qty) as pending_qty
    from erp.pending_rate_items pri
    where pri.status = 'open' and pri.item_id is not null
    group by pri.item_id, pri.warehouse_id
  ),
  base as (
    select
      i.id as item_id,
      i.code as item_code,
      i.name as item_name,
      w.code as warehouse_code,
      erp._item_inventory_section(i.id) as inventory_section,
      ib.on_hand_qty,
      coalesce(
        nullif(ib.on_hand_units, 0),
        erp._varnish_units_from_kg(i.id, ib.on_hand_qty)
      ) as on_hand_units,
      coalesce(p.pending_qty, 0) as pending_qty,
      ib.avg_unit_cost as book_unit_cost,
      ib.stock_value as book_value,
      erp.resolve_inventory_valuation_rate(i.id, p_as_of) as valuation_unit_rate
    from erp.inventory_balances ib
    join erp.items i on i.id = ib.item_id
    join erp.warehouses w on w.id = ib.warehouse_id
    left join pending p on p.item_id = ib.item_id and p.warehouse_id = ib.warehouse_id
    where coalesce(w.wh_type, '') <> 'triangle_transit'
      and coalesce(w.code, '') not ilike '%TRIANGLE%'
      and (ib.on_hand_qty <> 0 or coalesce(ib.on_hand_units, 0) <> 0 or coalesce(p.pending_qty, 0) <> 0)
  )
  select
    b.item_code,
    b.item_name,
    b.warehouse_code,
    b.inventory_section,
    b.on_hand_qty,
    b.on_hand_units,
    b.pending_qty,
    b.book_unit_cost,
    b.book_value,
    b.valuation_unit_rate,
    round(coalesce(b.on_hand_qty, 0) * coalesce(b.valuation_unit_rate, 0), 3) as valuation_value
  from base b
  order by b.inventory_section, b.item_code, b.warehouse_code;
end;
$$;


ALTER FUNCTION "erp"."fn_stock_valuation"("p_as_of" "date") OWNER TO "postgres";

--
-- Name: fn_transaction_history(timestamp with time zone, timestamp with time zone, "text", "uuid", "text", "text", integer); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_transaction_history"("p_from" timestamp with time zone DEFAULT (CURRENT_DATE - '30 days'::interval), "p_to" timestamp with time zone DEFAULT (CURRENT_DATE + '1 day'::interval), "p_entity_type" "text" DEFAULT NULL::"text", "p_actor_id" "uuid" DEFAULT NULL::"uuid", "p_action" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "event_at" timestamp with time zone, "action" "text", "entity_type" "text", "entity_id" "text", "source_doc_type" "text", "source_doc_id" "uuid", "source_doc_no" "text", "summary" "text", "actor_user_id" "uuid", "actor_display_name" "text", "before_data" "jsonb", "after_data" "jsonb", "metadata" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  if not erp.has_role('ADMIN') then
    raise exception 'insufficient privileges for transaction history';
  end if;

  return query
  select
    ae.id,
    ae.event_at,
    ae.action,
    ae.entity_type,
    ae.entity_id,
    ae.source_doc_type,
    ae.source_doc_id,
    ae.source_doc_no,
    ae.summary,
    ae.actor_user_id,
    erp._audit_actor_name(ae.actor_user_id),
    ae.before_data,
    ae.after_data,
    ae.metadata
  from erp.audit_events ae
  where ae.event_at >= coalesce(p_from, ae.event_at)
    and ae.event_at < coalesce(p_to, ae.event_at + interval '1 second')
    and (p_entity_type is null or ae.entity_type = p_entity_type)
    and (p_actor_id is null or ae.actor_user_id = p_actor_id)
    and (p_action is null or ae.action = p_action)
    and (
      p_search is null or trim(p_search) = ''
      or ae.summary ilike '%' || trim(p_search) || '%'
      or ae.source_doc_no ilike '%' || trim(p_search) || '%'
      or ae.entity_id ilike '%' || trim(p_search) || '%'
    )
  order by ae.event_at desc, ae.id desc
  limit greatest(1, least(coalesce(p_limit, 200), 1000));
end;
$$;


ALTER FUNCTION "erp"."fn_transaction_history"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_entity_type" "text", "p_actor_id" "uuid", "p_action" "text", "p_search" "text", "p_limit" integer) OWNER TO "postgres";

--
-- Name: fn_trial_balance("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_trial_balance"("p_from" "date" DEFAULT '1900-01-01'::"date", "p_to" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("account_code" "text", "account_name" "text", "account_type" "text", "total_debit" numeric, "total_credit" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    jl.account_code::text,
    erp._display_account_name(jl.account_code, ca.name, jl.account_name)::text as account_name,
    erp._infer_account_type(jl.account_code, ca.account_type)::text as account_type,
    coalesce(sum(jl.debit_amount), 0)::numeric as total_debit,
    coalesce(sum(jl.credit_amount), 0)::numeric as total_credit
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  left join erp.coa_accounts ca on ca.code = jl.account_code
  where je.posting_date between p_from and p_to
    and coalesce(je.voucher_no, '') not like 'VOID-%'
  group by jl.account_code, ca.name, jl.account_name, ca.account_type
  having coalesce(sum(jl.debit_amount), 0) <> 0
      or coalesce(sum(jl.credit_amount), 0) <> 0
  order by jl.account_code;
$$;


ALTER FUNCTION "erp"."fn_trial_balance"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_unit_economics("date", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_unit_economics"("p_from" "date" DEFAULT ("date_trunc"('month'::"text", (CURRENT_DATE)::timestamp with time zone))::"date", "p_to" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_production_kg numeric := 0;
  v_sold_kg numeric := 0;
  v_scrap_kg numeric := 0;
  v_purchased_rm_kg numeric := 0;
  v_varnish_kg numeric := 0;
  v_varnish_cost numeric := 0;
  v_varnish_drums_consumed numeric := 0;
  v_drum_weight_kg numeric := 200;

  v_direct_rm numeric := 0;
  v_direct_conversion numeric := 0;
  v_factory_overhead numeric := 0;
  v_wastage numeric := 0;
  v_unabsorbed numeric := 0;
  v_selling numeric := 0;
  v_admin numeric := 0;
  v_revenue numeric := 0;
  v_other_income numeric := 0;
  v_total_cogs numeric := 0;
  v_total_expense numeric := 0;

  v_direct_conversion_per_kg numeric;
  v_factory_overhead_per_kg numeric;
  v_varnish_per_kg_produced numeric;
  v_conversion_burden_per_kg_produced numeric;
  v_admin_per_kg_sold numeric;
  v_selling_per_kg_sold numeric;
  v_commercial_burden_per_kg_sold numeric;
  v_break_even_watta numeric;

  v_rm_per_kg_sold numeric;
  v_varnish_per_kg_sold numeric;
  v_rm_burden_per_kg_sold numeric;
  v_conversion_per_kg_produced numeric;
  v_commercial_per_kg_sold numeric;
  v_total_landed_per_kg_sold numeric;
  v_total_sales_landed_per_kg numeric;
  v_total_cash_landed_per_kg numeric;

  v_revenue_total numeric;
  v_revenue_per_kg numeric;
  v_gross_profit numeric;
  v_gross_margin_per_kg numeric;
  v_net_margin_per_kg numeric;

  v_warnings jsonb := '[]'::jsonb;
  v_expense_lines jsonb := '[]'::jsonb;
  v_yield_pct numeric;
  v_pac_status text := 'none';
  v_pac_period_code text;
  v_cogs_for_cap numeric := 0;
begin
  perform erp._assert_report_access();

  if p_from is null then
    p_from := date_trunc('month', current_date)::date;
  end if;
  if p_to is null then
    p_to := current_date;
  end if;

  v_drum_weight_kg := coalesce(nullif(erp._production_standard_num('varnish_drum_weight_kg'), 0), 200);

  select
    coalesce(sum(d.total_output_kg), 0),
    coalesce(sum(d.total_scrap_kg), 0)
  into v_production_kg, v_scrap_kg
  from erp.fn_daily_production(p_from, p_to) d;

  select coalesce(sum(im.qty_out), 0)
  into v_sold_kg
  from erp.inventory_movements im
  where im.movement_type = 'sales_out'
    and im.posting_date between p_from and p_to;

  select coalesce(sum(im.qty_in), 0)
  into v_purchased_rm_kg
  from erp.inventory_movements im
  where im.movement_type = 'purchase_in'
    and im.posting_date between p_from and p_to;

  -- Ops varnish intensity (display only — not added on top of sales COGS)
  select
    coalesce(sum(im.qty_out), 0),
    coalesce(sum(round(im.qty_out * coalesce(nullif(im.unit_cost, 0), ib.avg_unit_cost, 0), 2)), 0)
  into v_varnish_kg, v_varnish_cost
  from erp.inventory_movements im
  join erp.items i on i.id = im.item_id
  left join erp.inventory_balances ib
    on ib.item_id = im.item_id and ib.warehouse_id = im.warehouse_id
  where im.movement_type = 'production_issue'
    and im.posting_date between p_from and p_to
    and (
      coalesce(i.inventory_group, '') = 'chemicals'
      or coalesce(i.item_type, '') ilike '%varnish%'
    );

  if v_drum_weight_kg > 0 then
    v_varnish_drums_consumed := round(v_varnish_kg / v_drum_weight_kg, 3);
  end if;

  if v_production_kg <= 0 then
    v_warnings := v_warnings || jsonb_build_array('no_production_in_period');
  end if;
  if v_sold_kg <= 0 then
    v_warnings := v_warnings || jsonb_build_array('no_sales_in_period');
  end if;
  if v_sold_kg > v_production_kg and v_production_kg > 0 then
    v_warnings := v_warnings || jsonb_build_array('sold_exceeds_production_inventory_drawdown');
  end if;
  if v_varnish_kg > 0 and v_varnish_cost <= 0 then
    v_warnings := v_warnings || jsonb_build_array('varnish_consumed_without_unit_cost');
  end if;

  if v_production_kg > 0 then
    v_yield_pct := round(((v_production_kg - v_scrap_kg) / v_production_kg) * 100, 2);
  else
    v_yield_pct := null;
  end if;

  with tb as (
    select
      tb.account_code,
      tb.account_name,
      coalesce(ca.account_type, tb.account_type) as account_type,
      erp._infer_report_group(
        tb.account_code,
        coalesce(ca.account_type, tb.account_type),
        ca.report_group
      ) as report_group,
      coalesce(tb.total_debit, 0) as total_debit,
      coalesce(tb.total_credit, 0) as total_credit,
      case
        when coalesce(ca.account_type, tb.account_type) = 'expense'
          then coalesce(tb.total_debit, 0) - coalesce(tb.total_credit, 0)
        when coalesce(ca.account_type, tb.account_type) = 'income'
          then coalesce(tb.total_credit, 0) - coalesce(tb.total_debit, 0)
        else 0
      end as net_amount,
      case
        -- Sales COGS (clearing + component split) = RM / book COGS at sale
        when coalesce(ca.account_type, tb.account_type) = 'expense'
             and tb.account_code in ('51001', '51010', '51011', '51012', '51013')
          then 'direct_rm'
        -- Production unabsorbed / absorption contra — exclude from conversion rates
        when coalesce(ca.account_type, tb.account_type) = 'expense'
             and tb.account_code = '51999'
          then 'unabsorbed'
        -- Inventory write-down / scrap wastage
        when coalesce(ca.account_type, tb.account_type) = 'expense'
             and tb.account_code = '51006'
          then 'wastage'
        -- Remaining COGS = period factory cash (wages, freight in, packing, varnish cash…)
        when coalesce(ca.account_type, tb.account_type) = 'expense'
             and erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'cogs'
          then 'direct_conversion'
        when coalesce(ca.account_type, tb.account_type) = 'expense'
             and erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'factory_overhead'
          then 'factory_overhead'
        when coalesce(ca.account_type, tb.account_type) = 'expense'
             and erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'selling_expense'
          then 'selling'
        when coalesce(ca.account_type, tb.account_type) = 'expense'
             and erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'admin_expense'
          then 'admin'
        when coalesce(ca.account_type, tb.account_type) = 'income'
             and erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'operating_revenue'
          then 'revenue'
        when coalesce(ca.account_type, tb.account_type) = 'income'
             and erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'other_income'
          then 'other_income'
        else null
      end as bucket
    from erp.fn_trial_balance(p_from, p_to) tb
    left join erp.coa_accounts ca on ca.code = tb.account_code
  ),
  bucket_totals as (
    select
      coalesce(sum(case when bucket = 'direct_rm' then net_amount else 0 end), 0) as direct_rm,
      coalesce(sum(case when bucket = 'direct_conversion' then net_amount else 0 end), 0) as direct_conversion,
      coalesce(sum(case when bucket = 'factory_overhead' then net_amount else 0 end), 0) as factory_overhead,
      coalesce(sum(case when bucket = 'wastage' then net_amount else 0 end), 0) as wastage,
      coalesce(sum(case when bucket = 'unabsorbed' then net_amount else 0 end), 0) as unabsorbed,
      coalesce(sum(case when bucket = 'selling' then net_amount else 0 end), 0) as selling,
      coalesce(sum(case when bucket = 'admin' then net_amount else 0 end), 0) as admin,
      coalesce(sum(case when bucket = 'revenue' then net_amount else 0 end), 0) as revenue,
      coalesce(sum(case when bucket = 'other_income' then net_amount else 0 end), 0) as other_income,
      -- Book COGS for margin = sales COGS only (not period conversion / unabsorbed / wastage)
      coalesce(sum(case when bucket = 'direct_rm' then net_amount else 0 end), 0) as total_cogs,
      coalesce(sum(case when account_type = 'expense' then net_amount else 0 end), 0) as total_expense
    from tb
  )
  select
    bt.direct_rm,
    bt.direct_conversion,
    bt.factory_overhead,
    bt.wastage,
    bt.unabsorbed,
    bt.selling,
    bt.admin,
    bt.revenue,
    bt.other_income,
    bt.total_cogs,
    bt.total_expense
  into
    v_direct_rm,
    v_direct_conversion,
    v_factory_overhead,
    v_wastage,
    v_unabsorbed,
    v_selling,
    v_admin,
    v_revenue,
    v_other_income,
    v_total_cogs,
    v_total_expense
  from bucket_totals bt;

  if v_unabsorbed > 0.01 then
    v_warnings := v_warnings || jsonb_build_array('unabsorbed_production_cost_excluded');
  end if;
  if v_wastage > 0.01 then
    v_warnings := v_warnings || jsonb_build_array('wastage_excluded_from_conversion');
  end if;

  -- PAC coverage for the report range (prefer locked, else draft)
  select cp.status, cp.period_code
  into v_pac_status, v_pac_period_code
  from erp.costing_periods cp
  where cp.start_date <= p_from
    and cp.end_date >= p_to
    and cp.status = 'locked'
  order by cp.end_date desc
  limit 1;

  if v_pac_status is null then
    select cp.status, cp.period_code
    into v_pac_status, v_pac_period_code
    from erp.costing_periods cp
    where cp.start_date <= p_from
      and cp.end_date >= p_to
      and cp.status = 'draft'
    order by cp.last_run_at desc nulls last
    limit 1;
  end if;

  v_pac_status := coalesce(v_pac_status, 'none');

  if v_pac_status <> 'locked' then
    v_warnings := v_warnings || jsonb_build_array('no_locked_pac_for_range');
  end if;

  v_cogs_for_cap := greatest(v_direct_rm, 0) + greatest(v_direct_conversion, 0);
  if v_cogs_for_cap > 0 and v_unabsorbed > v_cogs_for_cap * 0.05 then
    v_warnings := v_warnings || jsonb_build_array('do_not_use_for_pricing');
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'code', x.account_code,
      'name', x.account_name,
      'bucket', x.bucket,
      'amount', round(x.net_amount, 2)
    )
    order by x.bucket, x.account_code
  ), '[]'::jsonb)
  into v_expense_lines
  from (
    select
      tb.account_code,
      max(tb.account_name) as account_name,
      case
        when tb.account_code in ('51001', '51010', '51011', '51012', '51013') then 'direct_rm'
        when tb.account_code = '51999' then 'unabsorbed'
        when tb.account_code = '51006' then 'wastage'
        when erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'cogs'
          then 'direct_conversion'
        when erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'factory_overhead'
          then 'factory_overhead'
        when erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'selling_expense'
          then 'selling'
        when erp._infer_report_group(tb.account_code, coalesce(ca.account_type, tb.account_type), ca.report_group) = 'admin_expense'
          then 'admin'
        else null
      end as bucket,
      sum(coalesce(tb.total_debit, 0) - coalesce(tb.total_credit, 0)) as net_amount
    from erp.fn_trial_balance(p_from, p_to) tb
    left join erp.coa_accounts ca on ca.code = tb.account_code
    where coalesce(ca.account_type, tb.account_type) = 'expense'
    group by tb.account_code, ca.account_type, ca.report_group, tb.account_type
  ) x
  where x.bucket is not null
    and abs(x.net_amount) > 0.01;

  -- Inventory varnish: ops line only (not double-counted into L2 RM)
  if v_varnish_cost > 0 then
    v_expense_lines := v_expense_lines || jsonb_build_array(
      jsonb_build_object(
        'code', 'VAR-INV',
        'name', 'Varnish consumed (inventory WAC — ops only)',
        'bucket', 'varnish',
        'amount', round(v_varnish_cost, 2)
      )
    );
  end if;

  if v_production_kg > 0 then
    v_direct_conversion_per_kg := round(v_direct_conversion / v_production_kg, 4);
    v_factory_overhead_per_kg := round(v_factory_overhead / v_production_kg, 4);
    v_varnish_per_kg_produced := round(v_varnish_cost / v_production_kg, 4);
    v_conversion_burden_per_kg_produced := round(
      coalesce(v_direct_conversion_per_kg, 0) + coalesce(v_factory_overhead_per_kg, 0),
      4
    );
    v_conversion_per_kg_produced := v_conversion_burden_per_kg_produced;
  end if;

  if v_sold_kg > 0 then
    v_admin_per_kg_sold := round(v_admin / v_sold_kg, 4);
    v_selling_per_kg_sold := round(v_selling / v_sold_kg, 4);
    v_commercial_burden_per_kg_sold := round(v_admin_per_kg_sold + v_selling_per_kg_sold, 4);
    -- Book RM/COGS at sale (already includes FG WAC varnish/OH components)
    v_rm_per_kg_sold := round(v_direct_rm / v_sold_kg, 4);
    v_varnish_per_kg_sold := round(v_varnish_cost / v_sold_kg, 4); -- informational
    v_rm_burden_per_kg_sold := v_rm_per_kg_sold;
  end if;

  if v_conversion_burden_per_kg_produced is not null
     and v_commercial_burden_per_kg_sold is not null then
    v_break_even_watta := round(
      v_conversion_burden_per_kg_produced + v_commercial_burden_per_kg_sold, 4
    );
  elsif v_conversion_burden_per_kg_produced is not null then
    v_break_even_watta := v_conversion_burden_per_kg_produced;
  elsif v_commercial_burden_per_kg_sold is not null then
    v_break_even_watta := v_commercial_burden_per_kg_sold;
  end if;

  v_commercial_per_kg_sold := v_commercial_burden_per_kg_sold;

  -- Sales COGS landed: book COGS already embeds absorbed OH in 51013 — do not add period conversion
  if v_rm_burden_per_kg_sold is not null or v_commercial_burden_per_kg_sold is not null then
    v_total_sales_landed_per_kg := round(
      coalesce(v_rm_burden_per_kg_sold, 0) + coalesce(v_commercial_burden_per_kg_sold, 0),
      4
    );
    -- Primary l2_landed = sales COGS view (honest for GP / pricing)
    v_total_landed_per_kg_sold := v_total_sales_landed_per_kg;
  end if;

  -- Cash period view: period factory cash + OpEx OH / prod + commercial (separate optics)
  if v_conversion_per_kg_produced is not null or v_commercial_burden_per_kg_sold is not null then
    v_total_cash_landed_per_kg := round(
      coalesce(v_rm_burden_per_kg_sold, 0)
      + coalesce(v_conversion_per_kg_produced, 0)
      + coalesce(v_commercial_burden_per_kg_sold, 0),
      4
    );
  end if;

  -- Margins from operating revenue vs book sales COGS (exclude other_income / unabsorbed noise)
  v_revenue_total := v_revenue;
  if v_sold_kg > 0 then
    v_revenue_per_kg := round(v_revenue_total / v_sold_kg, 4);
    v_gross_profit := v_revenue_total - v_total_cogs;
    v_gross_margin_per_kg := round(v_gross_profit / v_sold_kg, 4);
    v_net_margin_per_kg := round(
      (v_revenue_total - v_total_cogs - v_direct_conversion - v_factory_overhead - v_selling - v_admin - v_wastage)
        / v_sold_kg,
      4
    );
  end if;

  return jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'pac_status', jsonb_build_object(
      'status', v_pac_status,
      'period_code', v_pac_period_code
    ),
    'volumes', jsonb_build_object(
      'production_kg', round(v_production_kg, 3),
      'sold_kg', round(v_sold_kg, 3),
      'scrap_kg', round(v_scrap_kg, 3),
      'purchased_rm_kg', round(v_purchased_rm_kg, 3),
      'varnish_consumed_kg', round(v_varnish_kg, 3),
      'varnish_drums_consumed', v_varnish_drums_consumed,
      'varnish_drum_weight_kg', v_drum_weight_kg,
      'yield_pct', v_yield_pct,
      'warnings', v_warnings
    ),
    'totals', jsonb_build_object(
      'direct_rm', round(v_direct_rm, 2),
      'direct_conversion', round(v_direct_conversion, 2),
      'factory_overhead', round(v_factory_overhead, 2),
      'wastage', round(v_wastage, 2),
      'unabsorbed', round(v_unabsorbed, 2),
      'varnish_cost', round(v_varnish_cost, 2),
      'selling', round(v_selling, 2),
      'admin', round(v_admin, 2),
      'total_cogs', round(v_total_cogs, 2),
      'revenue', round(v_revenue, 2),
      'other_income', round(v_other_income, 2),
      'revenue_total', round(v_revenue_total, 2),
      'total_expense', round(v_total_expense, 2),
      'gross_profit', round(coalesce(v_gross_profit, 0), 2)
    ),
    'expense_lines', v_expense_lines,
    'layers', jsonb_build_object(
      'l1_conversion', jsonb_build_object(
        'direct_conversion_per_kg', v_direct_conversion_per_kg,
        'factory_overhead_per_kg', v_factory_overhead_per_kg,
        'varnish_per_kg_produced', v_varnish_per_kg_produced,
        'conversion_burden_per_kg_produced', v_conversion_burden_per_kg_produced,
        'admin_per_kg_sold', v_admin_per_kg_sold,
        'selling_per_kg_sold', v_selling_per_kg_sold,
        'commercial_burden_per_kg_sold', v_commercial_burden_per_kg_sold,
        'break_even_watta_pkr_per_kg', v_break_even_watta
      ),
      -- Primary / pricing view: sales COGS + commercial (no period conversion add-on)
      'l2_landed', jsonb_build_object(
        'view', 'sales_cogs',
        'rm_per_kg_sold', v_rm_per_kg_sold,
        'varnish_per_kg_sold', v_varnish_per_kg_sold,
        'rm_burden_per_kg_sold', v_rm_burden_per_kg_sold,
        'conversion_per_kg_produced', null,
        'commercial_per_kg_sold', v_commercial_per_kg_sold,
        'total_landed_per_kg_sold', v_total_landed_per_kg_sold,
        'note', 'Sales COGS already embeds absorbed OH in 51013 — period conversion not added'
      ),
      'l2_sales_cogs', jsonb_build_object(
        'sales_cogs_per_kg_sold', v_rm_per_kg_sold,
        'commercial_per_kg_sold', v_commercial_per_kg_sold,
        'total_sales_landed_per_kg_sold', v_total_sales_landed_per_kg,
        'note', 'Use for GP / pricing; OH embedded in sales COGS components'
      ),
      'l2_cash_period', jsonb_build_object(
        'sales_cogs_per_kg_sold', v_rm_per_kg_sold,
        'period_conversion_per_kg_produced', v_conversion_per_kg_produced,
        'commercial_per_kg_sold', v_commercial_per_kg_sold,
        'total_cash_landed_per_kg', v_total_cash_landed_per_kg,
        'note', 'Cash period optics — may double-count OH vs sales COGS; do not use alone for GP'
      ),
      'l3_margin', jsonb_build_object(
        'revenue_per_kg', v_revenue_per_kg,
        'gross_margin_per_kg', v_gross_margin_per_kg,
        'net_margin_per_kg', v_net_margin_per_kg
      )
    )
  );
end;
$$;


ALTER FUNCTION "erp"."fn_unit_economics"("p_from" "date", "p_to" "date") OWNER TO "postgres";

--
-- Name: fn_upsert_posting_maps_from_registry(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_upsert_posting_maps_from_registry"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_count int := 0;
begin
  insert into erp.posting_account_map (doc_type, line_role, account_code, is_active, effective_from)
  select r.doc_type, r.line_role, r.account_code, true, date '2000-01-01'
  from erp.posting_map_registry r
  where exists (select 1 from erp.coa_accounts c where c.code = r.account_code)
  on conflict (doc_type, line_role, effective_from) do update set
    account_code = excluded.account_code,
    is_active = true;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "erp"."fn_upsert_posting_maps_from_registry"() OWNER TO "postgres";

--
-- Name: fn_user_display_names("uuid"[]); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."fn_user_display_names"("p_user_ids" "uuid"[]) RETURNS TABLE("user_id" "uuid", "display_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    u.uid as user_id,
    coalesce(
      nullif(trim(up.display_name), ''),
      nullif(trim(up.email), ''),
      left(u.uid::text, 8) || '…'
    ) as display_name
  from unnest(coalesce(p_user_ids, '{}'::uuid[])) as u(uid)
  left join erp.user_profiles up on up.user_id = u.uid
  where erp.can_read_masters();
$$;


ALTER FUNCTION "erp"."fn_user_display_names"("p_user_ids" "uuid"[]) OWNER TO "postgres";

--
-- Name: force_delete_sales_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."force_delete_sales_invoice"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc_id uuid;
  v_return_id uuid;
  v_reverted_orders uuid[];
  v_step text := 'init';
  v_cleared_alloc int := 0;
  v_n int;
begin
  perform erp._assert_admin();
  perform erp._assert_posting_access();

  v_step := 'lock_invoice';
  select id into v_doc_id from erp.sales_invoices where id = p_doc_id for update;
  if v_doc_id is null then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', 'sales invoice not found');
  end if;

  v_step := 'clear_payment_allocations';
  for v_return_id in select id from erp.sales_returns where ref_invoice_id = v_doc_id loop
    v_n := erp._clear_ar_payment_allocations_for_doc('sales_return', v_return_id);
    v_cleared_alloc := v_cleared_alloc + v_n;
  end loop;
  v_n := erp._clear_ar_payment_allocations_for_doc('sales_invoice', v_doc_id);
  v_cleared_alloc := v_cleared_alloc + v_n;

  v_step := 'delete_linked_returns';
  for v_return_id in select id from erp.sales_returns where ref_invoice_id = v_doc_id loop
    delete from erp.inventory_movements where source_doc_type = 'sales_return' and source_doc_id = v_return_id;
    delete from erp.ar_documents where source_doc_type = 'sales_return' and source_doc_id = v_return_id;
    perform erp._hard_delete_clear_journals('sales_return', v_return_id);
    delete from erp.sales_returns where id = v_return_id;
  end loop;

  v_step := 'delete_premium_scrap';
  perform erp._hard_delete_premium_scrap_for_sales_invoice(v_doc_id);

  v_step := 'revert_order_fulfillment';
  v_reverted_orders := erp._revert_sales_order_fulfillment_from_invoice(v_doc_id);

  v_step := 'clear_side_effects';
  delete from erp.inventory_movements where source_doc_type = 'sales_invoice' and source_doc_id = v_doc_id;
  delete from erp.ar_documents where source_doc_type = 'sales_invoice' and source_doc_id = v_doc_id;
  perform erp._hard_delete_clear_journals('sales_invoice', v_doc_id);

  v_step := 'delete_header';
  perform set_config('erp.allow_posted_header_delete', '1', true);
  delete from erp.sales_invoices where id = v_doc_id;

  v_step := 'rebuild_inventory';
  begin
    perform erp.rebuild_inventory_balances_for_items(
      coalesce(erp._item_ids_from_inventory_movements('sales_invoice', v_doc_id), '{}')
    );
  exception when others then
    null; -- header is already gone; scoped rebuild best-effort here
  end;

  return jsonb_build_object(
    'ok', true,
    'step', 'done',
    'cleared_payment_allocations', v_cleared_alloc,
    'reverted_sales_order_ids', to_jsonb(v_reverted_orders)
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."force_delete_sales_invoice"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: force_delete_sales_invoice_by_no("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."force_delete_sales_invoice_by_no"("p_invoice_no" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  select id into v_id from erp.sales_invoices where invoice_no = p_invoice_no;
  if v_id is null then
    return jsonb_build_object('ok', false, 'error', 'sales invoice not found', 'invoice_no', p_invoice_no);
  end if;
  return erp.force_delete_sales_invoice(v_id);
end;
$$;


ALTER FUNCTION "erp"."force_delete_sales_invoice_by_no"("p_invoice_no" "text") OWNER TO "postgres";

--
-- Name: get_drawing_labor_rate(integer, "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."get_drawing_labor_rate"("p_gauge_swg" integer, "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS TABLE("base_rate_pkr" numeric, "increment_pkr" numeric, "effective_rate_pkr" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_base numeric;
  v_inc numeric;
  v_override numeric;
begin
  v_base := erp._drawing_base_rate(p_as_of);

  if coalesce(p_gauge_swg, 0) < 33 then
    return query select v_base, 0::numeric, v_base;
    return;
  end if;

  select p.increment_pkr, p.rate_pkr_override
    into v_inc, v_override
  from erp.drawing_labor_premium_rates p
  where p.gauge_swg = p_gauge_swg
    and p.is_active = true
    and p.effective_from <= coalesce(p_as_of, current_date)
  order by p.effective_from desc
  limit 1;

  v_inc := coalesce(v_inc, 0);
  return query select
    v_base,
    v_inc,
    coalesce(v_override, v_base + v_inc);
end;
$$;


ALTER FUNCTION "erp"."get_drawing_labor_rate"("p_gauge_swg" integer, "p_as_of" "date") OWNER TO "postgres";

--
-- Name: get_item_opening_stock("uuid", "uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."get_item_opening_stock"("p_item_id" "uuid", "p_warehouse_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("warehouse_id" "uuid", "warehouse_code" "text", "qty" numeric, "unit_count" numeric, "unit_cost" numeric, "as_of" "date", "value_amount" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select
    im.warehouse_id,
    w.code::text as warehouse_code,
    coalesce(im.qty_in, 0)::numeric as qty,
    coalesce(im.units_in, 0)::numeric as unit_count,
    coalesce(im.unit_cost, 0)::numeric as unit_cost,
    im.posting_date as as_of,
    coalesce(im.value_amount, 0)::numeric as value_amount
  from erp.inventory_movements im
  join erp.warehouses w on w.id = im.warehouse_id
  where im.item_id = p_item_id
    and im.movement_type = 'opening'
    and im.source_doc_type = 'opening_stock'
    and (p_warehouse_id is null or im.warehouse_id = p_warehouse_id)
  order by im.posting_date, w.code;
$$;


ALTER FUNCTION "erp"."get_item_opening_stock"("p_item_id" "uuid", "p_warehouse_id" "uuid") OWNER TO "postgres";

--
-- Name: get_my_login_status(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."get_my_login_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_active boolean := false;
  v_profile_exists boolean := false;
  v_roles text[];
begin
  if v_uid is null then
    return jsonb_build_object(
      'profile_exists', false,
      'is_active', false,
      'roles', '[]'::jsonb
    );
  end if;

  select exists (
      select 1 from erp.user_profiles up where up.user_id = v_uid
    ),
    coalesce((
      select up.is_active from erp.user_profiles up where up.user_id = v_uid
    ), false)
    into v_profile_exists, v_active;

  select coalesce(array_agg(r.code order by r.code), array[]::text[])
    into v_roles
  from erp.user_role_assignments ura
  join erp.roles r on r.id = ura.role_id
  where ura.user_id = v_uid
    and r.code in ('ADMIN', 'ACCOUNTANT');

  return jsonb_build_object(
    'profile_exists', v_profile_exists,
    'is_active', v_active,
    'roles', to_jsonb(v_roles)
  );
end;
$$;


ALTER FUNCTION "erp"."get_my_login_status"() OWNER TO "postgres";

--
-- Name: get_period_costing_preview("date", "date", boolean, numeric, numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."get_period_costing_preview"("p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean DEFAULT true, "p_actual_overhead_rate" numeric DEFAULT NULL::numeric, "p_actual_overhead_amount" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_oh numeric;
  v_fg_kg numeric;
  v_proxy_period erp.costing_periods%rowtype;
  v_amount numeric := p_actual_overhead_amount;
  v_source text := 'manual';
begin
  perform erp._assert_report_access();

  v_fg_kg := erp._pac_period_fg_output_kg(p_start_date, p_end_date);

  if p_is_draft then
    select * into v_proxy_period
    from erp.costing_periods
    where status = 'locked' and actual_overhead_rate is not null and actual_overhead_rate > 0
    order by end_date desc limit 1;

    if found then
      v_oh := v_proxy_period.actual_overhead_rate;
      v_source := 'proxy';
    else
      v_amount := coalesce(erp._pac_auto_overhead_amount(p_start_date, p_end_date), 0);
      if coalesce(v_fg_kg, 0) > 0 and coalesce(v_amount, 0) > 0 then
        v_oh := round(v_amount / v_fg_kg, 6);
        v_source := 'auto_gl';
      else
        v_oh := coalesce(nullif(erp._production_standard_num('live_conversion_rate_fallback'), 0), 0);
        v_source := 'fallback';
      end if;
    end if;
  else
    if coalesce(p_actual_overhead_rate, 0) > 0 then
      v_oh := p_actual_overhead_rate;
      v_source := 'manual_rate';
    else
      if v_amount is null then
        v_amount := coalesce(erp._pac_auto_overhead_amount(p_start_date, p_end_date), 0);
        v_source := 'auto_gl';
      else
        v_source := 'manual_amount';
      end if;
      v_oh := round(v_amount / nullif(v_fg_kg, 0), 6);
    end if;
  end if;

  return jsonb_build_object(
    'fg_output_kg', v_fg_kg,
    'overhead_rate_used', coalesce(v_oh, 0),
    'overhead_amount', v_amount,
    'overhead_amount_source', v_source,
    'proxy_source_period', case when p_is_draft and v_proxy_period.id is not null
                              then v_proxy_period.period_code else null end
  );
end;
$$;


ALTER FUNCTION "erp"."get_period_costing_preview"("p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean, "p_actual_overhead_rate" numeric, "p_actual_overhead_amount" numeric) OWNER TO "postgres";

--
-- Name: hard_delete_factory_scrap_dispatch("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."hard_delete_factory_scrap_dispatch"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.factory_scrap_dispatches%rowtype;
  v_step text := 'init';
begin
  perform erp._assert_posting_access();

  v_step := 'lock';
  select * into v_doc
  from erp.factory_scrap_dispatches
  where id = p_doc_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', 'factory scrap dispatch not found');
  end if;

  if v_doc.status = 'posted' then
    v_step := 'clear_posting';
    perform erp._clear_factory_scrap_dispatch_posting(v_doc.id);
  end if;

  v_step := 'clear_obligation';
  perform erp._clear_factory_scrap_obligation(v_doc.id);

  v_step := 'delete_header';
  delete from erp.factory_scrap_dispatches where id = v_doc.id;

  perform erp.fn_evaluate_production_alerts(v_doc.dispatch_date);

  return jsonb_build_object(
    'ok', true,
    'step', 'done',
    'dispatch_id', v_doc.id,
    'dispatch_no', v_doc.dispatch_no
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', sqlerrm);
end;
$$;


ALTER FUNCTION "erp"."hard_delete_factory_scrap_dispatch"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: hard_delete_inventory_adjustment("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."hard_delete_inventory_adjustment"("p_adjustment_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare v_adj erp.inventory_adjustments%rowtype; v_item_ids uuid[];
begin
  perform erp._assert_posting_access();
  select * into v_adj from erp.inventory_adjustments where id = p_adjustment_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'Inventory adjustment not found'); end if;
  v_item_ids := erp._item_ids_from_inventory_movements('inventory_adjustment', v_adj.id);
  delete from erp.inventory_movements where source_doc_type = 'inventory_adjustment' and source_doc_id = v_adj.id;
  perform erp._hard_delete_clear_journals('inventory_adjustment', v_adj.id);
  delete from erp.inventory_adjustments where id = v_adj.id;
  perform erp._rebuild_after_document_delete(v_item_ids);
  return jsonb_build_object('ok', true, 'id', v_adj.id, 'adjustment_no', v_adj.adjustment_no);
end;
$$;


ALTER FUNCTION "erp"."hard_delete_inventory_adjustment"("p_adjustment_id" "uuid") OWNER TO "postgres";

