--
-- Name: hard_delete_payment("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."hard_delete_payment"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.payments%rowtype;
  v_alloc record;
  v_clr record;
  v_ar erp.ar_documents%rowtype;
  v_ap erp.ap_documents%rowtype;
  v_parchi erp.parchi_instruments%rowtype;
  v_je_ids uuid[];
  v_open numeric;
  v_cleared numeric;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.payments where id = p_doc_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Payment not found');
  end if;

  if v_doc.voided_at is not null then
    return jsonb_build_object('ok', true, 'id', v_doc.id, 'already_voided', true);
  end if;

  if v_doc.posting_status = 'posted' then
    return erp.void_payment(p_doc_id, 'Deleted from cashbook');
  end if;

  for v_clr in select * from erp.parchi_clearances where payment_id = v_doc.id loop
    select * into v_parchi from erp.parchi_instruments where id = v_clr.parchi_id for update;
    if found then
      v_cleared := greatest(0, coalesce(v_parchi.cleared_amount, 0) - coalesce(v_clr.amount, 0));
      v_open := coalesce(v_parchi.total_amount, 0) - v_cleared;
      update erp.parchi_instruments
      set cleared_amount = v_cleared,
          open_amount = v_open,
          status = case
            when v_open <= 0.01 then 'cleared'
            when v_cleared > 0 then 'partial'
            else 'open'
          end
      where id = v_parchi.id;
    end if;
  end loop;
  delete from erp.parchi_clearances where payment_id = v_doc.id;

  for v_alloc in select * from erp.payment_allocations where payment_id = v_doc.id loop
    if v_alloc.ar_document_id is not null then
      select * into v_ar from erp.ar_documents where id = v_alloc.ar_document_id for update;
      if found then
        v_open := least(
          coalesce(v_ar.amount, 0),
          coalesce(v_ar.open_amount, 0) + coalesce(v_alloc.allocated_amount, 0)
        );
        update erp.ar_documents
        set open_amount = v_open,
            status = case
              when v_open <= 0.01 then 'settled'
              when v_open >= coalesce(v_ar.amount, 0) - 0.01 then 'open'
              else 'partially_settled'
            end
        where id = v_ar.id;
      end if;
    end if;
    if v_alloc.ap_document_id is not null then
      select * into v_ap from erp.ap_documents where id = v_alloc.ap_document_id for update;
      if found then
        v_open := least(
          coalesce(v_ap.amount, 0),
          coalesce(v_ap.open_amount, 0) + coalesce(v_alloc.allocated_amount, 0)
        );
        update erp.ap_documents
        set open_amount = v_open,
            status = case
              when v_open <= 0.01 then 'settled'
              when v_open >= coalesce(v_ap.amount, 0) - 0.01 then 'open'
              else 'partially_settled'
            end
        where id = v_ap.id;
      end if;
    end if;
  end loop;
  delete from erp.payment_allocations where payment_id = v_doc.id;

  select array_agg(id) into v_je_ids
  from erp.journal_entries
  where source_doc_type = 'payment' and source_doc_id = v_doc.id;
  if coalesce(array_length(v_je_ids, 1), 0) > 0 then
    delete from erp.journal_lines where journal_entry_id = any(v_je_ids);
    delete from erp.journal_entries where id = any(v_je_ids);
  end if;

  delete from erp.payments where id = v_doc.id;
  return jsonb_build_object('ok', true, 'id', v_doc.id, 'action', 'hard_deleted');
end;
$$;


ALTER FUNCTION "erp"."hard_delete_payment"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: hard_delete_purchase_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."hard_delete_purchase_invoice"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc_id uuid;
  v_return_id uuid;
  v_reverted_orders uuid[];
  v_step text := 'init';
  v_item_ids uuid[] := '{}';
begin
  perform erp._assert_posting_access();

  v_step := 'lock_invoice';
  select id into v_doc_id from erp.purchase_invoices where id = p_doc_id for update;
  if v_doc_id is null then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', 'purchase invoice not found');
  end if;

  v_item_ids := erp._item_ids_from_inventory_movements('purchase_invoice', v_doc_id);

  v_step := 'check_payments';
  if exists (
    select 1
    from erp.ap_documents ad
    join erp.payment_allocations pa on pa.ap_document_id = ad.id
    where ad.source_doc_type = 'purchase_invoice' and ad.source_doc_id = v_doc_id
  ) then
    return jsonb_build_object(
      'ok', false,
      'step', v_step,
      'error', 'cannot delete: invoice has payment allocations — clear cashbook allocations first'
    );
  end if;

  v_step := 'delete_linked_returns';
  for v_return_id in select id from erp.purchase_returns where ref_invoice_id = v_doc_id loop
    v_item_ids := erp._merge_item_id_arrays(
      v_item_ids,
      erp._item_ids_from_inventory_movements('purchase_return', v_return_id)
    );
    perform erp._void_pending_rate_items_for_doc('purchase_return', v_return_id);
    delete from erp.inventory_movements where source_doc_type = 'purchase_return' and source_doc_id = v_return_id;
    delete from erp.ap_documents where source_doc_type = 'purchase_return' and source_doc_id = v_return_id;
    perform erp._hard_delete_clear_journals('purchase_return', v_return_id);
    delete from erp.purchase_returns where id = v_return_id;
  end loop;

  v_step := 'revert_order_receiving';
  v_reverted_orders := erp._revert_purchase_order_receiving_from_invoice(v_doc_id);

  v_step := 'void_pending_rates';
  perform erp._void_pending_rate_items_for_doc('purchase_invoice', v_doc_id);

  v_step := 'revert_premium_scrap_pool';
  perform erp._revert_premium_purchase_scrap_pool(v_doc_id);

  v_step := 'clear_side_effects';
  delete from erp.inventory_movements where source_doc_type = 'purchase_invoice' and source_doc_id = v_doc_id;
  delete from erp.ap_documents where source_doc_type = 'purchase_invoice' and source_doc_id = v_doc_id;
  perform erp._hard_delete_clear_journals('purchase_invoice', v_doc_id);

  v_step := 'delete_header';
  perform set_config('erp.allow_posted_header_delete', '1', true);
  delete from erp.purchase_invoices where id = v_doc_id;

  v_step := 'rebuild_inventory';
  perform erp._rebuild_after_document_delete(v_item_ids);

  return jsonb_build_object('ok', true, 'step', 'done', 'reverted_purchase_order_ids', to_jsonb(v_reverted_orders));
exception
  when others then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."hard_delete_purchase_invoice"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: hard_delete_purchase_return("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."hard_delete_purchase_return"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_returns%rowtype;
  v_je_ids uuid[];
  v_item_ids uuid[];
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.purchase_returns where id = p_doc_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'Purchase return not found'); end if;

  v_item_ids := erp._item_ids_from_inventory_movements('purchase_return', v_doc.id);

  perform erp._void_pending_rate_items_for_doc('purchase_return', v_doc.id);
  delete from erp.inventory_movements where source_doc_type = 'purchase_return' and source_doc_id = v_doc.id;
  delete from erp.ap_documents where source_doc_type = 'purchase_return' and source_doc_id = v_doc.id;
  select array_agg(id) into v_je_ids from erp.journal_entries where source_doc_type = 'purchase_return' and source_doc_id = v_doc.id;
  if coalesce(array_length(v_je_ids, 1), 0) > 0 then
    delete from erp.journal_lines where journal_entry_id = any(v_je_ids);
    delete from erp.journal_entries where id = any(v_je_ids);
  end if;
  delete from erp.purchase_returns where id = v_doc.id;

  perform erp._rebuild_after_document_delete(v_item_ids);
  return jsonb_build_object('ok', true, 'id', v_doc.id);
end;
$$;


ALTER FUNCTION "erp"."hard_delete_purchase_return"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: hard_delete_sales_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."hard_delete_sales_invoice"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc_id uuid;
  v_return_id uuid;
  v_reverted_orders uuid[];
  v_step text := 'init';
  v_cleared_alloc int := 0;
  v_item_ids uuid[] := '{}';
begin
  perform erp._assert_posting_access();

  v_step := 'lock_invoice';
  select id into v_doc_id from erp.sales_invoices where id = p_doc_id for update;
  if v_doc_id is null then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', 'sales invoice not found');
  end if;

  v_item_ids := erp._item_ids_from_inventory_movements('sales_invoice', v_doc_id);

  v_step := 'check_payments';
  if exists (
    select 1
    from erp.ar_documents ad
    join erp.payment_allocations pa on pa.ar_document_id = ad.id
    where ad.source_doc_type = 'sales_invoice' and ad.source_doc_id = v_doc_id
  ) then
    return jsonb_build_object(
      'ok', false,
      'step', v_step,
      'error', 'cannot delete: invoice has payment allocations — use erp.force_delete_sales_invoice or clear cashbook allocations first',
      'hint', 'select erp.diagnose_sales_invoice_delete(invoice_no) for payment_no list'
    );
  end if;

  v_step := 'delete_linked_returns';
  for v_return_id in select id from erp.sales_returns where ref_invoice_id = v_doc_id loop
    v_item_ids := erp._merge_item_id_arrays(
      v_item_ids,
      erp._item_ids_from_inventory_movements('sales_return', v_return_id)
    );
    perform erp._void_pending_rate_items_for_doc('sales_return', v_return_id);
    perform erp._clear_ar_payment_allocations_for_doc('sales_return', v_return_id);
    delete from erp.inventory_movements where source_doc_type = 'sales_return' and source_doc_id = v_return_id;
    delete from erp.ar_documents where source_doc_type = 'sales_return' and source_doc_id = v_return_id;
    perform erp._hard_delete_clear_journals('sales_return', v_return_id);
    delete from erp.sales_returns where id = v_return_id;
  end loop;

  v_step := 'delete_premium_scrap';
  perform erp._hard_delete_premium_scrap_for_sales_invoice(v_doc_id);

  v_step := 'revert_order_fulfillment';
  v_reverted_orders := erp._revert_sales_order_fulfillment_from_invoice(v_doc_id);

  v_step := 'void_pending_rates';
  perform erp._void_pending_rate_items_for_doc('sales_invoice', v_doc_id);

  v_step := 'clear_side_effects';
  delete from erp.inventory_movements where source_doc_type = 'sales_invoice' and source_doc_id = v_doc_id;
  delete from erp.ar_documents where source_doc_type = 'sales_invoice' and source_doc_id = v_doc_id;
  perform erp._hard_delete_clear_journals('sales_invoice', v_doc_id);

  v_step := 'delete_header';
  perform set_config('erp.allow_posted_header_delete', '1', true);
  delete from erp.sales_invoices where id = v_doc_id;

  v_step := 'rebuild_inventory';
  perform erp._rebuild_after_document_delete(v_item_ids);

  return jsonb_build_object(
    'ok', true,
    'step', 'done',
    'cleared_payment_allocations', v_cleared_alloc,
    'reverted_sales_order_ids', to_jsonb(v_reverted_orders)
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."hard_delete_sales_invoice"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: hard_delete_sales_return("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."hard_delete_sales_return"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_returns%rowtype;
  v_je_ids uuid[];
  v_item_ids uuid[];
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.sales_returns where id = p_doc_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'Sales return not found'); end if;

  v_item_ids := erp._item_ids_from_inventory_movements('sales_return', v_doc.id);

  perform erp._void_pending_rate_items_for_doc('sales_return', v_doc.id);
  delete from erp.inventory_movements where source_doc_type = 'sales_return' and source_doc_id = v_doc.id;
  delete from erp.ar_documents where source_doc_type = 'sales_return' and source_doc_id = v_doc.id;
  select array_agg(id) into v_je_ids from erp.journal_entries where source_doc_type = 'sales_return' and source_doc_id = v_doc.id;
  if coalesce(array_length(v_je_ids, 1), 0) > 0 then
    delete from erp.journal_lines where journal_entry_id = any(v_je_ids);
    delete from erp.journal_entries where id = any(v_je_ids);
  end if;
  delete from erp.sales_returns where id = v_doc.id;

  perform erp._rebuild_after_document_delete(v_item_ids);
  return jsonb_build_object('ok', true, 'id', v_doc.id);
end;
$$;


ALTER FUNCTION "erp"."hard_delete_sales_return"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: hard_delete_scrap_receipt("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."hard_delete_scrap_receipt"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_receipts%rowtype;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.scrap_receipts where id = p_doc_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Scrap receipt not found');
  end if;

  if v_doc.status = 'posted' then
    update erp.scrap_receivable_obligations
    set received_kg = greatest(received_kg - v_doc.net_weight, 0)
    where id = v_doc.obligation_id;
    perform erp._sync_scrap_obligation_status(v_doc.obligation_id);

    delete from erp.inventory_movements
    where source_doc_type = 'scrap_receipt' and source_doc_id = v_doc.id;
  end if;

  delete from erp.scrap_receipts where id = v_doc.id;
  return jsonb_build_object('ok', true, 'id', v_doc.id);
end;
$$;


ALTER FUNCTION "erp"."hard_delete_scrap_receipt"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: hard_delete_scrap_trade("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."hard_delete_scrap_trade"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_trades%rowtype;
  v_receipt_id uuid;
  v_item_ids uuid[];
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.scrap_trades where id = p_doc_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'Scrap trade not found'); end if;
  if v_doc.status = 'posted' then
    return erp.void_scrap_trade(p_doc_id, 'Voided via hard_delete_scrap_trade');
  end if;
  v_item_ids := erp._item_ids_from_inventory_movements('scrap_trade', v_doc.id);
  for v_receipt_id in
    select id from erp.scrap_receipts where scrap_trade_id = v_doc.id
  loop
    perform erp.hard_delete_scrap_receipt(v_receipt_id);
  end loop;
  perform erp._void_pending_rate_items_for_doc('scrap_trade', v_doc.id);
  delete from erp.inventory_movements where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id;
  delete from erp.ap_documents where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id;
  delete from erp.ar_documents where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id;
  perform erp._hard_delete_clear_journals('scrap_trade', v_doc.id);
  delete from erp.scrap_trades where id = v_doc.id;
  perform erp._rebuild_after_document_delete(v_item_ids);
  return jsonb_build_object('ok', true, 'id', v_doc.id, 'action', 'deleted');
end;
$$;


ALTER FUNCTION "erp"."hard_delete_scrap_trade"("p_doc_id" "uuid") OWNER TO "postgres";

