--
-- Name: has_permission("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."has_permission"("p_permission_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_permission_id uuid;
  v_override boolean;
begin
  if erp.has_role('ADMIN') then
    return true;  -- has_role already requires is_active
  end if;

  if not exists (
    select 1 from erp.user_profiles up
    where up.user_id = auth.uid() and up.is_active = true
  ) then
    return false;
  end if;

  select id into v_permission_id from erp.permissions where code = p_permission_code limit 1;
  if v_permission_id is null then return false; end if;

  select upm.is_allowed into v_override
  from erp.user_permissions upm
  where upm.user_id = auth.uid()
    and upm.permission_id = v_permission_id
  limit 1;
  if v_override is not null then return v_override; end if;

  return exists (
    select 1
    from erp.user_role_assignments ura
    join erp.role_permissions rp
      on rp.role_id = ura.role_id
     and rp.permission_id = v_permission_id
    where ura.user_id = auth.uid()
  );
end;
$$;


ALTER FUNCTION "erp"."has_permission"("p_permission_code" "text") OWNER TO "postgres";

--
-- Name: has_role("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."has_role"("p_role_code" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
  select exists (
    select 1
    from erp.user_profiles up
    join erp.user_role_assignments ura on ura.user_id = up.user_id
    join erp.roles r on r.id = ura.role_id
    where up.user_id = auth.uid()
      and up.is_active = true
      and r.code = upper(p_role_code)
  )
$$;


ALTER FUNCTION "erp"."has_role"("p_role_code" "text") OWNER TO "postgres";

--
-- Name: is_session_live(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."is_session_live"() RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_claims json;
  v_session_id text;
begin
  begin
    v_claims := nullif(current_setting('request.jwt.claims', true), '')::json;
  exception when others then
    v_claims := null;
  end;
  if v_claims is null then
    return true;
  end if;

  v_session_id := nullif(v_claims ->> 'session_id', '');
  if v_session_id is null then
    return true;
  end if;

  return exists (
    select 1
    from auth.sessions s
    where s.id = v_session_id::uuid
      and (s.not_after is null or s.not_after > now())
  );
exception
  when others then
    return true;
end;
$$;


ALTER FUNCTION "erp"."is_session_live"() OWNER TO "postgres";

