--
-- Name: next_factory_scrap_dispatch_no("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."next_factory_scrap_dispatch_no"("p_prefix" "text" DEFAULT 'FSD-'::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $_$
declare
  v_prefix text := coalesce(nullif(trim(p_prefix), ''), 'FSD-');
  v_max_seq int := 0;
  v_no text;
  v_suffix text;
begin
  for v_no in
    select dispatch_no from erp.factory_scrap_dispatches where dispatch_no ilike v_prefix || '%'
  loop
    v_suffix := regexp_replace(v_no, '^.*-', '');
    if v_suffix ~ '^\d+$' then
      v_max_seq := greatest(v_max_seq, v_suffix::int);
    end if;
  end loop;
  return v_prefix || lpad((v_max_seq + 1)::text, 4, '0');
end;
$_$;


ALTER FUNCTION "erp"."next_factory_scrap_dispatch_no"("p_prefix" "text") OWNER TO "postgres";

