--
-- Name: post_drawing_weekly_wage_sheet("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_drawing_weekly_wage_sheet"("p_sheet_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_sheet erp.drawing_weekly_wage_sheets%rowtype;
  v_received numeric;
  v_scrap numeric;
  v_totals record;
begin
  perform erp._drawing_wage_post_access();

  select * into v_sheet from erp.drawing_weekly_wage_sheets where id = p_sheet_id for update;
  if not found then raise exception 'Wage sheet not found'; end if;
  if v_sheet.status = 'posted' then return; end if;

  v_received := coalesce(v_sheet.wire8_received_override, v_sheet.wire8_received_kg);
  v_scrap := coalesce(v_sheet.wire8_scrap_override, v_sheet.wire8_scrap_kg);

  select * into v_totals
  from erp._compute_drawing_sheet_totals(v_received, v_scrap, v_sheet.base_rate_pkr, p_sheet_id);

  update erp.drawing_weekly_wage_sheets s
  set
    status = 'posted',
    net_wire8_kg = v_totals.net_kg,
    base_wage_pkr = v_totals.base_wage,
    premium_wage_pkr = v_totals.premium_wage,
    total_wage_pkr = v_totals.total_wage,
    posted_at = now(),
    posted_by = auth.uid(),
    updated_at = now()
  where s.id = p_sheet_id;
end;
$$;


ALTER FUNCTION "erp"."post_drawing_weekly_wage_sheet"("p_sheet_id" "uuid") OWNER TO "postgres";

--
-- Name: post_factory_scrap_dispatch("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_factory_scrap_dispatch"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.factory_scrap_dispatches%rowtype;
  v_line record;
  v_rm_wh uuid;
  v_je_id uuid;
  v_ar_acct text;
  v_rev_acct text;
  v_wastage_acct text;
  v_inv_rm_acct text;
  v_amount numeric;
  v_unit_cost numeric;
  v_ln int := 0;
  v_line_sum numeric;
  v_item_ids uuid[] := '{}';
  v_obl_no text;
  v_parent_rm uuid;
  v_parent_mov_id uuid;
  v_parent_wac numeric;
  v_backflush_value numeric;
  v_total_backflush numeric := 0;
  v_on_hand numeric;
  v_machine_ids uuid[];
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.factory_scrap_dispatches where id = doc_id for update;
  if not found then raise exception 'factory scrap dispatch not found'; end if;
  if v_doc.status = 'posted' then return; end if;
  if coalesce(v_doc.net_weight, 0) <= 0 then
    raise exception 'dispatch requires positive net weight';
  end if;

  select coalesce(sum(fsl.net_weight), 0) into v_line_sum
  from erp.factory_scrap_dispatch_lines fsl where fsl.dispatch_id = v_doc.id;
  if v_line_sum <= 0 then raise exception 'dispatch requires at least one line'; end if;
  if abs(v_line_sum - v_doc.net_weight) > 0.5 then
    raise exception 'line total % kg must match header net % kg', round(v_line_sum, 3), round(v_doc.net_weight, 3);
  end if;

  select id into v_rm_wh from erp.warehouses
  where wh_type = 'raw_material' and is_active = true order by code limit 1;
  if v_rm_wh is null then raise exception 'raw material warehouse not configured'; end if;

  for v_line in select * from erp.factory_scrap_dispatch_lines where dispatch_id = v_doc.id order by line_no loop
    if v_line.machine_id is null then raise exception 'line % requires machine', v_line.line_no; end if;
    if coalesce(v_line.net_weight, 0) <= 0 then raise exception 'line % requires positive weight', v_line.line_no; end if;
  end loop;

  select coalesce(array_agg(distinct fsl.machine_id), '{}')
  into v_machine_ids
  from erp.factory_scrap_dispatch_lines fsl
  where fsl.dispatch_id = v_doc.id;

  v_amount := round(coalesce(nullif(v_doc.amount, 0), v_doc.net_weight * coalesce(nullif(v_doc.unit_rate, 0), 0)), 3);

  v_wastage_acct := erp._resolve_posting_account('factory_scrap_dispatch', 'wastage');
  v_inv_rm_acct := erp._resolve_posting_account('factory_scrap_dispatch', 'inventory_rm');

  for v_line in select * from erp.factory_scrap_dispatch_lines where dispatch_id = v_doc.id order by line_no loop
    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id, qty_in, unit_cost, value_amount,
      source_doc_type, source_doc_id, source_line_id, party_id, reference_no
    ) values (
      v_doc.dispatch_date, 'scrap_in', v_line.item_id, v_rm_wh, v_line.net_weight, 0, 0,
      'factory_scrap_dispatch', v_doc.id, v_line.id, v_doc.dest_party_id, v_doc.dispatch_no
    );

    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id, qty_out, unit_cost, value_amount,
      source_doc_type, source_doc_id, source_line_id, party_id, reference_no
    ) values (
      v_doc.dispatch_date, 'scrap_out', v_line.item_id, v_rm_wh, v_line.net_weight, 0, 0,
      'factory_scrap_dispatch', v_doc.id, v_line.id, v_doc.dest_party_id, v_doc.dispatch_no
    );

    v_item_ids := array_append(v_item_ids, v_line.item_id);

    v_parent_rm := erp._scrap_backflush_parent_rm(
      v_line.department,
      v_doc.dispatch_date,
      case when v_doc.mode = 'toll' then v_doc.expected_return_item_id else null end
    );
    if v_parent_rm is null then
      raise exception 'line %: cannot resolve parent RM for department %', v_line.line_no, v_line.department;
    end if;

    select coalesce(sum(ib.on_hand_qty), 0) into v_on_hand
    from erp.inventory_balances ib
    where ib.item_id = v_parent_rm
      and ib.warehouse_id = v_rm_wh;
    if v_on_hand + 0.001 < v_line.net_weight then
      raise exception
        'line %: insufficient parent RM stock for backflush (need % kg, on hand % kg)',
        v_line.line_no, round(v_line.net_weight, 3), round(v_on_hand, 3);
    end if;

    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id, qty_out, unit_cost, value_amount,
      source_doc_type, source_doc_id, source_line_id, party_id, reference_no
    ) values (
      v_doc.dispatch_date, 'production_issue', v_parent_rm, v_rm_wh, v_line.net_weight, 0, 0,
      'factory_scrap_dispatch', v_doc.id, v_line.id, v_doc.dest_party_id, v_doc.dispatch_no
    )
    returning id into v_parent_mov_id;

    v_parent_wac := erp._inventory_wac_before_movement(v_parent_mov_id);
    if coalesce(v_parent_wac, 0) = 0 then
      v_parent_wac := erp._inventory_replay_current_wac(v_parent_rm, v_rm_wh);
    end if;
    v_parent_wac := coalesce(v_parent_wac, 0);
    v_backflush_value := round(v_line.net_weight * v_parent_wac, 3);

    update erp.inventory_movements
    set unit_cost = v_parent_wac,
        value_amount = v_backflush_value
    where id = v_parent_mov_id;

    update erp.inventory_movements
    set unit_cost = v_parent_wac,
        value_amount = v_backflush_value
    where source_doc_type = 'factory_scrap_dispatch'
      and source_doc_id = v_doc.id
      and source_line_id = v_line.id
      and movement_type in ('scrap_in', 'scrap_out');

    v_total_backflush := v_total_backflush + v_backflush_value;
    v_item_ids := array_append(v_item_ids, v_parent_rm);
  end loop;

  v_total_backflush := round(v_total_backflush, 3);

  if v_total_backflush > 0 or (v_doc.mode = 'sale' and v_amount > 0) then
    v_ar_acct := null;
    v_rev_acct := null;
    if v_doc.mode = 'sale' and v_amount > 0 then
      v_ar_acct := erp._resolve_posting_account('factory_scrap_dispatch', 'ar');
      v_rev_acct := erp._resolve_posting_account('factory_scrap_dispatch', 'revenue');
    end if;

    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
    ) values (
      v_doc.dispatch_no,
      case when v_doc.mode = 'sale' then 'FACTORY_SCRAP_SALE' else 'FACTORY_SCRAP_TOLL' end,
      v_doc.dispatch_date, 'factory_scrap_dispatch', v_doc.id, v_doc.dispatch_no,
      coalesce(v_doc.remarks, 'Factory scrap dispatch (backflush)'), 'posted', now(), auth.uid()
    ) returning id into v_je_id;

    if v_doc.mode = 'sale' and v_amount > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ar_acct, v_doc.dest_party_id, v_amount, 0, 'Scrap sale receivable');
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_rev_acct, null, 0, v_amount, 'Scrap sale revenue');
    end if;

    if v_total_backflush > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_wastage_acct, null, v_total_backflush, 0, 'Scrap / wastage COGS (parent RM WAC)');
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_inv_rm_acct, null, 0, v_total_backflush, 'RM inventory backflush');
    end if;

    if v_doc.mode = 'sale' and v_amount > 0 then
      insert into erp.ar_documents (
        party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status
      ) values (
        v_doc.dest_party_id, 'factory_scrap_dispatch', v_doc.id, v_doc.dispatch_no,
        v_doc.dispatch_date, v_doc.dispatch_date, v_amount, v_amount, 'open'
      ) on conflict (source_doc_type, source_doc_id, party_id) do nothing;
    end if;
  end if;

  if v_doc.mode = 'toll' then
    if v_doc.expected_return_item_id is null then
      raise exception 'toll dispatch requires expected return item (Wire No 8 / Rod)';
    end if;
    v_obl_no := 'SCO-' || replace(v_doc.dispatch_no, 'FSD-', '');
    insert into erp.scrap_conversion_obligations (
      obligation_no, dispatch_id, dest_party_id, expected_item_id, expected_kg, returned_kg, status, remarks
    ) values (
      v_obl_no, v_doc.id, v_doc.dest_party_id, v_doc.expected_return_item_id,
      coalesce(nullif(v_doc.expected_return_kg, 0), v_doc.net_weight), 0, 'open',
      coalesce(v_doc.remarks, 'Factory scrap toll conversion')
    ) on conflict (dispatch_id) do update set
      expected_kg = excluded.expected_kg,
      expected_item_id = excluded.expected_item_id;
  end if;

  update erp.factory_scrap_dispatches
  set status = 'posted', posted_at = now(), posted_by = auth.uid(), amount = v_amount
  where id = v_doc.id;

  if v_doc.mode = 'toll' then
    perform erp._create_scrap_lot_from_factory_dispatch(v_doc.id);
  end if;

  if array_length(v_item_ids, 1) > 0 then
    perform erp.rebuild_inventory_balances_for_items(
      (select coalesce(array_agg(distinct x), '{}') from unnest(v_item_ids) x)
    );
  end if;
  perform erp.fn_evaluate_production_alerts(
    erp._production_alert_eval_as_of(v_doc.dispatch_date, v_machine_ids)
  );
end;
$$;


ALTER FUNCTION "erp"."post_factory_scrap_dispatch"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: post_inventory_adjustment("jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_inventory_adjustment"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item_code text;
  v_wh_type text;
  v_direction text;
  v_posting_date date;
  v_qty numeric;
  v_units numeric;
  v_remarks text;
  v_item erp.items%rowtype;
  v_wh_id uuid;
  v_adj_id uuid;
  v_adj_no text;
  v_unit_cost numeric;
  v_value numeric;
  v_on_hand numeric;
  v_on_hand_units numeric;
  v_section text;
  v_tracks_units boolean := false;
begin
  perform erp._assert_posting_access();

  v_item_code := nullif(trim(p_payload->>'item_code'), '');
  v_wh_type := nullif(trim(p_payload->>'warehouse_type'), '');
  v_remarks := nullif(trim(p_payload->>'remarks'), '');

  v_direction := lower(coalesce(nullif(trim(p_payload->>'direction'), ''), ''));
  if v_direction in ('reduce', 'shortage', 'loss', 'out') then
    v_direction := 'out';
  elsif v_direction in ('increase', 'found', 'gain', 'in') then
    v_direction := 'in';
  end if;

  if v_direction not in ('in', 'out') then
    return jsonb_build_object('ok', false, 'error', 'direction must be in/out (or increase/reduce)');
  end if;

  v_posting_date := coalesce((p_payload->>'adjustment_date')::date, (p_payload->>'posting_date')::date, current_date);
  v_qty := coalesce((p_payload->>'qty_kg')::numeric, (p_payload->>'quantity_kg')::numeric, (p_payload->>'qty')::numeric, 0);
  v_units := coalesce((p_payload->>'unit_count')::numeric, (p_payload->>'units')::numeric, 0);

  if v_item_code is null then
    return jsonb_build_object('ok', false, 'error', 'item_code is required');
  end if;
  if v_wh_type is null then
    return jsonb_build_object('ok', false, 'error', 'warehouse_type is required');
  end if;
  if coalesce(v_qty, 0) <= 0 then
    return jsonb_build_object('ok', false, 'error', 'qty_kg must be greater than zero');
  end if;

  select * into v_item
  from erp.items
  where code = v_item_code
    and coalesce(is_active, true)
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'error', format('Item not found: %s', v_item_code));
  end if;

  select id into v_wh_id
  from erp.warehouses
  where wh_type = v_wh_type
    and coalesce(is_active, true)
  order by code
  limit 1;

  if v_wh_id is null then
    return jsonb_build_object('ok', false, 'error', format('Warehouse not found for type %s', v_wh_type));
  end if;

  v_section := erp._item_inventory_section(v_item.id);
  v_tracks_units := v_section in (
      'fg_enameled',
      'fg_strip',
      'fg_copper_wire',
      'rm_scrap',
      'rm_wire8',
      'rm_rod',
      'varnish'
    )
    or v_item.inventory_group = 'packing_material'
    or erp._is_varnish_item(v_item.id);

  if v_direction = 'out' then
    v_on_hand := erp._inventory_on_hand(v_item.id, v_wh_id);
    if v_on_hand + 0.001 < v_qty then
      return jsonb_build_object(
        'ok', false,
        'error', format(
          'Insufficient stock for %s: need %s kg, on hand %s kg',
          v_item_code,
          trim(to_char(v_qty, 'FM999999990.999')),
          trim(to_char(v_on_hand, 'FM999999990.999'))
        )
      );
    end if;

    if v_tracks_units and coalesce(v_units, 0) > 0 then
      v_on_hand_units := erp._inventory_on_hand_units(v_item.id, v_wh_id);
      if v_on_hand_units + 0.001 < v_units then
        return jsonb_build_object(
          'ok', false,
          'error', format(
            'Insufficient units for %s: need %s, on hand %s',
            v_item_code,
            trim(to_char(v_units, 'FM999999990.999')),
            trim(to_char(v_on_hand_units, 'FM999999990.999'))
          )
        );
      end if;
    end if;
  end if;

  v_unit_cost := erp._resolve_adjustment_unit_cost(v_item.id, v_wh_id, v_direction, v_posting_date);
  v_value := round(v_qty * coalesce(v_unit_cost, 0), 3);

  if v_direction = 'out' and v_value <= 0 then
    return jsonb_build_object(
      'ok', false,
      'error', format('Cannot post adjustment out for %s: unit cost is zero', v_item_code)
    );
  end if;

  v_adj_no := erp.next_inventory_adjustment_no('ADJ-');
  v_adj_id := gen_random_uuid();

  insert into erp.inventory_adjustments (
    id, adjustment_no, posting_date, item_id, warehouse_id, direction,
    qty_kg, unit_count, unit_cost, value_amount, remarks, status, posted_at, posted_by, created_by
  ) values (
    v_adj_id, v_adj_no, v_posting_date, v_item.id, v_wh_id, v_direction,
    v_qty, greatest(coalesce(v_units, 0), 0), v_unit_cost, v_value, v_remarks,
    'posted', now(), auth.uid(), auth.uid()
  );

  if v_direction = 'out' then
    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id,
      qty_out, units_out, unit_cost, value_amount,
      source_doc_type, source_doc_id, reference_no
    ) values (
      v_posting_date, 'adjustment_out', v_item.id, v_wh_id,
      v_qty,
      case when v_tracks_units and coalesce(v_units, 0) > 0 then v_units else 0 end,
      v_unit_cost, v_value,
      'inventory_adjustment', v_adj_id, v_adj_no
    );
  else
    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id,
      qty_in, units_in, unit_cost, value_amount,
      source_doc_type, source_doc_id, reference_no
    ) values (
      v_posting_date, 'adjustment_in', v_item.id, v_wh_id,
      v_qty,
      case
        when v_tracks_units and coalesce(v_units, 0) > 0 then v_units
        when v_tracks_units and erp._is_varnish_item(v_item.id) then erp._varnish_units_from_kg(v_item.id, v_qty)
        else 0
      end,
      v_unit_cost, v_value,
      'inventory_adjustment', v_adj_id, v_adj_no
    );
  end if;

  if v_value > 0 then
    perform erp._sync_inventory_adjustment_gl(v_adj_id, v_direction, v_value, v_remarks);
  end if;

  perform erp._rebuild_after_document_post(array[v_item.id]);

  return jsonb_build_object(
    'ok', true,
    'adjustment_id', v_adj_id,
    'adjustment_no', v_adj_no,
    'direction', v_direction,
    'item_code', v_item.code,
    'warehouse_type', v_wh_type,
    'qty_kg', v_qty,
    'unit_count', v_units,
    'unit_cost', v_unit_cost,
    'value_amount', v_value
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$$;


ALTER FUNCTION "erp"."post_inventory_adjustment"("p_payload" "jsonb") OWNER TO "postgres";

--
-- Name: post_journal_voucher("jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_journal_voucher"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_posting_date date;
  v_reference text;
  v_narration text;
  v_lines jsonb;
  v_line jsonb;
  v_idx int := 0;
  v_line_count int;
  v_account_code text;
  v_party_id uuid;
  v_party_code text;
  v_debit numeric;
  v_credit numeric;
  v_remarks text;
  v_coa erp.coa_accounts%rowtype;
  v_total_debit numeric := 0;
  v_total_credit numeric := 0;
  v_voucher_id uuid;
  v_voucher_no text;
  v_je_id uuid;
begin
  perform erp._assert_posting_access();

  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    return jsonb_build_object('ok', false, 'error', 'payload is required');
  end if;

  v_posting_date := coalesce(
    (p_payload->>'posting_date')::date,
    (p_payload->>'postingDate')::date,
    current_date
  );
  v_reference := nullif(trim(coalesce(p_payload->>'reference_no', p_payload->>'voucher_no', p_payload->>'referenceNo', '')), '');
  v_narration := nullif(trim(coalesce(p_payload->>'narration', '')), '');
  v_lines := coalesce(p_payload->'lines', '[]'::jsonb);

  if jsonb_typeof(v_lines) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'lines must be an array');
  end if;

  v_line_count := jsonb_array_length(v_lines);
  if v_line_count < 2 then
    return jsonb_build_object('ok', false, 'error', 'At least two journal lines are required');
  end if;

  -- First pass: validate lines and compute totals
  for v_line in select value from jsonb_array_elements(v_lines) as t(value)
  loop
    v_idx := v_idx + 1;
    v_account_code := nullif(trim(coalesce(v_line->>'account_code', v_line->>'accountCode', '')), '');
    v_party_code := nullif(trim(coalesce(v_line->>'party_code', v_line->>'partyCode', '')), '');
    v_party_id := nullif(trim(coalesce(v_line->>'party_id', v_line->>'partyId', '')), '')::uuid;
    v_debit := coalesce((v_line->>'debit')::numeric, (v_line->>'debit_amount')::numeric, 0);
    v_credit := coalesce((v_line->>'credit')::numeric, (v_line->>'credit_amount')::numeric, 0);
    v_remarks := nullif(trim(coalesce(v_line->>'remarks', v_line->>'line_description', '')), '');

    if v_account_code is null then
      return jsonb_build_object('ok', false, 'error', format('Line %s: account_code is required', v_idx));
    end if;

    if v_debit < 0 or v_credit < 0 then
      return jsonb_build_object('ok', false, 'error', format('Line %s: debit and credit must be >= 0', v_idx));
    end if;

    if v_debit > 0 and v_credit > 0 then
      return jsonb_build_object('ok', false, 'error', format('Line %s: cannot have both debit and credit', v_idx));
    end if;

    if v_debit = 0 and v_credit = 0 then
      return jsonb_build_object('ok', false, 'error', format('Line %s: debit or credit must be greater than zero', v_idx));
    end if;

    select * into v_coa
    from erp.coa_accounts
    where code = v_account_code
    limit 1;

    if not found then
      return jsonb_build_object('ok', false, 'error', format('Line %s: account not found: %s', v_idx, v_account_code));
    end if;

    if coalesce(v_coa.is_active, true) = false then
      return jsonb_build_object('ok', false, 'error', format('Line %s: account %s is inactive', v_idx, v_account_code));
    end if;

    if coalesce(v_coa.is_group, false) = true or coalesce(v_coa.is_posting, true) = false then
      return jsonb_build_object('ok', false, 'error', format('Line %s: account %s is not a postable leaf', v_idx, v_account_code));
    end if;

    if v_party_id is null and v_party_code is not null then
      select id into v_party_id from erp.parties where code = v_party_code limit 1;
      if v_party_id is null then
        return jsonb_build_object('ok', false, 'error', format('Line %s: party not found: %s', v_idx, v_party_code));
      end if;
    end if;

    if erp._is_party_control_account(v_account_code) then
      if v_party_id is null then
        return jsonb_build_object(
          'ok', false,
          'error', format('Line %s: party is required for AR/AP account %s', v_idx, v_account_code)
        );
      end if;
    elsif v_party_id is not null then
      return jsonb_build_object(
        'ok', false,
        'error', format('Line %s: party is not allowed for account %s', v_idx, v_account_code)
      );
    end if;

    v_total_debit := v_total_debit + v_debit;
    v_total_credit := v_total_credit + v_credit;
  end loop;

  v_total_debit := round(v_total_debit, 3);
  v_total_credit := round(v_total_credit, 3);

  if v_total_debit <= 0 or v_total_credit <= 0 then
    return jsonb_build_object('ok', false, 'error', 'Total debit and credit must be greater than zero');
  end if;

  if v_total_debit <> v_total_credit then
    return jsonb_build_object(
      'ok', false,
      'error', format(
        'Journal is out of balance: debit %s, credit %s',
        trim(to_char(v_total_debit, 'FM999999990.999')),
        trim(to_char(v_total_credit, 'FM999999990.999'))
      )
    );
  end if;

  if v_reference is null then
    v_voucher_no := erp.next_journal_voucher_no('JV-');
  else
    if exists (select 1 from erp.journal_vouchers where voucher_no = v_reference) then
      return jsonb_build_object('ok', false, 'error', format('Voucher number already exists: %s', v_reference));
    end if;
    v_voucher_no := v_reference;
  end if;

  v_voucher_id := gen_random_uuid();

  insert into erp.journal_vouchers (
    id, voucher_no, posting_date, narration, total_debit, total_credit,
    status, posted_at, posted_by, created_by
  ) values (
    v_voucher_id, v_voucher_no, v_posting_date, v_narration, v_total_debit, v_total_credit,
    'posted', now(), auth.uid(), auth.uid()
  );

  insert into erp.journal_entries (
    voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no,
    narration, status, posted_at, posted_by
  ) values (
    v_voucher_no, 'JOURNAL', v_posting_date, 'journal_voucher', v_voucher_id, v_voucher_no,
    coalesce(v_narration, 'Manual journal voucher'), 'posted', now(), auth.uid()
  ) returning id into v_je_id;

  v_idx := 0;
  for v_line in select value from jsonb_array_elements(v_lines) as t(value)
  loop
    v_idx := v_idx + 1;
    v_account_code := nullif(trim(coalesce(v_line->>'account_code', v_line->>'accountCode', '')), '');
    v_party_code := nullif(trim(coalesce(v_line->>'party_code', v_line->>'partyCode', '')), '');
    v_party_id := nullif(trim(coalesce(v_line->>'party_id', v_line->>'partyId', '')), '')::uuid;
    v_debit := coalesce((v_line->>'debit')::numeric, (v_line->>'debit_amount')::numeric, 0);
    v_credit := coalesce((v_line->>'credit')::numeric, (v_line->>'credit_amount')::numeric, 0);
    v_remarks := nullif(trim(coalesce(v_line->>'remarks', v_line->>'line_description', '')), '');

    if v_party_id is null and v_party_code is not null then
      select id into v_party_id from erp.parties where code = v_party_code limit 1;
    end if;

    if not erp._is_party_control_account(v_account_code) then
      v_party_id := null;
    end if;

    perform erp._insert_je_line(
      v_je_id,
      v_idx,
      v_account_code,
      v_party_id,
      round(v_debit, 3),
      round(v_credit, 3),
      coalesce(v_remarks, v_narration, 'JV line')
    );
  end loop;

  return jsonb_build_object(
    'ok', true,
    'voucher_id', v_voucher_id,
    'voucher_no', v_voucher_no,
    'total_debit', v_total_debit,
    'total_credit', v_total_credit
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$$;


ALTER FUNCTION "erp"."post_journal_voucher"("p_payload" "jsonb") OWNER TO "postgres";

--
-- Name: post_opening_stock("uuid", "uuid", numeric, numeric, "date", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_opening_stock"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_unit_cost" numeric DEFAULT 0, "p_as_of" "date" DEFAULT CURRENT_DATE, "p_unit_count" numeric DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je_id uuid;
  v_inv text;
  v_eq text;
  v_value numeric;
  v_doc_id uuid := gen_random_uuid();
  v_as_of date := coalesce(p_as_of, current_date);
  v_units numeric := greatest(coalesce(p_unit_count, 0), 0);
  v_section text;
begin
  perform erp._assert_posting_access();
  if p_qty <= 0 then return; end if;
  if not exists (select 1 from erp.items where id = p_item_id) then
    raise exception 'Item not found for opening stock';
  end if;
  if not exists (select 1 from erp.warehouses where id = p_warehouse_id) then
    raise exception 'Warehouse not found for opening stock';
  end if;

  if exists (
    select 1
    from erp.inventory_movements im
    where im.item_id = p_item_id
      and im.warehouse_id = p_warehouse_id
      and im.movement_type = 'opening'
      and im.source_doc_type = 'opening_stock'
  ) then
    raise exception 'Opening stock already posted for this item and warehouse';
  end if;

  v_section := erp._item_inventory_section(p_item_id);
  if v_section = 'varnish' then
    v_inv := coalesce(
      erp._resolve_posting_account('opening_stock', 'inventory_varnish'),
      '12500'
    );
  else
    v_inv := erp._resolve_posting_account('opening_stock', 'inventory');
  end if;
  v_eq := erp._resolve_posting_account('opening_stock', 'opening_equity');
  v_value := round(p_qty * coalesce(p_unit_cost, 0), 3);

  insert into erp.inventory_movements (
    posting_date, movement_type, item_id, warehouse_id, qty_in, units_in, unit_cost, value_amount, source_doc_type, source_doc_id, party_id
  ) values (
    v_as_of, 'opening', p_item_id, p_warehouse_id, p_qty, v_units, p_unit_cost, v_value, 'opening_stock', v_doc_id, null
  );

  if v_value > 0 then
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
    ) values (
      'OPEN-' || left(p_item_id::text, 8), 'OPENING_STOCK', v_as_of, 'opening_stock', v_doc_id, 'OPEN-' || left(p_item_id::text, 8),
      'Opening stock', 'posted', now(), auth.uid()
    ) returning id into v_je_id;
    perform erp._insert_je_line(v_je_id, 1, v_inv, null, v_value, 0, 'Opening inventory');
    perform erp._insert_je_line(v_je_id, 2, v_eq, null, 0, v_value, 'Opening equity');
  end if;

  perform erp.rebuild_inventory_balances_for_items(array[p_item_id]);
end;
$$;


ALTER FUNCTION "erp"."post_opening_stock"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_unit_cost" numeric, "p_as_of" "date", "p_unit_count" numeric) OWNER TO "postgres";

--
-- Name: post_opening_stock_batch("jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_opening_stock_batch"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_row jsonb;
  v_item_id uuid;
  v_wh_id uuid;
  v_item_code text;
  v_wh_code text;
  v_qty numeric;
  v_unit_cost numeric;
  v_unit_count numeric;
  v_as_of date;
  v_posted int := 0;
  v_errors jsonb := '[]'::jsonb;
  v_line int := 0;
begin
  perform erp._assert_posting_access();

  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'p_rows must be a JSON array', 'posted', 0, 'errors', '[]'::jsonb);
  end if;

  for v_row in select * from jsonb_array_elements(p_rows)
  loop
    v_line := v_line + 1;
    v_item_code := upper(trim(coalesce(v_row->>'item_code', '')));
    v_wh_code := upper(trim(coalesce(v_row->>'warehouse_code', '')));
    v_qty := coalesce((v_row->>'qty')::numeric, 0);
    v_unit_cost := coalesce((v_row->>'unit_cost')::numeric, 0);
    v_unit_count := coalesce((v_row->>'unit_count')::numeric, 0);
    v_as_of := coalesce((v_row->>'as_of')::date, current_date);

    if v_item_code = '' or v_wh_code = '' then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'line', v_line, 'item_code', v_item_code, 'error', 'item_code and warehouse_code are required'
      ));
      continue;
    end if;

    if v_qty <= 0 then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'line', v_line, 'item_code', v_item_code, 'error', 'qty must be greater than zero'
      ));
      continue;
    end if;

    if coalesce(v_unit_cost, 0) <= 0 then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'line', v_line, 'item_code', v_item_code, 'error', 'unit_cost must be greater than zero'
      ));
      continue;
    end if;

    select id into v_item_id from erp.items where upper(code) = v_item_code and coalesce(is_active, true);
    if v_item_id is null then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'line', v_line, 'item_code', v_item_code, 'error', 'item not found'
      ));
      continue;
    end if;

    select id into v_wh_id from erp.warehouses where upper(code) = v_wh_code and coalesce(is_active, true);
    if v_wh_id is null then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'line', v_line, 'item_code', v_item_code, 'error', format('warehouse not found: %s', v_wh_code)
      ));
      continue;
    end if;

    begin
      perform erp.post_opening_stock(v_item_id, v_wh_id, v_qty, v_unit_cost, v_as_of, v_unit_count);
      v_posted := v_posted + 1;
    exception
      when others then
        v_errors := v_errors || jsonb_build_array(jsonb_build_object(
          'line', v_line, 'item_code', v_item_code, 'error', sqlerrm
        ));
    end;
  end loop;

  return jsonb_build_object(
    'ok', jsonb_array_length(v_errors) = 0,
    'posted', v_posted,
    'errors', v_errors
  );
end;
$$;


ALTER FUNCTION "erp"."post_opening_stock_batch"("p_rows" "jsonb") OWNER TO "postgres";

--
-- Name: post_parchi_issue("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_parchi_issue"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.parchi_instruments%rowtype;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.parchi_instruments where id = doc_id for update;
  if not found then raise exception 'parchi not found'; end if;

  -- Idempotent: already registered
  if v_doc.status = 'void' then
    raise exception 'cannot register void parchi';
  end if;

  -- Ensure open_amount is consistent (no GL impact)
  update erp.parchi_instruments
  set open_amount = greatest(0, total_amount - cleared_amount),
      status = case
        when cleared_amount <= 0 then 'open'
        when greatest(0, total_amount - cleared_amount) <= 0.01 then 'cleared'
        else 'partial'
      end
  where id = doc_id;
end;
$$;


ALTER FUNCTION "erp"."post_parchi_issue"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: post_party_opening_balance("uuid", numeric, numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_party_opening_balance"("p_party_id" "uuid", "p_fin" numeric, "p_metal" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_party erp.parties%rowtype;
  v_je_id uuid;
  v_voucher_no text;
begin
  select * into v_party from erp.parties where id = p_party_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'party not found');
  end if;
  perform erp._reverse_party_opening(p_party_id);
  update erp.parties
  set opening_fin_balance = coalesce(p_fin, 0),
      opening_metal_balance = coalesce(p_metal, 0)
  where id = p_party_id;
  if coalesce(p_fin, 0) <> 0 then
    v_voucher_no := 'OPEN-FIN-' || left(p_party_id::text, 8);
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date,
      source_doc_type, source_doc_id, source_doc_no,
      narration, status, posted_at, posted_by
    ) values (
      v_voucher_no, 'OPENING', current_date,
      'party_opening', p_party_id, v_party.code,
      'Opening financial balance for ' || v_party.name,
      'posted', now(), auth.uid()
    ) returning id into v_je_id;
    if p_fin > 0 then
      perform erp._insert_je_line(v_je_id, 1, '11201', p_party_id, p_fin, 0, 'Opening AR');
      perform erp._insert_je_line(v_je_id, 2, '31001', null, 0, p_fin, 'Opening equity offset');
      insert into erp.ar_documents (
        party_id, source_doc_type, source_doc_id, doc_date, due_date,
        amount, open_amount, status
      ) values (
        p_party_id, 'party_opening', p_party_id, current_date, current_date,
        p_fin, p_fin, 'open'
      );
    else
      perform erp._insert_je_line(v_je_id, 1, '31001', null, abs(p_fin), 0, 'Opening equity offset');
      perform erp._insert_je_line(v_je_id, 2, '21101', p_party_id, 0, abs(p_fin), 'Opening AP');
      insert into erp.ap_documents (
        party_id, source_doc_type, source_doc_id, doc_date, due_date,
        amount, open_amount, status
      ) values (
        p_party_id, 'party_opening', p_party_id, current_date, current_date,
        abs(p_fin), abs(p_fin), 'open'
      );
    end if;
  end if;
  return jsonb_build_object(
    'ok', true,
    'party_code', v_party.code,
    'fin', coalesce(p_fin, 0),
    'metal', coalesce(p_metal, 0)
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."post_party_opening_balance"("p_party_id" "uuid", "p_fin" numeric, "p_metal" numeric) OWNER TO "postgres";

