--
-- Name: post_payment("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_payment"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.payments%rowtype;
  v_je_id uuid;
  v_ar text;
  v_ap text;
  v_cash_code text;
  v_kind text;
  v_counter text;
  v_adv text;
  v_open numeric := 0;
  v_settle numeric := 0;
  v_advance numeric := 0;
  v_ln int := 0;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.payments where id = doc_id for update;
  if not found then raise exception 'payment not found' using errcode = 'P0001'; end if;
  if v_doc.posting_status = 'posted' then return; end if;

  v_kind := coalesce(
    v_doc.entry_kind,
    case when v_doc.payment_type = 'receipt' then 'party_receipt' else 'party_payment' end
  );
  if v_kind = 'expense_payment' then v_kind := 'gl_payment'; end if;
  if v_kind = 'income_receipt' then v_kind := 'gl_receipt'; end if;

  v_ar := erp._resolve_posting_account('payment_receipt', 'ar');
  v_ap := erp._resolve_posting_account('payment_payment', 'ap');

  insert into erp.journal_entries (
    voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no,
    narration, status, posted_at, posted_by
  ) values (
    v_doc.payment_no, 'PAYMENT', v_doc.payment_date, 'payment', v_doc.id, v_doc.payment_no,
    coalesce(v_doc.remarks, 'Payment posted'), 'posted', now(), auth.uid()
  ) returning id into v_je_id;

  if v_kind = 'party_settlement' then
    if v_doc.party_id is null then
      raise exception 'paying party is required for cross-party settlement' using errcode = 'P0001';
    end if;
    if v_doc.counter_party_id is null then
      raise exception 'receiving party is required for cross-party settlement' using errcode = 'P0001';
    end if;
    if v_doc.party_id = v_doc.counter_party_id then
      raise exception 'paying and receiving party must be different' using errcode = 'P0001';
    end if;
    perform erp._insert_je_line(v_je_id, 1, v_ap, v_doc.counter_party_id, v_doc.amount, 0, 'Cross-party settlement');
    perform erp._insert_je_line(v_je_id, 2, v_ar, v_doc.party_id, 0, v_doc.amount, 'Cross-party settlement');
    perform erp._apply_ap_allocation_for_party(v_doc.id, v_doc.counter_party_id, v_doc.amount);
    perform erp._apply_ar_allocation_for_party(v_doc.id, v_doc.party_id, v_doc.amount);
    update erp.payments
       set advance_amount = 0, advance_consumed = 0, is_advance = false
     where id = v_doc.id;

  elsif v_kind = 'party_receipt' then
    if v_doc.party_id is null then raise exception 'party is required for receipt' using errcode = 'P0001'; end if;
    v_cash_code := coalesce(
      v_doc.bank_account_code,
      erp._resolve_posting_account('payment_receipt', 'cash')
    );
    perform erp._assert_cashbook_cash_bank(v_cash_code);

    v_open := erp._party_open_ar(v_doc.party_id);
    v_advance := greatest(0, round(v_doc.amount - v_open, 3));
    v_settle := round(v_doc.amount - v_advance, 3);
    v_adv := erp._advance_account('customer');

    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_cash_code, v_doc.party_id, v_doc.amount, 0, 'Receipt');

    if v_settle > 0.01 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ar, v_doc.party_id, 0, v_settle, 'Settle receivable');
      perform erp._apply_ar_allocation(v_doc.id, v_settle);
    end if;

    if v_advance > 0.01 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_adv, v_doc.party_id, 0, v_advance, 'Customer advance (auto Special G/L)');
    end if;

    update erp.payments
       set advance_amount = v_advance,
           advance_consumed = 0,
           is_advance = (v_advance > 0.01)
     where id = v_doc.id;

  elsif v_kind = 'party_payment' then
    if v_doc.party_id is null then raise exception 'party is required for payment' using errcode = 'P0001'; end if;
    v_cash_code := coalesce(
      v_doc.bank_account_code,
      erp._resolve_posting_account('payment_payment', 'cash')
    );
    perform erp._assert_cashbook_cash_bank(v_cash_code);

    v_open := erp._party_open_ap(v_doc.party_id);
    v_advance := greatest(0, round(v_doc.amount - v_open, 3));
    v_settle := round(v_doc.amount - v_advance, 3);
    v_adv := erp._advance_account('vendor');

    if v_settle > 0.01 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ap, v_doc.party_id, v_settle, 0, 'Settle payable');
      perform erp._apply_ap_allocation(v_doc.id, v_settle);
    end if;

    if v_advance > 0.01 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_adv, v_doc.party_id, v_advance, 0, 'Vendor advance (auto Special G/L)');
    end if;

    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_cash_code, v_doc.party_id, 0, v_doc.amount, 'Payment');

    update erp.payments
       set advance_amount = v_advance,
           advance_consumed = 0,
           is_advance = (v_advance > 0.01)
     where id = v_doc.id;

  elsif v_kind = 'gl_receipt' then
    v_cash_code := coalesce(
      v_doc.bank_account_code,
      erp._resolve_posting_account('payment_receipt', 'cash')
    );
    perform erp._assert_cashbook_cash_bank(v_cash_code);
    v_counter := v_doc.counter_account_code;
    if v_counter is null then raise exception 'counter account (counter_account_code) is required' using errcode = 'P0001'; end if;
    perform erp._assert_cashbook_counter(v_counter);
    perform erp._insert_je_line(v_je_id, 1, v_cash_code, v_doc.party_id, v_doc.amount, 0, coalesce(v_doc.remarks, 'Receipt'));
    perform erp._insert_je_line(v_je_id, 2, v_counter, v_doc.party_id, 0, v_doc.amount, coalesce(v_doc.remarks, 'Receipt'));
    update erp.payments set advance_amount = 0, advance_consumed = 0, is_advance = false where id = v_doc.id;

  elsif v_kind = 'gl_payment' then
    v_cash_code := coalesce(
      v_doc.bank_account_code,
      erp._resolve_posting_account('payment_payment', 'cash')
    );
    perform erp._assert_cashbook_cash_bank(v_cash_code);
    v_counter := v_doc.counter_account_code;
    if v_counter is null then raise exception 'counter account (counter_account_code) is required' using errcode = 'P0001'; end if;
    perform erp._assert_cashbook_counter(v_counter);
    perform erp._insert_je_line(v_je_id, 1, v_counter, v_doc.party_id, v_doc.amount, 0, coalesce(v_doc.remarks, 'Payment'));
    perform erp._insert_je_line(v_je_id, 2, v_cash_code, v_doc.party_id, 0, v_doc.amount, coalesce(v_doc.remarks, 'Payment'));
    update erp.payments set advance_amount = 0, advance_consumed = 0, is_advance = false where id = v_doc.id;

  else
    raise exception 'Unknown entry_kind: %', v_kind using errcode = 'P0001';
  end if;

  perform erp._assert_je_balanced(v_je_id);
  update erp.payments set posting_status = 'posted' where id = v_doc.id;
end;
$$;


ALTER FUNCTION "erp"."post_payment"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: post_pending_scrap_receipts(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_pending_scrap_receipts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  r record;
  v_posted int := 0;
  v_errors jsonb := '[]'::jsonb;
begin
  perform erp._assert_posting_access();
  for r in select id, receipt_no from erp.scrap_receipts where status = 'draft' order by created_at
  loop
    begin
      perform erp.post_scrap_receipt(r.id);
      v_posted := v_posted + 1;
    exception when others then
      v_errors := v_errors || jsonb_build_array(jsonb_build_object(
        'receipt_id', r.id, 'receipt_no', r.receipt_no, 'error', sqlerrm
      ));
    end;
  end loop;
  return jsonb_build_object('posted', v_posted, 'errors', v_errors);
end;
$$;


ALTER FUNCTION "erp"."post_pending_scrap_receipts"() OWNER TO "postgres";

--
-- Name: post_production_batch("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_production_batch"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.production_batches%rowtype;
  v_line record;
  v_in numeric;
  v_out numeric;
  v_scrap numeric;
  v_units numeric;
  v_item_ids uuid[] := '{}';
  v_cost numeric;
  v_machines uuid[];
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.production_batches where id = doc_id for update;
  if not found then raise exception 'production batch not found'; end if;
  if v_doc.status = 'posted' then return; end if;
  if v_doc.process_type = 'drawing' then
    raise exception 'Drawing production is disabled';
  end if;

  perform erp._validate_production_mass_balance(v_doc.id);
  perform erp._assert_production_wire8_stock(v_doc.id);

  for v_line in
    select * from erp.production_batch_lines where production_batch_id = v_doc.id order by line_no
  loop
    if v_line.item_id is not null then
      v_item_ids := array_append(v_item_ids, v_line.item_id);
    end if;

    v_units := erp._effective_line_unit_count(v_line.item_id, v_line.unit_count);
    if v_units <= 0 and v_line.line_type = 'issue' and coalesce(v_line.net_weight, 0) > 0 then
      v_units := erp._varnish_units_from_kg(v_line.item_id, v_line.net_weight);
    end if;

    if v_line.line_type = 'issue' and v_line.net_weight > 0 then
      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id, qty_out, units_out, value_amount, source_doc_type, source_doc_id, source_line_id
      ) values (
        v_doc.batch_date, 'production_issue', v_line.item_id, v_line.warehouse_id, v_line.net_weight, v_units, 0,
        'production_batch', v_doc.id, v_line.id
      );
    elsif v_line.line_type = 'receipt' and v_line.net_weight > 0 then
      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id, qty_in, units_in, value_amount, source_doc_type, source_doc_id, source_line_id
      ) values (
        v_doc.batch_date, 'production_receipt', v_line.item_id, v_line.warehouse_id, v_line.net_weight, v_units, 0,
        'production_batch', v_doc.id, v_line.id
      );
    elsif v_line.line_type = 'scrap' and coalesce(v_line.scrap_weight, v_line.net_weight) > 0 then
      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id, qty_in, units_in, value_amount, source_doc_type, source_doc_id, source_line_id
      ) values (
        v_doc.batch_date, 'scrap_in', v_line.item_id, v_line.warehouse_id,
        coalesce(v_line.scrap_weight, v_line.net_weight), v_units, 0,
        'production_batch', v_doc.id, v_line.id
      );
    end if;
  end loop;

  v_cost := erp._apply_production_batch_costing(v_doc.id);
  perform erp._sync_production_batch_gl(v_doc.id);

  select t.input_kg, t.output_kg, t.scrap_kg into v_in, v_out, v_scrap
  from erp._production_batch_totals(v_doc.id) t;

  update erp.production_batches
  set status = 'posted',
      posted_at = now(),
      posted_by = auth.uid(),
      input_kg = v_in,
      output_kg = v_out,
      scrap_kg = v_scrap
  where id = v_doc.id;

  select coalesce(array_agg(distinct x.item_id), '{}')
  into v_item_ids
  from (
    select unnest(v_item_ids) as item_id
    union
    select item_id from erp.production_batch_lines where production_batch_id = v_doc.id and item_id is not null
  ) x;

  perform erp._rebuild_after_document_post(v_item_ids);

  select coalesce(array_agg(distinct coalesce(pbl.machine_id, v_doc.machine_id)), '{}')
  into v_machines
  from erp.production_batch_lines pbl
  where pbl.production_batch_id = v_doc.id
    and coalesce(pbl.machine_id, v_doc.machine_id) is not null;

  perform erp.fn_evaluate_production_alerts(
    erp._production_alert_eval_as_of(v_doc.batch_date, v_machines)
  );
end;
$$;


ALTER FUNCTION "erp"."post_production_batch"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: post_purchase_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_purchase_invoice"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_invoices%rowtype;
  v_je_id uuid;
  v_inv text;
  v_ap text;
  v_tax text;
  v_tax_amt numeric;
  v_net numeric;
  v_grand numeric;
  v_ln int := 0;
  v_line_count int;
  v_fixed_subtotal numeric;
  v_line record;
  v_qty numeric;
  v_units numeric;
  v_item_ids uuid[] := '{}';
  v_post_item_id uuid;
  v_canonical_w8 uuid;
  v_ap_doc_id uuid;
  v_ap_doc_party_id uuid;
  v_allocated numeric := 0;
  v_open numeric := 0;
begin
  perform erp._assert_posting_access();

  select * into v_doc from erp.purchase_invoices where id = doc_id for update;
  if not found then raise exception 'purchase invoice not found'; end if;
  if v_doc.posting_status = 'posted' then return; end if;

  select ad.id, ad.party_id, coalesce(sum(pa.allocated_amount), 0)
  into v_ap_doc_id, v_ap_doc_party_id, v_allocated
  from erp.ap_documents ad
  left join erp.payment_allocations pa on pa.ap_document_id = ad.id
  where ad.source_doc_type = 'purchase_invoice'
    and ad.source_doc_id = v_doc.id
  group by ad.id, ad.party_id
  order by coalesce(sum(pa.allocated_amount), 0) desc
  limit 1;

  if v_ap_doc_id is not null
     and v_allocated > 0
     and v_ap_doc_party_id is distinct from v_doc.party_id then
    raise exception 'cannot repost: allocated purchase invoice supplier cannot be changed';
  end if;

  select count(*)::int into v_line_count
  from erp.purchase_invoice_lines l
  where l.purchase_invoice_id = v_doc.id
    and l.item_id is not null
    and coalesce(l.net_weight, l.qty, 0) > 0;

  if v_line_count = 0 then
    raise exception 'Purchase invoice has no stock lines. Save lines with valid item codes from Item Master.';
  end if;

  v_canonical_w8 := erp._canonical_wire8_item_id(v_doc.invoice_date);
  if v_canonical_w8 is not null then
    if not exists (select 1 from erp.items where id = v_canonical_w8 and is_active) then
      raise exception
        'Wire No 8 item % is missing or inactive. Set an active item in Production Settings.',
        (select code from erp.items where id = v_canonical_w8);
    end if;
  end if;

  perform erp._clear_purchase_invoice_draft_posting(v_doc.id);
  perform erp._apply_purchase_order_fulfillment(v_doc.id);

  v_inv := erp._resolve_posting_account('purchase_invoice', 'inventory');
  v_ap := erp._resolve_posting_account('purchase_invoice', 'ap');
  v_tax := erp._resolve_posting_account('purchase_invoice', 'input_tax');

  select coalesce(sum(l.line_amount), 0) into v_fixed_subtotal
  from erp.purchase_invoice_lines l
  where l.purchase_invoice_id = v_doc.id
    and coalesce(l.rate_status, 'fixed') = 'fixed';

  if coalesce(v_doc.subtotal_amount, 0) > 0 and v_fixed_subtotal > 0 then
    v_tax_amt := round(coalesce(v_doc.tax_amount, 0) * v_fixed_subtotal / v_doc.subtotal_amount, 3);
  else
    v_tax_amt := 0;
  end if;
  v_net := v_fixed_subtotal;
  v_grand := v_net + v_tax_amt;

  if v_allocated > v_grand then
    raise exception 'cannot repost: allocated payments % exceed new invoice amount %', v_allocated, v_grand;
  end if;

  for v_line in
    select * from erp.purchase_invoice_lines l
    where l.purchase_invoice_id = v_doc.id and l.item_id is not null
  loop
    v_qty := coalesce(v_line.net_weight, v_line.qty, 0);
    if v_qty <= 0 then continue; end if;
    v_units := greatest(coalesce(v_line.unit_count, 0), 0);

    v_post_item_id := v_line.item_id;
    if v_canonical_w8 is not null and erp._is_wire8_item(v_line.item_id) then
      v_post_item_id := v_canonical_w8;
      if v_post_item_id <> v_line.item_id then
        update erp.purchase_invoice_lines
        set item_id = v_post_item_id
        where id = v_line.id;
      end if;
    end if;

    v_item_ids := array_append(v_item_ids, v_post_item_id);

    if coalesce(v_line.rate_status, 'fixed') = 'pending' then
      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id, qty_in, units_in, unit_cost, value_amount,
        source_doc_type, source_doc_id, source_line_id, party_id
      ) values (
        v_doc.invoice_date, 'purchase_in', v_post_item_id, v_line.warehouse_id, v_qty, v_units, 0, 0,
        'purchase_invoice', v_doc.id, v_line.id, v_doc.party_id
      );
      perform erp._enqueue_pending_rate_item(
        'purchase_invoice', v_doc.id, v_line.id, v_doc.invoice_no, v_line.line_no,
        v_doc.party_id, v_post_item_id, v_line.warehouse_id, v_qty, v_doc.invoice_date
      );
    else
      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id, qty_in, units_in, unit_cost, value_amount,
        source_doc_type, source_doc_id, source_line_id, party_id
      ) values (
        v_doc.invoice_date, 'purchase_in', v_post_item_id, v_line.warehouse_id, v_qty, v_units,
        case when v_qty > 0 then round(v_line.line_amount / v_qty, 6) else 0 end,
        v_line.line_amount,
        'purchase_invoice', v_doc.id, v_line.id, v_doc.party_id
      );
    end if;
  end loop;

  if v_grand > 0 then
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by
    ) values (
      v_doc.invoice_no, 'PURCHASE_INVOICE', v_doc.invoice_date, 'purchase_invoice', v_doc.id, v_doc.invoice_no,
      coalesce(v_doc.remarks, 'Purchase invoice posted'), 'posted', now(), auth.uid()
    ) returning id into v_je_id;

    if v_net > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, v_net, 0, 'Inventory');
    end if;
    if v_tax_amt > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_tax, null, v_tax_amt, 0, 'Input Tax');
    end if;
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_ap, v_doc.party_id, 0, v_grand, 'Accounts Payable');
  end if;

  v_open := v_grand - coalesce(v_allocated, 0);

  if v_ap_doc_id is not null then
    update erp.ap_documents
    set party_id = v_doc.party_id,
        source_doc_no = v_doc.invoice_no,
        doc_date = v_doc.invoice_date,
        due_date = coalesce(v_doc.due_date, v_doc.invoice_date),
        amount = v_grand,
        open_amount = v_open,
        status = case
          when v_open <= 0 then 'settled'
          when v_open < v_grand then 'partially_settled'
          else 'open'
        end
    where id = v_ap_doc_id;
  elsif v_grand > 0 then
    insert into erp.ap_documents (
      party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status
    ) values (
      v_doc.party_id, 'purchase_invoice', v_doc.id, v_doc.invoice_no, v_doc.invoice_date,
      coalesce(v_doc.due_date, v_doc.invoice_date), v_grand, v_open,
      case
        when v_open <= 0 then 'settled'
        when v_open < v_grand then 'partially_settled'
        else 'open'
      end
    );
  end if;

  perform erp._rebuild_after_document_post(v_item_ids);
  perform erp._refresh_doc_financial_status('purchase_invoice', v_doc.id);

  update erp.purchase_invoices
  set posting_status = 'posted', posted_at = now(), posted_by = auth.uid()
  where id = v_doc.id;
end;
$$;


ALTER FUNCTION "erp"."post_purchase_invoice"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: post_purchase_return("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_purchase_return"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_returns%rowtype;
  v_je_id uuid;
  v_ap text; v_inv text; v_var text;
  v_ln int := 0;
  v_financial numeric := 0;
  v_inventory numeric := 0;
  v_variance numeric := 0;
  v_line record;
  v_cost record;
  v_units numeric;
  v_item_ids uuid[] := '{}';
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.purchase_returns where id = doc_id for update;
  if not found then raise exception 'purchase return not found'; end if;
  if v_doc.posting_status = 'posted' then return; end if;

  perform erp._assert_purchase_return_stock(v_doc.id);
  v_ap := erp._resolve_posting_account('purchase_return', 'ap');
  v_inv := erp._resolve_posting_account('purchase_return', 'inventory');
  v_var := coalesce(erp._lookup_posting_account('purchase_return', 'cost_variance'), '51014');

  for v_line in
    select * from erp.purchase_return_lines l
    where l.purchase_return_id = v_doc.id
    order by l.line_no
  loop
    if coalesce(v_line.qty, 0) <= 0 then continue; end if;

    if coalesce(v_line.rate_status, 'fixed') = 'fixed' then
      v_financial := v_financial + coalesce(v_line.line_amount, 0);
    else
      perform erp._enqueue_pending_rate_item(
        'purchase_return', v_doc.id, v_line.id, v_doc.return_no, v_line.line_no,
        v_doc.party_id, v_line.item_id, v_line.warehouse_id, v_line.qty, v_doc.return_date
      );
    end if;

    if coalesce(v_doc.return_action, '') = 'stock' then
      select * into v_cost from erp._purchase_return_line_inventory_cost(v_line.id);
      if not found then raise exception 'Unable to cost purchase return line %', v_line.line_no; end if;
      v_units := greatest(coalesce(v_line.unit_count, 0), 0);
      v_item_ids := array_append(v_item_ids, v_line.item_id);
      v_inventory := v_inventory + v_cost.value_amount;

      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id, qty_out, units_out,
        unit_cost, value_amount, source_doc_type, source_doc_id, source_line_id, party_id
      ) values (
        v_doc.return_date, 'purchase_return_out', v_line.item_id, v_line.warehouse_id,
        v_line.qty, v_units, v_cost.unit_cost, v_cost.value_amount,
        'purchase_return', v_doc.id, v_line.id, v_doc.party_id
      );

      update erp.purchase_return_lines
      set source_inventory_movement_id = v_cost.source_movement_id,
          inventory_unit_cost = v_cost.unit_cost,
          inventory_value_amount = v_cost.value_amount,
          inventory_cost_basis = v_cost.cost_basis,
          cost_variance_amount = case
            when coalesce(v_line.rate_status, 'fixed') = 'fixed'
              then round(coalesce(v_line.line_amount, 0) - v_cost.value_amount, 3)
            else null
          end
      where id = v_line.id;
    else
      update erp.purchase_return_lines
      set source_inventory_movement_id = null,
          inventory_unit_cost = 0,
          inventory_value_amount = 0,
          inventory_cost_basis = 'financial_only',
          cost_variance_amount = case
            when coalesce(v_line.rate_status, 'fixed') = 'fixed'
              then round(coalesce(v_line.line_amount, 0), 3)
            else null
          end
      where id = v_line.id;
    end if;
  end loop;

  v_financial := round(v_financial, 3);
  v_inventory := round(v_inventory, 3);
  v_variance := round(v_financial - v_inventory, 3);

  if v_financial > 0 or v_inventory > 0 then
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id,
      source_doc_no, narration, status, posted_at, posted_by
    ) values (
      v_doc.return_no, 'PURCHASE_RETURN', v_doc.return_date, 'purchase_return', v_doc.id,
      v_doc.return_no, coalesce(v_doc.remarks, 'Purchase return posted'), 'posted', now(), auth.uid()
    ) returning id into v_je_id;
    if v_financial > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ap, v_doc.party_id, v_financial, 0, 'Reduce payable');
    end if;
    if v_inventory > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_inv, null, 0, v_inventory, 'Inventory out at original receipt cost');
    end if;
    if v_variance > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_var, null, 0, v_variance, 'Purchase return cost variance');
    elsif v_variance < 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_var, null, -v_variance, 0, 'Purchase return cost variance');
    end if;
    perform erp._assert_je_balanced(v_je_id);
    if v_financial > 0 then
      perform erp._reduce_ap_open(v_doc.party_id, v_financial);
    end if;
  end if;

  perform erp._rebuild_after_document_post(v_item_ids);
  perform erp._refresh_doc_financial_status('purchase_return', v_doc.id);
  update erp.purchase_returns
  set posting_status = 'posted', posted_at = now(), posted_by = auth.uid()
  where id = v_doc.id;
end;
$$;


ALTER FUNCTION "erp"."post_purchase_return"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "post_purchase_return"("doc_id" "uuid"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."post_purchase_return"("doc_id" "uuid") IS 'Post purchase return at linked original receipt cost; financial-only returns do not move stock.';


--
-- Name: post_sales_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_sales_invoice"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_invoices%rowtype;
  v_je_id uuid;
  v_ar text;
  v_rev text;
  v_tax text;
  v_tax_amt numeric;
  v_net numeric;
  v_grand numeric;
  v_ln int := 0;
  v_line record;
  v_qty numeric;
  v_units numeric;
  v_wac numeric;
  v_line_cogs numeric;
  v_c_amt numeric;
  v_v_amt numeric;
  v_p_amt numeric;
  v_o_amt numeric;
  v_state record;
  v_kg numeric;
  v_fixed_subtotal numeric;
  v_item_ids uuid[] := '{}';
  v_line_count int;
  v_mov_id uuid;
  v_has_cogs boolean := false;
  v_norm record;

  -- Grouped WAC roll-forward state (one entry per distinct item+warehouse)
  g_count int := 0;
  g_item uuid[];
  g_wh uuid[];
  g_qty numeric[];
  g_value numeric[];
  g_wac numeric[];
  g_last_valid numeric[];
  g_c_unit numeric[];
  g_v_unit numeric[];
  g_p_unit numeric[];
  g_o_unit numeric[];
  g_c_val numeric[];
  g_v_val numeric[];
  g_p_val numeric[];
  g_o_val numeric[];
  gi int;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.sales_invoices where id = doc_id for update;
  if not found then raise exception 'sales invoice not found'; end if;
  if v_doc.posting_status = 'posted' then return; end if;
  perform erp._assert_period_allows_posting(v_doc.invoice_date);

  if coalesce(v_doc.sale_mode, 'direct') = 'premium'
     and coalesce(v_doc.ref_scrap_rate, 0) <= 0 then
    raise exception 'Premium sales invoice requires ref_scrap_rate';
  end if;

  select count(*)::int into v_line_count
  from erp.sales_invoice_lines l
  where l.sales_invoice_id = v_doc.id
    and l.item_id is not null
    and coalesce(nullif(l.net_weight, 0), l.qty, 0) > 0;
  if v_line_count = 0 then
    raise exception 'Sales invoice has no stock lines. Save lines with valid item codes from Item Master.';
  end if;

  perform erp._assert_sales_invoice_stock(v_doc.id);
  perform erp._apply_sales_order_fulfillment(v_doc.id);

  v_ar := erp._resolve_posting_account('sales_invoice', 'ar');
  v_rev := erp._resolve_posting_account('sales_invoice', 'sales_revenue');
  v_tax := erp._resolve_posting_account('sales_invoice', 'output_tax');

  select coalesce(sum(l.line_amount), 0) into v_fixed_subtotal
  from erp.sales_invoice_lines l
  where l.sales_invoice_id = v_doc.id
    and coalesce(l.rate_status, 'fixed') = 'fixed';

  if coalesce(v_doc.subtotal_amount, 0) > 0 and v_fixed_subtotal > 0 then
    v_tax_amt := round(coalesce(v_doc.tax_amount, 0) * v_fixed_subtotal / v_doc.subtotal_amount, 3);
  else
    v_tax_amt := 0;
  end if;
  v_net := v_fixed_subtotal;
  v_grand := v_net + v_tax_amt;

  for v_line in
    select *
    from erp.sales_invoice_lines
    where sales_invoice_id = v_doc.id
    order by line_no, id
  loop
    -- FIX-1 (mig 306): treat net_weight = 0 as absent so stocked lines cannot be skipped.
    v_qty := coalesce(nullif(v_line.net_weight, 0), v_line.qty);
    if coalesce(v_qty, 0) <= 0 or v_line.item_id is null then continue; end if;
    v_units := erp._effective_line_unit_count(v_line.item_id, v_line.unit_count);
    v_item_ids := array_append(v_item_ids, v_line.item_id);

    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id, qty_out, units_out,
      unit_cost, value_amount, cost_status, costed_period_id,
      source_doc_type, source_doc_id, source_line_id, party_id
    ) values (
      v_doc.invoice_date, 'sales_out', v_line.item_id, v_line.warehouse_id,
      v_qty, v_units, 0, 0, 'provisional', null,
      'sales_invoice', v_doc.id, v_line.id, v_doc.party_id
    )
    returning id into v_mov_id;

    -- ---- locate/create the (item, warehouse) group -------------------------
    gi := 0;
    if g_count > 0 then
      for gi in 1 .. g_count loop
        exit when g_item[gi] = v_line.item_id and g_wh[gi] = v_line.warehouse_id;
      end loop;
      if not (g_item[gi] = v_line.item_id and g_wh[gi] = v_line.warehouse_id) then
        gi := 0;
      end if;
    end if;
    if gi = 0 then
      g_count := g_count + 1;
      gi := g_count;
      g_item[gi] := v_line.item_id;
      g_wh[gi] := v_line.warehouse_id;
      -- ONE canonical replay per group, anchored at this group's first movement.
      select * into v_state
      from erp._inventory_replay_state(v_line.item_id, v_line.warehouse_id, v_mov_id);
      g_qty[gi] := coalesce(v_state.on_hand_qty, 0);
      g_value[gi] := coalesce(v_state.stock_value, 0);
      g_wac[gi] := coalesce(v_state.avg_unit_cost, 0);
      g_last_valid[gi] := greatest(coalesce(v_state.avg_unit_cost, 0), 0);
      g_c_unit[gi] := coalesce(v_state.copper_unit_cost, 0);
      g_v_unit[gi] := coalesce(v_state.varnish_unit_cost, 0);
      g_p_unit[gi] := coalesce(v_state.packing_unit_cost, 0);
      g_o_unit[gi] := coalesce(v_state.oh_unit_cost, 0);
      g_c_val[gi] := round(g_qty[gi] * g_c_unit[gi], 3);
      g_v_val[gi] := round(g_qty[gi] * g_v_unit[gi], 3);
      g_p_val[gi] := round(g_qty[gi] * g_p_unit[gi], 3);
      g_o_val[gi] := round(g_qty[gi] * g_o_unit[gi], 3);
    end if;

    -- ---- zero-cost guard (FIX-2, mig 306 semantics preserved) -------------
    v_wac := g_wac[gi];
    if coalesce(v_wac, 0) <= 0 then
      v_wac := coalesce(
        erp.resolve_inventory_valuation_rate(v_line.item_id, v_doc.invoice_date),
        0
      );
    end if;
    if coalesce(v_wac, 0) <= 0
       and not coalesce(
             (select w.allow_negative_stock
              from erp.warehouses w
              where w.id = v_line.warehouse_id),
             false) then
      raise exception
        'Cannot post line %: item % has zero book cost in warehouse % (no WAC, no valuation rate). Fix pending purchase rates or set an inventory valuation rate first.',
        v_line.line_no,
        (select code from erp.items where id = v_line.item_id),
        (select code from erp.warehouses where id = v_line.warehouse_id);
    end if;

    -- ---- cost this outbound line ------------------------------------------
    v_line_cogs := round(v_qty * v_wac, 3);
    v_has_cogs := v_has_cogs or v_line_cogs > 0;

    v_c_amt := round(v_qty * coalesce(g_c_unit[gi], 0), 3);
    v_v_amt := round(v_qty * coalesce(g_v_unit[gi], 0), 3);
    v_p_amt := round(v_qty * coalesce(g_p_unit[gi], 0), 3);
    v_o_amt := round(v_qty * coalesce(g_o_unit[gi], 0), 3);

    select * into v_norm
    from erp._normalize_cogs_components(v_line_cogs, v_c_amt, v_v_amt, v_p_amt, v_o_amt);
    v_c_amt := v_norm.o_copper;
    v_v_amt := v_norm.o_varnish;
    v_p_amt := v_norm.o_packing;
    -- Fold clearing residual into oh for movement stamps (no clearing column)
    v_o_amt := round(coalesce(v_norm.o_oh, 0) + coalesce(v_norm.o_clearing, 0), 3);

    update erp.inventory_movements
    set unit_cost = v_wac,
        value_amount = v_line_cogs,
        cost_copper = v_c_amt,
        cost_varnish = v_v_amt,
        cost_packing = v_p_amt,
        cost_oh = v_o_amt
    where id = v_mov_id;

    -- ---- advance the group's running state (replay-outbound parity) -------
    g_qty[gi] := g_qty[gi] - v_qty;
    g_value[gi] := g_value[gi] - v_line_cogs;
    g_c_val[gi] := g_c_val[gi] - v_c_amt;
    g_v_val[gi] := g_v_val[gi] - v_v_amt;
    g_p_val[gi] := g_p_val[gi] - v_p_amt;
    g_o_val[gi] := g_o_val[gi] - v_o_amt;
    if g_qty[gi] > 0 then
      g_wac[gi] := round(g_value[gi] / g_qty[gi], 6);
      if g_wac[gi] > 0 then g_last_valid[gi] := g_wac[gi]; end if;
      g_c_unit[gi] := round(g_c_val[gi] / g_qty[gi], 6);
      g_v_unit[gi] := round(g_v_val[gi] / g_qty[gi], 6);
      g_p_unit[gi] := round(g_p_val[gi] / g_qty[gi], 6);
      g_o_unit[gi] := round(g_o_val[gi] / g_qty[gi], 6);
    else
      -- Retain last valid rates at zero/negative quantity (replay semantics).
      g_wac[gi] := g_last_valid[gi];
      g_value[gi] := round(g_qty[gi] * g_wac[gi], 3);
      g_c_val[gi] := round(g_qty[gi] * g_c_unit[gi], 3);
      g_v_val[gi] := round(g_qty[gi] * g_v_unit[gi], 3);
      g_p_val[gi] := round(g_qty[gi] * g_p_unit[gi], 3);
      g_o_val[gi] := round(g_qty[gi] * g_o_unit[gi], 3);
    end if;

    if coalesce(v_line.rate_status, 'fixed') = 'pending' then
      perform erp._enqueue_pending_rate_item(
        'sales_invoice', v_doc.id, v_line.id, v_doc.invoice_no, v_line.line_no,
        v_doc.party_id, v_line.item_id, v_line.warehouse_id, v_qty, v_doc.invoice_date
      );
    end if;
  end loop;

  perform erp._apply_goat_packing_issues(v_doc.id);

  if v_grand > 0 or v_has_cogs then
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id,
      source_doc_no, narration, status, posted_at, posted_by
    ) values (
      v_doc.invoice_no, 'SALES_INVOICE', v_doc.invoice_date,
      'sales_invoice', v_doc.id, v_doc.invoice_no,
      coalesce(v_doc.remarks, 'Sales invoice posted'),
      'posted', now(), auth.uid()
    ) returning id into v_je_id;
  end if;

  if v_grand > 0 then
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_ar, v_doc.party_id, v_grand, 0, 'Accounts Receivable');
    if v_net > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_rev, null, 0, v_net, 'Sales Revenue');
    end if;
    if v_tax_amt > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_tax, null, 0, v_tax_amt, 'Output Tax');
    end if;
  end if;

  if v_has_cogs then
    perform erp._sync_sales_invoice_cogs_gl(v_doc.id);
  elsif v_je_id is not null then
    perform erp._assert_je_balanced(v_je_id);
  end if;

  if v_grand > 0 then
    insert into erp.ar_documents (
      party_id, source_doc_type, source_doc_id, source_doc_no,
      doc_date, due_date, amount, open_amount, status
    ) values (
      v_doc.party_id, 'sales_invoice', v_doc.id, v_doc.invoice_no,
      v_doc.invoice_date, v_doc.due_date, v_grand, v_grand, 'open'
    )
    on conflict (source_doc_type, source_doc_id, party_id) do nothing;
  end if;

  v_kg := erp._premium_invoice_total_kg(v_doc.id);
  perform erp._refresh_doc_financial_status('sales_invoice', v_doc.id);
  update erp.sales_invoices
  set posting_status = 'posted',
      posted_at = now(),
      posted_by = auth.uid(),
      premium_total_kg = v_kg
  where id = v_doc.id;

  perform erp._create_scrap_receivable_obligation(v_doc.id);
  perform erp._rebuild_after_document_post(v_item_ids);
end;
$$;


ALTER FUNCTION "erp"."post_sales_invoice"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "post_sales_invoice"("doc_id" "uuid"); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."post_sales_invoice"("doc_id" "uuid") IS 'Posts sales using chronological WAC/components at each movement; PAC may subsequently restamp provisional costs.';


--
-- Name: post_sales_return("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_sales_return"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_returns%rowtype;
  v_je_id uuid;
  v_ar text; v_rev text; v_tax text;
  v_tax_amt numeric; v_net numeric; v_grand numeric;
  v_ln int := 0;
  v_fixed_subtotal numeric;
  v_line record;
  v_cost record;
  v_units numeric;
  v_item_ids uuid[] := '{}';
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.sales_returns where id = doc_id for update;
  if not found then raise exception 'sales return not found'; end if;
  if v_doc.posting_status = 'posted' then return; end if;

  v_ar := erp._resolve_posting_account('sales_return', 'ar');
  v_rev := erp._resolve_posting_account('sales_return', 'sales_revenue');
  v_tax := erp._resolve_posting_account('sales_return', 'output_tax');

  select coalesce(sum(l.line_amount), 0) into v_fixed_subtotal
  from erp.sales_return_lines l
  where l.sales_return_id = v_doc.id
    and coalesce(l.rate_status, 'fixed') = 'fixed';
  if coalesce(v_doc.subtotal_amount, 0) > 0 and v_fixed_subtotal > 0 then
    v_tax_amt := round(coalesce(v_doc.tax_amount, 0) * v_fixed_subtotal / v_doc.subtotal_amount, 3);
  else
    v_tax_amt := 0;
  end if;
  v_net := v_fixed_subtotal;
  v_grand := v_net + v_tax_amt;

  if v_doc.return_action = 'restock' then
    for v_line in
      select * from erp.sales_return_lines l
      where l.sales_return_id = v_doc.id
      order by l.line_no
    loop
      if coalesce(v_line.qty, 0) <= 0 then continue; end if;
      select * into v_cost from erp._sales_return_line_inventory_cost(v_line.id);
      if not found then raise exception 'Unable to cost sales return line %', v_line.line_no; end if;
      v_units := greatest(coalesce(v_line.unit_count, 0), 0);
      v_item_ids := array_append(v_item_ids, v_line.item_id);

      insert into erp.inventory_movements (
        posting_date, movement_type, item_id, warehouse_id, qty_in, units_in,
        unit_cost, value_amount, cost_copper, cost_varnish, cost_packing, cost_oh,
        source_doc_type, source_doc_id, source_line_id, party_id
      ) values (
        v_doc.return_date, 'sales_return_in', v_line.item_id, v_line.warehouse_id,
        v_line.qty, v_units, v_cost.unit_cost, v_cost.value_amount,
        v_cost.cost_copper, v_cost.cost_varnish, v_cost.cost_packing, v_cost.cost_oh,
        'sales_return', v_doc.id, v_line.id, v_doc.party_id
      );

      update erp.sales_return_lines
      set source_inventory_movement_id = v_cost.source_movement_id,
          inventory_unit_cost = v_cost.unit_cost,
          inventory_value_amount = v_cost.value_amount,
          inventory_cost_basis = v_cost.cost_basis
      where id = v_line.id;

      if coalesce(v_line.rate_status, 'fixed') = 'pending' then
        perform erp._enqueue_pending_rate_item(
          'sales_return', v_doc.id, v_line.id, v_doc.return_no, v_line.line_no,
          v_doc.party_id, v_line.item_id, v_line.warehouse_id, v_line.qty, v_doc.return_date
        );
      end if;
    end loop;
  end if;

  if v_grand > 0 then
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id,
      source_doc_no, narration, status, posted_at, posted_by
    ) values (
      v_doc.return_no, 'SALES_RETURN', v_doc.return_date, 'sales_return', v_doc.id,
      v_doc.return_no, coalesce(v_doc.remarks, 'Sales return posted'), 'posted', now(), auth.uid()
    ) returning id into v_je_id;
    if v_net > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_rev, null, v_net, 0, 'Sales return');
    end if;
    if v_tax_amt > 0 then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_tax, null, v_tax_amt, 0, 'Output tax reversal');
    end if;
    v_ln := v_ln + 1;
    perform erp._insert_je_line(v_je_id, v_ln, v_ar, v_doc.party_id, 0, v_grand, 'Reduce receivable');
    perform erp._reduce_ar_open(v_doc.party_id, v_grand);
  end if;

  perform erp._sync_sales_return_cogs_gl(v_doc.id);
  perform erp._rebuild_after_document_post(v_item_ids);
  perform erp._refresh_doc_financial_status('sales_return', v_doc.id);
  update erp.sales_returns
  set posting_status = 'posted', posted_at = now(), posted_by = auth.uid()
  where id = v_doc.id;
end;
$$;


ALTER FUNCTION "erp"."post_sales_return"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: post_scrap_conversion_return("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_scrap_conversion_return"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_conversion_returns%rowtype;
  v_obl erp.scrap_conversion_obligations%rowtype;
  v_rm_wh uuid;
  v_open numeric;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.scrap_conversion_returns where id = doc_id for update;
  if not found then raise exception 'scrap conversion return not found'; end if;
  if v_doc.status = 'posted' then return; end if;
  if coalesce(v_doc.net_weight, 0) <= 0 then
    raise exception 'return requires positive net weight';
  end if;

  select * into v_obl from erp.scrap_conversion_obligations where id = v_doc.obligation_id for update;
  if not found then raise exception 'linked conversion obligation not found'; end if;

  v_open := greatest(v_obl.expected_kg - v_obl.returned_kg, 0);
  if v_doc.net_weight > v_open + 0.001 then
    raise exception 'Return weight % exceeds open obligation % kg', v_doc.net_weight, v_open;
  end if;

  select id into v_rm_wh
  from erp.warehouses
  where wh_type = 'raw_material' and is_active = true
  order by code
  limit 1;
  if v_rm_wh is null then raise exception 'raw material warehouse not configured'; end if;

  insert into erp.inventory_movements (
    posting_date, movement_type, item_id, warehouse_id, qty_in, unit_cost, value_amount,
    source_doc_type, source_doc_id, party_id, reference_no
  ) values (
    v_doc.return_date, 'purchase_in', v_doc.item_id, v_rm_wh, v_doc.net_weight,
    coalesce(nullif(v_doc.unit_rate, 0), 0),
    coalesce(nullif(v_doc.amount, 0), v_doc.net_weight * coalesce(nullif(v_doc.unit_rate, 0), 0)),
    'scrap_conversion_return', v_doc.id, v_obl.dest_party_id, v_doc.return_no
  );

  update erp.scrap_conversion_obligations
  set returned_kg = returned_kg + v_doc.net_weight
  where id = v_obl.id;

  perform erp._sync_scrap_conversion_obligation_status(v_obl.id);

  update erp.scrap_conversion_returns
  set status = 'posted', posted_at = now(), posted_by = auth.uid()
  where id = v_doc.id;

  perform erp.rebuild_inventory_balances_for_items(array[v_doc.item_id]);
end;
$$;


ALTER FUNCTION "erp"."post_scrap_conversion_return"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: post_scrap_receipt("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_scrap_receipt"("doc_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_receipts%rowtype;
  v_obl erp.scrap_receivable_obligations%rowtype;
  v_open numeric;
  v_scrap_item uuid;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.scrap_receipts where id = doc_id for update;
  if not found then raise exception 'scrap receipt not found'; end if;
  if v_doc.status = 'posted' then return; end if;
  if coalesce(v_doc.net_weight, 0) <= 0 then raise exception 'scrap receipt requires positive net weight'; end if;

  select * into v_obl from erp.scrap_receivable_obligations where id = v_doc.obligation_id for update;
  if not found then raise exception 'linked scrap obligation not found'; end if;

  v_open := greatest(v_obl.expected_kg - v_obl.received_kg, 0);
  if v_doc.net_weight > v_open + 0.001 then
    raise exception 'Receipt weight % exceeds open obligation % kg', v_doc.net_weight, v_open;
  end if;

  if coalesce(v_doc.record_metal_movement, true) then
    if v_doc.item_id is null then
      select id into v_scrap_item from erp.items where code in ('RM-SCP-001', 'RM-SCRAP-001') limit 1;
      v_doc.item_id := v_scrap_item;
    end if;
    if v_doc.item_id is null then raise exception 'scrap item not configured'; end if;

    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id, qty_in, unit_cost, value_amount,
      source_doc_type, source_doc_id, party_id, reference_no
    )
    select
      v_doc.receipt_date, 'scrap_in', v_doc.item_id,
      (select id from erp.warehouses where is_active = true order by case wh_type when 'raw_material' then 0 else 1 end limit 1),
      v_doc.net_weight, v_doc.unit_rate, v_doc.amount,
      'scrap_receipt', v_doc.id, v_doc.party_id, v_obl.sales_invoice_no;
  end if;

  update erp.scrap_receivable_obligations
  set received_kg = received_kg + v_doc.net_weight
  where id = v_obl.id;

  perform erp._sync_scrap_obligation_status(v_obl.id);

  update erp.scrap_receipts
  set status = 'posted', posted_at = now(), posted_by = auth.uid()
  where id = v_doc.id;

  if v_doc.item_id is not null then
    perform erp.rebuild_inventory_balances_for_items(array[v_doc.item_id]);
  end if;
end;
$$;


ALTER FUNCTION "erp"."post_scrap_receipt"("doc_id" "uuid") OWNER TO "postgres";

--
-- Name: post_scrap_trade("uuid", "uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_scrap_trade"("doc_id" "uuid", "p_obligation_id" "uuid" DEFAULT NULL::"uuid", "p_allocations" "jsonb" DEFAULT NULL::"jsonb", "p_credit_allocations" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_trades%rowtype;
  v_transit_wh uuid;
  v_je_id uuid;
  v_ap_acct text;
  v_ar_acct text;
  v_inv_acct text;
  v_amount numeric;
  v_unit_cost numeric;
  v_ln int := 0;
  v_row jsonb;
  v_obl_id uuid;
  v_alloc_kg numeric;
  v_receipt_id uuid;
  v_line_seq int := 0;
  v_alloc_sum numeric := 0;
  v_credit_sum numeric := 0;
  v_credit_id uuid;
  v_obligation_net numeric;
  v_rate_pending boolean;
  v_pri_id uuid;
  v_is_unlinked boolean;
  v_pending_reason text;
  v_is_cash boolean;
begin
  perform erp._assert_posting_access();

  if p_obligation_id is not null and p_allocations is not null then
    raise exception 'Provide either p_obligation_id or p_allocations, not both';
  end if;

  select * into v_doc from erp.scrap_trades where id = doc_id for update;
  if not found then raise exception 'scrap trade not found'; end if;

  v_is_unlinked := p_obligation_id is null and p_allocations is null;
  v_is_cash := coalesce(v_doc.settlement_mode, 'triangle') = 'cash';

  if p_credit_allocations is not null then
    for v_row in select * from jsonb_array_elements(p_credit_allocations)
    loop
      v_credit_sum := v_credit_sum + coalesce((v_row->>'allocated_kg')::numeric, 0);
    end loop;
  end if;

  v_obligation_net := coalesce(v_doc.net_weight, 0) - v_credit_sum;

  if v_doc.status = 'posted' then
    if p_credit_allocations is not null then
      for v_row in select * from jsonb_array_elements(p_credit_allocations)
      loop
        v_credit_id := (v_row->>'scrap_credit_id')::uuid;
        v_alloc_kg := (v_row->>'allocated_kg')::numeric;
        v_obl_id := nullif(v_row->>'obligation_id', '')::uuid;
        perform erp._consume_party_scrap_credit(v_credit_id, v_alloc_kg, v_doc.id, v_obl_id);
      end loop;
    end if;

    if p_allocations is not null then
      for v_row in select * from jsonb_array_elements(p_allocations)
      loop
        v_obl_id := (v_row->>'obligation_id')::uuid;
        v_alloc_kg := (v_row->>'allocated_kg')::numeric;
        v_receipt_id := nullif(v_row->>'receipt_id', '')::uuid;
        v_alloc_sum := v_alloc_sum + v_alloc_kg;
        perform erp._apply_scrap_obligation_kg(v_doc.id, v_obl_id, v_alloc_kg, v_receipt_id);
      end loop;
      if abs(v_alloc_sum - v_obligation_net) > 0.001 then
        raise exception 'Allocation sum % must equal remainder kg %', v_alloc_sum, v_obligation_net;
      end if;
      delete from erp.scrap_obligation_allocations where scrap_trade_id = v_doc.id;
      v_line_seq := 0;
      for v_row in select * from jsonb_array_elements(p_allocations)
      loop
        v_line_seq := v_line_seq + 1;
        insert into erp.scrap_obligation_allocations (scrap_trade_id, obligation_id, receipt_id, allocated_kg, line_seq)
        values (
          v_doc.id,
          (v_row->>'obligation_id')::uuid,
          nullif(v_row->>'receipt_id', '')::uuid,
          (v_row->>'allocated_kg')::numeric,
          coalesce((v_row->>'line_seq')::int, v_line_seq)
        );
      end loop;
    elsif p_obligation_id is not null then
      perform erp._fulfill_scrap_obligation_on_trade(v_doc.id, p_obligation_id);
    end if;
    if not v_is_cash then
      perform erp._create_scrap_lot_from_trade(v_doc.id);
    end if;
    return;
  end if;

  if v_doc.item_id is null then raise exception 'scrap trade requires item'; end if;
  if coalesce(v_doc.net_weight, 0) <= 0 then raise exception 'scrap trade requires positive net weight'; end if;

  if p_allocations is not null then
    for v_row in select * from jsonb_array_elements(p_allocations)
    loop
      v_alloc_sum := v_alloc_sum + coalesce((v_row->>'allocated_kg')::numeric, 0);
    end loop;
    if abs(v_alloc_sum - v_obligation_net) > 0.001 then
      raise exception 'Allocation sum % must equal remainder kg % (net % minus credits %)',
        v_alloc_sum, v_obligation_net, v_doc.net_weight, v_credit_sum;
    end if;
  end if;

  if abs(v_credit_sum + v_alloc_sum - coalesce(v_doc.net_weight, 0)) > 0.001
     and (p_allocations is not null or p_credit_allocations is not null) then
    raise exception 'Credit + obligation allocations must equal net weight %', v_doc.net_weight;
  end if;

  select id into v_transit_wh from erp.warehouses where wh_type = 'triangle_transit' and is_active = true order by code limit 1;
  if v_transit_wh is null then raise exception 'triangle transit warehouse not configured'; end if;

  v_rate_pending := coalesce(v_doc.rate_status, 'fixed') = 'pending';
  v_pending_reason := coalesce(v_doc.pending_reason, case when v_rate_pending then 'rate' else null end);

  if v_rate_pending then
    v_amount := 0;
    v_unit_cost := 0;
  else
    v_amount := round(coalesce(nullif(v_doc.amount, 0), v_doc.net_weight * coalesce(nullif(v_doc.unit_rate, 0), 0)), 3);
    v_unit_cost := case when v_doc.net_weight > 0 then round(v_amount / v_doc.net_weight, 6) else coalesce(nullif(v_doc.unit_rate, 0), 0) end;
  end if;

  v_ap_acct := erp._resolve_posting_account('scrap_trade', 'ap');
  v_ar_acct := erp._resolve_posting_account('scrap_trade', 'ar');
  v_inv_acct := erp._resolve_posting_account('scrap_trade', 'inventory');

  if not v_is_cash then
    insert into erp.inventory_movements (posting_date, movement_type, item_id, warehouse_id, qty_in, unit_cost, value_amount, source_doc_type, source_doc_id, party_id, reference_no)
    values (v_doc.trade_date, 'scrap_in', v_doc.item_id, v_transit_wh, v_doc.net_weight, v_unit_cost, v_amount, 'scrap_trade', v_doc.id, v_doc.source_party_id, v_doc.trade_no);

    insert into erp.inventory_movements (posting_date, movement_type, item_id, warehouse_id, qty_out, unit_cost, value_amount, source_doc_type, source_doc_id, party_id, reference_no)
    values (v_doc.trade_date, 'scrap_out', v_doc.item_id, v_transit_wh, v_doc.net_weight, v_unit_cost, v_amount, 'scrap_trade', v_doc.id, v_doc.dest_party_id, v_doc.trade_no);
  end if;

  if v_rate_pending or v_pending_reason is not null then
    v_pri_id := erp._enqueue_pending_rate_item(
      'scrap_trade', v_doc.id, null, v_doc.trade_no, 1,
      v_doc.source_party_id, v_doc.item_id, null, v_doc.net_weight, v_doc.trade_date,
      coalesce(v_pending_reason, 'rate')
    );
  elsif v_amount > 0 then
    insert into erp.journal_entries (voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no, narration, status, posted_at, posted_by)
    values (v_doc.trade_no, 'SCRAP_TRADE', v_doc.trade_date, 'scrap_trade', v_doc.id, v_doc.trade_no, coalesce(v_doc.remarks, 'Scrap toll-drop posted'), 'posted', now(), auth.uid())
    returning id into v_je_id;

    if v_is_cash then
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ar_acct, v_doc.dest_party_id, v_amount, 0, 'Scrap delivered to destination');
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ap_acct, v_doc.source_party_id, 0, v_amount, 'Payable to source');

      insert into erp.ap_documents (party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status)
      values (v_doc.source_party_id, 'scrap_trade', v_doc.id, v_doc.trade_no, v_doc.trade_date, v_doc.trade_date, v_amount, v_amount, 'open')
      on conflict (source_doc_type, source_doc_id, party_id) do nothing;
      insert into erp.ar_documents (party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status)
      values (v_doc.dest_party_id, 'scrap_trade', v_doc.id, v_doc.trade_no, v_doc.trade_date, v_doc.trade_date, v_amount, v_amount, 'open')
      on conflict (source_doc_type, source_doc_id, party_id) do nothing;
    else
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_inv_acct, null, v_amount, 0, 'Scrap acquired in transit');
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ap_acct, v_doc.source_party_id, 0, v_amount, 'Payable to source');
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_ar_acct, v_doc.dest_party_id, v_amount, 0, 'Receivable from destination');
      v_ln := v_ln + 1;
      perform erp._insert_je_line(v_je_id, v_ln, v_inv_acct, null, 0, v_amount, 'Scrap delivered from transit');

      insert into erp.ap_documents (party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status)
      values (v_doc.source_party_id, 'scrap_trade', v_doc.id, v_doc.trade_no, v_doc.trade_date, v_doc.trade_date, v_amount, v_amount, 'open')
      on conflict (source_doc_type, source_doc_id, party_id) do nothing;
      insert into erp.ar_documents (party_id, source_doc_type, source_doc_id, source_doc_no, doc_date, due_date, amount, open_amount, status)
      values (v_doc.dest_party_id, 'scrap_trade', v_doc.id, v_doc.trade_no, v_doc.trade_date, v_doc.trade_date, v_amount, v_amount, 'open')
      on conflict (source_doc_type, source_doc_id, party_id) do nothing;
    end if;
  end if;

  perform erp._refresh_doc_financial_status('scrap_trade', v_doc.id);

  update erp.scrap_trades set status = 'posted', posted_at = now(), posted_by = auth.uid() where id = v_doc.id;

  if not v_is_cash then
    perform erp._create_scrap_lot_from_trade(v_doc.id);
  end if;

  if v_is_unlinked and (v_rate_pending or v_pending_reason is not null) and not v_is_cash then
    perform erp._upsert_party_scrap_credit(
      v_doc.source_party_id,
      v_doc.id,
      v_doc.net_weight,
      v_pri_id,
      null
    );
  end if;

  if p_credit_allocations is not null then
    for v_row in select * from jsonb_array_elements(p_credit_allocations)
    loop
      v_credit_id := (v_row->>'scrap_credit_id')::uuid;
      v_alloc_kg := (v_row->>'allocated_kg')::numeric;
      v_obl_id := nullif(v_row->>'obligation_id', '')::uuid;
      perform erp._consume_party_scrap_credit(v_credit_id, v_alloc_kg, v_doc.id, v_obl_id);
    end loop;
  end if;

  v_alloc_sum := 0;
  if p_allocations is not null then
    v_line_seq := 0;
    for v_row in select * from jsonb_array_elements(p_allocations)
    loop
      v_line_seq := v_line_seq + 1;
      v_obl_id := (v_row->>'obligation_id')::uuid;
      v_alloc_kg := (v_row->>'allocated_kg')::numeric;
      v_receipt_id := nullif(v_row->>'receipt_id', '')::uuid;
      v_alloc_sum := v_alloc_sum + v_alloc_kg;
      perform erp._apply_scrap_obligation_kg(v_doc.id, v_obl_id, v_alloc_kg, v_receipt_id);
      insert into erp.scrap_obligation_allocations (scrap_trade_id, obligation_id, receipt_id, allocated_kg, line_seq)
      values (
        v_doc.id,
        v_obl_id,
        v_receipt_id,
        v_alloc_kg,
        coalesce((v_row->>'line_seq')::int, v_line_seq)
      );
    end loop;
  elsif p_obligation_id is not null then
    if v_credit_sum > 0.001 and abs(v_obligation_net) > 0.001 then
      perform erp._apply_scrap_obligation_kg(v_doc.id, p_obligation_id, v_obligation_net, null);
    else
      perform erp._fulfill_scrap_obligation_on_trade(v_doc.id, p_obligation_id);
    end if;
  end if;

  perform erp.rebuild_inventory_balances_for_items(array[v_doc.item_id]);
end;
$$;


ALTER FUNCTION "erp"."post_scrap_trade"("doc_id" "uuid", "p_obligation_id" "uuid", "p_allocations" "jsonb", "p_credit_allocations" "jsonb") OWNER TO "postgres";

--
-- Name: post_supplies_restock("text", numeric, numeric, "text", "date", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_supplies_restock"("p_item_code" "text", "p_qty" numeric, "p_unit_cost" numeric DEFAULT 0, "p_remarks" "text" DEFAULT NULL::"text", "p_posting_date" "date" DEFAULT NULL::"date", "p_unit_count" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item erp.items%rowtype;
  v_wh_id uuid;
  v_wh_type text;
  v_doc_id uuid := gen_random_uuid();
  v_value numeric;
  v_units_in numeric := 0;
  v_posting_date date := coalesce(p_posting_date, current_date);
begin
  perform erp._assert_posting_access();

  if p_item_code is null or trim(p_item_code) = '' then
    return jsonb_build_object('ok', false, 'error', 'Item code is required');
  end if;
  if coalesce(p_qty, 0) <= 0 then
    return jsonb_build_object('ok', false, 'error', 'Quantity must be greater than zero');
  end if;

  select * into v_item
  from erp.items
  where code = trim(p_item_code) and coalesce(is_active, true)
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'error', format('Item not found: %s', p_item_code));
  end if;

  if v_item.inventory_group not in ('chemicals', 'packing_material') then
    return jsonb_build_object(
      'ok', false,
      'error', 'Supplies restock is only for chemicals (varnish) and packing material items'
    );
  end if;

  v_wh_type := case
    when v_item.inventory_group = 'chemicals' then 'varnish'
    else 'packing_material'
  end;

  select id into v_wh_id
  from erp.warehouses
  where wh_type = v_wh_type and coalesce(is_active, true)
  order by code
  limit 1;

  if v_wh_id is null then
    return jsonb_build_object('ok', false, 'error', format('Warehouse not found for type %s', v_wh_type));
  end if;

  if erp._is_varnish_item(v_item.id) then
    v_units_in := coalesce(nullif(p_unit_count, 0), erp._varnish_units_from_kg(v_item.id, p_qty));
  end if;

  v_value := round(p_qty * coalesce(p_unit_cost, 0), 3);

  insert into erp.inventory_movements (
    posting_date, movement_type, item_id, warehouse_id, qty_in, units_in, unit_cost, value_amount,
    source_doc_type, source_doc_id, reference_no
  ) values (
    v_posting_date, 'adjustment_in', v_item.id, v_wh_id, p_qty, v_units_in,
    coalesce(p_unit_cost, 0), v_value, 'supplies_restock', v_doc_id,
    nullif(trim(coalesce(p_remarks, '')), '')
  );

  if v_item.inventory_group = 'chemicals' and v_value > 0 then
    perform erp._sync_supplies_restock_gl(
      v_doc_id,
      v_posting_date,
      v_value,
      coalesce(nullif(trim(p_remarks), ''), 'Varnish supplies restock')
    );
  end if;

  perform erp.rebuild_inventory_balances_for_items(array[v_item.id]);

  return jsonb_build_object(
    'ok', true,
    'item_code', v_item.code,
    'qty', p_qty,
    'unit_count', v_units_in,
    'warehouse_type', v_wh_type
  );
end;
$$;


ALTER FUNCTION "erp"."post_supplies_restock"("p_item_code" "text", "p_qty" numeric, "p_unit_cost" numeric, "p_remarks" "text", "p_posting_date" "date", "p_unit_count" numeric) OWNER TO "postgres";

--
-- Name: post_supplies_stock_set("text", numeric, "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."post_supplies_stock_set"("p_item_code" "text", "p_new_qty" numeric, "p_remarks" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item erp.items%rowtype;
  v_wh_id uuid;
  v_wh_type text;
  v_doc_id uuid := gen_random_uuid();
  v_current numeric := 0;
  v_delta numeric;
  v_note text;
begin
  perform erp._assert_posting_access();

  if p_item_code is null or trim(p_item_code) = '' then
    return jsonb_build_object('ok', false, 'error', 'Item code is required');
  end if;
  if p_new_qty is null or p_new_qty < 0 then
    return jsonb_build_object('ok', false, 'error', 'Quantity cannot be negative');
  end if;

  select * into v_item
  from erp.items
  where code = trim(p_item_code) and coalesce(is_active, true)
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'error', format('Item not found: %s', p_item_code));
  end if;

  if v_item.inventory_group not in ('chemicals', 'packing_material') then
    return jsonb_build_object(
      'ok', false,
      'error', 'Stock edit is only for chemicals (varnish) and packing material items'
    );
  end if;

  v_wh_type := case
    when v_item.inventory_group = 'chemicals' then 'varnish'
    else 'packing_material'
  end;

  select id into v_wh_id
  from erp.warehouses
  where wh_type = v_wh_type and coalesce(is_active, true)
  order by code
  limit 1;

  if v_wh_id is null then
    return jsonb_build_object('ok', false, 'error', format('Warehouse not found for type %s', v_wh_type));
  end if;

  select coalesce(ib.on_hand_qty, 0) into v_current
  from erp.inventory_balances ib
  where ib.item_id = v_item.id
    and ib.warehouse_id = v_wh_id;

  v_delta := round(p_new_qty - coalesce(v_current, 0), 3);

  if abs(v_delta) < 0.0005 then
    return jsonb_build_object(
      'ok', true,
      'item_code', v_item.code,
      'qty', p_new_qty,
      'adjusted', 0
    );
  end if;

  v_note := nullif(trim(coalesce(p_remarks, '')), '');
  if v_note is null then
    v_note := format('Set stock %s → %s', to_char(v_current, 'FM999,999,990.999'), to_char(p_new_qty, 'FM999,999,990.999'));
  end if;

  if v_delta > 0 then
    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id, qty_in, value_amount,
      source_doc_type, source_doc_id, reference_no
    ) values (
      current_date, 'adjustment_in', v_item.id, v_wh_id, v_delta, 0,
      'supplies_stock_set', v_doc_id, v_note
    );
  else
    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id, qty_out, value_amount,
      source_doc_type, source_doc_id, reference_no
    ) values (
      current_date, 'adjustment_out', v_item.id, v_wh_id, abs(v_delta), 0,
      'supplies_stock_set', v_doc_id, v_note
    );
  end if;

  perform erp.rebuild_inventory_balances_for_items(array[v_item.id]);

  return jsonb_build_object(
    'ok', true,
    'item_code', v_item.code,
    'qty', p_new_qty,
    'adjusted', v_delta,
    'warehouse_type', v_wh_type
  );
end;
$$;


ALTER FUNCTION "erp"."post_supplies_stock_set"("p_item_code" "text", "p_new_qty" numeric, "p_remarks" "text") OWNER TO "postgres";

--
-- Name: purge_orphan_invoice_artifacts("text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."purge_orphan_invoice_artifacts"("p_invoice_no" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_si_id uuid;
  v_pi_id uuid;
  v_return_id uuid;
  v_step text := 'init';
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', 'authentication required');
  end if;

  select id into v_si_id from erp.sales_invoices where invoice_no = p_invoice_no limit 1;
  select id into v_pi_id from erp.purchase_invoices where invoice_no = p_invoice_no limit 1;

  if v_si_id is not null then
    return erp.hard_delete_sales_invoice(v_si_id);
  end if;

  if v_pi_id is not null then
    return erp.hard_delete_purchase_invoice(v_pi_id);
  end if;

  v_step := 'purge_orphan_sales_artifacts';
  for v_return_id in
    select sr.id
    from erp.sales_returns sr
    join erp.sales_invoices si on si.id = sr.ref_invoice_id
    where si.invoice_no = p_invoice_no
  loop
    perform erp._hard_delete_clear_doc_side_effects('sales_return', v_return_id, 'ar');
    delete from erp.sales_returns where id = v_return_id;
  end loop;

  delete from erp.inventory_movements im
  using erp.sales_invoices si
  where im.source_doc_type = 'sales_invoice'
    and im.source_doc_id = si.id
    and si.invoice_no = p_invoice_no;

  delete from erp.ar_documents ad
  using erp.sales_invoices si
  where ad.source_doc_type = 'sales_invoice'
    and ad.source_doc_id = si.id
    and si.invoice_no = p_invoice_no;

  delete from erp.journal_lines jl
  using erp.journal_entries je, erp.sales_invoices si
  where jl.journal_entry_id = je.id
    and je.source_doc_type = 'sales_invoice'
    and je.source_doc_id = si.id
    and si.invoice_no = p_invoice_no;

  delete from erp.journal_entries je
  using erp.sales_invoices si
  where je.source_doc_type = 'sales_invoice'
    and je.source_doc_id = si.id
    and si.invoice_no = p_invoice_no;

  v_step := 'purge_orphan_purchase_artifacts';
  for v_return_id in
    select pr.id
    from erp.purchase_returns pr
    join erp.purchase_invoices pi on pi.id = pr.ref_invoice_id
    where pi.invoice_no = p_invoice_no
  loop
    perform erp._hard_delete_clear_doc_side_effects('purchase_return', v_return_id, 'ap');
    delete from erp.purchase_returns where id = v_return_id;
  end loop;

  delete from erp.inventory_movements im
  using erp.purchase_invoices pi
  where im.source_doc_type = 'purchase_invoice'
    and im.source_doc_id = pi.id
    and pi.invoice_no = p_invoice_no;

  delete from erp.ap_documents ad
  using erp.purchase_invoices pi
  where ad.source_doc_type = 'purchase_invoice'
    and ad.source_doc_id = pi.id
    and pi.invoice_no = p_invoice_no;

  delete from erp.journal_lines jl
  using erp.journal_entries je, erp.purchase_invoices pi
  where jl.journal_entry_id = je.id
    and je.source_doc_type = 'purchase_invoice'
    and je.source_doc_id = pi.id
    and pi.invoice_no = p_invoice_no;

  delete from erp.journal_entries je
  using erp.purchase_invoices pi
  where je.source_doc_type = 'purchase_invoice'
    and je.source_doc_id = pi.id
    and pi.invoice_no = p_invoice_no;

  v_step := 'rebuild_inventory';
  perform erp.rebuild_inventory_balances();

  return jsonb_build_object('ok', true, 'step', 'done', 'note', 'no invoice header found; orphan artifacts purged if any');
exception
  when others then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', SQLERRM, 'code', SQLSTATE);
end;
$$;


ALTER FUNCTION "erp"."purge_orphan_invoice_artifacts"("p_invoice_no" "text") OWNER TO "postgres";

--
-- Name: rebuild_all_wac_and_gl("uuid", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."rebuild_all_wac_and_gl"("p_audit_run_id" "uuid", "p_execute" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $_$
declare
  v_run erp.wac_rebuild_audit_runs%rowtype;
  v_fingerprint jsonb;
  v_snapshot_count bigint := 0;
  v_movements_updated bigint := 0;
  v_sales_synced int := 0;
  v_returns_synced int := 0;
  v_prod_synced int := 0;
  v_locked_periods int := 0;
  v_rec record;
  v_je record;
  v_result jsonb;
  v_bad bigint;
  v_dr numeric;
  v_cr numeric;
  v_seq int;
begin
  -- Interactive callers must be live ADMIN users. Trusted SQL/service-role
  -- execution has no auth.uid(); EXECUTE remains revoked from anon/public and
  -- granted only to authenticated (checked here) and service_role.
  if auth.uid() is null then
    perform erp._assert_report_access();
  else
    perform erp._assert_admin();
  end if;

  if not coalesce(p_execute, false) then
    raise exception 'Execution confirmation required: pass p_execute => true'
      using errcode = '22023';
  end if;

  if p_audit_run_id is null then
    raise exception 'audit_run_id is required' using errcode = '22023';
  end if;

  if not pg_try_advisory_xact_lock(hashtextextended('erp.rebuild_all_wac_and_gl', 0)) then
    raise exception 'Another WAC/GL rebuild is already running'
      using errcode = '55P03';
  end if;

  select * into v_run
  from erp.wac_rebuild_audit_runs
  where id = p_audit_run_id;

  if not found or v_run.status <> 'succeeded' then
    raise exception 'A successful immutable audit run is required';
  end if;
  if not v_run.is_executable then
    raise exception 'Audit % is blocked by unresolved zero-cost inbound movements',
      p_audit_run_id;
  end if;

  if exists (
    select 1 from erp.wac_rebuild_executions where audit_run_id = p_audit_run_id
  ) then
    select result into v_result
    from erp.wac_rebuild_executions where audit_run_id = p_audit_run_id;
    return v_result || jsonb_build_object('idempotent_replay', true);
  end if;

  v_fingerprint := erp._wac_rebuild_source_fingerprint();

  if v_fingerprint is distinct from v_run.source_fingerprint then
    raise exception 'Inventory ledger changed after audit %. Run a fresh audit.',
      p_audit_run_id using errcode = '40001';
  end if;

  select count(*) into v_bad
  from erp.wac_rebuild_audit_details
  where audit_run_id = p_audit_run_id and unresolved_zero_cost;
  if v_bad > 0 then
    raise exception 'Audit contains % unresolved source costs', v_bad;
  end if;

  -- Complete pre-image snapshots. Journal snapshots are limited to documents
  -- whose cost legs can be rebuilt by this RPC.
  insert into erp.wac_rebuild_snapshots (audit_run_id, entity_type, entity_key, row_data)
  select p_audit_run_id, 'inventory_movement', im.id::text, to_jsonb(im)
  from erp.inventory_movements im
  join erp.wac_rebuild_audit_details d
    on d.audit_run_id = p_audit_run_id and d.movement_id = im.id;
  get diagnostics v_snapshot_count = row_count;

  insert into erp.wac_rebuild_snapshots (audit_run_id, entity_type, entity_key, row_data)
  select p_audit_run_id, 'inventory_balance',
         ib.item_id::text || ':' || ib.warehouse_id::text, to_jsonb(ib)
  from erp.inventory_balances ib;

  insert into erp.wac_rebuild_snapshots (audit_run_id, entity_type, entity_key, row_data)
  select p_audit_run_id, 'inventory_cost_component',
         ic.item_id::text || ':' || ic.warehouse_id::text, to_jsonb(ic)
  from erp.inventory_cost_components ic;

  insert into erp.wac_rebuild_snapshots (audit_run_id, entity_type, entity_key, row_data)
  select p_audit_run_id, 'journal_entry', je.id::text, to_jsonb(je)
  from erp.journal_entries je
  where (
    je.source_doc_type in (
      'sales_invoice','sales_return','sales_return_cogs',
      'purchase_return','purchase_return_cost_sync','production_batch'
    )
    and exists (
      select 1 from erp.wac_rebuild_audit_details d
      where d.audit_run_id = p_audit_run_id
        and d.source_doc_id = je.source_doc_id
        and (
          d.source_doc_type = je.source_doc_type
          or (d.source_doc_type = 'sales_return' and je.source_doc_type = 'sales_return_cogs')
          or (d.source_doc_type = 'purchase_return' and je.source_doc_type = 'purchase_return_cost_sync')
        )
    )
  )
  or (
    je.source_doc_type = 'inventory_recon_plug'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
  );

  insert into erp.wac_rebuild_snapshots (audit_run_id, entity_type, entity_key, row_data)
  select p_audit_run_id, 'journal_line', jl.id::text, to_jsonb(jl)
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where (
    je.source_doc_type in (
      'sales_invoice','sales_return','sales_return_cogs',
      'purchase_return','purchase_return_cost_sync','production_batch'
    )
    and exists (
      select 1 from erp.wac_rebuild_audit_details d
      where d.audit_run_id = p_audit_run_id
        and d.source_doc_id = je.source_doc_id
        and (
          d.source_doc_type = je.source_doc_type
          or (d.source_doc_type = 'sales_return' and je.source_doc_type = 'sales_return_cogs')
          or (d.source_doc_type = 'purchase_return' and je.source_doc_type = 'purchase_return_cost_sync')
        )
    )
  )
  or (
    je.source_doc_type = 'inventory_recon_plug'
    and coalesce(je.voucher_no, '') not like 'VOID-%'
  );

  -- Bypass is transaction-local and only covers this controlled repair.
  perform set_config('erp.skip_cogs_restamp', '1', true);
  perform set_config('erp.skip_period_lock_check', '1', true);
  perform set_config('erp.skip_inventory_balance_sync', '1', true);
  perform set_config('erp.wac_rebuild_run_id', p_audit_run_id::text, true);

  -- A Day-1 replay supersedes historical inventory-control plugs that were
  -- calculated against the corrupted pre-replay subledger. Preserve their
  -- pre-images above, then classify them under the report-neutral VOID protocol.
  update erp.journal_entries
  set voucher_no = 'VOID-WAC-' || left(id::text, 8)
  where source_doc_type = 'inventory_recon_plug'
    and coalesce(voucher_no, '') not like 'VOID-%';

  -- Preserve final stamps in locked PAC periods. Everything else receives the
  -- exact audited chronological cost and component values.
  update erp.inventory_movements im
  set unit_cost = d.expected_unit_cost,
      value_amount = d.expected_value,
      cost_copper = d.expected_copper,
      cost_varnish = d.expected_varnish,
      cost_packing = d.expected_packing,
      cost_oh = d.expected_oh
  from erp.wac_rebuild_audit_details d
  where d.audit_run_id = p_audit_run_id
    and d.movement_id = im.id
    and not d.locked_pac_stamp
    and (
      im.unit_cost is distinct from d.expected_unit_cost
      or im.value_amount is distinct from d.expected_value
      or im.cost_copper is distinct from d.expected_copper
      or im.cost_varnish is distinct from d.expected_varnish
      or im.cost_packing is distinct from d.expected_packing
      or im.cost_oh is distinct from d.expected_oh
    );
  get diagnostics v_movements_updated = row_count;

  -- Re-cost unlocked production in batch-date order. Migration 290's canonical
  -- helper, when present, is used by _apply_production_batch_costing.
  if to_regprocedure('erp._apply_production_batch_costing(uuid)') is not null then
    for v_rec in
      select distinct pb.id, pb.batch_date, pb.batch_no
      from erp.production_batches pb
      join erp.inventory_movements im
        on im.source_doc_type = 'production_batch' and im.source_doc_id = pb.id
      where pb.status = 'posted'
        and not exists (
          select 1 from erp.costing_periods cp
          where cp.status = 'locked'
            and pb.batch_date between cp.start_date and cp.end_date
        )
      order by pb.batch_date, pb.batch_no, pb.id
    loop
      perform erp._apply_production_batch_costing(v_rec.id);
    end loop;
  end if;

  -- Production receipt changes can move downstream provisional sales WAC.
  -- Migration 290's helper restamps only provisional sales and leaves PAC
  -- draft/final stamps authoritative.
  for v_rec in
    select distinct d.item_id, d.warehouse_id
    from erp.wac_rebuild_audit_details d
    where d.audit_run_id = p_audit_run_id
      and exists (
        select 1
        from erp.inventory_movements im
        where im.item_id = d.item_id
          and im.warehouse_id = d.warehouse_id
          and im.movement_type = 'sales_out'
          and coalesce(im.cost_status, 'provisional') = 'provisional'
      )
    order by d.item_id, d.warehouse_id
  loop
    perform erp._restamp_sales_cogs_for_item_wh(
      v_rec.item_id, v_rec.warehouse_id, null
    );
  end loop;

  -- Rebuild cache tables using migration 290's replacement when installed, or
  -- the current callable implementation otherwise.
  perform erp.rebuild_inventory_balances();

  -- Sales COGS: migration 287 helper preserves commercial AR/revenue/tax legs
  -- and rebuilds only COGS/inventory component legs.
  for v_rec in
    select distinct d.source_doc_id
    from erp.wac_rebuild_audit_details d
    where d.audit_run_id = p_audit_run_id
      and d.source_doc_type = 'sales_invoice'
      and d.movement_type = 'sales_out'
    order by d.source_doc_id
  loop
    if erp._sync_sales_invoice_cogs_gl(v_rec.source_doc_id) then
      v_sales_synced := v_sales_synced + 1;
    end if;
  end loop;

  -- Migration 291 supplies dedicated return helpers. Their absence is safe only
  -- when no corresponding return movements exist.
  if exists (
    select 1 from erp.wac_rebuild_audit_details
    where audit_run_id = p_audit_run_id and source_doc_type = 'sales_return'
  ) and to_regprocedure('erp._sync_sales_return_cogs_gl(uuid)') is null then
    raise exception 'Migration 291 helper erp._sync_sales_return_cogs_gl(uuid) is required';
  end if;

  if exists (
    select 1 from erp.wac_rebuild_audit_details
    where audit_run_id = p_audit_run_id and source_doc_type = 'purchase_return'
  ) and to_regprocedure('erp._sync_purchase_return_inventory_gl(uuid)') is null then
    raise exception 'Migration 291 helper erp._sync_purchase_return_inventory_gl(uuid) is required';
  end if;

  if to_regprocedure('erp._sync_sales_return_cogs_gl(uuid)') is not null then
    for v_rec in
      select distinct source_doc_id
      from erp.wac_rebuild_audit_details
      where audit_run_id = p_audit_run_id and source_doc_type = 'sales_return'
      order by source_doc_id
    loop
      execute 'select erp._sync_sales_return_cogs_gl($1)' using v_rec.source_doc_id;
      v_returns_synced := v_returns_synced + 1;
    end loop;
  end if;

  if to_regprocedure('erp._sync_purchase_return_inventory_gl(uuid)') is not null then
    for v_rec in
      select distinct source_doc_id
      from erp.wac_rebuild_audit_details
      where audit_run_id = p_audit_run_id and source_doc_type = 'purchase_return'
      order by source_doc_id
    loop
      execute 'select erp._sync_purchase_return_inventory_gl($1)' using v_rec.source_doc_id;
      v_returns_synced := v_returns_synced + 1;
    end loop;
  end if;

  -- Rebuild unlocked production JEs with the existing append-only VOID protocol.
  for v_rec in
    select distinct pb.id, pb.batch_date, pb.batch_no
    from erp.production_batches pb
    join erp.wac_rebuild_audit_details d
      on d.audit_run_id = p_audit_run_id
     and d.source_doc_type = 'production_batch'
     and d.source_doc_id = pb.id
    where pb.status = 'posted'
      and not exists (
        select 1 from erp.costing_periods cp
        where cp.status = 'locked'
          and pb.batch_date between cp.start_date and cp.end_date
      )
    order by pb.batch_date, pb.batch_no, pb.id
  loop
    v_seq := 0;
    for v_je in
      select je.id
      from erp.journal_entries je
      where je.source_doc_type = 'production_batch'
        and je.source_doc_id = v_rec.id
        and coalesce(je.voucher_no, '') not like 'VOID-%'
      order by je.posted_at, je.id
    loop
      v_seq := v_seq + 1;
      update erp.journal_entries
      set voucher_no = 'VOID-WAC-' || v_rec.batch_no
            || case when v_seq > 1 then '-' || v_seq::text else '' end,
          narration = coalesce(narration, '')
            || format(' [superseded by WAC rebuild %s]', p_audit_run_id)
      where id = v_je.id;
    end loop;
    perform erp._sync_production_batch_gl(v_rec.id);
    v_prod_synced := v_prod_synced + 1;
  end loop;

  select count(*) into v_locked_periods
  from erp.wac_rebuild_affected_periods
  where audit_run_id = p_audit_run_id;

  -- Fail-loud assertions. Any exception rolls back repair and snapshots together.
  select count(*) into v_bad
  from erp.inventory_movements im
  where coalesce(im.qty_in, 0) > 0
    and coalesce(im.unit_cost, 0) <= 0
    and coalesce(im.value_amount, 0) <= 0;
  if v_bad > 0 then
    raise exception 'Post-rebuild assertion failed: % zero-cost inbound movements', v_bad;
  end if;

  select count(*) into v_bad
  from erp.inventory_balances ib
  where abs(coalesce(ib.stock_value, 0)
          - round(coalesce(ib.on_hand_qty, 0) * coalesce(ib.avg_unit_cost, 0), 3)) > 0.02;
  if v_bad > 0 then
    raise exception 'Post-rebuild assertion failed: % balance arithmetic mismatches', v_bad;
  end if;

  select coalesce(sum(jl.debit_amount), 0), coalesce(sum(jl.credit_amount), 0)
  into v_dr, v_cr
  from erp.journal_lines jl
  join erp.journal_entries je on je.id = jl.journal_entry_id
  where coalesce(je.voucher_no, '') not like 'VOID-%';
  -- Reconciliation accepts sub-rupee aggregate rounding drift. Individual
  -- affected JEs remain subject to the stricter 0.01 assertion below.
  if abs(round(v_dr - v_cr, 3)) > 0.10 then
    raise exception 'Post-rebuild active GL is unbalanced: debit %, credit %', v_dr, v_cr;
  end if;

  select count(*) into v_bad
  from (
    select je.id
    from erp.journal_entries je
    join erp.journal_lines jl on jl.journal_entry_id = je.id
    where coalesce(je.voucher_no, '') not like 'VOID-%'
      and je.source_doc_type in ('sales_invoice','sales_return','purchase_return','production_batch')
    group by je.id
    having abs(round(sum(jl.debit_amount) - sum(jl.credit_amount), 3)) > 0.01
  ) x;
  if v_bad > 0 then
    raise exception 'Post-rebuild assertion failed: % affected active JEs are unbalanced', v_bad;
  end if;

  -- Locked periods remain locked. They are evidence for the next explicit stage.
  select count(*) into v_bad
  from erp.wac_rebuild_affected_periods ap
  join erp.costing_periods cp on cp.id = ap.period_id
  where ap.audit_run_id = p_audit_run_id and cp.status <> 'locked';
  if v_bad > 0 then
    raise exception 'Controlled repair unexpectedly changed % locked PAC period(s)', v_bad;
  end if;

  perform set_config('erp.skip_cogs_restamp', '0', true);
  perform set_config('erp.skip_period_lock_check', '0', true);
  perform set_config('erp.skip_inventory_balance_sync', '0', true);

  v_result := jsonb_build_object(
    'ok', true,
    'audit_run_id', p_audit_run_id,
    'movements_updated', v_movements_updated,
    'movement_snapshots', v_snapshot_count,
    'sales_invoices_gl_synced', v_sales_synced,
    'returns_gl_synced', v_returns_synced,
    'production_batches_gl_synced', v_prod_synced,
    'locked_pac_periods_requiring_staged_refinal', v_locked_periods,
    'locked_periods_mutated', false
  );

  insert into erp.wac_rebuild_executions (audit_run_id, executed_by, result)
  values (p_audit_run_id, auth.uid(), v_result);

  return v_result;
end;
$_$;


ALTER FUNCTION "erp"."rebuild_all_wac_and_gl"("p_audit_run_id" "uuid", "p_execute" boolean) OWNER TO "postgres";

--
-- Name: FUNCTION "rebuild_all_wac_and_gl"("p_audit_run_id" "uuid", "p_execute" boolean); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."rebuild_all_wac_and_gl"("p_audit_run_id" "uuid", "p_execute" boolean) IS 'ADMIN-only repair tied to an unchanged, executable audit run; locked PAC periods are staged, not reopened.';


--
-- Name: rebuild_inventory_balances(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."rebuild_inventory_balances"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_items uuid[];
begin
  -- Block ordinary authenticated users; allow trusted backend (service_role / SQL,
  -- where auth.uid() is null) and the SECURITY DEFINER post/delete flows that call this.
  if auth.uid() is not null then
    perform erp._assert_posting_access();
  end if;
  select coalesce(array_agg(distinct item_id), '{}') into v_items
  from erp.inventory_movements;
  perform erp.rebuild_inventory_balances_for_items(v_items);
  -- Also remove balance rows for items that no longer have any movements.
  delete from erp.inventory_balances ib
  where not exists (
    select 1 from erp.inventory_movements im where im.item_id = ib.item_id
  );
end;
$$;


ALTER FUNCTION "erp"."rebuild_inventory_balances"() OWNER TO "postgres";

--
-- Name: rebuild_inventory_balances_for_items("uuid"[]); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."rebuild_inventory_balances_for_items"("p_item_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_pair record;
  v_state record;
  v_units numeric;
begin
  if p_item_ids is null or cardinality(p_item_ids) = 0 then
    return;
  end if;

  delete from erp.inventory_balances ib
  where ib.item_id = any(p_item_ids);

  delete from erp.inventory_cost_components ic
  where ic.item_id = any(p_item_ids);

  for v_pair in
    select distinct im.item_id, im.warehouse_id
    from erp.inventory_movements im
    where im.item_id = any(p_item_ids)
      and im.item_id is not null
      and im.warehouse_id is not null
  loop
    select * into v_state
    from erp._inventory_replay_state(v_pair.item_id, v_pair.warehouse_id, null);

    select coalesce(sum(coalesce(im.units_in, 0) - coalesce(im.units_out, 0)), 0)
    into v_units
    from erp.inventory_movements im
    where im.item_id = v_pair.item_id
      and im.warehouse_id = v_pair.warehouse_id;

    insert into erp.inventory_balances (
      item_id, warehouse_id, on_hand_qty, on_hand_units,
      avg_unit_cost, stock_value, updated_at
    ) values (
      v_pair.item_id, v_pair.warehouse_id,
      coalesce(v_state.on_hand_qty, 0), coalesce(v_units, 0),
      coalesce(v_state.avg_unit_cost, 0), coalesce(v_state.stock_value, 0), now()
    )
    on conflict (item_id, warehouse_id) do update
    set on_hand_qty = excluded.on_hand_qty,
        on_hand_units = excluded.on_hand_units,
        avg_unit_cost = excluded.avg_unit_cost,
        stock_value = excluded.stock_value,
        updated_at = now();

    insert into erp.inventory_cost_components (
      item_id, warehouse_id, copper_unit_cost, varnish_unit_cost,
      packing_unit_cost, oh_unit_cost, updated_at
    ) values (
      v_pair.item_id, v_pair.warehouse_id,
      coalesce(v_state.copper_unit_cost, 0),
      coalesce(v_state.varnish_unit_cost, 0),
      coalesce(v_state.packing_unit_cost, 0),
      coalesce(v_state.oh_unit_cost, 0),
      now()
    )
    on conflict (item_id, warehouse_id) do update
    set copper_unit_cost = excluded.copper_unit_cost,
        varnish_unit_cost = excluded.varnish_unit_cost,
        packing_unit_cost = excluded.packing_unit_cost,
        oh_unit_cost = excluded.oh_unit_cost,
        updated_at = now();
  end loop;
end;
$$;


ALTER FUNCTION "erp"."rebuild_inventory_balances_for_items"("p_item_ids" "uuid"[]) OWNER TO "postgres";

--
-- Name: FUNCTION "rebuild_inventory_balances_for_items"("p_item_ids" "uuid"[]); Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON FUNCTION "erp"."rebuild_inventory_balances_for_items"("p_item_ids" "uuid"[]) IS 'Rebuilds quantity, value, WAC, units, and component rates from canonical chronological movement replay.';


--
-- Name: reclassify_item("uuid", "text", "text", "text", "text", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."reclassify_item"("p_item_id" "uuid", "p_target_product_type_slug" "text", "p_name" "text", "p_size_spec" "text", "p_item_type" "text" DEFAULT NULL::"text", "p_inventory_group" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item erp.items%rowtype;
  v_target erp.item_product_types%rowtype;
  v_old_group text;
  v_old_wh text;
  v_new_wh text;
  v_warnings text[] := '{}';
  v_top_old text;
  v_top_new text;
begin
  perform erp._assert_posting_access();
  if p_item_id is null then return jsonb_build_object('ok', false, 'error', 'item id is required'); end if;
  if coalesce(trim(p_target_product_type_slug), '') = '' then return jsonb_build_object('ok', false, 'error', 'target product type is required'); end if;
  if coalesce(trim(p_name), '') = '' then return jsonb_build_object('ok', false, 'error', 'item name is required'); end if;
  if coalesce(trim(p_size_spec), '') = '' then return jsonb_build_object('ok', false, 'error', 'size spec is required'); end if;
  select * into v_item from erp.items where id = p_item_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'item not found'); end if;
  if coalesce(v_item.is_active, true) = false then return jsonb_build_object('ok', false, 'error', 'inactive items cannot be reclassified'); end if;
  select * into v_target from erp.item_product_types where slug = trim(p_target_product_type_slug) and is_active = true;
  if not found then return jsonb_build_object('ok', false, 'error', 'target product type not found or inactive'); end if;
  v_old_group := v_item.inventory_group;
  v_top_old := erp._inventory_group_top_category(v_old_group);
  v_top_new := v_target.top_category;
  if v_top_old is distinct from v_top_new then
    return jsonb_build_object('ok', false, 'error', format('cannot reclassify across top categories (%s → %s)', v_top_old, v_top_new));
  end if;
  v_old_wh := erp._inventory_group_warehouse_type(v_old_group);
  v_new_wh := erp._inventory_group_warehouse_type(coalesce(p_inventory_group, v_target.inventory_group));
  if v_old_wh is distinct from v_new_wh then
    return jsonb_build_object('ok', false, 'error', format('warehouse type change not supported (%s → %s)', v_old_wh, v_new_wh));
  end if;
  if v_target.inventory_group = v_old_group and coalesce(p_item_type, v_target.item_type) = v_item.item_type
     and trim(p_name) = v_item.name and trim(p_size_spec) = v_item.size_spec then
    return jsonb_build_object('ok', true, 'id', v_item.id, 'code', v_item.code, 'unchanged', true, 'old_group', v_old_group, 'new_group', v_target.inventory_group);
  end if;
  if v_target.code_prefix is not null and position(v_target.code_prefix in v_item.code) <> 1 then
    v_warnings := array_append(v_warnings, format('Item code %s does not match target prefix %s (code unchanged)', v_item.code, v_target.code_prefix));
  end if;
  update erp.items set inventory_group = coalesce(p_inventory_group, v_target.inventory_group),
    item_type = coalesce(p_item_type, v_target.item_type), name = trim(p_name), size_spec = trim(p_size_spec)
  where id = v_item.id;
  return jsonb_build_object('ok', true, 'id', v_item.id, 'code', v_item.code, 'old_group', v_old_group,
    'new_group', coalesce(p_inventory_group, v_target.inventory_group), 'warnings', to_jsonb(v_warnings));
exception when others then
  return jsonb_build_object('ok', false, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."reclassify_item"("p_item_id" "uuid", "p_target_product_type_slug" "text", "p_name" "text", "p_size_spec" "text", "p_item_type" "text", "p_inventory_group" "text") OWNER TO "postgres";

--
-- Name: refresh_drawing_weekly_wage_sheet_weights("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."refresh_drawing_weekly_wage_sheet_weights"("p_sheet_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_sheet erp.drawing_weekly_wage_sheets%rowtype;
  v_received numeric;
  v_scrap numeric;
  v_totals record;
begin
  perform erp._drawing_wage_post_access();

  select * into v_sheet from erp.drawing_weekly_wage_sheets where id = p_sheet_id for update;
  if not found then raise exception 'Wage sheet not found'; end if;
  if v_sheet.status <> 'draft' then
    raise exception 'Only draft sheets can refresh weights';
  end if;

  select w.received_kg, w.scrap_kg
    into v_received, v_scrap
  from erp.fn_drawing_week_wire8_weights(v_sheet.week_start, v_sheet.week_end) w;

  update erp.drawing_weekly_wage_sheets s
  set
    wire8_received_kg = coalesce(v_received, 0),
    wire8_scrap_kg = coalesce(v_scrap, 0),
    updated_at = now()
  where s.id = p_sheet_id;

  select * into v_sheet from erp.drawing_weekly_wage_sheets where id = p_sheet_id;
  v_received := coalesce(v_sheet.wire8_received_override, v_sheet.wire8_received_kg);
  v_scrap := coalesce(v_sheet.wire8_scrap_override, v_sheet.wire8_scrap_kg);

  select * into v_totals
  from erp._compute_drawing_sheet_totals(v_received, v_scrap, v_sheet.base_rate_pkr, p_sheet_id);

  update erp.drawing_weekly_wage_sheets s
  set
    net_wire8_kg = v_totals.net_kg,
    base_wage_pkr = v_totals.base_wage,
    premium_wage_pkr = v_totals.premium_wage,
    total_wage_pkr = v_totals.total_wage,
    updated_at = now()
  where s.id = p_sheet_id;
end;
$$;


ALTER FUNCTION "erp"."refresh_drawing_weekly_wage_sheet_weights"("p_sheet_id" "uuid") OWNER TO "postgres";

--
-- Name: reopen_accounting_period("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."reopen_accounting_period"("p_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_row erp.costing_periods%rowtype;
begin
  perform erp._assert_report_access();

  select * into v_row from erp.costing_periods where id = p_period_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Period not found');
  end if;
  if v_row.status <> 'locked' then
    return jsonb_build_object('ok', false, 'error', 'Period is not locked');
  end if;

  update erp.costing_periods
    set status = 'open',
        locked_at = null,
        locked_by = null,
        updated_at = now()
    where id = p_period_id;

  return jsonb_build_object('ok', true, 'period_id', p_period_id);
end;
$$;


ALTER FUNCTION "erp"."reopen_accounting_period"("p_period_id" "uuid") OWNER TO "postgres";

--
-- Name: reopen_drawing_weekly_wage_sheet("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."reopen_drawing_weekly_wage_sheet"("p_sheet_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_status text;
begin
  perform erp._drawing_wage_post_access();

  select s.status into v_status
  from erp.drawing_weekly_wage_sheets s
  where s.id = p_sheet_id
  for update;

  if not found then raise exception 'Wage sheet not found'; end if;
  if v_status <> 'posted' then
    raise exception 'Only posted sheets can be reopened';
  end if;

  update erp.drawing_weekly_wage_sheets s
  set
    status = 'draft',
    posted_at = null,
    posted_by = null,
    updated_at = now()
  where s.id = p_sheet_id;
end;
$$;


ALTER FUNCTION "erp"."reopen_drawing_weekly_wage_sheet"("p_sheet_id" "uuid") OWNER TO "postgres";

--
-- Name: repair_inactive_party_opening_gl(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repair_inactive_party_opening_gl"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_party_id uuid;
  v_repaired int := 0;
begin
  for v_party_id in
    select distinct je.source_doc_id
    from erp.journal_entries je
    where je.source_doc_type = 'party_opening'
      and (
        not exists (select 1 from erp.parties p where p.id = je.source_doc_id)
        or exists (
          select 1 from erp.parties p
          where p.id = je.source_doc_id and coalesce(p.is_active, true) = false
        )
      )
  loop
    perform erp._reverse_party_opening(v_party_id);
    update erp.parties
    set opening_fin_balance = 0,
        opening_metal_balance = 0
    where id = v_party_id;
    v_repaired := v_repaired + 1;
  end loop;

  return jsonb_build_object('ok', true, 'parties_repaired', v_repaired);
end;
$$;


ALTER FUNCTION "erp"."repair_inactive_party_opening_gl"() OWNER TO "postgres";

--
-- Name: repair_inventory_costing_chain(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repair_inventory_costing_chain"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare v_batch record; v_batches int := 0; v_transfer numeric; v_total_transfer numeric := 0; v_sales jsonb;
begin
  for v_batch in select pb.id from erp.production_batches pb where pb.status = 'posted' order by pb.batch_date, pb.posted_at nulls last, pb.id loop
    v_transfer := erp._apply_production_batch_costing(v_batch.id);
    v_total_transfer := v_total_transfer + coalesce(v_transfer, 0); v_batches := v_batches + 1;
  end loop;
  perform erp.rebuild_inventory_balances();
  v_sales := erp.repair_sales_cogs_from_movements();
  return jsonb_build_object('production_batches_repaired', v_batches, 'rm_cost_transferred', round(v_total_transfer, 2), 'sales_repair', v_sales);
end; $$;


ALTER FUNCTION "erp"."repair_inventory_costing_chain"() OWNER TO "postgres";

--
-- Name: repair_orphan_scrap_payable_lots(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repair_orphan_scrap_payable_lots"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_before int;
  v_after int;
begin
  select count(*)::int into v_before from erp.scrap_payable_lots;
  perform erp._purge_orphan_scrap_payable_lots();
  select count(*)::int into v_after from erp.scrap_payable_lots;
  return greatest(v_before - v_after, 0);
end;
$$;


ALTER FUNCTION "erp"."repair_orphan_scrap_payable_lots"() OWNER TO "postgres";

--
-- Name: repair_parchi_issue_gl(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repair_parchi_issue_gl"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je record;
  v_p erp.parchi_instruments%rowtype;
  v_count int := 0;
begin
  for v_je in
    select je.id, je.source_doc_id
    from erp.journal_entries je
    where je.voucher_type = 'PARCHI_ISSUE'
      and je.source_doc_type = 'parchi_instrument'
  loop
    select * into v_p from erp.parchi_instruments where id = v_je.source_doc_id;
    if found then
      if v_p.direction = 'received' then
        perform erp._restore_ar_open(v_p.party_id, v_p.total_amount);
      else
        perform erp._restore_ap_open(v_p.party_id, v_p.total_amount);
      end if;
    end if;

    delete from erp.journal_lines where journal_entry_id = v_je.id;
    delete from erp.journal_entries where id = v_je.id;
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$$;


ALTER FUNCTION "erp"."repair_parchi_issue_gl"() OWNER TO "postgres";

--
-- Name: repair_party_opening_balance_postings(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repair_party_opening_balance_postings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_party erp.parties%rowtype;
  v_result jsonb;
  v_repaired int := 0;
  v_failed int := 0;
  v_errors jsonb := '[]'::jsonb;
begin
  for v_party in
    select * from erp.parties
    where coalesce(is_active, true)
      and (coalesce(opening_fin_balance, 0) <> 0 or coalesce(opening_metal_balance, 0) <> 0)
  loop
    if exists (
      select 1 from erp.journal_entries je
      where je.source_doc_type = 'party_opening' and je.source_doc_id = v_party.id
    ) and (
      coalesce(v_party.opening_metal_balance, 0) = 0
      or exists (
        select 1 from erp.inventory_movements im
        where im.source_doc_type = 'party_opening' and im.party_id = v_party.id
      )
    ) then continue; end if;
    v_result := erp.post_party_opening_balance(v_party.id, coalesce(v_party.opening_fin_balance, 0), coalesce(v_party.opening_metal_balance, 0));
    if coalesce(v_result->>'ok', 'false') = 'true' then v_repaired := v_repaired + 1;
    else v_failed := v_failed + 1; v_errors := v_errors || jsonb_build_array(jsonb_build_object('party_code', v_party.code, 'error', v_result->>'error')); end if;
  end loop;
  return jsonb_build_object('ok', v_failed = 0, 'repaired', v_repaired, 'failed', v_failed, 'errors', v_errors);
end;
$$;


ALTER FUNCTION "erp"."repair_party_opening_balance_postings"() OWNER TO "postgres";

--
-- Name: repair_reconciliation_data(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repair_reconciliation_data"() RETURNS TABLE("step" "text", "affected" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_n int;
begin
  perform erp.rebuild_inventory_balances();
  step := 'rebuild_inventory_balances'; affected := 0; return next;

  v_n := erp.repair_parchi_issue_gl();
  step := 'repair_parchi_issue_gl'; affected := v_n; return next;

  v_n := erp.backfill_sales_cogs_journals();
  step := 'backfill_sales_cogs_journals'; affected := v_n; return next;

  v_n := erp.backfill_sales_return_ar_offsets();
  step := 'backfill_sales_return_ar_offsets'; affected := v_n; return next;
end;
$$;


ALTER FUNCTION "erp"."repair_reconciliation_data"() OWNER TO "postgres";

--
-- Name: repair_sales_cogs_from_movements(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repair_sales_cogs_from_movements"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_pair record;
  v_part jsonb;
  v_sales_fixed int := 0;
  v_gl_fixed int := 0;
  v_pairs int := 0;
  v_corrupt_before int := 0;
  v_corrupt_after int := 0;
begin
  perform set_config('erp.skip_cogs_restamp', '1', true);

  select count(*)::int into v_corrupt_before
  from erp.inventory_movements im
  join erp.warehouses w on w.id = im.warehouse_id
  where im.movement_type = 'sales_out'
    and w.wh_type = 'finished_goods'
    and (im.unit_cost < 3000 or im.unit_cost > 4200);

  for v_pair in
    select distinct im.item_id, im.warehouse_id
    from erp.inventory_movements im
    where exists (
      select 1
      from erp.inventory_movements so
      where so.item_id = im.item_id
        and so.warehouse_id = im.warehouse_id
        and so.movement_type = 'sales_out'
    )
  loop
    v_part := erp._restamp_sales_cogs_for_item_wh(v_pair.item_id, v_pair.warehouse_id, null);
    v_sales_fixed := v_sales_fixed + coalesce((v_part->>'sales_out_restamped')::int, 0);
    v_gl_fixed := v_gl_fixed + coalesce((v_part->>'invoices_gl_synced')::int, 0);
    v_pairs := v_pairs + 1;
  end loop;

  perform erp.rebuild_inventory_balances();

  select count(*)::int into v_corrupt_after
  from erp.inventory_movements im
  join erp.warehouses w on w.id = im.warehouse_id
  where im.movement_type = 'sales_out'
    and w.wh_type = 'finished_goods'
    and (im.unit_cost < 3000 or im.unit_cost > 4200);

  perform set_config('erp.skip_cogs_restamp', '0', true);

  return jsonb_build_object(
    'item_warehouse_pairs', v_pairs,
    'sales_out_movements_repaired', v_sales_fixed,
    'cogs_journals_synced', v_gl_fixed,
    'fg_sales_out_of_bounds_before', v_corrupt_before,
    'fg_sales_out_of_bounds_after', v_corrupt_after
  );
end;
$$;


ALTER FUNCTION "erp"."repair_sales_cogs_from_movements"() OWNER TO "postgres";

--
-- Name: repair_varnish_cost_distribution("date", "date", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repair_varnish_cost_distribution"("p_from" "date", "p_to" "date", "p_execute" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_batch record;
  v_pair record;
  v_return_line record;
  v_return_id uuid;
  v_cost record;
  v_part jsonb;
  v_batches int := 0;
  v_sales_moves int := 0;
  v_sales_invoices int := 0;
  v_return_lines int := 0;
  v_production_journals int := 0;
  v_before_non_enameled numeric := 0;
  v_after_non_enameled numeric := 0;
  v_affected_items uuid[] := '{}';
begin
  if auth.uid() is null then
    perform erp._assert_report_access();
  else
    perform erp._assert_admin();
  end if;

  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'A valid from/to date range is required' using errcode = '22023';
  end if;

  if exists (
    select 1 from erp.costing_periods cp
    where cp.status = 'locked'
      and daterange(cp.start_date, cp.end_date, '[]') && daterange(p_from, p_to, '[]')
  ) then
    raise exception 'Cannot repair varnish distribution inside a locked PAC period; reopen it first';
  end if;

  select coalesce(sum(coalesce(im.cost_varnish, 0)), 0)
  into v_before_non_enameled
  from erp.inventory_movements im
  join erp.production_batches pb on pb.id = im.source_doc_id
  where im.source_doc_type = 'production_batch'
    and im.movement_type = 'production_receipt'
    and pb.status = 'posted'
    and pb.batch_date between p_from and p_to
    and not erp._is_enameled_output_item(im.item_id);

  if not coalesce(p_execute, false) then
    return jsonb_build_object(
      'ok', true,
      'executed', false,
      'from', p_from,
      'to', p_to,
      'non_enameled_varnish_before', round(v_before_non_enameled, 3),
      'note', 'Preview only; pass p_execute => true to repair and propagate costs'
    );
  end if;

  if not pg_try_advisory_xact_lock(hashtextextended('erp.repair_varnish_cost_distribution', 0)) then
    raise exception 'Another varnish-cost repair is already running' using errcode = '55P03';
  end if;

  create temp table _varnish_repair_pairs (
    item_id uuid not null,
    warehouse_id uuid not null,
    primary key (item_id, warehouse_id)
  ) on commit drop;

  for v_batch in
    select pb.id, pb.batch_no
    from erp.production_batches pb
    where pb.status = 'posted'
      and pb.batch_date between p_from and p_to
      and exists (
        select 1 from erp.inventory_movements im
        where im.source_doc_type = 'production_batch'
          and im.source_doc_id = pb.id
          and im.movement_type = 'production_receipt'
          and coalesce(im.cost_varnish, 0) <> 0
      )
    order by pb.batch_date, pb.batch_no, pb.id
  loop
    perform erp._redistribute_batch_varnish_cost(v_batch.id);
    v_batches := v_batches + 1;

    insert into pg_temp._varnish_repair_pairs(item_id, warehouse_id)
    select distinct im.item_id, im.warehouse_id
    from erp.inventory_movements im
    where im.source_doc_type = 'production_batch'
      and im.source_doc_id = v_batch.id
      and im.movement_type = 'production_receipt'
      and im.item_id is not null and im.warehouse_id is not null
    on conflict do nothing;

    perform erp._void_rename_active_journals(
      'production_batch', v_batch.id, 'Varnish cost distribution corrected'
    );
    perform erp._sync_production_batch_gl(v_batch.id);
    v_production_journals := v_production_journals + 1;
  end loop;

  select coalesce(array_agg(distinct item_id), '{}') into v_affected_items
  from pg_temp._varnish_repair_pairs;
  if cardinality(v_affected_items) > 0 then
    perform erp.rebuild_inventory_balances_for_items(v_affected_items);
  end if;

  for v_pair in select * from pg_temp._varnish_repair_pairs order by item_id, warehouse_id
  loop
    v_part := erp._restamp_sales_cogs_for_item_wh(v_pair.item_id, v_pair.warehouse_id, null);
    v_sales_moves := v_sales_moves + coalesce((v_part->>'sales_out_restamped')::int, 0);
    v_sales_invoices := v_sales_invoices + coalesce((v_part->>'invoices_gl_synced')::int, 0);
  end loop;

  for v_return_line in
    select l.id, l.sales_return_id
    from erp.sales_return_lines l
    join erp.sales_returns r on r.id = l.sales_return_id
    join pg_temp._varnish_repair_pairs p on p.item_id = l.item_id and p.warehouse_id = l.warehouse_id
    where r.posting_status = 'posted'
      and r.return_action = 'restock'
      and r.return_date >= p_from
      and coalesce(l.qty, 0) > 0
    order by r.return_date, r.return_no, l.line_no
  loop
    select * into v_cost from erp._sales_return_line_inventory_cost(v_return_line.id);
    if found then
      update erp.inventory_movements im
      set unit_cost = v_cost.unit_cost,
          value_amount = v_cost.value_amount,
          cost_copper = v_cost.cost_copper,
          cost_varnish = v_cost.cost_varnish,
          cost_packing = v_cost.cost_packing,
          cost_oh = v_cost.cost_oh
      where im.source_doc_type = 'sales_return'
        and im.source_doc_id = v_return_line.sales_return_id
        and im.source_line_id = v_return_line.id
        and im.movement_type = 'sales_return_in';

      update erp.sales_return_lines
      set source_inventory_movement_id = v_cost.source_movement_id,
          inventory_unit_cost = v_cost.unit_cost,
          inventory_value_amount = v_cost.value_amount,
          inventory_cost_basis = v_cost.cost_basis
      where id = v_return_line.id;

      v_return_lines := v_return_lines + 1;
    end if;
  end loop;

  for v_return_id in
    select distinct l.sales_return_id
    from erp.sales_return_lines l
    join erp.sales_returns r on r.id = l.sales_return_id
    join pg_temp._varnish_repair_pairs p on p.item_id = l.item_id and p.warehouse_id = l.warehouse_id
    where r.posting_status = 'posted' and r.return_action = 'restock' and r.return_date >= p_from
  loop
    perform erp._sync_sales_return_cogs_gl(v_return_id);
  end loop;

  if cardinality(v_affected_items) > 0 then
    perform erp.rebuild_inventory_balances_for_items(v_affected_items);
  end if;

  select coalesce(sum(coalesce(im.cost_varnish, 0)), 0)
  into v_after_non_enameled
  from erp.inventory_movements im
  join erp.production_batches pb on pb.id = im.source_doc_id
  where im.source_doc_type = 'production_batch'
    and im.movement_type = 'production_receipt'
    and pb.status = 'posted'
    and pb.batch_date between p_from and p_to
    and not erp._is_enameled_output_item(im.item_id);

  return jsonb_build_object(
    'ok', true,
    'executed', true,
    'from', p_from,
    'to', p_to,
    'batches_repaired', v_batches,
    'non_enameled_varnish_before', round(v_before_non_enameled, 3),
    'non_enameled_varnish_after', round(v_after_non_enameled, 3),
    'sales_movements_restamped', v_sales_moves,
    'sales_invoices_gl_synced', v_sales_invoices,
    'sales_return_lines_restamped', v_return_lines,
    'production_journals_synced', v_production_journals
  );
end;
$$;


ALTER FUNCTION "erp"."repair_varnish_cost_distribution"("p_from" "date", "p_to" "date", "p_execute" boolean) OWNER TO "postgres";

--
-- Name: repair_voided_parchi_orphan_gl(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repair_voided_parchi_orphan_gl"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_p record;
  v_total int := 0;
  v_n int;
begin
  for v_p in
    select distinct je.source_doc_id as parchi_id
    from erp.journal_entries je
    where je.source_doc_type = 'parchi_instrument'
      and je.voucher_type = 'PARCHI_ISSUE'
      and coalesce(je.voucher_no, '') not like 'VOID-%'
      and not exists (
        select 1 from erp.journal_entries rev
        where rev.source_doc_id = je.source_doc_id
          and rev.source_doc_type = 'parchi_instrument'
          and coalesce(rev.voucher_no, '') like 'VOID-%'
      )
  loop
    v_n := erp._reverse_parchi_issue_gl_for(v_p.parchi_id, 'Repair voided parchi GL');
    v_total := v_total + v_n;
  end loop;
  return v_total;
end;
$$;


ALTER FUNCTION "erp"."repair_voided_parchi_orphan_gl"() OWNER TO "postgres";

--
-- Name: replace_factory_scrap_dispatch("uuid", "jsonb", boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."replace_factory_scrap_dispatch"("p_doc_id" "uuid", "p_payload" "jsonb", "p_post" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.factory_scrap_dispatches%rowtype;
  v_line jsonb;
  v_idx int := 0;
  v_dest_party_id uuid;
  v_item_id uuid;
  v_header_item_id uuid;
  v_expected_item_id uuid;
  v_dispatch_date date;
  v_previous_skip text;
begin
  perform erp._assert_posting_access();

  if p_payload is null
     or jsonb_typeof(p_payload->'lines') <> 'array'
     or jsonb_array_length(p_payload->'lines') = 0 then
    raise exception 'add at least one machine scrap line';
  end if;

  select * into v_doc
  from erp.factory_scrap_dispatches
  where id = p_doc_id
  for update;
  if not found then
    raise exception 'factory scrap dispatch not found';
  end if;

  v_dispatch_date := (p_payload->>'dispatchDate')::date;
  select id into v_dest_party_id
  from erp.parties
  where code = p_payload->>'destPartyCode'
  limit 1;
  if v_dest_party_id is null then
    raise exception 'vendor party not found';
  end if;

  if nullif(p_payload->>'expectedReturnItemCode', '') is not null then
    select id into v_expected_item_id
    from erp.items
    where code = p_payload->>'expectedReturnItemCode'
    limit 1;
    if v_expected_item_id is null then
      raise exception 'expected return item not found: %', p_payload->>'expectedReturnItemCode';
    end if;
  end if;

  if v_doc.status = 'posted' then
    perform erp._assert_factory_scrap_has_no_returns(v_doc.id);
    perform erp._clear_factory_scrap_dispatch_posting(v_doc.id);
    perform erp._clear_factory_scrap_obligation(v_doc.id);
  end if;

  update erp.factory_scrap_dispatches
  set status = 'draft',
      posted_at = null,
      posted_by = null
  where id = v_doc.id;

  delete from erp.factory_scrap_dispatch_lines where dispatch_id = v_doc.id;

  for v_line in select value from jsonb_array_elements(p_payload->'lines') as t(value)
  loop
    v_idx := v_idx + 1;
    select id into v_item_id
    from erp.items
    where code = v_line->>'itemCode'
    limit 1;
    if v_item_id is null then
      raise exception 'item not found: %', v_line->>'itemCode';
    end if;
    if v_header_item_id is null then v_header_item_id := v_item_id; end if;

    insert into erp.factory_scrap_dispatch_lines (
      dispatch_id, line_no, machine_id, department, item_id,
      gross_weight, tare_weight, net_weight
    ) values (
      v_doc.id,
      v_idx,
      nullif(v_line->>'machineId', '')::uuid,
      v_line->>'department',
      v_item_id,
      coalesce((v_line->>'grossWeight')::numeric, 0),
      coalesce((v_line->>'tareWeight')::numeric, 0),
      coalesce((v_line->>'netWeight')::numeric, 0)
    );
  end loop;

  if nullif(p_payload->>'itemCode', '') is not null then
    select id into v_header_item_id
    from erp.items
    where code = p_payload->>'itemCode'
    limit 1;
  end if;

  update erp.factory_scrap_dispatches
  set dispatch_date = v_dispatch_date,
      dest_party_id = v_dest_party_id,
      mode = p_payload->>'mode',
      item_id = v_header_item_id,
      expected_return_item_id = case
        when p_payload->>'mode' = 'toll' then v_expected_item_id
        else null
      end,
      expected_return_kg = case
        when p_payload->>'mode' = 'toll'
          then coalesce((p_payload->>'expectedReturnKg')::numeric, (p_payload->>'netWeight')::numeric)
        else 0
      end,
      gross_weight = coalesce((p_payload->>'grossWeight')::numeric, 0),
      tare_weight = coalesce((p_payload->>'tareWeight')::numeric, 0),
      net_weight = coalesce((p_payload->>'netWeight')::numeric, 0),
      unit_rate = coalesce((p_payload->>'unitRate')::numeric, 0),
      amount = coalesce((p_payload->>'amount')::numeric, 0),
      bilty_no = nullif(p_payload->>'biltyNo', ''),
      vehicle_no = nullif(p_payload->>'vehicleNo', ''),
      remarks = nullif(p_payload->>'remarks', '')
  where id = v_doc.id;

  if p_post then
    v_previous_skip := coalesce(
      nullif(current_setting('erp.skip_period_lock_check', true), ''),
      '0'
    );
    if v_doc.status = 'posted' and v_dispatch_date = v_doc.dispatch_date then
      perform set_config('erp.skip_period_lock_check', '1', true);
    end if;

    perform erp.post_factory_scrap_dispatch(v_doc.id);
    perform set_config('erp.skip_period_lock_check', v_previous_skip, true);
  end if;

  return jsonb_build_object(
    'ok', true,
    'dispatch_id', v_doc.id,
    'posted', p_post
  );
end;
$$;


ALTER FUNCTION "erp"."replace_factory_scrap_dispatch"("p_doc_id" "uuid", "p_payload" "jsonb", "p_post" boolean) OWNER TO "postgres";

--
-- Name: replace_production_batch("uuid", "date", "jsonb", "uuid", numeric, numeric, numeric, boolean); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."replace_production_batch"("p_batch_id" "uuid", "p_batch_date" "date", "p_lines" "jsonb", "p_machine_id" "uuid" DEFAULT NULL::"uuid", "p_input_kg" numeric DEFAULT NULL::numeric, "p_output_kg" numeric DEFAULT NULL::numeric, "p_scrap_kg" numeric DEFAULT NULL::numeric, "p_post" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_existing erp.production_batches%rowtype;
  v_previous_skip text;
  v_result jsonb;
begin
  perform erp._assert_posting_access();

  select * into v_existing
  from erp.production_batches
  where id = p_batch_id
  for update;
  if not found then
    raise exception 'production batch not found';
  end if;

  v_previous_skip := coalesce(
    nullif(current_setting('erp.skip_period_lock_check', true), ''),
    '0'
  );

  if p_post
     and v_existing.status = 'posted'
     and p_batch_date = v_existing.batch_date then
    perform set_config('erp.skip_period_lock_check', '1', true);
  end if;

  v_result := erp._replace_production_batch_changed_lines(
    p_batch_id,
    p_batch_date,
    p_lines,
    p_machine_id,
    p_input_kg,
    p_output_kg,
    p_scrap_kg,
    p_post
  );

  perform set_config('erp.skip_period_lock_check', v_previous_skip, true);
  return v_result;
end;
$$;


ALTER FUNCTION "erp"."replace_production_batch"("p_batch_id" "uuid", "p_batch_date" "date", "p_lines" "jsonb", "p_machine_id" "uuid", "p_input_kg" numeric, "p_output_kg" numeric, "p_scrap_kg" numeric, "p_post" boolean) OWNER TO "postgres";

--
-- Name: repost_purchase_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repost_purchase_invoice"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_invoices%rowtype;
  v_item_ids uuid[] := '{}';
  v_new_item_ids uuid[] := '{}';
  v_step text := 'init';
  v_allocated numeric := 0;
  v_allocated_wrong_party boolean := false;
  v_physical_unchanged boolean := false;
  v_cascade jsonb := '{}'::jsonb;
begin
  perform erp._assert_posting_access();

  v_step := 'lock_invoice';
  select * into v_doc from erp.purchase_invoices where id = p_doc_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', 'purchase invoice not found');
  end if;
  if v_doc.posting_status <> 'posted' then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', 'only posted purchase invoices can be reposted');
  end if;

  select coalesce(sum(pa.allocated_amount), 0),
         coalesce(bool_or(ad.party_id is distinct from v_doc.party_id), false)
  into v_allocated, v_allocated_wrong_party
  from erp.ap_documents ad
  join erp.payment_allocations pa on pa.ap_document_id = ad.id
  where ad.source_doc_type = 'purchase_invoice'
    and ad.source_doc_id = v_doc.id;

  if coalesce(v_allocated, 0) > 0 and v_allocated_wrong_party then
    return jsonb_build_object(
      'ok', false,
      'step', 'check_payments',
      'error', 'cannot repost: allocated purchase invoice supplier cannot be changed'
    );
  end if;

  v_item_ids := erp._item_ids_from_inventory_movements('purchase_invoice', v_doc.id);

  select coalesce(array_agg(distinct l.item_id) filter (where l.item_id is not null), '{}')
  into v_new_item_ids
  from erp.purchase_invoice_lines l
  where l.purchase_invoice_id = v_doc.id;
  v_item_ids := erp._merge_item_id_arrays(v_item_ids, v_new_item_ids);

  v_step := 'check_returns';
  if exists (select 1 from erp.purchase_returns where ref_invoice_id = v_doc.id) then
    return jsonb_build_object(
      'ok', false,
      'step', v_step,
      'error', 'cannot repost: invoice has linked purchase returns'
    );
  end if;

  v_step := 'check_physical_shape';
  with mov as (
    select im.item_id, im.warehouse_id,
           round(sum(coalesce(im.qty_in, 0)), 3) as qty,
           round(sum(greatest(coalesce(im.units_in, 0), 0)), 3) as units,
           count(*) as rows_count
    from erp.inventory_movements im
    where im.source_doc_type = 'purchase_invoice'
      and im.source_doc_id = v_doc.id
      and coalesce(im.qty_in, 0) > 0
      and coalesce(im.qty_out, 0) = 0
    group by im.item_id, im.warehouse_id
  ),
  lin as (
    select l.item_id, l.warehouse_id,
           round(sum(coalesce(l.net_weight, l.qty, 0)), 3) as qty,
           round(sum(greatest(coalesce(l.unit_count, 0), 0)), 3) as units,
           count(*) as rows_count
    from erp.purchase_invoice_lines l
    where l.purchase_invoice_id = v_doc.id
      and l.item_id is not null
      and coalesce(l.net_weight, l.qty, 0) > 0
    group by l.item_id, l.warehouse_id
  )
  select not exists (
    select 1
    from mov
    full join lin using (item_id, warehouse_id)
    where mov.item_id is null
       or lin.item_id is null
       or abs(mov.qty - lin.qty) > 0.0005
       or abs(mov.units - lin.units) > 0.0005
       or mov.rows_count <> lin.rows_count
  )
  into v_physical_unchanged;

  if v_physical_unchanged then
    v_step := 'reprice_without_stock_replay';
    perform erp._reprice_purchase_invoice_without_stock_replay(v_doc.id);

    v_step := 'cascade_cogs';
    v_cascade := erp._cascade_purchase_reprice_cogs(v_doc.id);

    return jsonb_build_object(
      'ok', true,
      'step', 'done',
      'id', v_doc.id,
      'mode', 'reprice_without_stock_replay_line_id_tolerant',
      'cogs_cascade', v_cascade
    );
  end if;

  v_step := 'revert_order_receiving';
  perform erp._revert_purchase_order_receiving_from_invoice(v_doc.id);

  v_step := 'void_pending_rates';
  perform erp._void_pending_rate_items_for_doc('purchase_invoice', v_doc.id);

  v_step := 'revert_premium_scrap_pool';
  perform erp._revert_premium_purchase_scrap_pool(v_doc.id);

  v_step := 'clear_side_effects';
  delete from erp.inventory_movements
  where source_doc_type = 'purchase_invoice' and source_doc_id = v_doc.id;
  delete from erp.ap_documents ad
  where ad.source_doc_type = 'purchase_invoice'
    and ad.source_doc_id = v_doc.id
    and not exists (
      select 1 from erp.payment_allocations pa where pa.ap_document_id = ad.id
    );
  perform erp._hard_delete_clear_journals('purchase_invoice', v_doc.id);

  v_step := 'mark_draft';
  update erp.purchase_invoices
  set posting_status = 'draft',
      posted_at = null,
      posted_by = null
  where id = v_doc.id;

  v_step := 'rebuild_before_post';
  perform erp._rebuild_after_document_post(v_item_ids);

  v_step := 'repost';
  perform erp.post_purchase_invoice(v_doc.id);

  v_step := 'cascade_cogs';
  v_cascade := erp._cascade_purchase_reprice_cogs(v_doc.id);

  return jsonb_build_object(
    'ok', true,
    'step', 'done',
    'id', v_doc.id,
    'mode', 'full_repost',
    'cogs_cascade', v_cascade
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."repost_purchase_invoice"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: repost_purchase_return("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repost_purchase_return"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare v_doc erp.purchase_returns%rowtype; v_item_ids uuid[] := '{}'; v_new_item_ids uuid[] := '{}'; v_step text := 'init';
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.purchase_returns where id = p_doc_id for update;
  if not found then return jsonb_build_object('ok', false, 'step', 'lock_return', 'error', 'purchase return not found'); end if;
  if v_doc.posting_status <> 'posted' then return jsonb_build_object('ok', false, 'step', 'lock_return', 'error', 'only posted purchase returns can be reposted'); end if;
  v_item_ids := erp._item_ids_from_inventory_movements('purchase_return', v_doc.id);
  select coalesce(array_agg(distinct l.item_id) filter (where l.item_id is not null), '{}') into v_new_item_ids from erp.purchase_return_lines l where l.purchase_return_id = v_doc.id;
  v_item_ids := erp._merge_item_id_arrays(v_item_ids, v_new_item_ids);
  perform erp._void_pending_rate_items_for_doc('purchase_return', v_doc.id);
  delete from erp.inventory_movements where source_doc_type = 'purchase_return' and source_doc_id = v_doc.id;
  delete from erp.ap_documents where source_doc_type = 'purchase_return' and source_doc_id = v_doc.id;
  perform erp._hard_delete_clear_journals('purchase_return', v_doc.id);
  update erp.purchase_returns set posting_status = 'draft', posted_at = null, posted_by = null where id = v_doc.id;
  perform erp._rebuild_after_document_post(v_item_ids);
  perform erp.post_purchase_return(v_doc.id);
  return jsonb_build_object('ok', true, 'step', 'done', 'id', v_doc.id);
exception when others then return jsonb_build_object('ok', false, 'step', v_step, 'error', sqlerrm, 'code', sqlstate);
end; $$;


