--
-- Name: repost_sales_invoice("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repost_sales_invoice"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_invoices%rowtype;
  v_item_ids uuid[] := '{}';
  v_new_item_ids uuid[] := '{}';
  v_step text := 'init';
begin
  perform erp._assert_posting_access();

  v_step := 'lock_invoice';
  select * into v_doc from erp.sales_invoices where id = p_doc_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', 'sales invoice not found');
  end if;
  if v_doc.posting_status <> 'posted' then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', 'only posted sales invoices can be reposted');
  end if;

  v_item_ids := erp._item_ids_from_inventory_movements('sales_invoice', v_doc.id);

  select coalesce(array_agg(distinct l.item_id) filter (where l.item_id is not null), '{}')
  into v_new_item_ids
  from erp.sales_invoice_lines l
  where l.sales_invoice_id = v_doc.id;
  v_item_ids := erp._merge_item_id_arrays(v_item_ids, v_new_item_ids);

  v_step := 'check_payments';
  if exists (
    select 1
    from erp.ar_documents ad
    join erp.payment_allocations pa on pa.ar_document_id = ad.id
    where ad.source_doc_type = 'sales_invoice' and ad.source_doc_id = v_doc.id
  ) then
    return jsonb_build_object(
      'ok', false,
      'step', v_step,
      'error', 'cannot repost: invoice has payment allocations — clear cashbook allocations first'
    );
  end if;

  v_step := 'check_returns';
  if exists (select 1 from erp.sales_returns where ref_invoice_id = v_doc.id) then
    return jsonb_build_object(
      'ok', false,
      'step', v_step,
      'error', 'cannot repost: invoice has linked sales returns'
    );
  end if;

  v_step := 'check_scrap_receipts';
  if to_regclass('erp.scrap_receivable_obligations') is not null
     and exists (
       select 1
       from erp.scrap_receivable_obligations o
       join erp.scrap_receipts r on r.obligation_id = o.id
       where o.sales_invoice_id = v_doc.id
          or o.sales_invoice_no = v_doc.invoice_no
     ) then
    return jsonb_build_object(
      'ok', false,
      'step', v_step,
      'error', 'cannot repost: premium scrap receipts exist against this invoice'
    );
  end if;

  v_step := 'revert_order_fulfillment';
  perform erp._revert_sales_order_fulfillment_from_invoice(v_doc.id);

  v_step := 'void_pending_rates';
  perform erp._void_pending_rate_items_for_doc('sales_invoice', v_doc.id);

  v_step := 'clear_premium_obligation';
  if to_regclass('erp.scrap_receivable_obligations') is not null then
    delete from erp.scrap_receivable_obligations
    where sales_invoice_id = v_doc.id
       or sales_invoice_no = v_doc.invoice_no;
  end if;

  v_step := 'clear_side_effects';
  delete from erp.inventory_movements
  where source_doc_type = 'sales_invoice' and source_doc_id = v_doc.id;
  delete from erp.ar_documents
  where source_doc_type = 'sales_invoice' and source_doc_id = v_doc.id;
  perform erp._hard_delete_clear_journals('sales_invoice', v_doc.id);

  v_step := 'mark_draft';
  update erp.sales_invoices
  set posting_status = 'draft',
      posted_at = null,
      posted_by = null
  where id = v_doc.id;

  v_step := 'rebuild_before_post';
  perform erp._rebuild_after_document_post(v_item_ids);

  v_step := 'repost';
  perform erp.post_sales_invoice(v_doc.id);

  return jsonb_build_object('ok', true, 'step', 'done', 'id', v_doc.id);
exception
  when others then
    return jsonb_build_object('ok', false, 'step', v_step, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."repost_sales_invoice"("p_doc_id" "uuid") OWNER TO "postgres";

