--
-- Name: repost_scrap_trade("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."repost_scrap_trade"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_trades%rowtype;
  v_item_ids uuid[] := '{}';
  v_receipt_id uuid;
  v_lot_ids uuid[];
  v_alloc jsonb := '[]'::jsonb;
  v_alloc_row record;
  v_step text := 'init';
begin
  perform erp._assert_posting_access();
  v_step := 'lock_trade';
  select * into v_doc from erp.scrap_trades where id = p_doc_id for update;
  if not found then return jsonb_build_object('ok', false, 'step', v_step, 'error', 'scrap trade not found'); end if;
  if v_doc.status <> 'posted' then return jsonb_build_object('ok', false, 'step', v_step, 'error', 'only posted scrap trades can be reposted'); end if;
  v_item_ids := erp._item_ids_from_inventory_movements('scrap_trade', v_doc.id);
  if v_doc.item_id is not null then v_item_ids := erp._merge_item_id_arrays(v_item_ids, array[v_doc.item_id]); end if;
  if to_regclass('erp.scrap_obligation_allocations') is not null then
    select coalesce(jsonb_agg(jsonb_build_object('obligation_id', a.obligation_id, 'allocated_kg', a.allocated_kg, 'receipt_id', a.receipt_id, 'line_seq', a.line_seq) order by a.line_seq), '[]'::jsonb)
    into v_alloc from erp.scrap_obligation_allocations a where a.scrap_trade_id = v_doc.id;
    for v_alloc_row in select a.obligation_id, a.allocated_kg from erp.scrap_obligation_allocations a where a.scrap_trade_id = v_doc.id order by a.line_seq loop
      update erp.scrap_receivable_obligations set received_kg = greatest(0, received_kg - v_alloc_row.allocated_kg) where id = v_alloc_row.obligation_id;
      perform erp._sync_scrap_obligation_status(v_alloc_row.obligation_id);
    end loop;
    delete from erp.scrap_obligation_allocations where scrap_trade_id = v_doc.id;
  end if;
  for v_receipt_id in select id from erp.scrap_receipts where scrap_trade_id = v_doc.id loop
    perform erp.hard_delete_scrap_receipt(v_receipt_id);
  end loop;
  select coalesce(array_agg(id), '{}') into v_lot_ids from erp.scrap_payable_lots where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id;
  if coalesce(array_length(v_lot_ids, 1), 0) > 0 then
    delete from erp.scrap_allocations where scrap_lot_id = any(v_lot_ids);
    delete from erp.scrap_payable_lots where id = any(v_lot_ids);
  end if;
  perform erp._void_pending_rate_items_for_doc('scrap_trade', v_doc.id);
  delete from erp.inventory_movements where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id;
  delete from erp.ar_documents where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id;
  delete from erp.ap_documents where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id;
  perform erp._hard_delete_clear_journals('scrap_trade', v_doc.id);
  update erp.scrap_trades set status = 'draft', posted_at = null, posted_by = null where id = v_doc.id;
  perform erp._rebuild_after_document_post(v_item_ids);
  if jsonb_array_length(v_alloc) > 0 then perform erp.post_scrap_trade(v_doc.id, null, v_alloc); else perform erp.post_scrap_trade(v_doc.id); end if;
  return jsonb_build_object('ok', true, 'step', 'done', 'id', v_doc.id);
exception when others then return jsonb_build_object('ok', false, 'step', v_step, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."repost_scrap_trade"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: resolve_inventory_valuation_rate("uuid", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."resolve_inventory_valuation_rate"("p_item_id" "uuid", "p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_section text;
  v_swg numeric;
  v_grade text;
  v_scrap text;
  v_spec text;
  v_name text;
  v_spec_key text;
  v_rate numeric;
begin
  select i.size_spec, i.name into v_spec, v_name from erp.items i where i.id = p_item_id;
  if not found then return null; end if;
  select o.unit_rate into v_rate from erp.inventory_valuation_item_overrides o
  where o.item_id = p_item_id and o.is_active and o.effective_from <= p_as_of
  order by o.effective_from desc limit 1;
  if v_rate is not null then return v_rate; end if;
  v_section := erp._item_inventory_section(p_item_id);
  if v_section = 'fg_enameled' then
    v_swg := erp._parse_item_swg_decimal(v_spec);
    if v_swg is null then return null; end if;
    select r.unit_rate into v_rate from erp.inventory_valuation_rates r
    where r.is_active and r.product_kind = 'enamel' and r.effective_from <= p_as_of
      and v_swg between r.swg_min and r.swg_max
    order by (r.swg_max - r.swg_min), r.effective_from desc limit 1;
    return v_rate;
  end if;
  if v_section = 'fg_copper_wire' then
    v_spec_key := erp._normalize_valuation_spec_key(v_spec, v_name);
    if v_spec_key is null then return null; end if;
    select r.unit_rate into v_rate from erp.inventory_valuation_rates r
    where r.is_active and r.product_kind = 'copper_wire' and r.spec_key = v_spec_key and r.effective_from <= p_as_of
    order by r.effective_from desc limit 1;
    return v_rate;
  end if;
  if v_section = 'fg_strip' then
    v_spec_key := erp._normalize_valuation_spec_key(v_spec, v_name);
    if v_spec_key is null then return null; end if;
    select r.unit_rate into v_rate from erp.inventory_valuation_rates r
    where r.is_active and r.product_kind = 'strip' and r.spec_key = v_spec_key and r.effective_from <= p_as_of
    order by r.effective_from desc limit 1;
    return v_rate;
  end if;
  if v_section = 'rm_wire8' then
    v_grade := erp._parse_wire8_grade(v_spec, v_name);
    if v_grade is not null then
      select r.unit_rate into v_rate from erp.inventory_valuation_rates r
      where r.is_active and r.product_kind = 'wire8' and r.effective_from <= p_as_of and r.wire8_grade = v_grade
      order by r.effective_from desc limit 1;
    end if;
    if v_rate is null then
      select r.unit_rate into v_rate from erp.inventory_valuation_rates r
      where r.is_active and r.product_kind = 'wire8' and r.effective_from <= p_as_of and r.wire8_grade = 'Pass'
      order by r.effective_from desc limit 1;
    end if;
    if v_rate is null then
      select r.unit_rate into v_rate from erp.inventory_valuation_rates r
      where r.is_active and r.product_kind = 'wire8' and r.effective_from <= p_as_of
      order by r.effective_from desc limit 1;
    end if;
    return v_rate;
  end if;
  if v_section = 'rm_rod' then
    select r.unit_rate into v_rate from erp.inventory_valuation_rates r
    where r.is_active and r.product_kind = 'rod' and r.effective_from <= p_as_of
    order by r.effective_from desc limit 1;
    return v_rate;
  end if;
  if v_section = 'rm_scrap' then
    v_scrap := erp._item_scrap_kind(p_item_id);
    select r.unit_rate into v_rate from erp.inventory_valuation_rates r
    where r.is_active and r.product_kind = 'scrap' and r.scrap_kind = v_scrap and r.effective_from <= p_as_of
    order by r.effective_from desc limit 1;
    return v_rate;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "erp"."resolve_inventory_valuation_rate"("p_item_id" "uuid", "p_as_of" "date") OWNER TO "postgres";

--
-- Name: resolve_watta("uuid", "uuid", "text", "date", integer, "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."resolve_watta"("p_party_id" "uuid" DEFAULT NULL::"uuid", "p_item_id" "uuid" DEFAULT NULL::"uuid", "p_direction" "text" DEFAULT 'sales'::"text", "p_as_of" "date" DEFAULT CURRENT_DATE, "p_swg_override" integer DEFAULT NULL::integer, "p_wire8_grade" "text" DEFAULT NULL::"text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_kind text;
  v_swg int;
  v_spec text;
  v_grade text;
  v_row erp.watta_matrix%rowtype;
  v_watta numeric;
begin
  if p_item_id is null then return 0; end if;
  v_kind := erp._item_product_kind(p_item_id);
  select nullif(trim(coalesce(i.size_spec, '')), '') into v_spec from erp.items i where i.id = p_item_id;
  v_swg := coalesce(p_swg_override, erp._parse_item_swg(v_spec));

  if v_kind = 'wire8' then
    v_grade := nullif(trim(coalesce(p_wire8_grade, '')), '');
    if v_grade is null and v_spec in ('Fail', 'Pass', 'Special') then
      v_grade := v_spec;
    end if;
    if v_grade is null then
      select case
        when coalesce(i.name, '') ilike '%fail%' then 'Fail'
        when coalesce(i.name, '') ilike '%special%' then 'Special'
        else 'Pass'
      end into v_grade
      from erp.items i where i.id = p_item_id;
    end if;
  end if;

  select * into v_row
  from erp.watta_matrix w
  where w.direction = p_direction
    and w.product_kind = v_kind
    and w.is_active = true
    and w.effective_from <= coalesce(p_as_of, current_date)
    and (w.party_id = p_party_id or w.party_id is null)
    and (v_kind <> 'wire8' or w.wire8_grade is null or w.wire8_grade = v_grade)
    and (
      v_kind <> 'enamel'
      or (
        (w.swg_min is null and w.swg_max is null)
        or (v_swg is not null and (w.swg_min is null or v_swg >= w.swg_min) and (w.swg_max is null or v_swg <= w.swg_max))
      )
    )
  order by
    case when w.party_id = p_party_id then 0 else 1 end,
    w.effective_from desc
  limit 1;

  if not found then return 0; end if;

  v_watta := v_row.base_watta;
  if v_kind = 'enamel' and v_swg is not null and v_row.swg_min is not null
     and v_swg > v_row.swg_min and coalesce(v_row.increment_per_swg, 0) <> 0 then
    v_watta := v_watta + (v_swg - v_row.swg_min) * v_row.increment_per_swg;
  end if;

  return round(v_watta, 3);
end;
$$;


ALTER FUNCTION "erp"."resolve_watta"("p_party_id" "uuid", "p_item_id" "uuid", "p_direction" "text", "p_as_of" "date", "p_swg_override" integer, "p_wire8_grade" "text") OWNER TO "postgres";

--
-- Name: run_periodic_costing("date", "date", boolean, numeric, numeric, "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."run_periodic_costing"("p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean DEFAULT true, "p_actual_overhead_rate" numeric DEFAULT NULL::numeric, "p_actual_overhead_amount" numeric DEFAULT NULL::numeric, "p_period_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_period_id uuid;
  v_oh numeric;
  v_rm_result jsonb;
  v_prod_result jsonb;
  v_prod_gl_result jsonb := '{}'::jsonb;
  v_cogs_result jsonb;
  v_run_id uuid;
  v_warnings jsonb := '[]'::jsonb;
  v_stats jsonb := '{}'::jsonb;
  v_oh_amount_source text := 'manual';
  v_fg_kg numeric := 0;
begin
  perform erp._assert_report_access();

  if p_end_date < p_start_date then
    raise exception 'end_date must be >= start_date';
  end if;

  if not p_is_draft
     and p_actual_overhead_amount is null
     and coalesce(p_actual_overhead_rate, 0) <= 0 then
    p_actual_overhead_amount := coalesce(
      erp._pac_auto_overhead_amount(p_start_date, p_end_date),
      0
    );
    v_oh_amount_source := 'auto_gl';
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object(
        'code', 'OH_AUTO_FROM_GL',
        'message', 'Actual overhead amount auto-calculated from posted factory cashbook/GL',
        'amount', p_actual_overhead_amount
      )
    );
  elsif p_actual_overhead_amount is not null or coalesce(p_actual_overhead_rate, 0) > 0 then
    v_oh_amount_source := 'manual';
  end if;

  if not p_is_draft then
    if exists (
      select 1 from erp.costing_periods
      where status = 'locked'
        and p_start_date between start_date and end_date
        and p_end_date between start_date and end_date
    ) then
      raise exception 'Period already locked — reopen it first';
    end if;
  end if;

  perform set_config('erp.skip_cogs_restamp', '1', true);
  perform set_config('erp.skip_period_lock_check', '1', true);

  v_period_id := erp._pac_upsert_period(p_start_date, p_end_date, p_is_draft, p_period_code);

  insert into erp.period_costing_runs (period_id, mode, started_at, run_by)
  values (v_period_id, case when p_is_draft then 'draft' else 'final' end, now(), auth.uid())
  returning id into v_run_id;

  begin
    v_rm_result := erp._pac_compute_rm_rates(v_period_id, p_start_date, p_end_date, p_is_draft);
    v_warnings := v_warnings || coalesce(v_rm_result->'warnings', '[]'::jsonb);

    v_oh := erp._pac_resolve_overhead(
      v_period_id, p_start_date, p_end_date, p_is_draft,
      p_actual_overhead_rate, p_actual_overhead_amount
    );

    v_fg_kg := coalesce(erp._pac_period_fg_output_kg(p_start_date, p_end_date), 0);

    if not p_is_draft
       and coalesce(v_oh, 0) <= 0
       and coalesce(p_actual_overhead_amount, 0) > 0
       and v_fg_kg > 0 then
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object(
          'code', 'OH_RATE_ZERO_WITH_AMOUNT',
          'message', 'Final overhead rate resolved to 0 while overhead amount and FG kg are positive',
          'overhead_amount', p_actual_overhead_amount,
          'fg_output_kg', v_fg_kg
        )
      );
    end if;

    v_prod_result := erp._pac_cost_production(v_period_id, p_start_date, p_end_date, v_oh, p_is_draft);

    if not p_is_draft then
      v_prod_gl_result := erp._pac_rebuild_production_gl(p_start_date, p_end_date);
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object(
          'code', 'PROD_GL_REBUILT',
          'message', 'Production journal entries rebuilt from PAC-stamped movements',
          'detail', v_prod_gl_result
        )
      );
    end if;

    v_cogs_result := erp._pac_stamp_cogs(v_period_id, p_start_date, p_end_date, p_is_draft);

    perform erp._pac_rebuild_and_finalize(v_period_id, p_is_draft, v_oh);

    v_stats := jsonb_build_object(
      'overhead_rate_used', v_oh,
      'overhead_amount', p_actual_overhead_amount,
      'overhead_amount_source', v_oh_amount_source,
      'rm_rates', v_rm_result->'rates',
      'production', v_prod_result,
      'production_gl', v_prod_gl_result,
      'cogs', v_cogs_result,
      'warnings', v_warnings
    );

    update erp.period_costing_runs
      set finished_at = now(),
          ok = true,
          overhead_rate_used = v_oh,
          stats = v_stats
      where id = v_run_id;

    return jsonb_build_object(
      'ok', true,
      'period_id', v_period_id,
      'mode', case when p_is_draft then 'draft' else 'final' end,
      'overhead_rate_used', v_oh,
      'overhead_amount', p_actual_overhead_amount,
      'overhead_amount_source', v_oh_amount_source,
      'stats', v_stats
    );
  exception when others then
    update erp.period_costing_runs
      set finished_at = now(),
          ok = false,
          error_text = sqlerrm
      where id = v_run_id;
    raise;
  end;
end;
$$;


ALTER FUNCTION "erp"."run_periodic_costing"("p_start_date" "date", "p_end_date" "date", "p_is_draft" boolean, "p_actual_overhead_rate" numeric, "p_actual_overhead_amount" numeric, "p_period_code" "text") OWNER TO "postgres";

--
-- Name: save_and_post_payment("jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."save_and_post_payment"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_replace uuid;
  v_old erp.payments%rowtype;
  v_del jsonb;
  v_party_id uuid;
  v_counter_party_id uuid;
  v_payment_id uuid;
  v_entry_kind text;
  v_clr jsonb;
  v_payment_type text;
  v_freed_no text;
begin
  perform erp._assert_posting_access();

  v_replace := nullif(p_payload->>'replace_payment_id', '')::uuid;
  if v_replace is not null then
    select * into v_old from erp.payments where id = v_replace for update;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'Payment to replace not found');
    end if;

    if v_old.voided_at is null and v_old.posting_status = 'posted' then
      v_del := erp.void_payment(v_replace, 'Replaced via cashbook edit');
      if not coalesce((v_del->>'ok')::boolean, false) then
        return v_del;
      end if;
      v_freed_no := v_old.payment_no || '-V-' || substr(replace(v_replace::text, '-', ''), 1, 8);
      update erp.payments
         set payment_no = v_freed_no
       where id = v_replace;
    elsif v_old.voided_at is not null then
      v_freed_no := v_old.payment_no || '-V-' || substr(replace(v_replace::text, '-', ''), 1, 8);
      if v_old.payment_no = coalesce(p_payload->>'payment_no', v_old.payment_no) then
        update erp.payments set payment_no = v_freed_no where id = v_replace;
      end if;
    else
      v_del := erp.hard_delete_payment(v_replace);
      if not coalesce((v_del->>'ok')::boolean, false) then
        return v_del;
      end if;
    end if;
  end if;

  v_entry_kind := nullif(p_payload->>'entry_kind', '');

  if v_entry_kind = 'party_settlement' then
    v_payment_type := 'adjustment';
  else
    v_payment_type := coalesce(nullif(p_payload->>'payment_type', ''), 'receipt');
  end if;

  if nullif(p_payload->>'party_code', '') is not null then
    select id into v_party_id from erp.parties where code = p_payload->>'party_code';
  elsif nullif(p_payload->>'party_id', '') is not null then
    v_party_id := (p_payload->>'party_id')::uuid;
  end if;

  if nullif(p_payload->>'counter_party_code', '') is not null then
    select id into v_counter_party_id from erp.parties where code = p_payload->>'counter_party_code';
  elsif nullif(p_payload->>'counter_party_id', '') is not null then
    v_counter_party_id := (p_payload->>'counter_party_id')::uuid;
  end if;

  if v_entry_kind = 'party_settlement' then
    if v_party_id is null then
      return jsonb_build_object('ok', false, 'error', 'Paying party not found');
    end if;
    if v_counter_party_id is null then
      return jsonb_build_object('ok', false, 'error', 'Receiving party not found');
    end if;
    if v_party_id = v_counter_party_id then
      return jsonb_build_object('ok', false, 'error', 'Paying and receiving party must be different');
    end if;
  end if;

  if v_entry_kind is null then
    if v_party_id is not null then
      v_entry_kind := case when v_payment_type = 'receipt' then 'party_receipt' else 'party_payment' end;
    elsif nullif(p_payload->>'counter_account_code', '') is not null then
      v_entry_kind := case when v_payment_type = 'receipt' then 'gl_receipt' else 'gl_payment' end;
    else
      v_entry_kind := case when v_payment_type = 'receipt' then 'party_receipt' else 'party_payment' end;
    end if;
  end if;

  insert into erp.payments (
    payment_no, payment_type, payment_mode, payment_date,
    party_id, counter_party_id, amount, voucher_subtype,
    bank_account_code, counter_account_code, entry_kind,
    page_no, reference_no, remarks,
    is_advance, advance_amount, advance_consumed
  ) values (
    p_payload->>'payment_no',
    v_payment_type,
    coalesce(nullif(p_payload->>'payment_mode', ''), case when v_entry_kind = 'party_settlement' then 'adjustment' else 'cash' end),
    coalesce((p_payload->>'payment_date')::date, current_date),
    v_party_id,
    v_counter_party_id,
    coalesce((p_payload->>'amount')::numeric, 0),
    coalesce(nullif(p_payload->>'voucher_subtype', ''), case when v_entry_kind = 'party_settlement' then 'CROSS_SETTLE' when v_payment_type = 'receipt' then 'CRV' else 'CPV' end),
    nullif(p_payload->>'bank_account_code', ''),
    nullif(p_payload->>'counter_account_code', ''),
    v_entry_kind,
    nullif(p_payload->>'page_no', ''),
    nullif(p_payload->>'reference_no', ''),
    nullif(p_payload->>'remarks', ''),
    false, 0, 0
  )
  returning id into v_payment_id;

  perform erp.post_payment(v_payment_id);

  if p_payload ? 'parchi_clearances'
     and jsonb_array_length(coalesce(p_payload->'parchi_clearances', '[]'::jsonb)) > 0 then
    v_clr := erp.batch_apply_parchi_clearances(
      v_payment_id,
      coalesce((p_payload->>'payment_date')::date, current_date),
      p_payload->'parchi_clearances'
    );
    if not coalesce((v_clr->>'ok')::boolean, false) then
      return v_clr;
    end if;
  else
    v_clr := jsonb_build_object('ok', true, 'parchi_rows', '[]'::jsonb);
  end if;

  return jsonb_build_object('ok', true, 'payment_id', v_payment_id, 'parchi', v_clr);
end;
$$;


ALTER FUNCTION "erp"."save_and_post_payment"("p_payload" "jsonb") OWNER TO "postgres";

--
-- Name: save_drawing_weekly_wage_sheet("jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."save_drawing_weekly_wage_sheet"("p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_sheet_id uuid;
  v_sheet erp.drawing_weekly_wage_sheets%rowtype;
  v_received numeric;
  v_scrap numeric;
  v_line jsonb;
  v_line_no int := 0;
  v_gauge int;
  v_weight numeric;
  v_rate numeric;
  v_totals record;
begin
  perform erp._drawing_wage_post_access();

  v_sheet_id := (p_payload->>'sheet_id')::uuid;
  if v_sheet_id is null then
    raise exception 'sheet_id is required';
  end if;

  select * into v_sheet from erp.drawing_weekly_wage_sheets where id = v_sheet_id for update;
  if not found then raise exception 'Wage sheet not found'; end if;
  if v_sheet.status = 'posted' then raise exception 'Posted sheets cannot be edited'; end if;

  update erp.drawing_weekly_wage_sheets s
  set
    wire8_received_override = case
      when p_payload ? 'wire8_received_override' then (p_payload->>'wire8_received_override')::numeric
      else s.wire8_received_override
    end,
    wire8_scrap_override = case
      when p_payload ? 'wire8_scrap_override' then (p_payload->>'wire8_scrap_override')::numeric
      else s.wire8_scrap_override
    end,
    notes = coalesce(p_payload->>'notes', s.notes),
    updated_at = now()
  where s.id = v_sheet_id;

  delete from erp.drawing_weekly_wage_premium_lines where sheet_id = v_sheet_id;

  for v_line in select * from jsonb_array_elements(coalesce(p_payload->'premium_lines', '[]'::jsonb))
  loop
    v_line_no := v_line_no + 1;
    v_gauge := (v_line->>'gauge_swg')::int;
    v_weight := coalesce((v_line->>'weight_kg')::numeric, 0);
    if v_gauge is null or v_gauge < 33 then
      raise exception 'Premium lines require gauge SWG >= 33';
    end if;
    select r.effective_rate_pkr into v_rate
    from erp.get_drawing_labor_rate(v_gauge, v_sheet.week_start) r;
    insert into erp.drawing_weekly_wage_premium_lines (
      sheet_id, line_no, gauge_swg, weight_kg, rate_pkr_per_kg, amount_pkr
    ) values (
      v_sheet_id, v_line_no, v_gauge, v_weight, v_rate, round(v_weight * v_rate, 2)
    );
  end loop;

  select * into v_sheet from erp.drawing_weekly_wage_sheets where id = v_sheet_id;
  v_received := coalesce(v_sheet.wire8_received_override, v_sheet.wire8_received_kg);
  v_scrap := coalesce(v_sheet.wire8_scrap_override, v_sheet.wire8_scrap_kg);

  select * into v_totals
  from erp._compute_drawing_sheet_totals(v_received, v_scrap, v_sheet.base_rate_pkr, v_sheet_id);

  update erp.drawing_weekly_wage_sheets s
  set
    net_wire8_kg = v_totals.net_kg,
    base_wage_pkr = v_totals.base_wage,
    premium_wage_pkr = v_totals.premium_wage,
    total_wage_pkr = v_totals.total_wage,
    updated_at = now()
  where s.id = v_sheet_id;

  return v_sheet_id;
end;
$$;


ALTER FUNCTION "erp"."save_drawing_weekly_wage_sheet"("p_payload" "jsonb") OWNER TO "postgres";

--
-- Name: sync_party_opening_scrap_receivables("uuid", "jsonb"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."sync_party_opening_scrap_receivables"("p_party_id" "uuid", "p_lines" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_party erp.parties%rowtype;
  v_line jsonb;
  v_obl_id uuid;
  v_obl_no text;
  v_exp numeric;
  v_rate numeric;
  v_rec numeric;
  v_label text;
  v_as_of date;
  v_seq int := 0;
  v_keep_ids uuid[] := '{}';
  v_existing_id uuid;
  v_total_kg numeric := 0;
begin
  select * into v_party from erp.parties where id = p_party_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'party not found');
  end if;

  if v_party.party_type = 'vendor' then
    perform erp._reverse_party_opening_scrap(p_party_id);
    update erp.parties
    set opening_scrap_kg = 0,
        opening_scrap_ref_rate = 0
    where id = p_party_id;
    return jsonb_build_object('ok', true, 'party_code', v_party.code, 'line_count', 0);
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'lines must be a JSON array');
  end if;

  for v_line in select value from jsonb_array_elements(p_lines)
  loop
    v_exp := coalesce((v_line->>'expected_kg')::numeric, 0);
    v_rate := coalesce((v_line->>'ref_rate')::numeric, 0);
    if v_exp <= 0 and v_rate <= 0 then
      continue;
    end if;
    if v_exp <= 0 or v_rate <= 0 then
      return jsonb_build_object(
        'ok', false,
        'error', 'Each opening scrap line requires both expected kg and ref scrap rate'
      );
    end if;

    v_obl_id := nullif(trim(coalesce(v_line->>'obligation_id', '')), '')::uuid;
    if v_obl_id is not null then
      v_keep_ids := array_append(v_keep_ids, v_obl_id);
    end if;
  end loop;

  for v_existing_id in
    select o.id
    from erp.scrap_receivable_obligations o
    where o.party_id = p_party_id
      and o.obligation_source = 'opening'
      and (cardinality(v_keep_ids) = 0 or not (o.id = any (v_keep_ids)))
  loop
    perform erp._delete_opening_scrap_obligation(v_existing_id);
  end loop;

  for v_line in select value from jsonb_array_elements(p_lines)
  loop
    v_exp := coalesce((v_line->>'expected_kg')::numeric, 0);
    v_rate := coalesce((v_line->>'ref_rate')::numeric, 0);
    if v_exp <= 0 and v_rate <= 0 then
      continue;
    end if;

    v_label := nullif(trim(coalesce(v_line->>'label', '')), '');
    v_as_of := coalesce(nullif(trim(coalesce(v_line->>'as_of_date', '')), '')::date, current_date);
    v_obl_id := nullif(trim(coalesce(v_line->>'obligation_id', '')), '')::uuid;

    if v_obl_id is not null then
      select received_kg into v_rec
      from erp.scrap_receivable_obligations
      where id = v_obl_id
        and party_id = p_party_id
        and obligation_source = 'opening'
      for update;

      if not found then
        return jsonb_build_object('ok', false, 'error', 'Opening scrap line not found for this party');
      end if;

      if v_exp + 0.001 < coalesce(v_rec, 0) then
        return jsonb_build_object(
          'ok', false,
          'error', format('Opening scrap cannot be below already received (%s kg)', v_rec)
        );
      end if;

      update erp.scrap_receivable_obligations
      set
        ref_scrap_rate = v_rate,
        expected_kg = v_exp,
        invoice_date = v_as_of,
        sales_invoice_no = coalesce(v_label, sales_invoice_no)
      where id = v_obl_id;

      perform erp._sync_scrap_obligation_status(v_obl_id);
      v_total_kg := v_total_kg + v_exp;
      continue;
    end if;

    v_seq := coalesce((
      select max(
        nullif(regexp_replace(o.obligation_no, '^SRO-OPEN-' || v_party.code || '-', ''), '')::int
      )
      from erp.scrap_receivable_obligations o
      where o.party_id = p_party_id
        and o.obligation_source = 'opening'
        and o.obligation_no like 'SRO-OPEN-' || v_party.code || '-%'
    ), 0);
    v_seq := v_seq + 1;
    v_obl_no := 'SRO-OPEN-' || v_party.code || '-' || lpad(v_seq::text, 3, '0');

    insert into erp.scrap_receivable_obligations (
      obligation_no,
      party_id,
      sales_invoice_id,
      sales_invoice_no,
      invoice_date,
      ref_scrap_rate,
      expected_kg,
      received_kg,
      status,
      obligation_source,
      remarks
    ) values (
      v_obl_no,
      p_party_id,
      null,
      coalesce(v_label, 'Opening Balance #' || v_seq::text),
      v_as_of,
      v_rate,
      v_exp,
      0,
      'open',
      'opening',
      'Opening premium scrap receivable from party master'
    );

    v_total_kg := v_total_kg + v_exp;
  end loop;

  update erp.parties
  set opening_scrap_kg = v_total_kg,
      opening_scrap_ref_rate = case when v_total_kg > 0 then coalesce(
        (
          select o.ref_scrap_rate
          from erp.scrap_receivable_obligations o
          where o.party_id = p_party_id
            and o.obligation_source = 'opening'
          order by o.invoice_date desc, o.created_at desc
          limit 1
        ),
        0
      ) else 0 end
  where id = p_party_id;

  return jsonb_build_object(
    'ok', true,
    'party_code', v_party.code,
    'line_count', (
      select count(*)::int
      from erp.scrap_receivable_obligations o
      where o.party_id = p_party_id
        and o.obligation_source = 'opening'
    ),
    'total_expected_kg', v_total_kg
  );
exception
  when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm, 'code', sqlstate);
end;
$$;


ALTER FUNCTION "erp"."sync_party_opening_scrap_receivables"("p_party_id" "uuid", "p_lines" "jsonb") OWNER TO "postgres";

--
-- Name: sync_posted_purchase_invoice_dates("uuid", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."sync_posted_purchase_invoice_dates"("p_invoice_id" "uuid", "p_invoice_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_invoices%rowtype;
  v_ap int := 0;
  v_je int := 0;
  v_im int := 0;
  v_pri int := 0;
begin
  if not erp.can_mutate_transactions() then
    raise exception 'not authorized to sync posted purchase invoice dates';
  end if;

  select * into v_doc from erp.purchase_invoices where id = p_invoice_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'purchase invoice not found');
  end if;
  if v_doc.posting_status <> 'posted' then
    return jsonb_build_object('ok', true, 'skipped', true, 'reason', 'not posted');
  end if;

  update erp.ap_documents
  set doc_date = p_invoice_date, due_date = p_invoice_date
  where source_doc_type = 'purchase_invoice' and source_doc_id = p_invoice_id;
  get diagnostics v_ap = row_count;

  update erp.journal_entries
  set posting_date = p_invoice_date
  where source_doc_type = 'purchase_invoice' and source_doc_id = p_invoice_id;
  get diagnostics v_je = row_count;

  update erp.inventory_movements
  set posting_date = p_invoice_date
  where source_doc_type = 'purchase_invoice' and source_doc_id = p_invoice_id;
  get diagnostics v_im = row_count;

  update erp.pending_rate_items
  set original_posting_date = p_invoice_date
  where source_doc_type = 'purchase_invoice' and source_doc_id = p_invoice_id;
  get diagnostics v_pri = row_count;

  return jsonb_build_object(
    'ok', true,
    'ap_documents', v_ap,
    'journal_entries', v_je,
    'inventory_movements', v_im,
    'pending_rate_items', v_pri
  );
end;
$$;


ALTER FUNCTION "erp"."sync_posted_purchase_invoice_dates"("p_invoice_id" "uuid", "p_invoice_date" "date") OWNER TO "postgres";

--
-- Name: sync_posted_sales_invoice_dates("uuid", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
