--
-- Name: trg_block_posted_header_delete(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."trg_block_posted_header_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  -- Canonical delete RPCs set this transaction-locally after they have cleaned
  -- movements/journals/allocations themselves. Everything else stays blocked.
  if coalesce(current_setting('erp.allow_posted_header_delete', true), '') = '1' then
    return OLD;
  end if;

  if TG_TABLE_NAME = 'sales_invoices' and OLD.posting_status = 'posted' then
    raise exception 'Cannot delete posted sales invoice. Use void_sales_invoice.' using errcode = 'P0001';
  elsif TG_TABLE_NAME = 'purchase_invoices' and OLD.posting_status = 'posted' then
    raise exception 'Cannot delete posted purchase invoice. Use void_purchase_invoice.' using errcode = 'P0001';
  elsif TG_TABLE_NAME = 'payments' and OLD.posting_status = 'posted' then
    raise exception 'Cannot delete posted payment. Use void_payment.' using errcode = 'P0001';
  elsif TG_TABLE_NAME = 'scrap_trades' and OLD.status = 'posted' then
    raise exception 'Cannot delete posted scrap trade. Use void_scrap_trade.' using errcode = 'P0001';
  elsif TG_TABLE_NAME = 'production_batches' and OLD.status = 'posted' then
    raise exception 'Cannot delete posted production batch. Use void_production_batch.' using errcode = 'P0001';
  end if;
  return OLD;
end;
$$;


ALTER FUNCTION "erp"."trg_block_posted_header_delete"() OWNER TO "postgres";

--
-- Name: trg_inventory_balance_sync(); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."trg_inventory_balance_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_item_ids uuid[];
begin
  if current_setting('erp.skip_inventory_balance_sync', true) = '1' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    v_item_ids := array[old.item_id];
  elsif tg_op = 'UPDATE' and old.item_id is distinct from new.item_id then
    v_item_ids := array[old.item_id, new.item_id];
  else
    v_item_ids := array[new.item_id];
  end if;

  perform erp.rebuild_inventory_balances_for_items(
    array(select distinct x from unnest(v_item_ids) x where x is not null)
  );
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "erp"."trg_inventory_balance_sync"() OWNER TO "postgres";

--
-- Name: unpost_factory_scrap_dispatch("uuid"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."unpost_factory_scrap_dispatch"("p_doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.factory_scrap_dispatches%rowtype;
begin
  perform erp._assert_posting_access();

  select * into v_doc
  from erp.factory_scrap_dispatches
  where id = p_doc_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'factory scrap dispatch not found');
  end if;

  if v_doc.status <> 'posted' then
    return jsonb_build_object('ok', false, 'error', 'dispatch is not posted');
  end if;

  perform erp._clear_factory_scrap_dispatch_posting(v_doc.id);
  perform erp._clear_factory_scrap_obligation(v_doc.id);

  update erp.factory_scrap_dispatches
  set status = 'draft',
      posted_at = null,
      posted_by = null
  where id = v_doc.id;

  perform erp.fn_evaluate_production_alerts(v_doc.dispatch_date);

  return jsonb_build_object('ok', true, 'dispatch_id', v_doc.id, 'dispatch_no', v_doc.dispatch_no);
exception
  when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm);
end;
$$;


ALTER FUNCTION "erp"."unpost_factory_scrap_dispatch"("p_doc_id" "uuid") OWNER TO "postgres";

--
-- Name: update_production_receipt_line("uuid", "date", numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."update_production_receipt_line"("p_line_id" "uuid", "p_batch_date" "date" DEFAULT NULL::"date", "p_unit_count" numeric DEFAULT NULL::numeric, "p_gross_weight" numeric DEFAULT NULL::numeric, "p_tare_weight" numeric DEFAULT NULL::numeric, "p_net_weight" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_line erp.production_batch_lines%rowtype;
  v_batch erp.production_batches%rowtype;
  v_prev_line erp.production_batch_lines%rowtype;
  v_item_ids uuid[];
  v_net numeric;
  v_was_posted boolean;
begin
  perform erp._assert_posting_access();

  select pbl.* into v_line
  from erp.production_batch_lines pbl
  where pbl.id = p_line_id;

  if not found then
    raise exception 'production line not found';
  end if;
  if v_line.line_type <> 'receipt' then
    raise exception 'only receipt lines can be edited';
  end if;

  select * into v_batch from erp.production_batches where id = v_line.production_batch_id for update;
  if not found then
    raise exception 'production batch not found';
  end if;

  v_net := coalesce(p_net_weight, v_line.net_weight);
  if v_net <= 0 then
    raise exception 'net weight must be greater than zero';
  end if;

  v_was_posted := v_batch.status = 'posted';

  if v_was_posted then
    delete from erp.inventory_movements
    where source_doc_type = 'production_batch'
      and source_doc_id = v_batch.id;

    update erp.production_batches
    set status = 'draft', posted_at = null, posted_by = null
    where id = v_batch.id;
  end if;

  if p_batch_date is not null then
    update erp.production_batches set batch_date = p_batch_date where id = v_batch.id;
  end if;

  update erp.production_batch_lines
  set
    unit_count = coalesce(p_unit_count, unit_count),
    gross_weight = coalesce(p_gross_weight, gross_weight),
    tare_weight = coalesce(p_tare_weight, tare_weight),
    net_weight = v_net
  where id = p_line_id;

  select * into v_prev_line
  from erp.production_batch_lines
  where production_batch_id = v_batch.id
    and line_no = v_line.line_no - 1;

  if found and v_prev_line.line_type = 'issue' then
    update erp.production_batch_lines
    set net_weight = v_net
    where id = v_prev_line.id;
  end if;

  perform erp.post_production_batch(v_batch.id);

  select coalesce(array_agg(distinct item_id), '{}')
  into v_item_ids
  from (
    select item_id
    from erp.production_batch_lines
    where production_batch_id = v_batch.id
    union
    select item_id
    from erp.inventory_movements
    where source_doc_type = 'production_batch'
      and source_doc_id = v_batch.id
  ) affected;

  if coalesce(array_length(v_item_ids, 1), 0) > 0 then
    perform erp.rebuild_inventory_balances_for_items(v_item_ids);
  end if;

  return jsonb_build_object('ok', true, 'batch_id', v_batch.id, 'line_id', p_line_id);
end;
$$;


ALTER FUNCTION "erp"."update_production_receipt_line"("p_line_id" "uuid", "p_batch_date" "date", "p_unit_count" numeric, "p_gross_weight" numeric, "p_tare_weight" numeric, "p_net_weight" numeric) OWNER TO "postgres";

--
-- Name: update_supplies_restock("uuid", numeric, numeric, "date", "text", "text", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."update_supplies_restock"("p_movement_id" "uuid", "p_qty" numeric, "p_unit_cost" numeric DEFAULT 0, "p_posting_date" "date" DEFAULT NULL::"date", "p_remarks" "text" DEFAULT NULL::"text", "p_item_code" "text" DEFAULT NULL::"text", "p_unit_count" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_mov erp.inventory_movements%rowtype;
  v_item erp.items%rowtype;
  v_new_item erp.items%rowtype;
  v_wh_id uuid;
  v_wh_type text;
  v_old_item_id uuid;
  v_value numeric;
  v_rebuild_ids uuid[];
  v_units_in numeric := 0;
  v_posting_date date;
begin
  perform erp._assert_posting_access();

  if p_movement_id is null then
    return jsonb_build_object('ok', false, 'error', 'Movement id is required');
  end if;
  if coalesce(p_qty, 0) <= 0 then
    return jsonb_build_object('ok', false, 'error', 'Quantity must be greater than zero');
  end if;

  select * into v_mov
  from erp.inventory_movements
  where id = p_movement_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'Restock movement not found');
  end if;

  if v_mov.source_doc_type <> 'supplies_restock' or v_mov.movement_type <> 'adjustment_in' then
    return jsonb_build_object('ok', false, 'error', 'Only supplies restock receipts can be edited');
  end if;

  v_old_item_id := v_mov.item_id;

  select * into v_item from erp.items where id = v_mov.item_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Item not found for movement');
  end if;

  v_new_item := v_item;
  v_wh_id := v_mov.warehouse_id;

  if p_item_code is not null and trim(p_item_code) <> '' and trim(p_item_code) <> v_item.code then
    select * into v_new_item
    from erp.items
    where code = trim(p_item_code) and coalesce(is_active, true)
    limit 1;

    if not found then
      return jsonb_build_object('ok', false, 'error', format('Item not found: %s', p_item_code));
    end if;

    if v_new_item.inventory_group not in ('chemicals', 'packing_material') then
      return jsonb_build_object('ok', false, 'error', 'Restock item must be chemicals or packing material');
    end if;

    if v_new_item.inventory_group <> v_item.inventory_group then
      return jsonb_build_object('ok', false, 'error', 'Cannot change between varnish and packing on the same restock');
    end if;

    v_wh_type := case
      when v_new_item.inventory_group = 'chemicals' then 'varnish'
      else 'packing_material'
    end;

    select id into v_wh_id
    from erp.warehouses
    where wh_type = v_wh_type and coalesce(is_active, true)
    order by code
    limit 1;

    if v_wh_id is null then
      return jsonb_build_object('ok', false, 'error', format('Warehouse not found for type %s', v_wh_type));
    end if;
  end if;

  if erp._is_varnish_item(v_new_item.id) then
    v_units_in := coalesce(nullif(p_unit_count, 0), erp._varnish_units_from_kg(v_new_item.id, p_qty));
  end if;

  v_value := round(p_qty * coalesce(p_unit_cost, 0), 3);
  v_posting_date := coalesce(p_posting_date, v_mov.posting_date);

  update erp.inventory_movements
  set
    item_id = v_new_item.id,
    warehouse_id = v_wh_id,
    posting_date = v_posting_date,
    qty_in = p_qty,
    qty_out = 0,
    units_in = v_units_in,
    units_out = 0,
    unit_cost = coalesce(p_unit_cost, 0),
    value_amount = v_value,
    reference_no = nullif(trim(coalesce(p_remarks, '')), '')
  where id = p_movement_id;

  if v_new_item.inventory_group = 'chemicals' and v_value > 0 then
    perform erp._sync_supplies_restock_gl(
      v_mov.source_doc_id,
      v_posting_date,
      v_value,
      coalesce(nullif(trim(p_remarks), ''), 'Varnish supplies restock')
    );
  end if;

  if v_old_item_id = v_new_item.id then
    v_rebuild_ids := array[v_new_item.id];
  else
    v_rebuild_ids := array[v_old_item_id, v_new_item.id];
  end if;

  perform erp.rebuild_inventory_balances_for_items(v_rebuild_ids);

  return jsonb_build_object(
    'ok', true,
    'movement_id', p_movement_id,
    'item_code', v_new_item.code,
    'qty', p_qty,
    'unit_count', v_units_in
  );
end;
$$;


ALTER FUNCTION "erp"."update_supplies_restock"("p_movement_id" "uuid", "p_qty" numeric, "p_unit_cost" numeric, "p_posting_date" "date", "p_remarks" "text", "p_item_code" "text", "p_unit_count" numeric) OWNER TO "postgres";

--
-- Name: upsert_drawing_labor_settings(numeric, "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."upsert_drawing_labor_settings"("p_base_rate_pkr" numeric, "p_effective_from" "date" DEFAULT CURRENT_DATE) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  perform erp._drawing_wage_post_access();
  if coalesce(p_base_rate_pkr, 0) <= 0 then
    raise exception 'Base rate must be positive';
  end if;

  update erp.drawing_labor_settings set is_active = false where is_active = true;

  insert into erp.drawing_labor_settings (base_rate_pkr, effective_from, is_active, updated_by)
  values (p_base_rate_pkr, coalesce(p_effective_from, current_date), true, auth.uid())
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "erp"."upsert_drawing_labor_settings"("p_base_rate_pkr" numeric, "p_effective_from" "date") OWNER TO "postgres";

--
-- Name: upsert_drawing_premium_rate(integer, numeric, numeric, "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."upsert_drawing_premium_rate"("p_gauge_swg" integer, "p_increment_pkr" numeric, "p_rate_pkr_override" numeric DEFAULT NULL::numeric, "p_effective_from" "date" DEFAULT CURRENT_DATE) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  perform erp._drawing_wage_post_access();
  if p_gauge_swg < 33 then
    raise exception 'Premium gauge must be SWG 33 or higher';
  end if;

  insert into erp.drawing_labor_premium_rates (
    gauge_swg, increment_pkr, rate_pkr_override, effective_from, is_active
  ) values (
    p_gauge_swg,
    coalesce(p_increment_pkr, 0),
    p_rate_pkr_override,
    coalesce(p_effective_from, current_date),
    true
  )
  on conflict (gauge_swg, effective_from) do update
    set increment_pkr = excluded.increment_pkr,
        rate_pkr_override = excluded.rate_pkr_override,
        is_active = true,
        updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "erp"."upsert_drawing_premium_rate"("p_gauge_swg" integer, "p_increment_pkr" numeric, "p_rate_pkr_override" numeric, "p_effective_from" "date") OWNER TO "postgres";

--
-- Name: upsert_opening_stock("uuid", "uuid", numeric, numeric, "date", numeric); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."upsert_opening_stock"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_unit_cost" numeric DEFAULT 0, "p_as_of" "date" DEFAULT CURRENT_DATE, "p_unit_count" numeric DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_je_id uuid;
  v_inv text;
  v_eq text;
  v_value numeric;
  v_doc_id uuid := gen_random_uuid();
  v_as_of date := coalesce(p_as_of, current_date);
  v_units numeric := greatest(coalesce(p_unit_count, 0), 0);
  v_qty numeric := greatest(coalesce(p_qty, 0), 0);
  v_voucher text;
begin
  perform erp._assert_posting_access();
  perform set_config('erp.skip_period_lock_check', '1', true);
  perform set_config('erp.skip_cogs_restamp', '1', true);

  if not exists (select 1 from erp.items where id = p_item_id) then
    raise exception 'Item not found for opening stock';
  end if;
  if not exists (select 1 from erp.warehouses where id = p_warehouse_id) then
    raise exception 'Warehouse not found for opening stock';
  end if;

  delete from erp.journal_entries je
  where je.source_doc_type = 'opening_stock'
    and je.source_doc_id in (
      select im.source_doc_id
      from erp.inventory_movements im
      where im.item_id = p_item_id
        and im.warehouse_id = p_warehouse_id
        and im.movement_type = 'opening'
        and im.source_doc_type = 'opening_stock'
        and im.source_doc_id is not null
    );

  v_voucher := 'OPEN-' || left(p_item_id::text, 8);
  delete from erp.journal_entries je
  where je.source_doc_type = 'opening_stock'
    and je.voucher_type = 'OPENING_STOCK'
    and je.voucher_no = v_voucher
    and not exists (
      select 1
      from erp.inventory_movements im
      where im.source_doc_type = 'opening_stock'
        and im.source_doc_id = je.source_doc_id
    );

  delete from erp.inventory_movements im
  where im.item_id = p_item_id
    and im.warehouse_id = p_warehouse_id
    and im.movement_type = 'opening'
    and im.source_doc_type = 'opening_stock';

  if v_qty <= 0 then
    perform erp.rebuild_inventory_balances_for_items(array[p_item_id]);
    return;
  end if;

  v_inv := erp._inventory_gl_account_for_item(p_item_id);
  v_eq := erp._resolve_posting_account('opening_stock', 'opening_equity');
  v_value := round(v_qty * coalesce(p_unit_cost, 0), 3);

  insert into erp.inventory_movements (
    posting_date, movement_type, item_id, warehouse_id,
    qty_in, units_in, unit_cost, value_amount,
    source_doc_type, source_doc_id, party_id
  ) values (
    v_as_of, 'opening', p_item_id, p_warehouse_id,
    v_qty, v_units, coalesce(p_unit_cost, 0), v_value,
    'opening_stock', v_doc_id, null
  );

  if v_value > 0 then
    insert into erp.journal_entries (
      voucher_no, voucher_type, posting_date, source_doc_type, source_doc_id, source_doc_no,
      narration, status, posted_at, posted_by
    ) values (
      v_voucher, 'OPENING_STOCK', v_as_of, 'opening_stock', v_doc_id,
      v_voucher,
      'Opening stock', 'posted', now(), auth.uid()
    ) returning id into v_je_id;
    perform erp._insert_je_line(v_je_id, 1, v_inv, null, v_value, 0, 'Opening inventory');
    perform erp._insert_je_line(v_je_id, 2, v_eq, null, 0, v_value, 'Opening equity');
  end if;

  perform erp.rebuild_inventory_balances_for_items(array[p_item_id]);
end;
$$;


ALTER FUNCTION "erp"."upsert_opening_stock"("p_item_id" "uuid", "p_warehouse_id" "uuid", "p_qty" numeric, "p_unit_cost" numeric, "p_as_of" "date", "p_unit_count" numeric) OWNER TO "postgres";

--
-- Name: upsert_production_machine("uuid", "text", "text", "text", "text", boolean, integer); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."upsert_production_machine"("p_id" "uuid", "p_machine_code" "text", "p_name" "text", "p_department" "text", "p_scrap_item_code" "text", "p_is_active" boolean DEFAULT true, "p_sort_order" integer DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_scrap_id uuid;
  v_id uuid;
begin
  perform erp._assert_posting_access();
  if p_scrap_item_code is not null and btrim(p_scrap_item_code) <> '' then
    select id into v_scrap_id from erp.items where code = p_scrap_item_code limit 1;
  end if;
  if p_id is null then
    insert into erp.production_machines (machine_code, name, department, scrap_item_id, is_active, sort_order)
    values (p_machine_code, p_name, p_department, v_scrap_id, coalesce(p_is_active, true), coalesce(p_sort_order, 0))
    returning id into v_id;
  else
    update erp.production_machines
    set machine_code = p_machine_code,
        name = p_name,
        department = p_department,
        scrap_item_id = v_scrap_id,
        is_active = coalesce(p_is_active, true),
        sort_order = coalesce(p_sort_order, 0)
    where id = p_id
    returning id into v_id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "erp"."upsert_production_machine"("p_id" "uuid", "p_machine_code" "text", "p_name" "text", "p_department" "text", "p_scrap_item_code" "text", "p_is_active" boolean, "p_sort_order" integer) OWNER TO "postgres";

--
-- Name: upsert_production_standard("text", numeric, "text", "date"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."upsert_production_standard"("p_key" "text", "p_numeric" numeric DEFAULT NULL::numeric, "p_text" "text" DEFAULT NULL::"text", "p_effective_from" "date" DEFAULT CURRENT_DATE) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
begin
  perform erp._assert_posting_access();
  insert into erp.production_standards (standard_key, numeric_value, text_value, effective_from, updated_by)
  values (p_key, p_numeric, p_text, coalesce(p_effective_from, current_date), auth.uid())
  on conflict (standard_key, effective_from) do update set
    numeric_value = coalesce(excluded.numeric_value, erp.production_standards.numeric_value),
    text_value = coalesce(excluded.text_value, erp.production_standards.text_value),
    updated_by = auth.uid(),
    updated_at = now();
end;
$$;


ALTER FUNCTION "erp"."upsert_production_standard"("p_key" "text", "p_numeric" numeric, "p_text" "text", "p_effective_from" "date") OWNER TO "postgres";

--
-- Name: void_parchi_instrument("uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."void_parchi_instrument"("p_parchi_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_p erp.parchi_instruments%rowtype;
  v_reversed int;
begin
  perform erp._assert_posting_access();

  select * into v_p from erp.parchi_instruments where id = p_parchi_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Parchi not found');
  end if;

  if v_p.status = 'void' then
    v_reversed := erp._reverse_parchi_issue_gl_for(p_parchi_id, coalesce(p_reason, 'Void parchi (cleanup)'));
    return jsonb_build_object('ok', true, 'id', p_parchi_id, 'already_voided', true, 'gl_reversed', v_reversed);
  end if;

  if coalesce(v_p.cleared_amount, 0) > 0.01 then
    return jsonb_build_object(
      'ok', false,
      'error', 'Cannot void a parchi with clearance entries. Reverse cashbook clearance first.'
    );
  end if;

  if exists (select 1 from erp.parchi_clearances where parchi_id = p_parchi_id) then
    return jsonb_build_object(
      'ok', false,
      'error', 'Cannot void a parchi with clearance rows. Reverse cashbook clearance first.'
    );
  end if;

  v_reversed := erp._reverse_parchi_issue_gl_for(p_parchi_id, p_reason);

  update erp.parchi_instruments
  set status = 'void',
      open_amount = 0
  where id = p_parchi_id;

  return jsonb_build_object('ok', true, 'id', p_parchi_id, 'gl_reversed', v_reversed);
end;
$$;


ALTER FUNCTION "erp"."void_parchi_instrument"("p_parchi_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: void_payment("uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."void_payment"("p_doc_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.payments%rowtype;
  v_alloc record;
  v_clr record;
  v_ar erp.ar_documents%rowtype;
  v_ap erp.ap_documents%rowtype;
  v_parchi erp.parchi_instruments%rowtype;
  v_je record;
  v_open numeric;
  v_seq int := 0;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.payments where id = p_doc_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Payment not found');
  end if;
  if v_doc.voided_at is not null then
    return jsonb_build_object('ok', true, 'id', v_doc.id, 'already_voided', true);
  end if;
  if v_doc.posting_status <> 'posted' then
    raise exception 'only posted payments can be voided' using errcode = 'P0001';
  end if;

  for v_clr in select * from erp.parchi_clearances where payment_id = v_doc.id loop
    select * into v_parchi from erp.parchi_instruments where id = v_clr.parchi_id for update;
    if found then
      v_open := greatest(
        0,
        coalesce(v_parchi.total_amount, 0)
          - greatest(0, coalesce(v_parchi.cleared_amount, 0) - coalesce(v_clr.amount, 0))
      );
      update erp.parchi_instruments
      set
        cleared_amount = greatest(0, coalesce(v_parchi.cleared_amount, 0) - coalesce(v_clr.amount, 0)),
        open_amount = v_open,
        status = case
          when v_open <= 0.01 then 'cleared'
          when coalesce(v_parchi.cleared_amount, 0) - coalesce(v_clr.amount, 0) > 0 then 'partial'
          else 'open'
        end
      where id = v_parchi.id;
    end if;
  end loop;

  for v_alloc in select * from erp.payment_allocations where payment_id = v_doc.id loop
    if v_alloc.ar_document_id is not null then
      select * into v_ar from erp.ar_documents where id = v_alloc.ar_document_id for update;
      if found then
        v_open := least(
          coalesce(v_ar.amount, 0),
          coalesce(v_ar.open_amount, 0) + coalesce(v_alloc.allocated_amount, 0)
        );
        update erp.ar_documents
        set open_amount = v_open,
            status = case
              when v_open <= 0.01 then 'settled'
              when v_open >= coalesce(v_ar.amount, 0) - 0.01 then 'open'
              else 'partially_settled'
            end
        where id = v_ar.id;
      end if;
    end if;
    if v_alloc.ap_document_id is not null then
      select * into v_ap from erp.ap_documents where id = v_alloc.ap_document_id for update;
      if found then
        v_open := least(
          coalesce(v_ap.amount, 0),
          coalesce(v_ap.open_amount, 0) + coalesce(v_alloc.allocated_amount, 0)
        );
        update erp.ap_documents
        set open_amount = v_open,
            status = case
              when v_open <= 0.01 then 'settled'
              when v_open >= coalesce(v_ap.amount, 0) - 0.01 then 'open'
              else 'partially_settled'
            end
        where id = v_ap.id;
      end if;
    end if;
  end loop;

  for v_je in
    select id
    from erp.journal_entries
    where source_doc_type = 'payment'
      and source_doc_id = v_doc.id
      and coalesce(voucher_no, '') not like 'VOID-%'
    order by posted_at nulls last, id
  loop
    v_seq := v_seq + 1;
    perform erp._post_reversing_journal_entry(
      v_je.id,
      'VOID-' || v_doc.payment_no || case when v_seq > 1 then '-' || v_seq::text else '' end,
      'payment_void',
      v_doc.id,
      v_doc.payment_no,
      v_doc.payment_date,
      coalesce(p_reason, 'Void payment')
    );
  end loop;

  update erp.journal_entries
  set voucher_no = 'VOID-' || voucher_no
  where source_doc_type = 'payment'
    and source_doc_id = v_doc.id
    and coalesce(voucher_no, '') not like 'VOID-%';

  update erp.payments
  set voided_at = now(),
      voided_by = auth.uid(),
      void_reason = p_reason
  where id = v_doc.id;

  return jsonb_build_object('ok', true, 'id', v_doc.id, 'action', 'voided');
end;
$$;


ALTER FUNCTION "erp"."void_payment"("p_doc_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: void_production_batch("uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."void_production_batch"("p_batch_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_batch erp.production_batches%rowtype;
  v_mov erp.inventory_movements%rowtype;
  v_item_ids uuid[];
  v_je record;
begin
  perform erp._assert_posting_access();
  select * into v_batch from erp.production_batches where id = p_batch_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'production batch not found');
  end if;
  if v_batch.voided_at is not null or v_batch.status = 'voided' then
    return jsonb_build_object('ok', true, 'batch_id', p_batch_id, 'already_voided', true);
  end if;
  if v_batch.status <> 'posted' then
    raise exception 'only posted production batches can be voided' using errcode = 'P0001';
  end if;

  select coalesce(array_agg(distinct item_id), '{}')
  into v_item_ids
  from erp.inventory_movements
  where source_doc_type = 'production_batch' and source_doc_id = p_batch_id;

  for v_mov in
    select * from erp.inventory_movements
    where source_doc_type = 'production_batch' and source_doc_id = p_batch_id
  loop
    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id,
      qty_in, qty_out, units_in, units_out, unit_cost, value_amount,
      source_doc_type, source_doc_id, reference_no
    ) values (
      coalesce(v_batch.batch_date, current_date),
      coalesce(v_mov.movement_type, 'adjustment') || '_void',
      v_mov.item_id,
      v_mov.warehouse_id,
      coalesce(v_mov.qty_out, 0),
      coalesce(v_mov.qty_in, 0),
      coalesce(v_mov.units_out, 0),
      coalesce(v_mov.units_in, 0),
      v_mov.unit_cost,
      -coalesce(v_mov.value_amount, 0),
      'production_batch_void',
      p_batch_id,
      'VOID-' || v_batch.batch_no
    );
  end loop;

  for v_je in
    select je.id
    from erp.journal_entries je
    where je.source_doc_type = 'production_batch'
      and je.source_doc_id = p_batch_id
      and coalesce(je.voucher_no, '') not like 'VOID-%'
  loop
    perform erp._post_reversing_journal_entry(
      v_je.id,
      'VOID-' || v_batch.batch_no,
      'production_batch_void',
      p_batch_id,
      v_batch.batch_no,
      coalesce(v_batch.batch_date, current_date),
      coalesce(p_reason, 'Void production batch GL reversal')
    );
  end loop;

  update erp.production_batches
  set status = 'voided',
      voided_at = now(),
      voided_by = auth.uid(),
      void_reason = p_reason
  where id = p_batch_id;

  if coalesce(array_length(v_item_ids, 1), 0) > 0 then
    perform erp.rebuild_inventory_balances_for_items(v_item_ids);
  else
    perform erp.rebuild_inventory_balances();
  end if;

  return jsonb_build_object('ok', true, 'batch_id', p_batch_id);
end;
$$;


ALTER FUNCTION "erp"."void_production_batch"("p_batch_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: void_purchase_invoice("uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."void_purchase_invoice"("doc_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.purchase_invoices%rowtype;
  v_return_id uuid;
  v_return_no text;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.purchase_invoices where id = doc_id for update;
  if not found then raise exception 'purchase invoice not found'; end if;
  if v_doc.voided_at is not null then return v_doc.void_purchase_return_id; end if;
  if v_doc.posting_status <> 'posted' then raise exception 'only posted purchase invoices can be voided'; end if;

  perform erp._void_rename_active_journals('purchase_invoice', v_doc.id, p_reason);
  v_return_no := 'VOID-' || v_doc.invoice_no;
  insert into erp.purchase_returns (
    return_no, return_date, party_id, ref_invoice_id, return_action,
    subtotal_amount, tax_amount, grand_total, remarks
  ) values (
    v_return_no, current_date, v_doc.party_id, v_doc.id, 'stock',
    v_doc.subtotal_amount, v_doc.tax_amount, v_doc.grand_total,
    coalesce(p_reason, 'Voided purchase invoice')
  ) returning id into v_return_id;
  insert into erp.purchase_return_lines (
    purchase_return_id, line_no, item_id, warehouse_id, qty, unit_count,
    uom_code, unit_price, tax_rate, line_amount, rate_status
  )
  select
    v_return_id, l.line_no, l.item_id, l.warehouse_id,
    coalesce(nullif(l.net_weight, 0), l.qty), coalesce(l.unit_count, 0),
    l.uom_code, l.unit_price, l.tax_rate, l.line_amount, 'fixed'
  from erp.purchase_invoice_lines l
  where l.purchase_invoice_id = v_doc.id;
  perform erp.post_purchase_return(v_return_id);
  update erp.purchase_invoices
  set voided_at = now(), voided_by = auth.uid(), void_reason = p_reason,
      void_purchase_return_id = v_return_id
  where id = v_doc.id;
  return v_return_id;
end;
$$;


ALTER FUNCTION "erp"."void_purchase_invoice"("doc_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: void_sales_invoice("uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."void_sales_invoice"("doc_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.sales_invoices%rowtype;
  v_return_id uuid;
  v_return_no text;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.sales_invoices where id = doc_id for update;
  if not found then raise exception 'sales invoice not found'; end if;
  if v_doc.voided_at is not null then return v_doc.void_sales_return_id; end if;
  if v_doc.posting_status <> 'posted' then raise exception 'only posted sales invoices can be voided'; end if;

  perform erp._void_rename_active_journals('sales_invoice', v_doc.id, p_reason);
  v_return_no := 'VOID-' || v_doc.invoice_no;
  insert into erp.sales_returns (
    return_no, return_date, party_id, ref_invoice_id, return_action,
    subtotal_amount, tax_amount, grand_total, remarks
  ) values (
    v_return_no, current_date, v_doc.party_id, v_doc.id, 'restock',
    v_doc.subtotal_amount, v_doc.tax_amount, v_doc.grand_total,
    coalesce(p_reason, 'Voided sales invoice')
  ) returning id into v_return_id;
  insert into erp.sales_return_lines (
    sales_return_id, line_no, item_id, warehouse_id, qty, unit_count,
    uom_code, unit_price, tax_rate, line_amount, rate_status
  )
  select
    v_return_id, l.line_no, l.item_id, l.warehouse_id,
    coalesce(nullif(l.net_weight, 0), l.qty), coalesce(l.unit_count, 0),
    l.uom_code, l.unit_price, l.tax_rate, l.line_amount, 'fixed'
  from erp.sales_invoice_lines l
  where l.sales_invoice_id = v_doc.id;
  perform erp.post_sales_return(v_return_id);
  update erp.sales_invoices
  set voided_at = now(), voided_by = auth.uid(), void_reason = p_reason,
      void_sales_return_id = v_return_id
  where id = v_doc.id;
  return v_return_id;
end;
$$;


ALTER FUNCTION "erp"."void_sales_invoice"("doc_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: void_scrap_trade("uuid", "text"); Type: FUNCTION; Schema: erp; Owner: postgres
--

CREATE FUNCTION "erp"."void_scrap_trade"("p_doc_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'erp', 'pg_temp'
    AS $$
declare
  v_doc erp.scrap_trades%rowtype;
  v_je record;
  v_mov erp.inventory_movements%rowtype;
  v_seq int := 0;
begin
  perform erp._assert_posting_access();
  select * into v_doc from erp.scrap_trades where id = p_doc_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'Scrap trade not found');
  end if;
  if v_doc.voided_at is not null or v_doc.status = 'voided' then
    return jsonb_build_object('ok', true, 'id', v_doc.id, 'already_voided', true);
  end if;
  if v_doc.status <> 'posted' then
    raise exception 'only posted scrap trades can be voided' using errcode = 'P0001';
  end if;
  for v_je in
    select id from erp.journal_entries
    where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id
      and coalesce(voucher_no, '') not like 'VOID-%'
    order by posted_at nulls last, id
  loop
    v_seq := v_seq + 1;
    perform erp._post_reversing_journal_entry(
      v_je.id,
      'VOID-' || v_doc.trade_no || case when v_seq > 1 then '-' || v_seq::text else '' end,
      'scrap_trade_void',
      v_doc.id,
      v_doc.trade_no,
      coalesce(v_doc.trade_date, current_date),
      coalesce(p_reason, 'Void scrap trade')
    );
  end loop;
  for v_mov in
    select * from erp.inventory_movements
    where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id
  loop
    insert into erp.inventory_movements (
      posting_date, movement_type, item_id, warehouse_id,
      qty_in, qty_out, unit_cost, value_amount,
      source_doc_type, source_doc_id, party_id, reference_no
    ) values (
      coalesce(v_doc.trade_date, current_date),
      coalesce(v_mov.movement_type, 'adjustment') || '_void',
      v_mov.item_id,
      v_mov.warehouse_id,
      coalesce(v_mov.qty_out, 0),
      coalesce(v_mov.qty_in, 0),
      v_mov.unit_cost,
      -coalesce(v_mov.value_amount, 0),
      'scrap_trade_void',
      v_doc.id,
      v_mov.party_id,
      'VOID-' || v_doc.trade_no
    );
  end loop;
  update erp.ar_documents set open_amount = 0, status = 'settled' where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id;
  update erp.ap_documents set open_amount = 0, status = 'settled' where source_doc_type = 'scrap_trade' and source_doc_id = v_doc.id;
  update erp.scrap_trades set status = 'voided', voided_at = now(), voided_by = auth.uid(), void_reason = p_reason where id = v_doc.id;
  perform erp.rebuild_inventory_balances();
  return jsonb_build_object('ok', true, 'id', v_doc.id, 'action', 'voided');
end;
$$;


ALTER FUNCTION "erp"."void_scrap_trade"("p_doc_id" "uuid", "p_reason" "text") OWNER TO "postgres";

