--
-- Name: v_open_party_advances; Type: VIEW; Schema: erp; Owner: postgres
--

CREATE VIEW "erp"."v_open_party_advances" WITH ("security_invoker"='true') AS
 SELECT "p"."id" AS "payment_id",
    "p"."payment_no",
    "p"."payment_type",
    "p"."entry_kind",
    "p"."payment_date",
    "p"."party_id",
    "pt"."code" AS "party_code",
    "pt"."name" AS "party_name",
        CASE
            WHEN ("p"."entry_kind" = 'party_receipt'::"text") THEN 'customer'::"text"
            WHEN ("p"."entry_kind" = 'party_payment'::"text") THEN 'vendor'::"text"
            ELSE NULL::"text"
        END AS "advance_side",
    "p"."amount",
    COALESCE("p"."advance_amount", (0)::numeric) AS "advance_amount",
    COALESCE("p"."advance_consumed", (0)::numeric) AS "advance_consumed",
    COALESCE("a"."allocated", (0)::numeric) AS "allocated",
    "round"((COALESCE("p"."advance_amount", (0)::numeric) - COALESCE("p"."advance_consumed", (0)::numeric)), 2) AS "open_advance",
    "p"."remarks"
   FROM (("erp"."payments" "p"
     LEFT JOIN "erp"."parties" "pt" ON (("pt"."id" = "p"."party_id")))
     LEFT JOIN ( SELECT "payment_allocations"."payment_id",
            "sum"("payment_allocations"."allocated_amount") AS "allocated"
           FROM "erp"."payment_allocations"
          GROUP BY "payment_allocations"."payment_id") "a" ON (("a"."payment_id" = "p"."id")))
  WHERE (("p"."posting_status" = 'posted'::"text") AND ("p"."voided_at" IS NULL) AND ("p"."entry_kind" = ANY (ARRAY['party_receipt'::"text", 'party_payment'::"text"])) AND ("round"((COALESCE("p"."advance_amount", (0)::numeric) - COALESCE("p"."advance_consumed", (0)::numeric)), 2) > 0.01));


ALTER VIEW "erp"."v_open_party_advances" OWNER TO "postgres";

--
-- Name: VIEW "v_open_party_advances"; Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON VIEW "erp"."v_open_party_advances" IS 'Open party advance balances (security_invoker=true).';


--
-- Name: v_party_metal_ledger; Type: VIEW; Schema: erp; Owner: postgres
--

CREATE VIEW "erp"."v_party_metal_ledger" WITH ("security_invoker"='true') AS
 SELECT "p"."code" AS "party_code",
    "p"."name" AS "party_name",
    "im"."posting_date",
    "im"."movement_type",
    "im"."source_doc_type",
    "im"."source_doc_id",
    COALESCE("im"."reference_no", "si"."invoice_no", "pi"."invoice_no", "sr"."return_no", "pr"."return_no", "st"."trade_no", "scr"."receipt_no") AS "reference_no",
    "i"."name" AS "item_name",
    NULLIF(TRIM(BOTH FROM COALESCE("i"."size_spec", ''::"text")), ''::"text") AS "size_spec",
    COALESCE("im"."qty_in", (0)::numeric) AS "weight_in",
    COALESCE("im"."qty_out", (0)::numeric) AS "weight_out"
   FROM (((((((("erp"."inventory_movements" "im"
     JOIN "erp"."parties" "p" ON (("p"."id" = "im"."party_id")))
     JOIN "erp"."items" "i" ON (("i"."id" = "im"."item_id")))
     LEFT JOIN "erp"."sales_invoices" "si" ON ((("im"."source_doc_type" = 'sales_invoice'::"text") AND ("si"."id" = "im"."source_doc_id"))))
     LEFT JOIN "erp"."purchase_invoices" "pi" ON ((("im"."source_doc_type" = 'purchase_invoice'::"text") AND ("pi"."id" = "im"."source_doc_id"))))
     LEFT JOIN "erp"."sales_returns" "sr" ON ((("im"."source_doc_type" = 'sales_return'::"text") AND ("sr"."id" = "im"."source_doc_id"))))
     LEFT JOIN "erp"."purchase_returns" "pr" ON ((("im"."source_doc_type" = 'purchase_return'::"text") AND ("pr"."id" = "im"."source_doc_id"))))
     LEFT JOIN "erp"."scrap_trades" "st" ON ((("im"."source_doc_type" = 'scrap_trade'::"text") AND ("st"."id" = "im"."source_doc_id"))))
     LEFT JOIN "erp"."scrap_receipts" "scr" ON ((("im"."source_doc_type" = 'scrap_receipt'::"text") AND ("scr"."id" = "im"."source_doc_id"))))
  WHERE (("im"."party_id" IS NOT NULL) AND ("im"."movement_type" = ANY (ARRAY['purchase_in'::"text", 'purchase_return_out'::"text", 'sales_out'::"text", 'sales_return_in'::"text", 'scrap_out'::"text", 'scrap_in'::"text", 'opening'::"text"])));


ALTER VIEW "erp"."v_party_metal_ledger" OWNER TO "postgres";

--
-- Name: v_unallocated_payments; Type: VIEW; Schema: erp; Owner: postgres
--

CREATE VIEW "erp"."v_unallocated_payments" WITH ("security_invoker"='true') AS
 SELECT "p"."id" AS "payment_id",
    "p"."payment_no",
    "p"."payment_type",
    "p"."payment_date",
    "p"."party_id",
    "pt"."name" AS "party_name",
    "p"."amount",
    COALESCE("a"."allocated", (0)::numeric) AS "allocated",
    "round"(GREATEST((0)::numeric, (("p"."amount" - COALESCE("a"."allocated", (0)::numeric)) - (COALESCE("p"."advance_amount", (0)::numeric) - COALESCE("p"."advance_consumed", (0)::numeric)))), 2) AS "unallocated",
    COALESCE("ar"."open_ar", (0)::numeric) AS "party_open_ar",
    COALESCE("ap"."open_ap", (0)::numeric) AS "party_open_ap"
   FROM (((("erp"."payments" "p"
     LEFT JOIN ( SELECT "payment_allocations"."payment_id",
            "sum"("payment_allocations"."allocated_amount") AS "allocated"
           FROM "erp"."payment_allocations"
          GROUP BY "payment_allocations"."payment_id") "a" ON (("a"."payment_id" = "p"."id")))
     LEFT JOIN "erp"."parties" "pt" ON (("pt"."id" = "p"."party_id")))
     LEFT JOIN ( SELECT "ar_documents"."party_id",
            "sum"("ar_documents"."open_amount") AS "open_ar"
           FROM "erp"."ar_documents"
          WHERE ("ar_documents"."status" = ANY (ARRAY['open'::"text", 'partially_settled'::"text"]))
          GROUP BY "ar_documents"."party_id") "ar" ON (("ar"."party_id" = "p"."party_id")))
     LEFT JOIN ( SELECT "ap_documents"."party_id",
            "sum"("ap_documents"."open_amount") AS "open_ap"
           FROM "erp"."ap_documents"
          WHERE ("ap_documents"."status" = ANY (ARRAY['open'::"text", 'partially_settled'::"text"]))
          GROUP BY "ap_documents"."party_id") "ap" ON (("ap"."party_id" = "p"."party_id")))
  WHERE (("p"."posting_status" = 'posted'::"text") AND ("p"."voided_at" IS NULL) AND ("p"."entry_kind" = ANY (ARRAY['party_receipt'::"text", 'party_payment'::"text"])) AND ("round"(GREATEST((0)::numeric, (("p"."amount" - COALESCE("a"."allocated", (0)::numeric)) - (COALESCE("p"."advance_amount", (0)::numeric) - COALESCE("p"."advance_consumed", (0)::numeric)))), 2) > 0.01))
  ORDER BY "p"."payment_type", "p"."payment_date", "p"."payment_no";


ALTER VIEW "erp"."v_unallocated_payments" OWNER TO "postgres";

--
-- Name: VIEW "v_unallocated_payments"; Type: COMMENT; Schema: erp; Owner: postgres
--

COMMENT ON VIEW "erp"."v_unallocated_payments" IS 'Unallocated payment receipts (security_invoker=true).';


--
-- Name: v_zero_weight_posted_lines; Type: VIEW; Schema: erp; Owner: postgres
--

CREATE VIEW "erp"."v_zero_weight_posted_lines" WITH ("security_invoker"='true') AS
 SELECT "l"."sales_invoice_id",
    "i"."invoice_no",
    "i"."invoice_date",
    "l"."line_no",
    "l"."item_id",
    "l"."qty",
    "l"."net_weight",
    "l"."line_amount"
   FROM ("erp"."sales_invoice_lines" "l"
     JOIN "erp"."sales_invoices" "i" ON (("i"."id" = "l"."sales_invoice_id")))
  WHERE (("i"."posting_status" = 'posted'::"text") AND ("l"."item_id" IS NOT NULL) AND (COALESCE(NULLIF("l"."net_weight", (0)::numeric), "l"."qty", (0)::numeric) <= (0)::numeric));


ALTER VIEW "erp"."v_zero_weight_posted_lines" OWNER TO "postgres";

