    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "party_id" "uuid",
    "direction" "text" NOT NULL,
    "product_kind" "text" NOT NULL,
    "wire8_grade" "text",
    "swg_min" integer,
    "swg_max" integer,
    "base_watta" numeric(18,3) DEFAULT 0 NOT NULL,
    "increment_per_swg" numeric(18,3) DEFAULT 0 NOT NULL,
    "effective_from" "date" DEFAULT CURRENT_DATE NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "remarks" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "watta_matrix_direction_check" CHECK (("direction" = ANY (ARRAY['sales'::"text", 'purchase'::"text"]))),
    CONSTRAINT "watta_matrix_product_kind_check" CHECK (("product_kind" = ANY (ARRAY['enamel'::"text", 'wire8'::"text", 'rod'::"text"]))),
    CONSTRAINT "watta_matrix_wire8_grade_check" CHECK ((("wire8_grade" IS NULL) OR ("wire8_grade" = ANY (ARRAY['Fail'::"text", 'Pass'::"text", 'Special'::"text"]))))
);


ALTER TABLE "erp"."watta_matrix" OWNER TO "postgres";

